private void positionSlots() {
        for (var entry : style.getSlots().entrySet()) {
            var semantic = SlotSemantics.getOrThrow(entry.getKey());

            // Do not position slots that are hidden
            if (hiddenSlots.contains(semantic)) {
                continue;
            }

            repositionSlots(semantic);
        }
    }

private void refreshList() {
        this.byGroup.clear();

        final String searchFilterLowerCase = this.searchField.getValue().toLowerCase();

        final Set<Object> cachedSearch = this.getCacheForSearchTerm(searchFilterLowerCase);
        final boolean rebuild = cachedSearch.isEmpty();

        for (PatternContainerRecord entry : this.byId.values()) {
            // ignore inventory if not doing a full rebuild or cache already marks it as miss.
            if (!rebuild && !cachedSearch.contains(entry)) {
                continue;
            }

            // Shortcut to skip any filter if search term is ""/empty
            boolean found = searchFilterLowerCase.isEmpty();

            // Search if the current inventory holds a pattern containing the search term.
            if (!found) {
                for (ItemStack itemStack : entry.getInventory()) {
                    found = this.itemStackMatchesSearchTerm(itemStack, searchFilterLowerCase);
                    if (found) {
                        break;
                    }
                }
            }

            // if found, filter skipped or machine name matching the search term, add it
            if (found || entry.getSearchName().contains(searchFilterLowerCase)) {
                this.byGroup.put(entry.getGroup(), entry);
                cachedSearch.add(entry);
            } else {
                cachedSearch.remove(entry);
            }
        }

        this.groups.clear();
        this.groups.addAll(this.byGroup.keySet());

        this.groups.sort(GROUP_COMPARATOR);

        this.rows.clear();
        this.rows.ensureCapacity(this.getMaxRows());

        for (var group : this.groups) {
            this.rows.add(new GroupHeaderRow(group));

            var containers = new ArrayList<>(this.byGroup.get(group));
            Collections.sort(containers);
            for (var container : containers) {
                // Wrap the container inventory slots
                var inventory = container.getInventory();
                for (var offset = 0; offset < inventory.size(); offset += COLUMNS) {
                    var slots = Math.min(inventory.size() - offset, COLUMNS);
                    var containerRow = new SlotsRow(container, offset, slots);
                    this.rows.add(containerRow);
                }
            }
        }

        // lines may have changed - recalculate scroll bar.
        this.resetScrollbar();
    }

private boolean itemStackMatchesSearchTerm(ItemStack itemStack, String searchTerm) {
        if (itemStack.isEmpty()) {
            return false;
        }

        // Potential later use to filter by input
        return patternSearchText.computeIfAbsent(itemStack, this::getPatternSearchText).contains(searchTerm);
    }

@Override
    public <V> List<IRecipeType<?>> getRecipeTypes(IFocus<V> focus) {
        var stackFocus = focus.getTypedValue()
                .getIngredient(VanillaTypes.ITEM_STACK)
                .orElse(null);

        if (focus.getRole() == RecipeIngredientRole.OUTPUT && stackFocus != null) {
            // Looking up how a certain facade is crafted
            if (stackFocus.getItem() instanceof FacadeItem) {
                return Collections.singletonList(RecipeTypes.CRAFTING);
            }
        } else if (focus.getRole() == RecipeIngredientRole.INPUT && stackFocus != null) {
            // Looking up if a certain block can be used to make a facade

            if (!this.itemFacade.createFacadeForItem(stackFocus, true).isEmpty()) {
                return Collections.singletonList(RecipeTypes.CRAFTING);
            }
        }

        return Collections.emptyList();
    }

@SuppressWarnings("unchecked")
    @Override
    public <T, V> List<T> getRecipes(IRecipeType<T> recipeType, IFocus<V> focus) {
        if (!RecipeTypes.CRAFTING.equals(recipeType)) {
            return Collections.emptyList();
        }

        var focusStack = focus.getTypedValue()
                .getIngredient(VanillaTypes.ITEM_STACK)
                .orElse(null);

        if (focus.getRole() == RecipeIngredientRole.OUTPUT && focusStack != null) {
            // Looking up how a certain facade is crafted
            if (focusStack.getItem() instanceof FacadeItem facadeItem) {
                ItemStack textureItem = facadeItem.getTextureItem(focusStack);
                return Collections.singletonList((T) make(textureItem, focusStack));
            }
        } else if (focus.getRole() == RecipeIngredientRole.INPUT && focusStack != null) {
            // Looking up if a certain block can be used to make a facade

            ItemStack facade = this.itemFacade.createFacadeForItem(focusStack, false);

            if (!facade.isEmpty()) {
                return Collections.singletonList((T) make(focusStack, facade));
            }
        }

        return Collections.emptyList();
    }

@Nullable
    private static <T> ItemStack wrapDraggedItem(IIngredientType<T> type, T ingredient) {
        return VanillaTypes.ITEM_STACK.castIngredient(ingredient)
                .or(() -> {
                    var genericStack = GenericEntryStackHelper.ingredientToStack(type, ingredient);
                    if (genericStack != null) {
                        return Optional.of(GenericStack.wrapInItemStack(genericStack));
                    } else {
                        return Optional.empty();
                    }
                })
                .orElse(null);
    }

private List<IRecipeSlotView> findCraftableSlots(T menu, IRecipeSlotsView slotsView) {
        var repo = menu.getClientRepo();
        if (repo == null) {
            return List.of();
        }

        var craftableKeys = repo.getAllEntries().stream()
                .filter(GridInventoryEntry::isCraftable)
                .map(GridInventoryEntry::getWhat)
                .collect(Collectors.toSet());

        return slotsView.getSlotViews(RecipeIngredientRole.INPUT).stream()
                .filter(slotView -> slotView.getAllIngredients().anyMatch(ingredient -> {
                    var stack = GenericEntryStackHelper.ingredientToStack(ingredient);
                    return stack != null && craftableKeys.contains(stack.what());
                }))
                .toList();
    }

@Override
    public void update(ItemStackRenderState renderState,
            ItemStack stack,
            ItemModelResolver itemModelResolver,
            ItemDisplayContext displayContext,
            @Nullable ClientLevel level,
            @Nullable ItemOwner owner,
            int seed) {

        if (!(stack.getItem() instanceof MemoryCardItem item)) {
            return;
        }

        renderState.appendModelIdentityElement(this);

        var baseLayer = renderState.newLayer();
        var tint = baseLayer.tintLayers();
        tint.add(-1);
        tint.add(ARGB.opaque(item.getColor(stack)));
        baseModel.applyToLayer(baseLayer, displayContext);
        renderState.appendModelIdentityElement(tint.getInt(1));

        var colors = stack.getOrDefault(AEComponents.MEMORY_CARD_COLORS, MemoryCardColors.DEFAULT);
        var colorLayer = renderState.newLayer();
        colorLayer.setLocalTransform(transform);
        colorLayer.setExtents(baseModel.extents());
        baseModel.renderProperties().applyToLayer(colorLayer, displayContext);
        colorLayer.setQuads(hashModelCache.getUnchecked(colors));
        renderState.appendModelIdentityElement(colors);
    }

