private void readBuffer(FriendlyByteBuf in) {
        if (in.readableBytes() == 0) {
            this.dots = null;
            return;
        }

        final byte howMany = in.readByte();

        if (howMany == 0) {
            this.dots = null;
            return;
        }

        this.dots = new ArrayList<>(howMany);
        for (int x = 0; x < howMany; x++) {
            this.dots.add(new Splotch(in));
        }
    }

