public static ClientState readFromNbt(ValueInput tag) {
            var powered = tag.getBooleanOr("powered", false);
            var online = tag.getBooleanOr("online", false);
            AxisPosition axisPosition = DEFAULT.axisPosition;
            var axisPositionName = tag.getStringOr("axisPosition", null);
            if (axisPositionName != null) {
                try {
                    axisPosition = Enum.valueOf(AxisPosition.class, axisPositionName);
                } catch (IllegalArgumentException ignored) {
                    axisPosition = DEFAULT.axisPosition;
                }
            }
            var axisName = tag.getStringOr("axis", null);
            Direction.Axis axis = DEFAULT.axis;
            if (axisName != null) {
                try {
                    axis = Enum.valueOf(Direction.Axis.class, axisName);
                } catch (IllegalArgumentException ignored) {
                    axis = DEFAULT.axis;
                }
            }
            return new ClientState(
                    powered,
                    online,
                    axisPosition,
                    axis);
        }

@Override
    protected boolean readFromStream(RegistryFriendlyByteBuf data) {
        var changed = super.readFromStream(data);

        var packedState = data.readInt();
        for (int i = 0; i < getCellCount(); i++) {
            var cellStateOrdinal = (packedState >> (i * 3)) & 0b111;
            var cellState = CellState.values()[cellStateOrdinal];
            if (clientSideCellState[i] != cellState) {
                clientSideCellState[i] = cellState;
                changed = true;
            }
        }

        var online = (packedState & (1 << 31)) != 0;
        if (clientSideOnline != online) {
            clientSideOnline = online;
            changed = true;
        }

        for (int i = 0; i < getCellCount(); i++) {
            var itemId = data.readVarInt();
            Item item = itemId == 0 ? null : BuiltInRegistries.ITEM.byId(itemId);
            if (itemId != 0 && item == Items.AIR) {
                AELog.warn("Received unknown item id from server for disk drive %s: %d", this, itemId);
            }
            if (clientSideCellItems[i] != item) {
                clientSideCellItems[i] = item;
                changed = true;
            }
        }

        return changed;
    }

@Override
    protected void loadVisualState(ValueInput data) {
        super.loadVisualState(data);

        clientSideOnline = data.getBooleanOr("online", false);

        for (int i = 0; i < getCellCount(); i++) {
            this.clientSideCellItems[i] = null;
            this.clientSideCellState[i] = CellState.ABSENT;

            var tagName = "cell" + i;
            var cellData = data.child(tagName).orElse(null);
            if (cellData != null) {
                var id = Identifier.parse(cellData.getStringOr("id", ""));
                var cellStateName = cellData.getStringOr("state", "");

                clientSideCellItems[i] = BuiltInRegistries.ITEM.getOptional(id).orElse(null);
                try {
                    clientSideCellState[i] = CellState.valueOf(cellStateName.toUpperCase(Locale.ROOT));
                } catch (IllegalArgumentException e) {
                    AELog.warn("Cannot parse cell state for cell %d: %s", i, cellStateName);
                }
            }
        }
    }

