@Override
    public SelectedPart selectPartLocal(Vec3 pos) {
        for (var side : Platform.DIRECTIONS_WITH_NULL) {
            var p = this.getPart(side);
            if (p != null) {
                var boxes = new ArrayList<AABB>();

                var bch = new BusCollisionHelper(boxes, side, true);
                p.getBoxes(bch);
                for (AABB bb : boxes) {
                    bb = bb.inflate(0.002, 0.002, 0.002);
                    if (bb.contains(pos)) {
                        return new SelectedPart(p, side);
                    }
                }
            }
        }

        if (PartHelper.getCableRenderMode().opaqueFacades) {
            var fc = this.getFacadeContainer();
            for (var side : Direction.values()) {
                var p = fc.getFacade(side);
                if (p != null) {
                    var boxes = new ArrayList<AABB>();

                    var bch = new BusCollisionHelper(boxes, side, true);
                    p.getBoxes(bch, true);
                    for (AABB bb : boxes) {
                        bb = bb.inflate(0.01, 0.01, 0.01);
                        if (bb.contains(pos)) {
                            return new SelectedPart(p, side);
                        }
                    }
                }
            }
        }

        return new SelectedPart();
    }

private boolean loadPart(Direction side, ValueInput input) {
        var itemId = input.read("id", Identifier.CODEC).orElse(null);
        if (itemId == null) {
            return false;
        }
        var partItem = IPartItem.byId(itemId);
        if (partItem == null) {
            AELog.warn("Ignoring persisted part with non-part-item %s", itemId);
            return false;
        }

        var p = this.getPart(side);
        if (p != null && p.getPartItem() == partItem) {
            p.readFromNBT(input);
        } else {
            p = this.replacePart(partItem, side, null, null);
            if (p != null) {
                p.readFromNBT(input);
            } else {
                AELog.warn("Invalid NBT For CableBus Container: " + itemId
                        + " is not a valid part; it was ignored.");
            }
        }
        return true;
    }

@Nullable
    private static Direction tryReplaceCableSegment(Level level, ItemStack partStack, BlockPos pos,
            Vec3 clickLocation) {
        // Check if there exists a host with a cable in its center
        var host = PartHelper.getPartHost(level, pos);
        if (host == null) {
            return null;
        }
        var cable = host.getPart(null);
        if (!(cable instanceof CablePart cablePart)) {
            return null;
        }

        // Find hit side
        Direction hitSide = null;

        var localClickLocation = clickLocation.subtract(pos.getX(), pos.getY(), pos.getZ());
        sideLoop: for (var side : Direction.values()) {
            List<AABB> boxes = new ArrayList<>();
            var bch = new BusCollisionHelper(boxes, null, true);
            cablePart.getBoxes(bch, boxSide -> boxSide == side);

            for (var box : boxes) {
                if (box.inflate(0.02).contains(localClickLocation)) {
                    hitSide = side;
                    break sideLoop;
                }
            }
        }

        if (host.canAddPart(partStack, hitSide)) {
            return hitSide;
        } else {
            return null;
        }
    }

