public static ItemStack encodeSmithingPattern(ServerLevel level, ItemLike template, ItemLike base,
            ItemLike addition,
            boolean allowSubstitutes) {

        var input = new SmithingRecipeInput(new ItemStack(template), new ItemStack(base), new ItemStack(addition));

        var foundRecipe = level.recipeAccess().getRecipeFor(RecipeType.SMITHING, input, level).orElse(null);
        if (foundRecipe == null) {
            throw new RuntimeException(
                    "No stonecutter recipe found for template=" + template + " and base=" + base + " and addition="
                            + addition);
        }

        var result = foundRecipe.value().assemble(input);

        return PatternDetailsHelper.encodeSmithingTablePattern(
                foundRecipe,
                AEItemKey.of(template),
                AEItemKey.of(base),
                AEItemKey.of(addition),
                AEItemKey.of(result),
                allowSubstitutes);
    }

@TestPlot("crafting_terminal_fill_grid_moves_misplaced_items")
    public static void fillGridMovesMisplacedItems(PlotBuilder plot) {
        var origin = BlockPos.ZERO;
        plot.creativeEnergyCell(origin.below());
        plot.storageDrive(origin);
        plot.cable(origin.above()).part(Direction.NORTH, AEParts.CRAFTING_TERMINAL);

        plot.test(helper -> {
            helper.startSequence()
                    .thenExecute(() -> helper.getGrid(origin)) // Wait for grid init
                    .thenWaitUntil(() -> helper.check(
                            helper.getPart(origin.above(), Direction.NORTH, CraftingTerminalPart.class).isActive(),
                            "crafting terminal is not active"))
                    .thenExecute(() -> {
                        var part = helper.getPart(origin.above(), Direction.NORTH, CraftingTerminalPart.class);
                        var craftingGrid = part.getSubInventory(CraftingTerminalPart.INV_CRAFTING);

                        // Jungle stairs are shaped:
                        // # _ _
                        // # # _
                        // # # #
                        var recipeSlots = Set.of(0, 3, 4, 6, 7, 8);

                        // Fill the grid accordingly, but put the plank for slot 8 into slot 2 instead
                        for (var slot : Set.of(0, 3, 4, 6, 7, 2)) {
                            craftingGrid.setItemDirect(slot, new ItemStack(Items.JUNGLE_PLANKS));
                        }

                        // Use a separate fake player, so we don't interfere with the shared one
                        var player = new FakePlayer(helper.getLevel(),
                                new GameProfile(UUID.randomUUID(), "test-crafting-terminal"));
                        try {
                            // NeoForge's FakePlayer ignores openMenu, so we have to set the menu ourselves
                            var menu = new CraftingTermMenu(1, player.getInventory(), part);
                            menu.setLocator(MenuLocators.forPart(part));
                            player.containerMenu = menu;
                            // Opening the menu normally would do this, and it's required to update the link status
                            menu.broadcastChanges();
                            helper.check(menu.getLinkStatus().connected(), "crafting terminal is not connected");

                            // Simulates JEI/REI requesting the crafting grid to be filled for the recipe
                            var templates = NonNullList.withSize(9, ItemStack.EMPTY);
                            for (var slot : recipeSlots) {
                                templates.set(slot, new ItemStack(Items.JUNGLE_PLANKS));
                            }
                            new FillCraftingGridFromRecipePacket(
                                    ResourceKey.create(Registries.RECIPE, Identifier.parse("minecraft:jungle_stairs")),
                                    templates, false).handleOnServer(player);

                            for (var slot = 0; slot < craftingGrid.size(); slot++) {
                                var stack = craftingGrid.getStackInSlot(slot);
                                if (recipeSlots.contains(slot)) {
                                    helper.check(stack.is(Items.JUNGLE_PLANKS) && stack.getCount() == 1,
                                            "expected one jungle plank in slot " + slot + ", but got " + stack);
                                } else {
                                    helper.check(stack.isEmpty(),
                                            "expected slot " + slot + " to be empty, but got " + stack);
                                }
                            }

                            var storage = helper.getGrid(origin).getStorageService().getInventory();
                            helper.assertContainsNot(storage, AEItemKey.of(Items.JUNGLE_PLANKS));
                            helper.check(!player.getInventory().contains(new ItemStack(Items.JUNGLE_PLANKS)),
                                    "jungle plank should not have been moved to the player inventory");
                        } finally {
                            player.closeContainer();
                        }
                    })
                    .thenSucceed();
        });
    }

@TestPlot(value = "maxchannels_adhoctest", gameTest = false)
    public static void maxChannelsAdHocTest(PlotBuilder plot) {
        plot.creativeEnergyCell("0 -1 0");
        plot.block("[-3,3] -2 [-3,3]", AEBlocks.DRIVE);
        plot.cable("[-3,3] 0 [-3,3]", AEParts.SMART_DENSE_CABLE);
        plot.cable("[-3,3] [1,64] [-3,2]")
                .part(Direction.EAST, AEParts.TERMINAL)
                .part(Direction.NORTH, AEParts.TERMINAL)
                .part(Direction.WEST, AEParts.TERMINAL)
                .part(Direction.WEST, AEParts.TERMINAL);
        plot.cable("[-3,3] [1,64] 3")
                .part(Direction.NORTH, AEParts.PATTERN_PROVIDER)
                .part(Direction.SOUTH, AEParts.PATTERN_PROVIDER)
                .part(Direction.EAST, AEParts.PATTERN_PROVIDER)
                .part(Direction.WEST, AEParts.PATTERN_PROVIDER);

        plot.afterGridExistsAt(BlockPos.ZERO, (grid, node) -> {
            // This has so many nodes it needs infinite mode
            ((PathingService) grid.getPathingService()).setForcedChannelMode(ChannelMode.INFINITE);

            var patternProviders = grid.getMachines(PatternProviderPart.class).iterator();
            PatternProviderPart current = patternProviders.next();
            var craftingRecipes = node.getLevel().recipeAccess().recipeMap().byType(RecipeType.CRAFTING);

            Set<AEItemKey> neededIngredients = new HashSet<>();
            Set<AEItemKey> providedResults = new HashSet<>();

            for (var holder : craftingRecipes) {
                var recipe = holder.value();
                if (recipe.isSpecial()) {
                    continue;
                }

                ItemStack craftingPattern;
                try {
                    var resultItem = CraftingRecipeUtil.getResult(recipe);
                    var ingredients = CraftingRecipeUtil.ensure3by3CraftingMatrix(recipe).stream()
                            .map(i -> {
                                if (i.isEmpty()) {
                                    return ItemStack.EMPTY;
                                } else {
                                    return i.get().items().map(Holder::value).map(Item::getDefaultInstance).findFirst()
                                            .orElse(ItemStack.EMPTY);
                                }
                            }).toArray(ItemStack[]::new);

                    craftingPattern = PatternDetailsHelper.encodeCraftingPattern(
                            holder,
                            ingredients,
                            resultItem,
                            false,
                            false);

                    for (var ingredient : ingredients) {
                        var key = AEItemKey.of(ingredient);
                        if (key != null) {
                            neededIngredients.add(key);
                        }
                    }
                    if (!resultItem.isEmpty()) {
                        providedResults.add(AEItemKey.of(resultItem));
                    }
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }

                if (!current.getLogic().getPatternInv().addItems(craftingPattern).isEmpty()) {
                    if (!patternProviders.hasNext()) {
                        break;
                    }
                    current = patternProviders.next();
                    current.getLogic().getPatternInv().addItems(craftingPattern);
                }
            }

            // Add creative cells for anything that's not provided as a recipe result
            var keysToAdd = Sets.difference(neededIngredients, providedResults).iterator();
            drives: for (var drive : grid.getMachines(DriveBlockEntity.class)) {

                var cellInv = drive.getInternalInventory();
                for (int i = 0; i < cellInv.size(); i++) {
                    var creativeCell = AEItems.CREATIVE_CELL.stack();
                    var configInv = AEItems.CREATIVE_CELL.get().getConfigInventory(creativeCell);

                    for (int j = 0; j < configInv.size(); j++) {
                        if (!keysToAdd.hasNext()) {
                            cellInv.addItems(creativeCell);
                            break drives;
                        }

                        var keyToAdd = keysToAdd.next();
                        configInv.setStack(j, new GenericStack(keyToAdd, 1));
                    }
                    cellInv.addItems(creativeCell);

                }
            }
        });
    }

