@Override
    public CompletableFuture<?> run(CachedOutput pCache)
    {
        GameInitializationManager.getInstance().initialize(helper, output);
        IEWireTypes.setup();

        try(ModelRenderer itemRenderer = new ModelRenderer(256, 256, itemOutputDirectory.toFile()))
        {
            Set<String> domainsToRender = Set.of("minecraft", Lib.MODID);
            BuiltInRegistries.ITEM.stream().forEach(item -> {
                ResourceLocation name = BuiltInRegistries.ITEM.getKey(item);
                if(!domainsToRender.contains(name.getNamespace()))
                    return;
                ModelResourceLocation modelLocation = new ModelResourceLocation(name, "inventory");
                ItemStack stackToRender = item.getDefaultInstance();

                final BakedModel model = Minecraft.getInstance().getModelManager().getModel(modelLocation);
                itemRenderer.renderModel(model, name.getNamespace()+"/"+name.getPath()+".png", stackToRender);
            });
        }
        return CompletableFuture.completedFuture(null);
    }

@SubscribeEvent
	public void onItemTooltip(ItemTooltipEvent event)
	{
		if(event.getItemStack().isEmpty())
			return;
		var wrapper = event.getItemStack().getCapability(CapabilityShader.ITEM);
		if(wrapper!=null)
		{
			var shader = wrapper.getShader();
			if(shader!=null)
				event.getToolTip().add(TextUtils.applyFormat(
						ShaderItem.getShaderName(shader),
						ChatFormatting.DARK_GRAY
				));
		}
		if(event.getItemStack().has(IEDataComponents.CONTAINED_EARMUFF))
		{
			ItemStack earmuffs = event.getItemStack().get(IEDataComponents.CONTAINED_EARMUFF).attached();
			if(!earmuffs.isEmpty())
				event.getToolTip().add(TextUtils.applyFormat(
						earmuffs.getHoverName(),
						ChatFormatting.GRAY
				));
		}
		if(event.getItemStack().has(IEDataComponents.CONTAINED_POWERPACK))
		{
			ItemStack powerpack = event.getItemStack().get(IEDataComponents.CONTAINED_POWERPACK).attached();
			IEnergyStorage packStorage = powerpack.getCapability(EnergyStorage.ITEM);
			if(!powerpack.isEmpty()&&packStorage!=null)
			{
				List<Component> tooltip = event.getToolTip();
				// find gap
				int idx = IntStream.range(0, tooltip.size()).filter(i -> tooltip.get(i)==CommonComponents.EMPTY).findFirst().orElse(tooltip.size()-1);
				// put tooltip in that gap
				tooltip.add(idx++, CommonComponents.EMPTY);
				tooltip.add(idx++, TextUtils.applyFormat(powerpack.getHoverName(), ChatFormatting.GRAY));
				tooltip.add(idx++, TextUtils.applyFormat(
						Component.literal(packStorage.getEnergyStored()+"/"+packStorage.getMaxEnergyStored()+" IF"),
						ChatFormatting.GRAY
				));
				tooltip.add(idx, TextUtils.applyFormat(Component.translatable("desc.immersiveengineering.info.noChargeOnArmor"), ChatFormatting.DARK_GRAY));
			}
		}
		Level clientLevel = ClientUtils.mc().level;
		if(ClientUtils.mc().screen!=null
				&&ClientUtils.mc().screen instanceof BlastFurnaceScreen
				&&BlastFurnaceFuel.isValidBlastFuel(clientLevel, event.getItemStack()))
			event.getToolTip().add(TextUtils.applyFormat(
					Component.translatable("desc.immersiveengineering.info.blastFuelTime", BlastFurnaceFuel.getBlastFuelTime(clientLevel, event.getItemStack())),
					ChatFormatting.GRAY
			));

		if(IEClientConfig.tagTooltips.get()&&event.getFlags().isAdvanced())
			event.getItemStack().getItem().builtInRegistryHolder().tags()
					.map(TagKey::location)
					.forEach(oid ->
							event.getToolTip().add(TextUtils.applyFormat(
									Component.literal(oid.toString()),
									ChatFormatting.GRAY
							)));
	}

@SubscribeEvent
	public void onRenderOverlayPre(RenderGuiLayerEvent.Pre event)
	{
		if(event.getName().equals(VanillaGuiLayers.SUBTITLE_OVERLAY))
			ItemOverlayUtils.handleTooltipOffset(event.getGuiGraphics(), true);

		// early exit if not handling zooming
		if(!event.getName().equals(VanillaGuiLayers.CROSSHAIR)||!ZoomHandler.isZooming)
			return;

		// check for a zoom tool and get its step array
		Player player = ClientUtils.mc().player;
		float[] zoomSteps = Arrays.stream(InteractionHand.values())
				.map(player::getItemInHand)
				.mapMulti((BiConsumer<ItemStack, Consumer<float[]>>)(itemStack, consumer) -> {
					if(itemStack.getItem() instanceof IZoomTool zoomTool&&zoomTool.canZoom(itemStack, player))
						consumer.accept(zoomTool.getZoomSteps(itemStack, player));
				}).findFirst().orElse(null);

		if(zoomSteps==null||zoomSteps.length <= 1)
			return;

		// cancel default crosshair
		event.setCanceled(true);

		GuiGraphics graphics = event.getGuiGraphics();
		PoseStack transform = graphics.pose();
		transform.pushPose();
		int width = ClientUtils.mc().getWindow().getGuiScaledWidth();
		int height = ClientUtils.mc().getWindow().getGuiScaledHeight();
		int resMin = Math.min(width, height);
		float offsetX = Math.round((width-resMin)/2f);
		float offsetY = Math.round((height-resMin)/2f);

		if(resMin==width)
		{
			graphics.fill(0, 0, width, (int)offsetY+1, 0xff000000);
			graphics.fill(0, (int)offsetY+resMin, width, (int)(offsetY+resMin+offsetY+1), 0xff000000);
		}
		else
		{
			graphics.fill(0, 0, (int)offsetX+1, height, 0xff000000);
			graphics.fill((int)offsetX+resMin, 0, (int)(offsetX+resMin+offsetX+1), height, 0xff000000);
		}
		transform.translate(offsetX, offsetY, 0);

		RenderSystem.enableBlend();
		graphics.blitSprite(ieLoc("hud/scope"), 0, 0, resMin, resMin);
		RenderSystem.disableBlend();

		// draw gauge on the right side
		transform.translate(218/256f*resMin, 64/256f*resMin, 0);
		graphics.blitSprite(ieLoc("hud/gauge_vertical"), 0, 0, Math.round(24/256f*resMin), Math.round(128/256f*resMin));

		float stepLength = 118/(float)zoomSteps.length;
		float stepOffset = (stepLength-7)/2f;
		// move inside the gauge
		RenderSystem.enableBlend();
		transform.translate(5/256f*resMin, (5+stepOffset)/256f*resMin, 0);

		// draw markers for the possible steps
		int curStep = -1;
		float dist = 0;
		int innerWidth = Math.round(14/256f*resMin);
		int innerHeight = Math.round(7/256f*resMin);

		for(int i = 0; i < zoomSteps.length; i++)
		{
			graphics.blitSprite(ieLoc("hud/gauge_vertical_step"), 0, 0, innerWidth, innerHeight);
			transform.translate(0, stepLength/256*resMin, 0);
			if(curStep==-1||Math.abs(zoomSteps[i]-ZoomHandler.fovZoom) < dist)
			{
				curStep = i;
				dist = Math.abs(zoomSteps[i]-ZoomHandler.fovZoom);
			}
		}
		transform.translate(0, -118/256f*resMin, 0);

		// draw the pointer and text for current level
		transform.translate(0, curStep*stepLength/256*resMin, 0);
		graphics.blitSprite(ieLoc("hud/gauge_vertical_pointer"), 0, 0, innerWidth, innerHeight);
		transform.translate(16/256f*resMin, 1/256f*resMin, 0);
		graphics.drawString(ClientUtils.font(), (1/zoomSteps[curStep])+"x", 0, 0, 0xffffff, false);
		RenderSystem.disableBlend();
		transform.popPose();
	}

@SubscribeEvent
	public void onMouseEvent(MouseScrollingEvent event)
	{
		Player player = ClientUtils.mc().player;
		if(event.getScrollDeltaY()!=0&&ClientUtils.mc().screen==null&&player!=null)
		{
			// Handle zooming in and out
			if(ZoomHandler.isZooming)
			{
				float[] zoomSteps = Arrays.stream(InteractionHand.values())
						.map(player::getItemInHand)
						.mapMulti((BiConsumer<ItemStack, Consumer<float[]>>)(itemStack, consumer) -> {
							if(itemStack.getItem() instanceof IZoomTool zoomTool&&zoomTool.canZoom(itemStack, player))
								consumer.accept(zoomTool.getZoomSteps(itemStack, player));
						}).findFirst().orElse(null);
				if(zoomSteps!=null&&zoomSteps.length > 0)
				{
					int curStep = ZoomHandler.getCurrentZoomStep(zoomSteps);
					int newStep = curStep+(event.getScrollDeltaY() > 0?-1: 1);
					if(newStep >= 0&&newStep < zoomSteps.length)
						ZoomHandler.fovZoom = zoomSteps[newStep];
					event.setCanceled(true);
				}
			}
			else
			{
				ItemStack equipped = player.getItemInHand(InteractionHand.MAIN_HAND);
				// Handle sneak + scrolling
				if(player.isShiftKeyDown())
				{
					if(IEServerConfig.TOOLS.chemthrower_scroll.get()&&equipped.getItem() instanceof IScrollwheel)
					{
						PacketDistributor.sendToServer(new MessageScrollwheelItem(event.getScrollDeltaY() < 0));
						event.setCanceled(true);
					}
					if(equipped.getItem() instanceof RevolverItem)
					{
						PacketDistributor.sendToServer(new MessageRevolverRotate(event.getScrollDeltaY() < 0));
						event.setCanceled(true);
					}
				}
			}
		}
	}

@SubscribeEvent()
	public void onRenderLivingPre(RenderLivingEvent.Pre<LivingEntity, ?> event)
	{
		if(event.getEntity().getPersistentData().contains("headshot"))
			enableHead(event.getRenderer(), false);
		if(event.getEntity() instanceof Player player&&player.isCrouching()&&player.getItemBySlot(EquipmentSlot.CHEST).getItem() instanceof CrateItem crateItem)
			if(CrateItem.incognitoPlayers.contains(player.getId()))
			{
				ClientUtils.mc().getEntityRenderDispatcher().setRenderShadow(false);
				event.setCanceled(true);
				PoseStack pose = event.getPoseStack();
				pose.pushPose();

				var partialTick = event.getPartialTick();
				double posX = Mth.lerp(partialTick, player.xOld, player.getX());
				double posZ = Mth.lerp(partialTick, player.zOld, player.getZ());

				@SuppressWarnings("unchecked")
				Vec3 crouchOffset = event.getRenderer().getRenderOffset(player, partialTick);
				double x = Math.floor(posX)-posX;
				double z = Math.floor(posZ)-posZ;
				pose.translate(x, -crouchOffset.y, z);
				ClientUtils.mc().getBlockRenderer().renderSingleBlock(
						crateItem.getBlock().defaultBlockState(),
						pose,
						event.getMultiBufferSource(),
						event.getPackedLight(),
						OverlayTexture.NO_OVERLAY,
						ModelData.EMPTY,
						RenderType.solid()
				);
				pose.popPose();
			}
			else
				enableUpperBody(event.getRenderer(), false);
	}

@SubscribeEvent()
	public void onRenderLivingPost(RenderLivingEvent.Post<LivingEntity, ?> event)
	{
		if(event.getEntity().getPersistentData().contains("headshot"))
			enableHead(event.getRenderer(), true);
		if(event.getEntity() instanceof Player player&&player.isCrouching()&&player.getItemBySlot(EquipmentSlot.CHEST).getItem() instanceof CrateItem)
		{
			ClientUtils.mc().getEntityRenderDispatcher().setRenderShadow(true);
			enableUpperBody(event.getRenderer(), true);
		}
	}

@SubscribeEvent
	public void onToast(ToastAddEvent event)
	{
		if(event.getToast() instanceof AdvancementToast advToast)
		{
			AdvancementHolder advancement = ((AdvancementToastAccess)advToast).getAdvancement();
			ManualInstance manual = ManualHelper.getManual();
			if(manual.contentsByName.isEmpty()) // we need to load the manual if not already done
				manual.reload();
			List<ManualEntry> entries = manual.contentsByName.values().stream()
					.filter(entry -> entry.getRequiredAdvancement().map(loc -> loc.equals(advancement.id())).orElse(false))
					.toList();
			if(!entries.isEmpty())
			{
				// wrap the toast if it has a title, cancel the original
				Optional<AdvancementToast> wrapped = advancement.value().display().map(
						displayInfo -> displayInfo.getTitle().getString().isEmpty()?null: advToast
				);
				event.setCanceled(true);
				// then enqueue the manual toast
				ClientUtils.mc().getToasts().addToast(new ManualUnlockToast(wrapped, entries));
			}
		}
	}

@SubscribeEvent
	public static void updateEarmuffMultipliers(ClientTickEvent.Pre ev)
	{
		if(ClientUtils.mc().player==null)
			return;
		Map<SoundSource, Float> newMultipliers = makeDefaultMultipliers();
		ItemStack earmuffs = EarmuffsItem.EARMUFF_GETTERS.getFrom(ClientUtils.mc().player);
		if(!earmuffs.isEmpty())
		{
			final var earmuffConfig = earmuffs.getOrDefault(IEDataComponents.EARMUFF_DATA, EarmuffData.DEFAULT);
			for(SoundSource source : SoundSource.values())
				if(EarmuffsItem.affectedSoundCategories.contains(source.getName())&&earmuffConfig.affectedCategories().contains(source.getName()))
				{
					// The max call is just a last safeguard against overly high attenuation (see documentation on
					// EarmuffsItem.MIN_MULTIPLIER). The workbench config UI should limit the attenuation by itself.
					final float newMultiplier = Math.max(EarmuffsItem.MIN_MULTIPLIER, earmuffConfig.volumeMod());
					newMultipliers.put(source, newMultiplier);
				}
		}
		for(SoundSource source : SoundSource.values())
			if(LAST_MULTIPLIERS.get(source).floatValue()!=newMultipliers.get(source))
			{
				LAST_MULTIPLIERS.put(source, newMultipliers.get(source));
				Minecraft.getInstance().getSoundManager().updateSourceVolume(
						source, Minecraft.getInstance().options.getSoundSourceVolume(source)
				);
			}
	}

public static float getVolumeMultiplier(SoundInstance sound)
	{
		if(IGNORED_SOUNDS.contains(sound.getLocation()))
			return 1;
		else
			return LAST_MULTIPLIERS.get(sound.getSource());
	}

private static Pair<String, List<SpecialElementData>> getMineralVeinTexts()
	{
		StringBuilder text = new StringBuilder();
		List<SpecialElementData> specials = new ArrayList<>();

		List<RecipeHolder<MineralMix>> mineralsToAdd = new ArrayList<>(
				MineralMix.RECIPES.getRecipes(Minecraft.getInstance().level)
		);
		Function<RecipeHolder<MineralMix>, String> toName = mineral -> {
			String translationKey = MineralMix.getTranslationKey(mineral.id());
			String localizedName = I18n.get(translationKey);
			if(localizedName.equals(translationKey))
				localizedName = MineralMix.getPlainName(mineral.id());
			return localizedName;
		};
		mineralsToAdd.sort((i1, i2) -> toName.apply(i1).compareToIgnoreCase(toName.apply(i2)));
		for(RecipeHolder<MineralMix> holder : mineralsToAdd)
		{
			final MineralMix mineral = holder.value();
			// Assemble text for biome limitations
			String biomeText = mineral.biomeTagPredicates.stream().map(
					biomeTagPredicate -> biomeTagPredicate.tags().stream().map(biomeTagKey -> {
						// translate biome tags where possible, fall back to location path otherwise
						String key = biomeTagKey.location().toLanguageKey("tag.biome").replaceAll("/", ".");
						if(I18n.exists(key))
							return I18n.get(key);
						else
							return biomeTagKey.location().getPath();
					}).reduce((s, s2) -> I18n.get("ie.manual.entry.minerals.biomes_or", s, s2)).orElse("")
			).reduce((s, s2) -> I18n.get("ie.manual.entry.minerals.biomes_and", s, s2)).orElse("");
			// Combine it with the name of the vein
			String openingString = I18n.get(
					"ie.manual.entry.minerals.biomes",
					toName.apply(holder),
					biomeText
			);

			// Format output and spoils
			List<StackWithChance> formattedOutputs = new ArrayList<>(mineral.outputs);
			List<StackWithChance> formattedSpoils = new ArrayList<>(mineral.spoils);
			formattedOutputs.sort(Comparator.comparingDouble(i -> -i.chance()));
			formattedSpoils.sort(Comparator.comparingDouble(i -> -i.chance()));

			StringBuilder outputString = new StringBuilder();
			NonNullList<ItemStack> sortedOres = NonNullList.create();
			for(StackWithChance sorted : formattedOutputs)
			{
				outputString
						.append("\n")
						.append(
								new DecimalFormat("00.00")
										.format(sorted.chance()*100)
										.replaceAll("\\G0", "\u00A0")
						).append("% ")
						.append(sorted.stack().get().getHoverName().getString());
				sortedOres.add(sorted.stack().get());
			}

			StringBuilder spoilString = new StringBuilder();
			for(StackWithChance sorted : formattedSpoils)
			{
				spoilString
						.append("\n")
						.append(
								new DecimalFormat("00.00")
										.format(sorted.chance()*100)
										.replaceAll("\\G0", "\u00A0")
						).append("% ")
						.append(sorted.stack().get().getHoverName().getString());
				sortedOres.add(sorted.stack().get());
			}

			specials.add(new SpecialElementData(holder.id().toString(), 0, new ManualElementItem(ManualHelper.getManual(), sortedOres)));
			String desc = I18n.get(
					"ie.manual.entry.minerals_desc",
					openingString,
					outputString.toString(),
					spoilString.toString()
			);

			if(!text.isEmpty())
				text.append("<np>");
			text.append("<&")
					.append(holder.id())
					.append(">")
					.append(desc);
		}
		return Pair.of(text.toString(), specials);
	}

@Override
	public boolean mouseScrolled(double mouseX, double mouseY, double scrollX, double scrollY)
	{
		if(this.menu.getCarried().isEmpty()&&this.hoveredSlot instanceof IESlot.ItemHandlerGhost ghostSlot)
		{
			int side = ghostSlot.getSlotIndex()/SorterBlockEntity.FILTER_SLOTS_PER_SIDE;
			if(menu.filterMasks.get(Direction.from3DDataValue(side)).get().allowTags())
			{
				ItemStack item = ghostSlot.getItem();
				List<ResourceLocation> tags = FilterTag.getAvailableForItem(item);
				if(tags.isEmpty())
					return false;
				// get current selected tag
				GetterAndSetter<Optional<ResourceLocation>> selected = this.menu.selectedTags.get(ghostSlot.getSlotIndex());
				int index = selected.get().map(tags::indexOf).orElse(scrollY < 0?-1: 0);
				// scroll and wrap around with modulo, fetching the new tag
				ResourceLocation newTag = tags.get(
						Math.floorMod(index+(scrollY < 0?1: -1), tags.size())
				);
				// write newly selected tag & sync to server
				selected.set(Optional.of(newTag));
				CompoundTag tag = new CompoundTag();
				tag.putInt("tagSlot", ghostSlot.getSlotIndex());
				tag.putString("selectedTag", newTag.toString());
				sendUpdateToServer(tag);
				return true;
			}
		}
		return super.mouseScrolled(mouseX, mouseY, scrollX, scrollY);
	}

@Override
	public void onOpened(ManualScreen gui, int x, int y, List<Button> buttons)
	{
		Player player = mc().player;
		UUID uuid = player.getUUID();
		unlocked = ShaderRegistry.receivedShaders.get(uuid).contains(shader.getName());

		shaderItem = ShaderRegistry.makeShaderStack(shader.name);
		replicationCost = shader.replicationCost.get();

		if(unlocked)
		{
			ArrayList<ItemStack> list = new ArrayList<>();
			for(ItemStack is : ShaderRegistry.itemExamples)
			{
				ItemStack s = is.copy();
				ShaderWrapper wrapper = s.getCapability(CapabilityShader.ITEM);
				if(wrapper!=null)
				{
					wrapper.setShader(shader.name);
					list.add(s);
				}
			}
			exampleItems = list.toArray(new ItemStack[0]);
			example = 0;
			if(exampleItems.length > 1)
			{
				buttons.add(new GuiButtonManualNavigation(gui, x+50, y, 10, 16, 0, btn -> {
					example--;
					if(example < 0)
						example = this.exampleItems.length-1;
				}));
				buttons.add(new GuiButtonManualNavigation(gui, x+100, y, 10, 16, 1,
						btn -> example = (example+1)%exampleItems.length
				));
			}
		}
		else
			exampleItems = null;

		this.name = TextUtils.applyFormat(shaderItem.getHoverName(), ChatFormatting.BOLD);
		MutableComponent textAssembly = Component.literal("");
		textAssembly.append(TextUtils.applyFormat(Component.translatable("desc.immersiveengineering.info.shader.level"), ChatFormatting.BOLD));
		textAssembly.append(Component.translatable("desc.immersiveengineering.info.shader.rarity."+shader.rarity.name().toLowerCase(Locale.US)));
		if(unlocked)
		{
			String set = shader.info_set==null||shader.info_set.isEmpty()?null: ManualUtils.attemptStringTranslation(Lib.DESC_INFO+"shader.set.%s", shader.info_set);
			String reference = shader.info_reference==null||shader.info_reference.isEmpty()?null: ManualUtils.attemptStringTranslation(Lib.DESC_INFO+"shader.reference.%s", shader.info_reference);
			String details = shader.info_details==null||shader.info_details.isEmpty()?null: ManualUtils.attemptStringTranslation(Lib.DESC_INFO+"shader.details.%s", shader.info_details);

			if(set!=null)
				textAssembly.append("\n")
						.append(TextUtils.applyFormat(Component.translatable("desc.immersiveengineering.info.shader.set"), ChatFormatting.BOLD))
						.append(" "+set);
			if(reference!=null)
				textAssembly.append("\n")
						.append(TextUtils.applyFormat(Component.translatable("desc.immersiveengineering.info.shader.reference"), ChatFormatting.BOLD))
						.append("\n"+reference);
			if(details!=null)
				textAssembly.append("\n")
						.append(TextUtils.applyFormat(Component.translatable("desc.immersiveengineering.info.shader.details"), ChatFormatting.BOLD))
						.append("\n"+details);

			String cost = Integer.toString(replicationCost.getCount());
			if(!IngredientUtils.hasPlayerIngredient(mc().player, replicationCost)&&!mc().player.getAbilities().instabuild)
				cost = ChatFormatting.RED+cost;
			buttons.add(new GuiButtonManual(gui, x+50, y+120, 70, 12,
					Component.literal(I18n.get("ie.manual.entry.shaderList.order")+" "+cost+"x   ").withStyle(ChatFormatting.BOLD),
					btn -> {
						if(IngredientUtils.hasPlayerIngredient(mc().player, replicationCost)||mc().player.getAbilities().instabuild)
							PacketDistributor.sendToServer(
									new MessageShaderManual(MessageType.SPAWN, shader.getName())
							);
						gui.fullInit();
					})
					.setTextColour(gui.getManual().getTextColour(), gui.getManual().getHighlightColour()));
		}
		else
		{
			textAssembly.append("\n\n").append(Component.translatable("ie.manual.entry.shaderList.noInfo"));
			if(player.getAbilities().instabuild)
				buttons.add(new GuiButtonManual(gui, x+10, y+120, 100, 16,
						Component.translatable("ie.manual.entry.shaderList.unlock"),
						btn -> {
							UUID playerId = mc().player.getUUID();
							PacketDistributor.sendToServer(new MessageShaderManual(MessageType.UNLOCK, shader.getName()));
							ShaderRegistry.receivedShaders.put(playerId, shader.getName());
							gui.fullInit();
						})
						.setTextColour(gui.getManual().getTextColour(), gui.getManual().getHighlightColour())
				);
		}
		this.text = textAssembly;
	}

@Nullable
		@Override
		public BakedModel resolve(
				@Nonnull BakedModel model, @Nonnull ItemStack stack, @Nullable ClientLevel world,
				@Nullable LivingEntity livingEntity, int unused
		)
		{
			final FluidStack fluid = FluidUtil.getFluidContained(stack).orElse(FluidStack.EMPTY);
			if(fluid.isEmpty())
				return nested.resolve(model, stack, world, livingEntity, unused);
			int color = IClientFluidTypeExtensions.of(fluid.getFluid()).getTintColor(fluid);
			// flip to AGBR, because Mojang I guess
			color = (color&0xFF00FF00) // alpha and green same spot
					|((color>>16)&0x000000FF) // red moves to blue
					|((color<<16)&0x00FF0000); // blue moves to red
			return coloredModels.computeIfAbsent(color, i -> new PotionBucketModel(i).bake(
					owner, bakery, textureGetter,
					BlockModelRotation.X0_Y0, this
			));
		}

public SpecificFeedthroughModel(ItemStack stack)
		{
			final var itemData = stack.getOrDefault(IEDataComponents.FEEDTHROUGH_DATA, ItemData.FALLBACK);
			BlockState state = itemData.middleState();
			if(state.getBlock()==Blocks.AIR)
				state = Blocks.BOOKSHELF.defaultBlockState();
			init(new FeedthroughCacheKey(itemData.type(), state, Integer.MAX_VALUE, Direction.NORTH, null),
					i -> mc().getItemColors().getColor(stack, i));
		}

private void init(FeedthroughCacheKey k, Int2IntFunction colorMultiplierBasic)
		{
			RandomSource random = RandomSource.create(0);
			BakedModel model = mc().getBlockRenderer().getBlockModelShaper()
					.getBlockModel(k.baseState);
			if(colorMultiplierBasic==null)
			{
				ItemColors colors = mc().getItemColors();
				ItemStack stack = new ItemStack(k.baseState.getBlock(), 1);
				colorMultiplierBasic = i -> colors.getColor(stack, i);
			}
			Int2IntFunction colorMultiplierFinal = colorMultiplierBasic;
			Int2IntFunction colorMultiplier = i -> {
				int ret = colorMultiplierFinal.get(i);
				k.specificColorMultipliers.put(i, ret);
				return ret;
			};
			boolean renderBlockInLayer = k.layer==null||model.getRenderTypes(k.baseState, random, ModelData.EMPTY).contains(k.layer);
			for(int j = 0; j < 7; j++)
			{
				Direction side = j < 6?DirectionUtils.VALUES[j]: null;
				Direction facing = k.facing;
				switch(k.offset)
				{
					case 0:
						if(renderBlockInLayer)
						{
							List<BakedQuad> modelQuads = model.getQuads(
									k.baseState, side, random, ModelData.EMPTY, k.layer
							);
							quads.add(QuadTransformer.color(colorMultiplier).process(modelQuads));
						}
						break;
					case 1:
						facing = facing.getOpposite();
					case -1:
						if(k.layer==RenderType.solid())
							quads.add(getConnQuads(facing, side, k.type, new Matrix4(), k.layer, random));
						break;
					case Integer.MAX_VALUE:
						Matrix4 mat = new Matrix4();
						mat.translate(0, 0, 1);
						List<BakedQuad> all = new ArrayList<>(getConnQuads(facing, side, k.type, mat, k.layer, random));
						mat = new Matrix4();
						mat.translate(0, 0, -1);
						all.addAll(getConnQuads(facing.getOpposite(), side, k.type, mat, k.layer, random));
						if(renderBlockInLayer)
						{
							var tintTransformer = QuadTransformer.color(colorMultiplier);
							all.addAll(tintTransformer.process(
									model.getQuads(k.baseState, side, random, ModelData.EMPTY, k.layer)
							));
						}
						quads.add(all);
						break;
				}
				if(quads.size() <= j)
					quads.add(ImmutableList.of());
			}
		}

@Nullable
	private static ResourceLocation getSoilTexture(ItemStack soil)
	{
		ResourceLocation rl = ClocheRecipe.getSoilTexture(soil);
		if(rl==null)
		{
			try
			{
				BlockState state = Utils.getStateFromItemStack(soil);
				if(state!=null)
					rl = ModelUtils.getSideTexture(state, Direction.UP);
			} catch(Exception e)
			{
				rl = ModelUtils.getSideTexture(soil, Direction.UP);
			}
		}
		if(rl==null&&!soil.isEmpty()&&Utils.isFluidRelatedItemStack(soil))
			rl = FluidUtil.getFluidContained(soil)
					.map(fs -> IClientFluidTypeExtensions.of(fs.getFluid()).getStillTexture(fs))
					.orElse(null);
		return rl;
	}

