@Override
	public boolean shouldRenderGroup(Key stack, String group, RenderType layer)
	{
		if(group.equals("frame")||group.equals("cylinder"))
			return true;

		Set<String> render = new HashSet<>();
		String tag = stack.elite();
		String flavour = stack.flavor();
		if(!tag.isEmpty()&&specialRevolversByTag.containsKey(tag))
		{
			SpecialRevolver r = specialRevolversByTag.get(tag);
			if(r!=null&&r.renderAdditions()!=null)
				render.addAll(r.renderAdditions());
		}
		else if(!flavour.isEmpty()&&specialRevolversByTag.containsKey(flavour))
		{
			SpecialRevolver r = specialRevolversByTag.get(flavour);
			if(r!=null&&r.renderAdditions()!=null)
				render.addAll(r.renderAdditions());
		}
		if(stack.extraBullets()&&!render.contains("dev_mag"))
			render.add("player_mag");
		if(stack.extraMelee()&&!render.contains("dev_bayonet"))
		{
			render.add("bayonet_attachment");
			render.add("player_bayonet");
		}
		if(stack.electro())
		{
			render.add("player_electro_0");
			render.add("player_electro_1");
		}
		if(stack.scope())
			render.add("dev_scope");
		if(stack.snub())
			render.add("barrel_snub");
		else
		{
			render.add("barrel");
			render.add("cosmetic_compensator");
		}
		return render.contains(group);
	}

private <T> void renderQuadsForGroups(List<String> groups, SpecificIEOBJModel<T> model, ItemCallback<T> callback,
										  ItemStack stack, PoseStack matrix, MultiBufferSource buffer,
										  Set<String> visible, int light, int overlay)
	{
		List<ShadedQuads> quadsByLayer = new ArrayList<>();
		for(String groupName : groups)
		{
			Group<OBJMaterial> group = model.getGroups().get(groupName);
			if(visible.contains(groupName)&&callback.shouldRenderGroup(model.getKey(), groupName, null))
				quadsByLayer.addAll(model.addQuadsForGroup(groupName, group, true)
						.stream().filter(Objects::nonNull).toList());
			visible.remove(groupName);
		}
		matrix.pushPose();
		for(ShadedQuads quadsForLayer : quadsByLayer)
		{
			boolean bright = callback.areGroupsFullbright(stack, groups);
			RenderType baseType;
			ResourceLocation atlas = InventoryMenu.BLOCK_ATLAS;
			Color4 color = quadsForLayer.layer().getColor();
			List<RenderType> renderTypes = model.getRenderTypes(stack, Minecraft.useFancyGraphics());
			if(bright)
				baseType = IERenderTypes.getFullbrightTranslucent(atlas);
			else if(quadsForLayer.layer().isTranslucent()||color.a() < 1)
				baseType = RenderType.entityTranslucent(atlas);
			else if(!renderTypes.isEmpty())
				baseType = renderTypes.get(0);
			else
				baseType = RenderType.entityCutoutNoCull(atlas);
			RenderType actualType = quadsForLayer.layer().getRenderType(baseType);
			VertexConsumer builder = buffer.getBuffer(actualType);
			boolean hasColor = color.r()!=1 || color.b()!=1 || color.g()!=1 || color.a()!=1;
			for(BakedQuad quad : quadsForLayer.quadsInLayer())
				builder.putBulkData(matrix.last(), quad, color.r(), color.g(), color.b(), color.a(), light, overlay, !hasColor);
			matrix.scale(1.0005F, 1.0005F, 1.0005F);
		}
		matrix.popPose();
	}

public static BlueprintLines getBlueprintDrawable(ItemStack stack, Level world)
	{
		if(stack.isEmpty())
			return null;
		Player player = ClientUtils.mc().player;
		List<TextureAtlasSprite> images = new ArrayList<>();
		try
		{
			BakedModel ibakedmodel = ClientUtils.mc().getItemRenderer().getModel(stack, world, player, 0);
			Set<ResourceLocation> textures = new HashSet<>();
			Collection<BakedQuad> quads = ibakedmodel.getQuads(null, null, world.random, ModelData.EMPTY, null);
			final Function<ResourceLocation, TextureAtlasSprite> blockAtlas = ClientUtils.mc().getTextureAtlas(InventoryMenu.BLOCK_ATLAS);
			for(BakedQuad quad : quads)
			{
				final ResourceLocation texture = quad.getSprite().contents().name();
				if(textures.add(texture))
					images.add(blockAtlas.apply(texture));
			}
		} catch(Exception e)
		{
			e.printStackTrace();
		}
		if(images.isEmpty())
			return null;
		List<Pair<TexturePoint, TexturePoint>> lines = new ArrayList<>();
		Set<TexturePoint> testSet = new HashSet<>();
		HashMultimap<Integer, TexturePoint> area = HashMultimap.create();
		int wMax = 0;
		for(TextureAtlasSprite bufferedImage : images)
		{
			Set<Pair<TexturePoint, TexturePoint>> tempLines = new HashSet<>();

			int w = bufferedImage.contents().width();
			int h = bufferedImage.contents().height();

			if(h > w)
				h = w;
			if(w > wMax)
				wMax = w;
			for(int hh = 0; hh < h; hh++)
				for(int ww = 0; ww < w; ww++)
				{
					int argb = bufferedImage.getPixelRGBA(0, ww, hh);
					float r = (argb>>16&255)/255f;
					float g = (argb>>8&255)/255f;
					float b = (argb&255)/255f;
					float intesity = (r+b+g)/3f;
					int alpha = (argb>>24)&255;
					if(alpha > 0)
					{
						boolean added = false;
						//Check colour sets for similar colour to shade it later
						TexturePoint tp = new TexturePoint(ww, hh, w);
						if(!testSet.contains(tp))
						{
							for(Integer key : area.keySet())
							{
								for(TexturePoint p : area.get(key))
								{
									float mod = w/(float)p.scale;
									int pColour = bufferedImage.getPixelRGBA(0, (int)(p.x*mod), (int)(p.y*mod));
									float dR = (r-(pColour>>16&255)/255f);
									float dG = (g-(pColour>>8&255)/255f);
									float dB = (b-(pColour&255)/255f);
									double delta = Math.sqrt(dR*dR+dG*dG+dB*dB);
									if(delta < .25)
									{
										area.put(key, tp);
										added = true;
										break;
									}
								}
								if(added)
									break;
							}
							if(!added)
								area.put(argb, tp);
							testSet.add(tp);
						}
						//Compare to direct neighbour
						for(int i = 0; i < 4; i++)
						{
							int xx = (i==0?-1: i==1?1: 0);
							int yy = (i==2?-1: i==3?1: 0);
							int u = ww+xx;
							int v = hh+yy;

							int neighbour = 0;
							float delta = 1;
							boolean notTransparent = false;
							if(u >= 0&&u < w&&v >= 0&&v < h)
							{
								neighbour = bufferedImage.getPixelRGBA(0, u, v);
								notTransparent = ((neighbour>>24)&255) > 0;
								if(notTransparent)
								{
									float neighbourIntesity = ((neighbour>>16&255)+(neighbour>>8&255)+(neighbour&255))/765f;
									float intesityDelta = Math.max(0, Math.min(1, Math.abs(intesity-neighbourIntesity)));
									float rDelta = Math.max(0, Math.min(1, Math.abs(r-(neighbour>>16&255)/255f)));
									float gDelta = Math.max(0, Math.min(1, Math.abs(g-(neighbour>>8&255)/255f)));
									float bDelta = Math.max(0, Math.min(1, Math.abs(b-(neighbour&255)/255f)));
									delta = Math.max(intesityDelta, Math.max(rDelta, Math.max(gDelta, bDelta)));
									delta = delta < .25?0: delta > .4?1: delta;
								}
							}
							if(delta > 0)
							{
								Pair<TexturePoint, TexturePoint> l = Pair.of(new TexturePoint(ww+(i==0?0: i==1?1: 0), hh+(i==2?0: i==3?1: 0), w), new TexturePoint(ww+(i==0?0: i==1?1: 1), hh+(i==2?0: i==3?1: 1), w));
								tempLines.add(l);
							}
						}
					}
				}
			lines.addAll(tempLines);
		}

		List<Integer> lumiSort = new ArrayList<>(area.keySet());
		lumiSort.sort(Comparator.comparingDouble(BlueprintRenderer::getLuminance));
		HashMultimap<ShadeStyle, Point> complete_areaMap = HashMultimap.create();
		int lineNumber = 2;
		StripeDirection lineStyle = StripeDirection.VERTICAL;
		for(Integer i : lumiSort)
		{
			Set<Point> styleSlot = complete_areaMap.get(new ShadeStyle(lineNumber, lineStyle));
			for(TexturePoint point : area.get(i))
				styleSlot.add(new Point(point.x(), point.y()));
			lineStyle = lineStyle.next();
			if(lineStyle==StripeDirection.VERTICAL)
				lineNumber += 1;
		}

		Set<Pair<Point, Point>> complete_lines = new HashSet<>();
		for(Pair<TexturePoint, TexturePoint> line : lines)
		{
			TexturePoint p1 = line.getFirst();
			TexturePoint p2 = line.getSecond();
			complete_lines.add(Pair.of(new Point((int)(p1.x/(float)p1.scale*wMax), (int)(p1.y/(float)p1.scale*wMax)), new Point((int)(p2.x/(float)p2.scale*wMax), (int)(p2.y/(float)p2.scale*wMax))));
		}
		return new BlueprintLines(wMax, complete_lines, complete_areaMap);
	}

private static Pair<IntegerProperty, Integer> getCropAge(Block block) throws IllegalArgumentException
	{
		if(block instanceof CropBlock crop)
			return Pair.of(((CropBlockAccess)crop).invokeGetAgeProperty(), crop.getMaxAge());
		else
		{
			for(Property<?> prop : block.defaultBlockState().getProperties())
				if("age".equals(prop.getName())&&prop instanceof IntegerProperty intProp)
				{
					int max = intProp.getPossibleValues().stream().max(Integer::compare).orElse(-1);
					if(max > 0)
						return Pair.of(intProp, max);
				}
		}
		throw new IllegalArgumentException("Block "+block.getDescriptionId()+" is not a valid crop block");
	}

protected boolean canRotate()
	{
		//Basic heuristic: Multiblocks should not be rotated depending on state
		return !getStateDefinition().getProperties().contains(IEProperties.MULTIBLOCKSLAVE);
	}

@Override
	public void readCustomNBT(@Nonnull CompoundTag nbt, boolean descPacket, Provider provider)
	{
		super.readCustomNBT(nbt, descPacket, provider);
		final int oldStyle = style;
		final DyeColor oldC0 = colour0;
		final DyeColor oldC1 = colour1;
		style = nbt.getInt("style");
		int tmpIdx = nbt.getInt("colour0");
		colour0 = tmpIdx >= 0&&tmpIdx < DyeColor.values().length?DyeColor.byId(tmpIdx): null;
		tmpIdx = nbt.getInt("colour1");
		colour1 = tmpIdx >= 0&&tmpIdx < DyeColor.values().length?DyeColor.byId(tmpIdx): null;
