			requestModelDataUpdate();
		if(nbt.contains("shader", Tag.TAG_COMPOUND))
			shader = ShaderWrapper_Direct.SERIALIZER.read(this, nbt.getCompound("shader"), provider);
		markContainingBlockForUpdate(null);
	}

