private float getElectrodeComparatorValue()
		{
			return (float)IntStream.range(0, ELECTRODE_COUNT).mapToDouble(i -> {
				final ItemStack electrode = inventory.getStackInSlot(FIRST_ELECTRODE_SLOT+i);
				if(electrode.isEmpty())
