public static int bigItemStackToLuaTableFilter(BigItemStack entry, Map<?, ?> filter) throws LuaException {
		Map<String, Object> details = VanillaDetailRegistries.ITEM_STACK.getDetails(entry.stack);

		// Count needs to be replaced because BigItemStack can have a different count than the stack
		details.put("count", entry.count);

		// If name is in filter and doesn't have : in it add minecraft: namespace
		if (filter.containsKey("name") && filter.get("name") instanceof String name) {
			if (!name.contains(":")) {
				details.put("name", "minecraft:" + name);
			}
		}

		if (!deepEquals(new HashMap<>(filter), details))
			return 0;
		return entry.count;
	}

public static void init(IEventBus modEventBus) {
		modEventBus.addListener(Curios::onClientSetup);

		GogglesItem.addIsWearingPredicate(player -> resolveCuriosMap(player)
			.map(curiosMap -> {
				for (ICurioStacksHandler stacksHandler : curiosMap.values()) {
					// Search all the curio slots for Goggles existing
					int slots = stacksHandler.getSlots();
					for (int slot = 0; slot < slots; slot++) {
						if (AllItems.GOGGLES.isIn(stacksHandler.getStacks().getStackInSlot(slot))) {
							return true;
						}
					}
				}

				return false;
			})
			.orElse(false));

		BacktankUtil.addBacktankSupplier(entity -> resolveCuriosMap(entity)
			.map(curiosMap -> {
				List<ItemStack> stacks = new ArrayList<>();
				for (ICurioStacksHandler stacksHandler : curiosMap.values()) {
					// Search all the curio slots for pressurized air sources, and add them to the list
					int slots = stacksHandler.getSlots();
					for (int slot = 0; slot < slots; slot++) {
						final ItemStack itemStack = stacksHandler.getStacks().getStackInSlot(slot);
						if (AllTags.AllItemTags.PRESSURIZED_AIR_SOURCES.matches(itemStack))
							stacks.add(itemStack);
					}
				}

				return stacks;
			}).orElse(Collections.emptyList()));

		CatnipServices.PLATFORM.executeOnClientOnly(() -> () -> modEventBus.addListener(CuriosRenderers::onLayerRegister));
	}

public static CompoundTag prepareBlockEntityData(BlockState blockState, BlockEntity blockEntity) {
		CompoundTag data = null;
		if (blockEntity == null)
			return data;

		data = blockEntity.saveWithFullMetadata(blockEntity.getLevel().registryAccess());

		List<String> keysToRemove = new ArrayList<>();
		for (String key : data.getAllKeys())
			if (!KEYS_TO_RETAIN.contains(key))
				keysToRemove.add(key);
		for (String key : keysToRemove)
			data.remove(key);

		if (data.getCompound("camo")
			.contains("fluid"))
			data.remove("camo");

		if (data.getCompound("camo_two")
			.contains("fluid"))
			data.remove("camo_two");

		return data;
	}

public static ItemRequirement getRequiredItems(BlockState blockState, BlockEntity blockEntity) {
		if (blockEntity == null)
			return ItemRequirement.NONE;

		CompoundTag data = blockEntity.saveWithFullMetadata(blockEntity.getLevel().registryAccess());
		List<StackRequirement> list = new ArrayList<>();

		if (data.getBoolean("intangible"))
			list.add(new StackRequirement(new ItemStack(Items.PHANTOM_MEMBRANE), ItemUseType.CONSUME));

		if (data.getBoolean("glowing"))
			list.add(new StackRequirement(new ItemStack(Items.GLOWSTONE_DUST), ItemUseType.CONSUME));

		if (data.getBoolean("reinforced"))
			list.add(new StackRequirement(new ItemStack(Mods.FRAMEDBLOCKS.getItem("framed_reinforcement")),
				ItemUseType.CONSUME));

		if (data.contains("camo"))
			addCamoStack(blockEntity.getLevel().holderLookup(Registries.BLOCK), data.getCompound("camo"), list);

		if (data.contains("camo_two"))
			addCamoStack(blockEntity.getLevel().holderLookup(Registries.BLOCK), data.getCompound("camo_two"), list);

		return new ItemRequirement(list);
	}

private static void addCamoStack(HolderGetter<Block> level, CompoundTag tag, List<StackRequirement> list) {
		if (!tag.contains("state"))
			return;
		BlockState blockState = NbtUtils.readBlockState(level, tag.getCompound("state"));
		ItemStack itemStack = new ItemStack(blockState.getBlock());
		if (!itemStack.isEmpty())
			list.add(new StackRequirement(itemStack, ItemUseType.CONSUME));
	}

