public TransportedItemStack(ItemStack stack) {
		this.stack = stack;
		boolean centered = BeltHelper.isItemUpright(stack);
		angle = centered ? 180 : R.nextInt(360);
		if (PackageItem.isPackage(stack))
			angle = R.nextInt(4) * 90 + R.nextInt(20) - 10;
		sideOffset = prevSideOffset = getTargetSideOffset();
		insertedFrom = Direction.UP;
	}

public float getTargetSideOffset() {
		return (angle - 180) / (360 * 3f);
	}

@Override
	public int compareTo(TransportedItemStack o) {
		return beltPosition < o.beltPosition ? 1 : beltPosition > o.beltPosition ? -1 : 0;
	}

public TransportedItemStack getSimilar() {
		TransportedItemStack copy = new TransportedItemStack(stack.copy());
		copy.beltPosition = beltPosition;
		copy.insertedAt = insertedAt;
		copy.insertedFrom = insertedFrom;
		copy.prevBeltPosition = prevBeltPosition;
		copy.prevSideOffset = prevSideOffset;
		copy.processedBy = processedBy;
		copy.processingTime = processingTime;
		return copy;
	}

public TransportedItemStack copy() {
		TransportedItemStack copy = getSimilar();
		copy.angle = angle;
		copy.sideOffset = sideOffset;
		return copy;
	}

public CompoundTag serializeNBT(HolderLookup.Provider registries) {
		CompoundTag nbt = new CompoundTag();
		nbt.put("Item", stack.saveOptional(registries));
		nbt.putFloat("Pos", beltPosition);
		nbt.putFloat("PrevPos", prevBeltPosition);
		nbt.putFloat("Offset", sideOffset);
		nbt.putFloat("PrevOffset", prevSideOffset);
		nbt.putInt("InSegment", insertedAt);
		nbt.putInt("Angle", angle);
		nbt.putInt("InDirection", insertedFrom.get3DDataValue());

		if (processedBy != null) {
			ResourceLocation key = CreateBuiltInRegistries.FAN_PROCESSING_TYPE.getKey(processedBy);
			if (key == null)
				throw new IllegalArgumentException("Could not get id for FanProcessingType " + processedBy + "!");

			nbt.putString("FanProcessingType", key.toString());
			nbt.putInt("FanProcessingTime", processingTime);
		}

		if (locked)
			nbt.putBoolean("Locked", locked);
		if (lockedExternally)
			nbt.putBoolean("LockedExternally", lockedExternally);
		return nbt;
	}

public static TransportedItemStack read(CompoundTag nbt, HolderLookup.Provider registries) {
		TransportedItemStack stack = new TransportedItemStack(ItemStack.parseOptional(registries, nbt.getCompound("Item")));
		stack.beltPosition = nbt.getFloat("Pos");
		stack.prevBeltPosition = nbt.getFloat("PrevPos");
		stack.sideOffset = nbt.getFloat("Offset");
		stack.prevSideOffset = nbt.getFloat("PrevOffset");
		stack.insertedAt = nbt.getInt("InSegment");
		stack.angle = nbt.getInt("Angle");
		stack.insertedFrom = Direction.from3DDataValue(nbt.getInt("InDirection"));
		stack.locked = nbt.getBoolean("Locked");
		stack.lockedExternally = nbt.getBoolean("LockedExternally");

		if (nbt.contains("FanProcessingType")) {
			stack.processedBy = AllFanProcessingTypes.parseLegacy(nbt.getString("FanProcessingType"));
			stack.processingTime = nbt.getInt("FanProcessingTime");
		}

		return stack;
	}

public void clearFanProcessingData() {
		processedBy = null;
		processingTime = 0;
	}

public void removeInvalidConnections() {
		boolean changed = false;
		for (Iterator<BlockPos> iterator = connections.iterator(); iterator.hasNext(); ) {
			BlockPos next = iterator.next();
			BlockPos target = worldPosition.offset(next);
			if (!level.isLoaded(target))
				continue;
			if (level.getBlockEntity(target) instanceof ChainConveyorBlockEntity ccbe
				&& ccbe.connections.contains(next.multiply(-1)))
				continue;
			iterator.remove();
			changed = true;
		}
		if (changed)
			notifyUpdate();
	}

public boolean addTravellingPackage(ChainConveyorPackage box, BlockPos connection) {
		if (!connections.contains(connection))
			return false;
		travellingPackages.computeIfAbsent(connection, $ -> new ArrayList<>())
			.add(box);
		if (level.isClientSide)
			return true;
		notifyUpdate();
		return true;
	}

public boolean removeConnectionTo(BlockPos target) {
		BlockPos localTarget = target.subtract(worldPosition);
		if (!connections.contains(localTarget))
			return false;

		detachKinetics();
		connections.remove(localTarget);
		connectionStats.remove(localTarget);
		List<ChainConveyorPackage> packages = travellingPackages.remove(localTarget);
		if (packages != null)
			for (ChainConveyorPackage box : packages)
				drop(box);
		notifyUpdate();
		updateChainShapes();
		updateSpeed = true;

		return true;
	}

@Override
	public float propagateRotationTo(KineticBlockEntity target, BlockState stateFrom, BlockState stateTo, BlockPos diff,
									 boolean connectedViaAxes, boolean connectedViaCogs) {
		if (connections.contains(target.getBlockPos()
			.subtract(worldPosition))) {
			if (!(target instanceof ChainConveyorBlockEntity))
				return 0;
			return 1;
		}
		return super.propagateRotationTo(target, stateFrom, stateTo, diff, connectedViaAxes, connectedViaCogs);
	}

@Override
	protected void read(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		super.read(compound, registries, clientPacket);
		if (clientPacket && compound.contains("DestroyEffect") && level != null)
			spawnDestroyParticles(NBTHelper.readBlockPos(compound, "DestroyEffect"));

		int sizeBefore = connections.size();
		connections.clear();
		CatnipCodecUtils.decode(CatnipCodecs.set(BlockPos.CODEC), registries, compound.get("Connections")).ifPresent(connections::addAll);
		travellingPackages.clear();
		NBTHelper.iterateCompoundList(compound.getList("TravellingPackages", Tag.TAG_COMPOUND),
			c -> travellingPackages.put(NBTHelper.readBlockPos(c, "Target"),
				NBTHelper.readCompoundList(c.getList("Packages", Tag.TAG_COMPOUND), t -> ChainConveyorPackage.read(t, registries))));
		loopingPackages = NBTHelper.readCompoundList(compound.getList("LoopingPackages", Tag.TAG_COMPOUND),
			t -> ChainConveyorPackage.read(t, registries));
		connectionStats = null;
		updateBoxWorldPositions();
		updateChainShapes();

		if (connections.size() != sizeBefore && level != null && level.isClientSide)
			invalidateRenderBoundingBox();
	}

public static boolean validateAndConnect(LevelAccessor level, BlockPos pos, Player player, ItemStack chain,
		boolean simulate) {
		if (!simulate && player.isShiftKeyDown()) {
			CreateLang.translate("chain_conveyor.selection_cleared")
				.sendStatus(player);
			return false;
		}

		if (pos.equals(firstPos))
			return false;
		if (!pos.closerThan(firstPos, AllConfigs.server().kinetics.maxChainConveyorLength.get()))
			return fail("chain_conveyor.too_far");
		if (pos.closerThan(firstPos, 2.5))
			return fail("chain_conveyor.too_close");

		Vec3 diff = Vec3.atLowerCornerOf(pos.subtract(firstPos));
		double horizontalDistance = diff.multiply(1, 0, 1)
			.length() - 1.5;

		if (horizontalDistance <= 0)
			return fail("chain_conveyor.cannot_connect_vertically");
		if (Math.abs(diff.y) / horizontalDistance > 1)
			return fail("chain_conveyor.too_steep");

		ChainConveyorBlock chainConveyorBlock = AllBlocks.CHAIN_CONVEYOR.get();
		ChainConveyorBlockEntity sourceLift = chainConveyorBlock.getBlockEntity(level, firstPos);
		ChainConveyorBlockEntity targetLift = chainConveyorBlock.getBlockEntity(level, pos);

		if (targetLift.connections.size() >= AllConfigs.server().kinetics.maxChainConveyorConnections.get())
			return fail("chain_conveyor.cannot_add_more_connections");
		if (targetLift.connections.contains(firstPos.subtract(pos)))
			return fail("chain_conveyor.already_connected");
		if (sourceLift == null || targetLift == null)
			return fail("chain_conveyor.blocks_invalid");

		if (!player.isCreative()) {
			int chainCost = ChainConveyorBlockEntity.getChainCost(pos.subtract(firstPos));
			boolean hasEnough = ChainConveyorBlockEntity.getChainsFromInventory(player, chain, chainCost, true);
			if (simulate)
				BlueprintOverlayRenderer.displayChainRequirements(chain.getItem(), chainCost, hasEnough);
			if (!hasEnough)
				return fail("chain_conveyor.not_enough_chains");
		}

		if (simulate)
			return true;

		CatnipServices.NETWORK.sendToServer(new ChainConveyorConnectionPacket(firstPos, pos, chain, true));

		CreateLang.text("") // Clear status message
			.sendStatus(player);
		firstPos = null;
		firstDim = null;
		return true;
	}

public static ChainConveyorPackage read(CompoundTag compoundTag, HolderLookup.Provider registries) {
		float pos = compoundTag.getFloat("Position");
		ItemStack item = ItemStack.parseOptional(registries, compoundTag.getCompound("Item"));
		if (compoundTag.contains("NetID"))
			return new ChainConveyorPackage(pos, item, compoundTag.getInt("NetID"));
		return new ChainConveyorPackage(pos, item);
	}

@Override
	protected void read(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		Phase phaseBefore = phase;
		GroupedItems before = this.groupedItems;

		inventory.deserializeNBT(registries, compound.getCompound("Inventory"));
		input.read(compound.getCompound("ConnectedInput"));
		groupedItems = GroupedItems.read(compound.getCompound("GroupedItems"), registries);
		phase = Phase.IDLE;
		String name = compound.getString("Phase");
		for (Phase phase : Phase.values())
			if (phase.name()
				.equals(name))
				this.phase = phase;
		countDown = compound.getInt("CountDown");
		covered = compound.getBoolean("Cover");
		super.read(compound, registries, clientPacket);
		if (!clientPacket)
			return;
		if (compound.contains("Redraw"))
			level.sendBlockUpdated(getBlockPos(), getBlockState(), getBlockState(), 16);
		if (phaseBefore != phase && phase == Phase.CRAFTING)
			groupedItemsBeforeCraft = before;
		if (phaseBefore == Phase.EXPORTING && phase == Phase.WAITING) {
			if (before.onlyEmptyItems())
				return;
			Direction facing = getBlockState().getValue(MechanicalCrafterBlock.HORIZONTAL_FACING);
			Vec3 vec = Vec3.atLowerCornerOf(facing.getNormal())
				.scale(.75)
				.add(VecHelper.getCenterOf(worldPosition));
			Direction targetDirection = MechanicalCrafterBlock.getTargetDirection(getBlockState());
			vec = vec.add(Vec3.atLowerCornerOf(targetDirection.getNormal())
				.scale(1));
			level.addParticle(ParticleTypes.CRIT, vec.x, vec.y, vec.z, 0, 0, 0);
		}
	}

public static List<MechanicalCrafterBlockEntity> getAllCraftersOfChainIf(MechanicalCrafterBlockEntity root,
		Predicate<MechanicalCrafterBlockEntity> test, boolean poweredStart) {
		List<MechanicalCrafterBlockEntity> crafters = new ArrayList<>();
		List<Pair<MechanicalCrafterBlockEntity, MechanicalCrafterBlockEntity>> frontier = new ArrayList<>();
		Set<MechanicalCrafterBlockEntity> visited = new HashSet<>();
		frontier.add(Pair.of(root, null));

		boolean empty = false;
		boolean allEmpty = true;

		while (!frontier.isEmpty()) {
			Pair<MechanicalCrafterBlockEntity, MechanicalCrafterBlockEntity> pair = frontier.remove(0);
			MechanicalCrafterBlockEntity current = pair.getKey();
			MechanicalCrafterBlockEntity last = pair.getValue();

			if (visited.contains(current))
				return null;
			if (!(test.test(current)))
				empty = true;
			else
				allEmpty = false;

			crafters.add(current);
			visited.add(current);

			MechanicalCrafterBlockEntity target = getTargetingCrafter(current);
			if (target != last && target != null)
				frontier.add(Pair.of(target, current));
			for (MechanicalCrafterBlockEntity preceding : getPrecedingCrafters(current))
				if (preceding != last)
					frontier.add(Pair.of(preceding, current));
		}

		return empty && !poweredStart || allEmpty ? null : crafters;
	}

public static ItemStack tryToApplyRecipe(Level world, GroupedItems items) {
		items.calcStats();
		CraftingInput craftingInput = MechanicalCraftingInput.of(items);
		ItemStack result = null;
		RegistryAccess registryAccess = world.registryAccess();
		if (AllConfigs.server().recipes.allowRegularCraftingInCrafter.get())
			result = world.getRecipeManager()
				.getRecipeFor(RecipeType.CRAFTING, craftingInput, world)
				.filter(r -> isRecipeAllowed(r, craftingInput))
				.map(r -> r.value().assemble(craftingInput, registryAccess))
				.orElse(null);
		if (result == null)
			result = AllRecipeTypes.MECHANICAL_CRAFTING.find(craftingInput, world)
				.map(r -> r.value().assemble(craftingInput, registryAccess))
				.orElse(null);
		return result;
	}

