public static ItemStack fixCtrlCopiedStack(ItemStack stack) {
		// Salvage frequency data from one of the panel slots
		if (isTuned(stack) && networkFromStack(stack) == null) {
			CompoundTag bet = stack.getOrDefault(DataComponents.BLOCK_ENTITY_DATA, CustomData.EMPTY).copyTag();
			UUID frequency = UUID.randomUUID();

			for (PanelSlot slot : PanelSlot.values()) {
				CompoundTag panelTag = bet.getCompound(CreateLang.asId(slot.name()));
				if (panelTag.hasUUID("Freq"))
					frequency = panelTag.getUUID("Freq");
			}

			bet = new CompoundTag();
			bet.putUUID("Freq", frequency);

			BlockEntity.addEntityType(bet, ((IBE<?>) ((BlockItem) stack.getItem()).getBlock()).getBlockEntityType());
			stack.set(DataComponents.BLOCK_ENTITY_DATA, CustomData.of(bet));
		}

		return stack;
	}

@Nullable
	private static String checkForIssues(FactoryPanelBehaviour from, FactoryPanelSupportBehaviour to) {
		if (from == null)
			return "factory_panel.connection_aborted";

		BlockState state1 = from.blockEntity.getBlockState();
		BlockState state2 = to.blockEntity.getBlockState();
		BlockPos diff = to.getPos()
			.subtract(from.getPos());
		Direction connectedDirection = FactoryPanelBlock.connectedDirection(state1);

		if (connectedDirection != state2.getOptionalValue(WrenchableDirectionalBlock.FACING)
			.orElse(connectedDirection))
			return "factory_panel.same_orientation";

		if (connectedDirection.getAxis()
			.choose(diff.getX(), diff.getY(), diff.getZ()) != 0)
			return "factory_panel.same_surface";

		if (!diff.closerThan(BlockPos.ZERO, 16))
			return "factory_panel.too_far_apart";

		return null;
	}

private void searchForCraftingRecipe() {
		ItemStack output = outputConfig.stack;
		if (output.isEmpty())
			return;
		if (behaviour.targetedBy.isEmpty())
			return;

		Set<Item> itemsToUse = inputConfig.stream()
			.map(b -> b.stack)
			.filter(i -> !i.isEmpty())
			.map(i -> i.getItem())
			.collect(Collectors.toSet());

		ClientLevel level = Minecraft.getInstance().level;

		availableCraftingRecipe = level.getRecipeManager()
			.getAllRecipesFor(RecipeType.CRAFTING)
			.parallelStream()
			.filter(r -> output.getItem() == r.value().getResultItem(level.registryAccess())
				.getItem())
			.filter(r -> {
				if (AllRecipeTypes.shouldIgnoreInAutomation(r))
					return false;

				Set<Item> itemsUsed = new HashSet<>();
				for (Ingredient ingredient : r.value().getIngredients()) {
					if (ingredient.isEmpty())
						continue;
					boolean available = false;
					for (BigItemStack bis : inputConfig) {
						if (!bis.stack.isEmpty() && ingredient.test(bis.stack)) {
							available = true;
							itemsUsed.add(bis.stack.getItem());
							break;
						}
					}
					if (!available)
						return false;
				}

				if (itemsUsed.size() < itemsToUse.size())
					return false;

				return true;
			})
			.findAny()
			.map(RecipeHolder::value)
			.orElse(null);
	}

@Override
	public List<Component> makeSummary(ItemStack filter) {
		List<Component> list = new ArrayList<>();

		AttributeFilterWhitelistMode whitelistMode = filter.get(AllDataComponents.ATTRIBUTE_FILTER_WHITELIST_MODE);
		list.add((whitelistMode == AttributeFilterWhitelistMode.WHITELIST_CONJ
			? CreateLang.translateDirect("gui.attribute_filter.allow_list_conjunctive")
			: whitelistMode == AttributeFilterWhitelistMode.WHITELIST_DISJ
			? CreateLang.translateDirect("gui.attribute_filter.allow_list_disjunctive")
			: CreateLang.translateDirect("gui.attribute_filter.deny_list")).withStyle(ChatFormatting.GOLD));

		int count = 0;
		List<ItemAttribute.ItemAttributeEntry> attributes = filter.getOrDefault(AllDataComponents.ATTRIBUTE_FILTER_MATCHED_ATTRIBUTES, List.of());
		for (ItemAttributeEntry attributeEntry : attributes) {
			ItemAttribute attribute = attributeEntry.attribute();
			if (attribute == null)
				continue;
			boolean inverted = attributeEntry.inverted();
			if (count > 3) {
				list.add(Component.literal("- ...")
					.withStyle(ChatFormatting.DARK_GRAY));
				break;
			}
			list.add(Component.literal("- ")
				.append(attribute.format(inverted)));
			count++;
		}

		if (count == 0)
			return Collections.emptyList();

		return list;
	}

