@MustBeInvokedByOverriders
    public void onUnload() {
        getAllTraits().forEach(MachineTrait::onMachineUnload);

        for (TickableSubscription serverTick : serverTicks) {
            serverTick.unsubscribe();
        }
        serverTicks.clear();
    }

