@SuppressWarnings("unchecked")
    public @Nullable <T extends VirtualEntry> T getEntry(EntryTypes<T> type, String name) {
        return (T) registryMap.getOrDefault(type, Collections.emptyMap()).get(name);
    }

public void addEntry(String name, VirtualEntry entry) {
        registryMap.computeIfAbsent(entry.getType(), k -> new Object2ObjectOpenHashMap<>()).put(name, entry);
    }

public <T extends VirtualEntry> Map<String, VirtualEntry> getEntries(EntryTypes<T> type) {
        return registryMap.getOrDefault(type, new Object2ObjectOpenHashMap<>());
    }

public boolean contains(EntryTypes<?> type, String name) {
        return registryMap.containsKey(type) && registryMap.get(type).containsKey(name);
    }

public void deleteEntry(EntryTypes<?> type, String name) {
        Map<String, VirtualEntry> entries = registryMap.get(type);
        if (entries != null) {
            entries.remove(name);
            if (entries.isEmpty()) {
                registryMap.remove(type);
            }
        }
    }

public void clear() {
        registryMap.clear();
    }

public boolean isEmpty() {
        return registryMap.isEmpty();
    }

@Override
    public CompoundTag serializeNBT() {
        CompoundTag tag = new CompoundTag();
        for (Map.Entry<EntryTypes<?>, Map<String, VirtualEntry>> entry : registryMap.entrySet()) {
            ListTag entriesTag = new ListTag();
            for (VirtualEntry innerEntry : entry.getValue().values()) {
                if (innerEntry.canRemove()) continue;
                entriesTag.add(innerEntry.serializeNBT());
            }
            tag.put(entry.getKey().toString(), entriesTag);
        }
        return tag;
    }

@Override
    public void deserializeNBT(CompoundTag nbt) {
        for (String entryTypeString : nbt.getAllKeys()) {
            ResourceLocation entryTypeLoc = ResourceLocation.tryParse(entryTypeString);
            if (entryTypeLoc == null) continue;
            EntryTypes<?> type = EntryTypes.fromLocation(entryTypeLoc);
            if (type == null) continue;

            Tag virtualEntries = nbt.get(entryTypeString);

            // backwards compat
            if (virtualEntries instanceof CompoundTag compoundTag) {
                for (String name : compoundTag.getAllKeys()) {
                    CompoundTag entryTag = compoundTag.getCompound(name);
                    VirtualEntry entry = type.createInstance(entryTag);
                    if (entry.canRemove()) continue;
                    addEntry(entry.getColorStr(), type.createInstance(entryTag));
                }
            } else {
                ListTag listTag = (ListTag) virtualEntries;
                for (int i = 0; i < Objects.requireNonNull(listTag).size(); i++) {
                    var entry = type.createInstance(listTag.getCompound(i));
                    if (entry.canRemove()) continue;
                    addEntry(entry.getColorStr(), entry);
                }
            }

        }
    }

private MultiblockPatternBuilder(RelativeDirection sliceDir, RelativeDirection stringDir,
                                     RelativeDirection charDir) {
        directions[0] = sliceDir;
        directions[1] = stringDir;
        directions[2] = charDir;
        RelativeDirection.validateFacingsArray(directions);
        // todo is this wanted?
        this.symbolMap.put(' ', Predicates.any());
    }

public MultiblockPatternBuilder sliceRepeatable(int minRepeats, int maxRepeats, String... slice) {
        validateSlice(slice);
        for (String s : slice) {
            for (char c : s.toCharArray()) {
                this.usedChars.add(c);
            }
        }

        if (minRepeats > maxRepeats) {
            throw new IllegalArgumentException("minRepeats must be smaller than maxRepeats");
        }
        PatternSlice ps = new PatternSlice(slice);
        ps.minRepeats = minRepeats;
        ps.maxRepeats = maxRepeats;
        slices.add(ps);
        return this;
    }

public MultiblockPatternBuilder slice(String... slice) {
        return sliceRepeatable(1, 1, slice);
    }

public MultiblockPatternBuilder startOffset(OriginOffset offset) {
        this.offset = offset;
        return this;
    }

public MultiblockPatternBuilder anchorOffset(OriginOffset anchorOffset) {
        this.anchorOffset = anchorOffset;
        return this;
    }

public static MultiblockPatternBuilder start() {
        return new MultiblockPatternBuilder(RelativeDirection.BACK, RelativeDirection.UP, RelativeDirection.RIGHT);
    }

public static MultiblockPatternBuilder start(RelativeDirection sliceDir, RelativeDirection stringDir,
                                                 RelativeDirection charDir) {
        return new MultiblockPatternBuilder(sliceDir, stringDir, charDir);
    }

public MultiblockPatternBuilder where(char symbol, MultiPredicate predicate) {
        this.symbolMap.put(symbol, predicate);
        if (predicate.isController()) centerChar = symbol;
        return this;
    }

public MultiblockPatternBuilder sliceStrategy(SliceStrategy sliceStrategy) {
        this.sliceStrategy = sliceStrategy;
        return this;
    }

public IBlockPattern build() {
        checkMissingPredicates();
        checkGlobalConstraints();
        this.dimensions[0] = slices.size();
        if (sliceStrategy == null) sliceStrategy = new BasicSliceStrategy();

        sliceStrategy.finish(dimensions, directions, slices);
        return new BlockPattern(slices.toArray(new PatternSlice[0]), sliceStrategy, dimensions,
                directions, offset, anchorOffset, symbolMap, centerChar);
    }

private void checkMissingPredicates() {
        List<Character> list = new ArrayList<>();

        for (char c : this.usedChars) {
            if (!this.symbolMap.containsKey(c)) {
                list.add(c);
            }
        }

        if (!list.isEmpty()) {
            throw new IllegalStateException("Predicates for character(s) " + COMMA_JOINER.join(list) + " are missing");
        }

        checkNullPredicates(this.symbolMap);
    }

private void checkGlobalConstraints() {
        Char2IntMap charCount = new Char2IntOpenHashMap();
        for (var slice : slices) {
            for (var string : slice.getPattern()) {
                for (char c : string) {
                    charCount.merge(c, 1, Integer::sum);
                }
            }
        }

        for (var entry : symbolMap.char2ObjectEntrySet()) {
            char symbol = entry.getCharKey();
            MultiPredicate predicate = entry.getValue();
            int maxCount = -1;
            for (var basePredicate : predicate.expand()) {
                if (basePredicate.getMaxCount() == -1) {
                    maxCount = -1;
                    break;
                }
                if (basePredicate.getMinCount() == basePredicate.getMaxCount()) {
                    if (maxCount == -1) {
                        maxCount = basePredicate.getMinCount();
                    } else {
                        maxCount += basePredicate.getMinCount();
                    }
                }
            }
            if (maxCount == -1) continue;
            if (charCount.get(symbol) > maxCount) {
                throw new IllegalArgumentException("Predicate has global max of " + maxCount + " but appears " +
                        charCount.get(symbol) + " times.");
            }
        }
    }

public void validateSlice(String[] slice) {
        if (ArrayUtils.isEmpty(slice) || StringUtils.isEmpty(slice[0]))
            throw new IllegalArgumentException("Empty pattern for slice");

        if (dimensions[2] == -1) {
            dimensions[2] = slice[0].length();
        }

        if (dimensions[1] == -1) {
            dimensions[1] = slice.length;
        }

        if (slice.length != dimensions[1]) {
            throw new IllegalArgumentException("Expected slice with height of " + dimensions[1] +
                    ", but was given one with a height of " + slice.length);
        } else {
            for (String s : slice) {
                if (s.length() != dimensions[2]) {
                    throw new IllegalArgumentException(
                            "Not all rows in the given slice are the correct width (expected " + dimensions[2] +
                                    ", found one with " + s.length() + ")");
                }
            }
        }
    }

public static void autobuild(ServerPlayer player, ItemStack item, MultiblockMachineDefinition definition,
                                 MultiblockControllerMachine controller, Map<BlockPos, BlockInfo> blocksToPlace,
                                 AbstractStructureHelper structureHelper, boolean isFlipped) {
        Long2ObjectOpenHashMap<BlockState> alreadyValidPlaced = new Long2ObjectOpenHashMap<>();
        Long2ObjectOpenHashMap<BlockState> replaceableBlocks = new Long2ObjectOpenHashMap<>();
        Long2ObjectOpenHashMap<BlockState> canNotPlaceBlocks = new Long2ObjectOpenHashMap<>();

        Level level = player.level();

        Block controllerBlock = controller.getDefinition().getBlock();
        BlockPos schemaControllerPos = BlockPos.ZERO;
        for (var entry : blocksToPlace.entrySet()) {
            if (entry.getValue().getBlockState().is(controllerBlock)) {
                schemaControllerPos = entry.getKey();
                break;
            }
        }

        BlockPos controllerOffset = controller.getBlockPos().subtract(schemaControllerPos);

        PredicateContext cxt = new PredicateContext(null);
        cxt.updateLevel(level);
        int checkedBlocks = 0;
        for (var entry : blocksToPlace.entrySet()) {
            BlockPos pos = entry.getKey().offset(controllerOffset);
            var blockState = level.getBlockState(pos);

            var predicate = structureHelper.getPredicateFromPos(
                    definition.getStructurePatterns().get(DEFAULT_STRUCTURE).get(),
                    entry.getKey(), controller.getFrontFacing(), controller.getUpwardsFacing(), isFlipped);

            cxt.updatePos(pos);
            var innerPredicate = predicate.getPredicateAtPos(cxt);
            if (innerPredicate.hasMatched()) {
                alreadyValidPlaced.put(pos.asLong(), blockState);
            } else {
                if (blockState.canBeReplaced()) {
                    replaceableBlocks.put(pos.asLong(), entry.getValue().getBlockState());
                    checkedBlocks++;
                } else {
                    canNotPlaceBlocks.put(pos.asLong(), blockState);
                }
            }
            if (checkedBlocks > 32) {
                break;
            }
        }

        // Step 1. Making the "what we want" list
        Map<Item, Integer> whatWeWant = new Object2IntArrayMap<>();
        for (var entry : replaceableBlocks.long2ObjectEntrySet()) {
            if (entry.getValue().isAir()) continue;
            whatWeWant.merge(entry.getValue().getBlock().asItem(), 1, Integer::sum);
        }

        // Step 2. Try to fetch from inventory
        Map<Item, Integer> whatWeHave = new Object2IntArrayMap<>();
        for (var entry : whatWeWant.entrySet()) {
            Item desiredItem = entry.getKey();
            int desiredAmount = entry.getValue();
            var slotIndex = player.getInventory().findSlotMatchingItem(new ItemStack(desiredItem));
            if (slotIndex == -1) continue;
            var playerSlotStack = player.getInventory().getItem(slotIndex);
            int toDeduct = Math.min(playerSlotStack.getCount(), desiredAmount);
            playerSlotStack.shrink(toDeduct);
            whatWeHave.put(desiredItem, toDeduct);
        }

        // Step 2a. Calculate remaining items
        Map<Item, Integer> whatWeDontHave = new Object2IntArrayMap<>();
        for (var entry : whatWeWant.entrySet()) {
            Item item1 = entry.getKey();
            int count = whatWeHave.getOrDefault(item1, 0);
            if (count < entry.getValue()) {
                whatWeDontHave.put(item1, entry.getValue() - count);
            }
        }

        // Step 2b. Try to fetch from AE
        Map<Item, Integer> whatWeHaveAE = new Object2IntArrayMap<>();
        if (GTCEu.Mods.isAE2Loaded()) {
            whatWeHaveAE = AEWrapper.tryGrid(whatWeDontHave, level, item, player);
        }

        printBlockList(Component.translatable("gtceu.autobuild.ae_blocks").withStyle(ChatFormatting.AQUA), whatWeHaveAE,
                player);

        Map<Item, Integer> whatWePlaced = new Object2IntArrayMap<>();
        BlockState lastPlaced = null;
        // Step 3. Place what was fetched
        for (var entry : replaceableBlocks.long2ObjectEntrySet()
                .stream()
                .sorted(Comparator.comparingLong(Long2ObjectMap.Entry::getLongKey))
                .toList()) {
            var blockState = entry.getValue();
            BlockPos pos = BlockPos.of(entry.getLongKey());
            if (blockState.isAir()) {
                level.setBlockAndUpdate(pos, blockState);
                continue;
            }
            var blocksLeft = whatWeHave.merge(blockState.getBlock().asItem(), -1, Integer::sum);
            if (blocksLeft < 0) {
                blocksLeft = whatWeHaveAE.merge(blockState.getBlock().asItem(), -1, Integer::sum);
                if (blocksLeft < 0) continue;
            }
            ItemStack placedStack = new ItemStack(blockState.getBlock().asItem());
            if (!placeAsPlayer(player, pos, blockState, placedStack)) {
                player.getInventory().placeItemBackInInventory(placedStack);
                continue;
            }
            whatWeWant.merge(blockState.getBlock().asItem(), -1, Integer::sum);
            whatWePlaced.merge(blockState.getBlock().asItem(), 1, Integer::sum);
            lastPlaced = blockState;
        }
        if (lastPlaced != null) {
            SoundType soundType = lastPlaced.getSoundType();
            level.playSound(null, player.blockPosition(), soundType.getPlaceSound(), SoundSource.BLOCKS,
                    (soundType.getVolume() + 1.0F) / 2.0F, soundType.getPitch() * 0.8F);
        }

        printBlockList(Component.translatable("gtceu.autobuild.placed_blocks").withStyle(ChatFormatting.GREEN),
                whatWePlaced, player);
        printBlockList(Component.translatable("gtceu.autobuild.missing_blocks").withStyle(ChatFormatting.RED),
                whatWeWant, player);

        if (!canNotPlaceBlocks.isEmpty()) player.displayClientMessage(
                Component.translatable("gtceu.autobuild.unplaced_blocks").withStyle(ChatFormatting.RED), false);
        if (!canNotPlaceBlocks.isEmpty())
            GTNetwork.sendToPlayer(player, new SPacketAutobuildHighlight(canNotPlaceBlocks.keySet().toLongArray()));
    }

