private List<BakedQuad> renderPartOverrides(MachineModel controllerModel, MultiblockControllerMachine controller,
                                                List<BakedQuad> quads, MultiblockPartMachine part,
                                                Direction frontFacing,
                                                @Nullable Direction side, RandomSource rand,
                                                ModelData modelData, @Nullable RenderType renderType) {
        var overrides = controllerModel.textureOverrides;

        List<BakedQuad> renderQuads = new LinkedList<>();
        for (var render : controllerModel.getDynamicRenders()) {
            if (render instanceof IControllerModelRenderer controllerRenderer) {
                controllerRenderer.renderPartModel(renderQuads, controller, part, frontFacing, side,
                        rand, modelData, renderType);
                if (!renderQuads.isEmpty()) {
                    // assume the renderer drew the base model, and replace the override textures with empty ones
                    overrides = new HashMap<>();
                    for (String key : this.replaceableTextures) {
                        overrides.put(key, blankSprite);
                    }
                    break;
                }

            }
        }
        if (overrides.isEmpty()) {
            quads.addAll(renderQuads);
            return quads;
        }

        // parse out valid overrides
        Map<String, String> remaps = new IdentityHashMap<>();
        final TextureAtlasSprite missingno = Minecraft.getInstance().getTextureAtlas(InventoryMenu.BLOCK_ATLAS)
                .apply(MissingTextureAtlasSprite.getLocation());
        final Map<String, TextureAtlasSprite> finalOverrides = overrides;
        overrides = finalOverrides.keySet().stream()
                .flatMap(key -> {
                    var remapped = remapReplaceableTextures(key);
                    for (String r : remapped) {
                        remaps.put(r, key);
                    }
                    return remapped.stream();
                })
                .collect(Collectors.toMap(Function.identity(),
                        key -> finalOverrides.getOrDefault(remaps.get(key), missingno),
                        (o1, o2) -> o1));

        // actually process the sprite replacement
        quads = TextureOverrideModel.retextureQuads(quads, overrides);
        quads.addAll(renderQuads);
        return quads;
    }

public static void renderBlockHighlight(PoseStack poseStack, Camera camera, BlockHitResult target,
                                            MultiBufferSource multiBufferSource, float partialTick) {
        var mc = Minecraft.getInstance();
        var level = mc.level;
        var player = mc.player;
        if (level != null && player != null) {
            ItemStack held = player.getMainHandItem();
            BlockPos blockPos = target.getBlockPos();
            Vector3fc blockCenter = blockPos.getCenter().toVector3f();

            Set<GTToolType> toolType = ToolHelper.getToolTypes(held);
            BlockEntity blockEntity = level.getBlockEntity(blockPos);

            Vec3 cameraPos = camera.getPosition();
            // draw tool grid highlight
            if ((!toolType.isEmpty()) || (held.isEmpty() && player.isShiftKeyDown())) {
                IToolGridHighlight gridHighlight = null;
                if (blockEntity instanceof IToolGridHighlight highLight) {
                    gridHighlight = highLight;
                } else if (level.getBlockState(blockPos).getBlock() instanceof IToolGridHighlight highLight) {
                    gridHighlight = highLight;
                } else if (toolType.contains(GTToolType.WRENCH)) {
                    var behavior = CustomBlockRotations.getCustomRotation(level.getBlockState(blockPos).getBlock());
                    if (behavior != null && behavior.showGrid()) {
                        gridHighlight = new IToolGridHighlight() {

                            @Override
                            public @Nullable UITexture sideTips(@NotNull Player player, @NotNull BlockPos pos,
                                                                @NotNull BlockState state,
                                                                @NotNull Set<GTToolType> toolTypes,
                                                                ItemStack held, @NotNull Direction side) {
                                return behavior.showSideTip(state, side) ? GTGuiTextures.TOOL_FRONT_FACING_ROTATION :
                                        null;
                            }
                        };
                    }
                }
                if (gridHighlight == null) {
                    return;
                }
                BlockState state = level.getBlockState(blockPos);
                poseStack.pushPose();
                if (gridHighlight.shouldRenderGrid(player, blockPos, state, held, toolType)) {
                    final IToolGridHighlight finalGridHighlight = gridHighlight;
                    drawGridOverlays(poseStack, multiBufferSource, cameraPos, target,
                            side -> finalGridHighlight.sideTips(player, blockPos, state, toolType, held, side));
                } else {
                    Direction facing = target.getDirection();
                    var texture = gridHighlight.sideTips(player, blockPos, state, toolType, held, facing);
                    if (texture != null) {
                        RenderSystem.disableDepthTest();
                        RenderSystem.enableBlend();
                        RenderSystem.defaultBlendFunc();

                        poseStack.translate(facing.getStepX() * 0.01f, facing.getStepY() * 0.01f,
                                facing.getStepZ() * 0.01f);
                        poseStack.translate(-cameraPos.x(), -cameraPos.y(), -cameraPos.z());

                        RenderUtil.moveToFace(poseStack, blockCenter, facing);
                        if (facing.getAxis() == Direction.Axis.Y) {
                            RenderUtil.rotateToFace(poseStack, facing, Direction.SOUTH);
                        } else {
                            RenderUtil.rotateToFace(poseStack, facing, Direction.NORTH);
                        }
                        poseStack.scale(1f / 16, 1f / 16, 0);
                        poseStack.translate(-8, -8, 0);

                        drawOverlayTexture(poseStack, multiBufferSource, texture, 0xffffffff,
                                4, 4, 8, 8);

                        RenderSystem.disableBlend();
                        RenderSystem.enableDepthTest();
                    }
                }
                poseStack.popPose();
                return;
            }

            // draw cover grid highlight
            ICoverable coverable = GTCapabilityHelper.getCoverable(level, blockPos, target.getDirection());
            if (coverable != null && CoverPlaceBehavior.isCoverBehaviorItem(held, coverable::hasAnyCover,
                    coverDef -> ICoverable.canPlaceCover(coverDef, coverable))) {
                poseStack.pushPose();

                drawGridOverlays(poseStack, multiBufferSource, cameraPos, target,
                        side -> coverable.hasCover(side) ? null : GTGuiTextures.TOOL_ATTACH_COVER);

                poseStack.popPose();
            }

            // draw pipe connection grid highlight
            var pipeType = held.getItem() instanceof PipeBlockItem pipeBlockItem ? pipeBlockItem.getBlock().pipeType :
                    null;
            if (pipeType instanceof IPipeType<?> type && blockEntity instanceof PipeBlockEntity<?, ?> pipeBlockEntity &&
                    pipeBlockEntity.getPipeType().type().equals(type.type())) {
                poseStack.pushPose();

                drawGridOverlays(poseStack, multiBufferSource, cameraPos, target,
                        side -> level.isEmptyBlock(blockPos.relative(side)) ?
                                pipeBlockEntity.getPipeTexture(true) : null);

                poseStack.popPose();
            }
        }
    }

@Override
    @OnlyIn(Dist.CLIENT)
    public void renderCover(List<BakedQuad> quads, @Nullable Direction cullFace, RandomSource rand,
                            CoverBehavior coverBehavior, BlockPos pos, BlockAndTintGetter level,
                            ModelData modelData, @Nullable RenderType renderType) {
        if (!(coverBehavior instanceof FacadeCover facadeCover)) {
            return;
        }
        BlockState facadeState = facadeCover.getFacadeState();
        if (facadeState.getRenderShape() != RenderShape.MODEL) {
            return;
        }

        BakedModel facadeModel = RenderUtil.getModelForState(facadeState);
        if (facadeModel.isCustomRenderer()) {
            return;
        }

        ModelData facadeData = facadeModel.getModelData(level, pos, facadeState, modelData);
        if (renderType != null && !facadeModel.getRenderTypes(facadeState, rand, facadeData).contains(renderType)) {
            return;
        }

        Direction attachedSide = coverBehavior.attachedSide;
        if (cullFace != attachedSide && (cullFace != null || !coverBehavior.coverHolder.shouldRenderBackSide())) {
            return;
        }

        MeshBuilder meshBuilder = MeshBuilder.getInstance();
        var emitter = meshBuilder.getEmitter();

        QuadTransform clamper = FACADE_PLANE_TRANSFORMERS.get(attachedSide);
        QuadReInterpolator interpolator = new QuadReInterpolator();
        BlockColors blockColors = Minecraft.getInstance().getBlockColors();

        // always add unculled faces
        Map<Direction, List<BakedQuad>> facadeQuads = new IdentityHashMap<>();
        facadeQuads.put(null, facadeModel.getQuads(facadeState, null, rand, facadeData, renderType));
        if (cullFace != null) {
            // if a cullface is given, only draw that + unculled faces
            facadeQuads.put(cullFace, facadeModel.getQuads(facadeState, cullFace, rand, facadeData, renderType));
        } else {
            // add all culled faces if no cullface is given
            for (Direction face : GTUtil.DIRECTIONS) {
                facadeQuads.put(face, facadeModel.getQuads(facadeState, face, rand, facadeData, renderType));
            }
        }
        // clamp all 'facaded' quads into a box and bake their tint color into the vertices
        for (var entry : facadeQuads.entrySet()) {
            Direction face = entry.getKey();
            List<BakedQuad> cullfaceQuads = entry.getValue();
            if (cullfaceQuads.isEmpty()) continue;

            for (BakedQuad quad : cullfaceQuads) {
                // skip quads that aren't oriented correctly
                if (quad.getDirection() != attachedSide && (coverBehavior.shouldRenderPlate() ||
                        !coverBehavior.coverHolder.shouldRenderBackSide())) {
                    continue;
                }

                emitter.fromVanilla(quad, face);
                interpolator.setInputQuad(emitter);

                // bake the quad's colors into its vertices
                if (emitter.tintIndex() != -1) {
                    // if the quad has a tint index set, bake the tint into the vertex
                    int color = blockColors.getColor(facadeState, level, pos, quad.getTintIndex());
                    QuadTinter tinter = new QuadTinter(color);
                    tinter.transform(emitter);
                }

                // clamp the quad's vertices into the facade plane
                clamper.transform(emitter);
                // fix the quad's UVs based on the original & clamped vertices
                interpolator.transform(emitter);

                quads.add(emitter.toBlockBakedQuad());
                emitter.emit();
            }
        }
    }

@Override
        public List<BakedQuad> getQuads(@Nullable BlockState state, @Nullable Direction cullFace,
                                        RandomSource rand, ModelData modelData, @Nullable RenderType renderType) {
            if (this.quads.containsKey(cullFace)) {
                return this.quads.get(cullFace);
            }
            List<BakedQuad> quads = new LinkedList<>();
            this.quads.put(cullFace, quads);

            if (facadeState.getRenderShape() != RenderShape.MODEL) {
                return quads;
            }
            BakedModel facadeModel = RenderUtil.getModelForState(facadeState);
            if (facadeModel.isCustomRenderer()) {
                return quads;
            }

            ModelData facadeData = modelData.get(GTModelProperties.CHILD_MODEL_DATA);
            if (facadeData == null) facadeData = ModelData.EMPTY;

            MeshBuilder meshBuilder = MeshBuilder.getInstance();
            var emitter = meshBuilder.getEmitter();

            QuadTransform clamper = FACADE_PLANE_TRANSFORMERS.get(Direction.NORTH);
            QuadReInterpolator interpolator = new QuadReInterpolator();
            ItemColors itemColors = Minecraft.getInstance().getItemColors();

            for (var model : facadeModel.getRenderPasses(this.facadeStack, true)) {
                if (renderType != null && !model.getRenderTypes(facadeState, rand, facadeData).contains(renderType)) {
                    continue;
                }

                // always add unculled faces
                Map<Direction, List<BakedQuad>> facadeQuads = new IdentityHashMap<>();
                facadeQuads.put(null, model.getQuads(this.facadeState, null, rand, facadeData, renderType));
                if (cullFace != null) {
                    // if a cullface is given, only draw that + unculled faces
                    facadeQuads.put(cullFace, model.getQuads(this.facadeState, cullFace, rand, facadeData, renderType));
                } else {
                    // add all culled faces if no cullface is given
                    for (Direction face : GTUtil.DIRECTIONS) {
                        facadeQuads.put(face, model.getQuads(this.facadeState, face, rand, facadeData, renderType));
                    }
                }

                // clamp all 'facaded' quads into a box and bake their tint color into the vertices
                for (var entry : facadeQuads.entrySet()) {
                    Direction face = entry.getKey();
                    List<BakedQuad> cullfaceQuads = entry.getValue();
                    if (cullfaceQuads.isEmpty()) continue;

                    for (BakedQuad quad : cullfaceQuads) {
                        // skip quads that aren't oriented correctly
                        if (quad.getDirection() != Direction.NORTH) {
                            continue;
                        }

                        emitter.fromVanilla(quad, face);
                        interpolator.setInputQuad(emitter);

                        // bake the quad's colors into its vertices
                        if (emitter.tintIndex() != -1) {
                            // if the quad has a tint index set, bake the tint into the vertex
                            int color = itemColors.getColor(this.facadeStack, emitter.tintIndex());
                            QuadTinter tinter = new QuadTinter(color);
                            tinter.transform(emitter);
                        }

                        // clamp the quad's vertices into the facade plane
                        clamper.transform(emitter);
                        // fix the quad's UVs based on the original & clamped vertices
                        interpolator.transform(emitter);

                        quads.add(emitter.toBlockBakedQuad());
                        emitter.emit();
                    }
                }
            }

            return quads;
        }

