                    case "itemPull" -> {
                        channel = "EILink#" + channel;
                        if (!ender.hasEntry(owner, EntryTypes.ENDER_ITEM, channel))
                            return MultiLineComponent.empty();
                        IItemHandler items = ender.getEntry(owner, EntryTypes.ENDER_ITEM, channel).getHandler();
                        if (ctx.itemStackHandler() != null)
                            GTTransferUtils.transferItemsFiltered(items, ctx.itemStackHandler(), stack -> true, 1);
                        else throw new NotSupportedException();
                        return MultiLineComponent.empty();
                    }
                    case "itemPush" -> {
                        channel = "EILink#" + channel;
                        if (!ender.hasEntry(owner, EntryTypes.ENDER_ITEM, channel))
                            return MultiLineComponent.empty();
                        IItemHandler items = ender.getEntry(owner, EntryTypes.ENDER_ITEM, channel).getHandler();
                        if (ctx.itemStackHandler() != null)
                            GTTransferUtils.transferItemsFiltered(ctx.itemStackHandler(), items, stack -> true, 1);
                        else throw new NotSupportedException();
                        return MultiLineComponent.empty();
                    }
                    case "fluid" -> {
                        channel = "EFLink#" + channel;
                        if (!ender.hasEntry(owner, EntryTypes.ENDER_FLUID, channel))
                            return MultiLineComponent.literal(0);
                        return MultiLineComponent.literal(
                                ender.getEntry(owner, EntryTypes.ENDER_FLUID, channel).getFluidTank().getFluidAmount());
                    }
                    default -> throw new InvalidArgsException();
                }
            }

@Override
            public MultiLineComponent apply(PlaceholderContext ctx,
                                            List<MultiLineComponent> args) throws PlaceholderException {
                if (ctx.pos() == null) throw new NoTargetException();
                BlockEntity blockEntity = ctx.level().getBlockEntity(ctx.pos());
                if (blockEntity == null) return MultiLineComponent.empty();
                Tag tag = blockEntity.saveWithFullMetadata();
                if (tag instanceof CompoundTag compoundTag && compoundTag.contains("cover")) {
                    CompoundTag coverTag = compoundTag.getCompound("cover");
                    if (coverTag.contains(ctx.side().getName())) {
                        CompoundTag cover = coverTag.getCompound(ctx.side().getName()).getCompound("payload")
                                .getCompound("d");
                        cover.putString("text", "[REMOVED]");
                    }
                }
                for (MultiLineComponent arg : args) {
                    if (!(tag instanceof CompoundTag compoundTag)) return MultiLineComponent.empty();
                    tag = compoundTag.get(arg.toString());
                }
                return tag == null ? MultiLineComponent.empty() : MultiLineComponent.literal(tag.toString());
            }

public static @NotNull ModifierFunction hatchParallel(@NotNull MetaMachine machine, @NotNull GTRecipe recipe) {
        if (machine instanceof MultiblockControllerMachine controller && controller.isFormed()) {
            int parallels = controller.getParallelHatch()
                    .map(hatch -> ParallelLogic.getParallelAmount(machine, recipe, hatch.getCurrentParallel()))
                    .orElse(1);

            if (parallels == 1) return ModifierFunction.IDENTITY;
            return ModifierFunction.builder()
                    .modifyAllContents(ContentModifier.multiplier(parallels))
                    .eutMultiplier(parallels)
                    .parallels(parallels)
                    .build();
        }
        return ModifierFunction.IDENTITY;
    }

public static @NotNull ModifierFunction ebfOverclock(@NotNull MetaMachine machine, @NotNull GTRecipe recipe) {
        if (!(machine instanceof CoilWorkableElectricMultiblockMachine coilMachine)) {
            return RecipeModifier.nullWrongType(CoilWorkableElectricMultiblockMachine.class, machine);
        }

        int blastFurnaceTemperature = coilMachine.getCoilType().getCoilTemperature() +
                (100 * Math.max(0, coilMachine.getTier() - GTValues.MV));
        int recipeTemp = recipe.data.getInt("ebf_temp");
        if (!recipe.data.contains("ebf_temp") || recipeTemp > blastFurnaceTemperature) {
            return ModifierFunction.cancel(Component.translatable("gtceu.recipe_modifier.coil_temperature_too_low"));
        }

        if (RecipeHelper.getRecipeEUtTier(recipe) > coilMachine.getTier()) {
            return ModifierFunction.cancel(Component.translatable("gtceu.recipe_modifier.insufficient_voltage"));
        }

        var discount = ModifierFunction.builder()
                .eutMultiplier(getCoilEUtDiscount(recipeTemp, blastFurnaceTemperature))
                .build();

        OverclockingLogic logic = (p, v) -> OverclockingLogic.heatingCoilOC(p, v, recipeTemp, blastFurnaceTemperature);
        var oc = logic.getModifier(machine, recipe, coilMachine.getOverclockVoltage());

        return oc.compose(discount);
    }

