                        syncManager.syncedPanel(
                                "slot_dialog_" + id,
                                true,
                                (syncManager1, panelHandler1) -> new SimpleDialog<>(
                                        "slot_number_dialog_" + id,
                                        new TextFieldWidget().setNumbers(1, component.getDataItems().getSlots()),
                                        w -> Integer.parseInt(w.getText()),
                                        Text.lang("gtceu.central_monitor.gui.data_slot")).resultConsumer(slot -> {
                                            group.setDataSlot(slot - 1);
                                            groupSync.setValue(groups, true, false);
                                        }).draggable(true).size(160, 80));
                IntSupplier colorSupplier = () -> {
                    if (component == null) return 0;
                    boolean inGroup = group.contains(component.getComponentPos());
                    BlockPos target = group.getTargetRaw();
                    boolean isTarget = target != null && target.asLong() == component.getComponentPos().asLong();
                    if (inGroup && isTarget) return 0xFFFF00FF;
                    else if (inGroup) return 0xFFFF0000;
                    else if (isTarget) return 0xFF0000FF;
                    else return 0;
                };
                curRow.add(new ButtonWidget<>()
                        .margin(1)
                        .background(texture, new BorderDrawable(colorSupplier, 1), Text.dynamic(() -> {
                            if (component == null || component.getDataItems() == null) return Component.empty();
                            BlockPos target = group.getTargetRaw();
                            boolean isTarget = target != null &&
                                    target.asLong() == component.getComponentPos().asLong();
                            if (isTarget) return Component.literal(String.valueOf(group.getDataSlot() + 1));
                            else return Component.empty();
                        }))
                        .hoverBackground(texture, new BorderDrawable(() -> colorSupplier.getAsInt() | 0x222222, 1))
                        .syncHandler(new InteractionSyncHandler()
                                .setOnMousePressed(mouseData -> {
                                    if (component == null) return;
                                    int button = mouseData.mouseButton();
                                    if (button == InputConstants.MOUSE_BUTTON_LEFT) {
                                        if (!component.isMonitor()) return;
                                        if (group.contains(component.getComponentPos())) {
                                            group.remove(component.getComponentPos());
                                        } else {
                                            group.add(component.getComponentPos());
                                        }
                                    } else if (button == InputConstants.MOUSE_BUTTON_RIGHT) {
                                        group.setTarget(component.getComponentPos());
                                        groupSync.setValue(groups, true, false);
                                        if (slotDialogHandler != null) {
                                            slotDialogHandler.openPanel();
                                        }
                                    }
                                    groupSync.setValue(groups, true, false);
                                })));
            }
            matrixWidth = Math.max(matrixWidth, curRow.size() * 20);
        }
        int matrixHeight = matrix.size() * 20;
        BoolValue moduleChanged = new BoolValue(false);
        return new ModularPanel<>("editor_%d_panel".formatted(groupIndex))
                .closeOnOutOfBoundsClick(true)
                .width(Math.max(matrixWidth, 150))
                .height(matrixHeight + 60)
                .excludeAreaInRecipeViewer()
                .child(Flow.column()
                        .padding(10)
                        .child(new TextWidget<>(Text.lang("gtceu.central_monitor.gui.group_editor")))
                        .child(Flow.row()
                                .height(20)
                                .child(new TextWidget<>(Text.lang("gtceu.central_monitor.gui.group_name"))
                                        .paddingRight(4))
                                .child(new TextFieldWidget()
                                        .value(SyncHandlers.string(group::getName, s -> {
                                            group.setName(s);
                                            groupSync.setValue(groups, true, false);
                                        }).allowC2S()))
                                .child(new ItemSlot()
                                        .slot(group.getItemStackHandler(), 0)
                                        .name("module_slot")
                                        .slot(new ModularSlot(group.getItemStackHandler(), 0)
                                                .changeListener((item, amount, client, init) -> {
                                                    if (!init)
                                                        groupSync.setValue(groups, true, false);
                                                })))
                                .child(new ButtonWidget<>()
                                        .overlay(GuiTextures.EDIT)
                                        .setEnabledIf(w -> !group.getItemStackHandler().getStackInSlot(0).isEmpty())
                                        .addTooltipLine(Text.lang("gtceu.gui.central_monitor.module_editor_button"))
                                        .onMousePressed((context, button) -> {
                                            if (moduleEditor != null && !moduleChanged.getValue())
                                                moduleEditor.openPanel();
                                            return true;
                                        })))
                        .child(new Grid().grid(matrix).leftRel(0.5f).size(matrixWidth, matrixHeight)));
    }

@Override
    public void execute(NetworkEvent.Context context) {
        Level level = LogicalSidedProvider.CLIENTWORLD.get(context.getDirection().getReceptionSide())
                .or(() -> Optional.ofNullable(context.getSender()).map(ServerPlayer::level))
                .orElse(null);
        if (level == null) return;

        MetaMachine machine = MetaMachine.getMachine(level, pos);
        if (machine instanceof CentralMonitorMachine centralMonitor) {
            IItemHandlerModifiable itemHandler = centralMonitor.getMonitorGroups().get(monitorGroupId)
                    .getItemStackHandler();
            if (ItemStack.isSameItem(itemHandler.getStackInSlot(0), stack)) {
                itemHandler.setStackInSlot(0, stack);
            }
        }
    }

private ItemStack distributeEqually(List<ItemRoutePath> routePaths, ItemStack stack, boolean simulate,
                                        InsertionMode mode) {
        // Since atomic mode cannot split the given itemstack over multiple destinations, we just cycle the destinations
        // for it
        if (mode == InsertionMode.ATOMIC) {
            routePaths.sort(Comparator.comparingInt(inv -> didTransferTo(inv, simulate)));
            return insertOrdered(routePaths, stack, simulate, InsertionMode.ATOMIC, true);
        }

        List<EnhancedRoundRobinData> transferred = new ArrayList<>();
        IntList steps = new IntArrayList();
        int min = Integer.MAX_VALUE;
        ItemStack simStack;

        // find inventories that are not full and get the amount that was inserted in total
        for (ItemRoutePath inv : routePaths) {
            simStack = stack.copy();
            int ins = stack.getCount() - insertIntoTarget(inv, simStack, true, true).getCount();
            if (ins <= 0) continue;

            int didTransfer = didTransferTo(inv, simulate);
            EnhancedRoundRobinData data = new EnhancedRoundRobinData(inv, ins, didTransfer);
            transferred.add(data);

            min = Math.min(min, didTransfer);

            if (!steps.contains(didTransfer)) {
                steps.add(didTransfer);
            }
        }

        if (transferred.isEmpty() || steps.isEmpty()) {
            return stack;
        }

        if (!simulate && min < Integer.MAX_VALUE) {
            // min is already multiplied by the transferred stacks' max size factors
            decrementBy(min);
        }

        transferred.sort(Comparator.comparingInt(data -> data.transferred));
        steps.sort(Integer::compare);

        if (transferred.get(0).transferred != steps.getInt(0)) {
            return stack;
        }

        int amount = stack.getCount();
        int c = amount / transferred.size();
        int m = amount % transferred.size();
        List<EnhancedRoundRobinData> transferredCopy = new ArrayList<>(transferred);
        int nextStep = steps.removeInt(0);

        // equally distribute items over all inventories
        // it takes into account how much was inserted in total
        // f.e. if inv1 has 2 inserted and inv2 has 6 inserted, it will first try to insert 4 into inv1 so that both
        // have 6 and then it will distribute the rest equally
        outer:
        while (amount > 0 && !transferredCopy.isEmpty()) {
            Iterator<EnhancedRoundRobinData> iterator = transferredCopy.iterator();
            while (iterator.hasNext()) {
                EnhancedRoundRobinData data = iterator.next();
                if (nextStep >= 0 && data.transferred >= nextStep)
                    break;

                int toInsert;
                if (nextStep <= 0) {
                    if (amount <= m) {
                        // break outer;
                        toInsert = 1;
                    } else {
                        toInsert = Math.min(c, amount);
                    }
                } else {
                    toInsert = Math.min(amount, nextStep - data.transferred);
                }
                if (data.toTransfer + toInsert >= data.maxInsertable) {
                    data.toTransfer = data.maxInsertable;
                    iterator.remove();
                } else {
                    data.toTransfer += toInsert;
                }

                data.transferred += toInsert;

                if ((amount -= toInsert) == 0) {
                    break outer;
                }
            }

            for (EnhancedRoundRobinData data : transferredCopy) {
                if (data.transferred < nextStep)
                    continue outer;
            }
            if (steps.isEmpty()) {
                if (nextStep >= 0) {
                    c = amount / transferredCopy.size();
                    m = amount % transferredCopy.size();
                    nextStep = -1;
                }
            } else {
                nextStep = steps.removeInt(0);
            }
        }

        int inserted = 0;

        // finally actually insert the item
        for (EnhancedRoundRobinData data : transferred) {
            ItemStack toInsert = stack.copy();
            toInsert.setCount(data.toTransfer);
            ItemStack ins = insertIntoTarget(data.routePath, toInsert, simulate, false);
            int insCount = data.toTransfer - ins.getCount();

            inserted += ins.getCount();
            if (insCount > 0) transferTo(data.routePath, simulate, ins.copyWithCount(insCount));
        }

        ItemStack remainder = stack.copy();
        remainder.shrink(inserted);
        return remainder;
    }

private int didTransferTo(ItemRoutePath handler, boolean simulate) {
        if (simulate) {
            return simulatedTransfersGlobalRoundRobin.getOrDefault(handler.toFacingPos(), 0);
        } else {
            return pipe.getTransferredGlobalRoundRobin().getOrDefault(handler.toFacingPos(), 0);
        }
    }

