public static ItemStack loadItemStack(CompoundTag compoundTag) {
        try {
            Item item = BuiltInRegistries.ITEM.get(ResourceLocation.parse(compoundTag.getString("id")));
            int count = compoundTag.getInt("Count");
            ItemStack stack = new ItemStack(item, count);
            if (compoundTag.contains("tag", Tag.TAG_COMPOUND)) {
                stack.setTag(compoundTag.getCompound("tag"));
                if (stack.getTag() != null) {
                    stack.getItem().verifyTagAfterLoad(stack.getTag());
                }
            }

            if (stack.isDamageableItem()) {
                stack.setDamageValue(stack.getDamageValue());
            }
            return stack;
        } catch (RuntimeException var2) {
            GTCEu.LOGGER.debug("Tried to load invalid item: {}", compoundTag, var2);
            return ItemStack.EMPTY;
        }
    }

@Nullable
    public static ResearchItem readResearchId(@NotNull ItemStack stack) {
        CompoundTag compound = stack.getTag();
        if (!hasResearchTag(compound)) return null;

        CompoundTag researchCompound = compound.getCompound(RESEARCH_NBT_TAG);
        return ResearchItem.CODEC.parse(NbtOps.INSTANCE, researchCompound).result().orElse(null);
    }

private static boolean hasResearchTag(@Nullable CompoundTag compound) {
        if (compound == null || compound.isEmpty()) return false;
        return compound.contains(RESEARCH_NBT_TAG, Tag.TAG_COMPOUND);
    }

@Override
            public boolean matches(Set<String> input) {
                if (value == null || value.isEmpty()) return false;
                if (value.equals("$") && input.isEmpty()) return true;
                if (!value.contains(":") && !value.startsWith("*")) {
                    value = "forge:" + value;
                }

                String val = quote(value);
                return input.stream().anyMatch(inp -> Pattern.matches(val, inp));
            }

private String quote(String str) {
                if (str.contains("*")) {
                    var idx = str.indexOf("*");
                    if (idx == str.length() - 1) {
                        return quote(str.substring(0, idx)) + ".*";
                    } else {
                        return quote(str.substring(0, idx)) + ".*" + quote(str.substring(idx + 1));
                    }
                }

                return Pattern.quote(str);
            }

public static void fixTraitTags(MetaMachine machine, CompoundTag tag) {
        if (!tag.contains("traitHolder")) {
