public static void fixBatterySlotTag(MetaMachine machine, CompoundTag tag) {
        if (tag.contains("chargerInventory")) {
            var newTag = new CompoundTag();
            newTag.put("storage", Objects.requireNonNull(tag.get("chargerInventory")));

            putTraitTag(machine, tag, BatterySlotTrait.class, "batterySlot", newTag);
        }
    }

public static void fixProgrammedCircutTag(MetaMachine machine, CompoundTag tag) {
        if (tag.contains("circuitInventory")) {
            var oldData = tag.getCompound("circuitInventory");

            putTraitTag(machine, tag, ProgrammableCircuitSlotTrait.class, "circuitSlot", oldData);
        }
    }

public static Tag stripLDLibPayloadWrapper(Tag t) {
        if (!(t instanceof CompoundTag tag)) return t;
        if (tag.contains("p") && tag.contains("t")) {
            return tag.getCompound("p");
        }
        if (tag.contains("t", Tag.TAG_COMPOUND)) {
            return tag.getCompound("t").getCompound("p");
        }
        return tag;
    }

@GameTest(template = "empty", batch = "GTRecipeLookup")
    public static void recipeLookupCustomCountCanHandleTest(GameTestHelper helper) {
        var ingredients = createIngredients(new ItemStack(Items.CHERRY_WOOD, 16));
        // Do a recipe check with a condition that requires at least 4 ingredients in the inputs
        // The recipe has 8, so this should succeed
        GTRecipe resultRecipe = DB.find(ingredients,
                recipe -> recipe.inputs
                        .getOrDefault(ItemRecipeCapability.CAP, List.of())
                        .stream()
                        .allMatch(content -> ((SizedIngredient) content.content()).getAmount() > 4));
        helper.assertTrue(SMELT_CHERRY_WOOD.equals(resultRecipe),
                "GT Recipe should be smelt_cherry_wood, instead was " + resultRecipe);

        // Do a recipe check with a condition that requires at least 32 ingredients in the inputs
        // The recipe has 8, so this should fail
        resultRecipe = DB.find(ingredients, recipe -> recipe.inputs
                .getOrDefault(ItemRecipeCapability.CAP, List.of())
                .stream()
                .allMatch(content -> ((SizedIngredient) content.content()).getAmount() > 32));
        helper.assertTrue(resultRecipe == null, "GT Recipe should be empty (null), instead was " + resultRecipe);

        helper.succeed();
    }

