@Override
  public boolean shouldUpdate(Level world, MultiblockStructureData structure, BlockPos pos, BlockState state) {
    if (structure.withinBounds(pos)) {
      // if its a part of the structure, need to update if its not a valid smeltery block
      if (structure.contains(pos)) {
        return !isValidBlock(state.getBlock());
      }
      // if not part of the actual structure, we only care if its a block that's not air in the inner section
      // in other words, ignore blocks added into the frame
      // note we don't do a check for a valid inner block, if it is a valid inner block we need to update to include it
      return structure.isInside(pos) && !isAirBlock(state);
    }

    // if its one block above, might be trying to expand upwards
    return structure.isDirectlyAbove(pos) && isValidWall(state.getBlock());
  }

@Nullable
  public T readFromTag(CompoundTag nbt, BlockPos controllerPos) {
    BlockPos minPos = TagUtil.readOptionalPos(nbt, MultiblockStructureData.TAG_MIN, controllerPos);
    BlockPos maxPos = TagUtil.readOptionalPos(nbt, MultiblockStructureData.TAG_MAX, controllerPos);
    if (minPos == null || maxPos == null) {
      return null;
    }
    // extra positions will be empty client side
    return create(minPos, maxPos, ImmutableSet.copyOf(readPosList(nbt, MultiblockStructureData.TAG_EXTRA_POS, controllerPos)));
  }

protected static Collection<BlockPos> readPosList(CompoundTag rootTag, String key, BlockPos offset) {
    if (!rootTag.contains(key, Tag.TAG_LIST)) {
      return Collections.emptyList();
    }
    ListTag list = rootTag.getList(key, Tag.TAG_COMPOUND);
    List<BlockPos> collection = new ArrayList<>(list.size());
    for (int i = 0; i < list.size(); i++) {
      BlockPos pos = NbtUtils.readBlockPos(list.getCompound(i));
      if (!pos.equals(BlockPos.ZERO)) {
        collection.add(pos.offset(offset));
      }
    }
    return collection;
  }

public boolean contains(BlockPos pos) {
    return withinBounds(pos) && containsBase(pos);
  }

private boolean containsBase(BlockPos pos) {
    // blocks in the inner region are added to the extra positions, fall back to that
    if (!isInside(pos)) {
      // if there is a frame, shape is a full cube so the subtraction is all we need
      if (hasFrame) {
        return true;
      }

      // otherwise we have to count edges to make sure its not on a frame
      // frame is any blocks touching two edges
      int edges = 0;
      if (pos.getX() == minPos.getX() || pos.getX() == maxPos.getX()) edges++;
      if (pos.getZ() == minPos.getZ() || pos.getZ() == maxPos.getZ()) edges++;
      if ((hasFloor && pos.getY() == minPos.getY()) ||
          (hasCeiling && pos.getX() == maxPos.getX())) edges++;
      if (edges < 2) {
        return true;
      }
    }

    // inner blocks and frame blocks (no frame) can both be added
    // though note checking code does not currently support finding extra frame blocks
    return extra.contains(pos);
  }

public <T extends MantleBlockEntity & IMasterLogic> void assignMaster(T master, @Nullable MultiblockStructureData oldStructure) {
    Predicate<BlockPos> shouldUpdate;
    if (oldStructure == null) {
      shouldUpdate = pos -> true;
    } else {
      shouldUpdate = pos -> !oldStructure.contains(pos);
    }

    Level world = master.getLevel();
    assert world != null;


    // assign master to each servant
    forEachContained(pos -> {
      if (shouldUpdate.test(pos) && world.hasChunkAt(pos)) {
        updateMaster(world, pos, master, true);
      }
    });

    // remove master from anything only in the old structure
    if (oldStructure != null) {
      oldStructure.forEachContained(pos -> {
        if (!contains(pos) && world.hasChunkAt(pos)) {
          updateMaster(world, pos, master, false);
        }
      });
    }
  }

