@Override
  public RecipeResult<LazyToolStack> getValidatedResult(ITinkerStationContainer inv, RegistryAccess access) {
    ToolStack tool = inv.getTinkerable().copy();

    ModDataNBT persistentData = tool.getPersistentData();
    ModifierId key = TinkerModifiers.dyed.getId();
    int nr = 0, nb = 0, ng = 0;
    int brightness = 0;
    int count = 0;

    // copy existing color
    if (persistentData.contains(key, Tag.TAG_INT)) {
      int color = persistentData.getInt(key);
      int r = color >> 16 & 255;
      int g = color >>  8 & 255;
      int b = color       & 255;
      brightness = Math.max(r, Math.max(g, b));
      nr = r;
      ng = g;
      nb = b;
      count++;
    }

    // copy color from each dye
    for (int i = 0; i < inv.getInputCount(); i++) {
      ItemStack stack = inv.getInput(i);
      if (!stack.isEmpty()) {
        DyeColor dye = DyeColor.getColor(stack);
        if (dye != null) {
          float[] color = dye.getTextureDiffuseColors();
          int r = (int)(color[0] * 255);
          int g = (int)(color[1] * 255);
          int b = (int)(color[2] * 255);
          brightness += Math.max(r, Math.max(g, b));
          nr += r;
          ng += g;
          nb += b;
          count++;
        }
      }
    }

    // should never happen, but lets not crash
    if (count == 0) {
      return RecipeResult.pass();
    }

    // build the final color
    nr /= count;
    ng /= count;
    nb /= count;
    float scaledBrightness = (float)brightness / count / Math.max(nr, Math.max(ng, nb));
    nr = (int)(nr * scaledBrightness);
    ng = (int)(ng * scaledBrightness);
    nb = (int)(nb * scaledBrightness);
    persistentData.putInt(key, (nr << 16) | (ng << 8) | nb);

    // add the modifier if missing
    if (tool.getModifierLevel(key) == 0) {
      tool.addModifier(key, 1);
    }
    return ITinkerStationRecipe.success(tool, inv);
  }

@Override
    public void applyModifier(ToolStack tool) {
      // store into tool NBT
      ModifierId modifier = TinkerModifiers.dyed.getId();
      ModDataNBT persistentData = tool.getPersistentData();
      if (persistentData.contains(modifier, Tag.TAG_INT)) {
        int color = persistentData.getInt(modifier);
        int r = color >> 16 & 255;
        int g = color >>  8 & 255;
        int b = color       & 255;
        int nr = (r + this.r) / 2;
        int ng = (g + this.g) / 2;
        int nb = (b + this.b) / 2;

        // build the final color
        float brightness = (Math.max(r, Math.max(g, b)) + this.brightness) / 2f / Math.max(nr, Math.max(ng, nb));
        nr = (int)(nr * brightness);
        ng = (int)(ng * brightness);
        nb = (int)(nb * brightness);
        persistentData.putInt(modifier, (nr << 16) | (ng << 8) | nb);
      } else {
        persistentData.putInt(modifier, tintColor);
      }
      // add the modifier if missing
      if (tool.getModifierLevel(modifier) == 0) {
        tool.addModifier(modifier, 1);
      }
    }

@Override
  public RecipeResult<LazyToolStack> getValidatedResult(ITinkerStationContainer inv, RegistryAccess access) {
    // first need to find our trim and material instances
    TrimItems trimItems = findInputs(inv);
    // should never happen
    if (trimItems == null) {
      return RecipeResult.pass();
    }
    // validate the material nad pattern items
    Reference<TrimMaterial> material = TrimMaterials.getFromIngredient(access, trimItems.material).orElse(null);
    if (material == null) {
      return RecipeResult.failure(KEY_INVALID_MATERIAL, trimItems.material.getDisplayName());
    }
    ToolStack original = inv.getTinkerable();
    Reference<TrimPattern> pattern = null;
    if (!original.hasTag(TinkerTags.Items.TRIM_NO_PATTERN)) {
      pattern = TrimPatterns.getFromTemplate(access, trimItems.template).orElse(null);
      if (pattern == null) {
        return RecipeResult.failure(KEY_INVALID_PATTERN, trimItems.template.getDisplayName());
      }
    }

    // store into tool NBT
    ToolStack tool = inv.getTinkerable().copy();
    ModDataNBT persistentData = tool.getPersistentData();
    ModifierId modifier = TinkerModifiers.trim.getId();
    persistentData.putString(TrimModule.materialKey(modifier), material.key().location().toString());
    if (pattern != null) {
      persistentData.putString(TrimModule.patternKey(modifier), pattern.key().location().toString());
    }

    // add the modifier if missing
    if (tool.getModifierLevel(modifier) == 0) {
      tool.addModifier(modifier, 1);
    }
    return ITinkerStationRecipe.success(tool, inv);
  }

@Override
  public RecipeResult<LazyToolStack> getValidatedResult(ITinkerStationContainer inv, RegistryAccess access) {
    RecipeResult<LazyToolStack> result = super.getValidatedResult(inv, access);
    if (result.isSuccess()) {
      // tool must have modifier, else we are adding bad data
      IToolStackView tool = result.getResult().getTool();
      if (tool.getModifierLevel(modifier) > 0) {
        // find the potion, should be first non-empty stack
        ItemStack stack = ItemStack.EMPTY;
        for (int i = 0; i < inv.getInputCount(); i++) {
          stack = inv.getInput(i);
          if (!stack.isEmpty()) {
            break;
          }
        }
        // if we found one, set its NBT into the result tool
        if (!stack.isEmpty()) {
          CompoundTag tag = stack.getTag();
          if (tag != null && tag.contains(PotionUtils.TAG_POTION, Tag.TAG_STRING)) {
            tool.getPersistentData().putString(modifier, tag.getString(PotionUtils.TAG_POTION));
          }
        }
      }
    }
    return result;
  }

