@Override
	public void extractRenderState(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTicks) {
		Objects.requireNonNull(minecraft);
		float deltaTicks = Minecraft.getInstance().getDeltaTracker().getRealtimeDeltaTicks();
		ticks += deltaTicks;
		particle:
		if (ticks > nextParticleIn) {
			if (festival == 3) {
				nextParticleIn = ticks;
				if (pendingParticles.isEmpty()) {
					festival3populateNew();
				}
				if (Mth.abs(mouseX - lastMouseX) < 3 && Mth.abs(mouseY - lastMouseY) < 3) {
					break particle;
				}
				lastMouseX = mouseX;
				lastMouseY = mouseY;
				TextParticle particle = pendingParticles.removeFirst();
				particle.x = mouseX;
				particle.y = mouseY;
				particle.gravity = 0F;
				particle.age = 40;
				particles.add(particle);
				persistentParticles.add(particle);
				if (persistentParticles.size() > 50) {
					TextParticle first = persistentParticles.removeFirst();
					first.persistent = false;
				}
			} else if (festival == 1) {
				nextParticleIn = ticks + 10 + random.nextFloat() * 10;
				int color = ARGB.colorFromFloat(1, 1 - random.nextFloat() * 0.6F, 1, 1);
				color |= (random.nextInt(80) + 40) << 24;
				int x = random.nextIntBetweenInclusive(40, width + 100);
				var particle = new TextParticle("❄", x, -20, -0.3F, 0.5f, color, 2F + random.nextFloat());
				particle.gravity = 0F;
				particles.add(particle);
			}
		}
		super.extractRenderState(graphics, mouseX, mouseY, partialTicks);
		int left = width / 2 - 105;
		int top = height / 4 - 20;
		graphics.pose().pushMatrix();
		graphics.pose().translate(left, top);

		float scale = 2F;
		graphics.pose().scale(scale);
		graphics.text(font, ModIdentification.getModFullName(Jade.ID).orElse("Jade"), 0, 0, 0xFFFFFFFF);

		graphics.pose().scale(0.5F);
		titleY.tick(deltaTicks);
		String desc2 = I18n.get("gui.jade.configuration.desc2");
		float scaledX, scaledY;
		if (desc2.isEmpty()) {
			graphics.pose().popMatrix();
			graphics.pose().pushMatrix();
			graphics.pose().translate(left, top);
			scaledX = mouseX - left;
			scaledY = mouseY - top;
		} else {
			scaledX = (mouseX - left) / scale * 2;
			scaledY = (mouseY - top) / scale * 2;
		}
		drawFancyTitle(graphics, I18n.get("gui.jade.configuration.desc1"), Math.min(titleY.value, 20F), 20F, scaledX, scaledY);
		if (!desc2.isEmpty()) {
			drawFancyTitle(graphics, desc2, Math.min(titleY.value + 3F, 32F), 32F, scaledX, scaledY);
		}
		graphics.pose().popMatrix();

		particles.removeIf(p -> {
			p.tick(deltaTicks);
			if (p.y > height + 20) {
				return true;
			}
			p.render(graphics, font, mouseX, mouseY);
			return false;
		});
	}

public static void handleRequest(RequestBlockPacket message, ServerPayloadContext context, Consumer<CompoundTag> responseSender) {
		ServerPlayer player = context.player();
		context.execute(() -> {
			BlockPos pos = message.data().hit().getBlockPos();
			CompoundTag tag = message.data().data();
			tag.putInt("x", pos.getX());
			tag.putInt("y", pos.getY());
			tag.putInt("z", pos.getZ());

			if (Jade.isOutOfReach(player, pos, player.blockInteractionRange()) || !player.level().isLoaded(pos)) {
				responseSender.accept(tag);
				return;
			}

			BlockAccessor accessor = message.data().unpack(player);
			if (accessor == null) {
				return;
			}

			tag.putString("BlockId", CommonProxy.getId(accessor.getBlock()).toString());

			List<IServerDataProvider<BlockAccessor>> providers = WailaCommonRegistration.instance()
					.blockDataProvidersOf(accessor.getBlockState(), accessor.getBlockEntity(), true);
			for (IServerDataProvider<BlockAccessor> provider : providers) {
				if (!message.dataProviders().contains(provider)) {
					continue;
				}
				try {
					provider.appendServerData(tag, accessor);
				} catch (Exception e) {
					WailaExceptionHandler.handleErr(e, provider, null);
				}
			}

			responseSender.accept(tag);
		});
	}

public static void handleRequest(RequestEntityPacket message, ServerPayloadContext context, Consumer<CompoundTag> responseSender) {
		ServerPlayer player = context.player();
		context.execute(() -> {
			EntityAccessor accessor = message.data().unpack(player);
			if (accessor == null) {
				return;
			}

			Entity entity = accessor.getEntity();
			CompoundTag tag = accessor.getServerData();
			tag.putInt("EntityId", entity.getId());

			if (Jade.isOutOfReach(player, entity.blockPosition(), player.entityInteractionRange()) || !Jade.canBeTarget(entity, player)) {
				responseSender.accept(tag);
				return;
			}
			List<IServerDataProvider<EntityAccessor>> providers = WailaCommonRegistration.instance().entityDataProvidersOf(entity);
			for (IServerDataProvider<EntityAccessor> provider : providers) {
				if (!message.dataProviders().contains(provider)) {
					continue;
				}
				try {
					provider.appendServerData(tag, accessor);
				} catch (Exception e) {
					WailaExceptionHandler.handleErr(e, provider, null);
				}
			}

			responseSender.accept(tag);
		});
	}

