@WrapMethod(method = "getTooltipFromContainerItem")
	private List<Component> jade$addModName(
			ItemStack itemStack,
			Operation<List<Component>> original,
			@Share("index") LocalIntRef index,
			@Share("names") LocalRef<@Nullable List<String>> tabNames) {
		List<Component> tooltip = original.call(itemStack);
		int i = index.get();
		if (IWailaConfig.get().general().showItemModNameTooltip() && i > 0 && i < tooltip.size()) {
			String modName = ModIdentification.getModId(itemStack);
			modName = ModIdentification.getModFullName(modName).orElse(modName);
			List<String> tabNamesValue = tabNames.get();
			if (tabNamesValue != null) {
				String modNameLower = modName.toLowerCase(Locale.ENGLISH);
				for (String tabName : tabNamesValue) {
					if (tabName.startsWith(modNameLower)) {
						return tooltip;
					}
				}
			}
			tooltip.add(i, Component.literal(modName).withStyle(IWailaConfig.get().formatting().getItemModNameStyle()));
		}
		return tooltip;
	}

public static ItemStack getFakeBlock(LevelAccessor level, BlockPos pos) {
		if (displays.isEmpty()) {
			return ItemStack.EMPTY;
		}
		List<Display> entities = level.getEntitiesOfClass(Display.class, new AABB(pos), DatapackBlockManager::isAcceptableEntity);
		if (entities.isEmpty()) {
			return ItemStack.EMPTY;
		}

		ItemStack selectedItem = ItemStack.EMPTY;
		float selectedScore = 0f;
		for (Display display : entities) {
			if (!displays.contains(display.getId())) {
				continue;
			}
			ItemStack itemStack = ItemStack.EMPTY;
			if (display instanceof Display.BlockDisplay blockDisplay) {
				itemStack = blockDisplay.getBlockState().getCloneItemStack(level, pos, false);
			} else if (display instanceof Display.ItemDisplay itemDisplay) {
				itemStack = itemDisplay.getItemStack();
			}
			float score = 0f;
			if (itemStack.isEmpty()) {
				continue;
			}
			if (itemStack.hasNonDefault(DataComponents.CUSTOM_DATA)) {
				CustomData data = itemStack.get(DataComponents.CUSTOM_DATA);
				if (data != null && data.tag.contains(ModIdentification.JADE_STACK)) {
					score += 10f;
				} else if (data != null && data.tag.contains(ModIdentification.POLYMER_STACK)) {
					score += 2f;
				}
			}
			if (itemStack.hasNonDefault(DataComponents.ITEM_MODEL)) {
				score += 1f;
			}
			if (score > selectedScore) {
				selectedItem = itemStack;
				selectedScore = score;
			}
		}
		return selectedItem;
	}

