public void setProgress(List<ProgressView.Part> parts) {
		Set<Child> set = Sets.newHashSet();
		for (ProgressView.Part part : parts) {
			Child child = children.get(part.id());
			//noinspection ConstantValue
			if (child == null) {
				child = new Child(part, canDecrease);
				children.put(part.id(), child);
			} else {
				child.part = part;
				child.setProgress(child.part.progress());
			}
			set.add(child);
		}

		for (Child child : children.values()) {
			if (!set.contains(child)) {
				child.setProgress(0);
			}
		}
	}

@Nullable
	public static <IN, OUT> List<ClientViewGroup<OUT>> mapToClientGroups(
			Accessor<?> accessor,
			Identifier key,
			StreamCodec<RegistryFriendlyByteBuf, Map.Entry<Identifier, List<ViewGroup<IN>>>> codec,
			Function<Identifier, @Nullable IClientExtensionProvider<IN, OUT>> mapper,
			ITooltip tooltip) {
		Tag tag = accessor.getServerData().get(key.toString());
		if (tag == null) {
			return null;
		}
		Map.Entry<Identifier, List<ViewGroup<IN>>> entry = accessor.decodeFromNbt(codec, tag).orElse(null);
		if (entry == null) {
			return null;
		}
		IClientExtensionProvider<IN, OUT> provider = mapper.apply(entry.getKey());
		if (provider == null) {
			return null;
		}
		try {
			return provider.getClientGroups(accessor, entry.getValue());
		} catch (Exception e) {
			WailaExceptionHandler.handleErr(e, provider, tooltip::add);
			return null;
		}
	}

public static String getModIdFromItem(ItemStack stack) {
		String modid = stack.getItem().getCreatorNamespace(stack);
		if (!Identifier.DEFAULT_NAMESPACE.equals(modid)) {
			return modid;
		}
		if (stack.has(DataComponents.STORED_ENCHANTMENTS)) {
			ItemEnchantments enchantments = stack.getOrDefault(DataComponents.STORED_ENCHANTMENTS, ItemEnchantments.EMPTY);
			modid = null;
			for (Holder<Enchantment> enchantmentHolder : enchantments.keySet()) {
				Identifier id = enchantmentHolder.unwrapKey().map(ResourceKey::identifier).orElse(null);
				if (id != null) {
					String namespace = id.getNamespace();
					if (modid == null) {
						modid = namespace;
					} else if (!modid.equals(namespace)) {
						modid = null;
						break;
					}
				}
			}
			if (modid != null) {
				return modid;
			}
		}
		PotionContents potionContents = stack.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY);
		if (potionContents.hasEffects()) {
			modid = null;
			for (MobEffectInstance effect : potionContents.getAllEffects()) {
				Identifier id = effect.getEffect().unwrapKey().map(ResourceKey::identifier).orElse(null);
				if (id != null) {
					String namespace = id.getNamespace();
					if (modid == null) {
						modid = namespace;
					} else if (!modid.equals(namespace)) {
						modid = null;
						break;
					}
				}
			}
			if (modid != null) {
				return modid;
			}
		}
		if (stack.is(Items.PAINTING)) {
			Holder<PaintingVariant> holder = stack.get(DataComponents.PAINTING_VARIANT);
			if (holder != null) {
				return holder.unwrapKey()
						.map(ResourceKey::identifier)
						.map(Identifier::getNamespace)
						.orElse(Identifier.DEFAULT_NAMESPACE);
			}
		}
		return Identifier.DEFAULT_NAMESPACE;
	}

