                .getDisplayedItemStack()
                .map(i -> i.getItemHolder().getData(GrindingBallData.DATA_MAP_TYPE))
                .orElse(GrindingBallData.IDENTITY);

        if (data == null) {
            data = GrindingBallData.IDENTITY;
        }

        return TooltipUtil.withArgs(EIOCommonLang.ENERGY_AMOUNT, NumberFormat.getIntegerInstance(Locale.ENGLISH)
                .format(recipe.value().getEnergyCost(data)));
    }

public static double getModifier(ItemStack stack, TagKey<Item> reagent) {
        var map = stack.getItemHolder().getData(VatReagent.DATA_MAP);
        if (map != null) {
            return map.getOrDefault(reagent, 1D);
        }
        return 1;
    }

@Override
    public FluidStack test(@Nullable IFluidHandler target, FluidStack stack) {
        final boolean isAllowList = container.getOrDefault(LaserIODataComponents.FILTER_ALLOW, true);
        final boolean shouldCompareComponents = container.getOrDefault(LaserIODataComponents.FILTER_COMPARE, false);

        FilterBasicHandler filterSlotHandler = new FilterBasicHandler(FilterBasicContainer.SLOTS, container);

        for (int i = 0; i < filterSlotHandler.getSlots(); ++i) {
            ItemStack itemStack = filterSlotHandler.getStackInSlot(i);

            if (!itemStack.isEmpty()) {
                Optional<IFluidHandlerItem> fluidHandlerLazyOptional = FluidUtil.getFluidHandler(itemStack);
                if (fluidHandlerLazyOptional.isPresent()) {
                    IFluidHandler fluidHandler = fluidHandlerLazyOptional.get();

                    for (int tank = 0; tank < fluidHandler.getTanks(); ++tank) {
                        FluidStack fluidStack = fluidHandler.getFluidInTank(tank);
                        if (!fluidStack.isEmpty()) {
                            if (shouldCompareComponents ? FluidStack.isSameFluid(fluidStack, stack)
                                    : FluidStack.isSameFluidSameComponents(fluidStack, stack)) {
                                return isAllowList ? fluidStack : FluidStack.EMPTY;
                            }
                        }
                    }
                }
            }
        }

        return isAllowList ? FluidStack.EMPTY : stack;
    }

@Override
    public ItemStack test(@Nullable IItemHandler target, ItemStack stack) {
        final boolean isAllowList = container.getOrDefault(LaserIODataComponents.FILTER_ALLOW, true);
        final boolean shouldCompareComponents = container.getOrDefault(LaserIODataComponents.FILTER_COMPARE, false);

        FilterBasicHandler handler = new FilterBasicHandler(FilterBasicContainer.SLOTS, container);
        for (int i = 0; i < handler.getSlots(); i++) {
            ItemStack match = handler.getStackInSlot(i);
            if (!match.isEmpty()) {
                if (shouldCompareComponents ? ItemStack.isSameItem(match, stack)
                        : ItemStack.isSameItemSameComponents(match, stack)) {
                    return isAllowList ? stack : ItemStack.EMPTY;
                }
            }
        }

        return isAllowList ? ItemStack.EMPTY : stack;
    }

@Override
    public Soul getBoundSoul() {
        if (!(spawnEgg.getItem() instanceof SpawnEggItem spawnEggItem)) {
            return Soul.EMPTY;
        }

        // Get custom entity data
        var customEntityData = spawnEgg.getOrDefault(DataComponents.ENTITY_DATA, CustomData.EMPTY);
        if (!customEntityData.isEmpty()) {
            return new Soul(spawnEggItem.getType(spawnEgg), customEntityData.copyTag());
        }

        return Soul.of(spawnEggItem.getType(spawnEgg));
    }

@Override
