        if (slot > 0) {
            return Soul.EMPTY;
        }

        if (!(spawnEgg.getItem() instanceof SpawnEggItem spawnEggItem)) {
            return Soul.EMPTY;
        }

        // Get custom entity data
        var customEntityData = spawnEgg.getOrDefault(DataComponents.ENTITY_DATA, CustomData.EMPTY);
        if (!customEntityData.isEmpty()) {
            return new Soul(spawnEggItem.getType(spawnEgg), customEntityData.copyTag());
        }

        return Soul.of(spawnEggItem.getType(spawnEgg));
    }

@Override
    protected ObjectArrayList<ItemStack> doApply(ObjectArrayList<ItemStack> generatedLoot, LootContext context) {
        BlockEntity entity = context.getParamOrNull(LootContextParams.BLOCK_ENTITY);
        if (entity == null) {
            return generatedLoot;
        }
        if (entity instanceof SpawnerBlockEntity spawnerBlockEntity) {
            if (!context.getParam(LootContextParams.TOOL).is(EIOTags.Items.BROKEN_SPAWNER_BLACKLIST)) {
                if (context.getRandom().nextFloat() < BaseConfig.COMMON.BLOCKS.BROKEN_SPAWNER_DROP_CHANCE.get()) {
                    BaseSpawner spawner = spawnerBlockEntity.getSpawner();
                    CompoundTag entityTag = spawner.nextSpawnData.getEntityToSpawn();

                    // TODO: should we be copying the entire entity tag?
                    if (entityTag.contains(Entity.ID_TAG)) {
                        ResourceLocation type = ResourceLocation.parse(entityTag.getString(Entity.ID_TAG));
                        ItemStack brokenSpawner = BrokenSpawnerItem.forSoul(Soul.of(type));
                        generatedLoot.add(brokenSpawner);
                    }
                }
            }
        }

        return generatedLoot;
    }

@Override
    public Component getName(ItemStack stack) {
        var capacitorData = stack.getOrDefault(EIODataComponents.CAPACITOR_DATA, CapacitorData.NONE);

        if (capacitorData.modifiers().isEmpty()) {
            return getBaseName(capacitorData);
        }

        return getModifierQuality(capacitorData)
            .copy()
            .append(" ")
            .append(getModifierType(capacitorData))
            .append(" ")
            .append(getBaseName(capacitorData));
    }

