            BuiltInRegistries.BLOCK.getTag(blockTagKey)
                    .map(HolderSet.ListBacked::stream)
                    .orElse(Stream.empty())
                    .map(Holder::value)
                    .forEach(blocks::add);
        }
        return blocks;
    }

