public static boolean isSlicerValid(ItemStack stack, int slot) {
        checkCacheRebuild();
        if (ITEMS.get(slot).contains(stack.getItem())) {
            return true;
        }

        for (Ingredient ingredient : NON_OPTIMIZABLE_INGREDIENTS.get(slot)) {
            if (ingredient.test(stack)) {
                return true;
            }
        }
        return false;
    }

