@Override
    public void addCommonTooltips(ItemStack itemStack, @Nullable Player player, List<Component> tooltips) {
        // Add entity name
        var soul = itemStack.getOrDefault(EIODataComponents.SOUL, Soul.EMPTY);
        if (!soul.isEmpty()) {
