        EnergyIOMode energyIOMode = getExposedEnergyStorage().getIOMode();
        TransferUtil.distributeEnergyEvenly(level, worldPosition, dir -> energyIOMode.canPush(getIOMode(dir)) && shouldPushEnergyTo(dir));
    }

