        if (isHovered && Arrays.stream(tooltipRectangles).noneMatch(rect -> rect.contains(mouseX, mouseY))) {
            graphics.renderTooltip(Minecraft.getInstance().font, makeTooltip(offer, shoppingAmount), Optional.empty(), mouseX, mouseY);
