@Override
    public int onTargetHit(Minigun minigun, ItemStack ammo, Entity target) {
        ItemStack potion = getPotionStack(ammo);
        if (!potion.isEmpty() && target instanceof LivingEntity entity) {
            Player shooter = minigun.getPlayer();
            if (minigun.dispenserWeightedPercentage(ConfigHelper.common().minigun.potionProcChance.get(), 0.25f)) {
                if (potion.getItem() == Items.POTION) {
                    potion.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY)
                            .forEachEffect(effect -> entity.addEffect(new MobEffectInstance(effect)));
                    entity.level().playSound(null, entity.blockPosition(), SoundEvents.SPLASH_POTION_BREAK, SoundSource.PLAYERS, 1f, 1f);
                } else if (potion.getItem() == Items.SPLASH_POTION || potion.getItem() == Items.LINGERING_POTION) {
                    ThrownPotion entityPotion = new ThrownPotion(shooter.level(), shooter);
                    entityPotion.setItem(potion);
                    entityPotion.setPos(entity.getX(), entity.getY(), entity.getZ());
                    shooter.level().addFreshEntity(entityPotion);
                }
            }
            return getPotionAmmoCost(potion.getItem());
        } else {
            return super.onTargetHit(minigun, ammo, target);
        }
    }

public static PacketDescription fromNBT(CompoundTag compound, RegistryAccess registryAccess) {
        BlockPos pos = new BlockPos(compound.getInt("x"), compound.getInt("y"), compound.getInt("z"));
        boolean fullSync = true;
        CompoundTag subTag = compound.getCompound(Names.MOD_ID);
        int fieldCount = subTag.getInt("Length");
        List<IndexedField> fields = new ArrayList<>();
        if (fieldCount > 0) {
            ListTag list = subTag.getList("Data", Tag.TAG_COMPOUND);
            for (int i = 0; i < fieldCount; i++) {
                CompoundTag element = list.getCompound(i);
                SyncedField.FieldType type = SyncedField.FieldType.values()[element.getByte("Type")];
                byte[] b = element.getByteArray("Value");
                RegistryFriendlyByteBuf buf = new RegistryFriendlyByteBuf(Unpooled.wrappedBuffer(b), registryAccess, ConnectionType.NEOFORGE);
                fields.add(new IndexedField(i, type, SyncedField.fromBytes(buf, type)));
            }
        }
        CompoundTag extraData = subTag.getCompound(NBT_EXTRA);
        return new PacketDescription(pos, fullSync, fields, extraData);
    }

public static void handle(PacketSendNBTPacket message, IPayloadContext ctx) {
        BlockEntity te = ctx.player().level().getBlockEntity(message.pos());
        if (te != null) {
            try {
                te.loadCustomOnly(message.tag(), ctx.player().registryAccess());
                if (te instanceof RandomizableContainer r && !message.tag().contains("LootTable")) {
                    // bit of a kludge to ensure loot table data gets cleared clientside
                    r.setLootTable(null);
                }
            } catch (Throwable e) {
                TrackerBlacklistManager.addInventoryTEToBlacklist(te, e);
            }
        }
    }

public static void handle(PacketSetGlobalVariable message, IPayloadContext ctx) {
        Player player = ctx.player();

        message.value()
                .ifLeft(pos -> GlobalVariableHelper.getInstance().setPos(player.getUUID(), message.varName(), pos.orElse(null)))
                .ifRight(stack -> GlobalVariableHelper.getInstance().setStack(player.getUUID(), message.varName(), stack));

        if (ctx.flow().isClientbound()) {
            AbstractRemoteScreen.handleVariableChangeIfOpen(message.varName());
            AreaRenderManager.getInstance().clearPosProviderCache();
        }
    }

public static void handle(PacketUpdateArmorExtraData message, IPayloadContext ctx) {
        ItemStack stack = ctx.player().getItemBySlot(message.slot());
        if (stack.getItem() instanceof PneumaticArmorItem && stack.getComponents() instanceof PatchedDataComponentMap pdcm) {
            CommonArmorHandler handler = CommonArmorHandler.getHandlerForPlayer(ctx.player());
            message.patch.entrySet().forEach(entry -> {
                if (isTypeOKForSlot(message.slot, entry.getKey())) {
                    pdcm.applyPatch(message.patch);
                    IArmorUpgradeHandler<?> upgradeHandler = ArmorUpgradeRegistry.getInstance().getUpgradeEntry(message.upgradeID());
                    if (upgradeHandler != null) {
                        upgradeHandler.onDataFieldUpdated(handler, entry.getKey(), entry.getValue().orElse(null));
                    }
                }
            });
        }
    }

