        boolean itemOK = inputs.inputItem().map(ingr -> ingr.test(itemStack)).orElse(itemStack.isEmpty());
        boolean fluidOK = inputs.inputFluid().map(ingr -> ingr.ingredient().test(fluidStack)).orElse(fluidStack.isEmpty());

