public BookData(JsonObject root) {
			var emptyArray = new JsonArray();
			for (var e : GsonHelper.getAsJsonArray(root, "viewedEntries", emptyArray)) {
				viewedEntries.add(Identifier.parse(e.getAsString()));
			}
			for (var e : GsonHelper.getAsJsonArray(root, "bookmarks", emptyArray)) {
				bookmarks.add(new Bookmark(e.getAsJsonObject()));
			}
			for (var e : GsonHelper.getAsJsonArray(root, "history", emptyArray)) {
				history.add(Identifier.parse(e.getAsString()));
			}
			for (var e : GsonHelper.getAsJsonArray(root, "completedManualQuests", emptyArray)) {
				completedManualQuests.add(Identifier.parse(e.getAsString()));
			}
		}

public JsonObject serialize() {
			var ret = new JsonObject();
			var viewed = new JsonArray();
			this.viewedEntries.stream().map(Object::toString).forEach(viewed::add);
			ret.add("viewedEntries", viewed);

			var bookmarks = new JsonArray();
			this.bookmarks.stream().map(Bookmark::serialize).forEach(bookmarks::add);
			ret.add("bookmarks", bookmarks);

			var completed = new JsonArray();
			this.completedManualQuests.stream().map(Object::toString).forEach(completed::add);
			ret.add("completedManualQuests", completed);

			return ret;
		}

public BookEntry(JsonObject root, Identifier id, Book book, @Nullable String addedBy, HolderLookup.Provider registries) {
		this.id = id;
		this.book = book;
		this.addedBy = addedBy;

		var categoryId = GsonHelper.getAsString(root, "category");
		if (categoryId.contains(":")) { // full category ID
			this.categoryId = Identifier.tryParse(categoryId);
		} else {
			String hint = String.format("`%s:%s`", book.id.getNamespace(), categoryId);
			throw new IllegalArgumentException("`category` must be fully qualified (domain:name). Hint: Try " + hint);
		}

		this.name = GsonHelper.getAsString(root, "name");
		this.flag = GsonHelper.getAsString(root, "flag", "");
		this.icon = BookIcon.from(GsonHelper.getAsString(root, "icon"), registries);
		this.priority = GsonHelper.getAsBoolean(root, "priority", false);
		this.secret = GsonHelper.getAsBoolean(root, "secret", false);
		this.readByDefault = GsonHelper.getAsBoolean(root, "read_by_default", false);
		this.advancement = SerializationUtil.getAsIdentifier(root, "advancement", null);
		this.turnin = SerializationUtil.getAsIdentifier(root, "turnin", null);
		this.sortnum = GsonHelper.getAsInt(root, "sortnum", 0);
		var entryColor = GsonHelper.getAsString(root, "entry_color", null);
		if (entryColor != null) {
			this.entryColor = Integer.parseInt(entryColor, 16);
		} else {
			this.entryColor = book.textColor;
		}
		this.pages = ClientBookRegistry.INSTANCE.gson.fromJson(GsonHelper.getAsJsonArray(root, "pages"), BookPage[].class);

		var extraRecipeMap = GsonHelper.getAsJsonObject(root, "extra_recipe_mappings", null);
		if (extraRecipeMap == null) {
			extraRecipeMappings = Collections.emptyMap();
		} else {
			extraRecipeMappings = ClientBookRegistry.INSTANCE.gson.fromJson(extraRecipeMap, new TypeToken<Map<String, Integer>>() {}.getType());
		}

	}

public boolean isFoundByQuery(String query) {
		if (getName().getString().toLowerCase().contains(query)) {
			return true;
		}

		for (StackWrapper wrapper : relevantStacks) {
			if (wrapper.stack.getHoverName().getString().toLowerCase().contains(query)) {
				return true;
			}
		}

		return false;
	}

@Override
	protected EntryDisplayState computeReadState() {
		BookData data = PersistentData.data.getBookData(book);
		if (data != null && getId() != null && !readByDefault && !isLocked() && !data.viewedEntries.contains(getId())) {
			return EntryDisplayState.UNREAD;
		}

		if (turnin != null && !ClientAdvancements.hasDone(turnin.toString())) {
			return EntryDisplayState.PENDING;
		}

		for (BookPage page : pages) {
			if (page instanceof PageQuest && ((PageQuest) page).isCompleted(book)) {
				return EntryDisplayState.COMPLETED;
			}
		}

		return EntryDisplayState.NEUTRAL;
	}

@Override
	public void onFirstOpened() {
		super.onFirstOpened();

		boolean dirty = false;
		var key = entry.getId();

		BookData data = PersistentData.data.getBookData(book);

		if (!data.viewedEntries.contains(key)) {
			data.viewedEntries.add(key);
			dirty = true;
			entry.markReadStateDirty();
		}

		int index = data.history.indexOf(key);
		if (index != 0) {
			if (index > 0) {
				data.history.remove(key);
			}

			data.history.addFirst(key);
			while (data.history.size() > GuiBookEntryList.ENTRIES_PER_PAGE) {
				data.history.remove(GuiBookEntryList.ENTRIES_PER_PAGE);
			}

			dirty = true;
		}

		if (dirty) {
			PersistentData.save();
		}
	}

public boolean isCompleted(Book book) {
		return isManual
				? PersistentData.data.getBookData(book).completedManualQuests.contains(entry.getId())
				: trigger != null && ClientAdvancements.hasDone(trigger.toString());
	}

protected void questButtonClicked(Button button) {
		var res = entry.getId();
		BookData data = PersistentData.data.getBookData(parent.book);

		if (data.completedManualQuests.contains(res)) {
			data.completedManualQuests.remove(res);
		} else {
			data.completedManualQuests.add(res);
		}
		PersistentData.save();

		updateButtonText(button);
		entry.markReadStateDirty();
	}

public static BookTemplate createTemplate(Book book, BookContentsBuilder builder, String type, @Nullable TemplateInclusion inclusion) {
		Identifier key;
		if (type.contains(":")) {
			key = Identifier.tryParse(type);
		} else {
			key = Identifier.fromNamespaceAndPath(book.id.getNamespace(), type);
		}

		Supplier<BookTemplate> supplier = builder.getTemplate(key);
		if (supplier == null) {
			throw new IllegalArgumentException("Template " + key + " does not exist");
		}

		BookTemplate template = supplier.get();
		template.book = book;
		template.encapsulation = inclusion;

		return template;
	}

@NotNull
	@Override
	public IStateMatcher tagMatcher(@NotNull TagKey<Block> tag) {
		/* TODO deduplicate with StringStateMatcher's version. This one is okay with
		* tags that don't exist but that one validates that the tag exists.
		*/
		return new IStateMatcher() {
			@NotNull
			@Override
			public BlockState getDisplayedState(long ticks) {
				return BuiltInRegistries.BLOCK.get(tag).map(n -> {
					int idx = (int) ((ticks / 20) % n.size());
					return n.get(idx).value().defaultBlockState();
				}).orElse(Blocks.BEDROCK.defaultBlockState());
			}

			@NotNull
			@Override
			public TriPredicate<BlockGetter, BlockPos, BlockState> getStatePredicate() {
				return (w, p, s) -> s.is(tag);
			}
		};
	}

