public void interact(Player player, InteractionHand hand, ItemStack stack, Direction side) {
		int index = side.get3DDataValue();
		if(index >= 0) {
			ItemStack stackAt = getItem(index);
			if(!stackAt.isEmpty() && stack.isEmpty()) {
				player.setItemInHand(hand, stackAt);
				setItem(index, ItemStack.EMPTY);
			} else if(!stack.isEmpty()) {
				ItemStack copy = stack.split(1);

				if(stack.isEmpty()) {
					player.setItemInHand(hand, stackAt);
				} else if(!stackAt.isEmpty()) {
					player.getInventory().placeItemBackInInventory(stackAt);
				}

				setItem(index, copy);
			}
		}

		if(level != null && !level.isClientSide) {
			jump();

			if(hasCustomName()) {
				TinyPotatoInfo info = TinyPotatoInfo.fromComponent(name);

				String checkName = info.name().toLowerCase(Locale.ROOT).trim();
				if(SOUNDS.containsKey(checkName) && soundCd == 0) {
					SoundEvent playSound = SOUNDS.get(checkName);
					soundCd = 20;
					level.playSound(null, worldPosition, playSound, SoundSource.BLOCKS, 1F, 1F);
				}
			}

			ItemStack tater = ItemStack.EMPTY;
			boolean manyTater = false;
			for(int i = 0; i < getContainerSize(); i++) {
				ItemStack stackAt = getItem(i);
				if(!stackAt.isEmpty() && stackAt.is(TinyPotatoModule.tiny_potato.asItem())) {
					if(tater.isEmpty())
						tater = stackAt;
					else {
						manyTater = true;
						break;
					}
				}
			}
			if(!tater.isEmpty()) {
				String taterGender = manyTater ? "children" : "son";
				if(tater.getComponents().has(DataComponents.CUSTOM_NAME) && !manyTater) {
					TinyPotatoInfo info = TinyPotatoInfo.fromComponent(tater.getHoverName());
					taterGender = GENDER.getOrDefault(info.name(), taterGender);
				}
				if(player instanceof ServerPlayer serverPlayer)
					serverPlayer.sendSystemMessage(Component.translatable("quark.misc.my_" + taterGender), true);
			}
		}
	}

@Override
	public ItemInteractionResult useItemOn(ItemStack stack, BlockState state, Level worldIn, BlockPos pos, Player player, InteractionHand handIn, BlockHitResult hit) {

		// fix pipes if they're ruined
		if(stack.getItem() == Items.STICK) {
			Set<BlockPos> found = new HashSet<>();
			boolean fixedAny = false;

			Set<BlockPos> candidates = new HashSet<>();
			Set<BlockPos> newCandidates = new HashSet<>();

			candidates.add(pos);
			do {
				for(BlockPos cand : candidates) {
					for(Direction d : Direction.values()) {
						BlockPos offPos = cand.relative(d);
						BlockState offState = worldIn.getBlockState(offPos);
						if(offState.getBlock() == this && !candidates.contains(offPos) && !found.contains(offPos))
							newCandidates.add(offPos);
					}

					BlockState curr = worldIn.getBlockState(cand);
					BlockState target = getTargetState(worldIn, cand);
					if(!target.equals(curr)) {
						fixedAny = true;
						worldIn.setBlock(cand, target, 2 | 4);
					}
				}

				found.addAll(candidates);
				candidates = newCandidates;
				newCandidates = new HashSet<>();
			} while(!candidates.isEmpty());

			if(fixedAny)
				return ItemInteractionResult.sidedSuccess(worldIn.isClientSide);
		}

		return super.useItemOn(stack, state, worldIn, pos, player, handIn, hit);
	}

private static BakedModel getModel(String name, boolean angry) {
		ModelManager bmm = Minecraft.getInstance().getModelManager();
		Map<ModelResourceLocation, BakedModel> mm = ((AccessorModelManager) bmm).getBakedRegistry();
		BakedModel missing = bmm.getMissingModel();
		ModelResourceLocation location = ModelResourceLocation.standalone(taterLocation(name));
		BakedModel model = mm.get(location);
		if(model == null) {
			if(isTheSpookDay()) {
				return mm.getOrDefault(ModelResourceLocation.standalone(taterLocation(HALLOWEEN)), missing);
			} else if(angry) {
				return mm.getOrDefault(ModelResourceLocation.standalone(taterLocation(ANGRY)), missing);
			} else {
				return mm.getOrDefault(ModelResourceLocation.standalone(taterLocation(DEFAULT)), missing);
			}
		}
		return model;
	}

