@Override
			public int getColor(@NotNull ItemStack stack, int layer) {
		 		if(isEnabled() && featureEnabled.getAsBoolean() && (layer == 1 || layer == 2) && stack.has(DataComponents.BUCKET_ENTITY_DATA)) {
					CompoundTag tag = stack.get(DataComponents.BUCKET_ENTITY_DATA).copyTag();

					if(tag != null && tag.contains(TropicalFish.BUCKET_VARIANT_TAG, Tag.TAG_INT)) {
						int variant = tag.getInt(TropicalFish.BUCKET_VARIANT_TAG);

						DyeColor dyeColor = layer == 1 ? TropicalFish.getBaseColor(variant) : TropicalFish.getPatternColor(variant);
						int colorComponents = dyeColor.getTextureDiffuseColor();

						return ((colorComponents * 255) << 16) |
								((colorComponents * 255) << 8) |
                                (colorComponents * 255);
					}
				}

				return parent != null ? parent.getColor(stack, layer) : -1;
			}

public boolean namesMatch(ItemStack stack, String search) {
			search = ChatFormatting.stripFormatting(search.trim().toLowerCase(Locale.ROOT));
			if(search == null || search.isEmpty())
				return true;

			if(stack.isEmpty())
				return false;

			Item item = stack.getItem();
			ResourceLocation res = BuiltInRegistries.ITEM.getKey(item);
			if(SimilarBlockTypeHandler.isShulkerBox(res) && stack.has(DataComponents.BLOCK_ENTITY_DATA)) {
				CompoundTag cmp = stack.get(DataComponents.BLOCK_ENTITY_DATA).copyTag();
				Level level = Minecraft.getInstance().level;
				if(cmp != null && level != null) {
					if(!cmp.contains("id")) {
						cmp = cmp.copy();
						cmp.putString("id", "minecraft:shulker_box");
					}

					BlockEntity be = BlockEntity.loadStatic(BlockPos.ZERO, ((BlockItem) item).getBlock().defaultBlockState(), cmp, level.registryAccess());
					if(be != null) {
						Optional<IItemHandler> handler = Optional.ofNullable(level.getCapability(Capabilities.ItemHandler.BLOCK, be.getBlockPos(), null));
						if(handler.isPresent()) {
							IItemHandler items = handler.orElse(new ItemStackHandler());
							for(int i = 0; i < items.getSlots(); i++)
								if(namesMatch(items.getStackInSlot(i), search))
									return true;
						}
					}
				}
			}

			String name = stack.getHoverName().getString();
			name = ChatFormatting.stripFormatting(name.trim().toLowerCase(Locale.ROOT));

			StringMatcher matcher = String::contains;

			if(search.length() >= 3 && search.startsWith("\"") && search.endsWith("\"")) {
				search = search.substring(1, search.length() - 1);
				matcher = String::equals;
			}

			if(search.length() >= 3 && search.startsWith("/") && search.endsWith("/")) {
				search = search.substring(1, search.length() - 1);
				matcher = (s1, s2) -> Pattern.compile(s2).matcher(s1).find();
			}

			if(stack.isEnchanted()) {
				ItemEnchantments enchants = stack.get(DataComponents.ENCHANTMENTS);
				for(Holder<Enchantment> e : enchants.keySet())
					if(e != null && matcher.test(Enchantment.getFullname(e, enchants.getLevel(e)).toString().toLowerCase(Locale.ROOT), search))
						return true;
			}

			List<Component> potionNames = new ArrayList<>();
			if (stack.has(DataComponents.POTION_CONTENTS)) {
				PotionContents.addPotionTooltip(stack.get(DataComponents.POTION_CONTENTS).getAllEffects(), (component) -> potionNames.add(component), 1F, Item.TooltipContext.EMPTY.tickRate());
				for (Component s : potionNames) {
					if (matcher.test(ChatFormatting.stripFormatting(s.toString().trim().toLowerCase(Locale.ROOT)), search))
						return true;
				}
			}

			if (stack.has(DataComponents.STORED_ENCHANTMENTS)) {
				ItemEnchantments enchantments = stack.get(DataComponents.STORED_ENCHANTMENTS);
				for (Holder<Enchantment> e : enchantments.keySet()) {
					int lvl = enchantments.getLevel(e);
					if (matcher.test(Enchantment.getFullname(e, lvl).toString().toLowerCase(Locale.ROOT), search))
						return true;
				}
			}

			for(String tabDisplayName : BuiltInRegistries.CREATIVE_MODE_TAB.stream()
				.filter(tab -> tab.contains(stack))
				.map(tab -> tab.getDisplayName().getString().toLowerCase(Locale.ROOT))
				.toList()
			) {
				if(matcher.test(tabDisplayName, search))
					return true;
			}

			ResourceLocation itemName = BuiltInRegistries.ITEM.getKey(item);
			@Nullable
			String modDisplayName = zeta().getModDisplayName(itemName.getNamespace());

			if(modDisplayName != null && matcher.test(modDisplayName.toLowerCase(Locale.ROOT), search))
				return true;

			return matcher.test(name, search);
			//		return ISearchHandler.hasHandler(stack) && ISearchHandler.getHandler(stack).stackMatchesSearchQuery(search, matcher, ChestSearchBar::namesMatch);
		}

@Override
		public void renderImage(@NotNull Font font, int tooltipX, int tooltipY, @NotNull GuiGraphics guiGraphics) {
			PoseStack pose = guiGraphics.pose();

			if(!Screen.hasShiftDown()) {
				pose.pushPose();

				pose.translate(0, 0, 500); // Sets the priority of the tooltip that we are making

				// Shader stuff, shouldn't be too crazy
				RenderSystem.setShader(GameRenderer::getPositionTexShader);
				RenderSystem.setShaderColor(1.0F, 1.0F, 1.0F, 1.0F);

				Minecraft mc = net.minecraft.client.Minecraft.getInstance();
				Player player = mc.player; // Player will always be available, if it isnt then uhhhh
				ItemAttributeModifiers modifiers = stack.getAttributeModifiers(); // The attributes of the item.

				// Sorting has some errors, huh.
				/*modifiers.modifiers().sort((entry, entry2) -> {
					if (!entry.attribute().equals(entry2.attribute())) {
						return entry.attribute().getRegisteredName().compareTo(entry2.attribute().getRegisteredName());
					} else if (entry.modifier().operation() != entry2.modifier().operation()) {
						return entry.modifier().operation().id() - entry2.modifier().operation().id();
					} else return 0;
				});*/

				int x = tooltipX;
				int y = tooltipY - 1;

				List<EquipmentSlotGroup> groups = new ArrayList<>();

				for (ItemAttributeModifiers.Entry entry : modifiers.modifiers()) {
					if (!groups.contains(entry.slot())) groups.add(entry.slot());
				}

				boolean shouldSeparateFromMain = groups.size() > 1;
				ItemStack comparedItem = player.getItemBySlot(player.getEquipmentSlotForItem(stack));

				for (EquipmentSlotGroup slotGroup : groups) {
					int groupX = tooltipX;
					if (shouldSeparateFromMain) {
						guiGraphics.blit(ClientUtil.GENERAL_ICONS, groupX, y, 193 + slotGroup.ordinal() * 9, 35, 9, 9, 256, 256);
						groupX += 16;
					}

					if (!comparedItem.isEmpty() && !comparedItem.equals(stack) &&
							comparedItem.has(DataComponents.ATTRIBUTE_MODIFIERS) &&
							!comparedItem.getAttributeModifiers().modifiers().isEmpty()) {
						ItemAttributeModifiers differenceInModifiers = compareAttributesOfStacks(comparedItem, stack);

						for (ItemAttributeModifiers.Entry entry : simplifyStackAttributes(stack).modifiers()) {
							if (entry.slot() != slotGroup) {
								continue;
							}

							ItemAttributeModifiers.Entry diffAttribute = null;

							for (ItemAttributeModifiers.Entry potentialDiffAttribute : differenceInModifiers.modifiers()) {
								if (potentialDiffAttribute.modifier().operation().equals(entry.modifier().operation()) &&
										potentialDiffAttribute.slot().equals(entry.slot()) && potentialDiffAttribute.attribute().equals(entry.attribute())) {
									diffAttribute = potentialDiffAttribute;
									break;
								}
							}

							groupX = renderAttribute(guiGraphics, entry, groupX, y, mc, diffAttribute);
						}
					} else {
						for (ItemAttributeModifiers.Entry entry : simplifyStackAttributes(stack).modifiers()) {
							if (entry.slot() != slotGroup) {
								continue;
							}

							groupX = renderAttribute(guiGraphics, entry, groupX, y, mc, null);
						}
					}
					x = groupX;
					y += 10;
				}

				pose.popPose();

			}
		}

@Override
		public int getHeight() {
			int y = 0;
			ItemAttributeModifiers modifiers = stack.getAttributeModifiers();
			if (modifiers.showInTooltip()) {
				List<EquipmentSlotGroup> groups = new ArrayList<>();
				for (ItemAttributeModifiers.Entry entry : modifiers.modifiers()) {
					if (!groups.contains(entry.slot())) groups.add(entry.slot());
				}
				y = groups.size() * 10;
			}
			return y;
