@Override
		public int getWidth(@NotNull Font font) {
			int width = 8;
			ItemAttributeModifiers modifiers = stack.getAttributeModifiers();
			Minecraft mc = Minecraft.getInstance();

			if (modifiers.showInTooltip()) {
				List<EquipmentSlotGroup> groups = new ArrayList<>();

				for (ItemAttributeModifiers.Entry entry : modifiers.modifiers()) {
					if (!groups.contains(entry.slot())) groups.add(entry.slot());
				}

				int x = 0;
				for (EquipmentSlotGroup slotGroup : groups) {
					int groupX = 0;
					if (groups.size() > 1) {
						groupX += 16;
					}

					for (ItemAttributeModifiers.Entry entry : modifiers.modifiers()) {
						if (entry.slot() != slotGroup) continue;
						double baseVal;
                        try {
                            baseVal = mc.player.getAttributeBaseValue(entry.attribute());
                        } catch (Exception exception) { // The game expects a base value, but its not guaranteed! So to avoid an exception we catch it here.
                            baseVal = 0;
                        }
						groupX += mc.font.width(format(entry, baseVal)) + 20;
					}
					x = Math.max(x, groupX);
				}
				width = x;
			}
			return width - 8;
		}

private static void computeAdditionalStacks() {
		additionalStacks = HashMultimap.create();

		for(String s : ImprovedTooltipsModule.enchantingAdditionalStacks) {
			if(!s.contains("="))
				continue;

			String[] tokens = s.split("=");
			String left = tokens[0];
			String right = tokens[1];

			Quark.ZETA.hackilyGetCurrentLevelRegistryAccess().registry(Registries.ENCHANTMENT).get().getOptional(ResourceLocation.parse(left))
					.ifPresent(ench -> {
						for(String itemId : right.split(",")) {
							BuiltInRegistries.ITEM.getOptional(ResourceLocation.parse(itemId)).ifPresent(item -> additionalStacks.put(ench, new ItemStack(item)));
						}
					});
		}
	}

public static void makeTooltip(ZGatherTooltipComponents event) {
		ItemStack stack = event.getItemStack();
		if(!stack.isEmpty()) {
			Screen screen = Minecraft.getInstance().screen;
			if(screen != null && screen instanceof AbstractFurnaceScreen<?>) {
				//for fuel times added with NeoForge data maps:
				int count = Quark.ZETA.itemExtensions.get(stack).getBurnTimeZeta(stack, RecipeType.SMELTING);
				if(count == 0){
					//for fuel times added with Zeta code:
					count = Quark.ZETA.fuel.fuelValues.getOrDefault(stack.getItem(), 0);
				}
				if(count == 0){
					//for fuel times added with item class getBurnTime overrides
					count = stack.getItem().getBurnTime(stack, RecipeType.SMELTING);
				}


				if(count > 0) {
					Font font = Minecraft.getInstance().font;

					String time = getDisplayString(count);
					event.getTooltipElements().add(Either.right(new FuelComponent(stack, 18 + font.width(time), count)));
