@NotNull
	@Override
	public InteractionResult useOn(UseOnContext context) {
		Player player = context.getPlayer();
		if (player == null) return InteractionResult.PASS;
		InteractionHand hand = context.getHand();

		List<Integer> targets = new ArrayList<>();
		Inventory inventory = player.getInventory();
		for(int i = 0; i < Inventory.getSelectionSize(); i++) {
			ItemStack stack = inventory.getItem(i);
			if(isValidTarget(stack, context))
				targets.add(i);
		}

		if (targets.isEmpty()) return InteractionResult.PASS;

		ItemStack trowel = player.getItemInHand(hand);

		long seed = Optional.ofNullable(trowel.get(QuarkDataComponents.PLACING_SEED)).orElse(0L);
		Random rand = new Random(seed);
		trowel.set(QuarkDataComponents.PLACING_SEED, rand.nextLong());

		int targetSlot = targets.get(rand.nextInt(targets.size()));
		ItemStack toPlaceStack = inventory.getItem(targetSlot);

		player.setItemInHand(hand, toPlaceStack);
		InteractionResult result = toPlaceStack.useOn(new TrowelBlockItemUseContext(context, toPlaceStack));
		//get new item in hand
		ItemStack newHandItem = player.getItemInHand(hand);

		//reset
		player.setItemInHand(hand, trowel);
		inventory.setItem(targetSlot, newHandItem);

		if (result.consumesAction()) {
			trowel.set(QuarkDataComponents.LAST_STACK, new ItemWrapperComponent(toPlaceStack.copy()));

			if (TrowelModule.maxDamage > 0)
				MiscUtil.damageStack(context.getItemInHand(), 1, player, hand == InteractionHand.MAIN_HAND ? EquipmentSlot.MAINHAND : EquipmentSlot.OFFHAND);
		}

        if (toPlaceStack.isEmpty()) trowel.remove(QuarkDataComponents.LAST_STACK);

		return result;
	}

@Override
	@NotNull
	public ItemStack run(@NotNull ItemStack stack, LootContext context) {
		if(options.isEmpty()){
			//AncientTomesModule::onLootTableLoad will use this route,
			//or it will default to this if you don't specify "options" in a loot table
			Holder<Enchantment> enchantment = AncientTomesModule.validEnchants.get(context.getRandom().nextInt(AncientTomesModule.validEnchants.size()));
			return AncientTomeItem.getEnchantedItemStack(enchantment);
		}
		else{
			List<Holder<Enchantment>> possibleEnchantments = new ArrayList<>();
			for(Holder<Enchantment> enchantment : options.get()){
				if(onlyValid){
					//if true, the function should check the config to make sure the enchantment is valid
					if(AncientTomesModule.validEnchants.contains(enchantment)) {
						if (!(AncientTomesModule.sanityCheck && enchantment.value().getMaxLevel() == 1)) {
							possibleEnchantments.add(enchantment);
						}
					}
				}
				else {
					possibleEnchantments.add(enchantment);
				}
			}
			Holder<Enchantment> enchantment = possibleEnchantments.get(context.getRandom().nextInt(possibleEnchantments.size()));
			return AncientTomeItem.getEnchantedItemStack(enchantment);
		}
    }

