protected void updateSearch() {
        String searchString = searchField.getValue().trim();
        if (searchField.getValue().isEmpty()) {
            searchField.setSuggestion(Component.translatable("ars_nouveau.spell_book_gui.search").getString());
        } else {
            searchField.setSuggestion("");
        }

        if (refreshItemList || !searchLast.equals(searchString)) {
            this.itemsSorted = new ArrayList<>();
            String search = searchString.toLowerCase();

            SearchType searchFieldType = SearchType.ITEM;
            for (SearchType value : SearchType.values()) {
                if (value.isMatch(search)) {
                    searchFieldType = value;
                }
            }
            if (searchFieldType != SearchType.ITEM) {
                search = searchString.substring(1);
            }
            String finalSearch = search;

            for (StoredItemStack stored : this.itemsUnsorted) {
                if (stored == null || stored.getStack() == null) continue;

                boolean isMatch = switch (searchFieldType) {
                    case ITEM -> {
                        boolean contains = stored.getStack().getHoverName().getString().toLowerCase().contains(finalSearch);
                        if (contains) yield true;
                        yield tooltipCache.getUnchecked(stored).stream().anyMatch(tooltip -> tooltip.toLowerCase().contains(finalSearch));
                    }
                    case MOD ->
                            BuiltInRegistries.ITEM.getKey(stored.getStack().getItem()).getNamespace().contains(finalSearch);
                    case TAG -> tagCache.getUnchecked(stored).stream().anyMatch(tag -> tag.contains(finalSearch));
                    case COMPONENT -> {
                        if (stored.getStack().getComponentsPatch().isEmpty()) yield false;
                        yield componentCache.getUnchecked(stored).contains(finalSearch);
                    }
                };

                if (isMatch) {
                    addStackToClientList(stored);
                }
            }

            Collections.sort(this.itemsSorted, noSort ? sortComp : comparator);
            if (!searchLast.equals(searchString)) {
                this.scrollTo(0);
                this.currentScroll = 0;
                if (searchType == 1) {
                    IAutoFillTerminal.sync(searchString);
                }
                Networking.sendToServer(new ClientSearchPacket(searchString));
                onUpdateSearch(searchString);
            } else {
                this.scrollTo(this.currentScroll);
            }
            refreshItemList = false;
            this.searchLast = searchString;
        }
    }

@Override
    public void broadcastChanges() {
        if (te == null) {
            return;
        }

        Map<StoredItemStack, Long> itemsCount = te.getStacks(tabs.get(pinv.player.getUUID()));
        List<StoredItemStack> toWrite = new ArrayList<>();
        Set<StoredItemStack> found = new HashSet<>();
        itemsCount.forEach((s, c) -> {
            long pc = this.itemLongMap.getLong(s);
            if (pc != 0L) found.add(s);
            if (pc != c) {
                toWrite.add(new StoredItemStack(s.getStack(), c));
            }
        });
        this.itemLongMap.forEach((s, c) -> {
            if (!found.contains(s))
                toWrite.add(new StoredItemStack(s.getStack(), 0L));
        });
        this.itemLongMap.clear();
        this.itemLongMap.putAll(itemsCount);
        if (!toWrite.isEmpty()) {
            Networking.sendToPlayerClient(new UpdateStorageItemsPacket(toWrite), (ServerPlayer) pinv.player);
        }

        if (!sentSettings) {
            Networking.sendToPlayerClient(new SetTerminalSettingsPacket(te.sortSettings, null), (ServerPlayer) pinv.player);
            Networking.sendToPlayerClient(new ServerToClientStoragePacket(te.getLastSearch(pinv.player), te.getTabNames()), (ServerPlayer) pinv.player);
            sentSettings = true;
        }

        super.broadcastChanges();
    }

private Upgrades getUpgradable() {
        if (upgradableCache != null) {
            return upgradableCache;
        }

        List<EmiStack> fromList = new ArrayList<>();
        List<EmiStack> toList = new ArrayList<>();

        List<ItemStack> stacks = PerkRegistry.getPerkProviderItems().stream().filter(item -> item instanceof AnimatedMagicArmor ama && ama.getMinTier() < recipe.tier).map(Item::getDefaultInstance).toList();

        for (ItemStack from : stacks) {
            ItemStack to = from.copy();
            List<List<PerkSlot>> perkProvider = PerkRegistry.getPerkProvider(from);
            if (perkProvider != null) {
                ArmorPerkHolder perkHolder = from.getOrDefault(DataComponentRegistry.ARMOR_PERKS, new ArmorPerkHolder(null, List.of(), 0, new HashMap<>()));
                from.set(DataComponentRegistry.ARMOR_PERKS, perkHolder.setTier(recipe.tier - 1));
                ArmorPerkHolder copyHolder = to.getOrDefault(DataComponentRegistry.ARMOR_PERKS, new ArmorPerkHolder(null, List.of(), 0, new HashMap<>()));
                to.set(DataComponentRegistry.ARMOR_PERKS, copyHolder.setTier(recipe.tier));
            }

            fromList.add(EmiStack.of(from));
            toList.add(EmiStack.of(to));
        }

        upgradableCache = new Upgrades(fromList, toList);
        return upgradableCache;
    }

public static void renderOverlay(GuiGraphics graphics, DeltaTracker tracker) {
        PoseStack poseStack = graphics.pose();
        Minecraft mc = Minecraft.getInstance();
        if (mc.options.hideGui || mc.gameMode.getPlayerMode() == GameType.SPECTATOR)
            return;

        HitResult objectMouseOver = mc.hitResult;
        List<Component> tooltip = new ArrayList<>();
        Object hovering = null;
        if (objectMouseOver instanceof BlockHitResult hitResult) {
            hovering = hitResult.getBlockPos();
            if (mc.level.getBlockEntity(hitResult.getBlockPos()) instanceof ITooltipProvider iTooltipProvider) {
                iTooltipProvider.getTooltip(tooltip);
            }
        } else if (objectMouseOver instanceof EntityHitResult result) {
            if (result.getEntity() instanceof ITooltipProvider iTooltipProvider) {
                iTooltipProvider.getTooltip(tooltip);
            }
            if (result.getEntity() instanceof ItemFrame frame) {
                ItemScrollData data = frame.getItem().getOrDefault(DataComponentRegistry.ITEM_SCROLL_DATA, new ItemScrollData(List.of()));
                data.addToTooltip(Item.TooltipContext.EMPTY, tooltip::add, TooltipFlag.NORMAL);
            }
            hovering = result.getEntity();
        }

        if (hovering == null || (lastHovered != null && !lastHovered.equals(hovering))) {
            lastHovered = null;
            hoverTicks = 0;
        }

        if (lastHovered == null || lastHovered.equals(hovering))
            hoverTicks++;
        else
            hoverTicks = 0;
        lastHovered = hovering;


        if (tooltip.isEmpty()) {
            return;
        }
        poseStack.pushPose();

        int tooltipTextWidth = 0;
        for (FormattedText textLine : tooltip) {
            int textLineWidth = mc.font.width(textLine);
            if (textLineWidth > tooltipTextWidth)
                tooltipTextWidth = textLineWidth;
        }

        int tooltipHeight = 8;
        if (tooltip.size() > 1) {
            tooltipHeight += 2; // gap between title lines and next lines
            tooltipHeight += (tooltip.size() - 1) * 10;
        }
        int xOffset = Config.TOOLTIP_X_OFFSET.get();
        int width = Minecraft.getInstance().getWindow().getGuiScaledWidth();
        int height = Minecraft.getInstance().getWindow().getGuiScaledHeight();
        int posX = width / 2 + xOffset;
        int posY = height / 2 + Config.TOOLTIP_Y_OFFSET.get();

        posX = Math.min(posX, width - tooltipTextWidth - 20);
        posY = Math.min(posY, height - tooltipHeight - 20);

        float fade = Mth.clamp((hoverTicks + tracker.getGameTimeDeltaTicks()) / 12f, 0, 1);
        Color colorBackground = VANILLA_TOOLTIP_BACKGROUND.scaleAlpha(.75f);
        Color colorBorderTop = VANILLA_TOOLTIP_BORDER_1;
        Color colorBorderBot = VANILLA_TOOLTIP_BORDER_2;

        if (fade < 1) {
            poseStack.translate((1 - fade) * Math.signum(xOffset + .5f) * 4, 0, 0);
            colorBackground.scaleAlpha(fade);
            colorBorderTop.scaleAlpha(fade);
            colorBorderBot.scaleAlpha(fade);
        }
        drawHoveringText(ItemStack.EMPTY, graphics, tooltip, posX, posY, width, height, -1, colorBackground.getRGB(),
                colorBorderTop.getRGB(), colorBorderBot.getRGB(), mc.font);
        poseStack.popPose();
    }

