            return -1;

        }, ItemsRegistry.SPELL_PARCHMENT);

        event.register((stack, color) -> {
            var contents = stack.get(DataComponentRegistry.POTION_JAR);
            if (contents == null) {
                return -1;
            }
            return contents.contents().getColor();
        }, BlockRegistry.POTION_JAR);

