        for (CasterRecipeWrapper g : tomes) {
            entries.put(CasterTomeData.nameKey(g.id()), g.name());
            entries.put(CasterTomeData.flavorKey(g.id()), g.flavorText());
        }

        for (UpdatedRecipeWrapper g : updatedTomes) {
            entries.put(CasterTomeData.nameKey(g.id()), g.name());
            entries.put(CasterTomeData.flavorKey(g.id()), g.flavorText());
        }
        return entries;
    }

