@Override
    protected @NotNull InteractionResult mobInteract(@NotNull Player player, @NotNull InteractionHand hand) {
        if (level().isClientSide || hand != InteractionHand.MAIN_HAND)
            return InteractionResult.SUCCESS;

        ItemStack stack = player.getItemInHand(hand);

        if (player.getMainHandItem().is(Tags.Items.DYES)) {
            DyeColor color = DyeColor.getColor(stack);
            if (color == null || this.entityData.get(COLOR).equals(color.getName()) || !Arrays.asList(EntityWixie.COLORS).contains(color.getName()))
                return InteractionResult.SUCCESS;
            setColor(color);
            return InteractionResult.SUCCESS;
        } else {
            for (BrewingRecipe r : ArsNouveauAPI.getInstance().getAllPotionRecipes(level())) {
                ItemStack water = PotionUtil.getPotion(Potions.WATER);
                ItemStack awkward = PotionUtil.getPotion(Potions.AWKWARD);

                if (r.isIngredient(stack) && (r.getInput().test(awkward) || r.getInput().test(water))) {
                    PotionContents contents = PotionUtil.getContents(r.getOutput());

                    if (!PotionUtil.isEmpty(contents)) {
                        PotionUtil.applyContents(contents, player, player, player);
                        ItemStack potionStack = new ItemStack(Items.POTION);
                        potionStack.set(DataComponents.POTION_CONTENTS, contents);
                        PortUtil.sendMessage(player, Component.translatable("ars_nouveau.wixie_familiar.applied", potionStack.getHoverName().getString()));
                        Networking.sendToNearbyClient(level(), this, new PacketAnimEntity(this.getId(), EntityWixie.Animations.CAST.ordinal()));
                        ParticleUtil.spawnPoof((ServerLevel) level(), player.blockPosition().above());
                        if (!player.hasInfiniteMaterials()) {
                            stack.shrink(1);
                        }
                        return InteractionResult.SUCCESS;
                    }
                }
            }
        }
        return super.mobInteract(player, hand);
    }

public StarbyListBehavior(Starbuncle entity, CompoundTag tag) {
        super(entity, tag);
        int counter = 0;

        while (NBTUtil.hasBlockPos(tag, "from_" + counter)) {
            BlockPos pos = NBTUtil.getBlockPos(tag, "from_" + counter);
            if (!this.FROM_LIST.contains(pos))
                this.FROM_LIST.add(pos);
            counter++;
        }

        counter = 0;
        while (NBTUtil.hasBlockPos(tag, "to_" + counter)) {
            BlockPos pos = NBTUtil.getBlockPos(tag, "to_" + counter);
            if (!this.TO_LIST.contains(pos))
                this.TO_LIST.add(pos);
            counter++;
        }

        for (String key : tag.getAllKeys()) {
            if (key.startsWith("from_direction_")) {
                int hash = Integer.parseInt(key.substring(15));
                FROM_DIRECTION_MAP.put(hash, Direction.from3DDataValue(tag.getInt(key)));
            }
            if (key.startsWith("to_direction_")) {
                int hash = Integer.parseInt(key.substring(13));
                TO_DIRECTION_MAP.put(hash, Direction.from3DDataValue(tag.getInt(key)));
            }
        }

    }

public void addFromPos(BlockPos fromPos) {
        if (!FROM_LIST.contains(fromPos)) {
            FROM_LIST.add(fromPos.immutable());
            syncTag();
        }
    }

public void addToPos(BlockPos toPos) {
        if (!TO_LIST.contains(toPos)) {
            TO_LIST.add(toPos.immutable());
