@SubscribeEvent
    public static void sleepEvent(SleepFinishedTimeEvent event) {
        if (!(event.getLevel() instanceof ServerLevel level)) {
            return;
        }

        var key = level.dimension().location().toString();
        if (!CAT_MAP.posMap.containsKey(key)) {
            return;
        }

        var positions = CAT_MAP.posMap.getOrDefault(key, new HashSet<>());
        List<BlockPos> stale = new ArrayList<>();
        for (BlockPos p : positions) {
            if (!level.isLoaded(p)) {
                continue;
            }

            if (CAT_MAP.removeFunction.apply(level, p)) {
                stale.add(p);
                continue;
            }

            var tile = (MobJarTile) level.getBlockEntity(p);
            var cat = (Cat) tile.getEntity();

            if (!(cat.getOwner() instanceof Player owner) || cat.getRandom().nextFloat() > 0.7F) {
                return;
            }

            if (owner.distanceToSqr(cat) <= 10 * 10 && owner.getSleepTimer() >= 100) {
                LootTable loottable = level.getServer().reloadableRegistries().getLootTable(BuiltInLootTables.CAT_MORNING_GIFT);
                LootParams lootparams = new LootParams.Builder(level)
                        .withParameter(LootContextParams.ORIGIN, cat.position())
                        .withParameter(LootContextParams.THIS_ENTITY, cat)
                        .create(LootContextParamSets.GIFT);

                for (ItemStack itemstack : loottable.getRandomItems(lootparams)) {
                    JarBehavior.insertOrCreateItem(tile, itemstack);
                }
            }
        }

        for (BlockPos pos : stale) {
            CAT_MAP.posMap.get(key).remove(pos);
        }
    }

@Override
    public void tick(MobJarTile tile) {
        if (tile.getLevel().isClientSide || isPowered(tile)) {
            return;
        }
        ExtraData data = new ExtraData(tile.getExtraDataTag());
        Piglin piglin = entityFromJar(tile);
        boolean hasCurrency = piglin.getOffhandItem().isPiglinCurrency();
        if (!hasCurrency && piglin.isAdult() && tile.getLevel().getRandom().nextInt(20) == 0) {
            List<ItemEntity> itemEntities = piglin.level.getEntitiesOfClass(ItemEntity.class, new AABB(tile.getBlockPos()).inflate(3), ItemEntity::isAlive);
            if (!itemEntities.isEmpty()) {
                ItemEntity itemEntity = itemEntities.stream().filter(item -> item.getItem().isPiglinCurrency()).findFirst().orElse(null);
                if (itemEntity != null) {
                    piglin.setItemInHand(InteractionHand.OFF_HAND, itemEntity.getItem().split(1));
                    tile.updateBlock();
                }
            }
        }

        boolean isAdmiring = piglin.isAdult() && piglin.getOffhandItem().isPiglinCurrency();
        if (isAdmiring) {
            data.ticksWithCurrency++;
            if (data.ticksWithCurrency >= 60) {
                data.ticksWithCurrency = 0;
                throwItems(piglin, getBarterResponseItems(piglin));
                piglin.setItemInHand(InteractionHand.OFF_HAND, ItemStack.EMPTY);
                tile.updateBlock();
            }
            CompoundTag updateTag = new CompoundTag();
            data.writeToNBT(updateTag);
            tile.setExtraDataTag(updateTag);
        }
    }

