@Override
    protected boolean handleRecipe(IMappingCollector<NormalizedSimpleStack, Long> mapper, SawmillRecipe recipe, MekFakeGroupHelper fakeGroupHelper, ContextMap contextMap) {
        int primaryMultiplier;
        int secondaryMultiplier;
        if (recipe.getSecondaryChance() > 0 && recipe.getSecondaryChance() < 1) {
            Fraction multiplier;
            try {
                multiplier = Fraction.getFraction(recipe.getSecondaryChance()).invert();
            } catch (ArithmeticException e) {
                //If we couldn't turn it into a fraction, then note we failed to convert the recipe
                return false;
            }
            primaryMultiplier = multiplier.getNumerator();
            secondaryMultiplier = multiplier.getDenominator();
        } else {
            primaryMultiplier = 1;
            secondaryMultiplier = 1;
        }

        if (OPTIMIZE_BASIC && recipe instanceof BasicSawmillRecipe basicRecipe) {
            //This will be the case for the majority of our recipes
            Object2IntMap<NormalizedSimpleStack> ingredients = fakeGroupHelper.forIngredient(recipe.getInput(), contextMap);
            if (ingredients.isEmpty()) {
                return false;
            } else if (primaryMultiplier > 1) {
                ingredients = insertScaled(new Object2IntArrayMap<>(ingredients.size()), ingredients, primaryMultiplier);
            }
            SawmillOutput output = SawmillOutput.create(basicRecipe.getMainOutputRaw().orElse(null),
                  basicRecipe.getSecondaryOutputRaw().orElse(null),
                  primaryMultiplier,
                  secondaryMultiplier
            );
            return addConversions(mapper, output, ingredients);
        }
        Function<SequencedCollection<ItemStack>, Object2IntMap<NormalizedSimpleStack>> representationGetter;
        if (primaryMultiplier == 1) {
            representationGetter = fakeGroupHelper::forItems;
        } else {
            representationGetter = representations -> {
                Object2IntMap<NormalizedSimpleStack> ingredients = fakeGroupHelper.forItems(representations);
                return insertScaled(new Object2IntArrayMap<>(ingredients.size()), ingredients, primaryMultiplier);
            };
        }
        return addConversions(mapper, contextMap, recipe.getInput(), input -> SawmillOutput.create(recipe.getOutput(input), primaryMultiplier, secondaryMultiplier),
              output -> output.mainOutput() == null, representationGetter, ItemStackContentsFactory.INSTANCE, SawmillRecipeMapper::addConversions);
    }

@Override
    public boolean mouseClicked(MouseButtonEvent event, boolean isDoubleClick) {
        hasClicked = true;
        // first try to send the mouse event to our overlays
        GuiWindow top = windows.peek();
        for (GuiWindow overlay : windows) {
            if (overlay.mouseClicked(event, isDoubleClick)) {
                if (windows.contains(overlay)) {
                    //Validate that the focused window is still one of our windows, as if it wasn't focused/on top, and
                    // it is being closed, we don't want to update and mark it as focused, as our defocusing code won't
                    // run as we ran it when we pressed the button
                    setFocused(overlay);
                    if (event.button() == InputConstants.MOUSE_BUTTON_LEFT) {
                        setDragging(true);
                    }
                    // this check prevents us from moving the window to the top of the stack if the clicked window opened up an additional window
                    if (top != overlay) {
                        //noinspection DataFlowIssue: if null, we won't be in this loop
                        top.onFocusLost();
                        windows.moveUp(overlay);
                        overlay.onFocused();
                    }
                }
                return true;
            }
        }
        // otherwise, we send it to the current element (this is the same as super.super [ContainerEventHandler#mouseClicked], but in reverse order)
        //TODO: Why do we do this in reverse order?
        GuiEventListener clickedChild = GuiUtils.findChild(children(), event, isDoubleClick, GuiEventListener::mouseClicked);
        if (clickedChild != null) {
            setFocused(clickedChild);
            if (event.button() == InputConstants.MOUSE_BUTTON_LEFT) {
                setDragging(true);
            }
            return true;
        } else {
            //If we can't find a child, allow clearing whatever focus we currently have
            clearFocus();
        }
        return super.mouseClicked(event, isDoubleClick);
    }

private boolean isVirtualSlotAvailable(IVirtualSlot virtualSlot) {
        // A virtual slot is only considered as available if it is linked to the window, and the window hasn't been closed
        return virtualSlot.getLinkedWindow() instanceof GuiWindow linkedWindow && windows.contains(linkedWindow);
    }

@Override
    protected void extractSlot(GuiGraphicsExtractor graphics, Slot slot, int mouseX, int mouseY) {
        if (!(slot instanceof IVirtualSlot virtualSlot)) {
            //If we are not a virtual slot, the super method is good enough
            super.extractSlot(graphics, slot, mouseX, mouseY);
            return;
        }
        //Basically a copy of super.extractSlot, except with the rendering at the bottom adjusted for if we are a virtual slot
        ItemStack itemStack = slot.getItem();
        boolean quickCraftStack = false;
        ItemStack carried = this.menu.getCarried();
        String itemCount = null;
        if (this.isQuickCrafting && this.quickCraftSlots.contains(slot) && !carried.isEmpty()) {
            if (this.quickCraftSlots.size() == 1) {
                return;
            }

            if (AbstractContainerMenu.canItemQuickReplace(slot, carried, true) && this.menu.canDragTo(slot)) {
                quickCraftStack = true;
                int maxSize = Math.min(carried.getMaxStackSize(), slot.getMaxStackSize(carried));
                int carry = slot.getItem().isEmpty() ? 0 : slot.getItem().getCount();
                int newCount = AbstractContainerMenu.getQuickCraftPlaceCount(this.quickCraftSlots.size(), this.quickCraftingType, carried) + carry;
                if (newCount > maxSize) {
                    newCount = maxSize;
                    itemCount = ChatFormatting.YELLOW.toString() + maxSize;
                }

                itemStack = carried.copyWithCount(newCount);
            } else {
                this.quickCraftSlots.remove(slot);
                recalculateQuickCraftRemaining();
            }
        }
        //Note: We don't include vanilla's no item icon rendering here as virtual slots can just have that set directly, and it simplifies our copy
        //If the slot is a virtual slot, have the GuiSlot that corresponds to it handle the rendering
        virtualSlot.updateRenderInfo(itemStack, slot == this.hoveredSlot, quickCraftStack, itemCount);
    }

