private void recheckItem() {
        ItemResource type = itemSupplier.get();
        if (!currentItem.equals(type)) {
            updateItemAndList(type);
            ModuleData<?> prevSelect = getSelection();
            if (prevSelect != null) {
                if (currentList.contains(prevSelect)) {
                    //The item still supports the existing selection, mark that the selected data changed
                    onSelectedChange();
                } else {
                    //Otherwise, it doesn't have the same type still, we need to clear the current selection
                    clearSelection();
                }
            }
        }
    }

@Override
    public void syncFrom(GuiElement element) {
        super.syncFrom(element);
        GuiModuleScrollList old = (GuiModuleScrollList) element;
        if (currentItem.equals(old.currentItem)) {
            //If the item is the same just change what module data we have as our selected
            // and don't notify the callback with a fresh read of the module data as it
            // should have the data it expects already
            selectedType = old.selectedType;
        } else if (old.selectedType != null) {
            if (currentList.contains(old.selectedType)) {
                //If the item doesn't match (in general it will) and it still has the corresponding module,
                // we need to update the selected value and fire the corresponding callbacks
                setSelected(old.selectedType);
            } else {
                //If the data is no longer present we need to fire the callbacks to ensure we propagate the clear to the current selection
                onSelectedChange();
            }
        }
    }

@Override
    protected boolean setText(GuiTextField text) {
        String name = text.getText();
        if (name.isEmpty()) {
            filterSaveFailed(getNoFilterSaveError());
            return false;
        }
        String modid = "c";
        String newFilter = name.toLowerCase(Locale.ROOT);
        if (newFilter.contains(":")) {
            String[] split = newFilter.split(":");
            modid = split[0];
            newFilter = split[1];
            if (modid.contains("/")) {
                filterSaveFailed(MekanismLang.OREDICTIONIFICATOR_FILTER_INVALID_NAMESPACE);
                return false;
            }
        }
        if (newFilter.contains(":")) {
            filterSaveFailed(MekanismLang.OREDICTIONIFICATOR_FILTER_INVALID_PATH);
            return false;
        }
        Identifier filterLocation = Identifier.fromNamespaceAndPath(modid, newFilter);
        if (filter.hasFilter() && filter.filterMatches(filterLocation)) {
            filterSaveFailed(MekanismLang.TAG_FILTER_SAME_TAG);
        } else if (TileEntityOredictionificator.isValidTarget(filterLocation)) {
            filter.setFilter(filterLocation);
            slotDisplay.updateStackList();
            text.setText("");
            return true;
        } else {
            filterSaveFailed(MekanismLang.OREDICTIONIFICATOR_FILTER_UNSUPPORTED_TAG);
        }
        return false;
    }

