public static AllModuleData fromDataMaps(Registry<Item> itemRegistry) {
            Map<ResourceKey<Item>, HolderSet<ModuleData<?>>> dataMap = itemRegistry.getDataMap(IMekanismDataMapTypes.INSTANCE.supportedModules());
            if (dataMap.isEmpty()) {
                return EMPTY;
            }

            ReferenceSet<Item> moduleContainers = new ReferenceOpenHashSet<>();
            Reference2ObjectMap<Item, ReferenceSet<ModuleData<?>>> supportedModules = new Reference2ObjectOpenHashMap<>();
            Reference2ObjectMap<ModuleData<?>, ReferenceSet<Item>> supportedContainers = new Reference2ObjectOpenHashMap<>();

            for (Map.Entry<ResourceKey<Item>, HolderSet<ModuleData<?>>> entry : dataMap.entrySet()) {
                ResourceKey<Item> key = entry.getKey();
                Item moduleContainer = itemRegistry.getValue(key);
                if (moduleContainer == null) {
                    Mekanism.logger.error("Unable to locate module container item: '{}' for supported modules: {}", key.identifier(), entry.getValue());
                } else {
                    ReferenceSet<ModuleData<?>> modules = new ReferenceOpenHashSet<>();
                    for (Holder<ModuleData<?>> moduleHolder : entry.getValue()) {
                        ModuleData<?> module = moduleHolder.value();
                        modules.add(module);
                        supportedContainers.computeIfAbsent(module, _ -> new ReferenceOpenHashSet<>())
                              .add(moduleContainer);
                    }
                    if (modules.isEmpty()) {
                        Mekanism.logger.warn("Attempted to add zero supported modules to module container item: '{}'; not added as a module container.", key.identifier());
                    } else {
                        moduleContainers.add(moduleContainer);
                        supportedModules.put(moduleContainer, modules);
                    }
                }
            }
            if (moduleContainers.isEmpty()) {
                return EMPTY;
            }
            //Calculate conflicting modules
            Reference2ObjectMap<ModuleData<?>, ReferenceSet<ModuleData<?>>> conflictingModules = new Reference2ObjectOpenHashMap<>();
            for (ObjectIterator<Reference2ObjectMap.Entry<ModuleData<?>, ReferenceSet<Item>>> iterator = Reference2ObjectMaps.fastIterator(supportedContainers); iterator.hasNext(); ) {
                Reference2ObjectMap.Entry<ModuleData<?>, ReferenceSet<Item>> entry = iterator.next();
                ModuleData<?> moduleType = entry.getKey();
                ReferenceSet<ModuleData<?>> conflicting = new ReferenceOpenHashSet<>();
                for (Item item : entry.getValue()) {
                    for (ModuleData<?> other : supportedModules.getOrDefault(item, ReferenceSets.emptySet())) {
                        if (moduleType != other && moduleType.isExclusive(other.getExclusiveFlags())) {
                            conflicting.add(other);
                        }
                    }
                }
                if (!conflicting.isEmpty()) {
                    conflictingModules.put(moduleType, conflicting);
                }
            }
            return new AllModuleData(ReferenceSets.unmodifiable(moduleContainers), unmodifiable(supportedModules),
                  unmodifiable(supportedContainers), unmodifiable(conflictingModules));
        }

public Set<ModuleData<?>> getSupported(Item item) {
            return supportedModules.getOrDefault(item, ReferenceSets.emptySet());
        }

public Set<Item> getSupportedItems(Holder<ModuleData<?>> type) {
            return supportedContainers.getOrDefault(type.value(), ReferenceSets.emptySet());
        }

public Set<ModuleData<?>> getConflicting(Holder<ModuleData<?>> type) {
            return conflictingModules.getOrDefault(type.value(), ReferenceSets.emptySet());
        }

private static InteractionResult transformAOE(UseOnContext context, BlockState clickedState, EnergyHandler energyHandler, int diameter, TransactionContext transaction,
          ResourceKey<BlockTransformer> transformer, int energyUsage, IToolAOEData toolAOEData) {
        Reference<BlockTransformer> holder = context.getLevel().registryAccess().getOrThrow(transformer);
        Iterable<BlockTransformData> transforms = DataMapHooks.getAllTransformers(holder);
        Player player = context.getPlayer();
        if (player != null && !MekanismUtils.isPlayingMode(player)) {
            energyUsage = 0;
        }
        Level level = context.getLevel();
        BlockPos pos = context.getClickedPos();
        Direction clickedFace = context.getClickedFace();
        ItemStack itemInHand = context.getItemInHand();
        BlockState modifiedState = null;
        BlockTransformer.BlockTransformData chosenTransform = null;
        int theoreticalAvailableEnergy = -1;
        for (BlockTransformer.BlockTransformData transformData : transforms) {
            if (!transformData.disallowedFaces().contains(clickedFace)) {
                BlockState newBlockState = transformData.blockStateProvider().value().getOptionalState(level, level.getRandom(), pos);
                if (newBlockState != null) {
                    //Scale up (or down) how much energy each action costs based on how much damage is done per usage
                    int scaledEnergyUsage = energyUsage * transformData.itemDamagePerUse();
                    if (scaledEnergyUsage > 0) {
                        if (theoreticalAvailableEnergy != -1 && scaledEnergyUsage > theoreticalAvailableEnergy) {
                            //We need more energy than the max amount we already know can be extracted checked an amount higher than what we have available,
                            // and we know we won't have enough for this either, so skip
                            continue;
                        }
                        try (Transaction subTransaction = Transaction.open(transaction)) {
                            int extracted = energyHandler.extract(scaledEnergyUsage, subTransaction);
                            if (extracted < scaledEnergyUsage) {
                                //We don't have enough energy to extracting from our container, skip to the next valid transform as maybe it costs less energy
                                theoreticalAvailableEnergy = extracted;
                                continue;
                            } else if (!level.isClientSide()) {
                                //Consume energy for primary target block
                                subTransaction.commit();
                            }
                        }
                    }
                    modifiedState = newBlockState;
                    chosenTransform = transformData;
                    //Scale up (or down) how much energy each action costs based on how much damage is done per usage
                    energyUsage = scaledEnergyUsage;
                    break;
                }
            }
        }
        if (modifiedState == null) {
            //Skip modifying the blocks if the one we clicked cannot be modified
            return InteractionResult.PASS;
        } else if (level.isClientSide()) {
            return InteractionResult.SUCCESS;
        }
        //Process the block we interacted with initially and play the sound
        applyTransform(level, pos, clickedFace, modifiedState, clickedState, player, itemInHand, chosenTransform, toolAOEData);
        for (BlockPos newPos : toolAOEData.getTargetPositions(pos, clickedFace, (diameter - 1) / 2)) {
            if (pos.equals(newPos)) {
                //Skip the source position as we manually handled it before the loop
                continue;
            }
            try (Transaction subTransaction = Transaction.open(transaction)) {
                if (energyUsage > 0 && energyHandler.extract(energyUsage, subTransaction) < energyUsage) {
                    //We don't have enough energy to continue extracting from our container, break
                    break;
                }
                //Check to make that the result we would get from modifying the other block is the same as the one we got on the initial block we interacted with
                // Also make sure that it is properly valid
                if (modifiedState == chosenTransform.blockStateProvider().value().getOptionalState(level, level.getRandom(), newPos)) {
                    //Some of the below methods don't behave properly when the BlockPos is mutable, so now that we are onto ones where it may actually
                    // matter we make sure to get an immutable instance of newPos
                    newPos = newPos.immutable();
                    //Update energy cost
                    subTransaction.commit();
                    BlockState oldBlockState = level.getBlockState(newPos);
                    applyTransform(level, newPos, clickedFace, modifiedState, oldBlockState, player, itemInHand, chosenTransform, toolAOEData);
                    PacketUtils.sendToAllTracking(new PacketLightningRender(LightningPreset.TOOL_AOE, 31 * pos.hashCode() + newPos.hashCode(),
                          toolAOEData.getLightningPos(pos, clickedFace), toolAOEData.getLightningPos(newPos, clickedFace), 10), level, pos);
                }
            }
        }
        return InteractionResult.SUCCESS;
    }

@Override
    public <ITEM extends TypedInstance<Item> & DataComponentGetter> boolean canPerformAction(IModule<ModuleShearingUnit> module, IModuleContainer container, ITEM instance,
          ItemAbility action) {
        //Note: If for some reason we are installed on something that is not the Meka-Tool don't stop the action from being enabled
        // as it may not actually require energy
        if (instance.is(MekanismAPITags.Items.MODULE_CONTAINERS_HELD_MEKA_TOOL)) {
            if (action == ItemAbilities.SHEARS_DISARM) {
                //Only require energy if we are installed on a Meka-Tool and can thus calculate the energy required to break the block "safely"
                // Note: We assume hardness is zero like the default is for tripwires as we don't have the target block in our current context
                int cost = ItemMekaTool.getDestroyEnergy(container, 0, container.hasEnabled(MekanismModules.SILK_TOUCH_UNIT));
                return module.hasEnoughEnergy(ItemAccessUtils.sideEffectFreeAccess(instance), cost);
            } else if (action == ItemAbilities.SHEARS_DIG) {
                EnergyHandler energyHandler = module.getEnergyHandler(ItemAccessUtils.sideEffectFreeAccess(instance), true);
                if (energyHandler == null) {
                    return false;
                }
                //Note: We use a hardness of zero here as that will get the minimum potential destroy energy required
                // as that is the best guess we can currently give whether the corresponding dig action is supported
                int energyRequired = ItemMekaTool.getDestroyEnergy(container, 0, container.hasEnabled(MekanismModules.SILK_TOUCH_UNIT));
                int energyAvailable = energyHandler.getAmountAsInt();
                //If we don't have enough energy to break at full speed check if the reduced speed could actually mine
                return energyRequired <= energyAvailable || ((double) energyAvailable / energyRequired) > Mth.EPSILON;
            } else if (action == ItemAbilities.SHEARS_TRIM) {
                return module.hasEnoughEnergy(ItemAccessUtils.sideEffectFreeAccess(instance), MekanismConfig.gear.mekaToolEnergyUsageShearTrim);
            }
        }
        return ItemAbilities.DEFAULT_SHEARS_ACTIONS.contains(action);
    }

