@Override
    public InteractionResult onItemUseFirst(ItemStack stack, UseOnContext context) {
        Player player = context.getPlayer();
        if (stack.isEmpty() || player == null) {
            return InteractionResult.PASS;
        } else if (!player.isShiftKeyDown() && !BlockData.hasData(stack)) {
            Level world = context.getLevel();
            BlockPos pos = context.getClickedPos();
            BlockState state = world.getBlockState(pos);
            if (state.is(MekanismTags.Blocks.CARDBOARD_BLACKLIST)) {
                //Note: While this is slightly redundant with the relocability check below, we check it any way,
                // as for balance reasons we don't allow moving spawners by default
                return InteractionResult.FAIL;
            } else if (!state.isAir() && state.getDestroySpeed(world, pos) != Block.INDESTRUCTIBLE) {
                BlockRelocability relocability = state.getRelocability(world, pos);
                if (!relocability.isRelocatable(Set.of(pos))) {
                    return InteractionResult.FAIL;
                }
                Identifier stateName = RegistryUtils.getName(state.typeHolder());
                if (stateName == null || MekanismConfig.general.cardboardModBlacklist.get().contains(stateName.getNamespace()) ||
                    !canReplace(world, player, pos, context.getClickedFace(), state, stack)) {
                    return InteractionResult.FAIL;
                }
                BlockEntity tile = WorldUtils.getTileEntity(world, pos);
                if (!IBlockSecurityUtils.INSTANCE.canAccessOrDisplayError(player, world, pos, tile)) {
                    //If the tile is in the tile entity type blacklist or the player cannot access the tile
                    // don't allow them to pick it up with a cardboard box
                    return InteractionResult.FAIL;
                }
                if (!world.isClientSide()) {
                    BlockData data = new BlockData(world.registryAccess(), state, tile);
                    stack.consume(1, player);
                    //Mark that we are monitoring item drops that might have been created due to using the cardboard box
                    // and then replace the block with the cardboard box, which will cause items to drop and then get
                    // cancelled by our listener in CommonWorldTickHandler
                    Mekanism.worldTickHandler.monitoringCardboardBox = true;
                    world.setBlock(pos, getBlock().defaultBlockState().setValue(BlockStateHelper.storageProperty, true), Block.UPDATE_ALL | Block.UPDATE_SUPPRESS_DROPS);
                    Mekanism.worldTickHandler.monitoringCardboardBox = false;
                    TileEntityCardboardBox box = WorldUtils.getTileEntity(TileEntityCardboardBox.class, world, pos);
                    if (box != null) {
                        box.setComponents(DataComponentMap.builder()
                              .addAll(box.components())
                              .set(MekanismDataComponents.BLOCK_DATA, data)
                              .build());
                    }
                }
                return InteractionResult.SUCCESS;
            }
        }
        return InteractionResult.PASS;
    }

private UpgradeBasedUnsignedLongCache(ItemAccess attachedAccess, LongSupplier baseStorage) {
            this.attachedAccess = attachedAccess;
            UpgradeAware upgradeAware = this.attachedAccess.getResource().getOrDefault(MekanismDataComponents.UPGRADES, UpgradeAware.EMPTY);
            this.lastInstalled = upgradeAware.getUpgradeCount(UpgradeIds.ENERGY);
            this.baseStorage = baseStorage;
            this.value = this.lastInstalled.getMaxEnergy(this.baseStorage.getAsLong());
        }

@Override
        public long getAsLong() {
            UpgradeAware upgradeAware = attachedAccess.getResource().getOrDefault(MekanismDataComponents.UPGRADES, UpgradeAware.EMPTY);
            UpgradeAmount installed = upgradeAware.getUpgradeCount(UpgradeIds.ENERGY);
            if (!installed.equals(lastInstalled)) {
                lastInstalled = installed;
                value = this.lastInstalled.getMaxEnergy(baseStorage.getAsLong());
            }
            return value;
        }

@SuppressWarnings("unchecked")
    default <FREQ extends Frequency> void syncColorWithFrequency(ItemStack stack) {
        DataComponentType<FrequencyAware<FREQ>> frequencyComponent = (DataComponentType<FrequencyAware<FREQ>>) getFrequencyComponent();
        if (frequencyComponent != null) {
            FrequencyAware<FREQ> frequencyAware = stack.getOrDefault(frequencyComponent, FrequencyAware.none());
            if (frequencyAware.frequency().orElse(null) instanceof IColorableFrequency frequency) {
                stack.set(MekanismDataComponents.COLOR, frequency.getColor());
            } else {
                stack.remove(MekanismDataComponents.COLOR);
            }
        }
    }

