        UUID owner = IItemSecurityUtils.INSTANCE.getOwnerUUID(itemAccess);
        if (owner == null) {
            Mekanism.logger.error("Storage inventory asked for but item type has no owner! {}", itemAccess.getResource(), new Exception());
