@Override
    protected void applyImplicitComponents(DataComponentGetter input) {
        super.applyImplicitComponents(input);
        // Check if the stack has a custom name, and if the tile supports naming, name it
        if (isNameable()) {
            setCustomName(input.get(DataComponents.CUSTOM_NAME));
        }

        for (ITileComponent component : components) {
            component.applyImplicitComponents(input);
        }
        //Recalculate upgrades before setting types so that we don't clamp the stored energy
        TagKey<Upgrade> supportedUpgrade = getSupportedUpgrade();
        if (supportedUpgrade != null && upgradesRegistry != null) {
            //The level should theoretically always be present here (and thus the upgrades registry should be present)
            Optional<Named<Upgrade>> tag = upgradesRegistry.get(supportedUpgrade);
            if (tag.isPresent()) {
                for (Holder<Upgrade> upgrade : tag.get()) {
                    recalculateUpgrades(upgradesRegistry, upgrade, getUpgrades(upgrade));
                }
            }
        }

        for (IContainerType<?, ?> type : ContainerType.TYPES) {
            if (persistsToItem(type)) {
                type.copyToTile(this, input);
            }
        }
        if (this instanceof ITileFilterHolder<?> filterHolder) {
            FilterAware filterAware = input.get(MekanismDataComponents.FILTER_AWARE);
            if (filterAware != null) {
                //TODO - 1.20.4: Do we need to copy these or can we just pass the raw instance?
                filterHolder.getFilterManager().trySetFilters(filterAware.filters());
            }
        }
        if (supportsRedstone()) {
            setControlType(input.getOrDefault(MekanismDataComponents.REDSTONE_CONTROL, RedstoneControl.DISABLED));
        }
    }

@Override
    public List<DataComponentType<?>> getRemapEntries() {
        List<DataComponentType<?>> remapEntries = super.getRemapEntries();
        for (ITileComponent component : components) {
            component.addRemapEntries(remapEntries);
        }
        for (IContainerType<?, ?> type : ContainerType.TYPES) {
            if (persistsToItem(type)) {
                DataComponentType<?> componentType = type.getComponentType().get();
                if (!remapEntries.contains(componentType)) {
                    //Ensure we add any container types that we only conditionally added
                    remapEntries.add(componentType);
                }
            }
        }
        if (this instanceof ITileFilterHolder<?> && !remapEntries.contains(MekanismDataComponents.FILTER_AWARE.get())) {
            remapEntries.add(MekanismDataComponents.FILTER_AWARE.get());
        }
        return remapEntries;
    }

private float damageShield(Level level, LivingEntity livingEntity, Vec3 from, float damage) {
        DamageSource source = MekanismDamageTypes.LASER.source(level, from);
        //Absorb part of the damage based on the given absorption ratio
        DamageContainer damageContainer = new DamageContainer(source, damage);
        //Note: Even though we fire this even here manually, it doesn't cause issues with the damage pipeline
        // as if we do block damage, then we won't end up firing the normal pipeline
        ItemStack blockingWith = livingEntity.getItemBlockingWith();
        if (blockingWith == null) {
            return 0;
        }
        BlocksAttacks blocksAttacks = blockingWith.get(DataComponents.BLOCKS_ATTACKS);
        if (blocksAttacks == null) {
            return 0;
        }
        HolderSet<DamageType> bypassedBy = blocksAttacks.bypassedBy().orElse(null);
        boolean originallyBlocked = bypassedBy != null && !bypassedBy.contains(source.typeHolder());
        float damageBlocked = 0;
        //assuming if it was bypassed we don't need to calculate this?
        if (originallyBlocked) {
            double angle = getAngle(livingEntity, from);
            damageBlocked = blocksAttacks.resolveBlockedDamage(source, damage, angle);
        }
        LivingShieldBlockEvent event = CommonHooks.onDamageBlock(livingEntity, damageContainer, damageBlocked, originallyBlocked);
        if (!event.getBlocked()) {
            //Blocking was not allowed, return we didn't block any damage
            return 0;
        }
        int shieldDamage = event.shieldDamage();
        if (shieldDamage > 0) {
            //Only damage the shield if the shield isn't setup to block damage for free
            blocksAttacks.hurtBlockingItem(level, blockingWith, livingEntity, livingEntity.getUsedItemHand(), damageBlocked, shieldDamage);
        }
        damageBlocked = event.getBlockedDamage();
        if (livingEntity instanceof Player player && damageBlocked > 0 && damageBlocked < 3.4028235E37F) {
            player.awardStat(Stats.DAMAGE_BLOCKED_BY_SHIELD, Math.round(damageBlocked * 10F));
        }
        return damageBlocked;
    }

public static boolean isSavedReplaceTarget(ItemAccess itemAccess, ItemResource target) {
        ItemResource itemType = itemAccess.getResource();
        if (itemType.isEmpty()) {
            return false;
        }
        //This method is here to make it easier to maintain parity if we change the logic of isReplaceTarget
        if (itemType.getOrDefault(MekanismDataComponents.INVERSE, false)) {
            Item inverseReplaceTarget = itemType.getOrDefault(MekanismDataComponents.REPLACE_STACK, Items.AIR);
            return inverseReplaceTarget != Items.AIR && target.is(inverseReplaceTarget);
        }
        FilterAware filterAware = itemType.get(MekanismDataComponents.FILTER_AWARE);
        return filterAware != null && filterAware.anyEnabledMatch(MinerFilter.class, filter -> filter.replaceTargetMatches(target));
    }

@Override
    public void loadAdditional(ValueInput input) {
        super.loadAdditional(input);
        running = input.getBooleanOr(SerializationConstants.RUNNING, false);
        delay = input.getIntOr(SerializationConstants.DELAY, 0);
        numPowering = input.getIntOr(SerializationConstants.NUM_POWERING, 0);
        searcher.state = input.read(SerializationConstants.STATE, State.CODEC).orElse(State.IDLE);
        if (!initCalc && searcher.state == State.SEARCHING) {
            //If we loaded and haven't started yet, but we were searching when we saved
            // pretend we had finished searching so that we will start again on the first tick
            searcher.state = State.FINISHED;
        }
        //Update energy per tick in case any of the values changed. It would be slightly cleaner to also validate the fact
        // the values changed, but it would make the code a decent bit messier, as we couldn't use NBTUtils, and it is a
        // rather quick check to update the energy per tick, and in most cases at least one of the settings will not be at
        // the default value
        energyContainer.updateMinerEnergyPerTick();
    }

