private static <R> IRecipeLayoutDrawable<R> createLayoutForPrefix(IRecipeType<R> recipeType, String prefix) {
		var manager = Internal.getJeiRuntime().getRecipeManager();
		var category = manager.getRecipeCategory(recipeType);
		var recipe = manager.createRecipeLookup(recipeType).get()
			.filter(value -> Objects.requireNonNull(category.getIdentifier(value)).getPath().startsWith(prefix))
			.findFirst().orElseThrow(() -> new AssertionError("No recipe found for " + recipeType + ": " + prefix));
		return createLayout(category, recipe);
	}

private static <R> Identifier getIdentifier(IRecipeLayoutDrawable<R> layout) {
		return Objects.requireNonNull(layout.getRecipeCategory().getIdentifier(layout.getRecipe()));
	}

private static void assertTooltipIds(IRecipeLayoutDrawable<?> layout, List<Identifier> expectedIds) {
		check(layout.getSourceRecipeIds().equals(expectedIds), "Layout source IDs must match the tooltip IDs");
		var output = layout.getRecipeSlotsView().getSlotViews().stream().filter(slot -> slot.getRole() == RecipeIngredientRole.OUTPUT)
			.map(IRecipeSlotDrawable.class::cast).findFirst().orElseThrow();
		var tooltip = new JeiTooltip();
		output.getTooltip(tooltip);
		var lines = tooltip.getLines().stream().flatMap(line -> line.left().stream()).map(text -> text.getString()).toList();
		var expectedLines = expectedIds.stream().map(id -> Component.translatable("jei.tooltip.recipe.id", Component.literal(id.toString())).getString()).toList();
		var actualLines = lines.stream().filter(line -> line.startsWith("Recipe ID: ")).toList();
		check(actualLines.equals(expectedLines), "Tooltip recipe IDs must match the sources: " + actualLines);
	}

private static void check(boolean condition, String message) {
		if (!condition) {
			throw new AssertionError(message);
		}
	}

public static IServerConfig register() {
		var config = mezz.jei.common.config.ServerConfig.register();
		Path legacyConfig = FabricLoader.getInstance().getConfigDir().resolve("jei-server.properties");
		ServerLifecycleEvents.SERVER_STARTING.register(server -> {
			Path worldConfigDirectory = server.getWorldPath(LevelResource.ROOT).resolve("serverconfig");
			config.prepareLegacyMigration(worldConfigDirectory, List.of(legacyConfig));
		});
		Identifier migrationPhase = Identifier.fromNamespaceAndPath(ModIds.JEI_ID, "migrate_server_config");
		ServerLifecycleEvents.SERVER_STARTED.addPhaseOrdering(Event.DEFAULT_PHASE, migrationPhase);
		ServerLifecycleEvents.SERVER_STARTED.register(migrationPhase, server -> config.migrateLegacyConfig());
		return config;
	}

FabricKeyModifier(int mask, String translationKey) {
		this.mask = mask;
		this.translationKey = translationKey;
	}

public static EnumSet<FabricKeyModifier> fromMask(int mask) {
		EnumSet<FabricKeyModifier> modifiers = EnumSet.noneOf(FabricKeyModifier.class);
		for (FabricKeyModifier modifier : values()) {
			if ((mask & modifier.mask) != 0) {
				modifiers.add(modifier);
			}
		}
		return modifiers;
	}

public static int toMask(Set<FabricKeyModifier> modifiers) {
		int mask = 0;
		for (FabricKeyModifier modifier : modifiers) {
			mask |= modifier.mask;
		}
		return mask;
	}

public static Set<FabricKeyModifier> from(JeiKeyModifier modifier) {
		return switch (modifier) {
			case NONE -> Set.of();
			case SHIFT -> Set.of(SHIFT);
			case CONTROL -> Set.of(CONTROL);
			case ALT -> Set.of(ALT);
			case CONTROL_OR_COMMAND -> {
				if (InputQuirks.REPLACE_CTRL_KEY_WITH_CMD_KEY) {
					yield Set.of(COMMAND);
				}
				yield Set.of(CONTROL);
			}
		};
	}

public static @Nullable FabricKeyModifier forKey(int key) {
		return switch (key) {
			case InputConstants.KEY_LSHIFT, InputConstants.KEY_RSHIFT -> SHIFT;
			case InputConstants.KEY_LCONTROL, InputConstants.KEY_RCONTROL -> CONTROL;
			case InputConstants.KEY_LALT, InputConstants.KEY_RALT -> ALT;
			case InputConstants.KEY_LGUI, InputConstants.KEY_RGUI -> COMMAND;
			default -> null;
		};
	}

public static EnumSet<FabricKeyModifier> current() {
		Minecraft minecraft = Minecraft.getInstance();
		EnumSet<FabricKeyModifier> modifiers = EnumSet.noneOf(FabricKeyModifier.class);
		if (minecraft.hasShiftDown()) {
			modifiers.add(SHIFT);
		}
		if (minecraft.hasControlDown()) {
			modifiers.add(CONTROL);
		}
		if (minecraft.hasAltDown()) {
			modifiers.add(ALT);
		}
		if (InputConstants.isKeyDown(InputConstants.KEY_LGUI) || InputConstants.isKeyDown(InputConstants.KEY_RGUI)) {
			modifiers.add(COMMAND);
		}
		return modifiers;
	}

public static Component getCombinedName(Set<FabricKeyModifier> modifiers, Component keyName) {
		for (FabricKeyModifier modifier : values()) {
			if (modifiers.contains(modifier)) {
				keyName = Component.translatable(modifier.translationKey, keyName);
			}
		}
		return keyName;
	}

