private void registerEvents() {
        Minecraft client = Minecraft.getInstance();
        final Identifier recipeButtonTex = Identifier.withDefaultNamespace("textures/gui/recipe_button.png");
        MutableLong endReload = new MutableLong(-1);
        PRE_UPDATE_RECIPES.register((recipeAccess, registryAccess) -> {
            reloadPlugins(null, ReloadStage.START, registryAccess);
        });
        ClientRecipeUpdateEvent.EVENT.register(recipeManager -> {
            reloadPlugins(endReload, ReloadStage.END);
        });
        ClientRecipeUpdateEvent.ADD.register((recipeAccess, entries) -> {
            if (ClientHelperImpl.getInstance().canUsePackets()) {
                return;
            }

            InternalLogger.getInstance().debug("Received server's request to add %d recipes.", entries.size());
            DisplayRegistryImpl registry = (DisplayRegistryImpl) DisplayRegistry.getInstance();
            List<RecipeDisplayEntry> mapped = CollectionUtils.map(entries, ClientboundRecipeBookAddPacket.Entry::contents);
            // Record the server-advertised ids so the local fallback can dedup against them.
            ClientRecipeFallback.onServerRecipeBookAdd(CollectionUtils.map(mapped, RecipeDisplayEntry::id));
            registry.addJob(() -> registry.addRecipes(mapped));
        });
        ClientRecipeUpdateEvent.REMOVE.register((recipeAccess, entries) -> {
            if (ClientHelperImpl.getInstance().canUsePackets()) {
                return;
            }

            InternalLogger.getInstance().debug("Received server's request to remove %d recipes.", entries.size());
            DisplayRegistryImpl registry = (DisplayRegistryImpl) DisplayRegistry.getInstance();
            Set<RecipeDisplayId> ids = new HashSet<>(entries);
            ClientRecipeFallback.onServerRecipeBookRemove(ids);
            registry.addJob(() -> registry.removeRecipes(ids));
        });
        ClientPlayerEvent.CLIENT_PLAYER_QUIT.register(player -> {
            InternalLogger.getInstance().debug("Player quit, clearing reload tasks!");
            endReload.setValue(-1);
            ReloadManagerImpl.terminateReloadTasks();
            ClientRecipeFallback.reset();
        });
        ClientGuiEvent.INIT_PRE.register((screen, access) -> {
            List<ReloadStage> stages = ((PluginManagerImpl<REICommonPlugin>) PluginManager.getInstance()).getObservedStages();

            if (Minecraft.getInstance().level != null && Minecraft.getInstance().player != null && stages.contains(ReloadStage.START)
                    && !stages.contains(ReloadStage.END) && !PluginManager.areAnyReloading() && screen instanceof AbstractContainerScreen) {
                if (ReloadManagerImpl.countRunningReloadTasks() > 0) {
                    return EventResult.pass();
                }

                InternalLogger.getInstance().error("Detected missing stage: END! This is possibly due to issues during client recipe reload! REI will force a reload of the recipes now!");
                reloadPlugins(endReload, ReloadStage.END);
            }

            return EventResult.pass();
        });
        ClientGuiEvent.INIT_POST.register((screen, access) -> {
            REIRuntime.getInstance().getOverlay(false, true);
            if (Minecraft.getInstance().gui.screen() == screen) {
                if (REIRuntime.getInstance().getPreviousScreen() != screen) {
                    OverlaySearchField searchField = REIRuntimeImpl.getSearchField();

                    if (searchField != null) {
                        searchField.setFocused(false);
                    }
                }

                REIRuntimeImpl.getInstance().setPreviousScreen(screen);
                ((ScreenRegistryImpl) ScreenRegistry.getInstance()).getLastRendererProvider(screen);
            }
            if (ConfigObject.getInstance().doesDisableRecipeBook() && screen instanceof AbstractContainerScreen) {
                access.getRenderables().removeIf(widget -> widget instanceof ImageButton button && button.sprites.enabled().equals(recipeButtonTex));
                access.getNarratables().removeIf(widget -> widget instanceof ImageButton button && button.sprites.enabled().equals(recipeButtonTex));
                screen.children().removeIf(widget -> widget instanceof ImageButton button && button.sprites.enabled().equals(recipeButtonTex));
            }
        });
        ClientScreenInputEvent.MOUSE_CLICKED_PRE.register((minecraftClient, screen, event, doubleClick) -> {
            isLeftMousePressed = true;
            if (shouldReturn(screen) || screen instanceof DisplayScreen)
                return EventResult.pass();
            resetFocused(screen);
            if (getOverlay().mouseClicked(event, doubleClick)) {
                if (event.button() == 0) {
                    screen.setDragging(true);
                }
                resetFocused(screen);
                return EventResult.interruptFalse();
            }
            return EventResult.pass();
        });
        ClientScreenInputEvent.MOUSE_RELEASED_PRE.register((minecraftClient, screen, event) -> {
            isLeftMousePressed = false;
            if (shouldReturn(screen) || screen instanceof DisplayScreen)
                return EventResult.pass();
            resetFocused(screen);
            if (REIRuntime.getInstance().isOverlayVisible() && getOverlay().mouseReleased(event)
                    && resetFocused(screen)) {
                return EventResult.interruptFalse();
            }
            return EventResult.pass();
        });
        ClientScreenInputEvent.MOUSE_SCROLLED_PRE.register((minecraftClient, screen, mouseX, mouseY, amountX, amountY) -> {
            if (shouldReturn(screen) || screen instanceof DisplayScreen)
                return EventResult.pass();
            resetFocused(screen);
            if (REIRuntime.getInstance().isOverlayVisible() && getOverlay().mouseScrolled(mouseX, mouseY, amountX, amountY)
                    && resetFocused(screen))
                return EventResult.interruptFalse();
            return EventResult.pass();
        });
        ClientScreenInputEvent.CHAR_TYPED_PRE.register((minecraftClient, screen, event) -> {
            if (shouldReturn(screen) || screen instanceof DisplayScreen)
                return EventResult.pass();
            if (!REIRuntimeImpl.getSearchField().isFocused()) {
                GuiEventListener focused = screen.getFocused();
                if (focused != null) {
                    if (focused instanceof EditBox editBox && editBox.isFocused()) return EventResult.pass();
                    if (focused instanceof RecipeBookComponent book && book.searchBox != null && book.searchBox.isFocused()) return EventResult.pass();
                }
            }
            resetFocused(screen);
            if (getOverlay().charTyped(event)
                    && resetFocused(screen))
                return EventResult.interruptFalse();
            return EventResult.pass();
        });
        ClientScreenInputEvent.MOUSE_DRAGGED_PRE.register((minecraftClient, screen, event, mouseX2, mouseY2) -> {
            if (shouldReturn(screen) || screen instanceof DisplayScreen)
                return EventResult.pass();
            resetFocused(screen);
            if (getOverlay().mouseDragged(event, mouseX2, mouseY2)
                    && resetFocused(screen))
                return EventResult.interruptFalse();
            return EventResult.pass();
        });
        ClientScreenInputEvent.KEY_PRESSED_PRE.register((minecraftClient, screen, event) -> {
            if (shouldReturn(screen) || screen instanceof DisplayScreen)
                return EventResult.pass();
            if (screen instanceof AbstractContainerScreen && ConfigObject.getInstance().doesDisableRecipeBook() && ConfigObject.getInstance().doesFixTabCloseContainer()) {
                if (event.key() == 258 && minecraftClient.options.keyInventory.matches(event)) {
                    minecraftClient.player.closeContainer();
                    return EventResult.interruptFalse();
                }
            }
            if (!REIRuntimeImpl.getSearchField().isFocused()) {
                GuiEventListener focused = screen.getFocused();
                if (focused != null) {
                    if (focused instanceof EditBox editBox && editBox.isFocused()) return EventResult.pass();
                    if (focused instanceof RecipeBookComponent book && book.searchBox != null && book.searchBox.isFocused()) return EventResult.pass();
                }
            }
            resetFocused(screen);
            if (getOverlay().keyPressed(event)
                    && resetFocused(screen))
                return EventResult.interruptFalse();
            return EventResult.pass();
        });
        ClientScreenInputEvent.KEY_RELEASED_PRE.register((minecraftClient, screen, event) -> {
            if (shouldReturn(screen) || screen instanceof DisplayScreen)
                return EventResult.pass();
            if (!REIRuntimeImpl.getSearchField().isFocused()) {
                GuiEventListener focused = screen.getFocused();
                if (focused != null) {
                    if (focused instanceof EditBox editBox && editBox.isFocused()) return EventResult.pass();
                    if (focused instanceof RecipeBookComponent book && book.searchBox != null && book.searchBox.isFocused()) return EventResult.pass();
                }
            }
            resetFocused(screen);
            if (getOverlay().keyReleased(event)
                    && resetFocused(screen))
                return EventResult.interruptFalse();
            return EventResult.pass();
        });
    }

public static void onInitialize() {
        NetworkManager.registerReceiver(NetworkManager.c2s(), REIPackets.DeleteItems.TYPE, REIPackets.DeleteItems.STREAM_CODEC, List.of(new SplitPacketTransformer()), (payload, context) -> {
            ServerPlayer player = (ServerPlayer) context.getPlayer();
            if (!player.permissions().hasPermission(new Permission.HasCommandLevel(PermissionLevel.GAMEMASTERS))) {
                player.sendSystemMessage(Component.translatable("text.rei.no_permission_cheat").withStyle(ChatFormatting.RED));
                return;
            }
            AbstractContainerMenu menu = player.containerMenu;
            if (!menu.getCarried().isEmpty()) {
                menu.setCarried(ItemStack.EMPTY);
                menu.broadcastChanges();
            }
        });
        NetworkManager.registerReceiver(NetworkManager.c2s(), REIPackets.CreateItems.TYPE, REIPackets.CreateItems.STREAM_CODEC, List.of(new SplitPacketTransformer()), (payload, context) -> {
            ServerPlayer player = (ServerPlayer) context.getPlayer();

            if (!player.permissions().hasPermission(new Permission.HasCommandLevel(PermissionLevel.GAMEMASTERS))) {
                player.sendSystemMessage(Component.translatable("text.rei.no_permission_cheat").withStyle(ChatFormatting.RED));
                return;
            }
            ItemStack stack = payload.stack();
            if (player.getInventory().add(stack.copy())) {
                NetworkManager.sendToPlayer(player, new REIPackets.CreateItemsMessage(stack.copy(), player.getScoreboardName()));
            } else {
                player.sendSystemMessage(Component.translatable("text.rei.failed_cheat_items"));
            }
        });
        NetworkManager.registerReceiver(NetworkManager.c2s(), REIPackets.CreateItemsGrab.TYPE, REIPackets.CreateItemsGrab.STREAM_CODEC, List.of(new SplitPacketTransformer()), (payload, context) -> {
            ServerPlayer player = (ServerPlayer) context.getPlayer();
            if (!player.permissions().hasPermission(new Permission.HasCommandLevel(PermissionLevel.GAMEMASTERS))) {
                player.sendSystemMessage(Component.translatable("text.rei.no_permission_cheat").withStyle(ChatFormatting.RED));
                return;
            }

            AbstractContainerMenu menu = player.containerMenu;
            ItemStack stack = payload.stack().copy();
            if (!menu.getCarried().isEmpty() && ItemStack.isSameItemSameComponents(menu.getCarried(), stack)) {
                stack.setCount(Mth.clamp(stack.getCount() + menu.getCarried().getCount(), 1, stack.getMaxStackSize()));
            } else if (!menu.getCarried().isEmpty()) {
                return;
            }
            menu.setCarried(stack.copy());
            menu.broadcastChanges();
            NetworkManager.sendToPlayer(player, new REIPackets.CreateItemsMessage(stack.copy(), player.getScoreboardName()));
        });
        NetworkManager.registerReceiver(NetworkManager.c2s(), REIPackets.CreateItemsHotbar.TYPE, REIPackets.CreateItemsHotbar.STREAM_CODEC, List.of(new SplitPacketTransformer()), (payload, context) -> {
            ServerPlayer player = (ServerPlayer) context.getPlayer();
            if (!player.permissions().hasPermission(new Permission.HasCommandLevel(PermissionLevel.GAMEMASTERS))) {
                player.sendSystemMessage(Component.translatable("text.rei.no_permission_cheat").withStyle(ChatFormatting.RED));
                return;
            }
            ItemStack stack = payload.stack();
            int hotbarSlotId = payload.hotbarSlot();
            if (hotbarSlotId >= 0 && hotbarSlotId < 9) {
                AbstractContainerMenu menu = player.containerMenu;
                player.getInventory().setItem(hotbarSlotId, stack.copy());
                menu.broadcastChanges();
                NetworkManager.sendToPlayer(player, new REIPackets.CreateItemsMessage(stack.copy(), player.getScoreboardName()));
            } else {
                player.sendSystemMessage(Component.translatable("text.rei.failed_cheat_items"));
            }
        });
        NetworkManager.registerReceiver(NetworkManager.c2s(), REIPackets.MoveItemsNew.TYPE, REIPackets.MoveItemsNew.STREAM_CODEC, List.of(new SplitPacketTransformer()), (payload, context) -> {
            ServerPlayer player = (ServerPlayer) context.getPlayer();
            CategoryIdentifier<Display> category = CategoryIdentifier.of(payload.category());
            AbstractContainerMenu container = player.containerMenu;
            InventoryMenu playerContainer = player.inventoryMenu;
            try {
                boolean shift = payload.shift();
                try {
                    CompoundTag nbt = payload.data();
                    int version = nbt.getInt("Version").orElse(-1);
                    if (version != 1) throw new IllegalStateException("Server and client REI protocol version mismatch! Server: 1, Client: " + version);
                    List<InputIngredient<ItemStack>> inputs = readInputs(context.registryAccess(), nbt.getListOrEmpty("Inputs"));
                    List<SlotAccessor> input = readSlots(container, player, nbt.getListOrEmpty("InputSlots"));
                    List<SlotAccessor> inventory = readSlots(container, player, nbt.getListOrEmpty("InventorySlots"));
                    NewInputSlotCrafter<AbstractContainerMenu, Container> crafter = new NewInputSlotCrafter<>(container, input, inventory, inputs);
                    crafter.fillInputSlots(player, shift);
                } catch (InputSlotCrafter.NotEnoughMaterialsException e) {
                    if (!(container instanceof RecipeBookMenu)) {
                        return;
                    }
                } catch (IllegalStateException e) {
                    player.sendSystemMessage(Component.translatable(e.getMessage()).withStyle(ChatFormatting.RED));
                } catch (Exception e) {
                    player.sendSystemMessage(Component.translatable("error.rei.internal.error", e.getMessage()).withStyle(ChatFormatting.RED));
                    e.printStackTrace();
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        });
        if (Platform.getEnvironment() == Env.SERVER) {
            NetworkManager.registerS2CPayloadType(REIPackets.CreateItemsMessage.TYPE, REIPackets.CreateItemsMessage.STREAM_CODEC);
            NetworkManager.registerS2CPayloadType(REIPackets.NotEnoughItems.TYPE, REIPackets.NotEnoughItems.STREAM_CODEC);
            NetworkManager.registerS2CPayloadType(DisplaySyncPacket.TYPE, DisplaySyncPacket.STREAM_CODEC, List.of(new SplitPacketTransformer()));
        }
    }

@Override
    public String getModFromModId(String modId) {
        if (modId == null)
            return "";
        String any = modNameCache.getOrDefault(modId, null);
        if (any != null)
            return any;
        if (Platform.isModLoaded(modId)) {
            String modName = Platform.getMod(modId).getName();
            modNameCache.put(modId, modName);
            return modName;
        }
        return modId;
    }

@ApiStatus.Internal
    public Long2LongMap _getInventoryItemsTypes() {
        EntryDefinition<ItemStack> definition;
        try {
            definition = VanillaEntryTypes.ITEM.getDefinition();
        } catch (NullPointerException e) {
            return Long2LongMaps.EMPTY_MAP;
        }
        Long2LongOpenHashMap map = new Long2LongOpenHashMap();
        for (ItemStack stack : Minecraft.getInstance().player.getInventory().getNonEquipmentItems()) {
            long hash = definition.hash(null, stack, ComparisonContext.FUZZY);
            long newCount = map.getOrDefault(hash, 0) + Math.max(0, stack.getCount());
            map.put(hash, newCount);
        }
        return map;
    }

@ApiStatus.Internal
    public Long2LongMap _getContainerItemsTypes() {
        EntryDefinition<ItemStack> definition;
        try {
            definition = VanillaEntryTypes.ITEM.getDefinition();
        } catch (NullPointerException e) {
            return Long2LongMaps.EMPTY_MAP;
        }
        Long2LongOpenHashMap map = new Long2LongOpenHashMap();
        AbstractContainerMenu menu = Minecraft.getInstance().player.containerMenu;
        if (menu != null) {
            for (Slot slot : menu.slots) {
                ItemStack stack = slot.getItem();

                if (!stack.isEmpty()) {
                    long hash = definition.hash(null, stack, ComparisonContext.FUZZY);
                    long newCount = map.getOrDefault(hash, 0) + Math.max(0, stack.getCount());
                    map.put(hash, newCount);
