        var cur = (float) Math.max(0, stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of()).size() - 2);

        var ratio = Mth.clamp(cur / max, 0F, 1F);

        return Mth.hsvToRgb(ratio / 3F, 1F, 1F);
