public static EntityHitResult rayTraceEntity(Entity shooter, Predicate<? super Entity> filter, double distance) {
        Level world = shooter.level();

        Vec3 startVec = shooter.getEyePosition(1.0F);
        Vec3 endVec = shooter.getEyePosition(1.0F).add(shooter.getViewVector(1.0F).scale(distance));

        double d0 = distance * distance;

        Entity entity = null;
        Vec3 vector3d = null;

        for (Entity entity1 : world.getEntities(shooter, shooter.getBoundingBox()
                .expandTowards(shooter.getViewVector(1.0F).scale(distance * distance)).inflate(1.0D), filter)) {
            AABB axisalignedbb = entity1.getBoundingBox().inflate(entity1.getPickRadius());
            Optional<Vec3> optional = axisalignedbb.clip(startVec, endVec);

            if (axisalignedbb.contains(startVec)) {
                if (d0 >= 0.0D) {
                    entity = entity1;
                    vector3d = optional.orElse(startVec);

                    d0 = 0.0D;
                }
            } else if (optional.isPresent()) {
                Vec3 vector3d1 = optional.get();

                double d1 = startVec.distanceToSqr(vector3d1);

                if (d1 < d0 || d0 == 0.0D) {
                    if (entity1.getRootVehicle() == shooter.getRootVehicle() && !entity1.canRiderInteract()) {
                        if (d0 == 0.0D) {
                            entity = entity1;
                            vector3d = vector3d1;
                        }
                    } else {
                        entity = entity1;
                        vector3d = vector3d1;

                        d0 = d1;
                    }
                }
            }
        }

        return entity == null ? null : new EntityHitResult(entity, vector3d);
    }

public static ItemStack findEquippedCurio(Entity entity, Item item) {
        if (!(entity instanceof Player player))
            return ItemStack.EMPTY;

        return CuriosApi.getCuriosInventory(player)
                .map(inventory -> {
                    var equipped = inventory.getEquippedCurios();

                    for (var i = 0; i < equipped.getSlots(); i++) {
                        var stack = equipped.getStackInSlot(i);

                        if (!stack.isEmpty() && stack.getItem() == item)
                            return stack;
                    }

                    return ItemStack.EMPTY;
                })
                .orElse(ItemStack.EMPTY);
    }

public static List<ItemStack> findEquippedCurios(Entity entity, Item item, Predicate<ItemStack> predicate) {
        if (!(entity instanceof LivingEntity livingEntity))
            return List.of();

        return CuriosApi.getCuriosInventory(livingEntity)
                .map(inventory -> {
                    var equipped = inventory.getEquippedCurios();
                    List<ItemStack> result = new ArrayList<>();

                    for (var i = 0; i < equipped.getSlots(); i++) {
                        var stack = equipped.getStackInSlot(i);

                        if (!stack.isEmpty() && stack.getItem() == item && predicate.test(stack))
                            result.add(stack);
                    }

                    return result;
                })
                .orElse(List.of());
    }

public static double maxValue(LivingEntity entity, ItemStack stack, String ability, String stat, Predicate<AbilityData> predicate) {
        var fallback = getFallbackAbilityData(entity, stack, ability);
        var abilities = getActiveAbilityData(entity, stack, ability, predicate);

        if (abilities.isEmpty())
            return fallback == null ? 0D : clampByThreshold(fallback, stat, fallback.getStatData(stat).getValue());

        var reference = abilities.getFirst();
        var max = abilities.stream().mapToDouble(abilityData -> abilityData.getStatData(stat).getValue()).max().orElse(reference.getStatData(stat).getValue());

        return clampByThreshold(reference, stat, max);
    }

public static double minValue(LivingEntity entity, ItemStack stack, String ability, String stat, Predicate<AbilityData> predicate) {
        var fallback = getFallbackAbilityData(entity, stack, ability);
        var abilities = getActiveAbilityData(entity, stack, ability, predicate);

        if (abilities.isEmpty())
            return fallback == null ? 0D : clampByThreshold(fallback, stat, fallback.getStatData(stat).getValue());

        var reference = abilities.getFirst();
        var min = abilities.stream().mapToDouble(abilityData -> abilityData.getStatData(stat).getValue()).min().orElse(reference.getStatData(stat).getValue());

        return clampByThreshold(reference, stat, min);
    }

