@SubscribeEvent
  public void onAttributeTooltip(final AddAttributeTooltipsEvent evt) {
    AttributeTooltipContext context = evt.getContext();
    ItemStack stack = evt.getStack();
    GatherSkippedAttributeTooltipsEvent skipped =
        NeoForge.EVENT_BUS.post(new GatherSkippedAttributeTooltipsEvent(stack, context));

    if (skipped.isSkippingAll()) {
      return;
    }
    List<Component> attributesTooltip = new ArrayList<>();
    Player player = context.player();
    Set<String> slots = getItemStackSlots(stack, player).keySet();

    for (String identifier : slots) {
      SlotContext slotContext = new SlotContext(identifier, player, 0, false, true);
      Multimap<Holder<Attribute>, AttributeModifier> attributes = LinkedHashMultimap.create();
      ICurioItem.forEachModifier(stack, slotContext, attributes::put);
      attributes.values().removeIf(modifier -> skipped.isSkipped(modifier.id()));

      if (attributes.isEmpty()) {
        continue;
      }
      attributesTooltip.add(Component.empty());
      attributesTooltip.add(
          Component.translatable("curios.modifiers." + identifier).withStyle(ChatFormatting.GOLD));

      if (player != null) {
        AttributeUtil.applyTextFor(
            stack,
            attributesTooltip::add,
            attributes,
            AttributeTooltipContext.of(player, context, context.tooltipDisplay(), context.flag()));
      }
    }
    evt.addTooltipLines(
        CuriosApi.getCurio(stack)
            .map(curio -> curio.getAttributesTooltip(attributesTooltip, context))
            .orElse(attributesTooltip)
            .toArray(new Component[0]));
  }

@SubscribeEvent
  public void onTooltip(final ItemTooltipEvent evt) {
    ItemStack stack = evt.getItemStack();
    Player player = evt.getEntity();

    if (stack.isEmpty()) {
      return;
    }
    Map<String, ISlotType> slots = getItemStackSlots(stack, player);

    if (slots.isEmpty()) {
      return;
    }
    List<String> slotIds = slots.keySet().stream().toList();
    MutableComponent slotsTooltip =
        Component.translatable("curios.tooltip.slot").append(" ").withStyle(ChatFormatting.GOLD);

    for (int j = 0; j < slotIds.size(); j++) {
      String id = slotIds.get(j);
      String key = "curios.identifier." + id;
      MutableComponent type =
          Component.translatableWithFallback(
              key, id.substring(0, 1).toUpperCase(Locale.ROOT)
                  + id.substring(1).toLowerCase(Locale.ROOT));

      if (j < slotIds.size() - 1) {
        type = type.append(", ");
      }
      type = type.withStyle(ChatFormatting.YELLOW);
      slotsTooltip.append(type);
    }
    Item.TooltipContext context = evt.getContext();
    List<Component> toAdd = List.of(slotsTooltip);
    evt.getToolTip()
        .addAll(
            1,
            CuriosApi.getCurio(stack)
                .map(curio -> curio.getSlotsTooltip(toAdd, context))
                .orElse(toAdd));
  }

private static Map<String, ISlotType> getItemStackSlots(ItemStack stack, Player player) {
    Map<String, ISlotType> result = new LinkedHashMap<>();
    Map<String, ISlotType> map =
        player != null
            ? CuriosSlotTypes.getItemSlotTypes(stack, player)
            : CuriosSlotTypes.getItemSlotTypes(stack, FMLLoader.getCurrent().getDist().isClient());

    for (Map.Entry<String, ISlotType> entry : map.entrySet()) {
      ISlotType slotType = entry.getValue();

      // Avoid getting slots with "all" validators to solve tooltip bloat
      if (!slotType.getValidators().contains(CuriosResources.resource("all"))) {
        result.put(entry.getKey(), slotType);
      }
    }
    String curio = CuriosSlotTypes.Preset.CURIO.id();

    if (result.containsKey(curio)) {

      if (stack.is(CuriosTags.CURIO)) {
        return Map.of(curio, result.get(curio));
      } else {
        result.remove(curio);
      }
    }
    return result;
  }

@Override
  protected void extractSlot(@Nonnull GuiGraphicsExtractor graphics, Slot slot, int x, int y) {
    int i = slot.x;
    int j = slot.y;
    ItemStack itemstack = slot.getItem();

    if (slot instanceof ICurioSlot curioSlot) {
      itemstack =
          curioSlot.getSlotExtension().getDisplayStack(curioSlot.getSlotContext(), itemstack);
    }
    boolean quickCraftStack = false;
    boolean done = false;
    ItemStack carried = this.menu.getCarried();
    String itemCount = null;

    if (this.isQuickCrafting && this.quickCraftSlots.contains(slot) && !carried.isEmpty()) {

      if (this.quickCraftSlots.size() == 1) {
        return;
      }

      if (AbstractContainerMenu.canItemQuickReplace(slot, carried, true) &&
          this.menu.canDragTo(slot)) {
        quickCraftStack = true;
        int maxSize = Math.min(carried.getMaxStackSize(), slot.getMaxStackSize(carried));
        int carry = slot.getItem().isEmpty() ? 0 : slot.getItem().getCount();
        int newCount = AbstractContainerMenu.getQuickCraftPlaceCount(this.quickCraftSlots.size(),
            this.quickCraftingType, carried) + carry;

        if (newCount > maxSize) {
          newCount = maxSize;
          itemCount = ChatFormatting.YELLOW.toString() + maxSize;
        }
        itemstack = carried.copyWithCount(newCount);
      } else {
        this.quickCraftSlots.remove(slot);
        this.recalculateQuickCraftRemaining();
      }
    }

    if (itemstack.isEmpty() && slot.isActive()) {
      Identifier icon = slot.getNoItemIcon();

      if (icon != null) {
        graphics.blitSprite(RenderPipelines.GUI_TEXTURED, icon, i, j, 16, 16);
        done = true;
      }
    }

    if (!done) {

      if (quickCraftStack) {
        graphics.fill(i, j, i + 16, j + 16, -2130706433);
      }
      this.renderSlotContents(graphics, itemstack, slot, itemCount);
    }
  }

private static void handleDrops(String identifier, LivingEntity livingEntity,
                                  List<Pair<Predicate<ItemStack>, DropRule>> dropRules,
                                  NonNullList<Boolean> renders, IDynamicStackHandler stacks,
                                  boolean cosmetic, Collection<ItemEntity> drops,
                                  boolean keepInventory, LivingDropsEvent evt) {
    for (int i = 0; i < stacks.getSlots(); i++) {
      ItemStack stack = stacks.getStackInSlot(i);
      SlotContext slotContext = new SlotContext(identifier, livingEntity, i, cosmetic,
          renders.size() > i && renders.get(i));

      if (!stack.isEmpty()) {
        DropRule dropRuleOverride = null;

        for (Pair<Predicate<ItemStack>, DropRule> override : dropRules) {

          if (override.getFirst().test(stack)) {
            dropRuleOverride = override.getSecond();
          }
        }
        DropRule dropRule = dropRuleOverride != null ? dropRuleOverride : CuriosApi.getCurio(stack)
            .map(curio -> curio.getDropRule(slotContext, evt.getSource(), evt.isRecentlyHit()))
            .orElse(DropRule.DEFAULT);

        if (dropRule == DropRule.DEFAULT) {
          ISlotType slotType = ISlotType.get(identifier);

          if (slotType != null) {
            dropRule = slotType.getDropRule();
          }
        }

        if ((dropRule == DropRule.DEFAULT && keepInventory) || dropRule == DropRule.ALWAYS_KEEP) {
          continue;
        }

        if (!EnchantmentHelper.has(stack, EnchantmentEffectComponents.PREVENT_EQUIPMENT_DROP) &&
            dropRule != DropRule.DESTROY) {
          drops.add(getDroppedItem(stack, livingEntity));
        }
        stacks.setStackInSlot(i, ItemStack.EMPTY);
      }
    }
  }

@SubscribeEvent(priority = EventPriority.HIGHEST)
  public void onBreakBlock(BlockDropsEvent event) {
    AtomicInteger experience = new AtomicInteger(event.getDroppedExperience());

    if (experience.get() <= 0 || !(event.getBreaker() instanceof LivingEntity entity)) {
      return;
    }

    CuriosApi.getCuriosInventory(entity).ifPresent(handler -> {
      for (Map.Entry<String, ICurioStacksHandler> entry : handler.getCurios().entrySet()) {
        IDynamicStackHandler stacks = entry.getValue().getStacks();
        NonNullList<Boolean> renderStates = entry.getValue().getRenders();

        for (int i = 0; i < stacks.getSlots(); i++) {
          SlotContext context = new SlotContext(entry.getKey(), entity, i, false,
              renderStates.size() > i && renderStates.get(i));

          experience.addAndGet(
              EnchantmentHelper.processBlockExperience(event.getLevel(), event.getTool(),
                  CuriosApi.getCurio(stacks.getStackInSlot(i))
                      .map(curio -> curio.getFortuneLevel(
                          context, null)).orElse(0)));
        }
      }
    });

    event.setDroppedExperience(experience.get());
  }

@SubscribeEvent
  public void enderManAnger(final EndermanAngerEvent evt) {
    // Check cached value first
    if (enderManMaskCache.size() > 500) {
      enderManMaskCache.clear();
    }
    Player player = evt.getPlayer();
    long gameTime = player.level().getGameTime();

    if (enderManMaskCache.containsKey(player.getUUID())) {
      var pair = enderManMaskCache.get(player.getUUID());

      if (pair.getFirst() == gameTime) {
        evt.setCanceled(pair.getSecond());
        return;
      }
    }
    CuriosApi.getCuriosInventory(player).ifPresent(handler -> {
      all:
      for (Map.Entry<String, ICurioStacksHandler> entry : handler.getCurios().entrySet()) {
        IDynamicStackHandler stacks = entry.getValue().getStacks();

        for (int i = 0; i < stacks.getSlots(); i++) {
          final int index = i;
          NonNullList<Boolean> renderStates = entry.getValue().getRenders();
          boolean hasMask = CuriosApi.getCurio(stacks.getStackInSlot(i)).map(
                  curio -> curio.isEnderMask(new SlotContext(entry.getKey(), player, index, false,
                          renderStates.size() > index
                              && renderStates.get(index)),
                      evt.getEntity()))
              .orElse(false);

          if (hasMask) {
            enderManMaskCache.put(player.getUUID(), Pair.of(gameTime, true));
            evt.setCanceled(true);
            break all;
          }
        }
      }
    });
    enderManMaskCache.put(player.getUUID(), Pair.of(gameTime, false));
  }

private static void syncCurios(LivingEntity livingEntity, ItemStack stack,
                                 Optional<ICurio> currentCurio, Optional<ICurio> prevCurio,
                                 String identifier, int index, boolean cosmetic, boolean visible,
                                 HandlerType type) {
    SlotContext slotContext = new SlotContext(identifier, livingEntity, index, cosmetic, visible);
    boolean syncable = currentCurio.map(curio -> curio.canSync(slotContext)).orElse(false) ||
        prevCurio.map(curio -> curio.canSync(slotContext)).orElse(false);
    CompoundTag syncTag = syncable ?
        currentCurio.map(curio -> curio.writeSyncData(slotContext))
            .orElse(new CompoundTag()) :
        new CompoundTag();
    PacketDistributor.sendToPlayersTrackingEntityAndSelf(livingEntity,
        new SPacketSyncStack(livingEntity.getId(),
            identifier, index,
            stack, type.ordinal(),
            syncTag));
  }

public void loadInventoryConfiguration() {
    Map<ISlotType, ICurioStacksHandler> defaultInventory = this.createDefaultInventory();
    SortedMap<ISlotType, ICurioStacksHandler> sortedCurios = new TreeMap<>(defaultInventory);

    for (Map.Entry<String, ICurioStacksHandler> entry : this.curios.entrySet()) {
      String id = entry.getKey();
      ISlotType slotType = CuriosSlotTypes.getSlotType(id, this.owner.level().isClientSide());
      ICurioStacksHandler prevStacksHandler = entry.getValue();

      if (slotType != null && defaultInventory.containsKey(slotType)) {
        ICurioStacksHandler curioStacksHandler = defaultInventory.get(slotType);
        int defaultSize = curioStacksHandler.getSlots();
        int oldSize = prevStacksHandler.getSlots();
        curioStacksHandler.copyModifiers(prevStacksHandler);

        if (oldSize != defaultSize) {
          curioStacksHandler.addTransientModifier(
              new AttributeModifier(SIZE_SHIFT, oldSize - defaultSize,
                  AttributeModifier.Operation.ADD_VALUE));
        }
        int index = 0;

        while (index < curioStacksHandler.getSlots() && index < prevStacksHandler.getSlots()) {
          ItemStack prevStack = prevStacksHandler.getStacks().getStackInSlot(index);

          if (!prevStack.isEmpty()) {

            if (curioStacksHandler.getStacks().isItemValid(index, prevStack)) {
              curioStacksHandler.getStacks().setStackInSlot(index, prevStack);
            } else {
              this.invalidStacks.add(prevStack);
            }
          }
          ItemStack prevCosmetic =
              prevStacksHandler.getCosmeticStacks().getStackInSlot(index);

          if (!prevCosmetic.isEmpty()) {

            if (curioStacksHandler.getStacks().isItemValid(index, prevCosmetic)) {
              curioStacksHandler
                  .getCosmeticStacks()
                  .setStackInSlot(
                      index, prevStacksHandler.getCosmeticStacks().getStackInSlot(index));
            } else {
              this.invalidStacks.add(prevCosmetic);
            }
          }
          index++;
        }

        while (index < prevStacksHandler.getSlots()) {
          this.invalidStacks.add(prevStacksHandler.getStacks().getStackInSlot(index));
          this.invalidStacks.add(prevStacksHandler.getCosmeticStacks().getStackInSlot(index));
          index++;
        }
        sortedCurios.put(slotType, curioStacksHandler);

        for (int j = 0;
             j < curioStacksHandler.getRenders().size()
                 && j < prevStacksHandler.getRenders().size();
             j++) {
          curioStacksHandler.getRenders().set(j, prevStacksHandler.getRenders().get(j));
        }

        for (int j = 0;
             j < curioStacksHandler.getActiveStates().size()
                 && j < prevStacksHandler.getActiveStates().size();
             j++) {
          curioStacksHandler.getActiveStates()
              .set(j, prevStacksHandler.getActiveStates().get(j));
        }
      } else {
        IDynamicStackHandler stackHandler = prevStacksHandler.getStacks();
        IDynamicStackHandler cosmeticStackHandler = prevStacksHandler.getCosmeticStacks();

        for (int j = 0; j < stackHandler.getSlots(); j++) {
          ItemStack stack = stackHandler.getStackInSlot(j);

          if (!stack.isEmpty()) {
            this.invalidStacks.add(stack);
          }

          ItemStack cosmeticStack = cosmeticStackHandler.getStackInSlot(j);

          if (!cosmeticStack.isEmpty()) {
            this.invalidStacks.add(cosmeticStack);
          }
        }
      }
    }
    this.curios.clear();

    for (Map.Entry<ISlotType, ICurioStacksHandler> entry : sortedCurios.entrySet()) {
      ICurioStacksHandler stacksHandler = entry.getValue();

      if (stacksHandler instanceof CurioStacksHandler curioStacksHandler) {
        curioStacksHandler.setDataLoaded();
      }
      this.curios.put(entry.getKey().getId(), stacksHandler);
    }
  }

@Override
  public void deserialize(@Nonnull ValueInput valueInput) {
    this.curios.clear();
    ValueInput.ValueInputList list = valueInput.childrenListOrEmpty(CURIOS_KEY);

    if (list.isEmpty()) {
      this.resetInventory();
      return;
    }
    list.forEach(input -> {

      for (String id : input.keySet()) {

        if (!id.isEmpty()) {
          ICurioStacksHandler stacks = new CurioStacksHandler(this, id);
          stacks.deserialize(input.childOrEmpty(id));
          this.curios.put(id, stacks);
        }
      }
    });
  }

@Override
  public List<SlotResult> findCurios(boolean includeInactive, String... identifiers) {
    List<SlotResult> result = new ArrayList<>();
    Set<String> ids = new HashSet<>(List.of(identifiers));
    Map<String, ICurioStacksHandler> curios = this.getCurios();

    for (String id : curios.keySet()) {

      if (ids.contains(id)) {
        ICurioStacksHandler stacksHandler = curios.get(id);
        IDynamicStackHandler stackHandler = stacksHandler.getStacks();
        NonNullList<Boolean> activeStates = stacksHandler.getActiveStates();

        for (int i = 0; i < stackHandler.getSlots(); i++) {

          if (!includeInactive && activeStates.size() > i && !activeStates.get(i)) {
            continue;
          }
          ItemStack stack = stackHandler.getStackInSlot(i);

          if (!stack.isEmpty()) {
            NonNullList<Boolean> renderStates = stacksHandler.getRenders();
            result.add(
                new SlotResult(
                    new SlotContext(
                        id,
                        this.livingEntity,
                        i,
                        false,
                        renderStates.size() > i && renderStates.get(i)),
                    stack));
          }
        }
      }
    }
    return result;
  }

