@WrapMethod(method = {
            "submit(Lcom/mojang/blaze3d/vertex/PoseStack;Lnet/minecraft/client/renderer/SubmitNodeCollector;ILnet/minecraft/client/renderer/entity/state/LivingEntityRenderState;FF)V",      // Mojmap
            "method_17159(Lnet/minecraft/class_4587;Lnet/minecraft/class_11659;ILnet/minecraft/class_10042;FF)V",                                                                             // Yarn Interm.
            "render(Lnet/minecraft/client/util/math/MatrixStack;Lnet/minecraft/client/render/command/OrderedRenderCommandQueue;ILnet/minecraft/client/render/entity/state/LivingEntityRenderState;FF)V" // Yarn
    })
    private void accessories$adjustHeadItem(PoseStack poseStack, SubmitNodeCollector submitNodeCollector, int i, S livingEntityRenderState, float f, float g, Operation<Void> original) {
        ItemStackRenderState prevState = null;

        if (livingEntityRenderState instanceof AccessoriesRenderStateAPI extension) {
            var lookup = extension.getStorageLookup();

            if (lookup != null) {
                var ref = lookup.getEquipped(ItemStackBasedPredicate.ofClass(BannerItem.class))
                        .stream()
                        .filter(entry -> entry.path().slotName().equals(AccessoriesBaseData.HAT_SLOT))
                        .findFirst()
                        .orElse(null);

                if (ref != null) {
                    var stack = ref.stack();
                    prevState = livingEntityRenderState.headItem;

                    var alternativeRenderState = new ItemStackRenderState();

                    Minecraft.getInstance().getItemModelResolver()
                            .updateForTopItem(alternativeRenderState, stack, ItemDisplayContext.HEAD, Minecraft.getInstance().level, null, extension.getEntityUUIDForState().hashCode() + 5);

                    ((LivingEntityRenderStateAccessor) livingEntityRenderState).accessories$headItem(alternativeRenderState);
                }
            }
        }

        original.call(poseStack, submitNodeCollector, i, livingEntityRenderState, f, g);

        if (prevState != null) ((LivingEntityRenderStateAccessor) livingEntityRenderState).accessories$headItem(prevState);
    }

@Override
    public void tick(ItemStack stack, SlotReference reference) {
        var currentDamage = stack.getDamageValue();

        if(currentDamage >= 63) return;

        var customData = stack.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY);

        var tag = customData.copyTag();

        var refillTimeout = tag.getIntOr(REFILL_TIME_OUT_KEY, -1);

        if(refillTimeout != -1) {
            CustomData.update(DataComponents.CUSTOM_DATA, stack, tag1 -> {
                var newRefillTimeout = refillTimeout - 1;

                if(newRefillTimeout > 0) {
                    tag1.putInt(REFILL_TIME_OUT_KEY, newRefillTimeout);
                } else {
                    tag1.remove(REFILL_TIME_OUT_KEY);
                }
            });

            return;
        }

        if(reference.entity() instanceof ServerPlayer serverPlayer){
            var currentAirSupply = serverPlayer.getAirSupply();

            if(serverPlayer.getMaxAirSupply() - currentAirSupply >= 20) {
                stack.setDamageValue(currentDamage + 1);

                serverPlayer.setAirSupply(currentAirSupply + 20);

                CustomData.update(DataComponents.CUSTOM_DATA, stack, tag1 -> {
                    tag1.putInt(REFILL_TIME_OUT_KEY, 4);
                });
            }
        }
    }

public void registerReloadListeners(AddServerReloadListenersEvent event){
        var loaders = AccessoriesNeoforgeInternals.TO_BE_LOADED.getOrDefault(PackType.SERVER_DATA, new LinkedHashSet<>());

        loaders.forEach((loader) -> {
            if (loader instanceof EndecDataLoader<?> endecDataLoader) {
                var registryHolder = new MutableObject<>(event.getRegistryAccess());

                endecDataLoader.setRegistriesAccess(sharedState -> {
                    var registry = registryHolder.getValue();

                    registryHolder.setValue(null);

                    return registry;
                });
            }

            event.addListener(loader.getId(), loader);
        });

        loaders.forEach((endecDataLoader) -> {
            for (var dependencyId : endecDataLoader.getDependencyIds()) {
                event.addDependency(dependencyId, endecDataLoader.getId());
            }
        });

        event.addListener(Accessories.DATA_RELOAD_HOOK, new SimplePreparableReloadListener<Void>() {
            @Override protected Void prepare(ResourceManager resourceManager, ProfilerFiller profiler) { return null; }
            @Override protected void apply(Void object, ResourceManager resourceManager, ProfilerFiller profiler) {
                AccessoriesEventHandler.dataReloadOccurred = true;
            }
        });
    }

public void registerReloadListeners(AddClientReloadListenersEvent event){
        var loaders = AccessoriesNeoforgeInternals.TO_BE_LOADED.getOrDefault(PackType.CLIENT_RESOURCES, new LinkedHashSet<>());

        loaders.forEach((endecDataLoader) -> event.addListener(endecDataLoader.getId(), endecDataLoader));

        loaders.forEach((endecDataLoader) -> {
            for (var dependencyId : endecDataLoader.getDependencyIds()) {
                event.addDependency(dependencyId, endecDataLoader.getId());
            }
        });
    }

