				this.addOneOf(event,
						new ItemStack(EnigmaticItems.GUARDIAN_HEART, 1),
						new ItemStack(Items.HEART_OF_THE_SEA, 1),
						new ItemStack(Items.ENCHANTED_GOLDEN_APPLE, 1),
