public InteractionResultHolder<ItemStack> use(Level worldIn, Player livingEntityIn, InteractionHand handIn) {
        ItemStack stack = livingEntityIn.getItemInHand(handIn);
        boolean left = false;
        if (livingEntityIn.getUsedItemHand() == InteractionHand.OFF_HAND && livingEntityIn.getMainArm() == HumanoidArm.RIGHT || livingEntityIn.getUsedItemHand() == InteractionHand.MAIN_HAND && livingEntityIn.getMainArm() == HumanoidArm.LEFT) {
            left = true;
        }
        EntityCachalotEcho whaleEcho = new EntityCachalotEcho(worldIn, livingEntityIn, !left, type == EchoType.PUPFISH);
        if (!worldIn.isClientSide && worldIn instanceof ServerLevel) {
            BlockPos playerPos = livingEntityIn.blockPosition();
            List<BlockPos> portals = getNearbyPortals(playerPos, (ServerLevel) worldIn, 128);
            BlockPos pos = null;
            if(type == EchoType.ENDER){
                for (BlockPos portalPos : portals) {
                    if (pos == null || pos.distSqr(playerPos) > portalPos.distSqr(playerPos)) {
                        pos = portalPos;
                    }
                }
            }else if(type == EchoType.PUPFISH){
                for (BlockPos portalPos : portals) {
                    if (pos == null || pos.distSqr(playerPos) > portalPos.distSqr(playerPos)) {
                        pos = portalPos;
                    }
                }
            }else{
                CompoundTag nbt = stack.getOrCreateTag();
                if(nbt.contains("CavePos") && nbt.getBoolean("ValidCavePos")){
                    pos = BlockPos.of(nbt.getLong("CavePos"));
                    if(isCaveAir(worldIn, pos) || 1000000 < pos.distSqr(playerPos)){
                        nbt.putBoolean("ValidCavePos", false);
                    }
                }else{
                    for (BlockPos portalPos : portals) {
                        if (pos == null || pos.distSqr(playerPos) < portalPos.distSqr(playerPos)) {
                            pos = portalPos;
                        }
                    }
                    if(pos != null){
                        nbt.putLong("CavePos", pos.asLong());
                        nbt.putBoolean("ValidCavePos", true);
                        stack.setTag(nbt);
                    }
                }

            }
            if (pos != null) {
                double d0 = pos.getX() + 0.5F - whaleEcho.getX();
                double d1 = pos.getY() + 0.5F - whaleEcho.getY();
                double d2 = pos.getZ() + 0.5F - whaleEcho.getZ();
                whaleEcho.tickCount = 15;
                whaleEcho.shoot(d0, d1, d2, 0.4F, 0.3F);
                worldIn.addFreshEntity(whaleEcho);
                livingEntityIn.gameEvent(GameEvent.ITEM_INTERACT_START);
                worldIn.playSound((Player)null, whaleEcho.getX(), whaleEcho.getY(), whaleEcho.getZ(), AMSoundRegistry.CACHALOT_WHALE_CLICK.get(), SoundSource.PLAYERS, 1.0F, 1.0F);
                stack.hurtAndBreak(1, livingEntityIn, (player) -> {
                    player.broadcastBreakEvent(livingEntityIn.getUsedItemHand());
                });
            }
        }
        livingEntityIn.getCooldowns().addCooldown(this, 5);

        return InteractionResultHolder.sidedSuccess(stack, worldIn.isClientSide());
    }

public boolean onLeftClick(ItemStack stack, LivingEntity playerIn) {
        if(stack.getItem() == AMItemRegistry.FALCONRY_GLOVE.get()){
            final float dist = 128;
            Vec3 Vector3d = playerIn.getEyePosition(1.0F);
            Vec3 Vector3d1 = playerIn.getViewVector(1.0F);
            final double vector3d1xDist = Vector3d1.x * dist;
            final double vector3d1yDist = Vector3d1.y * dist;
            final double vector3d1zDist = Vector3d1.z * dist;
            Vec3 Vector3d2 = Vector3d.add(vector3d1xDist, vector3d1yDist, vector3d1zDist);
            double d1 = dist;
            Entity pointedEntity = null;
            List<Entity> list = playerIn.level().getEntities(playerIn, playerIn.getBoundingBox().expandTowards(vector3d1xDist, vector3d1yDist, vector3d1zDist).inflate(1.0D, 1.0D, 1.0D), new Predicate<Entity>() {
                public boolean apply(@Nullable Entity entity) {
                    return entity != null && entity.isPickable() && (entity instanceof Player || (entity instanceof LivingEntity));
                }
            });
            for (Entity entity1 : list) {
                AABB axisalignedbb = entity1.getBoundingBox().inflate(entity1.getPickRadius());
                Optional<Vec3> optional = axisalignedbb.clip(Vector3d, Vector3d2);

                if (axisalignedbb.contains(Vector3d)) {
                    if (d1 >= 0.0D) {
                        //pointedEntity = entity1;
                        d1 = 0.0D;
                    }
                } else if (optional.isPresent()) {
                    double d3 = Vector3d.distanceTo(optional.get());

                    if (d3 < d1 || d1 == 0.0D) {
                        if (entity1.getRootVehicle() == playerIn.getRootVehicle() && !playerIn.canRiderInteract()) {
                            if (d1 == 0.0D) {
                                pointedEntity = entity1;
                            }
                        } else {
                            pointedEntity = entity1;
                            d1 = d3;
                        }
                    }
                }
            }

            if(!playerIn.getPassengers().isEmpty()){
                for(Entity entity : playerIn.getPassengers()){
                    if(entity instanceof IFalconry && entity instanceof Animal animal){
                        IFalconry falcon = (IFalconry)entity;
                        animal.removeVehicle();
                        animal.moveTo(playerIn.getX(), playerIn.getEyeY(), playerIn.getZ(), animal.getYRot(), animal.getXRot());
                        if(animal.level().isClientSide){
                            AlexsMobs.sendMSGToServer(new MessageSyncEntityPos(animal.getId(), playerIn.getX(), playerIn.getEyeY(), playerIn.getZ()));
                        }else{
                            AlexsMobs.sendMSGToAll(new MessageSyncEntityPos(animal.getId(), playerIn.getX(), playerIn.getEyeY(), playerIn.getZ()));
                        }
                        if(playerIn instanceof Player){
                            falcon.onLaunch((Player)playerIn, pointedEntity);
                        }
                        return true;
                    }
                }
            }
        }
        return false;
    }

private boolean placeFish(ServerLevel worldIn, ItemStack stack, BlockPos pos) {
        Entity entity = AMEntityRegistry.FLUTTER.get().spawn(worldIn, stack, (Player)null, pos, MobSpawnType.BUCKET, true, false);
        if (entity != null && entity instanceof EntityFlutter) {
