                return NONBI;
            }else if (name.contains("trans")) {
                return TRANS;
            }else if (name.contains("bi")) {
                return BI;
            }else if (name.contains("asexual") || name.contains("ace")) {
                return ACE;
            }else if (name.contains("weezer")) {
                return WEEZER;
            }else if (name.contains("brazil")) {
                return BRAZIL;
            }
            return RAINBOW;
        }

