public static void handle(PacketContext<ServerboundSyncPatternPacket> context) {
		ServerPlayer player = context.sender();
		List<Pattern> pattern = context.message().patterns();

		ArcanusComponents.setPattern(player, pattern);

		if(pattern.size() >= 3 && context.message().castSpell()) {
			ItemStack stack = player.getMainHandItem();

			if(stack.getItem() instanceof StaffItem staff) {
				Optional<TrinketComponent> optional = TrinketsApi.getTrinketComponent(player);

				if(optional.isPresent()) {
					ItemStack spellBook = ArcanusHelper.getActiveSpellBook(player);
					SpellBookComponent spells = spellBook.getOrDefault(ArcanusDataComponents.SPELL_BOOK.get(), SpellBookComponent.empty());
					int index = ArcanusHelper.getSpellIndex(pattern);

					if(player.getCooldowns().getCooldownPercent(staff, 1f) == 0) {
						Spell spell = spells.getSpell(index);

						if(!spell.getComponentGroups().stream().flatMap(SpellGroup::getAllComponents).allMatch(spellComponent -> ArcanusComponents.knowsSpellComponents(player, spellComponent))) {
							player.displayClientMessage(Component.translatable(SPELL_UNKNOWN_SPELL_COMPONENTS).withStyle(ChatFormatting.RED, ChatFormatting.ITALIC), true);
							return;
						}

						if(spell.getComponentGroups().stream().flatMap(SpellGroup::getAllComponents).count() > ArcanusComponents.maxSpellSize()) {
							player.displayClientMessage(Component.translatable(SPELL_TOO_MANY_COMPONENTS), true);
							return;
						}

						for(PrimalArcana primalArcana : spell.getArcanaCost().keySet()) {
							if(!player.isCreative() && !ArcanusComponents.drainArcana(player, primalArcana, spell.getArcanaCost().getDouble(primalArcana), false)) {
								player.displayClientMessage(Component.translatable(SPELL_NOT_ENOUGH_MANA).withStyle(ChatFormatting.RED, ChatFormatting.ITALIC), true);
								return;
							}
						}

						ArcanusComponents.setPattern(player, ArcanusHelper.getSpellPattern(index));
						ArcanusComponents.setLastCastTime(player, player.level().getGameTime());
						spell.cast(player, player.serverLevel(), stack);
						player.displayClientMessage(Component.translatable(spell.getName()).withStyle(ChatFormatting.GREEN), true);

						for(Holder<Item> holder : BuiltInRegistries.ITEM.getTagOrEmpty(ArcanusItemTags.STAVES))
							player.getCooldowns().addCooldown(holder.value(), (int) (spell.getCoolDown() * player.getAttributeValue(ArcanusAttributes.SPELL_COOL_DOWN.holder())));
					}
				}
			}
		}
	}

@Override
	public void effect(@Nullable LivingEntity caster, @Nullable Entity sourceEntity, Level level, HitResult target, List<SpellEffect> effects, ItemStack stack, double potency) {
		if(target.getType() == HitResult.Type.ENTITY) {
			EntityHitResult entityHit = (EntityHitResult) target;
			Entity entity = entityHit.getEntity();
			float damage = ArcanusConfig.AttackEffects.DamageEffectProperties.baseDamage;

			if(entity instanceof Player playerTarget && caster instanceof Player playerCaster && !playerCaster.canHarmPlayer(playerTarget))
				return;

			if(caster != null && entity instanceof Targetable targetable && targetable.arcanus$canBeTargeted()) {
				List<DamageModifyingSpellEffect> modifiers = effects.stream().filter(spellEffect -> spellEffect instanceof DamageModifyingSpellEffect).map(spellEffect -> (DamageModifyingSpellEffect) spellEffect).toList();
				DamageSource damageSource = modifiers.stream().map(spellEffect -> spellEffect.damageSource(level.damageSources())).findAny().orElse(sourceEntity instanceof Projectile projectile ? ArcanusDamageTypes.getMagicProjectileDamage(projectile, caster) : ArcanusDamageTypes.getMagicDamage(caster));

				for(Float value : modifiers.stream().map(spellEffect -> spellEffect.multiplyDamage(entity)).toList())
					damage *= value;

				entity.invulnerableTime = 0;
				entity.hurt(damageSource, (float) (damage * potency));
			}
		}
	}

@Override
	public void cast(@Nullable LivingEntity caster, Vec3 castFrom, @Nullable Entity castSource, ServerLevel level, ItemStack stack, List<SpellEffect> effects, List<SpellGroup> spellGroups, int groupIndex, double potency) {
		Entity sourceEntity = castSource != null ? castSource : caster;
		float radius = ArcanusConfig.SpellShapes.BurstShapeProperties.radius;
		AABB boundingBox = new AABB(castFrom.add(-radius, -radius, -radius), castFrom.add(radius, radius, radius));
		potency += getPotencyModifier();

		// need to map to immutable, else they all end up as the same pos
		// https://github.com/CammiesCorner/Arcanus/issues/56
		for(BlockPos blockPos : BlockPos.betweenClosedStream(boundingBox).map(BlockPos::immutable).toList()) {
			Vec3 pos = Vec3.atCenterOf(blockPos);

			if(pos.distanceToSqr(castFrom) > radius * radius)
				continue;

			for(SpellEffect effect : new HashSet<>(effects))
				effect.effect(caster, sourceEntity, level, new BlockHitResult(pos, Direction.UP, blockPos, true), effects, stack, potency);
		}

		for(SpellEffect effect : new HashSet<>(effects)) {
			if(effect.singleCastOnly() && sourceEntity != null) {
				effect.effect(caster, sourceEntity, level, new EntityHitResult(sourceEntity), effects, stack, potency);
				continue;
			}

			for(Entity entity : level.getEntities(sourceEntity == caster ? caster : null, boundingBox, entity -> entity.isAlive() && !entity.isSpectator() && castFrom.distanceTo(entity.position()) <= radius))
				effect.effect(caster, sourceEntity, level, new EntityHitResult(entity), effects, stack, potency);
		}

		// TODO add vfx & sfx for burst
		level.gameEvent(caster, GameEvent.EXPLODE, new Vec3(castFrom.x(), castFrom.y(), castFrom.z()));
		level.playSeededSound(null, castFrom.x(), castFrom.y(), castFrom.z(), SoundEvents.GENERIC_EXPLODE, SoundSource.BLOCKS, 4f, (1f + (level.random.nextFloat() - level.random.nextFloat()) * 0.2f) * 0.7f, 1);

		for(ServerPlayer player : PlayerLookup.tracking(level, BlockPos.containing(castFrom.x(), castFrom.y(), castFrom.z())))
			Network.getNetworkHandler().sendToClient(new ClientboundBurstVfxPacket(castFrom, 4f, effects.contains(ArcanusSpellComponents.MINE.get())), player);

		castNext(caster, castFrom, castSource, level, stack, spellGroups, groupIndex, potency);
	}

public static void findAndTransferArcana(LevelAccessor level, BlockPos pos, ArcanaStack arcanaStack, double amount) {
		if(arcanaStack.isEmpty() || level.isClientSide())
			return;

		List<BlockPos> alreadyChecked = new ArrayList<>();
		List<BlockPos> newPipes = new ArrayList<>();
		AtomicReference<Float> arcanaReduction = new AtomicReference<>(1f);
		AtomicInteger addVertical = new AtomicInteger(0);

		alreadyChecked.add(pos);
		newPipes.add(pos);

		while(!newPipes.isEmpty()) {
			List.copyOf(newPipes).forEach(blockPos -> {
				for(Direction direction : Direction.values()) {
					BlockState state = level.getBlockState(blockPos);
					BlockPos sidePos = blockPos.relative(direction);
					BlockState sideState = level.getBlockState(sidePos);

					if(alreadyChecked.contains(sidePos))
						continue;

					if((state.is(ArcanusBlocks.ARCANA_PIPE.get()) && !state.getValue(ArcanaPipeBlock.CONNECTION_BY_DIRECTION.get(direction.getOpposite())))
						|| (state.is(ArcanusBlocks.ARCANA_PUMP.get()) && !state.getValue(ArcanaPumpBlock.AXIS).test(direction))
						|| (level.getBlockEntity(sidePos) instanceof ArcanaContainer container && (!container.outputDirections().contains(direction) || container.isFull())))
						continue;

					if(!blockPos.equals(pos) && level.getBlockEntity(pos) instanceof ArcanaContainer start && level.getBlockEntity(sidePos) instanceof ArcanaContainer end && end.inputDirections().contains(direction.getOpposite())) {
						transferArcana(start, end, arcanaStack, amount, arcanaReduction.get());
						newPipes.clear();
						break;
					}

					if(sideState.is(ArcanusBlocks.ARCANA_PUMP.get()) && sideState.getValue(ArcanaPumpBlock.AXIS).test(direction)) {
						addVertical.getAndAdd(10);
						arcanaReduction.set(Math.max(arcanaReduction.get() - 0.1f, 0f));
					}

					if(sideState.getBlock() instanceof AbstractPipeBlock) {
						BooleanProperty property = ArcanaPipeBlock.EXTENSION_BY_DIRECTION.get(direction.getOpposite());

						if(!alreadyChecked.contains(sidePos) && sideState.hasProperty(property) && sideState.getValue(property)
							&& direction == Direction.UP && sidePos.getY() > pos.getY() + addVertical.get())
							continue;

						newPipes.add(sidePos);
					}

					alreadyChecked.add(sidePos);
				}

				newPipes.remove(blockPos);
			});
		}
	}

public static void transferArcana(ArcanaContainer start, ArcanaContainer end, ArcanaStack startStack, double amount, double lossPercentage) {
		if(startStack.isEmpty() || end.isFull())
			return;

		if(!end.contains(startStack.arcana()))
			end.addArcanaStack(new ArcanaStack(startStack.arcana()));

		int index = end.indexOf(new ArcanaStack(startStack.arcana()));
		ArcanaStack endStack = end.getArcanaStack(index);
		double startArcanaAmount = startStack.amount();
		double endArcanaAmount = endStack.amount();

		if(!startStack.sameArcana(endStack) || startArcanaAmount <= 0 || endArcanaAmount >= end.maximumArcana())
			return;

		double maxDrain = Math.clamp(amount, 0, end.maximumArcana() - endArcanaAmount);

		end.setArcanaStack(new ArcanaStack(startStack.arcana(), endArcanaAmount + (maxDrain * lossPercentage)), index);
		start.setArcanaStack(new ArcanaStack(startStack.arcana(), startArcanaAmount - maxDrain), index);
	}

