@Inject(method = "onScroll", at = @At(value = "INVOKE", target = "Lnet/minecraft/world/entity/player/Inventory;swapPaint(D)V"), locals = LocalCapture.CAPTURE_FAILSOFT, cancellable = true)
	private void cycleSpellBookPouch(long windowPointer, double xOffset, double yOffset, CallbackInfo ci, boolean bl, double d, double e, double f, int i, int j, int k) {
		if(minecraft.player.getMainHandItem().getItem() instanceof StaffItem && minecraft.player.isCrouching() && TrinketsApi.getTrinketComponent(minecraft.player).get() instanceof TrinketComponent component && component.isEquipped(ArcanusItems.BOOK_POUCH.get())) {
			ItemStack stack = component.getEquipped(ArcanusItems.BOOK_POUCH.get()).getFirst().getB();
			BookPouchComponent spellBooks = stack.getOrDefault(ArcanusDataComponents.BOOK_POUCH.get(), BookPouchComponent.EMPTY);

			if(!spellBooks.spellBooks().isEmpty() && spellBooks.spellBooks().stream().filter(Predicate.not(ItemStack::isEmpty)).count() > 1) {
				int index = stack.getOrDefault(ArcanusDataComponents.BOOK_POUCH_INDEX.get(), 0) + k;

				if(index < 0)
					index = BookPouchItem.SLOT_COUNT - 1;
				else if(index >= BookPouchItem.SLOT_COUNT)
					index = 0;

				while(spellBooks.spellBooks().get(index).isEmpty()) {
					index += k;

					if(index < 0)
						index = BookPouchItem.SLOT_COUNT - 1;
					else if(index >= BookPouchItem.SLOT_COUNT)
						index = 0;
				}

				Network.getNetworkHandler().sendToServer(new ServerboundCycleBookPouchPacket(index));
			}

			ci.cancel();
		}
	}

@Inject(method = "tick", at = @At("HEAD"))
	private void tick(CallbackInfo info) {
		if(!level().isClientSide() && ArcanusComponents.PATTERN_COMPONENT.isProvidedBy(this) && ArcanusComponents.CASTING_COMPONENT.isProvidedBy(this)) {
			prevVelocity = getDeltaMovement();

			AttributeInstance speedAttr = getAttribute(Attributes.MOVEMENT_SPEED);
			List<Pattern> pattern = ArcanusComponents.getPattern(self);
			ItemStack stack = getMainHandItem();

			if(speedAttr != null) {
				if(stack.getItem() instanceof StaffItem && ArcanusComponents.isCasting(self) && pattern.size() == 3) {
					Optional<TrinketComponent> optional = TrinketsApi.getTrinketComponent(self);

					if(optional.isPresent()) {
						ItemStack spellBook = ArcanusHelper.getActiveSpellBook(self);
						SpellBookComponent spellBookComponent = spellBook.getOrDefault(ArcanusDataComponents.SPELL_BOOK.get(), SpellBookComponent.empty());
						int index = ArcanusHelper.getSpellIndex(pattern);

						if(spellBookComponent.hasSpell(index)) {
							Spell spell = spellBookComponent.getSpell(index);
							AttributeModifier speedMod = new AttributeModifier(Arcanus.SPELL_SPEED_MODIFIER_ID, spell.getWeight().getSlowdown(), AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);

							if(!speedAttr.hasModifier(Arcanus.SPELL_SPEED_MODIFIER_ID))
								speedAttr.addTransientModifier(speedMod);
						}
					}
				}
				else if(speedAttr.getModifier(Arcanus.SPELL_SPEED_MODIFIER_ID) != null) {
					speedAttr.removeModifier(Arcanus.SPELL_SPEED_MODIFIER_ID);
				}
			}
		}
	}

@WrapOperation(method = "baseTick", at = @At(value = "INVOKE", target = "Lnet/minecraft/world/entity/LivingEntity;isEyeInFluid(Lnet/minecraft/tags/TagKey;)Z"))
	private boolean drownInAJar(LivingEntity instance, TagKey<Fluid> tagKey, Operation<Boolean> original) {
		BlockState state = level().getBlockState(blockPosition());
		AABB insideJar = WardedJarBlock.INSIDE.bounds().inflate(0.001).move(blockPosition());

		if(state.is(ArcanusBlocks.WARDED_JAR.get()) && insideJar.contains(position()) && insideJar.contains(getEyePosition()))
			return getBlockY() + (0.078125 * state.getValue(WardedJarBlock.LEVEL)) + 0.0625 >= getEyeY();

		return original.call(instance, tagKey);
	}

public static boolean areItemStackTagsEqualForCrafting(ItemStack slotItem,ItemStack recipeItem)
    {
    	if (recipeItem == null || slotItem == null) return false;
    	if (recipeItem.getTagCompound()!=null && slotItem.getTagCompound()==null ) return false;
    	if (recipeItem.getTagCompound()==null ) return true;

    	Iterator iterator = recipeItem.getTagCompound().getKeySet().iterator();
        while (iterator.hasNext())
        {
            String s = (String)iterator.next();
            if (slotItem.getTagCompound().hasKey(s)) {
            	if (!slotItem.getTagCompound().getTag(s).toString().equals(
            			recipeItem.getTagCompound().getTag(s).toString())) {
            		return false;
            	}
            } else {
        		return false;
            }

        }
        return true;
    }

public static boolean compareTagsRelaxed(NBTTagCompound prime, NBTTagCompound other) {
		for (String key : prime.getKeySet()) {			
			if (!other.hasKey(key) || !prime.getTag(key).equals(other.getTag(key))) {
				return false;
			}
		}		
		return true;
	}

public static AspectList getEntityAspects(Entity entity) { 		
		AspectList tags = null;               
		String entityString = EntityList.getEntityString(entity);
	    if (entity instanceof EntityPlayer) {
	    	tags = new AspectList();
	    	tags.add(Aspect.MAN, 4);        	
			Random rand = new Random(((EntityPlayer)entity).getName().hashCode());
	    	Aspect[] posa = Aspect.aspects.values().toArray(new Aspect[]{});
			tags.add(posa[rand.nextInt(posa.length)], 15);
	    	tags.add(posa[rand.nextInt(posa.length)], 15);
	    	tags.add(posa[rand.nextInt(posa.length)], 15);
	    } else {
	        f1:
			for (ThaumcraftApi.EntityTags et:CommonInternals.scanEntities) {
				if (!et.entityName.equals(entityString)) continue;
				if (et.nbts==null || et.nbts.length==0) {
					tags = et.aspects;
				} else {
					NBTTagCompound tc = new NBTTagCompound();
					entity.writeToNBT(tc);
					for (EntityTagsNBT nbt:et.nbts) {
						if (tc.hasKey(nbt.name)) {
							if (!ThaumcraftApiHelper.getNBTDataFromId(tc, tc.getTagId(nbt.name), nbt.name).equals(nbt.value)) continue f1; 
						} else {
							continue f1;
						}
					}
					tags = et.aspects;
				}
			}
	    }           	
		return tags;
	}

