@Override
	public void render(Entity entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float netHeadPitch, float scale) {
		prepareForRender(entity);
		this.setRotationAngles(limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, netHeadPitch, scale, entity);

		this.setHeadRotation();
		this.setChestRotation(entity);
		this.setLegsRotation();
		this.setBootRotation();
		GlStateManager.pushMatrix();

        head.showModel = slot == EntityEquipmentSlot.HEAD;
        chest.showModel = slot == EntityEquipmentSlot.CHEST;
        armR.showModel = slot == EntityEquipmentSlot.CHEST;
        armL.showModel = slot == EntityEquipmentSlot.CHEST;
        legR.showModel = slot == EntityEquipmentSlot.LEGS;
        legL.showModel = slot == EntityEquipmentSlot.LEGS;
        legsTop.showModel = slot == EntityEquipmentSlot.LEGS;
        bootR.showModel = slot == EntityEquipmentSlot.FEET;
        bootL.showModel = slot == EntityEquipmentSlot.FEET;

        if (this.isChild)
        {
            float f = 2.0F;
            GlStateManager.scale(1.5F / f, 1.5F / f, 1.5F / f);
            GlStateManager.translate(0.0F, 16.0F * scale, 0.0F);
            this.renderHead(scale*armorScale);
            GlStateManager.popMatrix();
            GlStateManager.pushMatrix();
            GlStateManager.scale(1.0F / f, 1.0F / f, 1.0F / f);
            GlStateManager.translate(0.0F, 24.0F * scale, 0.0F);
            this.renderPartsMinusHead(scale*armorScale);
            GlStateManager.translate(0.0F, 24.0F * scale, 0.0F);
            this.renderLegs(scale*armorScale);
        }
        else
        {
            if (entity.isSneaking())
            {
                GlStateManager.translate(0.0F, 0.2F, 0.0F);
            }

            this.renderParts(scale*armorScale);
            GlStateManager.translate(0.0F, -2.0F * scale, 0.0F);
            this.renderArms(scale*armorScale);
            GlStateManager.translate(0.0F, 2.0F * scale, 0.0F);
            GlStateManager.translate(0.0F, 24.0F * scale, 0.0F);
            this.renderLegs(scale*armorScale);
        }

        GlStateManager.popMatrix();

		GlStateManager.pushMatrix();
        if (this.cape != null){
        	this.setCapeRotation(entity);
    		cape.showModel = slot == EntityEquipmentSlot.CHEST;
	        if (this.cape.childModels.size() == 10 && cape.showModel){
		        for (int i = 1; i < 8; i ++){
					this.cape.childModels.get(i+2).showModel = false;
				}
				if (entity instanceof EntityLivingBase){
					ItemStack stack = ((EntityLivingBase)entity).getItemStackFromSlot(EntityEquipmentSlot.CHEST);
					if (stack.hasTagCompound()){
						for (int i = 1; i < 8; i ++){
							this.cape.childModels.get(i+2).showModel = slot == EntityEquipmentSlot.CHEST && stack.getTagCompound().hasKey("gem"+i);
						}
					}
				}
	        }
    		if (this.isChild)
            {
                float f = 2.0F;
                GlStateManager.scale(1.0F / f, 1.0F / f, 1.0F / f);
                GlStateManager.translate(0.0F, 24.0F * scale, 0.0F);
                this.renderCape(scale*armorScale);
            }
            else
            {
                if (entity.isSneaking())
                {
                    GlStateManager.translate(0.0F, 0.2F, 0.0F);
                }

                this.renderCape(scale*armorScale);
            }
        }
		GlStateManager.popMatrix();
	}

public void renderCape(Entity entity, float scale) {
        GlStateManager.pushMatrix();
        if (this.cape != null) {
            this.setCapeRotation(entity);
            cape.showModel = slot == EntityEquipmentSlot.CHEST;
            if (this.cape.childModels.size() == 10 && cape.showModel) {
                for (int i = 1; i < 8; i++) {
                    this.cape.childModels.get(i + 2).showModel = false;
                }
                if (entity instanceof EntityLivingBase) {
                    ItemStack stack = ((EntityLivingBase) entity).getItemStackFromSlot(EntityEquipmentSlot.CHEST);
                    if (stack.hasTagCompound()) {
                        for (int i = 1; i < 8; i++) {
                            this.cape.childModels.get(i + 2).showModel = slot == EntityEquipmentSlot.CHEST && stack.getTagCompound().hasKey("gem" + i);
                        }
                    }
                }
            }
            if (this.isChild) {
                float f = 2.0F;
                GlStateManager.scale(1.0F / f, 1.0F / f, 1.0F / f);
                GlStateManager.translate(0.0F, 24.0F * scale, 0.0F);
                cape.render(scale);
            } else {
                if (entity.isSneaking()) {
                    GlStateManager.translate(0.0F, 0.2F, 0.0F);
                }

                cape.render(scale);
            }
        }
        GlStateManager.popMatrix();
    }

public DefaultEmberItemCapability(@Nonnull ItemStack stack, double capacity) {
        this.stack = stack;
        if (!stack.hasTagCompound()) {
            stack.setTagCompound(new NBTTagCompound());
            setEmber(0);
            setEmberCapacity(capacity);
        } else {
            migrateLegacy();
        }
    }

@Override
    public boolean hasCapability(@Nonnull Capability<?> capability, @Nullable EnumFacing facing) {
        return capability == EmbersCapabilities.EMBER_CAPABILITY;
    }

@Nullable
    @Override
    public <T> T getCapability(@Nonnull Capability<T> capability, @Nullable EnumFacing facing) {
        if (capability == EmbersCapabilities.EMBER_CAPABILITY)
            return EmbersCapabilities.EMBER_CAPABILITY.cast(this);
        return null;
    }

@Override
    public double getEmber() {
        return stack.hasTagCompound() ? stack.getTagCompound().getDouble("ember") : 0;
    }

@Override
    public double getEmberCapacity() {
        return stack.hasTagCompound() ? stack.getTagCompound().getDouble("emberCapacity") : 0;
    }

@Override
    public void setEmber(double value) {
        if (stack.hasTagCompound()) {
            stack.getTagCompound().setDouble("ember", value);
        }
    }

@Override
    public void setEmberCapacity(double value) {
        if (stack.hasTagCompound()) {
            stack.getTagCompound().setDouble("emberCapacity", value);
        }
    }

@Override
    public double addAmount(double value, boolean doAdd) {
        double ember = getEmber();
        double capacity = getEmberCapacity();
        double added = Math.min(capacity - ember, value);
        double newEmber = ember + added;
        if (doAdd) {
            if (newEmber != ember)
                onContentsChanged();
            setEmber(ember + added);
        }
        return added;
    }

@Override
    public double removeAmount(double value, boolean doRemove) {
        double ember = getEmber();
        double removed = Math.min(ember, value);
        double newEmber = ember - removed;
        if (doRemove) {
            if (newEmber != ember)
                onContentsChanged();
            setEmber(ember - removed);
        }
        return removed;
    }

