public static void updateAbilities(ResourceKey<Level> level, LivingEntity entity) {
		ArrayList<Holder<MobEffect>> supportedEffects = new ArrayList<>();
		ArrayList<Integer> amplifiers = new ArrayList<>();
		ItemStack[] stack = {entity.getItemBySlot(EquipmentSlot.HEAD), entity.getItemBySlot(EquipmentSlot.CHEST), entity.getItemBySlot(EquipmentSlot.LEGS), entity.getItemBySlot(EquipmentSlot.FEET)};
		ArrayList<ItemDivineArmor> equipment = new ArrayList<>();
		for(ItemStack s : stack) if(s.getItem() instanceof ItemDivineArmor armor) equipment.add(armor);//list all divine armor pieces
		for(ItemDivineArmor armor : equipment) if(armor.supportedEffects != null) for(int i = 0; i < armor.supportedEffects.length; i++) {//list all theoretically supported armor effects and their amplifiers
			Holder<MobEffect> supportedEffect = armor.supportedEffects[i];
			if(!supportedEffects.contains(supportedEffect)) {
				supportedEffects.add(supportedEffect);
				amplifiers.add(armor.amplifier == null ? 0 : armor.amplifier[i]);
			}
		} boolean fullArmor = equipment.size() == 4;
		if(fullArmor) {
			ArmorMaterial mat = equipment.getFirst().getMaterial().value();
			for(int i = 1; fullArmor && i < 4; i++) fullArmor = equipment.get(i).getMaterial().value() == mat;//check if all armor pieces are of the same type
			if(fullArmor) for(int i = 0; i < supportedEffects.size(); i++) {//apply all not yet present supported effects with their respected amplifiers
				MobEffectInstance instance;
				Holder<MobEffect> supportedEffect = supportedEffects.get(i);
				boolean shouldRemove = false;
				if(!entity.hasEffect(supportedEffect) || (shouldRemove = !(instance = entity.getEffect(supportedEffect)).isInfiniteDuration() || !(instance instanceof ArmorEffectInstance))) {
					if(shouldRemove) entity.removeEffect(supportedEffect);
					entity.addEffect(new ArmorEffectInstance(supportedEffect, amplifiers.get(i)));
				} else if(supportedEffect.value() instanceof UpdatableArmorEffect update) update.update(level, entity);
			}
		}//the following if case is intentionally not an else case
		if(!fullArmor) for(Holder<MobEffect> supportedEffect : supportedEffects) if(entity.hasEffect(supportedEffect) && entity.getEffect(supportedEffect).isInfiniteDuration()) entity.removeEffect(supportedEffect);//remove all theoretically supported effects if full armor set is not present
	}

@SubscribeEvent
    public void playerTick(PlayerTickEvent.Pre event){
        Player player = event.getEntity();
        Level level = player.level();
        if(!level.isClientSide()) Arcana.regen(player);
        if(level.dimension() == LevelRegistry.ICEIKA) {
            if(!level.isClientSide() && (player.tickCount & 7) == 0) AttachmentRegistry.IN_DUNGEON.set(player, ((ServerLevel) level).structureManager().getStructureWithPieceAt(player.blockPosition(), TagRegistry.ICEIKA_DUNGEON).isValid());
            if(!player.isCreative() && !player.isSpectator()) {
                if(Utils.ICEIKA_WEATHER == 1 && level.isRaining() && player.getItemBySlot(EquipmentSlot.HEAD).isEmpty() && player.getRandom().nextFloat() < .1F && level.canSeeSky(player.blockPosition())) player.hurt(level.damageSources().source(DamageRegistry.HAIL.getKey()), 1);
                if(!level.isClientSide && !player.hasEffect(MobEffectRegistry.WARMTH) && !player.isOnFire() && !player.getItemBySlot(EquipmentSlot.CHEST).getTagEnchantments().keySet().contains(level.registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolderOrThrow(EnchantmentRegistry.INSULATION)) && level.getLightEngine().getLayerListener(LightLayer.BLOCK).getLightValue(player.blockPosition()) < 8) {
                    player.setSharedFlagOnFire(false);
                    if(player.isFullyFrozen()) {
                        player.setTicksFrozen(player.getTicksRequiredToFreeze() + 2);
                        if(player.getHealth() > 1 && player.tickCount % 40 == 0) player.hurt(level.damageSources().freeze(), .5F);
                    } else player.setTicksFrozen(player.getTicksFrozen() + 2 + player.getRandom().nextInt(2) + (Utils.ICEIKA_WEATHER == 2 ? player.getRandom().nextInt(2) : 0));
                }
            }
        } if(player.getItemBySlot(EquipmentSlot.CHEST).getAllEnchantments(CommonHooks.resolveLookup(Registries.ENCHANTMENT)).keySet().contains(level.registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolderOrThrow(EnchantmentRegistry.INSULATION))) {
    		int f = player.getTicksFrozen();
    		if(f > 0) player.setTicksFrozen(f - 2);
        }
    }

@SubscribeEvent
    public void onEntityLeave(EntityLeaveLevelEvent event) {
        if(!event.getLevel().isClientSide && event.getEntity() instanceof ItemEntity i && i.getAge() < i.lifespan) {
            ItemStack stack = i.getItem();
            if(stack.isEmpty()) return;
            BlockPos pos = i.blockPosition();
            Iterable<BlockPos> positions = BlockPos.betweenClosed(pos.offset(-1, -1, -1), pos.offset(1, 0, 1));
            ServerLevel level = (ServerLevel) event.getLevel();
            if(!level.isAreaLoaded(pos, 1)) return;
            List<FireConversionRecipe> recipes = level.getRecipeManager().getAllRecipesFor(FireConversionRecipe.TYPE).stream().filter(r -> r.value().inputItem().test(stack)).map(RecipeHolder::value).toList();
            BlockState state, prevState;
            for(BlockPos position : positions) {
                prevState = state = level.getBlockState(position);
                if(state.isAir()) continue;
                for(FireConversionRecipe recipe : recipes) if(recipe.inputState().test(state, level.random)) {
                    level.setBlock(position, Blocks.AIR.defaultBlockState(), Block.UPDATE_NONE);
                    Direction.Axis axis;
                    if(recipe.frame().isPresent() && recipe.portal().isPresent() && (axis = Utils.checkForFrame(level, position, recipe.frame().get())) != null) {
                        if(!level.isClientSide) Utils.spreadBlock(level, recipe.portal().get().getState(level.random, position).setValue(BlockStateProperties.HORIZONTAL_AXIS, axis), position, Blocks.AIR, axis);
                        level.playSound(null, pos, SoundEvents.FLINTANDSTEEL_USE, SoundSource.BLOCKS, 1, level.random.nextFloat() * .4F + .8F);
                        level.playSound(null, pos, SoundRegistry.PORTAL_CREATION.get(), SoundSource.BLOCKS, 1, 1F);
                        if(recipe.outputState().isPresent()) prevState = recipe.outputState().get().getState(level.getRandom(), position);
                        state = Blocks.AIR.defaultBlockState();
                    } else if(recipe.outputState().isPresent()) level.setBlock(position, state = recipe.outputState().get().getState(level.getRandom(), position), 3);
                    else level.setBlock(position, prevState, Block.UPDATE_NONE);
                    if(recipe.outputItem().isPresent()) {
                        ItemStack output = recipe.outputItem().get().copy();
                        if(!output.isEmpty()) {
                            if(output.is(ItemRegistry.frozen_clock)) output.set(DataComponentRegistry.variant, Utils.determineTimeOfDay(level));
                            output.setCount(output.getCount() * stack.getCount());
                            ItemEntity itemEntity = new ItemEntity(level, i.getX(), i.getY(), i.getZ(), output);
                            itemEntity.setDefaultPickUpDelay();
                            itemEntity.setDeltaMovement(i.getDeltaMovement());
                            level.addFreshEntity(itemEntity);
                        }
                    } if(recipe.advancement().isPresent()) {
                        List<ServerPlayer> players = Utils.getNearbyPlayers(level, i.getX(), i.getY(), i.getZ(), 9);
                        for(ServerPlayer player : players) Utils.awardAdvancement(level.getServer(), player, recipe.advancement().get(), recipe.advancementCriteria().orElse("impossible"));
                    } if(state.isAir()) {
                        if(prevState.is(BlockRegistry.icyFire)) level.playSound(null, position, SoundRegistry.FREEZE.get(), SoundSource.BLOCKS, .8F, 1.5F);
                        else if(prevState.is(BlockRegistry.enchantedFlame)) {
                            level.playSound(null, position, SoundEvents.ENCHANTMENT_TABLE_USE, SoundSource.BLOCKS, 0.8F, 1.2F);
                            level.playSound(null, position, SoundEvents.ENDERMAN_TELEPORT, SoundSource.BLOCKS, 0.8F, 1F);
                        } else if(prevState.is(BlockTags.FIRE)) level.playSound(null, position, SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS);
                        else if(prevState.getFluidState().is(FluidRegistry.SMOLDERING_TAR_FLUID.get())) {
                            level.playSound(null, position, SoundEvents.LAVA_EXTINGUISH, SoundSource.BLOCKS, 1, 1);
                            level.sendParticles(ParticleTypes.SMOKE, i.getX(), i.getY(), i.getZ(), 25, .5, .5, .5, .01);
                        }
                    } else if(state.is(BlockRegistry.icyFire)) {
                        if(prevState.is(BlockRegistry.icyFire)) level.playSound(null, position, SoundRegistry.FREEZE.get(), SoundSource.BLOCKS, .8F, 1.5F);
                        else level.playSound(null, position, SoundRegistry.FREEZE.get(), SoundSource.BLOCKS, 1, 1);
                    } else if(state.is(BlockRegistry.hellFire)) {
                        level.sendParticles(ParticleTypes.SOUL, i.getX(), i.getY(), i.getZ(), 4, .2, .2, .2, 0);
                        level.playSound(null, position, SoundEvents.SCULK_SHRIEKER_SHRIEK, SoundSource.BLOCKS, .7F, 1.5F);
                        level.playSound(null, position, SoundEvents.FIRECHARGE_USE, SoundSource.BLOCKS, 1, 1);
                    } else if(state.is(BlockRegistry.divineFlame) || state.is(BlockRegistry.wildFlame) || state.is(BlockRegistry.enchantedFlame) || state.is(BlockRegistry.skyFire) || state.is(BlockRegistry.mortumEmbers)) {
                        level.playSound(null, position, SoundEvents.ENCHANTMENT_TABLE_USE, SoundSource.BLOCKS, 1, 1);
                        level.playSound(null, position, SoundEvents.FIRECHARGE_USE, SoundSource.BLOCKS, 1, 1);
                    } return;
                } if(state.is(BlockTags.FIRE) && stack.is(CLOCKS) && Utils.clockUse(level, stack, position, state, Utils.getNearbyPlayers(level, i.getX(), i.getY(), i.getZ(), 9), null)) return;
            }
        }
    }

@SubscribeEvent
    public void onItemTooltip(final ItemTooltipEvent event) {
        List<Component> tooltip = event.getToolTip();
        ItemStack stack = event.getItemStack();
        if(stack.getItem() instanceof DiggerItem item && ClientConfig.Values.TOOL_TOOLTIPIFICATION) {
            tooltip.add(1, LocalizeUtils.efficiency((int)item.getTier().getSpeed()));
            TagKey<Block> tagKey = item.getTier().getIncorrectBlocksForDrops();
            HolderSet<Block> holderSet = BuiltInRegistries.BLOCK.getOrCreateTag(tagKey);
            if(holderSet.stream().anyMatch(holder -> holder.is(BlockTags.NEEDS_STONE_TOOL))) tooltip.add(2, LocalizeUtils.harvestLevel(Component.literal(Items.COAL.getName(stack).getString()).withStyle(DARK_GRAY)));
            else if(holderSet.stream().anyMatch(holder -> holder.is(BlockTags.NEEDS_IRON_TOOL))) tooltip.add(2, LocalizeUtils.harvestLevel(Component.literal(Items.LAPIS_LAZULI.getName(stack).getString()).withColor(5931746)));
            else if(holderSet.stream().anyMatch(holder -> holder.is(BlockTags.NEEDS_DIAMOND_TOOL))) tooltip.add(2, LocalizeUtils.harvestLevel(Component.literal(Items.DIAMOND.getName(stack).getString()).withColor(2293477)));
            else if(holderSet.stream().anyMatch(holder -> holder.is(NEEDS_NETHERITE_TOOL))) tooltip.add(2, LocalizeUtils.harvestLevel(Component.literal(Items.OBSIDIAN.getName(stack).getString()).withColor(7096985)));
            else tooltip.add(2, LocalizeUtils.harvestLevel(Component.literal(Items.OBSIDIAN.getName(stack).getString() + "+").withStyle(DARK_RED)));
        } if(stack.getDescriptionId().contains("torridite")) tooltip.add(1, LocalizeUtils.i18n("torridite", DARK_RED, BOLD));
    }

