public static ResourceLocation[] getResourceLocationList(Property property){
		return toResourceLocations(property.getStringList());
	}

public static ResourceLocation[] toResourceLocations(String... strings){
		return Arrays.stream(strings).map(s -> new ResourceLocation(s.toLowerCase(Locale.ROOT).trim())).toArray(ResourceLocation[]::new);
	}

@SuppressWarnings("unchecked") // Shut up java
	public static Pair<ResourceLocation, Short>[] parseItemMetaStrings(String... strings){
		return Arrays.stream(strings).map(Settings::parseItemMetaString).toArray(Pair[]::new);
	}

public static Pair<ResourceLocation, Short> parseItemMetaString(String string){

		string = string.toLowerCase(Locale.ROOT).trim();

		String item;
		short meta;

		int lastColon = string.lastIndexOf(':');

		if (lastColon > -1 && lastColon < string.length() - 1) { // if there is a colon and it's not the last char
			String metaString = string.substring(lastColon + 1);
			try {
				short parsedMeta = Short.parseShort(metaString);
				String itemString = string.substring(0, lastColon);

				// If itemString has no colon, it could be 'item:meta' or 'namespace:numeric_path'.
				// e.g., 'wool:1' vs 'mod:123'. We want to support 'wool:1' as item 'wool' with meta 1.
				// We can't reliably distinguish the two cases without knowing all namespaces, so we have to use
				// a heuristic. The original code favoured the 'item:meta' interpretation, let's stick with that.
				// The issue was with 'namespace:numeric_path' which this logic now handles.
				if (itemString.indexOf(':') == -1) {
					item = itemString;
					meta = parsedMeta;
				} else {
					// Disambiguate things like 'mod:123:4' (item 'mod:123' with meta 4) vs 'mod:item:123' (item 'mod:item' with meta 123)
					// If the bit before the last colon is a valid resource location, it's probably item:meta
					try {
						new ResourceLocation(itemString);
						item = itemString;
						meta = parsedMeta;
					} catch (Exception e) {
						item = string;
						meta = OreDictionary.WILDCARD_VALUE;
					}
				}

			} catch (NumberFormatException e) {
				// The part after colon is not a number, so it's part of the name
				item = string;
				meta = OreDictionary.WILDCARD_VALUE;
			}
		} else {
			item = string;
			meta = OreDictionary.WILDCARD_VALUE;
		}

		return Pair.of(new ResourceLocation(item), meta);
	}

public static boolean containsMetaBlock(Pair<ResourceLocation, Short>[] array, IBlockState block){
		return containsMetaThing(array, block.getBlock().getRegistryName(), (short)block.getBlock().getMetaFromState(block));
	}

public static boolean containsMetaItem(Pair<ResourceLocation, Short>[] array, ItemStack stack){
		return containsMetaThing(array, stack.getItem().getRegistryName(), (short)stack.getMetadata());
	}

public static boolean containsMetaThing(Pair<ResourceLocation, Short>[] array, ResourceLocation id, short metadata){
		return Arrays.asList(array).contains(Pair.of(id, metadata)) || Arrays.asList(array).contains(Pair.of(id, (short)OreDictionary.WILDCARD_VALUE));
	}

@EventHandler
	public void preInit(FMLPreInitializationEvent event){

		logger = event.getModLog();

		configDirectory = new File(event.getModConfigurationDirectory(), Wizardry.MODID);
		settings.initConfig(event);

		Calendar calendar = Calendar.getInstance();
		tisTheSeason = calendar.get(Calendar.MONTH) + 1 == 12 && calendar.get(Calendar.DAY_OF_MONTH) >= 24
				&& calendar.get(Calendar.DAY_OF_MONTH) <= 26;

		// Capabilities
		WizardData.register();
		DispenserCastingData.register();

		// Register things that don't have registries
		WizardryBlocks.registerTileEntities();
		WizardryLoot.register();
		WizardryAdvancementTriggers.register();
		Forfeit.register();
		BlockBookshelf.registerStandardBookModelTextures();

		// Client-side stuff (via proxies)
		proxy.registerRenderers();
		proxy.registerKeyBindings();

		// Commented out for 4.2.3 to get rid of the sound bug, reinstate once a fix is found.
		WizardrySounds.SPELLS = SoundCategory.PLAYERS;//CustomSoundCategory.add(Wizardry.MODID + "_spells");

		WizardryBaublesIntegration.init();
		WizardryAntiqueAtlasIntegration.init();

	}

@EventHandler
	public void init(FMLInitializationEvent event){
		proxy.registerResourceReloadListeners();

		settings.initConfigExtras();

		// Update constants with configured values
		settings.updateConstantsFromSettings();

		// World generators
		// Weight is a misnomer, it's actually the priority (where lower numbers get generated first)
		// Literally nothing on typical 'weight' values here, there isn't even an upper limit
		// Examples I've managed to find:
		// - Tinker's construct slime islands use 25
		GameRegistry.registerWorldGenerator(new WorldGenCrystalOre(), 0);
		GameRegistry.registerWorldGenerator(new WorldGenCrystalFlower(), 50);
		GameRegistry.registerWorldGenerator(new WorldGenWizardTower(), 20);
		GameRegistry.registerWorldGenerator(new WorldGenObelisk(), 20);
		GameRegistry.registerWorldGenerator(new WorldGenShrine(), 20);
		GameRegistry.registerWorldGenerator(new WorldGenLibraryRuins(), 20);
		GameRegistry.registerWorldGenerator(new WorldGenUndergroundLibraryRuins(), 20);

		// This is for the config change and missing mappings events
		MinecraftForge.EVENT_BUS.register(instance); // Since there's already an instance we might as well use it

		NetworkRegistry.INSTANCE.registerGuiHandler(this, new WizardryGuiHandler());
		WizardryPacketHandler.initPackets();

		// Post-registry extras
		BlockBookshelf.compileBookModelTextures();
		ContainerBookshelf.initDefaultBookItems();
		WizardryItems.registerDispenseBehaviours();
		WizardryItems.registerBannerPatterns();
		WandHelper.populateUpgradeMap();
		Spell.registry.forEach(Spell::init);
		SpellProperties.init();

		// Client-side stuff (via proxies)
		proxy.initGuiBits();
		proxy.registerParticles();
		proxy.registerItemColorHandlers();
		proxy.registerModelProperties();
		proxy.registerSoundEventListener();
	}

@EventHandler
	public void postInit(FMLPostInitializationEvent event){
		proxy.initialiseLayers();
		proxy.initialiseAnimations();

		SpellNetworkIDSorter.init();
	}

@EventHandler
	public void serverStarting(FMLServerStartingEvent event){
		event.registerServerCommand(new CommandCastSpell());
		event.registerServerCommand(new CommandSetAlly());
		event.registerServerCommand(new CommandViewAllies());
		event.registerServerCommand(new CommandDiscoverSpell());
