public static Item getArmour(Element element, ArmourClass armourClass, EntityEquipmentSlot slot){
		if(slot == null || slot.getSlotType() != Type.ARMOR)
			throw new IllegalArgumentException("Must be a valid armour slot");
		if(element == null) element = Element.MAGIC;
		String registryName = armourClass.name + "_" + armourClass.armourPieceNames.get(slot);
		if(element != Element.MAGIC) registryName = registryName + "_" + element.getName();
		return Item.REGISTRY.getObject(new ResourceLocation(Wizardry.MODID,  registryName));
	}

public static boolean isWearingFullSet(EntityLivingBase entity, @Nullable Element element, @Nullable ArmourClass armourClass){
		ItemStack helmet = entity.getItemStackFromSlot(EntityEquipmentSlot.HEAD);
		if(!(helmet.getItem() instanceof ItemWizardArmour)) return false;
		Element e = element == null ? ((ItemWizardArmour)helmet.getItem()).element : element;
		ArmourClass ac = armourClass == null ? ((ItemWizardArmour)helmet.getItem()).armourClass : armourClass;
		return Arrays.stream(InventoryUtils.ARMOUR_SLOTS)
				.allMatch(s -> entity.getItemStackFromSlot(s).getItem() instanceof ItemWizardArmour
						&& ((ItemWizardArmour)entity.getItemStackFromSlot(s).getItem()).element == e
						&& ((ItemWizardArmour)entity.getItemStackFromSlot(s).getItem()).armourClass == ac);
	}

public static boolean doAllArmourPiecesHaveMana(EntityLivingBase entity){
		return Arrays.stream(InventoryUtils.ARMOUR_SLOTS).noneMatch(s -> entity.getItemStackFromSlot(s).getItem() instanceof IManaStoringItem
						&& ((IManaStoringItem) entity.getItemStackFromSlot(s).getItem()).isManaEmpty(entity.getItemStackFromSlot(s)));
	}

@SubscribeEvent
	public static void onLivingSetAttackTargetEvent(LivingSetAttackTargetEvent event){
		// Undo the mob detection penalty for wearing armour when invisible
		// Only bother doing this for players because the penalty only applies to them
		if(event.getTarget() instanceof EntityPlayer && event.getEntityLiving() instanceof EntityLiving
				&& event.getEntityLiving().isInvisible()){

			int armourPieces = (int)Streams.stream(event.getTarget().getArmorInventoryList())
					.filter(s -> !s.isEmpty() && !(s.getItem() instanceof ItemWizardArmour))
					.count();

			if(armourPieces == 0) return;

			// Repeat the calculation from EntityAIFindNearestPlayer, but ignoring wizard armour
			IAttributeInstance attribute = event.getEntityLiving().getEntityAttribute(SharedMonsterAttributes.FOLLOW_RANGE);
			double followRange = attribute == null ? 16 : attribute.getAttributeValue();
			if(event.getTarget().isSneaking()) followRange *= 0.8;
			float f = (float)armourPieces / ((EntityPlayer)event.getTarget()).inventory.armorInventory.size();
			if(f < 0.1F) f = 0.1F;
			followRange *= 0.7F * f;
			// Don't need to worry about the isSuitableTarget check since it must already have been checked to get this far
			if(event.getTarget().getDistance(event.getEntity()) > followRange) ((EntityLiving)event.getEntityLiving()).setAttackTarget(null);
		}
	}

private Spell pickRandomSpell(ItemStack stack, Random random, SpellProperties.Context spellContext, EntityPlayer player){

		// We're now doing this first because we need to know which spells we have to play with before selecting a tier and element
		List<Spell> possibleSpells = Spell.getSpells(s -> s.isEnabled(spellContext) && s.applicableForItem(stack.getItem())
				// Remove excluded tiers/elements immediately (mainly because empty tier checks should account for excluded elements)
				&& (tiers == null || tiers.contains(s.getTier())) && (elements == null || elements.contains(s.getElement())));

		if(spells != null && !spells.isEmpty()){
			possibleSpells.retainAll(spells); // Normally you wouldn't specify a spells list AND tiers/elements... but you could!
		}

		if(stack.getItem() instanceof ItemScroll) possibleSpells.removeIf(s -> !s.isEnabled(SpellProperties.Context.SCROLL));
		if(stack.getItem() instanceof ItemSpellBook) possibleSpells.removeIf(s -> !s.isEnabled(SpellProperties.Context.BOOK));

		// Select a tier...

		List<Tier> possibleTiers = new ArrayList<>();

		if(tiers == null || tiers.isEmpty()){
			possibleTiers.addAll(Arrays.asList(Tier.values()));
		}else{
			possibleTiers.addAll(tiers);
		}
		// Remove all empty tiers
		possibleTiers.removeIf(t -> possibleSpells.stream().noneMatch(s -> s.getTier() == t)); // Lambdaception!

		if(possibleTiers.isEmpty()) return Spells.none; // Gotta disable a lot of spells for this to happen

		Tier tier = ignoreWeighting ? possibleTiers.get(random.nextInt(possibleTiers.size()))
				: Tier.getWeightedRandomTier(random, possibleTiers.toArray(new Tier[0]));

		// Remove all spells that aren't of the selected tier
		possibleSpells.removeIf(s -> s.getTier() != tier);
		if(possibleSpells.isEmpty()) return Spells.none; // Should be caught by the no-elements check but we might as well

		// Select an element...

		List<Element> possibleElements = new ArrayList<>();

		// Elements aren't weighted
		if(elements == null || elements.isEmpty()){
			possibleElements.addAll(Arrays.asList(Element.values()));
		}else{
			possibleElements.addAll(elements);
		}
		// Remove all empty elements
		possibleElements.removeIf(e -> possibleSpells.stream().noneMatch(s -> s.getElement() == e));

		if(possibleElements.isEmpty()) return Spells.none; // A bit more likely I guess, but still pretty unlikely

		Element element = possibleElements.get(random.nextInt(possibleElements.size()));

		// Remove all spells that aren't of the selected tier
		possibleSpells.removeIf(s -> s.getElement() != element);
		if(possibleSpells.isEmpty()) return Spells.none; // If it fails anywhere, it'll most likely be here

		if(player != null){

			float bias = undiscoveredBias;
			// Archivist's eyeglass increases undiscovered bias by 0.4 up to a maximum of 0.9
			if(ItemArtefact.isArtefactActive(player, WizardryItems.charm_spell_discovery))
				bias = Math.min(bias + 0.4f, 0.9f);

			// Remove either the undiscovered spells or the discovered ones, depending on the bias
			if(bias > 0){

				WizardData data = WizardData.get(player);

				int discoveredCount = (int)possibleSpells.stream().filter(data::hasSpellBeenDiscovered).count();
				// If none have been discovered or they've all been discovered, don't bother!
				if(discoveredCount > 0 && discoveredCount < possibleSpells.size()){
					// Kinda unintuitive but it's very neat!
					boolean keepDiscovered = random.nextFloat() > 0.5f + 0.5f * bias;
					possibleSpells.removeIf(s -> keepDiscovered != data.hasSpellBeenDiscovered(s));
				}
			}
		}

		return possibleSpells.get(random.nextInt(possibleSpells.size())); // Finally pick a spell
	}

@Override
	public IMessage onMessage(Message message, MessageContext ctx){

		// Just to make sure that the side is correct
		if(ctx.side.isServer()){

			final EntityPlayerMP player = ctx.getServerHandler().player;

			player.getServerWorld().addScheduledTask(() -> {

				ItemStack wand = player.getHeldItemMainhand();

				if(!(wand.getItem() instanceof ISpellCastingItem)){
					wand = player.getHeldItemOffhand();
				}

				switch(message.controlType){

				case APPLY_BUTTON:

					if(!(player.openContainer instanceof ContainerArcaneWorkbench)){
						Wizardry.logger.warn("Received a PacketControlInput, but the player that sent it was not " +
								"currently using an arcane workbench. This should not happen!");
					}else{
						((ContainerArcaneWorkbench)player.openContainer).onApplyButtonPressed(player);
					}

					break;

				case CLEAR_BUTTON:

					if(!(player.openContainer instanceof ContainerArcaneWorkbench)){
						Wizardry.logger.warn("Received a PacketControlInput, but the player that sent it was not " +
								"currently using an arcane workbench. This should not happen!");
					}else{
						((ContainerArcaneWorkbench)player.openContainer).onClearButtonPressed(player);
					}

					break;

				case NEXT_SPELL_KEY:

					if(wand.getItem() instanceof ISpellCastingItem){

						((ISpellCastingItem)wand.getItem()).selectNextSpell(wand);
						// This line fixes the bug with continuous spells casting when they shouldn't be
						player.stopActiveHand();
					}

					break;

				case PREVIOUS_SPELL_KEY:

					if(wand.getItem() instanceof ISpellCastingItem){

						((ISpellCastingItem)wand.getItem()).selectPreviousSpell(wand);
						// This line fixes the bug with continuous spells casting when they shouldn't be
						player.stopActiveHand();
					}

					break;

				case RESURRECT_BUTTON:

					if(player.isDead && Resurrection.getRemainingWaitTime(player.deathTime) == 0){

						ItemStack stack = InventoryUtils.getHotbar(player).stream()
								.filter(s -> Resurrection.canStackResurrect(s, player)).findFirst().orElse(null);

						if(stack != null){
							if(MinecraftForge.EVENT_BUS.post(new ResurrectionEvent(player, player))) break;
							// This should suffice, since this is the only way a player can cast resurrection when dead!
							((ISpellCastingItem)stack.getItem()).cast(stack, Spells.resurrection, player, EnumHand.MAIN_HAND, 0, new SpellModifiers());
							break;
						}
					}

					Wizardry.logger.warn("Received a resurrect button packet, but the player that sent it was not" +
							" currently able to resurrect. This should not happen!");

					break;

				case CANCEL_RESURRECT:

					if(player.world.getGameRules().getBoolean("keepInventory")) break; // Shouldn't even receive this

					if(player.isDead){

						ItemStack stack = InventoryUtils.getHotbar(player).stream()
								.filter(s -> Resurrection.canStackResurrect(s, player)).findFirst().orElse(null);

						if(stack != null){
							player.dropItem(stack, true, false);
							player.inventory.deleteStack(stack); // Might as well
							break;
						}

						Wizardry.logger.warn("Received a cancel resurrect packet, but the player that sent it was not" +
								" holding a wand with the resurrection spell. This should not happen!");
					}

					Wizardry.logger.warn("Received a cancel resurrect packet, but the player that sent it was not" +
							" currently dead. This should not happen!");

					break;

				case POSSESSION_PROJECTILE:

					if(!Possession.isPossessing(player)) Wizardry.logger.warn("Received a possession projectile packet, " +
							"but the player that sent it is not currently possessing anything!");

					Possession.shootProjectile(player);

					break;
				}
			});
		}

		return null;
	}

public CreativeTabListed(String label, List<Item> order){

			super(label, (stack1, stack2) -> {
				// Neither stack is in the creative tab
				if(!order.contains(stack1.getItem()) && !order.contains(stack2.getItem())) return 0;
				if(!order.contains(stack1.getItem())) return 1; // Only stack 2 is in the creative tab
				if(!order.contains(stack2.getItem())) return -1; // Only stack 1 is in the creative tab
				// Both stacks are in the creative tab
				return order.indexOf(stack1.getItem()) - order.indexOf(stack2.getItem());
			});

			this.order = order;
		}

protected static Strength forWeight(float weight){
			return Arrays.stream(values()).filter(s -> s.minWeight < weight).max(Comparator.naturalOrder()).orElse(NOTHING);
		}

@Override
	protected boolean onEntityHit(World world, Entity target, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse,
								  SpellModifiers modifiers){

		if(target instanceof EntityLiving && !blacklist.contains(target.getClass()) && caster instanceof EntityPlayer
				&& !isPossessing((EntityPlayer)caster)){

			EntityPlayer player = (EntityPlayer)caster;

			if(!player.isCreative() && player.getHealth() <= getProperty(CRITICAL_HEALTH).floatValue()){
				player.sendStatusMessage(new TextComponentTranslation(
						"spell." + this.getRegistryName() + ".insufficienthealth"), true);
				return false;
			}

			if(!world.isRemote){
				int duration = (int)(getProperty(EFFECT_DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade));
				if(possess(player, (EntityLiving)target, duration)){
					return true;
				}
			}
		}

		return false;
	}

@Override
	public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

		WizardData data = WizardData.get(caster);

		double radius = getProperty(EFFECT_RADIUS).doubleValue() * modifiers.get(WizardryItems.range_upgrade);

		if(!world.isRemote && caster.getServer() != null){
			// Potency reduces the time you have to wait to resurrect an ally
			int waitTime = (int)(getProperty(WAIT_TIME).floatValue() / modifiers.get(SpellModifiers.POTENCY));

			EntityPlayerMP nearestDeadAlly = caster.getServer().getPlayerList().getPlayers().stream()
					.filter(p -> !p.isEntityAlive() && p.deathTime > waitTime && (data.isPlayerAlly(p) || caster == p)
							&& p.getDistanceSq(caster) < radius * radius)
					.min(Comparator.comparingDouble(caster::getDistanceSq))
					.orElse(null);

			if(nearestDeadAlly != null){

				if(MinecraftForge.EVENT_BUS.post(new ResurrectionEvent(nearestDeadAlly, caster))) return false;

				// When the player entity dies, it is removed from world#loadedEntityList. However, it is NOT removed
				// from playerEntityList (and probably a few other places) until respawn is clicked, and since that
				// never happens here we need to clean up those references or the player will have duplicate entries
				// in some entity lists - and weirdness will ensue!
				world.removeEntity(nearestDeadAlly); // Clean up the old entity references
				resurrect(nearestDeadAlly); // Reset isDead, must be before spawning the player again
				world.spawnEntity(nearestDeadAlly); // Re-add the player to all the relevant entity lists

				// Notify clients to reset the appropriate fields, spawn particles and play sounds
				IMessage msg = new PacketResurrection.Message(nearestDeadAlly.getEntityId());
				WizardryPacketHandler.net.sendToDimension(msg, caster.dimension);

				if(caster == nearestDeadAlly){
					caster.getServer().getPlayerList().sendMessage(new TextComponentTranslation(
							"spell." + this.getRegistryName() + ".resurrect_self", caster.getDisplayName()));
				}else{
					caster.getServer().getPlayerList().sendMessage(new TextComponentTranslation(
							"spell." + this.getRegistryName() + ".resurrect_ally", nearestDeadAlly.getDisplayName(), caster.getDisplayName()));
				}

				return true;
			}
		}

		return false;
	}

public static boolean canStackResurrect(ItemStack stack, EntityPlayer player){
		return stack.getItem() instanceof ISpellCastingItem
				&& Arrays.asList(((ISpellCastingItem)stack.getItem()).getSpells(stack)).contains(Spells.resurrection)
				&& ((ISpellCastingItem)stack.getItem()).canCast(stack, Spells.resurrection, player, EnumHand.MAIN_HAND, 0, new SpellModifiers());
	}

