public void tick(Level level, BlockPos pos, BlockState p_155110_) {
    this.syncEnergy();
    if (this.requiresRedstone() && !this.isPowered()) {
      setLitProperty(false);
      return;
    }
    if (effects.size() == 0) {
      timer = 0;
    }
    int cost = POWERCONF.get();
    if (energy.getEnergyStored() < cost && (cost > 0)) {
      return;
    }
    energy.extractEnergy(cost, false);
    timer--;
    if (timer > 0) {
      setLitProperty(true);
      tryAffectEntities(cost);
    }
    else {
      //timer is <=zero, delete all effects
      effects.clear();
      ItemStack s = inventory.getStackInSlot(0);
      if (!s.isEmpty()) {
        Iterable<MobEffectInstance> newEffects = s.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY).getAllEffects();
        if (newEffects.iterator().hasNext()) {
          pullFromItem(newEffects);
        }
      }
      return;
    } //end of timer/potion checks
    tickBeam(level, worldPosition);
  }

