public static Map<String, String> getMappedBeheading() {
    Map<String, String> mappedBeheading = new HashMap<String, String>();
    for (String s : BEHEADING_SKINS.get()) {
      try {
        String[] stuff = s.split(":");
        String entity = stuff[0] + ":" + stuff[1];
        String skin = stuff[2];
        mappedBeheading.put(entity, skin);
      }
      catch (Exception e) {
        ModCyclic.LOGGER.error("Beheading Enchantment: Invalid config entry " + s);
      }
    }
    return mappedBeheading;
  }

public static boolean isFacadeAllowed(ItemStack item) {
    ResourceLocation itemId = BuiltInRegistries.ITEM.getKey(item.getItem());
    if (StringParseUtil.isInList(getFacadeIgnoreList(), itemId)) {
      return false;
    }
    return true;
  }

@SubscribeEvent
  public void onEntityUpdate(EntityTickEvent.Pre event) {
    if (!(event.getEntity() instanceof Player p)) { return; }
    Holder<Enchantment> h = EnchantUtil.holder(EnchantRegistry.LAUNCH, p);
    ItemStack armorStack = EnchantUtil.getFirstArmorStackWithEnchant(h, p);
    if (armorStack.isEmpty()) { return; }
    if ((p.hasImpulse == false || p.onGround()) && armorStack.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag().getInt(NBT_USES) > 0) {
      armorStack.update(DataComponents.CUSTOM_DATA, CustomData.EMPTY, d -> { CompoundTag t = d.copyTag(); t.putInt(NBT_USES, 0); return CustomData.of(t); });
    }
  }

public static void onKeyInput(Player player) {
    if (player == null || player.getVehicle() instanceof Boat) { return; }
    Holder<Enchantment> h = EnchantUtil.holder(EnchantRegistry.LAUNCH, player);
    ItemStack feet = EnchantUtil.getFirstArmorStackWithEnchant(h, player);
    if (feet.isEmpty() || player.isCrouching()) { return; }
    int level = EnchantUtil.getCurrentLevelTool(h, feet);
    if (level <= 0) { return; }
    if (player.getCooldowns().isOnCooldown(feet.getItem())) { return; }
    if (Minecraft.getInstance().options.keyJump.isDown()
        && player.getY() < player.yOld && player.hasImpulse && !player.isInWater()) {
      int uses = feet.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag().getInt(NBT_USES);
      player.fallDistance = 0;
      float angle = (player.getDeltaMovement().x == 0 && player.getDeltaMovement().z == 0) ? 90 : ROTATIONPITCH;
      EntityUtil.launch(player, angle, POWER);
      ParticleUtil.spawnParticle(player.getCommandSenderWorld(), ParticleTypes.CRIT, player.blockPosition(), 7);
      uses++;
      if (uses >= level) {
        if (!feet.isEmpty()) EntityUtil.setCooldownItem(player, feet.getItem(), COOLDOWN);
        uses = 0;
      }
      final int finalUses = uses;
      feet.update(DataComponents.CUSTOM_DATA, CustomData.EMPTY, d -> { CompoundTag t = d.copyTag(); t.putInt(NBT_USES, finalUses); return CustomData.of(t); });
      player.fallDistance = 0;
      PacketDistributor.sendToServer(new PacketPlayerFalldamage());
    }
  }

public static boolean isEnabled() {
    return CFG == null || CFG.get();
  }

private static Holder<Enchantment> getHolder(Player player) {
    try {
      return player.level().registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(EnchantRegistry.SOULBOUND);
    }
    catch (Exception e) {
      return null;
    }
  }

@SubscribeEvent
  public void onLivingDeath(LivingDeathEvent event) {
    if (!isEnabled()) {
      return;
    }
    if (!(event.getEntity() instanceof Player player)) {
      return;
    }
    if (player.level().isClientSide()) {
      return;
    }
    Holder<Enchantment> holder = getHolder(player);
    if (holder == null) {
      return;
    }
    HolderLookup.Provider provider = player.level().registryAccess();
    ListTag pending = new ListTag();
    Inventory inv = player.getInventory();
    for (int i = 0; i < inv.getContainerSize(); i++) {
      addIfSoulbound(holder, inv.getItem(i), i, provider, pending);
    }
    for (int i = 0; i < inv.armor.size(); i++) {
      addIfSoulbound(holder, inv.armor.get(i), 36 + i, provider, pending);
    }
    if (!inv.offhand.isEmpty()) {
      addIfSoulbound(holder, inv.offhand.get(0), 40, provider, pending);
    }
    if (!pending.isEmpty()) {
      PENDING.put(player.getUUID(), pending);
    }
  }

private static void addIfSoulbound(Holder<Enchantment> holder, ItemStack stack, int slot, HolderLookup.Provider provider, ListTag out) {
    if (stack.isEmpty() || EnchantmentHelper.getItemEnchantmentLevel(holder, stack) <= 0) {
      return;
    }
    Tag itemTag = stack.copy().save(provider);
    if (itemTag instanceof CompoundTag itemCtag) {
      CompoundTag entry = new CompoundTag();
      entry.put(NBT_ITEM, itemCtag);
      entry.putInt(NBT_SLOT, slot);
      out.add(entry);
    }
  }

@SubscribeEvent(priority = EventPriority.HIGHEST)
  public void onPlayerDrops(LivingDropsEvent event) {
    if (!isEnabled()) {
      return;
    }
    if (!(event.getEntity() instanceof Player player)) {
      return;
    }
    if (player.level().isClientSide()) {
      return;
    }
    Holder<Enchantment> holder = getHolder(player);
    ListTag pending = PENDING.remove(player.getUUID());
    if (holder == null || pending == null || pending.isEmpty()) {
      return;
    }
    event.getDrops().removeIf(drop -> {
      ItemStack stack = drop.getItem();
      return !stack.isEmpty() && EnchantmentHelper.getItemEnchantmentLevel(holder, stack) > 0;
    });
    player.getPersistentData().put(NBT_KEY, pending);
  }

@SubscribeEvent
  public void onClone(PlayerEvent.Clone event) {
    if (!event.isWasDeath()) {
      return;
    }
    Player original = event.getOriginal();
    Player respawned = event.getEntity();
    CompoundTag pdata = original.getPersistentData();
    if (!pdata.contains(NBT_KEY)) {
      return;
    }
    Tag savedTag = pdata.get(NBT_KEY);
    pdata.remove(NBT_KEY);
    if (!(savedTag instanceof ListTag savedList)) {
      return;
    }
    HolderLookup.Provider provider = respawned.level().registryAccess();
    for (Tag entryTag : savedList) {
      if (!(entryTag instanceof CompoundTag entry)) {
        continue;
      }
      ItemStack saved = ItemStack.parse(provider, entry.get(NBT_ITEM)).orElse(ItemStack.EMPTY);
      if (saved.isEmpty()) {
        continue;
      }
      int durabilityCost = DURABILITY_COST == null ? 5 : DURABILITY_COST.get();
      if (durabilityCost > 0 && saved.isDamageableItem() && !respawned.isCreative()) {
        saved.setDamageValue(Math.min(saved.getDamageValue() + durabilityCost, saved.getMaxDamage() - 1));
      }
      int slot = entry.getInt(NBT_SLOT);
      if (slot >= 0) {
        Inventory inv = respawned.getInventory();
        boolean canUseSlot = slot < inv.getContainerSize()
            ? inv.getItem(slot).isEmpty()
            : slot < 40 ? inv.armor.get(slot - 36).isEmpty()
            : slot == 40 && inv.offhand.get(0).isEmpty();
        if (canUseSlot) {
          if (slot < inv.getContainerSize()) {
            inv.setItem(slot, saved);
          }
          else if (slot < 40) {
            inv.armor.set(slot - 36, saved);
          }
          else {
            inv.offhand.set(0, saved);
          }
          continue;
        }
      }
      if (!respawned.getInventory().add(saved)) {
        respawned.drop(saved, false);
      }
    }
  }

