          count++;
          if (firstName == null) {
            firstName = inSlot.getHoverName();
          }
        }
      }
      data.putInt(NBT_COUNT, count);
      if (firstName != null) {
        data.putString(NBT_TOOLTIP, firstName.getString());
      }
      else {
        data.remove(NBT_TOOLTIP);
      }
      cardStack.set(DataComponents.CUSTOM_DATA, CustomData.of(data));
    }
  }

