@OnlyIn(Dist.CLIENT)
  @SubscribeEvent
  public static void registerItemColors(RegisterColorHandlersEvent.Item event) {
    event.register((stack, tintIndex) -> {
      if (tintIndex == 0) { //layer zero is outline, ignore this 
        return 0xFFFFFFFF;
      }
      //layer 1 is overlay  
      return ScreenLunchbox.getColour(stack);
    }, ItemRegistry.LUNCHBOX.get());
    //
    event.register((stack, tintIndex) -> {
      //layer 0 = outline, layer 2 = string overlay; only tint layer 1 (bag body)
      if (tintIndex != 1) {
        return 0xFFFFFFFF;
      }
      return ItemStorageBag.getColour(stack);
    }, ItemRegistry.STORAGE_BAG.get());
    //
    event.register((stack, tintIndex) -> {
      if (stack.has(DataComponents.CUSTOM_DATA) && tintIndex > 0) {
        //what entity is inside
        EntityType<?> thing = BuiltInRegistries.ENTITY_TYPE.get(ResourceLocation.parse(stack.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag().getString(EntityMagicNetEmpty.NBT_ENTITYID)));
        //pull the colours from the egg
        for (SpawnEggItem spawneggitem : SpawnEggItem.eggs()) {
          if (spawneggitem.getType(spawneggitem.getDefaultInstance()) == thing) {
            return 0xFF000000 | spawneggitem.getColor(tintIndex - 1);
          }
        }
      }
      return 0xFFFFFFFF;
    }, ItemRegistry.MOB_CONTAINER.get());
  }

public static ItemStack getCurio(Player player, Item match) {
    if (ModList.get().isLoaded(CompatConstants.CURIOS)) {
      try {
        SlotResult first = CuriosApi.getCuriosInventory(player)
            .flatMap(handler -> handler.findFirstCurio(match))
            .orElse(null);
        if (first != null && isMatching(first.stack(), match)) {
          return first.stack();
        }
      }
      catch (Exception e) {
        // if API not installed or fails
      }
    }
    return ItemStack.EMPTY;
  }

private static Triple<String, Integer, ItemStack> isCurioOrInventory(Player player, Item match) {
    Triple<String, Integer, ItemStack> stackFound = Triple.of("", -1, ItemStack.EMPTY);
    if (ModList.get().isLoaded(CompatConstants.CURIOS)) {
      try {
        SlotResult first = CuriosApi.getCuriosInventory(player)
            .flatMap(handler -> handler.findFirstCurio(match))
            .orElse(null);
        if (first != null && isMatching(first.stack(), match)) {
          ItemStack found = first.stack();
          if (found.getItem() instanceof IHasClickToggle) {
            IHasClickToggle testMe = (IHasClickToggle) found.getItem();
            if (testMe.isOn(found)) {
              return Triple.of(CompatConstants.CURIOS, first.slotContext().index(), found);
            }
            // else found but turned off, keep looking
          }
        }
      }
      catch (Exception e) {
        // if API not installed or fails
      }
    }
    for (int i = 0; i < player.getInventory().getContainerSize(); i++) {
      ItemStack temp = player.getInventory().getItem(i);
      if (isMatching(temp, match)) {
        if (temp.getItem() instanceof IHasClickToggle) {
          IHasClickToggle testMe = (IHasClickToggle) temp.getItem();
          if (testMe.isOn(temp)) {
            return Triple.of("player", i, temp);
          }
        }
      }
    }
    if (isMatching(player.getOffhandItem(), match)) {
      return Triple.of("offhand", -1, player.getOffhandItem());
    }
    if (isMatching(player.getMainHandItem(), match)) {
      return Triple.of("hand", -1, player.getMainHandItem());
    }
    return stackFound;
  }

public static boolean tryFillPositionFromTank(Level world, BlockPos posSide, Direction sideOpp, IFluidHandler tankFrom, final int amount) {
    if (tankFrom == null || amount <= 0) {
      return false;
    }
    try {
      IFluidHandler fluidTo = FluidUtil.getFluidHandler(world, posSide, sideOpp).orElse(null);
      if (fluidTo == null) {
        return false;
      }
      FluidStack toBeDrained = tankFrom.drain(amount, IFluidHandler.FluidAction.SIMULATE);
      if (toBeDrained == null || toBeDrained.isEmpty()) {
        return false;
      }
      final int filledAmount = fluidTo.fill(toBeDrained, IFluidHandler.FluidAction.EXECUTE);
      if (filledAmount <= 0) {
        return false;
      }
      final FluidStack drained = tankFrom.drain(filledAmount, IFluidHandler.FluidAction.EXECUTE);
      final int drainedAmount = drained.getAmount();
      //sanity check
      if (filledAmount != drainedAmount) {
        ModCyclic.LOGGER.error("Imbalance filling fluids, filled " + filledAmount + " drained " + drainedAmount);
      }
      return true;
    }
    catch (Exception e) {
      ModCyclic.LOGGER.error("A fluid tank had an issue when we tried to fill", e);
      //charset crashes here i guess
      //https://github.com/PrinceOfAmber/Cyclic/issues/605
      // https://github.com/PrinceOfAmber/Cyclic/issues/605https://pastebin.com/YVtMYsF6
      return false;
    }
  }

