private static boolean attemptBreak(Level world, BlockPos pos, BlockState blockState, @Nullable Player player, @Nullable InteractionHand hand,
            ItemStack itemStack, ToolAction toolAction, int min, int multiplier) {

        if (player == null) {
            return false;
        }

        int integrity = blockState.getValue(propIntegrity);

        int progress = CastOptional.cast(itemStack.getItem(), IToolProvider.class)
                .map(item -> item.getToolLevel(itemStack, toolAction))
                .map(level -> (level - min) * multiplier)
                .orElse(1);

        if (integrity - progress >= 0) {
            if (TetraToolActions.hammer.equals(toolAction)) {
                world.playSound(player, pos, SoundEvents.ZOMBIE_ATTACK_IRON_DOOR, SoundSource.PLAYERS, 1, 0.5f);
            } else {
                world.playSound(player, pos, SoundEvents.LADDER_STEP, SoundSource.PLAYERS, 0.7f, 2f);
            }

            world.setBlockAndUpdate(pos, blockState.setValue(propIntegrity, integrity - progress));
        } else {
            boolean didBreak = EffectHelper.breakBlock(world, player, itemStack, pos, blockState, false, false);
            if (didBreak && world instanceof ServerLevel) {
                BlockInteraction.getLoot(interactionLootTable, player, hand, (ServerLevel) world, blockState)
                        .forEach(lootStack -> popResource(world, pos, lootStack));
            }
        }

        return true;
    }

private static List<BlockPos> getConnectedBlocks(Level world, BlockPos pos, List<BlockPos> visited, boolean isXAxis) {
        if (!visited.contains(pos) && world.getBlockState(pos).getBlock() instanceof ForgedVentBlock) {
            visited.add(pos);

            getConnectedBlocks(world, pos.above(), visited, isXAxis);
            getConnectedBlocks(world, pos.below(), visited, isXAxis);

            if (isXAxis) {
                getConnectedBlocks(world, pos.east(), visited, isXAxis);
                getConnectedBlocks(world, pos.west(), visited, isXAxis);
            } else {
                getConnectedBlocks(world, pos.north(), visited, isXAxis);
                getConnectedBlocks(world, pos.south(), visited, isXAxis);
            }
        }

        return visited;
    }

private static boolean hit(Level world, BlockPos pos, @Nullable Player playerEntity, InteractionHand hand) {
        if (FeatureFlag.isEnabled(FeatureFlag.bedrockExtraction)) {
            int amount = Optional.ofNullable(playerEntity)
                    .map(player -> player.getItemInHand(hand))
                    .filter(itemStack -> itemStack.getItem() instanceof IToolProvider)
                    .map(itemStack -> ((IToolProvider) itemStack.getItem()).getToolEfficiency(itemStack, TetraToolActions.hammer))
                    .map(Math::round)
                    .orElse(4);

            TileEntityOptional.from(world, pos, ChthonicExtractorTile.class).ifPresent(tile -> tile.damage(amount));
            FracturedBedrockBlock.pierce(world, pos.below(), amount);
            world.playSound(playerEntity, pos, SoundEvents.NETHERITE_BLOCK_HIT, SoundSource.PLAYERS, 0.8f, 0.5f);
            return true;
        }
        return false;
    }

@Override
    protected void onHit(HitResult rayTraceResult) {
        if (!level().isClientSide
                && rayTraceResult.getType() == HitResult.Type.BLOCK
                && getDeltaMovement().lengthSqr() > 0.95) {
            ServerPlayer shooter = CastOptional.cast(getOwner(), ServerPlayer.class).orElse(null);
            BlockPos pos = ((BlockHitResult) rayTraceResult).getBlockPos();

            if (shooter != null && breakBlock(level(), pos, shooter)) {
                breakAround(level(), pos, ((BlockHitResult) rayTraceResult).getDirection(), shooter);
                setDeltaMovement(getDeltaMovement().scale(0.95f));
                hitAdditional();
                return;
            }
        }

        super.onHit(rayTraceResult);
    }

