public ItemStack applyCraftEffects(Level world, BlockPos pos, BlockState blockState, ItemStack targetStack, String slot, boolean isReplacing,
            Player player, ToolAction requiredTool, int requiredLevel, boolean consumeResources) {
        if (consumeResources) {
            consumeFuel(world, pos);
        }

        if (isReplacing) {
            int preciseLevel = TileEntityOptional.from(world, pos, HammerBaseBlockEntity.class)
                    .map(te -> te.getEffectLevel(HammerEffect.precise))
                    .orElse(0);

            if (preciseLevel > 0) {
                ItemStack upgradedStack = targetStack.copy();

                ItemModuleMajor.addImprovement(upgradedStack, slot, qualityImprovementKey, preciseLevel);
                return upgradedStack;
            }
        }

        return targetStack;
    }

@Override
    public InteractionResult use(final BlockState blockState, final Level world, final BlockPos pos, final Player player, final InteractionHand hand,
            final BlockHitResult rayTraceResult) {
        Direction blockFacing = blockState.getValue(facingProp);
        HammerBaseBlockEntity te = TileEntityOptional.from(world, pos, HammerBaseBlockEntity.class).orElse(null);
        ItemStack heldStack = player.getItemInHand(hand);
        Direction facing = rayTraceResult.getDirection();

        if (te == null) {
            return InteractionResult.FAIL;
        }

        if (blockFacing.getAxis().equals(facing.getAxis())) {
            int slotIndex = blockFacing.equals(facing) ? 0 : 1;
            if (te.hasCellInSlot(slotIndex)) {
                ItemStack cell = te.removeCellFromSlot(slotIndex);
                if (player.getInventory().add(cell)) {
                    player.playSound(SoundEvents.ITEM_PICKUP, 1, 1);
                } else {
                    popResource(world, pos.relative(facing), cell);
                }

                world.playSound(player, pos, SoundEvents.IRON_TRAPDOOR_CLOSE, SoundSource.PLAYERS, 0.5f, 0.6f);

                if (!player.level().isClientSide) {
                    BlockUseCriterion.trigger((ServerPlayer) player, world.getBlockState(pos), ItemStack.EMPTY, getAdvancementData(world, pos));
                }

                return InteractionResult.sidedSuccess(player.level().isClientSide);
            } else if (heldStack.getItem() instanceof ThermalCellItem) {
                te.putCellInSlot(heldStack, slotIndex);
                player.setItemInHand(hand, ItemStack.EMPTY);
                world.playSound(player, pos, SoundEvents.IRON_TRAPDOOR_CLOSE, SoundSource.PLAYERS, 0.5f, 0.5f);

                if (!player.level().isClientSide) {
                    BlockUseCriterion.trigger((ServerPlayer) player, world.getBlockState(pos), heldStack, getAdvancementData(world, pos));
                }

                return InteractionResult.sidedSuccess(player.level().isClientSide);
            }
        } else {
            boolean isA = Rotation.CLOCKWISE_90.rotate(blockFacing).equals(facing);

            if (te.getEffect(isA) == null) {
                boolean success = te.setModule(isA, heldStack.getItem());
                if (success) {
                    if (!player.level().isClientSide) {
                        BlockUseCriterion.trigger((ServerPlayer) player, world.getBlockState(pos), heldStack, getAdvancementData(world, pos));
                    }

                    world.playSound(player, pos, SoundEvents.IRON_TRAPDOOR_CLOSE, SoundSource.PLAYERS, 0.5f, 0.5f);
                    heldStack.shrink(1);

                    if (world.isClientSide) {
                        InteractiveBlockOverlay.markDirty();
                    }

                    return InteractionResult.sidedSuccess(player.level().isClientSide);
                }
            }
        }

        return BlockInteraction.attemptInteraction(world, world.getBlockState(pos), pos, player, hand, rayTraceResult);
    }

@Override
    public void load(CompoundTag compound) {
        super.load(compound);

        slots = new ItemStack[2];
        if (compound.contains(slotsKey)) {
            ListTag tagList = compound.getList(slotsKey, 10);

            for (int i = 0; i < tagList.size(); i++) {
                CompoundTag itemCompound = tagList.getCompound(i);
                int slot = itemCompound.getByte(indexKey) & 255;

                if (slot < this.slots.length) {
                    this.slots[slot] = ItemStack.of(itemCompound);
                }
            }
        }

        moduleA = null;
        if (compound.contains(moduleAKey)) {
            byte data = compound.getByte(moduleAKey);
            if (data < HammerEffect.values().length) {
                moduleA = HammerEffect.values()[data];
            }
        }

        moduleB = null;
        if (compound.contains(moduleBKey)) {
            byte data = compound.getByte(moduleBKey);
            if (data < HammerEffect.values().length) {
                moduleB = HammerEffect.values()[data];
            }
        }

        redstonePower = compound.getInt(redstoneKey);
    }

public void tick(Level level, BlockPos pos, BlockState state) {
        if (redstonePower > 0 && level.getGameTime() % tickrate() == 0 && level.hasNeighborSignal(pos) && isFunctional()) {
            BlockPos targetPos = pos.below(2);
            BlockState targetState = level.getBlockState(targetPos);

            HammerHeadBlockEntity head = TileEntityOptional.from(level, pos.below(), HammerHeadBlockEntity.class).orElse(null);

            if (head == null || head.isJammed()) {
                return;
            }

            CastOptional.cast(targetState.getBlock(), IInteractiveBlock.class)
                    .map(block -> block.getPotentialInteractions(level, targetPos, targetState, Direction.UP, Collections.singletonList(TetraToolActions.hammer)))
                    .stream()
                    .flatMap(Arrays::stream)
                    .filter(interaction -> TetraToolActions.hammer.equals(interaction.requiredTool))
                    .filter(interaction -> getHammerLevel() >= interaction.requiredLevel)
                    .findFirst()
                    .ifPresent(interaction -> {
                        interaction.applyOutcome(level, targetPos, targetState, null, null, Direction.UP);

                        // the workbench triggers the hammer on the server side, so no need to consume fuel and play sounds
                        if (!(targetState.getBlock() instanceof AbstractWorkbenchBlock)) {
                            if (!level.isClientSide) {
                                consumeFuel();
                            } else {
                                head.activate();
                                level.playSound(null, pos, SoundEvents.ANVIL_LAND, SoundSource.BLOCKS, 0.2f, (float) (0.5 + Math.random() * 0.2));
                            }
                        } else {
                            head.activate();
                        }
                    });
        }
    }

