@Override
    public void perform(Player player, ItemStack targetStack, WorkbenchTile workbench) {
        if (player != null && !player.level().isClientSide) {
            ServerLevel world = (ServerLevel) player.level();
            LootTable table = world.getServer().getLootData().getLootTable(lootTable);
            ItemStack toolStack = requiredTools.getLevelMap().entrySet().stream()
                    .min(Map.Entry.comparingByValue())
                    .map(entry -> {
                        ItemStack providingStack = PropertyHelper.getPlayerProvidingItemStack(entry.getKey(), entry.getValue(), player);

                        if (providingStack.isEmpty()) {
                            providingStack = PropertyHelper.getToolbeltProvidingItemStack(entry.getKey(), entry.getValue(), player);
                        }

                        return providingStack;
                    })
                    .orElse(ItemStack.EMPTY);

            LootParams context = new LootParams.Builder(world)
                    .withLuck(player.getLuck())
                    .withParameter(LootContextParams.TOOL, toolStack)
                    .withParameter(LootContextParams.THIS_ENTITY, player)
                    .withParameter(LootContextParams.ORIGIN, player.position())
                    .create(lootParameters);

            table.getRandomItems(context).forEach(itemStack -> {
                if (!player.getInventory().add(itemStack)) {
                    player.drop(itemStack, false);
                }
            });

            BlockPos pos = workbench.getBlockPos();
            world.playSound(null, pos, SoundEvents.STONE_BREAK, player.getSoundSource(),
                    1.0F, 1.5f + (float) Math.random() * 0.5f);

            world.sendParticles(new ItemParticleOption(ParticleTypes.ITEM, targetStack),
                    pos.getX() + 0.5d, pos.getY() + 1.1d, pos.getZ() + 0.5d,
                    4, 0, 0, 0,
                    0.1f);

            // todo: add proper criteria
            CriteriaTriggers.CONSUME_ITEM.trigger((ServerPlayer) player, targetStack);

            targetStack.setCount(targetStack.getCount() - 1);
            workbench.setChanged();
        } else if (!workbench.getLevel().isClientSide) {
            ServerLevel world = (ServerLevel) workbench.getLevel();
            LootTable table = world.getServer().getLootData().getLootTable(lootTable);

            LootParams context = new LootParams.Builder(world)
                    .withParameter(LootContextParams.ORIGIN, Vec3.upFromBottomCenterOf(workbench.getBlockPos(), 1.1f))
                    .create(lootParameters);

            table.getRandomItems(context).forEach(itemStack -> Block.popResource(world, workbench.getBlockPos().above(), itemStack));

            BlockPos pos = workbench.getBlockPos();
            world.playSound(null, pos, SoundEvents.STONE_BREAK, SoundSource.BLOCKS,
                    1.0F, 1.5f + (float) Math.random() * 0.5f);

            world.sendParticles(new ItemParticleOption(ParticleTypes.ITEM, targetStack),
                    pos.getX() + 0.5d, pos.getY() + 1.1d, pos.getZ() + 0.5d,
                    4, 0, 0, 0,
                    0.1f);

            targetStack.setCount(targetStack.getCount() - 1);
            workbench.setChanged();
        }
    }

public void update(UpgradeSchematic schematic, Player player, ItemStack itemStack, ItemStack previewStack, ItemStack[] materials, String slot,
            Map<ToolAction, Integer> availableTools) {
        enabled = schematic.canApplyUpgrade(player, itemStack, materials, slot, availableTools);
        tooltip = new ArrayList<>();

        if (enabled) {
            labelColor = GuiColors.normal;
            backdropColor = GuiColors.normal;

            boolean willReplace = schematic.willReplace(itemStack, materials, slot);
            float severity = schematic.getSeverity(itemStack, materials, slot);
            List<String> destabilizationChance =
                    getDestabilizationChance(previewStack.isEmpty() ? itemStack : previewStack, severity, willReplace ? slot : null);

            if (!destabilizationChance.isEmpty()) {
                backdropColor = GuiColors.destabilized;
                tooltip.add(Component.translatable("tetra.workbench.schematic_detail.destabilize_tooltip"));
                destabilizationChance.stream()
                        .map(Component::literal)
                        .forEach(tooltip::add);
            }

            boolean willRepair = CastOptional.cast(itemStack.getItem(), IModularItem.class)
                    .map(item -> item.getRepairSlot(itemStack))
                    .map(repairSlot -> repairSlot.equals(slot))
                    .orElse(false)
                    && willReplace
                    && itemStack.isDamageableItem()
                    && itemStack.getDamageValue() * 1d / itemStack.getMaxDamage() > 0;

            if (willRepair) {
                if (!tooltip.isEmpty()) {
                    tooltip.add(Component.literal(" "));
                }
                tooltip.add(Component.translatable("tetra.workbench.schematic_detail.repair_tooltip"));
            }
        } else {
            labelColor = GuiColors.muted;
            backdropColor = GuiColors.negative;

            if (!schematic.isMaterialsValid(itemStack, slot, materials)) {
                if (hasEmptyMaterial(schematic, materials)) {
                    tooltip.add(Component.translatable("tetra.workbench.schematic_detail.no_material_tooltip"));
                    backdropColor = GuiColors.muted;
                } else if (hasInsufficientQuantities(schematic, itemStack, slot, materials)) {
                    tooltip.add(Component.translatable("tetra.workbench.schematic_detail.material_count_tooltip"));
                } else {
                    tooltip.add(Component.translatable("tetra.workbench.schematic_detail.material_tooltip"));
                }
            } else {
                if (schematic.isIntegrityViolation(player, itemStack, materials, slot)) {
                    tooltip.add(Component.translatable("tetra.workbench.schematic_detail.integrity_tooltip"));
                }
                if (!schematic.checkTools(itemStack, materials, availableTools)) {
                    tooltip.add(Component.translatable("tetra.workbench.schematic_detail.tools_tooltip"));
                }
                if (!player.isCreative() && player.experienceLevel < schematic.getExperienceCost(itemStack, materials, slot)) {
                    tooltip.add(Component.translatable("tetra.workbench.schematic_detail.level_tooltip"));
                }
            }
        }

        updateColors();
    }

