private void setupImprovements(ItemModuleMajor previewModule, ItemStack previewStack, ItemModuleMajor module, ItemStack itemStack) {
        improvementGroup.clearChildren();

        String[] improvements = getImprovementUnion(module.getImprovements(itemStack), previewModule.getImprovements(previewStack));

        for (String improvementKey : improvements) {
            int currentValue = module.getImprovementLevel(itemStack, improvementKey);
            int previewValue = previewModule.getImprovementLevel(previewStack, improvementKey);
            int color;

            if (currentValue == -1) {
                color = GuiColors.add;
            } else if (previewValue == -1) {
                color = GuiColors.remove;
            } else if (currentValue != previewValue) {
                color = GuiColors.change;
            } else {
                color = module.getImprovement(itemStack, improvementKey).glyph.tint;
            }

            GuiModuleImprovement improvement = new GuiModuleImprovement(0, 0, improvementKey, previewValue, color,
                    previewValue != -1 ? previewStack : itemStack,
                    () -> hoverHandler.accept(slotKey, improvementKey),
                    () -> {
                        if (hasFocus()) {
                            hoverHandler.accept(slotKey, null);
                        }
                    });

            improvementGroup.addChild(improvement);
        }

        Map<Enchantment, Integer> currentEnchantments = module.getEnchantments(itemStack);
        Map<Enchantment, Integer> previewEnchantments = module.getEnchantments(previewStack);
        getEnchantmentUnion(currentEnchantments.keySet(), previewEnchantments.keySet()).forEach(enchantment -> {
            int color;

            int currentLevel = currentEnchantments.getOrDefault(enchantment, 0);
            int previewLevel = previewEnchantments.getOrDefault(enchantment, 0);

            if (currentLevel == 0) {
                color = GuiColors.add;
            } else if (previewLevel == 0) {
                color = GuiColors.remove;
            } else if (currentLevel != previewLevel) {
                color = GuiColors.change;
            } else {
                color = GuiColors.normal;
            }

            String enchantmentKey = "enchantment:" + ForgeRegistries.ENCHANTMENTS.getKey(enchantment).toString();
            improvementGroup.addChild(new GuiModuleEnchantment(0, 0, enchantment, previewLevel, color,
                    () -> hoverHandler.accept(slotKey, enchantmentKey),
                    () -> {
                        if (hasFocus()) {
                            hoverHandler.accept(slotKey, null);
                        }
                    }));
        });

        improvementGroup.forceLayout();
    }

public void onTileEntityChange(Player player, WorkbenchTile tileEntity, ItemStack itemStack, String selectedSlot, UpgradeSchematic currentSchematic) {
        ItemModule module = CastOptional.cast(itemStack.getItem(), IModularItem.class)
                .map(item -> item.getModuleFromSlot(itemStack, selectedSlot))
                .orElse(null);

        if (currentSchematic == null) {
            updateSchematicList(player, tileEntity, selectedSlot);
        } else {
            Level world = tileEntity.getLevel();
            BlockPos pos = tileEntity.getBlockPos();
            Map<ToolAction, Integer> availableTools = PropertyHelper.getCombinedToolLevels(player, world, pos, world.getBlockState(pos));
            ItemStack[] materials = tileEntity.getMaterials();

            ItemStack previewStack = currentSchematic.applyUpgrade(itemStack.copy(), materials, false, selectedSlot, player);

            schematicDetail.update(world, pos, tileEntity, currentSchematic, itemStack, selectedSlot, materials, availableTools, player);
            schematicDetail.updateMagicCapacity(currentSchematic, selectedSlot, itemStack, previewStack);
            schematicDetail.updateButton(currentSchematic, player, itemStack, previewStack, materials, selectedSlot, availableTools);

            tab = 1;
        }

        moduleDetails.update(module, itemStack);
        tabGroup.setHasContent(0, module != null);

        tweakControls.update(module, itemStack);
        tabGroup.setHasContent(2, module != null && module.isTweakable(itemStack));

        schematicDetail.setVisible(currentSchematic != null);
        schematicList.setVisible(currentSchematic == null);

        updateTabVisibility();
        tabGroup.setActive(tab);
    }

public void update(UpgradeSchematic schematic, ItemStack targetStack, String slot, ItemStack[] materials, Map<ToolAction, Integer> availableTools) {
        boolean hasValidMaterials = schematic.isMaterialsValid(targetStack, slot, materials);
        setVisible(hasValidMaterials);

        if (hasValidMaterials) {
            clearChildren();

            requiredTools = schematic.getRequiredToolLevels(targetStack, materials);

            var layout = new GuiHorizontalLayoutGroup(0, 0, 16, -2 - requiredTools.size() * 2);
            layout.setAttachmentPoint(GuiAttachment.topCenter);
            addChild(layout);
            var spacing = -3 - requiredTools.size() * 2;

            var i = new AtomicInteger(0);
            requiredTools.entrySet().stream()
                    .map(entry -> new ToolRequirementGui(-1 * i.getAndIncrement() * (spacing + GuiTool.width), 0, entry.getKey())
                            .updateRequirement(entry.getValue(), availableTools.getOrDefault(entry.getKey(), 0))
                            .setAttachment(GuiAttachment.topRight))
                    .forEach(this::addChild);
            setWidth(requiredTools.size() * GuiTool.width + (requiredTools.size() - 1) * spacing);
        }
    }

public void updateAvailableTools(Map<ToolAction, Integer> availableTools) {
        getChildren(ToolRequirementGui.class).forEach(indicator ->
                indicator.updateRequirement(
                        requiredTools.getOrDefault(indicator.getToolAction(), 0),
                        availableTools.getOrDefault(indicator.getToolAction(), 0)));
    }

