@Override
    public boolean apply(ResourceLocation[] unlockedEffects, ItemStack upgradedStack, String slot, boolean isReplacing, Player player,
            ItemStack[] preMaterials,
            Map<ToolAction, Integer> tools, Level world, UpgradeSchematic schematic, BlockPos pos, BlockState blockState, boolean consumeResources,
            ItemStack[] postMaterials, float severity) {
        return CastOptional.cast(upgradedStack.getItem(), IModularItem.class)
                .map(item -> item.getModuleFromSlot(upgradedStack, slot))
                .flatMap(module -> CastOptional.cast(module, ItemModuleMajor.class))
                .map(module -> {
                    AtomicBoolean result = new AtomicBoolean(false);
                    for (Map.Entry<String, Integer> improvement : improvements.entrySet()) {
                        String key = improvement.getKey();
                        if (key.startsWith("#")) {
                            ItemAspect aspect = ItemAspect.get(key.substring(1));

                            Arrays.stream(module.getAcceptedImprovements(aspect))
                                    .collect(StreamHelper.toShuffledList())
                                    .stream()
                                    .map(k -> new ImprovementPair(k, stacking.evaluate(module.getImprovementLevel(upgradedStack, k), improvement.getValue())))
                                    .filter(pair -> module.acceptsImprovementLevel(pair.key, pair.level))
                                    .findFirst()
                                    .ifPresent(pair -> {
                                        module.addImprovement(upgradedStack, pair.key, pair.level);
                                        result.set(true);
                                    });

                        } else {
                            int level = stacking.evaluate(module.getImprovementLevel(upgradedStack, key), improvement.getValue());
                            if (module.acceptsImprovementLevel(key, level)) {
                                module.addImprovement(upgradedStack, key, level);
                                result.set(true);
                            }
                        }
                    }
                    return result.get();
                })
                .orElse(false);
    }

@Override
    public boolean apply(ResourceLocation[] unlockedEffects, ItemStack upgradedStack, String targetSlot, boolean isReplacing, Player player,
            ItemStack[] preMaterials, Map<ToolAction, Integer> tools, Level world, UpgradeSchematic schematic, BlockPos pos, BlockState blockState,
            boolean consumeResources, ItemStack[] postMaterials, float severity) {
        if (upgradedStack.getItem() instanceof IModularItem item) {
            AtomicBoolean result = new AtomicBoolean(false);
            Stream.concat(
                            major ? Arrays.stream(item.getMajorModuleKeys(upgradedStack)) : Stream.empty(),
                            minor ? Arrays.stream(item.getMinorModuleKeys(upgradedStack)) : Stream.empty())
                    .filter(slot -> slots == null || Arrays.asList(slots).contains(slot))
                    .filter(slot -> exclude == null || !Arrays.asList(exclude).contains(slot))
                    .filter(slot -> current || !slot.equals(targetSlot))
                    .filter(slot -> item.getModuleFromSlot(upgradedStack, slot) != null)
                    .forEach(slot -> {
                        if (outcome.apply(unlockedEffects, upgradedStack, slot, isReplacing, player, preMaterials, tools, world, schematic, pos, blockState, consumeResources, postMaterials, severity)) {
                            result.set(true);
                        }
                    });
            return result.get();
        }


        return false;
    }

