public static void perform(LivingEntity entity, ItemStack itemStack, double multiplier) {
        if (!entity.level().isClientSide) {
            double effectProbability = EffectHelper.getEffectEfficiency(itemStack, ItemEffect.enderReverb);
            if (effectProbability > 0
                    && !CastOptional.cast(entity, Player.class).map(Player::isCreative).orElse(false)
                    && entity.getRandom().nextDouble() < effectProbability * multiplier) {
                AABB aabb = new AABB(entity.blockPosition()).inflate(24);
                List<LivingEntity> nearbyTargets = entity.level().getEntitiesOfClass(LivingEntity.class, aabb,
                        target -> target instanceof EnderMan || target instanceof Endermite
                                || target instanceof Shulker || target instanceof EnderDragon);
                if (nearbyTargets.size() > 0) {
                    nearbyTargets.get(entity.getRandom().nextInt(nearbyTargets.size())).setLastHurtByMob(entity);
                }
            }
        }
    }

private AbilityUseResult defensiveExecute(Player attacker, ItemModularHandheld item, ItemStack itemStack, LivingEntity target) {
        boolean targetFullHealth = target.getMaxHealth() == target.getHealth();
        double damageMultiplier = item.getEffectLevel(itemStack, ItemEffect.abilityDefensive) / 100f;

        if (targetFullHealth) {
            damageMultiplier += item.getEffectEfficiency(itemStack, ItemEffect.abilityDefensive) / 100f;
        }

        AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, 0.2f, 0.2f);

        if (result != AbilityUseResult.fail) {
            int amp = Optional.ofNullable(target.getEffect(SeveredPotionEffect.instance))
                    .map(MobEffectInstance::getAmplifier)
                    .orElse(-1);
            amp += targetFullHealth ? 2 : 1;
            amp = Math.min(amp, 2);

            target.addEffect(new MobEffectInstance(SeveredPotionEffect.instance, 1200, amp, false, false));
        }

        return result;
    }

public static void breakBlocks(ItemModularHandheld item, ItemStack itemStack, int effectLevel, ServerLevel world, BlockState state, BlockPos pos, LivingEntity entity) {
        Player player = CastOptional.cast(entity, Player.class).orElse(null);

        if (effectLevel > 0) {
            Vec3 entityPosition = entity.getEyePosition(0);
            double lookDistance = Optional.ofNullable(entity.getAttribute(ForgeMod.BLOCK_REACH.get()))
                    .map(AttributeInstance::getValue)
                    .orElse(5d);

            Vec3 lookingPosition = entity.getLookAngle().scale(lookDistance).add(entityPosition);
            BlockHitResult rayTrace = world.clip(new ClipContext(entityPosition, lookingPosition,
                    ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, entity));

            Direction direction = rayTrace.getType() == HitResult.Type.BLOCK
                    ? rayTrace.getDirection().getOpposite()
                    : Direction.orderedByNearest(entity)[0];

            float referenceHardness = state.getDestroySpeed(world, pos);
            ToolAction referenceTool = ToolActionHelper.getAppropriateTools(state).stream()
                    .filter(tool -> item.canPerformAction(itemStack, tool))
                    .findFirst()
                    .orElse(null);

            if (referenceTool != null && item.getToolLevel(itemStack, referenceTool) > 0) {
                double critMultiplier = CritEffect.rollMultiplier(entity.getRandom(), item, itemStack);
                if (critMultiplier != 1) {
                    effectLevel *= critMultiplier;
                    world.sendParticles(ParticleTypes.ENCHANTED_HIT, pos.getX() + .5f, pos.getY() + .5f, pos.getZ() + .5f, 15, 0.2D, 0.2D, 0.2D, 0.0D);
                }

                breakRecursive(world, player, item, itemStack, direction, pos, referenceHardness, referenceTool, effectLevel);
                item.applyDamage(effectLevel, itemStack, entity);
                item.tickProgression(entity, itemStack, Mth.ceil(effectLevel / 2d));
            }
        }
    }

