@Override
    public float getDestroySpeed(ItemStack itemStack, BlockState blockState) {
        if (!isBroken(itemStack)) {
            float speed = (float) getAttackSpeedHarvestModifier(getAttributeValue(itemStack, Attributes.ATTACK_SPEED, 4));
            Set<ToolAction> appropriateTools = ToolActionHelper.getAppropriateTools(blockState);

            if (!appropriateTools.isEmpty()) {
                speed *= (float) appropriateTools.stream()
                        .mapToDouble(tool -> getToolEfficiency(itemStack, tool))
                        .max()
                        .orElse(0f);
            } else {
                speed *= getToolActions(itemStack).stream()
                        .filter(toolAction -> ToolActionHelper.isEffectiveOn(toolAction, blockState))
                        .map(toolAction -> getToolEfficiency(itemStack, toolAction))
                        .max(Comparator.naturalOrder())
                        .orElse(0f);
            }

            if (getToolLevel(itemStack, TetraToolActions.cut) > 0) {
                if (blockState.is(ToolActionHelper.swordVeryEfficient)) {
                    speed *= 10;
                }

                if (blockState.is(ToolActionHelper.swordInstamine)) {
                    speed = 30;
                }
            }

            if (speed < 1) {
                return 1;
            }
            return speed;
        }
        return 1;
    }

private boolean checkImprovements(ItemStack itemStack, String slot) {
        IModularItem item = (IModularItem) itemStack.getItem();

        if (slot != null) {
            return CastOptional.cast(item.getModuleFromSlot(itemStack, slot), ItemModuleMajor.class)
                    .map(module -> {
                        if (hasDisallowedImprovements(module, itemStack)) {
                            return false;
                        }

                        if (improvements.entrySet().stream().allMatch(entry -> entry.getKey().startsWith("!"))) {
                            return true;
                        }

                        return hasImprovements(module, itemStack);
                    })
                    .orElse(false);
        } else {
            boolean hasDisallowed = Arrays.stream(item.getMajorModules(itemStack))
                    .filter(Objects::nonNull)
                    .anyMatch(module -> hasDisallowedImprovements(module, itemStack));

            if (hasDisallowed) {
                return false;
            }

            // if the improvement predicate set only contains disallowed rules we can return true here
            if (improvements.entrySet().stream().allMatch(entry -> entry.getKey().startsWith("!"))) {
                return true;
            }

            return Arrays.stream(item.getMajorModules(itemStack))
                    .filter(Objects::nonNull)
                    .anyMatch(module -> hasImprovements(module, itemStack));
        }
    }

