public void updateVariants(OutcomePreview[] previews, List<OutcomeStack> selectedOutcomes) {
        variants.clearChildren();

        List<OutcomePreview> matchingSelections = selectedOutcomes.stream()
                .filter(stack -> stack.schematicEquals(schematic))
                .map(stack -> stack.preview)
                .collect(Collectors.toList());
        isActive = !matchingSelections.isEmpty();

        this.preview = null;

        if (previews.length > 1) {
            int labelStart = findLabelStart(previews);
            for (int i = 0; i < previews.length; i++) {
                String labelString = previews[i].variantName;

                boolean isConnected = i + 1 < previews.length && Objects.equals(previews[i].variantKey, previews[i + 1].variantKey);

                HoloImprovementVariantGui variant = new HoloImprovementVariantGui(i * 28, 0, labelString, labelStart, previews[i], isConnected,
                        onVariantHover, onVariantBlur,
                        preview -> onVariantSelect.accept(new OutcomeStack(schematic, preview)));
                variants.addChild(variant);

                if (!matchingSelections.isEmpty()) {
                    variant.setMuted(!matchingSelections.contains(previews[i]));
                }

                backdrop.setColor(GuiColors.normal);
                label.setColor(GuiColors.normal);

                variants.setVisible(true);
            }

            header.setY(0);

            setWidth(Math.max(variants.getX() + previews.length * 28 - 9, header.getWidth()));

            updateTint(false);
        } else {
            header.setY(6);
            variants.setVisible(false);

            if (previews.length == 1) {
                this.preview = previews[0];
            }

            setWidth(header.getWidth() + 24);

            updateTint(hasFocus());
        }

    }

private int findLabelStart(OutcomePreview[] previews) {
        int maxLength = Arrays.stream(previews)
                .map(preview -> preview.variantName)
                .filter(Objects::nonNull)
                .mapToInt(String::length)
                .max()
                .orElse(0);

        Character cmp = null;
        for (int j = 0; j < maxLength; j++) {
            for (int i = 0; i < previews.length; i++) {
                String name = previews[i].variantName;
                if (name != null && name.length() > j) {
                    if (cmp == null) {
                        cmp = name.charAt(j);
                    } else if (!cmp.equals(name.charAt(j))) {
                        return j;
                    }
                }
            }

            cmp = null;
        }

        return 0;
    }

public void update(Level level, BlockPos pos, WorkbenchTile blockEntity, ItemStack itemStack, String slot, UpgradeSchematic schematic,
            Player playerEntity) {
        this.item = null;
        this.itemStack = null;
        this.slot = null;
        this.schematic = null;

        tooltip = new ArrayList<>();

        String[] materials = schematic.getApplicableMaterials();
        if (materials != null && materials.length > 0) {
            String materialsString = Arrays.stream(materials)
                    .map(mat -> {
                        if (mat.startsWith("#")) {
                            return I18n.get("tetra.variant_category." + mat.substring(1) + ".label");
                        } else if (mat.startsWith("!")) {
                            return I18n.get("tetra.material." + mat.substring(1));
                        }
                        return Optional.ofNullable(ForgeRegistries.ITEMS.getValue(new ResourceLocation(mat)))
                                .map(Item::getDescription)
                                .map(Component::getString)
                                .orElse(mat);
                    })
                    .collect(Collectors.joining(", "));

            tooltip.add(Component.translatable("tetra.holo.craft.applicable_materials"));
            tooltip.add(Component.literal(materialsString).withStyle(ChatFormatting.GRAY));
            tooltip.add(Component.literal(""));

            ItemStack holosphereStack = ModularHolosphereItem.findHolosphere(playerEntity, level, pos);

            if ((schematic.getType() != SchematicType.major && schematic.getType() != SchematicType.minor)
                    || schematic.getRarity() != SchematicRarity.basic) {
                tooltip.add(Component.translatable("tetra.holo.craft.holosphere_shortcut_disabled"));
                tooltip.add(Component.translatable("tetra.holo.craft.holosphere_shortcut_unavailable").withStyle(ChatFormatting.DARK_GRAY));
            } else if (holosphereStack.isEmpty() || !(itemStack.getItem() instanceof IModularItem)) {
                tooltip.add(Component.translatable("tetra.holo.craft.holosphere_shortcut_disabled"));
                tooltip.add(Component.translatable("tetra.holo.craft.holosphere_shortcut_missing").withStyle(ChatFormatting.DARK_GRAY));
            } else {
                tooltip.add(Component.translatable("tetra.holo.craft.holosphere_shortcut"));
                this.item = (IModularItem) itemStack.getItem();
                this.itemStack = itemStack;
                this.slot = slot;
                this.schematic = schematic;
            }
        } else {
            tooltip = emptyTooltip;
        }
    }

