private void updateGuiVisibility() {
        int sweeperRange = Stream.of(mc.player.getMainHandItem(), mc.player.getOffhandItem())
                .filter(stack -> stack.getItem() instanceof ModularHolosphereItem)
                .map(stack -> ((IModularItem) stack.getItem()).getEffectLevel(stack, ItemEffect.sweeperRange))
                .findFirst()
                .orElse(0);

        if (!scanner.isVisible() && sweeperRange > 0) {
            updateStats();
        }

        if (sweeperRange > 0) {
            scanner.show();
        } else {
            scanner.hide();
        }
    }

@SubscribeEvent
    public void onClientTick(TickEvent.ClientTickEvent event) {
        Level world = mc.level;
        Player player = mc.player;

        if (world == null || player == null || TickEvent.Phase.START != event.phase) {
            return;
        }

        updateGuiVisibility();
        ticks++;

        if (ticks % 200 == 0) {
            updateStats();
        }

        if (available && ticks % 20 == 0) {
            if (isSnoozed()) {
                scanner.setStatus(getStatus());
            } else {
                scanner.setStatus(null);
            }
        }

        if (available && ticks % 2 == 0 && !isSnoozed()) {
            int offset = (ticks / 2) % (int) (horizontalSpread * 2 * cooldown);
            if (offset < horizontalSpread * 2) {
                int yawOffset = (int) ((-horizontalSpread + offset) * ScannerBarGui.getDegreesPerUnit());
                if (offset % 2 == 0) {
                    if (verticalSpread > 0) {
                        upHighlight = IntStream.range(0, verticalSpread)
                                .map(i -> i * -5 - 25)
                                .mapToObj(pitch -> getPositions(player, world, pitch, yawOffset))
                                .filter(result -> result.getType() != HitResult.Type.MISS)
                                .map(BlockHitResult::getBlockPos)
                                .findAny()
                                .orElse(null);
                        scanner.highlightUp(offset / 2, upHighlight != null);
                        if (upHighlight != null) {
                            sound.activate();
                        }

                        downHighlight = IntStream.range(0, verticalSpread)
                                .map(i -> i * 5 + 25)
                                .mapToObj(pitch -> getPositions(player, world, pitch, yawOffset))
                                .filter(result -> result.getType() != HitResult.Type.MISS)
                                .map(BlockHitResult::getBlockPos)
                                .findAny()
                                .orElse(null);
                        scanner.highlightDown(offset / 2, downHighlight != null);
                        if (downHighlight != null) {
                            sound.activate();
                        }
                    }
                } else if (offset / 2 < horizontalSpread - 1) {
                    midHighlight = IntStream.range(-1, 2)
                            .map(i -> i * 10)
                            .mapToObj(pitch -> getPositions(player, world, pitch, yawOffset))
                            .filter(result -> result.getType() != HitResult.Type.MISS)
                            .map(BlockHitResult::getBlockPos)
                            .findAny()
                            .orElse(null);

                    scanner.highlightMid(offset / 2, midHighlight != null);
                    if (midHighlight != null) {
                        sound.activate();
                    }

                }
            }
        }
    }

@Override
    public ItemStack applyUpgrade(ItemStack itemStack, ItemStack[] materials, boolean consumeMaterials, String slot, Player player) {
        ItemStack upgradedStack = itemStack.copy();

        ItemStack bannerStack = materials[0];

        if (isMaterialsValid(itemStack, slot, materials)) {

            CastOptional.cast(itemStack.getItem(), IModularItem.class)
                    .map(item -> item.getModuleFromSlot(itemStack, slot))
                    .flatMap(module -> CastOptional.cast(module, ItemModuleMajor.class))
                    .ifPresent(module -> {
                        if (module.acceptsImprovementLevel(ModularShieldItem.bannerImprovementKey, 0)) {
                            module.addImprovement(upgradedStack, ModularShieldItem.bannerImprovementKey, 0);

                            CompoundTag bannerTag = Optional.ofNullable(bannerStack.getTagElement("BlockEntityTag"))
                                    .map(CompoundTag::copy)
                                    .orElse(new CompoundTag());

                            bannerTag.putInt("Base", ((BannerItem) bannerStack.getItem()).getColor().getId());
                            upgradedStack.addTagElement("BlockEntityTag", bannerTag.copy());

                            if (consumeMaterials) {
                                materials[0].shrink(1);
                            }

                            if (consumeMaterials && player instanceof ServerPlayer) {
                                ImprovementCraftCriterion.trigger((ServerPlayer) player, itemStack, upgradedStack, getKey(), slot,
                                        ModularShieldItem.bannerImprovementKey, 0, null, -1);
                            }
                        }
                    });
        }


        return upgradedStack;
    }

private void renderEtching(ItemStack itemStack, ModelPart modelRenderer, PoseStack matrixStack, MultiBufferSource buffer,
            int combinedLight, int combinedOverlay) {
        List<Pair<Holder<BannerPattern>, DyeColor>> list = BannerBlockEntity.createPatterns(ShieldItem.getColor(itemStack), BannerBlockEntity.getItemPatterns(itemStack));

        for (int i = 0; i < 17 && i < list.size(); ++i) {
            Pair<Holder<BannerPattern>, DyeColor> pair = list.get(i);
            if (!BannerPatterns.BASE.equals(pair.getFirst().unwrapKey().orElse(null))) {
                float[] tint = pair.getSecond().getTextureDiffuseColors();
                pair.getFirst().unwrapKey().map(Sheets::getShieldMaterial).ifPresent(material -> {
                    VertexConsumer vertexBuilder = material.sprite().wrap(ItemRenderer.getFoilBuffer(buffer, RenderType.entityNoOutline(material.atlasLocation()), false, itemStack.hasFoil()));
                    modelRenderer.render(matrixStack, vertexBuilder, combinedLight, combinedOverlay, tint[0], tint[1], tint[2], 0.7f);
                });
            }
        }
    }

public List<Collection<ItemEffect>> getSlotEffects(ItemStack itemStack, SlotType slotType) {
        return getAllModules(itemStack).stream()
                .map(module -> module.getEffectData(itemStack))
                .filter(Objects::nonNull)
                .filter(effects -> effects.contains(slotType.effect))
                .map(effects -> {
                    Map<ItemEffect, Integer> effectLevels = effects.getLevelMap();

                    int slotCount = effectLevels.get(slotType.effect);
                    Collection<Collection<ItemEffect>> result = new ArrayList<>(slotCount);
                    for (int i = 0; i < slotCount; i++) {
                        int index = i;
                        result.add(effectLevels.entrySet().stream()
                                .filter(entry -> !entry.getKey().equals(slotType.effect))
                                .filter(entry -> entry.getValue() > index)
                                .map(Map.Entry::getKey)
