public static PoppetData getPoppetFromInventory(World world, PoppetItem item, Entity owner, List<ItemStack> inventory) {
		if (inventory == null) {
			return PoppetData.EMPTY;
		}
		for (int i = 0; i < inventory.size(); i++) {
			ItemStack stack = inventory.get(i);
			if (BWConfig.disabledPoppets.contains(Registries.ITEM.getId(stack.getItem()).toString())) {
				continue;
			}
			if (stack.getItem() == item && TaglockItem.hasTaglock(stack)) {
				UUID uuid = null;
				if (owner != null) {
					uuid = owner.getUuid();
				} else {
					LivingEntity taglockOwner = getTaglockOwner(world, stack);
					if (taglockOwner != null) {
						uuid = taglockOwner.getUuid();
					}
				}
				if (TaglockItem.getTaglockUUID(stack).equals(uuid)) {
					return new PoppetData(stack, null, i);
				}
			}
		}
		return PoppetData.EMPTY;
	}

@Override
	public ActionResult onUse(BlockState state, World world, BlockPos pos, PlayerEntity player, Hand hand, BlockHitResult hit) {
		boolean client = world.isClient;
		ItemStack stack = player.getStackInHand(hand);
		if (!formed) {
			AltarMapEntry entry = BewitchmentAPI.ALTAR_MAP_ENTRIES.stream().filter(e -> e.unformed() == this && e.carpet() == stack.getItem()).findFirst().orElse(null);
			if (entry != null) {
				if (!client) {
					if (!player.isCreative()) {
						stack.decrement(1);
					}
					Direction facing = world.getBlockState(pos).get(FACING);
					world.breakBlock(pos, false);
					world.setBlockState(pos, entry.formed().getPlacementState(new ItemPlacementContext(player, hand, stack, hit)).with(FACING, facing));
				}
				return ActionResult.success(client);
			}
		} else {
			WitchAltarBlockEntity blockEntity = (WitchAltarBlockEntity) world.getBlockEntity(pos);
			if (!client) {
				if (!stack.isEmpty()) {
					boolean sword = stack.isIn(BWTags.SWORDS);
					boolean pentacle = stack.isIn(BWTags.PENTACLES);
					boolean wand = stack.isIn(BWTags.WANDS);
					if (sword || pentacle || wand) {
						int slot = sword ? 0 : pentacle ? 1 : 2;
						ItemScatterer.spawn(world, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, blockEntity.removeStack(slot, 1));
						blockEntity.setStack(slot, stack.split(1));
						world.setBlockState(pos, state.with(Properties.LEVEL_15, calculateLuminance(blockEntity)), 11);
						world.updateComparators(pos, this);
						blockEntity.markedForScan = true;
						blockEntity.markDirty();
						blockEntity.sync();
					}
				} else {
					if (player.isSneaking()) {
						ItemScatterer.spawn(world, pos.add(0, 1, 0), blockEntity);
						world.setBlockState(pos, state.with(Properties.LEVEL_15, 0), 11);
						world.updateComparators(pos, this);
						blockEntity.markedForScan = true;
						blockEntity.markDirty();
						blockEntity.sync();
					} else {
						player.sendMessage(Text.literal(blockEntity.power + " / " + blockEntity.maxPower + " (" + blockEntity.gain + "x)"), true);
					}
				}
			}
			return ActionResult.success(client);
		}
		return super.onUse(state, world, pos, player, hand, hit);
	}

@Override
	public void onBlockAdded(BlockState state, World world, BlockPos pos, BlockState oldState, boolean notify) {
		if (formed) {
			if (!world.isClient && state.getBlock() != oldState.getBlock()) {
				BWWorldState worldState = BWWorldState.get(world);
				worldState.potentialCandelabras.add(pos.asLong());
				worldState.markDirty();
			}
			for (BlockPos foundPos : BWUtil.getBlockPoses(pos, BWConfig.altarDistributionRadius)) {
				if (world.getWorldBorder().contains(foundPos) && world.getBlockEntity(foundPos) instanceof UsesAltarPower usesAltarPower) {
					usesAltarPower.setAltarPos(getClosestAltarPos(world, foundPos));
					((BlockEntity) usesAltarPower).markDirty();
				}
			}
		}
	}

