public static void tick(World world, BlockPos pos, BlockState state, BrazierBlockEntity blockEntity) {
		if (world != null) {
			if (!blockEntity.loaded) {
				if (!world.isClient && state.get(Properties.LIT)) {
					blockEntity.incenseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.INCENSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(blockEntity, world)).findFirst().orElse(null);
					if (BWConfig.enableCurses) {
						blockEntity.curseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.CURSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(blockEntity, world)).findFirst().orElse(null);
					}
					blockEntity.hasIncense = blockEntity.incenseRecipe != null;
					blockEntity.markDirty();
					blockEntity.syncBrazier();
				}
				blockEntity.loaded = true;
			}
			if (blockEntity.timer < 0) {
				blockEntity.timer++;
				if (world.isClient) {
					if (world.random.nextBoolean()) {
						world.addParticle(blockEntity.hasIncense ? (ParticleEffect) BWParticleTypes.INCENSE_SMOKE : ParticleTypes.LARGE_SMOKE, pos.getX() + 0.5 + MathHelper.nextDouble(world.random, -0.2, 0.2), pos.getY() + (state.get(Properties.HANGING) ? 0.4 : 1.25), pos.getZ() + 0.5 + MathHelper.nextDouble(world.random, -0.2, 0.2), 0, 0.05, 0);
					}
				} else if (blockEntity.timer == 0) {
					boolean clear = blockEntity.hasIncense;
					if (blockEntity.curseRecipe != null) {
						PlayerEntity closestPlayer = world.getClosestPlayer(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, 24, false);
						if (blockEntity.altarPos != null && ((WitchAltarBlockEntity) world.getBlockEntity(blockEntity.altarPos)).drain(blockEntity.curseRecipe.cost, false)) {
							if (closestPlayer != null) {
								Entity target = blockEntity.getTarget();
								if (target instanceof PlayerEntity player && BewitchmentAPI.getFamiliar(player) == BWEntityTypes.RAVEN && world.random.nextBoolean()) {
									target = closestPlayer;
								}
								if (target instanceof LivingEntity livingEntity) {
									PoppetData poppetData = BewitchmentAPI.getPoppet(world, BWObjects.CURSE_POPPET, target);
									if (!poppetData.stack().isEmpty() && poppetData.stack().hasNbt() && !poppetData.stack().getNbt().getBoolean("Cursed")) {
										poppetData.stack().getNbt().putString("Curse", BWRegistries.CURSE.getId(blockEntity.curseRecipe.curse).toString());
										poppetData.stack().getNbt().putBoolean("Cursed", true);
										TaglockItem.removeTaglock(poppetData.stack());
										poppetData.update(world, true);
									} else {
										int duration = 168000;
										if (BewitchmentAPI.getFamiliar(closestPlayer) == BWEntityTypes.RAVEN) {
											duration *= 2;
										}
										if (target instanceof PlayerEntity player && TrinketsApi.getTrinketComponent((LivingEntity) target).get().isEquipped(BWObjects.NAZAR) && BewitchmentAPI.drainMagic(player, 50, false)) {
											duration /= 2;
										}
										BWComponents.CURSES_COMPONENT.get(livingEntity).addCurse(new Curse.Instance(blockEntity.curseRecipe.curse, duration));
									}
									world.playSound(null, pos, BWSoundEvents.ENTITY_GENERIC_CURSE, SoundCategory.BLOCKS, 1, 1);
									clear = true;
								}
							} else {
								world.playSound(null, pos, BWSoundEvents.BLOCK_BRAZIER_FAIL, SoundCategory.BLOCKS, 1, 1);
								if (closestPlayer != null) {
									String entityName = "";
									for (int i = 0; i < blockEntity.size(); i++) {
										ItemStack stack = blockEntity.getStack(i);
										if (stack.getItem() instanceof TaglockItem && TaglockItem.hasTaglock(stack)) {
											entityName = TaglockItem.getTaglockName(stack);
											break;
										}
									}
									closestPlayer.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.invalid_entity", entityName), true);
								}
							}
						} else {
							if (closestPlayer != null) {
								world.playSound(null, pos, BWSoundEvents.BLOCK_BRAZIER_FAIL, SoundCategory.BLOCKS, 1, 1);
								closestPlayer.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.insufficent_altar_power"), true);
							}
						}
					}
					blockEntity.reset(clear);
					blockEntity.syncBrazier();
				}
			}
		}
	}

public void onUse(World world, BlockPos pos, PlayerEntity player, Hand hand) {
		if (!getCachedState().get(Properties.WATERLOGGED)) {
			ItemStack stack = player.getStackInHand(hand);
			if (getCachedState().get(Properties.LIT)) {
				world.setBlockState(pos, getCachedState().with(Properties.LIT, false));
				world.playSound(null, pos, SoundEvents.BLOCK_FIRE_EXTINGUISH, SoundCategory.BLOCKS, 1, 2);
				reset(hasIncense);
				syncBrazier();
			} else {
				if (stack.getItem() instanceof FlintAndSteelItem) {
					world.setBlockState(pos, getCachedState().with(Properties.LIT, true));
					world.playSound(null, pos, SoundEvents.ITEM_FLINTANDSTEEL_USE, SoundCategory.BLOCKS, 1, 1);
					stack.damage(1, player, stackUser -> stackUser.sendToolBreakStatus(hand));
					IncenseRecipe foundIncenseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.INCENSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(this, world)).findFirst().orElse(null);
					if (foundIncenseRecipe != null) {
						incenseRecipe = foundIncenseRecipe;
						timer = -6000;
						hasIncense = true;
						syncBrazier();
					} else if (BWConfig.enableCurses) {
						CurseRecipe foundCurseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.CURSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(this, world)).findFirst().orElse(null);
						if (foundCurseRecipe != null && getTarget() != null) {
							curseRecipe = foundCurseRecipe;
							timer = -100;
							syncBrazier();
						}
					}
				} else if (!stack.isEmpty()) {
					int firstEmpty = getFirstEmptySlot();
					if (firstEmpty != -1) {
						setStack(firstEmpty, stack.split(1));
						syncBrazier();
					}
				} else {
					reset(hasIncense);
					syncBrazier();
				}
			}
		}
		markDirty();
	}

@Override
	public void readNbt(NbtCompound nbt) {
		super.readNbt(nbt);
		if (nbt.contains("AltarPos")) {
			setAltarPos(BlockPos.fromLong(nbt.getLong("AltarPos")));
		}
		if (nbt.contains("EffectivePos")) {
			effectivePos = BlockPos.fromLong(nbt.getLong("EffectivePos"));
		}
		inventory.clear();
		Inventories.readNbt(nbt, inventory);
		ritualFunction = BWRegistries.RITUAL_FUNCTION.get(new Identifier(nbt.getString("RitualFunction")));
		timer = nbt.getInt("Timer");
		endTime = nbt.getInt("EndTime");
		catFamiliar = nbt.getBoolean("CatFamiliar");
	}

public static void tick(World world, BlockPos pos, BlockState state, GlyphBlockEntity blockEntity) {
		if (world != null) {
			if (!blockEntity.loaded) {
				blockEntity.markDirty();
				blockEntity.loaded = true;
			}
			if (blockEntity.ritualFunction != null) {
				BlockPos targetPos = blockEntity.effectivePos == null ? pos : blockEntity.effectivePos;
				if (!world.getWorldBorder().contains(targetPos)) {
					return;
				}
				blockEntity.timer++;
				if (world.isClient) {
					world.addParticle(ParticleTypes.END_ROD, true, pos.getX() + 0.5 + MathHelper.nextFloat(world.random, -0.2f, 0.2f), pos.getY() + 0.5 + MathHelper.nextFloat(world.random, -0.2f, 0.2f), pos.getZ() + 0.5 + MathHelper.nextFloat(world.random, -0.2f, 0.2f), 0, 0, 0);
					if (blockEntity.timer < 0) {
						for (int i = 0; i < 3; i++) {
							world.addParticle((ParticleEffect) blockEntity.ritualFunction.startParticle, true, targetPos.getX() + 0.5 + MathHelper.nextFloat(world.random, -0.2f, 0.2f), targetPos.getY() + 0.5 + MathHelper.nextFloat(world.random, -0.2f, 0.2f), targetPos.getZ() + 0.5 + MathHelper.nextFloat(world.random, -0.2f, 0.2f), MathHelper.nextFloat(world.random, -1, 1), MathHelper.nextFloat(world.random, 0.125f, 1), MathHelper.nextFloat(world.random, -1, 1));
						}
					}
				}
				if (blockEntity.timer >= 0) {
					blockEntity.ritualFunction.tick(world, pos, targetPos, blockEntity.catFamiliar);
					if (!world.isClient) {
						world.getWorldChunk(blockEntity.effectivePos);
						if (blockEntity.timer == 0) {
							blockEntity.ritualFunction.start((ServerWorld) world, pos, targetPos, blockEntity, blockEntity.catFamiliar);
							world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_PLING, SoundCategory.BLOCKS, 1, 1);
							ItemScatterer.spawn(world, pos, blockEntity);
						}
						if (blockEntity.timer >= blockEntity.endTime) {
							blockEntity.effectivePos = null;
							blockEntity.ritualFunction = null;
							blockEntity.timer = 0;
							blockEntity.endTime = 0;
							blockEntity.catFamiliar = false;
							blockEntity.syncGlyph();
						}
					}
				}
			}
		}
	}

public void onUse(World world, BlockPos pos, LivingEntity user, Hand hand, LivingEntity sacrifice) {
		ItemStack stack = user.getStackInHand(hand);
		if (ritualFunction != null && pos.equals(effectivePos) && stack.getItem() instanceof WaystoneItem && stack.hasNbt() && stack.getOrCreateNbt().contains("LocationPos") && world.getRegistryKey().getValue().toString().equals(stack.getOrCreateNbt().getString("LocationWorld"))) {
			effectivePos = BlockPos.fromLong(stack.getOrCreateNbt().getLong("LocationPos"));
			stack.damage(1, user, stackUser -> stackUser.sendToolBreakStatus(hand));
			syncGlyph();
		} else {
			if (ritualFunction == null) {
				SimpleInventory test = new SimpleInventory(size());
				List<ItemEntity> items = world.getEntitiesByType(EntityType.ITEM, new Box(pos).expand(2, 0, 2), entity -> true);
				for (ItemEntity entity : items) {
					test.addStack(entity.getStack().copy().split(1));
				}
				RitualRecipe recipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.RITUAL_RECIPE_TYPE).stream().filter(ritualRecipe -> ritualRecipe.matches(test, world)).findFirst().orElse(null);
				if (recipe != null && recipe.input.size() == items.size() && hasValidChalk(recipe)) {
					if (recipe.ritualFunction.isValid((ServerWorld) world, pos, test) || (recipe.ritualFunction.sacrifice != null && sacrifice != null && recipe.ritualFunction.sacrifice.test(sacrifice))) {
						boolean cat = user instanceof PlayerEntity player && BewitchmentAPI.getFamiliar(player) == EntityType.CAT;
						if (altarPos != null && ((WitchAltarBlockEntity) world.getBlockEntity(altarPos)).drain((int) (recipe.cost * (cat ? 0.75f : 1)), false)) {
							world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FIRE, SoundCategory.BLOCKS, 1, 1);
							if (user instanceof PlayerEntity player) {
								player.sendMessage(Text.translatable("ritual." + recipe.getId().toString().replace(":", ".").replace("/", ".")), true);
							}
							for (int i = 0; i < items.size(); i++) {
								ItemEntity item = items.get(i);
								PlayerLookup.tracking(item).forEach(foundPlayer -> SpawnSmokeParticlesPacket.send(foundPlayer, item));
								setStack(i, item.getStack().split(1));
							}
							effectivePos = pos;
							ritualFunction = recipe.ritualFunction;
							timer = -100;
							endTime = recipe.runningTime;
							catFamiliar = cat;
							syncGlyph();
							return;
						}
						world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
						if (user instanceof PlayerEntity player) {
							player.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.insufficent_altar_power"), true);
						}
						return;
					}
					world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
					if (user instanceof PlayerEntity player) {
						player.sendMessage(Text.translatable(recipe.ritualFunction.getInvalidMessage()), true);
					}
					return;
				}
				world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
				if (user instanceof PlayerEntity player) {
					player.sendMessage(Text.translatable("ritual.none"), true);
				}
			} else if (sacrifice == null) {
				world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
				ItemScatterer.spawn(world, pos, this);
				effectivePos = null;
				ritualFunction = null;
				timer = 0;
				endTime = 0;
				catFamiliar = false;
				syncGlyph();
			}
		}
	}

private void scan(int times) {
		if (world != null) {
			for (int i = 0; i < times; i++) {
				counter = ++counter % Short.MAX_VALUE;
				int x = counter & 31;
				int y = (counter >> 5) & 31;
				int z = (counter >> 10) & 31;
				BlockState checkedState = world.getBlockState(checking.set(pos.getX() + x - 15, pos.getY() + y - 15, pos.getZ() + z - 15));
				Block checkedBlock = checkedState.getBlock();
				if (givesAltarPower(checkedState) && !(checkedState.isIn(BlockTags.LOGS) && Registries.BLOCK.getId(checkedBlock).getPath().contains("stripped"))) {
					checked.put(checkedBlock, Math.min(checked.getOrDefault(checkedBlock, 0) + 1, 256));
				}
				if (counter == Short.MAX_VALUE - 1) {
					gain = getPentacleValue(getStack(1));
					maxPower = 0;
					float varietyMultiplier = 1;
					for (Block block : checked.keySet()) {
						if (checked.get(block) > 3) {
							varietyMultiplier *= 1.1f;
						}
						maxPower += checked.get(block);
					}
					maxPower = (int) ((maxPower * Math.min(varietyMultiplier, 4) / 10) * getSwordValue(getStack(0)) + getWandValue(getStack(2)));
					power = Math.min(power, maxPower);
					checked.clear();
				}
			}
		}
	}

