@Override
	public ItemStack finishUsing(ItemStack stack, World world, LivingEntity user) {
		if (user instanceof PlayerEntity player) {
			if (!world.isClient && BewitchmentAPI.drainMagic(player, 2, false)) {
				PotionEntity potion = new PotionEntity(world, user);
				List<StatusEffectInstance> effects = PotionUtil.getCustomPotionEffects(stack);
				ItemStack potionStack = PotionUtil.setCustomPotionEffects(new ItemStack(Items.SPLASH_POTION), effects);
				potionStack.getOrCreateNbt().putInt("CustomPotionColor", PotionUtil.getColor(effects));
				if (stack.getOrCreateNbt().contains("PolymorphUUID")) {
					potionStack.getOrCreateNbt().putUuid("PolymorphUUID", stack.getOrCreateNbt().getUuid("PolymorphUUID"));
					potionStack.getOrCreateNbt().putString("PolymorphName", stack.getOrCreateNbt().getString("PolymorphName"));
				}
				potion.setItem(potionStack);
				potion.setVelocity(user, user.getPitch(), user.getYaw(), -20, 0.5f, 1);
				world.spawnEntity(potion);
				world.playSound(null, user.getBlockPos(), SoundEvents.ENTITY_SPLASH_POTION_THROW, SoundCategory.PLAYERS, 1, 1);
				if (!player.isCreative()) {
					stack.getOrCreateNbt().putInt("PotionUses", stack.getOrCreateNbt().getInt("PotionUses") - 1);
					if (stack.getOrCreateNbt().getInt("PotionUses") <= 0) {
						if (stack.getOrCreateNbt().contains("PolymorphUUID")) {
							potionStack.getOrCreateNbt().remove("PolymorphUUID");
							potionStack.getOrCreateNbt().remove("PolymorphName");
						}
						stack.getOrCreateNbt().put("CustomPotionEffects", new NbtList());
					}

					stack.damage(1, user, stackUser -> stackUser.sendToolBreakStatus(user.getActiveHand()));
				}
			}
		}
		return stack;
	}

@Override
	public ActionResult useOnBlock(ItemUsageContext context) {
		World world = context.getWorld();
		BlockPos pos = context.getBlockPos();
		BlockState state = world.getBlockState(pos);
		PlayerEntity player = context.getPlayer();
		boolean client = world.isClient;
		if (state.getBlock() instanceof BedBlock) {
			if (!client && player != null && player.isSneaking()) {
				MinecraftServer server = world.getServer();
				if (server != null) {
					if (state.get(BedBlock.PART) != BedPart.HEAD) {
						pos = pos.offset(state.get(BedBlock.FACING));
					}
					PlayerEntity earliestSleeper = null;
					for (ServerPlayerEntity playerEntity : server.getPlayerManager().getPlayerList()) {
						BlockPos bedPos = playerEntity.getSpawnPointPosition();
						if (bedPos != null && bedPos.equals(pos) && (earliestSleeper == null || playerEntity.getSleepTimer() < earliestSleeper.getSleepTimer())) {
							earliestSleeper = playerEntity;
						}
					}
					if (earliestSleeper != null) {
						return useTaglock(player, earliestSleeper, context.getHand(), false, true);
					}
				}
			}
			return ActionResult.success(client);
		} else {
			ItemStack stack = context.getStack();
			BlockEntity blockEntity = world.getBlockEntity(state.getBlock() instanceof DoorBlock && state.get(DoorBlock.HALF) == DoubleBlockHalf.UPPER ? pos.down() : pos);
			if (blockEntity instanceof TaglockHolder taglockHolder) {
				if (player.getUuid().equals(taglockHolder.getOwner())) {
					int firstEmpty = taglockHolder.getFirstEmptySlot();
					if (firstEmpty != -1) {
						if (!client) {
							taglockHolder.getTaglockInventory().set(firstEmpty, stack.split(1));
							taglockHolder.syncTaglockHolder(blockEntity);
							blockEntity.markDirty();
						}
						return ActionResult.success(client);
					}
				}
			} else if (blockEntity instanceof Lockable lockable) {
				if (hasTaglock(stack)) {
					if (player.getUuid().equals(lockable.getOwner()) && lockable.getLocked()) {
						UUID uuid = getTaglockUUID(stack);
						if (!lockable.getEntities().contains(uuid)) {
							if (!client) {
								if (lockable.getEntities().isEmpty()) {
									lockable.setModeOnWhitelist(true);
								}
								lockable.getEntities().add(uuid);
								if (!player.isCreative()) {
									stack.decrement(1);
								}
								lockable.syncLockable(blockEntity);
								blockEntity.markDirty();
							}
							return ActionResult.success(client);
						}
					}
				}
			} else if (blockEntity instanceof SigilHolder sigilHolder) {
				if (hasTaglock(stack)) {
					if (!client) {
						if (sigilHolder.getSigil() != null) {
							UUID uuid = getTaglockUUID(stack);
							if (!sigilHolder.getEntities().contains(uuid)) {
								if (sigilHolder.getEntities().isEmpty()) {
									sigilHolder.setModeOnWhitelist(true);
								}
								sigilHolder.getEntities().add(uuid);
								if (!player.isCreative()) {
									stack.decrement(1);
								}
								sigilHolder.syncSigilHolder(blockEntity);
								blockEntity.markDirty();
							}
						}
					}
					return ActionResult.success(client);
				}
			}
		}
		return super.useOnBlock(context);
	}

@Override
	public void appendTooltip(ItemStack stack, @Nullable World world, List<Text> tooltip, TooltipContext context) {
		if (hasTaglock(stack)) {
			tooltip.add(Text.literal(getTaglockName(stack)).formatted(Formatting.GRAY));
			NbtCompound nbt = stack.getNbt();
			if (nbt.contains("UsedForScrying")) {
				if (nbt.contains("Failed")) {
					tooltip.add(Text.translatable(Bewitchment.MOD_ID + ".tooltip.failed").formatted(Formatting.DARK_GRAY));
				} else {
					boolean shifting = Screen.hasShiftDown();
					BlockPos pos = BlockPos.fromLong(stack.getNbt().getLong("LocationPos"));
					tooltip.add(Text.translatable(Bewitchment.MOD_ID + ".tooltip.location", pos.getX(), pos.getY(), pos.getZ(), stack.getNbt().getString("LocationWorld")).formatted(Formatting.DARK_GRAY));
					tooltip.add(Text.translatable(Bewitchment.MOD_ID + ".tooltip.level", stack.getNbt().getInt("Level")).formatted(Formatting.DARK_GRAY));
					MutableText curseTooltip = Text.translatable(Bewitchment.MOD_ID + ".tooltip.curse");
					NbtList cursesList = nbt.getList("Curses", 10);
					if (cursesList.isEmpty()) {
						curseTooltip.append(Text.translatable(Bewitchment.MOD_ID + ".tooltip.none"));
					} else if (!shifting) {
						curseTooltip.append(Text.translatable(Bewitchment.MOD_ID + ".tooltip.press_shift"));
					}
					tooltip.add(curseTooltip.formatted(Formatting.DARK_GRAY));
					if (shifting) {
						for (NbtElement element : cursesList) {
							NbtCompound curseCompound = (NbtCompound) element;
							MutableText curseText = Text.translatable("curse." + curseCompound.getString("Curse").replace(":", "."));
							int duration = curseCompound.getInt("Duration") / 24000;
							tooltip.add(Text.translatable(Bewitchment.MOD_ID + ".tooltip.curse_expanded", curseText, duration).formatted(Formatting.DARK_GRAY));
						}
					}
					MutableText contractTooltip = Text.translatable(Bewitchment.MOD_ID + ".tooltip.contract");
					NbtList contractList = nbt.getList("Contracts", 10);
					if (contractList.isEmpty()) {
						contractTooltip.append(Text.translatable(Bewitchment.MOD_ID + ".tooltip.none"));
					} else if (!shifting) {
						contractTooltip.append(Text.translatable(Bewitchment.MOD_ID + ".tooltip.press_shift"));
					}
					tooltip.add(contractTooltip.formatted(Formatting.DARK_GRAY));
					if (shifting) {
						for (NbtElement element : contractList) {
							NbtCompound contractCompound = (NbtCompound) element;
							MutableText curseText = Text.translatable("contract." + contractCompound.getString("Contract").replace(":", "."));
							int duration = contractCompound.getInt("Duration") / 24000;
							tooltip.add(Text.translatable(Bewitchment.MOD_ID + ".tooltip.curse_expanded", curseText, duration).formatted(Formatting.DARK_GRAY));
						}
					}
					tooltip.add(Text.translatable(Bewitchment.MOD_ID + ".tooltip.transformation", Text.translatable(stack.getNbt().getString("Transformation"))).formatted(Formatting.DARK_GRAY));
					tooltip.add(Text.translatable(Bewitchment.MOD_ID + ".tooltip.familiar", Text.translatable("entity." + nbt.getString("Familiar").replace(":", "."))).formatted(Formatting.DARK_GRAY));
					tooltip.add(Text.translatable(Bewitchment.MOD_ID + ".tooltip.pledge", Text.translatable(stack.getNbt().getString("Pledge"))).formatted(Formatting.DARK_GRAY));
				}
			}
		}
	}

public static boolean hasTaglock(ItemStack stack) {
		return stack.hasNbt() && stack.getOrCreateNbt().contains("OwnerUUID");
	}

