@Inject(method = "craft(Lnet/minecraft/inventory/RecipeInputInventory;Lnet/minecraft/registry/DynamicRegistryManager;)Lnet/minecraft/item/ItemStack;", at = @At(value = "RETURN", ordinal = 1), cancellable = true)
	private void craft(RecipeInputInventory recipeInputInventory, DynamicRegistryManager dynamicRegistryManager, CallbackInfoReturnable<ItemStack> cir) {
		ItemStack stack = recipeInputInventory.getStack(1 + recipeInputInventory.getWidth());
		if (stack.hasNbt() && stack.getNbt().contains("BewitchmentBrew")) {
			int color = PotionUtil.getColor(stack);
			UUID uuid = null;
			String name = null;
			if (stack.getNbt().contains("PolymorphUUID")) {
				uuid = stack.getNbt().getUuid("PolymorphUUID");
				name = stack.getNbt().getString("PolymorphName");
			}
			stack = cir.getReturnValue();
			stack.getOrCreateNbt().putBoolean("BewitchmentBrew", true);
			stack.getOrCreateNbt().putInt("CustomPotionColor", color);
			if (uuid != null) {
				stack.getOrCreateNbt().putUuid("PolymorphUUID", uuid);
				stack.getOrCreateNbt().putString("PolymorphName", name);
			}
			cir.setReturnValue(stack);
		}
	}

@Inject(method = "tick", at = @At("TAIL"))
	private void tick(CallbackInfo callbackInfo) {
		if (getStack().getItem() == BWObjects.VOODOO_POPPET && !BWConfig.disabledPoppets.contains("bewitchment:voodoo_poppet")) {
			LivingEntity owner = BewitchmentAPI.getTaglockOwner(getWorld(), getStack());
			if (owner != null) {
				if (getVelocity().length() > 1 / 8f) {
					int damage = random.nextFloat() < 1 / 4f ? 1 : 0;
					if (getStack().damage(damage, random, null) && getStack().getDamage() >= getStack().getMaxDamage()) {
						getStack().decrement(1);
					}
					if (!BewitchmentAPI.hasVoodooProtection(owner, damage)) {
						owner.addVelocity(getVelocity().x / 2, getVelocity().y / 2, getVelocity().z / 2);
						owner.velocityModified = true;
					}
				}
				if (isSubmergedInWater()) {
					int damage = age % 20 == 0 ? 1 : 0;
					if (getStack().damage(damage, random, null) && getStack().getDamage() >= getStack().getMaxDamage()) {
						getStack().decrement(1);
					}
					if (!BewitchmentAPI.hasVoodooProtection(owner, damage)) {
						BWComponents.ADDITIONAL_WATER_DATA_COMPONENT.get(owner).setSubmerged(true);
					}
				}
			}
		}
	}

@Inject(method = "damage", at = @At("HEAD"), cancellable = true)
	private void damage(DamageSource source, float amount, CallbackInfoReturnable<Boolean> callbackInfo) {
		if (getStack().getItem() == BWObjects.VOODOO_POPPET && !BWConfig.disabledPoppets.contains("bewitchment:voodoo_poppet")) {
			if (!getWorld().isClient) {
				LivingEntity owner = BewitchmentAPI.getTaglockOwner(getWorld(), getStack());
				if (owner != null) {
					if (source.isIn(DamageTypeTags.IS_FIRE) || source.isOf(DamageTypes.LIGHTNING_BOLT)) {
						remove(RemovalReason.DISCARDED);
						if (!BewitchmentAPI.hasVoodooProtection(owner, getStack().getMaxDamage() / 4)) {
							owner.setFireTicks(Integer.MAX_VALUE);
						}
					}
					if (source.isOf(DamageTypes.CACTUS) && owner.hurtTime == 0) {
						if (getStack().damage(1, random, null) && getStack().getDamage() >= getStack().getMaxDamage()) {
							getStack().decrement(1);
						}
						if (!BewitchmentAPI.hasVoodooProtection(owner, 1)) {
							owner.damage(getWorld().getDamageSources().cactus(), 1);
						}
					}
				}
			}
			if (source.isIn(DamageTypeTags.IS_FIRE) || source.isOf(DamageTypes.LIGHTNING_BOLT) || source.isOf(DamageTypes.CACTUS)) {
				callbackInfo.setReturnValue(false);
			}
		}
	}

@Inject(method = "damage", at = @At("HEAD"))
	private void damageHead(DamageSource source, float amount, CallbackInfoReturnable<Boolean> callbackInfo) {
		if (!getWorld().isClient) {
			if (amount > 0 && hurtTime == 0) {
				if ((Object) this instanceof PlayerEntity player && source.getSource() instanceof LivingEntity livingSource) {
					List<Pair<SlotReference, ItemStack>> component = TrinketsApi.getTrinketComponent(player).get().getEquipped(BWObjects.PRICKLY_BELT);
					if (!component.isEmpty()) {
						ItemStack belt = component.get(0).getRight();
						if (belt.hasNbt() && belt.getNbt().getInt("PotionUses") > 0) {
							boolean used = false;
							List<StatusEffectInstance> effects = PotionUtil.getPotionEffects(belt);
							for (StatusEffectInstance effect : effects) {
								if (effect.getEffectType().getCategory() == StatusEffectCategory.HARMFUL) {
									if (!livingSource.hasStatusEffect(effect.getEffectType()) && BewitchmentAPI.drainMagic(player, 2, true) && livingSource.addStatusEffect(effect)) {
										used = true;
									}
								} else if (!hasStatusEffect(effect.getEffectType()) && BewitchmentAPI.drainMagic(player, 2, true) && addStatusEffect(effect)) {
									if (belt.getNbt().contains("PolymorphUUID")) {
										BWComponents.POLYMORPH_COMPONENT.maybeGet(this).ifPresent(polymorphComponent -> {
											polymorphComponent.setUuid(belt.getNbt().getUuid("PolymorphUUID"));
											polymorphComponent.setName(belt.getNbt().getString("PolymorphName"));
										});
									}
									used = true;
								}
							}
							if (used) {
								belt.getNbt().putInt("PotionUses", belt.getNbt().getInt("PotionUses") - 1);
								if (belt.getNbt().getInt("PotionUses") <= 0) {
									belt.getOrCreateNbt().put("CustomPotionEffects", new NbtList());
									if (belt.getNbt().contains("PolymorphUUID")) {
										belt.getNbt().remove("PolymorphUUID");
										belt.getNbt().remove("PolymorphName");
									}
								}
							}
						}
					}
				}
			}
		}
	}

@Override
	protected InteractionResult useWithoutItem(BlockState state, Level level, BlockPos pos, Player player, BlockHitResult hitResult) {
		return level.getBlockEntity(pos, ModBlocks.APOTHECARY_MORTAR_TILE_TYPE.get()).map(mortar -> {
			if (player.isCrouching()) {
				InventoryHelper.executeOnItemHandlerAt(level, pos, state, mortar,
						itemHandler -> InventoryHelper.tryRemovingLastStack(itemHandler, level, mortar.getBlockPos()));
				return InteractionResult.SUCCESS;
			}

			if (mortar.usePestle(level)) {
				level.playSound(null, pos, soundType.getStepSound(), SoundSource.BLOCKS, (soundType.getVolume() + 1.0F) / 2.0F, soundType.getPitch() * 0.8F);
				player.swing(InteractionHand.MAIN_HAND);
				return InteractionResult.CONSUME;
			}
			return InteractionResult.FAIL;
		}).orElse(InteractionResult.FAIL);
	}

@Override
	protected ItemInteractionResult useItemOn(ItemStack heldItem, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand,
			BlockHitResult hitResult) {
		return level.getBlockEntity(pos, ModBlocks.APOTHECARY_MORTAR_TILE_TYPE.get()).map(mortar -> {
			// if we're in cooldown prevent player from insta inserting essence that they just got from mortar
			if (mortar.isInCooldown(level) && heldItem.getItem() == ModItems.POTION_ESSENCE.get()) {
				return ItemInteractionResult.FAIL;
			}

			ItemStack stackToAdd = heldItem.copy();
			stackToAdd.setCount(1);

			boolean putItemInSlot = InventoryHelper.executeOnItemHandlerAt(level, pos, state, mortar, itemHandler -> {
				if (InventoryHelper.insertIntoInventory(stackToAdd, itemHandler) == 1) {
					heldItem.shrink(1);
					return true;
				}
				return false;
			}, false);

			if (!putItemInSlot) {
				if (mortar.usePestle(level)) {
					level.playSound(null, pos, soundType.getStepSound(), SoundSource.BLOCKS, (soundType.getVolume() + 1.0F) / 2.0F,
							soundType.getPitch() * 0.8F);
					return ItemInteractionResult.CONSUME;
				} else {
					return ItemInteractionResult.FAIL;
				}
			} else {
				mortar.setChanged();
			}
			return ItemInteractionResult.SUCCESS;
		}).orElse(ItemInteractionResult.FAIL);
	}

@Override
	public void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
		ResourceKey<Level> dimKey = level.dimension();
		if (!currentDimensionTicks.containsKey(dimKey) || currentDimensionTicks.get(dimKey) != level.getGameTime()) {
			currentDimensionTicks.put(dimKey, level.getGameTime());
			dimensionPositionsTicked.put(dimKey, new HashSet<>());
		} else if (dimensionPositionsTicked.computeIfAbsent(dimKey, k -> new HashSet<>()).contains(pos)) {
			return;
		}
		growCropsNearby(level, pos, state);
		dimensionPositionsTicked.computeIfAbsent(dimKey, k -> new HashSet<>()).add(pos);
	}

