public void tick() {
        if (this.level != null) {
            ++this.tickCount;
            if (this.level instanceof ServerLevel serverLevel) {
                int radius = 8 + this.getEnchantments().getOrDefault(ModEnchantments.RADIUS.get(), 0);
                if (this.target == null) {
                    for (LivingEntity livingEntity : serverLevel.getEntitiesOfClass(LivingEntity.class, new AABB(this.worldPosition).inflate(radius * 2))) {
                        if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity) && livingEntity.distanceToSqr(this.getBlockPos().getCenter()) <= Mth.square(radius)) {
                            boolean flag = livingEntity.getHealth() >= livingEntity.getMaxHealth() * 0.25F;
                            if (this.getTrueOwner() != null) {
                                flag &= !MobUtil.areAllies(this.getTrueOwner(), livingEntity);
                            } else {
                                flag &= !this.isAllyWith(livingEntity);
                            }
                            if (flag) {
                                this.target = livingEntity;
                            }
                        }
                    }
                } else {
                    if (!this.target.isAlive() || this.target.getHealth() < this.target.getMaxHealth() * 0.25F || this.target.distanceToSqr(this.getBlockPos().getCenter()) > Mth.square(radius)) {
                        this.attackTick = 0;
                        this.target = null;
                    } else {
                        ++this.attackTick;
                        if (this.attackTick % 20 == 0) {
                            Vec3 vector3d1 = this.getBlockPos().getCenter();
                            DamageSource damageSource = this.getTrueOwner() != null ? ModDamageSource.soulLeech(this.getTrueOwner(), this.getTrueOwner()) : this.level.damageSources().magic();
                            this.target.addEffect(new MobEffectInstance(GoetyEffects.CURSED.get(), 10, 0, false, false));
                            if (this.target.hurt(damageSource, this.target.getMaxHealth() * 0.1F)) {
                                ColorUtil colorUtil1 = new ColorUtil(0x5038dd);
                                serverLevel.sendParticles(new SpirallingParticleOption(1.0F, colorUtil1.red, colorUtil1.green, colorUtil1.blue, 5), vector3d1.x, vector3d1.y, vector3d1.z, 1, 0.0D, 0.0D, 0.0D, 1.0D);
                                Vec3 vec3 = new Vec3(this.target.getX(), this.target.getY() + (this.target.getBbHeight() / 2.0F), this.target.getZ());
                                serverLevel.sendParticles(new GatherTrailParticleOption(colorUtil1, vector3d1), vec3.x, vec3.y, vec3.z, 0, 0.0F, 0.0F, 0.0F, 0.5F);
                                for (int i = 0; i < 8; ++i) {
                                    Vec3 vec31 = new Vec3(this.target.getRandomX(1.0F), this.target.getRandomY(), this.target.getRandomZ(1.0F));
                                    serverLevel.sendParticles(new AbsorbTrailParticleOption(vector3d1, 0x5038dd, 10), vec31.x, vec31.y, vec31.z, 1, 0.0, 0.0, 0.0, 0.0);
                                }
                                this.level.playSound(null, this.worldPosition, ModSounds.SOUL_EAT.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                if (this.getTrueOwner() instanceof Player player) {
                                    if (SEHelper.getSoulGiven(this.target) > 0) {
                                        int enchantment = this.getEnchantments().getOrDefault(ModEnchantments.SOUL_EATER.get(), 0);
                                        int soulEater = Mth.clamp(enchantment + 1, 1, 10);
                                        SEHelper.increaseSouls(player, MainConfig.BlackCrystalSouls.get() * soulEater);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

public boolean canCraft(Level world) {
        Container container = this.getCraftContainer();

        if (this.recipe != null) {
            if (this.recipe.couldMatch(container, world)) {
                return true;
            }
            this.recipe = null;
        }

        List<CauldronRecipe> candidates = world.getRecipeManager()
                .getAllRecipesFor(ModRecipeSerializer.CAULDRON_TYPE.get()).stream()
                .filter(r -> r.couldMatch(container, world))
                .toList();

        if (candidates.isEmpty()) {
            return false;
        }

        CauldronRecipe exact = candidates.stream()
                .filter(r -> r.matches(container, world))
                .findFirst().orElse(null);

        if (exact != null) {
            this.recipe = exact;
        } else if (candidates.size() == 1) {
            this.recipe = candidates.get(0);
        }
        return true;
    }

public Mode addSacrifice(Entity entity){
        if (this.level != null && !this.level.isClientSide){
            int firstEmpty = getFirstEmptySlot();
            if (firstEmpty != -1) {
                if (this.mode == Mode.BREWING && this.getOccupiedSlots() >= this.getCapacity()) {
                    return fail();
                }
                this.setSacrificed(firstEmpty, entity.getType());
                if (this.mode == Mode.BREWING) {
                    BrewingRecipe brewingRecipe = this.level.getRecipeManager().getAllRecipesFor(ModRecipeSerializer.BREWING_TYPE.get()).stream()
                            .filter(recipe -> {
                                if (recipe.getEntityTypeTag() != null){
                                    return entity.getType().is(recipe.getEntityTypeTag());
                                } else if (recipe.getEntityType() != null) {
                                    return entity.getType() == recipe.getEntityType();
                                }
                                return false;
                            }).findFirst().orElse(null);
                    BrewEffect brewEffect = new BrewEffects().getEffectFromSacrifice(entity.getType());
                    if (brewingRecipe != null){
                        if ((brewingRecipe.getCapacityExtra() + this.getCapacityUsed()) <= this.getCapacity()) {
                            this.capacityUsed += brewingRecipe.getCapacityExtra();
                            this.addCost(brewingRecipe.soulCost);
                            this.setColor(BrewUtils.getColor(this.getBrew()));
                            return Mode.BREWING;
                        }
                    }
                    if (brewEffect != null){
                        if ((brewEffect.getCapacityExtra() + this.getCapacityUsed()) <= this.getCapacity()) {
                            this.capacityUsed += brewEffect.getCapacityExtra();
                            this.addCost(brewEffect.getSoulCost());
                            this.setColor(BrewUtils.getColor(this.getBrew()));
                            return Mode.BREWING;
                        }
                    }
                }
            }
            this.markUpdated();
        }
        return fail();
    }

public Mode insertItem(ItemStack itemStack){
        if (this.level != null && !this.level.isClientSide){
            boolean craft = itemStack.is(ModItems.NIGHTSHADE_BLOSSOM.get());
            if (this.mode == Mode.IDLE && craft) {
                this.clearContent();
                return Mode.CRAFTING;
            } else if (this.mode == Mode.CRAFTING && this.addCraftItem(itemStack)) {
                if (!this.canCraft(this.level)) {
                    return this.fail();
                }
                return Mode.CRAFTING;
            }
            Item ingredient = itemStack.getItem();
            BrewModifier brewModifier = new BrewEffects().getModifier(ingredient);
            int modLevel = brewModifier != null ? brewModifier.getLevel() : -1;
            boolean activate = brewModifier instanceof CapacityModifier && brewModifier.getLevel() == 0;
            int firstEmpty = getFirstEmptySlot();
            if (firstEmpty != -1 && this.mode != Mode.CRAFTING) {
                if (this.mode == Mode.BREWING && !this.freeModifier(brewModifier) && !activate) {
                    if (this.getOccupiedSlots() >= this.getCapacity()) {
                        return fail();
                    }
                }

                this.setItem(firstEmpty, itemStack);
                if (this.mode == Mode.IDLE && this.getCapacity() < BrewConfig.InitialCapacity.get() && activate) {
                    this.clearContent();
                    this.capacity = BrewConfig.InitialCapacity.get();
                    if (this.level instanceof ServerLevel serverLevel){
                        for(int k = 0; k < 20; ++k) {
                            float f2 = serverLevel.random.nextFloat() * 4.0F;
                            float f1 = serverLevel.random.nextFloat() * ((float)Math.PI * 2F);
                            double d1 = Mth.cos(f1) * f2;
                            double d2 = 0.01D + serverLevel.random.nextDouble() * 0.5D;
                            double d3 = Mth.sin(f1) * f2;
                            serverLevel.sendParticles(ParticleTypes.WITCH, (this.getBlockPos().getX() + 0.5D) + d1 * 0.1D, (this.getBlockPos().getY() + 0.5D) + 0.3D, (this.getBlockPos().getZ() + 0.5D) + d3 * 0.1D, 0, d1, d2, d3, 0.25F);
