public void inventoryTick(ItemStack p_40720_, Level p_40721_, Entity p_40722_, int p_40723_, boolean p_40724_) {
        if (!p_40721_.isClientSide) {
            CompoundTag compoundtag = p_40720_.getOrCreateTag();
            if (!p_40722_.isAlive()){
                if (compoundtag.contains(TAG_PLAYER)){
                    compoundtag.remove(TAG_PLAYER);
                }
                if (compoundtag.contains(TAG_PLAYER_NAME)){
                    compoundtag.remove(TAG_PLAYER_NAME);
                }
                if (compoundtag.contains(TAG_ARCA_POS)){
                    compoundtag.remove(TAG_ARCA_POS);
                }
                if (compoundtag.contains(TAG_ARCA_DIMENSION)){
                    compoundtag.remove(TAG_ARCA_DIMENSION);
                }
                if (compoundtag.contains(TAG_ARCA_TRACKED)){
                    compoundtag.remove(TAG_ARCA_TRACKED);
                }
            }
            if (hasPlayer(p_40720_)){
                if (compoundtag.contains(TAG_PLAYER)){
                    Player player = p_40721_.getPlayerByUUID(compoundtag.getUUID(TAG_PLAYER));
                    if (player == null) {
                        return;
                    }
                    if (SEHelper.getArcaBlock(player) != null){
                        if (!compoundtag.contains(TAG_ARCA_POS)){
                            compoundtag.put(TAG_ARCA_POS, NbtUtils.writeBlockPos(SEHelper.getArcaBlock(player)));
                            if (SEHelper.getArcaDimension(player) != null){
                                Level.RESOURCE_KEY_CODEC.encodeStart(NbtOps.INSTANCE, SEHelper.getArcaDimension(player)).result().ifPresent((p_40731_) -> {
                                    compoundtag.put(TAG_ARCA_DIMENSION, p_40731_);
                                });
                            }
                        }
                    }
                }
                if (hasArca(p_40720_)) {
                    if (compoundtag.contains(TAG_ARCA_TRACKED) && !compoundtag.getBoolean(TAG_ARCA_TRACKED)) {
                        return;
                    }

                    Optional<ResourceKey<Level>> optional = getArcaDimension(compoundtag);
                    if (optional.isPresent() && optional.get() == p_40721_.dimension() && compoundtag.contains(TAG_ARCA_POS)) {
                        BlockPos blockpos = NbtUtils.readBlockPos(compoundtag.getCompound(TAG_ARCA_POS));
                        if (!p_40721_.isInWorldBounds(blockpos) || !(p_40721_.getBlockEntity(blockpos) instanceof ArcaBlockEntity)) {
                            compoundtag.remove(TAG_ARCA_POS);
                        }
                    }
                }
            } else if (compoundtag.contains(TAG_PLAYER_NAME)){
                compoundtag.remove(TAG_PLAYER_NAME);
            }
        }
    }

@Override
    public void appendHoverText(ItemStack stack, Level worldIn, List<Component> tooltip, TooltipFlag flagIn) {
        if (stack.getTag() != null) {
            if (stack.getTag().contains(TAG_PLAYER_NAME)) {
                tooltip.add(Component.translatable("tooltip.goety.arca_compass_track", stack.getTag().getString(TAG_PLAYER_NAME)).withStyle(ChatFormatting.AQUA));
            }
            GlobalPos globalPos = getArcaPosition(stack.getTag());
            if (globalPos != null) {
                BlockPos blockPos = globalPos.pos();
                tooltip.add(Component.translatable("tooltip.goety.arca").withStyle(ChatFormatting.GOLD)
                        .append(Component.translatable("tooltip.goety.arcaCoords", blockPos.getX(), blockPos.getY(), blockPos.getZ())));
                if (getArcaDimension(stack.getTag()).isPresent()){
                    ResourceKey<Level> dimension = getArcaDimension(stack.getTag()).get();
                    tooltip.add(Component.translatable("tooltip.goety.arcaDimension", dimension.location().toString()));
                }
            }
        } else {
            tooltip.add(Component.translatable("tooltip.goety.arca_compass").withStyle(ChatFormatting.GOLD));
        }
        super.appendHoverText(stack, worldIn, tooltip, flagIn);
    }

public InteractionResultHolder<ItemStack> use(Level pLevel, Player pPlayer, InteractionHand pHand) {
        ItemStack itemstack = pPlayer.getItemInHand(pHand);
        HitResult raytraceresult = getPlayerPOVHitResult(pLevel, pPlayer, ClipContext.Fluid.ANY);
        if (raytraceresult.getType() == HitResult.Type.MISS) {
            return InteractionResultHolder.pass(itemstack);
        } else {
            Vec3 vector3d = pPlayer.getViewVector(1.0F);
            double d0 = 5.0D;
            List<Entity> list = pLevel.getEntities(pPlayer, pPlayer.getBoundingBox().expandTowards(vector3d.scale(5.0D)).inflate(1.0D), ENTITY_PREDICATE);
            if (!list.isEmpty()) {
                Vec3 vector3d1 = pPlayer.getEyePosition(1.0F);

                for(Entity entity : list) {
                    AABB axisalignedbb = entity.getBoundingBox().inflate((double)entity.getPickRadius());
                    if (axisalignedbb.contains(vector3d1)) {
                        return InteractionResultHolder.pass(itemstack);
                    }
                }
            }

            if (raytraceresult.getType() == HitResult.Type.BLOCK) {
                ModBoat boatentity = this.getBoat(pLevel, raytraceresult);
                boatentity.setType(this.type);
                boatentity.setYRot(pPlayer.getYRot());
                if (!pLevel.noCollision(boatentity, boatentity.getBoundingBox().inflate(-0.1D))) {
                    return InteractionResultHolder.fail(itemstack);
                } else {
                    if (!pLevel.isClientSide) {
                        pLevel.addFreshEntity(boatentity);
                        if (!pPlayer.getAbilities().instabuild) {
                            itemstack.shrink(1);
                        }
                    }

                    pPlayer.awardStat(Stats.ITEM_USED.get(this));
                    return InteractionResultHolder.sidedSuccess(itemstack, pLevel.isClientSide());
                }
            } else {
                return InteractionResultHolder.pass(itemstack);
            }
        }
    }

@Override
    public InteractionResult interactLivingEntity(ItemStack stack, Player player, LivingEntity target, InteractionHand hand) {
        Level level = player.getCommandSenderWorld();
        if (!level.isClientSide) {
            if (target instanceof AbstractVillager villager && !villager.isBaby() && !villager.getType().is(ModTags.EntityTypes.UNSHACKLEABLE)) {
                Prisoner prisoner = ServantUtil.takePrisoner(villager);
                if (prisoner != null) {
                    prisoner.setTrueOwner(player);
                    for (Mob mob : level.getEntitiesOfClass(Mob.class, player.getBoundingBox().inflate(16.0D))) {
                        if (mob instanceof Villager villager1) {
                            Brain<?> brain = villager1.getBrain();
                            Player player1 = brain.getMemory(MemoryModuleType.NEAREST_VISIBLE_PLAYER).orElse(null);
                            if (player1 != null && player1 == player) {
                                if (villager1.getPlayerReputation(player) > -200) {
                                    villager1.getGossips().add(player.getUUID(), GossipType.MAJOR_NEGATIVE, 25);
                                }
                            }
                        }
                        if (mob.getType().is(ModTags.EntityTypes.VILLAGE_GUARDS)) {
                            if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(player) && !MobUtil.areAllies(mob, player)) {
                                if (mob instanceof IronGolem ironGolem) {
                                    if (!ironGolem.isPlayerCreated()) {
                                        ironGolem.setTarget(player);
                                    }
                                } else {
                                    mob.setTarget(player);
                                }
                            }
                        }
                    }
                    prisoner.setItemInHand(InteractionHand.OFF_HAND, new ItemStack(ModItems.OMINOUS_SHACKLES.get()));
                    prisoner.setDropChance(EquipmentSlot.OFFHAND, 0.0F);
                    stack.shrink(1);
                    return InteractionResult.SUCCESS;
                }
            }
        }
        return super.interactLivingEntity(stack, player, target, hand);
    }

public ItemStack finishUsingItem(ItemStack stack, Level worldIn, LivingEntity entityLiving) {
        super.finishUsingItem(stack, worldIn, entityLiving);
        if (worldIn instanceof ServerLevel serverWorld){
            boolean flag = serverWorld.isVillage(entityLiving.blockPosition());
            entityLiving.playSound(SoundEvents.RAID_HORN.get(), 16.0F, 1.0F);
            serverWorld.playSound(null, entityLiving.blockPosition(), SoundEvents.RAID_HORN.get(), SoundSource.NEUTRAL, 16.0F, 1.0F);
            if (entityLiving instanceof Player player) {
                if (SEHelper.getAllyEntityTypes(player).contains(EntityType.VILLAGER)) {
                    flag = false;
                }
            }
            if (flag){
                int i = 0;
                for (RaiderServant servant : worldIn.getEntitiesOfClass(RaiderServant.class, entityLiving.getBoundingBox().inflate(16.0F))) {
                    if (servant.getTrueOwner() == entityLiving) {
                        ++i;
                        servant.setRaidPos(entityLiving.blockPosition());
                        servant.setRaidDim(serverWorld.dimension());
                        if (servant.isStaying()) {
                            servant.setStaying(false);
                        }
                        if (servant.isGuardingArea()) {
                            servant.setBoundPos(null);
                        }
                        if (servant.isLeader()) {
                            for (RaiderServant servant1 : servant.getNearbyCompanions()) {
                                servant1.setRaidPos(entityLiving.blockPosition());
                                servant1.setRaidDim(serverWorld.dimension());
                                if (servant1.getLeader() == null) {
                                    servant1.setLeader(servant);
                                    servant1.setFollowing();
                                }
                            }
                        }
                    }
                }
                if (i > 0) {
                    if (entityLiving instanceof Player player) {
                        SEHelper.addCooldown(player, this, 300);
                    }
                }
            }
        }
        return stack;
    }

@Override
    public InteractionResult interactLivingEntity(ItemStack stack, Player player, LivingEntity target, InteractionHand hand) {
        Level level = player.getCommandSenderWorld();
        if (!level.isClientSide) {
            if (player.getOffhandItem().getItem() instanceof HammerItem || player.getOffhandItem().is(ModTags.Items.HAMMERS)) {
                if (target instanceof Mob mob) {
                    if (target.getType().getDescriptionId().contains("golem") || target.getType().is(ModTags.EntityTypes.REPAIRABLE)) {
                        boolean ownedByPlayer = mob instanceof OwnableEntity owned && owned.getOwner() == player;
                        boolean notTargetFriendly = mob.getTarget() == null || (mob.getTarget() != player && !MobUtil.areAllies(mob.getTarget(), player));
                        if (mob.getHealth() < mob.getMaxHealth() && !mob.isDeadOrDying()) {
                            if (notTargetFriendly || ownedByPlayer || (target instanceof IronGolem golem && golem.isPlayerCreated())) {
                                mob.heal(25.0F);
                                float f1 = 1.0F + (level.getRandom().nextFloat() - level.getRandom().nextFloat()) * 0.2F;
                                mob.playSound(SoundEvents.IRON_GOLEM_REPAIR, 1.0F, f1);
                                if (level instanceof ServerLevel serverLevel) {
                                    for (int i = 0; i < 7; ++i) {
                                        double d0 = mob.getRandom().nextGaussian() * 0.02D;
                                        double d1 = mob.getRandom().nextGaussian() * 0.02D;
                                        double d2 = mob.getRandom().nextGaussian() * 0.02D;
                                        serverLevel.sendParticles(ModParticleTypes.HEAL_EFFECT.get(), mob.getRandomX(1.0D), mob.getRandomY() + 0.5D, mob.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                                    }
                                }
                                if (!player.getAbilities().instabuild) {
                                    stack.shrink(1);
                                }
                                return InteractionResult.SUCCESS;
                            }
                        }
                    }
                }
            }
        }
        return super.interactLivingEntity(stack, player, target, hand);
    }

