private static boolean tryLoadProjectiles(LivingEntity shooter, ItemStack crossbow) {
        int i = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.MULTISHOT, crossbow);
        int j = i == 0 ? 3 : 9;
        boolean flag = shooter instanceof Player player && player.getAbilities().instabuild;
        ItemStack itemstack = shooter.getProjectile(crossbow);
        ItemStack itemstack1 = itemstack.copy();

        for(int k = 0; k < j; ++k) {
            if (k > 0) {
                itemstack = itemstack1.copy();
            }

            if (itemstack.isEmpty() && flag) {
                itemstack = new ItemStack(Items.ARROW);
                itemstack1 = itemstack.copy();
            }

            if (!loadProjectile(shooter, crossbow, itemstack, k > 0, flag)) {
                return false;
            }
        }

        return true;
    }

private static boolean loadProjectile(LivingEntity shooter, ItemStack crossbow, ItemStack arrow, boolean hasArrow, boolean creative) {
        if (arrow.isEmpty()) {
            return false;
        } else {
            boolean flag = creative && arrow.getItem() instanceof ArrowItem;
            ItemStack itemstack;
            if (!flag && !creative && !hasArrow) {
                itemstack = arrow.split(1);
                if (arrow.isEmpty() && shooter instanceof Player player) {
                    player.getInventory().removeItem(arrow);
                }
            } else {
                itemstack = arrow.copy();
            }

            addChargedProjectile(crossbow, itemstack);
            return true;
        }
    }

public void chain(LivingEntity pTarget, LivingEntity pAttacker) {
        double range = 6;
        Level level = pAttacker.level;
        float oDamage = getInitialDamage();

        List<Entity> harmed = new ArrayList<>();
        Predicate<Entity> selector = entity -> entity instanceof LivingEntity livingEntity && livingEntity != pAttacker && !harmed.contains(livingEntity) && MobUtil.canAttack(pAttacker, livingEntity);
        LivingEntity prevTarget = pTarget;

        float damage = level.isThundering() ? oDamage : oDamage / 2.0F;

        for (int i = 0; i < 4; i++) {
            AABB aabb = new AABB(Vec3Util.subtract(prevTarget.position(), range), Vec3Util.add(prevTarget.position(), range));
            List<Entity> entities = level.getEntities(prevTarget, aabb, selector);
            if (!entities.isEmpty()) {
                LivingEntity target = (LivingEntity) entities.get(level.getRandom().nextInt(entities.size()));
                if (target.hurt(ModDamageSource.directShock(pAttacker), damage)) {
                    if (prevTarget != target) {
                        Vec3 vec3 = prevTarget.getEyePosition();
                        Vec3 vec31 = target.getEyePosition();
                        ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, 8));
                    }
                }

                harmed.add(target);
                prevTarget = target;
                damage--;
            }
        }
    }

