@Override
    public void appendHoverText(ItemStack stack, Item.TooltipContext context, TooltipDisplay display, Consumer<Component> tooltip, TooltipFlag tooltipFlag) {
        tooltip.accept(Component.translatable("block.apotheosis.reforging_table.desc").withStyle(ChatFormatting.GRAY));

        LootRarity max = this.computeMaxRarity();
        if (max == null) {
            return;
        }

        LootRarity globalMax = RarityRegistry.getSortedRarities().stream()
            .max(Comparator.comparingInt(LootRarity::sortIndex))
            .orElse(null);

        if (globalMax != null && max.sortIndex() < globalMax.sortIndex()) {
            tooltip.accept(Component.translatable("block.apotheosis.reforging_table.desc2", max.toComponent()).withStyle(ChatFormatting.GRAY));
        }
    }

@SuppressWarnings("deprecation")
    private LootRarity computeMaxRarity() {
        LootRarity best = null;
        for (RecipeHolder<ReforgingRecipe> holder : ReforgingRecipeCache.all()) {
            ReforgingRecipe recipe = holder.value();
            if (!recipe.tables().contains(this.getBlock().builtInRegistryHolder()) || !recipe.rarity().isBound()) {
                continue;
            }
            LootRarity r = recipe.rarity().get();
            if (best == null || r.sortIndex() > best.sortIndex()) {
                best = r;
            }
        }
        return best;
    }

@Nullable
    @SuppressWarnings("deprecation")
    public ReforgingRecipe getRecipeFor(LootRarity rarity) {
        if (this.level == null) {
            return null;
        }
        Collection<RecipeHolder<ReforgingRecipe>> recipes;
        if (this.level.isClientSide()) {
            recipes = ReforgingRecipeCache.all();
        }
        else {
            recipes = this.level.getServer().getRecipeManager().recipeMap().byType(RecipeTypes.REFORGING);
        }
        return recipes.stream()
            .map(RecipeHolder::value)
            .filter(r -> r.rarity().get() == rarity && r.tables().contains(this.getBlockState().getBlock().builtInRegistryHolder()))
            .findFirst()
            .orElse(null);
    }

@Override
    public void extractRenderState(GuiGraphicsExtractor gfx, int mouseX, int mouseY, float partialTick) {
        super.extractRenderState(gfx, mouseX, mouseY, partialTick);

        int maxDisplay = Math.min(6, this.results.size());

        IntSet skipSlots = new IntOpenHashSet();
        for (int i = 0; i < maxDisplay; i++) {
            ItemStack display = this.results.get(i).stack().create();
            int displaySlot = -1;
            for (int slot = 12; slot < 18; slot++) {
                if (skipSlots.contains(slot)) {
                    continue;
                }
                ItemStack outStack = this.menu.slots.get(slot).getItem();
                if (outStack.isEmpty()) {
                    displaySlot = slot;
                    skipSlots.add(slot);
                    break;
                }
                else if (outStack.is(display.getItem())) {
                    break;
                }
            }
            if (displaySlot == -1) {
                continue;
            }
            Slot slot = this.menu.getSlot(displaySlot);
            int sx = this.getLeftPos() + slot.x;
            int sy = this.getTopPos() + slot.y;
            PipelinedRenderer.grayFakeItem(gfx, display, sx, sy);
        }

        List<Component> tooltip = new ArrayList<>();
        tooltip.add(Component.translatable("text.apotheosis.salvage_results").withStyle(ChatFormatting.YELLOW, ChatFormatting.UNDERLINE));
        for (OutputData data : this.results) {
            tooltip.add(Component.translatable("%s-%s %s", data.min(), data.max(), data.stack().create().getHoverName()));
        }
        if (tooltip.size() > 1) {
            this.drawOnLeft(gfx, tooltip, this.getTopPos() + 29);
        }
    }

