public static ItemStack createLootItem(ItemStack stack, LootCategory cat, LootRarity rarity, GenContext ctx) {
        stack.set(Components.AFFIXES, ItemAffixes.EMPTY);
        AffixHelper.setRarity(stack, rarity);

        for (LootRule rule : rarity.getRules(cat)) {
            rule.execute(stack, rarity, ctx);
        }

        ItemAffixes loaded = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY);
        if (loaded.size() == 0) {
            return stack; // TODO: Re-enable the hard error when we actually have affixes loaded.
            // throw new RuntimeException(String.format("Failed to locate any affixes for %s{%s} with category %s and rarity %s.", stack.getItem(), stack.getComponents(),
            // cat, rarity));
        }

        List<Affix> nameList = new ArrayList<>(loaded.size());
        for (DynamicHolder<Affix> a : loaded.keySet()) {
            nameList.add(a.get());
        }

        jRand.setSeed(ctx.rand().nextLong());
        Collections.shuffle(nameList, jRand);
        String key = nameList.size() > 1 ? "misc.apotheosis.affix_name.three" : "misc.apotheosis.affix_name.two";
        MutableComponent name = Component.translatable(key, nameList.get(0).getName(true), "", nameList.size() > 1 ? nameList.get(1).getName(false) : "").withStyle(Style.EMPTY.withColor(rarity.color()).withItalic(false));
        AffixHelper.setName(stack, name);
        stack.remove(Components.TOUCHED_BY_MALICE);

        return stack;
    }

public static Stream<DynamicHolder<Affix>> getAvailableAffixes(ItemStack stack, LootRarity rarity, AffixType type) {
        LootCategory cat = LootCategory.forItem(stack);
        ItemAffixes current = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY);
        return AffixHelper.byType(type).stream()
            .filter(a -> a.get().canApplyTo(stack, cat, rarity))
            .filter(a -> a.get().isCompatibleWith(current));
    }

public static Stream<DynamicHolder<Affix>> getAlternativeAffixes(Player player, ItemStack stack, LootRarity rarity, DynamicHolder<Affix> affix) {
        ItemStack copy = stack.copy();
        ItemAffixes fixed = copy.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY).toBuilder().remove(affix).build();
        copy.set(Components.AFFIXES, fixed);
        return getAvailableAffixes(copy, rarity, affix.get().definition().type()).filter(a -> !a.equals(affix)).filter(hasPositiveWeight(player));
    }

@Override
        public void execute(ItemStack stack, LootRarity rarity, GenContext ctx) {
            List<Weighted<Affix>> available = LootController.getWeightedAffixes(stack, rarity, this.type, ctx);
            int weight = WeightedRandom.getTotalWeight(available, Weighted::weight);
            if (available.size() == 0 || weight == 0) {
                Identifier id = BuiltInRegistries.ITEM.getKey(stack.getItem());
                Apotheosis.LOGGER.error("Failed to execute AffixLootRule (no affixes available) {}/{}/{}/{}!", id, RarityRegistry.INSTANCE.getKey(rarity), this.type, LootCategory.forItem(stack));
                return;
            }
            Affix selected = WeightedRandom.getRandomItem(ctx.rand(), available, weight, Weighted::weight).get().value();
            ItemAffixes.Builder builder = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY).toBuilder();
            builder.upgrade(AffixRegistry.INSTANCE.holder(selected), ctx.rand().nextFloat());
            AffixHelper.setAffixes(stack, builder.build());
        }

@Inject(at = @At("RETURN"), method = "processDurabilityChange(Lnet/minecraft/server/level/ServerLevel;Lnet/minecraft/world/item/ItemStack;I)I", cancellable = true)
    private static void apoth_processAffixDurability(ServerLevel level, ItemStack stack, int damage, CallbackInfoReturnable<Integer> cir) {
        if (cir.getReturnValueI() <= 0) {
            return;
        }

        int amount = cir.getReturnValueI();
        double chance = stack.getOrDefault(Components.DURABILITY_BONUS, 0F);

        if (stack.has(Components.SOCKETED_GEMS)) {
            double socketBonus = SocketHelper.getGems(stack).getDurabilityBonusPercentage().reduce(0, ApothMiscUtil::duraProd);
            chance = ApothMiscUtil.duraProd(chance, socketBonus);
        }

        if (stack.has(Components.AFFIXES)) {
            double afxBonus = AffixHelper.streamAffixes(stack).mapToDouble(AffixInstance::getDurabilityBonusPercentage).reduce(0, ApothMiscUtil::duraProd);
            chance = ApothMiscUtil.duraProd(chance, afxBonus);
        }

        int delta = 1;
        int blocked = 0;

        if (chance < 0) {
            delta = -1;
            chance = -chance;
        }

        if (chance > 0) {
            for (int i = 0; i < amount; i++) {
                if (level.getRandom().nextFloat() <= chance) {
                    blocked += delta;
                }
            }
        }

        cir.setReturnValue(amount - blocked);
    }

@Inject(method = "useOn", at = @At("RETURN"), cancellable = true)
    public void apoth_useItemOnBlockPost(UseOnContext ctx, CallbackInfoReturnable<InteractionResult> cir, @Local UseItemOnBlockEvent event) {
        if (!cir.getReturnValue().consumesAction() && !event.isCanceled()) {
            ItemStack s = (ItemStack) (Object) this;
            InteractionResult socketRes = SocketHelper.getGems(s).onItemUse(ctx);
            if (socketRes != null) {
                cir.setReturnValue(socketRes);
                return;
            }

            InteractionResult afxRes = AffixHelper.streamAffixes(s).map(afx -> afx.onItemUse(ctx)).filter(Predicates.notNull()).findFirst().orElse(null);
            if (afxRes != null) {
                cir.setReturnValue(afxRes);
                return;
            }
        }
    }

public void transformMiniboss(ServerLevelAccessor level, Mob mob, GenContext ctx) {
        Vec3 pos = mob.getPosition(0);

        Optional<CompoundTag> optNbt = this.basicData.nbt();
        if (optNbt.isPresent()) {
            // Since the mob already exists, we need to load all the entities in the passengers tab.
            CompoundTag nbt = optNbt.get();
            if (nbt.contains(Entity.TAG_PASSENGERS)) {
                ListTag passengers = nbt.getListOrEmpty(Entity.TAG_PASSENGERS);
                for (int i = 0; i < passengers.size(); ++i) {
                    Entity entity = EntityType.loadEntityRecursive(passengers.getCompoundOrEmpty(i), level.getLevel(), net.minecraft.world.entity.EntitySpawnReason.EVENT, net.minecraft.world.entity.EntityProcessor.NOP);
                    if (entity != null) {
                        entity.setPos(pos);
                        level.addFreshEntityWithPassengers(entity);
                        entity.startRiding(mob, true, true);
                    }
                }
            }
        }

        mob.setPos(pos);
        this.initElite(mob, ctx);

        // readAdditionalSaveData should leave unchanged any tags that are not in the NBT data.
        if (optNbt.isPresent()) {
            try (ProblemReporter.ScopedCollector reporter = new ProblemReporter.ScopedCollector(mob.problemPath(), dev.shadowsoffire.apotheosis.Apotheosis.LOGGER)) {
                ((EntityInvoker) mob).callReadAdditionalSaveData(TagValueInput.create(reporter, level.registryAccess(), optNbt.get()));
            }
        }

        if (this.basicData.hasMount()) {
            Mob mount = this.basicData().createMount(level, BlockPos.containing(pos), mob);
            level.addFreshEntity(mount);
        }

        for (SupportingEntity support : this.basicData.support()) {
            // TODO: Improve spawning algorithm instead of spawning all mobs directly on top of the main entity.
            // Probably best to steal the inward spiral from Gateways.
            Mob supportingMob = support.create(mob.level(), mob.getX() + 0.5, mob.getY(), mob.getZ() + 0.5);
            if (supportingMob != null) {
                level.addFreshEntity(supportingMob);
            }
        }
    }

public Mob createBoss(ServerLevelAccessor level, BlockPos pos, GenContext ctx, @Nullable LootRarity rarity) {
        Optional<CompoundTag> nbt = this.basicData.nbt();
        CompoundTag fakeNbt = nbt.map(CompoundTag::copy).orElse(new CompoundTag());
        fakeNbt.putString("id", EntityType.getKey(this.entity).toString());
        Mob entity = (Mob) EntityType.loadEntityRecursive(fakeNbt, level.getLevel(), net.minecraft.world.entity.EntitySpawnReason.EVENT, net.minecraft.world.entity.EntityProcessor.NOP);

        this.initBoss(entity, ctx, rarity);

        if (this.basicData.finalizeSpawn()) {
            // TODO: Implement finalize support for invaders. Needs to not fire the event, or somehow recursively fire the event without reentrancy.
        }

        // Re-read here so we can apply certain things after the boss has been modified
        // But only mob-specific things, not a full load()
        if (nbt.isPresent()) {
            try (net.minecraft.util.ProblemReporter.ScopedCollector reporter = new net.minecraft.util.ProblemReporter.ScopedCollector(entity.problemPath(), Apotheosis.LOGGER)) {
                ((dev.shadowsoffire.apotheosis.mixin.EntityInvoker) entity).callReadAdditionalSaveData(net.minecraft.world.level.storage.TagValueInput.create(reporter, level.registryAccess(), nbt.get()));
            }
        }

        entity.snapTo(pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5, ctx.rand().nextFloat() * 360.0F, 0.0F);

        if (this.basicData.hasMount()) {
            entity = this.basicData.createMount(level, pos, entity);
        }

        entity.snapTo(pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5, ctx.rand().nextFloat() * 360.0F, 0.0F);

        // TODO: Implement supporting entities here. Need to return the boss *and* the supports for spawning.
        return entity;
    }

public void initBoss(Mob mob, GenContext ctx, @Nullable LootRarity rarity) {
        RandomSource rand = ctx.rand();

        if (rarity == null) {
            rarity = LootRarity.random(ctx, this.stats.keySet());
        }

        BossStats stats = this.stats.get(rarity);
        int duration = mob instanceof Creeper ? 6000 : Integer.MAX_VALUE;

        for (ChancedEffectInstance inst : stats.effects()) {
            if (rand.nextFloat() <= inst.chance()) {
                mob.addEffect(inst.create(rand, duration));
            }
        }

        for (RandomAttributeModifier modif : stats.modifiers()) {
            modif.apply(rand, mob);
        }

        mob.goalSelector.getAvailableGoals().removeIf(IS_VILLAGER_ATTACK);

        this.basicData.applyEntityName(rand, mob);

        GearSet set = this.basicData.applyGearSet(mob, ctx);

        if (set != null) {
            boolean anyValid = false;

            for (EquipmentSlot t : EquipmentSlot.values()) {
                ItemStack s = mob.getItemBySlot(t);
                if (!s.isEmpty() && !LootCategory.forItem(s).isNone()) {
                    anyValid = true;
                    break;
                }
            }

            if (!anyValid) {
                Apotheosis.LOGGER.error("Attempted to apply boss gear set " + GearSetRegistry.INSTANCE.getKey(set) + " but it had no valid affix loot items generated.");
            }
        }
        else {
            // We didn't apply an armor set to this invader. We still need to generate an affix item, so we'll pull one at random and equip it.
            ItemStack affixItem = LootController.createRandomLootItem(ctx, rarity);
            LootCategory cat = LootCategory.forItem(affixItem);
            EquipmentSlot slot = Arrays.stream(EquipmentSlot.values())
                .filter(eSlot -> cat.getSlots().test(EquipmentSlotCompat.fromVanilla(eSlot)))
                .findAny()
                .orElse(EquipmentSlot.MAINHAND);
            mob.setItemSlot(slot, affixItem);
        }

        EquipmentSlot[] slots = EquipmentSlot.values();

        EquipmentSlot guaranteed = slots[rand.nextInt(6)];
        int tries = 50;

        ItemStack temp = mob.getItemBySlot(guaranteed);
        while (temp.isEmpty() || LootCategory.forItem(temp) == LootCategories.NONE) {
            guaranteed = slots[rand.nextInt(6)];
            temp = mob.getItemBySlot(guaranteed);

            if (tries-- <= 0) {
                break; // Shouldn't happen, but we can't deadlock here.
            }
        }

        for (EquipmentSlot s : EquipmentSlot.values()) {
            ItemStack stack = mob.getItemBySlot(s);
            if (stack.isEmpty()) {
                continue;
            }

            if (s == guaranteed) {

                boolean cursed = false;
                if (mob.level() instanceof ServerLevelAccessor sl) {
                    ResourceKey<DimensionType> dimId = sl.getLevel().dimensionTypeRegistration().getKey();
                    InvaderSpawnRules rules = sl.registryAccess().lookupOrThrow(Registries.DIMENSION_TYPE).getData(DataMaps.INVADER_SPAWN_RULES, dimId);
                    cursed = (rules == null ? Optional.<Boolean>empty() : rules.cursed()).orElse(AdventureConfig.curseBossItems);
                }

                mob.setDropChance(s, 2F);
                mob.setItemSlot(s, modifyBossItem(stack, mob.getName(), ctx, rarity, stats.enchLevels().primary(), mob.level().registryAccess(), cursed));
                mob.setCustomName(mob.getName().copy().withStyle(Style.EMPTY.withColor(rarity.color())));
            }
            else if (rand.nextFloat() < stats.enchantChance()) {
                enchantBossItem(rand, stack, stats.enchLevels().secondary(), true, mob.level().registryAccess());
                mob.setItemSlot(s, stack);
            }
        }

        mob.getPersistentData().putBoolean(BOSS_KEY, true);
        mob.getPersistentData().putString(RARITY_KEY, RarityRegistry.INSTANCE.getKey(rarity).toString());
        mob.setHealth(mob.getMaxHealth());

        if (AdventureConfig.bossGlowOnSpawn) {
            mob.addEffect(new MobEffectInstance(MobEffects.GLOWING, 3600, 0, true, false));
        }

        this.basicData.appendBonusLoot(mob);
    }

public static void enchantBossItem(RandomSource rand, ItemStack stack, int level, boolean treasure, RegistryAccess reg) {
        Stream<Holder<Enchantment>> available = reg.lookupOrThrow(Registries.ENCHANTMENT).get(EnchantmentTags.ON_MOB_SPAWN_EQUIPMENT).map(HolderSet::stream).orElse(Stream.empty());
        List<EnchantmentInstance> ench = EnchantmentHelper.selectEnchantment(rand, stack, level, available);
        ItemEnchantments.Mutable builder = new ItemEnchantments.Mutable(EnchantmentHelper.getEnchantmentsForCrafting(stack));
        ench.stream().filter(d -> !d.enchantment().is(EnchantmentTags.CURSE)).forEach(i -> builder.upgrade(i.enchantment(), i.level()));
        EnchantmentHelper.setEnchantments(stack, builder.toImmutable());
    }

public static ItemStack modifyBossItem(ItemStack stack, Component bossName, GenContext ctx, LootRarity rarity, int enchLevel, RegistryAccess reg, boolean cursed) {
        RandomSource rand = ctx.rand();
        if (enchLevel > 0) {
            enchantBossItem(rand, stack, enchLevel, true, reg);
        }
        NameHelper.setItemName(rand, stack);
        stack = LootController.createLootItem(stack, LootCategory.forItem(stack), rarity, ctx);

        // Upgrade all affixes on Invader items by 10-25%
        ItemAffixes.Builder builder = stack.getOrDefault(Components.AFFIXES, ItemAffixes.EMPTY).toBuilder();
        for (DynamicHolder<Affix> afx : builder.keySet()) {
            builder.upgrade(afx, Math.min(Affix.STANDARD_MAX_LEVEL, builder.getLevel(afx) + Mth.nextFloat(rand, 0.1F, 0.25F)));
        }
        AffixHelper.setAffixes(stack, builder.build());

        Component bossOwnerName = Component.translatable(NameHelper.ownershipFormat, bossName);
        Component name = AffixHelper.getName(stack);
        if (name != null && name.getContents() instanceof TranslatableContents tc) {
            String oldKey = tc.getKey();
            String newKey = "misc.apotheosis.affix_name.two".equals(oldKey) ? "misc.apotheosis.affix_name.three" : "misc.apotheosis.affix_name.four";
            Object[] newArgs = new Object[tc.getArgs().length + 1];
            newArgs[0] = bossOwnerName;
            for (int i = 1; i < newArgs.length; i++) {
                newArgs[i] = tc.getArgs()[i - 1];
            }
            Component copy = Component.translatable(newKey, newArgs).withStyle(name.getStyle().withItalic(false));

            // We need to ensure things aren't entangled, but we can't otherwise make a deep copy of the TranslatableContents.
            // So... we just serialize the entire thing and deserialize it. Shouldn't be too expensive to run here.
            var rfbb = new RegistryFriendlyByteBuf(Unpooled.buffer(), reg, ConnectionType.NEOFORGE);
            ComponentSerialization.TRUSTED_STREAM_CODEC.encode(rfbb, copy);
            Component deserialized = ComponentSerialization.TRUSTED_STREAM_CODEC.decode(rfbb);

            AffixHelper.setName(stack, deserialized);
        }

        ItemEnchantments.Mutable enchMap = new ItemEnchantments.Mutable(ItemEnchantments.EMPTY);
        for (Object2IntMap.Entry<Holder<Enchantment>> e : EnchantmentHelper.getEnchantmentsForCrafting(stack).entrySet()) {
            if (e.getKey() != null) {
                enchMap.upgrade(e.getKey(), Math.min(ApothicEnchantingCompat.getMaxLevel(e.getKey().value()), e.getIntValue() + rand.nextInt(2)));
            }
        }

        if (cursed) {
            List<Holder.Reference<Enchantment>> curses = reg.lookupOrThrow(Registries.ENCHANTMENT).listElements().filter(e -> e.is(EnchantmentTags.CURSE) && e.is(EnchantmentTags.ON_MOB_SPAWN_EQUIPMENT)).toList();
            if (!curses.isEmpty()) {
                Holder<Enchantment> curse = curses.get(rand.nextInt(curses.size()));
                enchMap.upgrade(curse, Mth.nextInt(rand, 1, ApothicEnchantingCompat.getMaxLevel(curse.value())));
            }
        }

        EnchantmentHelper.setEnchantments(stack, enchMap.toImmutable());
        stack.set(Components.FROM_BOSS, true);
        return stack;
    }

