private static @NotNull Collection<JEIPotionMix> createFromGroup(@NotNull List<ExtendedPotionMix> group) {
        ExtendedPotionMix full = group.stream().filter(mix -> !mix.efficient).findFirst().orElse(group.getFirst());
        ExtendedPotionMix reduced = group.stream().filter(mix -> mix.efficient).findFirst().orElse(null);

        IngredientWithAmounts mix1 = new IngredientWithAmounts(full.reagent1.get(), amounts(full.reagent1Count, reduced == null ? -1 : reduced.reagent1Count));
        IngredientWithAmounts mix2 = new IngredientWithAmounts(full.reagent2.get(), amounts(full.reagent2Count, reduced == null ? -1 : reduced.reagent2Count));

        List<JEIPotionMix> recipes = new ArrayList<>(3);

        var potion = build(full, reduced, Items.POTION, full.input, full.output, mix1, mix2);
        PotionBrewingStepCounter.INSTANCE.addVaporStillRecipe(potion.getPotionInput(), potion.getPotionOutput());
        recipes.add(potion);

        if (full.output.value().getEffects().stream().noneMatch(s -> s.getEffect().value().getCategory() != MobEffectCategory.HARMFUL)) {
            var splash = build(full, reduced, Items.SPLASH_POTION, full.input, full.output, mix1, mix2);
            PotionBrewingStepCounter.INSTANCE.addVaporStillRecipe(splash.getPotionInput(), splash.getPotionOutput());
            recipes.add(splash);

            var lingering = build(full, reduced, Items.LINGERING_POTION, full.input, full.output, mix1, mix2);
            PotionBrewingStepCounter.INSTANCE.addVaporStillRecipe(lingering.getPotionInput(), lingering.getPotionOutput());
            recipes.add(lingering);
        }
        return recipes;
    }

private int resolve(String uid, Set<String> visited) {
        Integer cached = stepCache.get(uid);
        if (cached != null) return cached;
        if (!visited.add(uid)) return Integer.MAX_VALUE;

        Set<String> inputs = inputMap.getOrDefault(uid, Set.of());
        int min = inputs.stream().mapToInt(input -> resolve(input, visited)).min().orElse(Integer.MAX_VALUE);

        int steps = min == Integer.MAX_VALUE ? Integer.MAX_VALUE : min + 1;
        stepCache.put(uid, steps);
        return steps;
    }

private static String getUid(ItemStack stack) {
        var contents = stack.get(DataComponents.POTION_CONTENTS);
        if (contents != null) {
            String itemId = net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString();
            String potionId = contents.potion().map(holder -> holder.unwrapKey().map(key -> key.identifier().toString()).orElse("unknown")).orElse("none");
            return itemId + "/" + potionId;
        }
        return net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString();
    }

@Override
    public void setRecipe(IRecipeLayoutBuilder builder, RecipeHolder<InfuserRecipe> recipe, IFocusGroup focuses) {
        InfuserRecipe value = recipe.value();
        var item1 = builder.addSlot(RecipeIngredientRole.INPUT, 97-6, 33+9-15);
        item1.add(value.ingredient());

        var input1 = builder.addSlot(RecipeIngredientRole.INPUT, 7-6, 16-15);
        if (value.ingredient1().isPresent()) input1.add(value.ingredient1().get());
        var input2 = builder.addSlot(RecipeIngredientRole.INPUT, 29-6, 16-15);
        if (value.ingredient2().isPresent()) input2.add(value.ingredient2().get());
        var input3 = builder.addSlot(RecipeIngredientRole.INPUT, 51-6, 16-15);
        if (value.ingredient3().isPresent()) input3.add(value.ingredient3().get());
        var input4 = builder.addSlot(RecipeIngredientRole.INPUT, 73-6, 16-15);
        if (value.ingredient4().isPresent()) input4.add(value.ingredient4().get());

        var result1 = builder.addSlot(RecipeIngredientRole.OUTPUT, 150-6, 32+9-15);
        Optional<ItemStackTemplate> result = value.result();
        if (result.isPresent()) {
            result1.add(result.get());
        } else {
            if (value.ingredient().isCustom()) {
                ContextMap contextmap = SlotDisplayContext.fromLevel(Objects.requireNonNull(Minecraft.getInstance().level));

                var stacks = value.ingredient().display().resolveForStacks(contextmap);
                for (ItemStack stack : stacks) {
                    var level = stack.getOrDefault(ModDataComponents.PURE_LEVEL, PureLevel.EMPTY);
                    result1.add(PureLevel.pureBlood(stack, Math.min(level.level() + 1, 4)));
                }
            } else {
                value.ingredient().getValues().stream().map(x -> PureLevel.template(x, 0)).forEach(result1::add);
            }
        }

        builder.addSlot(RecipeIngredientRole.OUTPUT, 18-6, 59+9-15).add(value.result1());
        builder.addSlot(RecipeIngredientRole.OUTPUT, 40-6, 59+9-15).add(value.result2());
        builder.addSlot(RecipeIngredientRole.OUTPUT, 62-6, 59+9-15).add(value.result3());
    }

