public static boolean reduceAppliedOilDuration(@NotNull ItemStack stack) {
        return AppliedOilContent.getAppliedOil(stack).map(appliedOil -> {
            int newDuration = appliedOil.duration() - appliedOil.oil().value().getDurationReduction();
            if (newDuration > 0) {
                AppliedOilContent.apply(stack, appliedOil.oil(), newDuration);
                return false;
            } else {
                AppliedOilContent.remove(stack);
                return true;
            }
        }).orElse(true);
    }

public static boolean reduceAppliedOilDuration(@NotNull ItemStack stack, IApplicableOil oil, int durationReduction) {
        return AppliedOilContent.getAppliedOil(stack).filter(s -> s.oil().value() == oil).map(appliedOil -> {
            int newDuration = appliedOil.duration() - durationReduction;
            if (newDuration > 0) {
                AppliedOilContent.apply(stack, appliedOil.oil(), newDuration);
                return false;
            } else {
                AppliedOilContent.remove(stack);
                return true;
            }
        }).orElse(true);
    }

public static @NotNull Optional<StructureStart> getStructureStartAt(Level level, @NotNull BlockPos pos, @NotNull TagKey<Structure> structureTag) {
        if (level instanceof ServerLevel serverLevel && serverLevel.isLoaded(pos)) {
            Registry<Structure> registry = serverLevel.registryAccess().lookupOrThrow(Registries.STRUCTURE);
            return serverLevel.structureManager().startsForStructure(ChunkPos.containing(pos), structure -> {
                return registry.get(registry.getId(structure)).map(a -> a.is(structureTag)).orElse(false);
            }).stream().findFirst();
        }
        return Optional.empty();
    }

