@Override
    protected InteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hitResult) {
        if (state.is(ModBlocks.DARK_STONE_BRICKS) && stack.get(ModDataComponents.BOTTLE_BLOOD) != null) {
            boolean isCreative = player.getAbilities().instabuild;
            boolean isStacked = stack.getCount() > 1;

            ItemStack bottle = (!isCreative && isStacked) ? stack.split(1) : stack;
            int blood = bottle.getOrDefault(ModDataComponents.BOTTLE_BLOOD, new BottleBlood(0)).blood();

            if (blood >= 1) {
                level.setBlockAndUpdate(pos, ModBlocks.BLOODY_DARK_STONE_BRICKS.get().defaultBlockState());
                level.playSound(null, pos, SoundEvents.SCULK_BLOCK_SPREAD, SoundSource.BLOCKS, 4.0F, 1.0F);

                if (!isCreative) {
                    int bloodLeft = blood - 1;
                    ItemStack resultBottle;

                    if (bloodLeft <= 0 && ModConfig.common().autoConvertGlassBottles.get()) {
                        resultBottle = new ItemStack(Items.GLASS_BOTTLE);
                    } else {
                        resultBottle = bottle;
                        resultBottle.set(ModDataComponents.BOTTLE_BLOOD, new BottleBlood(bloodLeft));
                    }

                    if (isStacked) {
                        if (!player.addItem(resultBottle)) {
                            player.drop(resultBottle, false);
                        }
                    } else if (bloodLeft <= 0 && ModConfig.common().autoConvertGlassBottles.get()) {
                        player.setItemInHand(hand, resultBottle);
                    }
                }

                return InteractionResult.SUCCESS_SERVER;
            }
        }

        return super.useItemOn(stack, state, level, pos, player, hand, hitResult);
    }

@Override
    protected InteractionResult useWithoutItem(BlockState state, Level level, BlockPos pos, Player player, BlockHitResult hitResult) {
        try (var transaction = Transaction.openRoot()) {
            var resource = Optional.ofNullable(level.getCapability(Capabilities.Item.BLOCK, pos, hitResult.getDirection())).map(handler -> {
                var item = ResourceHandlerUtil.extractFirst(handler, x -> true, 1, transaction);
                if (item == null || item.isEmpty()) {
                    return null;
                }
                return item.resource().toStack(item.amount());
            }).orElse(ItemStack.EMPTY);
            if (resource.getItem() instanceof VampireSwordItem vampireSwordItem) {
                if (vampireSwordItem.isFullyCharged(resource)) {
                    vampireSwordItem.tryName(resource, player);
                    player.awardStat(ModStats.ITEMS_FILLED_ON_BLOOD_PEDESTAL.get());
                }
            }

            if (resource.isEmpty()) {
                return InteractionResult.PASS;
            }

            ItemResource itemResource = ItemResource.of(resource);
            PlayerInventoryWrapper playerInventoryWrapper = PlayerInventoryWrapper.of(player);
            int insert = playerInventoryWrapper.getHandSlot(InteractionHand.MAIN_HAND).insert(itemResource, 1, transaction);
            if (insert == 0) {
                playerInventoryWrapper.drop(itemResource, 1, true, false, transaction);
            }
            transaction.commit();
            player.awardStat(ModStats.INTERACT_WITH_BLOOD_PEDESTAL.get());
            return InteractionResult.SUCCESS;
        }
    }

@Override
    public InteractionResult useWithoutItem(BlockState blockState, Level world, final BlockPos pos, Player player, BlockHitResult rayTraceResult) {
        if (world.isClientSide()) return InteractionResult.SUCCESS;
        if (HunterPlayer.get(player).getLevel() == 0) {
            player.sendOverlayMessage(Component.translatable("message.vampirism.tent.cant_use"));
            return InteractionResult.SUCCESS;
        }

        player.awardStat(ModStats.INTERACT_WITH_TENT.get());
        BedRule bedrule = world.environmentAttributes().getValue(EnvironmentAttributes.BED_RULE, pos);
        if (bedrule.explodes()) {
            world.removeBlock(pos, false);
            BlockPos blockpos = pos.relative(blockState.getValue(HORIZONTAL_FACING).getOpposite());
            if (world.getBlockState(blockpos).is(this)) {
                world.removeBlock(blockpos, false);
            }

            Vec3 vec3 = pos.getCenter();
            world.explode(null, world.damageSources().badRespawnPointExplosion(vec3), null, vec3, 5.0F, true, Level.ExplosionInteraction.BLOCK);
            return InteractionResult.SUCCESS;
        } else if (blockState.getValue(OCCUPIED)) {
            player.sendOverlayMessage(Component.translatable("message.vampirism.tent.occupied"));
            return InteractionResult.SUCCESS;
        } else {
            BlockState targetState = blockState;
            BlockPos targetPos = pos;
            Direction thisFacing = blockState.getValue(FACING);
            int thisPos = blockState.getValue(POSITION);
            if (thisPos != 0) {
                BlockPos main = switch (thisPos) {
                    case 1 -> pos.relative(thisFacing.getClockWise());
                    case 2 -> pos.relative(thisFacing.getOpposite()).relative(thisFacing.getClockWise());
                    case 3 -> pos.relative(thisFacing);
                    default -> null;
                };
                if (main != null) {
                    targetState = world.getBlockState(main);
                    targetPos = main;
                }
            }
            BlockState finalTargetState = targetState;
            BlockPos finalTargetPos = targetPos;
            player.startSleepInBed(finalTargetPos).ifLeft(sleepResult1 -> {
                if (sleepResult1.message() != null) {
                    player.sendOverlayMessage(sleepResults.getOrDefault(sleepResult1, sleepResult1.message()));
                }
            }).ifRight(u -> {
                this.setBedOccupied(finalTargetState, world, finalTargetPos, null, true);
                setTentSleepPosition(player, finalTargetPos, finalTargetState.getValue(POSITION), finalTargetState.getValue(HORIZONTAL_FACING));
            });
            return InteractionResult.SUCCESS;
        }
    }

