@Override
	protected InteractionResult useWithoutItem(BlockState state, Level level, BlockPos pos, Player player, BlockHitResult hitResult) {
		if (level.getBlockEntity(pos) instanceof SkullCandleBlockEntity sc && player.isSecondaryUseActive() && state.getValue(CANDLES) > 0) {
			int newCandleAmount = state.getValue(CANDLES) - 1;
			if (newCandleAmount > 0) {
				level.setBlockAndUpdate(pos, state.setValue(CANDLES, newCandleAmount));
				sc.setCandleInfo(new SkullCandles(sc.getCandleInfo().color(), newCandleAmount));
				sc.setChanged();
			} else {
				boolean wall = state.getBlock() instanceof WallSkullCandleBlock;
				Block newBlock = getNoCandleSkull(wall);
				if (newBlock != null) {
					DataComponentMap components = sc.components();
                    BlockState newState;
                    if (wall) {
                        newState = newBlock.defaultBlockState().setValue(WallSkullBlock.FACING, state.getValue(WallSkullCandleBlock.FACING));
                    } else {
                        newState = newBlock.defaultBlockState().setValue(SkullBlock.ROTATION, state.getValue(SkullCandleBlock.ROTATION));
                    }
                    level.setBlockAndUpdate(pos, newState);
                    level.setBlockEntity(new SkullBlockEntity(pos, newState));
                    if (level.getBlockEntity(pos) instanceof SkullBlockEntity sc1) sc1.setComponents(components);
				}
			}
			level.playSound(null, pos, SoundEvents.CANDLE_BREAK, SoundSource.BLOCKS, 1.0F, 1.0F);
			level.getLightEngine().checkBlock(pos);
			ItemStack candle = new ItemStack(candleColorToCandle(CandleColors.colorFromInt(sc.getCandleInfo().color())));
			if (player.hasInfiniteMaterials()) {
				if (!player.getInventory().contains(candle)) {
					player.getInventory().add(candle);
				}
			} else {
				InventoryUtil.giveItemToPlayer(player, candle);
			}
			return InteractionResult.SUCCESS;
		}
		return super.useWithoutItem(state, level, pos, player, hitResult);
	}

@Override
	protected InteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult result) {
		if (stack.is(ItemTags.CANDLES) || player.isShiftKeyDown()) {
			if (level.getBlockEntity(pos) instanceof CandelabraBlockEntity candelabra) {
				int i = this.getSlot(state.getValue(FACING), result.getLocation().subtract(result.getBlockPos().getX(), result.getBlockPos().getY(), result.getBlockPos().getZ()));
				if (state.getValue(CANDLES.get(i)) && player.isShiftKeyDown()) {
					ItemStack itemstack = new ItemStack(candelabra.removeCandle(i));
					level.playSound(null, pos, SoundEvents.CANDLE_PLACE, SoundSource.BLOCKS, 1.0F, level.getRandom().nextFloat() * 0.1F + 0.9F);
					if (player.hasInfiniteMaterials()) {
						if (!player.getInventory().contains(itemstack)) {
							player.getInventory().add(itemstack);
						}
					} else {
						InventoryUtil.giveItemToPlayer(player, itemstack);
					}
					level.gameEvent(player, GameEvent.BLOCK_CHANGE, pos);
					return InteractionResult.SUCCESS;
				} else if (!state.getValue(CANDLES.get(i))) {
					if (stack.is(ItemTags.CANDLES) && stack.getItem() instanceof BlockItem block) {
						if (!level.isClientSide()) {
							player.awardStat(Stats.ITEM_USED.get(stack.getItem()));
							candelabra.setCandle(i, block.getBlock());
							level.playSound(null, pos, SoundEvents.CANDLE_PLACE, SoundSource.BLOCKS, 1.0F, level.getRandom().nextFloat() * 0.1F + 0.9F);
							stack.consume(1, player);
						}
						return InteractionResult.SUCCESS;
					}
				}
				return InteractionResult.CONSUME;
			}
		} else if (stack.is(Tags.Items.DUSTS_REDSTONE) && state.getValue(LIGHTING) == Lighting.NORMAL) {
			level.setBlockAndUpdate(pos, state.setValue(LIGHTING, Lighting.DIM));
			stack.consume(1, player);
			level.playSound(null, pos, TFSounds.CANDELABRA_LIGHT.get(), SoundSource.BLOCKS, 1.0F, level.getRandom().nextFloat() * 0.1F + 0.9F);
			if (level.isClientSide()) {
				this.eruptFlameParticles(TFParticleType.DIM_FLAME.get(), level, pos, state);
			}
			return InteractionResult.SUCCESS;
		} else if ((stack.is(TFItemTags.SCEPTERS) || stack.is(TFItems.EXANIMATE_ESSENCE)) && (state.getValue(LIGHTING) == Lighting.NORMAL || state.getValue(LIGHTING) == Lighting.NONE) && getCandleCount(state) > 0) {
			level.setBlockAndUpdate(pos, state.setValue(LIGHTING, Lighting.OMINOUS));
			level.playSound(null, pos, TFSounds.CANDELABRA_OMINOUS.get(), SoundSource.BLOCKS, 1.0F, level.getRandom().nextFloat() * 0.1F + 0.9F);
			if (level.isClientSide()) {
				this.eruptFlameParticles(TFParticleType.OMINOUS_FLAME.get(), level, pos, state);
			}
			return InteractionResult.SUCCESS;
		}
		return this.tryLightCandles(stack, state, level, pos, player);
	}

@Override
	protected InteractionResult useWithoutItem(BlockState state, Level level, BlockPos pos, Player player, BlockHitResult hit) {
		ItemStack experStack = new ItemStack(TFItems.EXPERIMENT_115.get());
		FoodProperties props = experStack.get(DataComponents.FOOD);
		Consumable consumable = experStack.getOrDefault(DataComponents.CONSUMABLE, Consumables.DEFAULT_FOOD);
		if (props != null && consumable.canConsume(player, experStack.copy())) {
			props.onConsume(level, player, experStack.copy(), consumable);
			consumable.onConsume(level, player, experStack.copy());
			int i = state.getValue(BITES_TAKEN);

			if (i < 7) {
				level.setBlock(pos, state.setValue(BITES_TAKEN, i + 1), Block.UPDATE_ALL);
			} else {
				level.removeBlock(pos, false);
			}

			if (player instanceof ServerPlayer) {
				CriteriaTriggers.CONSUME_ITEM.trigger((ServerPlayer) player, experStack);
				player.awardStat(Stats.ITEM_USED.get(experStack.getItem()));
				player.awardStat(TFStats.E115_SLICES_EATEN.get());

			}

			return InteractionResult.SUCCESS;
		}
		return InteractionResult.PASS;
	}

