@PostConstruct
	private void setup() {
		NeoForge.EVENT_BUS.addListener(this::updateShields);
		NeoForge.EVENT_BUS.addListener(this::updatePlayerCaps);
		NeoForge.EVENT_BUS.addListener(this::absorbShieldHits);
		NeoForge.EVENT_BUS.addListener(this::spawnInTFIfNecessary);
		NeoForge.EVENT_BUS.addListener(this::playerLogsIn);
	}

private void updateShields(EntityTickEvent.Post event) {
		if (event.getEntity() instanceof LivingEntity living && !living.level().isClientSide() && living.hasData(TFDataAttachments.FORTIFICATION_SHIELDS)) {
			event.getEntity().getData(TFDataAttachments.FORTIFICATION_SHIELDS).tick(living);
		}
	}

private void updatePlayerCaps(PlayerTickEvent.Post event) {
		if (event.getEntity().getData(TFDataAttachments.FEATHER_FAN)) {
			event.getEntity().setIgnoreFallDamageFromCurrentImpulse(true, event.getEntity().position());
			event.getEntity().currentImpulseImpactPos = event.getEntity().position();

			if (event.getEntity().onGround() || event.getEntity().isSwimming() || event.getEntity().isInWater()) {
				event.getEntity().setData(TFDataAttachments.FEATHER_FAN, false);
			}
		}
		event.getEntity().getData(TFDataAttachments.YETI_THROWING).tick(event.getEntity());
		event.getEntity().getData(TFDataAttachments.TF_PORTAL_COOLDOWN).tick(event.getEntity());
	}

private void absorbShieldHits(LivingIncomingDamageEvent event) {
		LivingEntity living = event.getEntity();
		// shields
		if (!living.level().isClientSide() && !event.getSource().is(DamageTypeTags.BYPASSES_ARMOR)) {
            FortificationShieldAttachment attachment = living.getData(TFDataAttachments.FORTIFICATION_SHIELDS);
			if (attachment.shieldsLeft() > 0) {
				if (living.invulnerableTime <= 0) {
					attachment.breakShield(living, false);
					FortificationShieldAttachment.addShieldBreakParticles(event.getSource(), living);
					living.invulnerableTime = 20; //invulnerableDuration was only a static constant.
				}
				event.setCanceled(true);
			}
		}
	}

private void spawnInTFIfNecessary(PlayerEvent.PlayerRespawnEvent event) {
		if (!(event.getEntity() instanceof ServerPlayer serverPlayer)) return;

		if (serverPlayer.getRespawnConfig() == null) {
			newSpawnInTwilightForest(serverPlayer);
		}
	}

public void playerLogsIn(PlayerEvent.PlayerLoggedInEvent event) {
		if (event.getEntity().level().isClientSide() || !(event.getEntity() instanceof ServerPlayer player))
			return;
		dataFixLegacyBanish(player);
		if (!player.hasData(TFDataAttachments.BANISHED_TO_TWILIGHT_FOREST))
			newSpawnInTwilightForest(player);
	}

private static void newSpawnInTwilightForest(ServerPlayer player) {
		if (!TFConfig.newPlayersSpawnInTF)
			return;
		ServerLevel level = player.level().getServer().getLevel(TFDimension.DIMENSION_KEY);
		if (level == null)
			return;

		BlockPos newDefaultSpawn = level.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, player.blockPosition());

		player.teleport(TFConfig.portalForNewPlayerSpawn ?
			TFTeleporter.createTransition(player, level, newDefaultSpawn, true) :
			NoReturnTeleporter.createNoPortalTransition(level, player, newDefaultSpawn));
		ServerPlayer.RespawnConfig newSpawn = new ServerPlayer.RespawnConfig(
			LevelData.RespawnData.of(TFDimension.DIMENSION_KEY, newDefaultSpawn, player.getYRot(), player.getXRot()), true);
		player.setRespawnPosition(newSpawn, false);

		player.setData(TFDataAttachments.BANISHED_TO_TWILIGHT_FOREST, Unit.INSTANCE);
	}

private static void dataFixLegacyBanish(ServerPlayer player) {
		CompoundTag tagCompound = player.getPersistentData();
		if (!tagCompound.contains(Player.PERSISTED_NBT_TAG))
			return;
		CompoundTag playerData = tagCompound.getCompoundOrEmpty(Player.PERSISTED_NBT_TAG);
		if (!playerData.contains("twilightforest_banished"))
			return;

		playerData.remove("twilightforest_banished");
		tagCompound.put(Player.PERSISTED_NBT_TAG, playerData);

		if (player.hasData(TFDataAttachments.BANISHED_TO_TWILIGHT_FOREST))
			return;

		player.setData(TFDataAttachments.BANISHED_TO_TWILIGHT_FOREST, Unit.INSTANCE);
	}

@PostConstruct
	private void setup() {
		NeoForge.EVENT_BUS.addListener(EventPriority.HIGHEST, this::applyCharmOfLife);
		NeoForge.EVENT_BUS.addListener(EventPriority.HIGH, this::applyKeepingAndCasket);
		NeoForge.EVENT_BUS.addListener(this::returnItemsOnRespawn);
	}

private void applyCharmOfLife(LivingDeathEvent event) {
		LivingEntity living = event.getEntity();

		// Ensure our player is real and in survival before attempting anything
		if (event.isCanceled() || living.level().isClientSide() || !(living instanceof Player player) || living instanceof FakePlayer ||
				player.isCreative() || player.isSpectator()) return;

		if (handleCharmOfLife(player)) event.setCanceled(true); // Executes if the player had charms
	}

private void applyKeepingAndCasket(LivingDeathEvent event) {
		LivingEntity living = event.getEntity();

		// Ensure our player is real and in survival before attempting anything
		if (event.isCanceled() || living.level().isClientSide() || !(living instanceof Player player) || living instanceof FakePlayer ||
				player.isCreative() || player.isSpectator()) return;

		if (living.level() instanceof ServerLevel server && !server.getGameRules().get(GameRules.KEEP_INVENTORY)) {
			// Did the player recover? No? Let's give them their stuff based on the keeping charms
			handleCharmOfKeeping(player);

			// Then let's store the rest of their stuff in the casket
			stockKeepsakeCasket(player);
		}
	}

private void returnItemsOnRespawn(PlayerEvent.PlayerRespawnEvent event) {
		if (!(event.getEntity() instanceof ServerPlayer serverPlayer)) return;
		if (!event.isEndConquered()) {
			returnStoredItems(serverPlayer);
		}
	}

private static boolean handleCharmOfLife(Player player) {
		boolean charm2 = TFItemStackUtils.consumeInventoryItem(player, TFItems.CHARM_OF_LIFE_2.get(), getPlayerData(player), false) || hasCharmCurio(TFItems.CHARM_OF_LIFE_2.get(), player, false);
		boolean charm1 = !charm2 && (TFItemStackUtils.consumeInventoryItem(player, TFItems.CHARM_OF_LIFE_1.get(), getPlayerData(player), false) || hasCharmCurio(TFItems.CHARM_OF_LIFE_1.get(), player, false));

		if (charm2 || charm1) {
			if (charm1) {
				player.setHealth(8);
				player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 100, 0));
			}

			if (charm2) {
				player.setHealth(player.getMaxHealth());

				player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 600, 3));
				player.addEffect(new MobEffectInstance(MobEffects.RESISTANCE, 600, 0));
				player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 600, 0));
			}

			if (player instanceof ServerPlayer serverPlayer) {
				PacketDistributor.sendToPlayer(serverPlayer, new SpawnCharmPacket(new ItemStack(charm1 ? TFItems.CHARM_OF_LIFE_1.get() : TFItems.CHARM_OF_LIFE_2.get()), TFSounds.CHARM_LIFE.getKey()));
				serverPlayer.awardStat(TFStats.LIFE_CHARMS_ACTIVATED.get());
			}

			return true;
		}

		return false;
	}

private static void handleCharmOfKeeping(Player player) {
		// Create an additional inventory to hold our stored items
		Inventory inventory = player.getInventory();
		Inventory keepInventory = new Inventory(player, new EntityEquipment());

		if (!applyCharm(TFItems.CHARM_OF_KEEPING_3, keepInventory, player, 0, Inventory.INVENTORY_SIZE)) {
			if (!applyCharm(TFItems.CHARM_OF_KEEPING_2, keepInventory, player, 0, Inventory.SELECTION_SIZE)) {
				int selected = inventory.getSelectedSlot();
				if (Inventory.isHotbarSlot(selected)) {
					applyCharm(TFItems.CHARM_OF_KEEPING_1, keepInventory, player, selected, selected + 1);
				}
			}
		}

		// Keep all items in the KEPT_ON_DEATH tag
		for (int slot = 0; slot < inventory.getContainerSize(); slot++) {
			keepTaggedItem(inventory, keepInventory, slot);
		}

		// Save our data to the attachment
		CharmAttachment attachment = CharmAttachment.fromInventory(keepInventory);
		if (attachment.isEmpty()) {
			player.removeData(TFDataAttachments.CHARM_INVENTORY);
		} else {
			player.setData(TFDataAttachments.CHARM_INVENTORY, attachment);
		}
	}

private static void keepTaggedItem(Inventory inventory, Inventory keepInventory, int slot) {
		ItemStack stack = inventory.getItem(slot);
		if (stack.is(TFItemTags.KEPT_ON_DEATH)) {
			keepInventory.setItem(slot, stack.copy());
			inventory.setItem(slot, ItemStack.EMPTY);
		}
	}

private static boolean applyCharm(DeferredItem<Item> charm, Inventory keptInventory, Player player, int fromSlot, int toSlot) {
		Inventory inventory = player.getInventory();
		List<ItemStack> mergedCheck = new ArrayList<>(inventory.getNonEquipmentItems().subList(fromSlot, toSlot));

		// Armor and offhand are always kept by a Charm of Keeping
		for (int slot : CHARM_EQUIPMENT_SLOTS) {
			mergedCheck.add(inventory.getItem(slot));
		}

		// Filter out the charm so it does not count towards keeping items if it is the only thing being held
		if (mergedCheck.stream().filter(stack -> !stack.is(charm)).allMatch(ItemStack::isEmpty)) {
			return false;
		}

		// Stop operation if there is no charm present
		if (!TFItemStackUtils.consumeInventoryItem(player, charm, getPlayerData(player), true) && !hasCharmCurio(charm.value(), player, true)) {
			return false;
		}

		boolean skipCasketCheck = charm == TFItems.CHARM_OF_KEEPING_3;
		boolean keptCasket = false;

		for (int slot = fromSlot; slot < toSlot; slot++) {
			keptCasket = keepItem(inventory, keptInventory, slot, skipCasketCheck, keptCasket);
		}

		for (int slot : CHARM_EQUIPMENT_SLOTS) {
			keptCasket = keepItem(inventory, keptInventory, slot, skipCasketCheck, keptCasket);
		}

		return true;
	}

private static boolean keepItem(Inventory inventory, Inventory keptInventory, int slot, boolean skipCasketCheck, boolean keptCasket) {
		ItemStack item = inventory.getItem(slot).copy();
		if (skipCasketCheck || !item.is(TFItems.KEEPSAKE_CASKET) || keptCasket) {
			keptInventory.setItem(slot, item);
			inventory.setItem(slot, ItemStack.EMPTY);
			return keptCasket;
		}

		if (item.getCount() > 1) {
			item.shrink(1);
			keptInventory.setItem(slot, item);
			inventory.setItem(slot, item.copyWithCount(1));
		}

		return true;
	}

private static void stockKeepsakeCasket(Player player) {
		// Make sure we are still actually holding onto items before trying to place a casket
		if (player.getInventory().hasAnyMatching(stack -> !stack.isEmpty() && !stack.is(TFItems.KEEPSAKE_CASKET))) {
			boolean casketConsumed = TFItemStackUtils.consumeInventoryItem(player, TFBlocks.KEEPSAKE_CASKET, getPlayerData(player), false);

			if (!casketConsumed)
				return;

			Level level = player.level();
			BlockPos.MutableBlockPos pos = player.blockPosition().mutable();

			if (pos.getY() < level.dimensionType().minY() + 2) {
				pos.setY(level.dimensionType().minY() + 2);
			} else {
				int logicalHeight = player.level().dimensionType().logicalHeight();

				if (pos.getY() > logicalHeight) {
					pos.setY(logicalHeight - 1);
				}
			}

			pos.move(0, -1, 0);

			do {
				pos.move(0, 1, 0);
			} while (!level.getBlockState(pos).canBeReplaced());

			BlockPos immutablePos = pos.immutable();
			FluidState fluidState = level.getFluidState(immutablePos);

			int damage = getPlayerData(player).getInt(CASKET_DAMAGE_TAG).orElse(0);
			BlockState setState = TFBlocks.KEEPSAKE_CASKET.get().defaultBlockState()
				.setValue(BlockLoggingEnum.MULTILOGGED, BlockLoggingEnum.getFromFluid(fluidState.getType()))
				.setValue(KeepsakeCasketBlock.BREAKAGE, damage)
				.setValue(KeepsakeCasketBlock.FACING, Direction.from2DDataValue(level.getRandom().nextInt(4)));

			if (player.getRandom().nextFloat() <= 0.15F) {
				if (damage >= 2) {
					setState = TFBlocks.SKULL_CHEST.get().withPropertiesOf(setState);
					TwilightForestMod.LOGGER.debug("{}'s Casket damage value was too high, placing Skull Chest instead", player.getName().getString());
				} else {
					damage = damage + 1;
					setState = TFBlocks.KEEPSAKE_CASKET.get().withPropertiesOf(setState).setValue(KeepsakeCasketBlock.BREAKAGE, damage);
					TwilightForestMod.LOGGER.debug("{}'s Casket was randomly damaged, applying new damage", player.getName().getString());
				}
			}

			if (!level.setBlockAndUpdate(immutablePos, setState)) {
				TwilightForestMod.LOGGER.error("Could not place Keepsake Casket at {}", pos);
				return;
			}

			if (!(level.getBlockEntity(immutablePos) instanceof SkullChestBlockEntity casket)) {
				TwilightForestMod.LOGGER.error("Failed to set Keepsake Casket data at {}", pos);
				return;
			}

			if (TFConfig.casketUUIDLocking) {
				// Make it so only the player who died can open the chest if our config allows us
				casket.owner = ResolvableProfile.createResolved(player.getGameProfile());
			} else {
				casket.owner = null;
			}

			// Some names are way too long for the casket so we'll cut them down
			String modifiedName = player.getName().getString().substring(0, Math.min(12, player.getName().getString().length()));
			casket.name = (Component.literal(modifiedName + "'s " + (level.getRandom().nextInt(1000) == 0 ? "Costco Casket" : casket.getDisplayName().getString())));

			int casketCapacity = casket.getContainerSize();
			List<ItemStack> list = new ArrayList<>(casketCapacity);
			NonNullList<ItemStack> filler = NonNullList.withSize(4, ItemStack.EMPTY);

			// Let's add our inventory exactly how it was on us.
			list.addAll(TFItemStackUtils.sortArmorForCasket(player));
			list.addAll(filler);
			list.add(player.getInventory().getItem(Inventory.SLOT_OFFHAND));
			list.addAll(TFItemStackUtils.sortInvForCasket(player));

			for (int slot = 0; slot < player.getInventory().getContainerSize(); slot++) {
				player.getInventory().setItem(slot, ItemStack.EMPTY);
			}

			casket.setItems(NonNullList.of(ItemStack.EMPTY, list.toArray(new ItemStack[casketCapacity])));
			getPlayerData(player).remove(CASKET_DAMAGE_TAG);
		} else {
			// Inventory is empty minus the casket: put the casket into the kept inventory
			CharmAttachment attachment = player.hasData(TFDataAttachments.CHARM_INVENTORY) ? player.getData(TFDataAttachments.CHARM_INVENTORY) : new CharmAttachment();
			Inventory keptInventory = attachment.toInventory(player);
			boolean keptCasket = false;

			for (int slot = 0; slot < player.getInventory().getContainerSize(); slot++) {
				ItemStack stack = player.getInventory().getItem(slot);
				if (stack.is(TFItems.KEEPSAKE_CASKET) && keptInventory.add(stack.copy())) {
					player.getInventory().setItem(slot, ItemStack.EMPTY);
					keptCasket = true;
				}
			}

			if (keptCasket) {
				player.setData(TFDataAttachments.CHARM_INVENTORY, CharmAttachment.fromInventory(keptInventory));
			}
		}
	}

private static void returnStoredItems(Player player) {
		TwilightForestMod.LOGGER.debug("Player {} ({}) respawned and received items held in storage", player.getName().getString(), player.getUUID());

		if (!player.level().isClientSide() && player.hasData(TFDataAttachments.CHARM_INVENTORY)) {
			CharmAttachment attachment = player.getData(TFDataAttachments.CHARM_INVENTORY);
			player.removeData(TFDataAttachments.CHARM_INVENTORY);
			if (!attachment.isEmpty()) {
				attachment.applyTo(player.getInventory());
			}
		}

		CompoundTag playerData = getPlayerData(player);
		if (playerData.contains(CONSUMED_CHARM_TAG)) {
			if (player instanceof ServerPlayer serverPlayer) {
				ItemStack charm = ItemStack.CODEC
					.parse(player.registryAccess().createSerializationContext(NbtOps.INSTANCE), playerData.get(CONSUMED_CHARM_TAG))
					.resultOrPartial(TwilightForestMod.LOGGER::error)
					.orElse(ItemStack.EMPTY);
				if (!charm.isEmpty()) {
					PacketDistributor.sendToPlayer(serverPlayer, new SpawnCharmPacket(charm, TFSounds.CHARM_KEEP.getKey()));
				}
				serverPlayer.awardStat(TFStats.KEEPING_CHARMS_ACTIVATED.get());
			}
			getPlayerData(player).remove(CONSUMED_CHARM_TAG);
		}
	}

public static CompoundTag getPlayerData(Player player) {
		if (!player.getPersistentData().contains(Player.PERSISTED_NBT_TAG)) {
			player.getPersistentData().put(Player.PERSISTED_NBT_TAG, new CompoundTag());
		}
		return player.getPersistentData().getCompound(Player.PERSISTED_NBT_TAG).get();
	}

private static boolean hasCharmCurio(Item item, Player player, boolean saveItemToTag) {
		if (ModList.get().isLoaded("curios")) {
			return CuriosCompat.findAndConsumeCurio(item, player, saveItemToTag);
		}

		return false;
	}

private void removeCastleTextIfAttacked(AttackEntityEvent event) {
		// For clearing our Display text entities at the Final Castle Gazebo, there's no other way to remove them otherwise
		// The tag distinguishes our Interaction entities from other Mods' utilization
		if (event.getTarget().level() instanceof ServerLevel level && event.getTarget() instanceof Interaction interaction && interaction.entityTags().contains(FinalCastleBossGazeboComponent.INTERACTION_TAG)) {
			AABB bounds = interaction.getBoundingBox();
			level.getEntities(interaction, bounds, e -> e instanceof Display).forEach(Entity::discard);
			interaction.discard();
		}
	}

@SuppressWarnings("UnusedReturnValue")
	private static boolean checkForLockedStructuresSendPacket(Player player, ServerLevel world) {
		ChunkPos chunkPlayer = player.chunkPosition();
		return LandmarkUtil.locateNearestLandmarkStart(world, chunkPlayer.x(), chunkPlayer.z()).map(structureStart -> {
			if (structureStart.getStructure() instanceof AdvancementLockedStructure advancementLockedStructure && !advancementLockedStructure.doesPlayerHaveRequiredAdvancements(player)) {
				List<Pair<BoundingBox, Boolean>> boundingBoxesData = structureStart.getPieces().stream()
					.map(piece -> Pair.of(isPieceProtected(piece) ? piece.getBoundingBox().inflatedBy(4) : piece.getBoundingBox(), isPieceProtected(piece)))
					.toList();

				sendStructureProtectionPacket(player, boundingBoxesData);
				return true;
			}

			sendAllClearPacket(player);
			return false;
		}).orElse(false);
	}

private void checkForPortalCreation(ServerPlayer player, ServerLevel level, float rangeToCheck, int checkInterval) {
		if (level.dimension().identifier().equals(Identifier.parse(TFConfig.originDimension))
			|| TFDimension.isTwilightPortalDestination(level)
			|| TFConfig.allowPortalsInOtherDimensions) {

			List<ItemEntity> itemList = level.getEntitiesOfClass(ItemEntity.class, player.getBoundingBox().inflate(rangeToCheck));
			ItemEntity qualified = null;

			for (ItemEntity entityItem : itemList) {
				if (entityItem.getItem().is(TFItemTags.PORTAL_ACTIVATOR) &&
					TFBlocks.TWILIGHT_PORTAL.get().canFormPortal(level.getBlockState(entityItem.blockPosition())) &&
					Objects.equals(entityItem.getOwner(), player)) {

					qualified = entityItem;
					break;
				}
			}

			if (qualified == null) return;

			if (!player.isCreative() && !player.isSpectator() && TFConfig.getPortalLockingAdvancement(player) != null) {
				AdvancementHolder requirement = PlayerHelper.getAdvancement(player, Objects.requireNonNull(TFConfig.getPortalLockingAdvancement(player)));
				if (requirement != null && !PlayerHelper.doesPlayerHaveRequiredAdvancement(player, requirement)) {
					player.sendOverlayMessage(TFPortalBlock.PORTAL_UNWORTHY);

					if (!TFPortalBlock.isPlayerNotifiedOfRequirement(player)) {
						// .doesPlayerHaveRequiredAdvancement null-checks already, so we can skip null-checking the `requirement`
						DisplayInfo info = requirement.value().display().orElse(null);
						PacketDistributor.sendToPlayer(player, info == null ? new MissingAdvancementToastPacket(net.minecraft.network.chat.Component.translatable("twilightforest.ui.advancement.no_title"), new ItemStackTemplate(TFBlocks.TWILIGHT_PORTAL_MINIATURE_STRUCTURE.get().asItem())) : new MissingAdvancementToastPacket(info.getTitle(), info.getIcon()));

						TFPortalBlock.playerNotifiedOfRequirement(player);
					}

					return; // Item qualifies, but the player doesn't
				}
			}

			if (TFBlocks.TWILIGHT_PORTAL.get().tryToCreatePortal(level, qualified.blockPosition(), qualified, player))
				TFAdvancements.MADE_TF_PORTAL.get().trigger(player);
			else
				PacketDistributor.sendToPlayersTrackingEntity(qualified, new CreatePortalItemEmitterPacket(qualified.getId(), checkInterval));

		}
	}

private void onEnderBowHit(ProjectileImpactEvent evt) {
		Projectile arrow = evt.getProjectile();
		if (arrow.getOwner() instanceof Player player
			&& evt.getRayTraceResult() instanceof EntityHitResult result
			&& result.getEntity() instanceof LivingEntity living
			&& arrow.getOwner() != result.getEntity() && !result.getEntity().is(Tags.EntityTypes.BOSSES)) {

			if (arrow.getPersistentData().contains(EnderBowItem.KEY)) {
				double sourceX = player.getX(), sourceY = player.getY(), sourceZ = player.getZ();
				float sourceYaw = player.getYRot(), sourcePitch = player.getXRot();
				@Nullable Entity playerVehicle = player.getVehicle();

				player.setYRot(living.getYRot());
				player.teleportTo(living.getX(), living.getY(), living.getZ());
				player.invulnerableTime = 40;
				player.level().broadcastEntityEvent(player, (byte) 46);
				if (living.isPassenger() && living.getVehicle() != null) {
					player.startRiding(living.getVehicle(), true, true);
					living.stopRiding();
				}
				player.playSound(SoundEvents.CHORUS_FRUIT_TELEPORT, 1.0F, 1.0F);

				living.setYRot(sourceYaw);
				living.setXRot(sourcePitch);
				living.teleportTo(sourceX, sourceY, sourceZ);
				living.level().broadcastEntityEvent(player, (byte) 46);
				if (playerVehicle != null) {
					living.startRiding(playerVehicle, true, true);
					player.stopRiding();
				}
				living.playSound(SoundEvents.CHORUS_FRUIT_TELEPORT, 1.0F, 1.0F);
			}
		}
	}

