public static void loadNoClear(HolderLookup.Provider registryAccess, ListTag tag, Inventory inventory) {
		List<ItemStack> blockedItems = new ArrayList<>();

		for (int i = 0; i < tag.size(); ++i) {
			CompoundTag compoundtag = tag.getCompoundOrEmpty(i);
			int j = compoundtag.getByteOr("Slot", (byte) 0) & 255;
			ItemStack itemstack = ItemStack.OPTIONAL_CODEC.parse(NbtOps.INSTANCE, compoundtag).resultOrPartial(_ -> {}).orElse(ItemStack.EMPTY);

			if (!itemstack.isEmpty()) {
				int targetSlot = -1;

				if (j < Inventory.INVENTORY_SIZE) {
					targetSlot = j;
				} else if (j >= 100 && j < 104) {
					targetSlot = Inventory.INVENTORY_SIZE + (j - 100);
				} else if (j == 150) {
					targetSlot = Inventory.SLOT_OFFHAND;
				}

				if (targetSlot >= 0) {
					if (inventory.getItem(targetSlot).isEmpty()) {
						inventory.setItem(targetSlot, itemstack);
					} else {
						blockedItems.add(itemstack);
					}
				} else {
					blockedItems.add(itemstack);
				}
			}
		}

		if (!blockedItems.isEmpty()) {
			blockedItems.forEach(inventory::add);
		}
	}

public static boolean blockNearLandmarkCenter(int blockX, int blockZ, int range) {
		for (int x = -range; x <= range; x++) {
			for (int z = -range; z <= range; z++) {
				if (LegacyLandmarkPlacements.chunkHasLandmarkCenter(blockX >> 4 + x, blockZ >> 4 + z))
					return true;
			}
		}
		return false;
	}

public static boolean blockIsInLandmarkCenter(int blockX, int blockZ) {
		return chunkHasLandmarkCenter(blockX >> 4, blockZ >> 4);
	}

public static boolean chunkHasLandmarkCenter(int chunkX, int chunkZ) {
		BlockPos nearestCenter = getNearestCenterXZ(chunkX, chunkZ);

		return chunkX == nearestCenter.getX() >> 4 && chunkZ == nearestCenter.getZ() >> 4;
	}

public static int manhattanDistanceFromLandmarkCenter(int chunkX, int chunkZ) {
		BlockPos nearestCenter = getNearestCenterXZ(chunkX, chunkZ);

		int deltaChunkX = Math.abs(chunkX - (nearestCenter.getX() >> 4));
		int deltaChunkZ = Math.abs(chunkZ - (nearestCenter.getZ() >> 4));

		return deltaChunkX + deltaChunkZ;
	}

public static ResourceKey<Structure> pickLandmarkAtBlock(int blockX, int blockZ, LevelReader world) {
		return pickLandmarkForChunk(blockX >> 4, blockZ >> 4, world);
	}

public static ResourceKey<Structure> pickLandmarkForChunk(int chunkX, int chunkZ, LevelReader world) {
		// set the chunkX and chunkZ to the center of the biome
		chunkX = Math.round(chunkX / 16F) * 16;
		chunkZ = Math.round(chunkZ / 16F) * 16;

		BlockPos pos = new BlockPos((chunkX << 4) + 8, 0, (chunkZ << 4) + 8);

		// what biome is at the center of the chunk?
		Optional<ResourceKey<Biome>> biomeResourceKey = world.getBiome(pos).unwrapKey();

		if (biomeResourceKey.isPresent()) {
			ResourceKey<Structure> biomeFeature = BIOME_2_STRUCTURES.get(biomeResourceKey.get());

			if (biomeFeature != null)
				return biomeFeature;
		}

		return pickVarietyLandmark(chunkX, chunkZ);
	}

public static ResourceKey<Structure> pickVarietyLandmark(int chunkX, int chunkZ) {
		// set the chunkX and chunkZ to the center of the biome in case they arent already
		chunkX = Math.round(chunkX / 16F) * 16;
		chunkZ = Math.round(chunkZ / 16F) * 16;

		int regionOffsetX = Math.abs((chunkX + 64 >> 4) % 8);
		int regionOffsetZ = Math.abs((chunkZ + 64 >> 4) % 8);

		// plant two lich towers near the center of each 2048x2048 map area
		if ((regionOffsetX == 4 && regionOffsetZ == 5) || (regionOffsetX == 4 && regionOffsetZ == 3)) {
			return TFStructures.LICH_TOWER;
		}

		// also two nagas
		if ((regionOffsetX == 5 && regionOffsetZ == 4) || (regionOffsetX == 3 && regionOffsetZ == 4)) {
			return TFStructures.NAGA_COURTYARD;
		}

		// okay, well that takes care of most special cases
		return VARIETY_LANDMARKS
			.getRandom(new LegacyRandomSource(WorldUtil.getOverworldSeed() + chunkX * 25117L + chunkZ * 151121L))
			.orElse(TFStructures.HOLLOW_HILL_SMALL);
	}

public static XZQuadrantIterator<BlockPos> landmarkCenterScanner(BlockPos searchFocus, int gridSearchRadius) {
		return new XZQuadrantIterator<>((searchFocus.getX() >> 4) & ~0b1111, (searchFocus.getZ() >> 4) & ~0b1111, false, gridSearchRadius, 16, LegacyLandmarkPlacements::getNearestCenterXZ);
	}

public static BlockPos getNearestCenterXZ(int chunkX, int chunkZ) {
		return getNearestCenterXZ(chunkX, chunkZ, 0);
	}

public static BlockPos getNearestCenterXZ(int chunkX, int chunkZ, int height) {
		// generate random number for the whole biome area
		int regionX = (chunkX + 8) >> 4;
		int regionZ = (chunkZ + 8) >> 4;

		long seed = regionX * 3129871L ^ regionZ * 116129781L;
		seed = seed * seed * 42317861L + seed * 7L;

		int num0 = (int) (seed >> 12 & 3L);
		int num1 = (int) (seed >> 15 & 3L);
		int num2 = (int) (seed >> 18 & 3L);
		int num3 = (int) (seed >> 21 & 3L);

		// slightly randomize center of biome (+/- 3)
		int centerX = 8 + num0 - num1;
		int centerZ = 8 + num2 - num3;

		// centers are offset strangely depending on +/-
		int ccz;
		if (regionZ >= 0) {
			ccz = (regionZ * 16 + centerZ - 8) * 16 + 8;
		} else {
			ccz = (regionZ * 16 + (16 - centerZ) - 8) * 16 + 9;
		}

		int ccx;
		if (regionX >= 0) {
			ccx = (regionX * 16 + centerX - 8) * 16 + 8;
		} else {
			ccx = (regionX * 16 + (16 - centerX) - 8) * 16 + 9;
		}

		return new BlockPos(ccx, height, ccz);
	}

public MegaCanopyTreeFeature(Codec<TFTreeFeatureConfig> config) {
		super(config);
	}

@Override
	protected boolean generate(WorldGenLevel world, RandomSource random, BlockPos pos, BiConsumer<BlockPos, BlockState> trunkPlacer, BiConsumer<BlockPos, BlockState> leavesPlacer, RootPlacer decorationPlacer, TFTreeFeatureConfig config) {
		List<BlockPos> leaves = Lists.newArrayList();
		// determine a height
		int treeHeight = config.minHeight;
		if (random.nextInt(config.chanceAddFiveFirst) == 0) {
			treeHeight += random.nextInt(treeHeight / 2);

			if (random.nextInt(config.chanceAddFiveSecond) == 0) {
				treeHeight += random.nextInt(treeHeight / 4);
			}
		}

		if (world.isOutsideBuildHeight(pos.getY() + treeHeight)) {
			return false;
		}

		// check if we're on dirt or grass
		if (world.getBlockState(pos.below()).canSustainPlant(world, pos.below(), Direction.UP, TFBlocks.CANOPY_SAPLING.get().defaultBlockState()).isFalse()) {
			return false;
		}

		leaves.clear();

		//okay build a tree!  Go up to the height
		buildTrunk(world, leaves, trunkPlacer, random, pos, treeHeight, config);

		// make 3 - 4 branches
		int numBranches = 6 + random.nextInt(3);
		float bangle = random.nextFloat();
		int offset = 0;
		for (int b = 0; b < numBranches; b++) {
			float btilt = 0.25F;// + (random.nextFloat() * 0.05F);
			buildBranch(world, leaves, randomlyOffset(pos, random), trunkPlacer, treeHeight - 15 - (b + offset), 15 + random.nextInt(4), bangle, btilt, false, random, config);

			offset += random.nextInt(2);
			bangle += (random.nextFloat() * 0.4F);
			if (bangle > 1.0F) {
				bangle -= 1.0F;
			}
		}

		// add the actual leaves
		for (BlockPos leafPos : leaves) {
			makeLeafBlob(world, trunkPlacer, leavesPlacer, random, leafPos, config);
		}

		MegaCanopyTreeFeature.makeRoots(world, trunkPlacer, decorationPlacer, random, pos, config);
		MegaCanopyTreeFeature.makeRoots(world, trunkPlacer, decorationPlacer, random, pos.east(), config);
		MegaCanopyTreeFeature.makeRoots(world, trunkPlacer, decorationPlacer, random, pos.south(), config);
		MegaCanopyTreeFeature.makeRoots(world, trunkPlacer, decorationPlacer, random, pos.east().south(), config);

		return true;
	}

private void makeLeafBlob(WorldGenLevel world, BiConsumer<BlockPos, BlockState> trunkPlacer, BiConsumer<BlockPos, BlockState> leafPlacer, RandomSource rand, BlockPos leafPos, TFTreeFeatureConfig config) {
		FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, leafPos, config.branchProvider);
		for (Direction direction : new Direction[]{Direction.NORTH, Direction.EAST, Direction.SOUTH, Direction.WEST}) {
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, leafPos.relative(direction, 1), config.branchProvider);
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, leafPos.relative(direction, 2), config.branchProvider);
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, leafPos.relative(direction, 3), config.branchProvider);
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, leafPos.relative(direction, 4), config.branchProvider);

			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, leafPos.relative(direction, 5).relative(direction.getClockWise()), config.branchProvider);
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, leafPos.relative(direction, 5).relative(direction.getCounterClockWise()), config.branchProvider);

			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, leafPos.relative(direction, 2).relative(direction.getClockWise(), 1), config.branchProvider);
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, leafPos.relative(direction, 3).relative(direction.getClockWise(), 2), config.branchProvider);
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, leafPos.relative(direction, 4).relative(direction.getClockWise(), 3), config.branchProvider);
		}
		// Use circles with legacy distance instead of a spheroid to match the 1.4.7 version as much as possible
		FeaturePlacers.placeCircleOdd(world, leafPlacer, FeaturePlacers.VALID_TREE_POS, rand, leafPos.above(2), 3, config.leavesProvider, true);
		FeaturePlacers.placeCircleOdd(world, leafPlacer, FeaturePlacers.VALID_TREE_POS, rand, leafPos.above(), 6, config.leavesProvider, true);
		FeaturePlacers.placeCircleOdd(world, leafPlacer, FeaturePlacers.VALID_TREE_POS, rand, leafPos, 8, config.leavesProvider, true);
		FeaturePlacers.placeCircleOdd(world, leafPlacer, FeaturePlacers.VALID_TREE_POS, rand, leafPos.below(), 7, config.leavesProvider, true);
		FeaturePlacers.placeCircleOdd(world, leafPlacer, FeaturePlacers.VALID_TREE_POS, rand, leafPos.below(2), 4.5f, config.leavesProvider, true);
	}

private void buildTrunk(WorldGenLevel world, List<BlockPos> leaves, BiConsumer<BlockPos, BlockState> trunkPlacer, RandomSource rand, BlockPos pos, int treeHeight, TFTreeFeatureConfig config) {
		for (int dy = 0; dy <= treeHeight; dy++) {
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, pos.offset(0, dy, 0), config.trunkProvider);
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, pos.offset(1, dy, 0), config.trunkProvider);
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, pos.offset(0, dy, 1), config.trunkProvider);
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, rand, pos.offset(1, dy, 1), config.trunkProvider);
		}

		for (int i = 0; i < 7; i++) {
			if (rand.nextInt(3) == 0) {
				Direction direction = Direction.getRandom(rand);
				Direction.Axis axis = direction.getAxis();
				if (axis != Direction.Axis.Y) {
					BlockPos.MutableBlockPos bugPos = new BlockPos.MutableBlockPos();
					bugPos.set(pos.offset(direction == Direction.EAST ? 1 : 0, rand.nextInt(treeHeight), direction == Direction.SOUTH ? 1 : 0));
					bugPos.move(direction).move(axis == Direction.Axis.Z ? rand.nextInt(2) : 0, 0, axis == Direction.Axis.X ? rand.nextInt(2) : 0);
					if (!world.getBlockState(bugPos).isSolidRender()) {
						BlockState bugState = TFBlocks.FIREFLY.get().defaultBlockState().setValue(DirectionalBlock.FACING, direction);
						this.setBlock(world, bugPos, bugState);
					}
				}
			}
		}

		leaves.add(randomlyOffset(pos.above(treeHeight), rand));
	}

@Override
	void buildBranch(WorldGenLevel world, List<BlockPos> leaves, BlockPos pos, BiConsumer<BlockPos, BlockState> trunkPlacer, int height, double length, double angle, double tilt, boolean trunk, RandomSource treeRNG, TFTreeFeatureConfig config) {
		BlockPos src = pos.above(height);
		BlockPos dest = FeatureLogic.translate(src, length, angle, tilt);

		// constrain branch spread
		int limit = 12;
		if ((dest.getX() - pos.getX()) < -limit) {
			dest = new BlockPos(pos.getX() - limit, dest.getY(), dest.getZ());
		}
		if ((dest.getX() - pos.getX()) > limit) {
			dest = new BlockPos(pos.getX() + limit, dest.getY(), dest.getZ());
		}
		if ((dest.getZ() - pos.getZ()) < -limit) {
			dest = new BlockPos(dest.getX(), dest.getY(), pos.getZ() - limit);
		}
		if ((dest.getZ() - pos.getZ()) > limit) {
			dest = new BlockPos(dest.getX(), dest.getY(), pos.getZ() + limit);
		}

		if (trunk) {
			FeaturePlacers.drawBresenhamTree(world, trunkPlacer, FeaturePlacers.VALID_TREE_POS, src, dest, config.trunkProvider, treeRNG);
		} else {
			FeaturePlacers.drawBresenhamBranch(world, trunkPlacer, treeRNG, src, dest, config.branchProvider);
			FeaturePlacers.drawBresenhamBranch(world, trunkPlacer, treeRNG, src.below(), dest.below(), config.branchProvider);
		}

		leaves.add(dest);
	}

protected static BlockPos randomlyOffset(BlockPos pos, RandomSource random) {
		return randomlyOffset(pos.getX(), pos.getY(), pos.getZ(), random);
	}

protected static BlockPos randomlyOffset(int x, int y, int z, RandomSource random) {
		return switch (random.nextInt(4)) {
			case 0 -> new BlockPos(x, y, z);
			case 1 -> new BlockPos(x + 1, y, z);
			case 2 -> new BlockPos(x, y, z + 1);
			default -> new BlockPos(x + 1, y, z + 1);
		};
	}

private static void filterAlignedPieces(RandomSource random, ObjectArrayList<StructureTemplate.StructureBlockInfo> blockInfos) {
		Util.shuffle(blockInfos, random);
		IntSet xDistinct = new IntArraySet();
		IntSet zDistinct = new IntArraySet();

		for (int i = 0; i < blockInfos.size(); i++) {
			StructureTemplate.StructureBlockInfo blockInfo = blockInfos.get(i);
			if (blockInfo.nbt() == null || filterMetadata(random, blockInfo.nbt())) continue;

			BlockPos pos = blockInfo.pos();
			if (xDistinct.contains(pos.getX()) || zDistinct.contains(pos.getZ())) {
				blockInfos.remove(i);
				i--;
			} else {
				xDistinct.add(pos.getX());
				zDistinct.add(pos.getZ());
			}
		}
	}

private static boolean filterMetadata(RandomSource random, CompoundTag nbt) {
		if (nbt.isEmpty() || !nbt.contains("metadata"))
			return true;

		String metadata = nbt.getString("metadata").get().split("%", 1)[0];
		String chance = metadata.startsWith("rope") ? metadata.substring("rope".length()) : metadata.substring("chain".length());

		return chance.isBlank() || StringUtils.isNumeric(chance) && random.nextFloat() > Integer.parseInt(chance) * 0.01f;
	}

private static EntityType<?> randomMobFromParams(RandomSource random, String[] monsters) {
		String label = Util.getRandom(monsters, random);
		return switch (label) {
			case "hedge_spider" -> TFEntities.HEDGE_SPIDER.value();
			case "swarm_spider" -> TFEntities.SWARM_SPIDER.value();
			default -> EntityType.byString(label).orElse(EntityType.ZOMBIE);
		};
	}

