@Override
	public void deserializeNBT(NBTTagCompound nbt) {
		if (nbt == null) return;

		wasTamperedWith = NBTHelper.getBoolean(nbt, "tampered_with", wasTamperedWith);

		isDepressed = NBTHelper.getBoolean(nbt, "depressed", isDepressed);

		primaryColor = new Color(NBTHelper.getInteger(nbt, "primary_color", 0xFFFFFF));

		secondaryColor = new Color(NBTHelper.getInteger(nbt, "secondary_color", 0xFFFFFF));

		age = NBTHelper.getInteger(nbt, "age", age);

		owner = NBTHelper.getUniqueId(nbt, "owner_id");

		if (nbt.hasKey("mana_capability"))
			handler.deserializeNBT(NBTHelper.getCompoundTag(nbt, "mana_capability"));

		infusedSpell.clear();
		NBTTagList list = NBTHelper.getTagList(nbt, "infused_spell", Constants.NBT.TAG_COMPOUND);
		if (list != null) {
			for (NBTBase base : list) {
				if (base instanceof NBTTagCompound) {
					NBTTagCompound compound = (NBTTagCompound) base;

					SpellRing ring = SpellRing.deserializeRing(compound);
					infusedSpell.add(ring);
				}
			}
		}
	}

@Override
	public void deserializeNBT(NBTTagCompound nbt) {
		// NOTE: Don't store nbt argument to serializedNBT. This one must be generated only by serializeNBT()

		if (nbt.hasKey("module")) this.module = ModuleInstance.deserialize(nbt.getString("module"));
		if (nbt.hasKey("extra")) informationTag = sortInformationTag(nbt.getCompoundTag("extra"));
		if (nbt.hasKey("primary_color")) primaryColor = Color.decode(nbt.getString("primary_color"));
		if (nbt.hasKey("secondary_color")) secondaryColor = Color.decode(nbt.getString("secondary_color"));

		if (nbt.hasKey("modifiers")) {
			compileTimeModifiers.clear();
			for (NBTBase base : nbt.getTagList("modifiers", Constants.NBT.TAG_COMPOUND)) {
				if (base instanceof NBTTagCompound) {
					NBTTagCompound modifierCompound = (NBTTagCompound) base;
					if (modifierCompound.hasKey("operation") && modifierCompound.hasKey("attribute") && modifierCompound.hasKey("modifier")) {
						Operation operation = Operation.values()[modifierCompound.getInteger("operation") % Operation.values().length];
						Attribute attribute = AttributeRegistry.getAttributeFromName(modifierCompound.getString("attribute"));

						float modifierFixed = FixedPointUtils.getFixedFromNBT(modifierCompound, "modifier");
						compileTimeModifiers.put(operation, new AttributeModifierSpellRing(attribute, modifierFixed, operation));
					}
				}
			}
		}

		if (nbt.hasKey("child_ring")) {
			SpellRing childRing = deserializeRing(nbt.getCompoundTag("child_ring"));
			childRing.setParentRing(this);
			setChildRing(childRing);
		}

		if (nbt.hasKey("uuid")) uniqueID = UUID.fromString(nbt.getString("uuid"));

	}

public static Set<BlockPos> blocksInSquare(BlockPos center, Axis axis, int maxBlocks, int maxRange, Predicate<BlockPos> ignore) {
		Set<BlockPos> blocks = new HashSet<>();
		if (ignore.test(center)) return blocks;
		blocks.add(center);
		if (blocks.size() >= maxBlocks) return blocks;

		Queue<BlockPos> blockQueue = new LinkedList<>();
		blockQueue.add(center);

		while (!blockQueue.isEmpty()) {
			BlockPos pos = blockQueue.remove();

			for (EnumFacing facing : EnumFacing.VALUES) {
				if (facing.getAxis() == axis)
					continue;
				BlockPos shift = pos.offset(facing);
				if (shift.getX() - center.getX() > maxRange || center.getX() - shift.getX() > maxRange)
					continue;
				if (shift.getY() - center.getY() > maxRange || center.getY() - shift.getY() > maxRange)
					continue;
				if (shift.getZ() - center.getZ() > maxRange || center.getZ() - shift.getZ() > maxRange)
					continue;
				if (blocks.contains(shift))
					continue;
				if (ignore.test(shift))
					continue;
				blocks.add(shift);
				blockQueue.add(shift);
				if (blocks.size() >= maxBlocks)
					break;
			}

			if (blocks.size() >= maxBlocks)
				break;
		}

		return blocks;
	}

public static float fixedToDouble(long fixedVal) {
		return (float) fixedVal / NBT_FIXEDPOINT_GRANULARITY;
	}

public static float doubleToFixed(double dblVal) {
		return (float) dblVal;
	}

public static float getDoubleFromNBT(NBTTagCompound nbt, String key) {
		// See net.minecraft.nbt.NBTBase.NBT_TYPES[] for meaning of type ids.

		byte dataType = nbt.getTagId(key);
		if (dataType == Constants.NBT.TAG_DOUBLE) // double
			return (float) nbt.getDouble(key);    // NOTE: For legacy case
		else if (dataType == Constants.NBT.TAG_FLOAT)
			return nbt.getFloat(key);
		else if (dataType == Constants.NBT.TAG_LONG) {
			return fixedToDouble(nbt.getLong(key));
		}
		return 0;
	}

public static float getFixedFromNBT(NBTTagCompound nbt, String key) {
		// See net.minecraft.nbt.NBTBase.NBT_TYPES[] for meaning of type ids.

		byte dataType = nbt.getTagId(key);
		if (dataType == Constants.NBT.TAG_DOUBLE)
			return (float) nbt.getDouble(key);    // NOTE: For legacy case
		else if (dataType == Constants.NBT.TAG_FLOAT) // byte, short, int, long, float
			return nbt.getFloat(key);
		else if (dataType == Constants.NBT.TAG_LONG)
			return fixedToDouble(nbt.getLong(key));
		return 0;
	}

public static void setFixedToNBT(NBTTagCompound nbt, String key, float value) {
		nbt.setFloat(key, value);
	}

private void doRender(EnumHandSide side, ItemStack stack) {
		Minecraft mc = Minecraft.getMinecraft();

		boolean isGuiOpen = mc.currentScreen instanceof GuiBook;
		boolean rightHand = side == EnumHandSide.RIGHT;
		boolean hasSpell = NBTHelper.getBoolean(stack, "has_spell", false);

		final String openingTagRight = "openingCooldownRight";
		final String openingTagLeft = "openingCooldownLeft";

		final String openingTag = rightHand ? openingTagRight : openingTagLeft;
		if (isGuiOpen || hasSpell) {
			if (!animatingFields.contains(openingTag)) {
				animatingFields.add(openingTag);
				BasicAnimation<RenderCodex> anim = new BasicAnimation<>(INSTANCE, openingTag);
				anim.setTo(10);
				anim.setDuration(20);
				anim.setEasing(Easing.easeOutCubic);
				anim.setCompletion(() -> {
					animatingFields.remove(openingTag);
				});
				animator.add(anim);
			}

		} else {
			if (!animatingFields.contains(openingTag)) {
				animatingFields.add(openingTag);
				BasicAnimation<RenderCodex> anim = new BasicAnimation<>(INSTANCE, openingTag);
				anim.setTo(0);
				anim.setDuration(20);
				anim.setEasing(Easing.easeOutCubic);
				anim.setCompletion(() -> {
					animatingFields.remove(openingTag);
				});
				animator.add(anim);
			}
		}

		animateIdle("idleXRight");
		animateIdle("idleYRight");
		animateIdle("idleZRight");
		animateIdle("idleXLeft");
		animateIdle("idleYLeft");
		animateIdle("idleZLeft");

		GlStateManager.pushMatrix();
		GlStateManager.color(1F, 1F, 1F);

		double flip = rightHand ? 1 : -1;
		float openingCooldown = rightHand ? openingCooldownRight : openingCooldownLeft;
		float idleX = rightHand ? idleXRight : idleXLeft;
		float idleY = rightHand ? idleYRight : idleYLeft;
		float idleZ = rightHand ? idleZRight : idleZLeft;

		// X axis is Z axis
		// Z axis is X axis
		// Everything is reversed
		GlStateManager.translate(
				0.3F + 0.02F * openingCooldown + (openingCooldown / 50.0) + ((10 - openingCooldown) / 50.0F) + (rightHand ? -0.1F : 0),
				0.475F + 0.01F * openingCooldown + (!rightHand ? 0.02F : 0) + ((10 - openingCooldown) / 100.0F),
				-0.2F - (rightHand ? 0.035F : 0.01F) * openingCooldown + (flip * openingCooldown / 50.0) + (!rightHand ? ((openingCooldown / 10.0F) * 0.08F - 0.03F) : 0));

		// 87.5 rotates from facing the book's spine to the cover facing the player
		// Rotates around book spine
		GlStateManager.rotate((rightHand ? 87.5F : ((openingCooldown / 10.0F) * -20 + 90)) + openingCooldown * (rightHand ? 8 : 12) + (idleY * 5f), 0F, 1F, 0F);

		// Rotates around the CENTER of the book's spine horizontally.
		// IE: Transverse section of the book.
		// Point ur hand horizontally and slide it horizontally.
		// Will rotate the book backwards as it opens, adding a 3d effect
		GlStateManager.rotate(idleZ * 5f, 0F, 0F, 1F);

		mc.renderEngine.bindTexture(texture);
		model.render(null, 0F, 0F, pageFlipCooldownRight, openingCooldown / 12F, 0F, 1F / 16F);

		FontRenderer font = Minecraft.getMinecraft().fontRenderer;
		boolean prevFlag = font.getUnicodeFlag();

		GlStateManager.rotate(180F, 0F, 0F, 1F);

		if (openingCooldown < 3) {
			font.setUnicodeFlag(false);

			GlStateManager.pushMatrix();

			GlStateManager.disableLighting();

			GlStateManager.translate(-0.30F, -0.24F, -0.07F);
			GlStateManager.scale(0.003F, 0.003F, -0.003F);
			GlStateManager.translate(-2, 0, 0); // Yes. I'm nudging it. This is how horrible this gl state is.

			// Below logo
			GlStateManager.translate(0, 70 - font.FONT_HEIGHT, 0);

			String[] title = LibrarianLib.PROXY.translate("wizardry.book.title").split(" ");
			for (String aTitle : title) {
				GlStateManager.translate(0, font.FONT_HEIGHT, 0);

				String titleText = font.trimStringToWidth(aTitle, 80);
				int width = font.getStringWidth(titleText);
				int max = 80;
				double x = max / 2.0 - width / 2.0;
				GlStateManager.translate(x, 0, 0);
				font.drawString(titleText, 0, 0, 0x00FFFF);
				GlStateManager.translate(-x, 0, 0);
			}

			GlStateManager.translate(0, font.FONT_HEIGHT, 0);

			String subtitle = font.trimStringToWidth(LibrarianLib.PROXY.translate("wizardry.book.subtitle"), 80);
			double scale = 2.6;
			GlStateManager.translate((80F - font.getStringWidth(subtitle)) * scale, 0F, 0F);
			GlStateManager.scale(0.6F, 0.6F, 0.6F);
			font.drawString(TextFormatting.ITALIC + subtitle, 0, 0, 0x00FFFF);

			GlStateManager.enableLighting();
			GlStateManager.popMatrix();
		}

		// In both pages: 0,0 is the top left corner
		// You're welcome.
		if (hasSpell && openingCooldown > 6) {
			font.setUnicodeFlag(true);

			// LEFT PAGE
			{
				GlStateManager.pushMatrix();

				GlStateManager.rotate(60, 0, 1, 0);
				GlStateManager.translate(0, 0.1, 0);

				GlStateManager.translate(-0.30F, -0.24F, -0.07F);
				GlStateManager.scale(0.003F, 0.003F, -0.003F);

				GlStateManager.translate(-10, -30, -5);

				// Draw tooltip above page here
				if (rightHand) {
					GlStateManager.pushMatrix();
					GlStateManager.translate(-30, -25, -30);
					drawTooltip(font, LibrarianLib.PROXY.translate("wizardry.book.shift_scroll"),
							LibrarianLib.PROXY.translate("wizardry.book.open_recipe_tab"));
					GlStateManager.popMatrix();
				}

				String[] lines = getSpellStructureLines(stack);
				for (int i = 0; i < lines.length; i++)
					font.drawString(lines[i], 0, i * font.FONT_HEIGHT, 0x00);

				GlStateManager.popMatrix();
			}
			// RIGHT PAGE
			{
				GlStateManager.pushMatrix();

				GlStateManager.rotate(120, 0, 1, 0);
				GlStateManager.translate(0, 0.1, 0);

				GlStateManager.translate(-0.30F, -0.24F, -0.07F);
				GlStateManager.scale(0.003F, 0.003F, -0.003F);

				GlStateManager.translate(120, -25, 0);

				// Translate a little extra bit to fit the recipe cozily
				GlStateManager.translate(-5, -5, 0);

				// Draw tooltip above page here
				if (!rightHand)
					drawTooltip(font, LibrarianLib.PROXY.translate("wizardry.book.shift_scroll"),
							LibrarianLib.PROXY.translate("wizardry.book.open_recipe_tab"));

				List<ItemStack> inventory = getSpellInventory(stack);
				int currentPage = NBTHelper.getInt(stack, "page", 0);

				int row = 0;
				int column = 0;
				int pageNb = 0;
				for (int i = 0; i < inventory.size(); i++) {
					ItemStack recipeStack = inventory.get(i);
					if (recipeStack.isEmpty()) continue;

					if (pageNb >= currentPage) {

						GlStateManager.pushMatrix();
						GlStateManager.translate(column * 32, row * 16, -150);

						renderItemStack(recipeStack);

						GlStateManager.popMatrix();

						if (i != inventory.size() - 1 && column < 3) {
							GlStateManager.pushMatrix();
							GlStateManager.translate(32 + column * 32, row * 16 + 13, 0);

							GlStateManager.rotate(180, 0, 0, 1);
							GlStateManager.color(0, 1f, 1f, 1f);
							GlStateManager.disableLighting();

							arrowSprite.bind();
							arrowSprite.draw(0, 0, 0, 16, 8);

							GlStateManager.enableLighting();

							GlStateManager.popMatrix();
						}

					}

					if (++column >= 3) {
						column = 0;
						row++;
					}

					if (row >= 9) {
						row = 0;
						pageNb++;

						if (pageNb > currentPage) break;
					}

				}

				GlStateManager.popMatrix();
			}
		}

		font.setUnicodeFlag(prevFlag);
		GlStateManager.popMatrix();
	}

public void animateIdle(String tag) {
		if (!animatingFields.contains(tag) && RandUtil.nextBoolean()) {
			animatingFields.add(tag);
			BasicAnimation<RenderCodex> anim = new BasicAnimation<>(INSTANCE, tag);
			anim.setTo(RandUtil.nextFloat(0, 1));
			anim.setDuration(RandUtil.nextInt(80, 120));
			anim.setEasing(Easing.easeInOutSine);
			anim.setCompletion(() -> {
				animatingFields.remove(tag);
			});
			animator.add(anim);
		}
	}

@SubscribeEvent
	public void underworldTeleport(LivingHurtEvent event) {
		if (!(event.getEntity() instanceof EntityPlayer)) return;
		if (fallResetter.contains(event.getEntity().getUniqueID())) {
			if (event.getEntity().posY < 0 || event.getEntity().posY > event.getEntity().world.getHeight()) {
				event.setCanceled(true);
				return;
			}
			if (event.getSource() == DamageSource.FALL) {
				fallResetter.remove(event.getEntity().getUniqueID());
				event.setCanceled(true);
			}
		}
	}

