@NotNull
	@Override
	public SpellData renderVisualization(@Nonnull World world, ModuleInstanceEffect instance, @Nonnull SpellData data, @Nonnull SpellRing ring, float partialTicks) {
		if (ring.getParentRing() != null
				&& ring.getParentRing().getModule() != null
				&& ring.getParentRing().getModule().getModuleClass() instanceof ModuleShapeZone)
			return data;


		BlockPos targetPos = data.getData(BLOCK_HIT);
		EnumFacing facing = data.getData(FACE_HIT);

		double range = ring.getAttributeValue(world, AttributeRegistry.AREA, data);
		double strength = ring.getAttributeValue(world, AttributeRegistry.POTENCY, data);

		if (targetPos == null || facing == null) return data;
		Set<BlockPos> blocks = BlockUtils.blocksInSquare(targetPos, facing, (int) range, (int) ((Math.sqrt(range) + 1) / 2), pos ->
		{
			BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos(pos);
			if (!world.isAirBlock(mutable.offset(facing))) return true;
			IBlockState state = world.getBlockState(pos);
			if (BlockUtils.isAnyAir(state)) return true;

			float hardness = state.getBlockHardness(world, pos);
			return hardness < 0 || hardness > strength;
		});
		if (blocks.isEmpty()) return data;
		for (BlockPos pos : blocks) {
			IBlockState state = world.getBlockState(pos);
			BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos(pos);
			for (EnumFacing face : EnumFacing.VALUES) {
				mutable.move(face);
				IBlockState adjStat = instance.getCachableBlockstate(world, mutable, data);
				if (adjStat.getBlock() != state.getBlock() || !blocks.contains(mutable)) {
					RenderUtils.drawFaceOutline(mutable, face.getOpposite());
				}
				mutable.move(face.getOpposite());
			}
		}
		return data;
	}

@NotNull
	@Override
	public SpellData renderVisualization(@Nonnull World world, ModuleInstanceEffect instance, @Nonnull SpellData data, @Nonnull SpellRing ring, float partialTicks) {
		if (ring.getParentRing() != null
				&& ring.getParentRing().getModule() != null
				&& ring.getParentRing().getModule().getModuleClass() instanceof ModuleShapeZone)
			return data;

		BlockPos targetPos = data.getData(SpellData.DefaultKeys.BLOCK_HIT);
		EnumFacing facing = data.getFaceHit();
		Entity caster = data.getCaster(world);

		if (facing == null || targetPos == null) return data;

		double area = ring.getAttributeValue(world, AttributeRegistry.AREA, data);

		if (caster instanceof EntityPlayer) {
			IBlockState selected = instance.getSelectedBlockState((EntityPlayer) caster);
			if (selected == null) return data;

			IBlockState targetState = world.getBlockState(targetPos);
			List<ItemStack> stacks = instance.getAllOfStackFromInventory((EntityPlayer) caster, selected);
			if (stacks.isEmpty()) return data;

			int stackCount = instance.getCountOfStacks(stacks);
			Set<BlockPos> blocks = BlockUtils.blocksInSquare(targetPos, facing, Math.min(stackCount, (int) area), (int) ((Math.sqrt(area)+1)/2), pos -> {
				if (BlockUtils.isAnyAir(targetState)) return true;

				BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos(pos);
				IBlockState adjacentState = instance.getCachableBlockstate(world, mutable.offset(facing), data);
				if (adjacentState.getBlock() != Blocks.AIR) return true;

				IBlockState state = instance.getCachableBlockstate(world, pos, data);
				return state.getBlock() != targetState.getBlock();
			});

			if (blocks.isEmpty()) {
				if (targetState.getBlock() == Blocks.AIR)
					RenderUtils.drawCubeOutline(world, targetPos, targetState);
				else RenderUtils.drawFaceOutline(targetPos, facing);
			} else
				for (BlockPos areaPos : blocks) {
					BlockPos pos = areaPos.offset(facing);

					BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos(pos);
					for (EnumFacing facing1 : EnumFacing.VALUES) {

						mutable.move(facing1);

						if (blocks.contains(mutable)) {

							RenderUtils.drawFaceOutline(mutable, facing1.getOpposite());
						}
						mutable.move(facing1.getOpposite());
					}
				}
		}
		return data;
	}

@Override
	public boolean run(@NotNull World world, ModuleInstanceEffect instance, @Nonnull SpellData spell, @Nonnull SpellRing spellRing) {
		Entity targetEntity = spell.getVictim(world);
		Entity caster = spell.getCaster(world);
		BlockPos targetBlock = spell.getTargetPos();
		EnumFacing facing = spell.getFaceHit();

		if (caster == null) return false;

		if (targetEntity instanceof EntityLivingBase) {
			if (!spellRing.taxCaster(world, spell, true)) return false;

			Vec3d posTarget = new Vec3d(targetEntity.posX, targetEntity.posY, targetEntity.posZ),
					posCaster = new Vec3d(caster.posX, caster.posY, caster.posZ);
			float yawTarget = targetEntity.rotationYaw,
					pitchTarget = targetEntity.rotationPitch,
					yawCaster = caster.rotationYaw,
					pitchCaster = caster.rotationPitch;

			targetEntity.rotationYaw = yawCaster;
			targetEntity.rotationPitch = pitchCaster;
			targetEntity.setPositionAndUpdate(posCaster.x, posCaster.y, posCaster.z);

			caster.rotationYaw = yawTarget;
			caster.rotationPitch = pitchTarget;
			caster.setPositionAndUpdate(posTarget.x, posTarget.y, posTarget.z);
			world.playSound(null, caster.getPosition(), ModSounds.TELEPORT, CommonProxy.SoundCategory_WizardryGeneral, 1, RandUtil.nextFloat());
			world.playSound(null, targetEntity.getPosition(), ModSounds.TELEPORT, CommonProxy.SoundCategory_WizardryGeneral, 1, RandUtil.nextFloat());

			return true;

		} else if (targetBlock != null && caster instanceof EntityPlayer) {
			if (facing == null) return false;
			ItemStack hand = ((EntityPlayer) caster).getHeldItemMainhand();
			if (hand.isEmpty()) return false;

			world.playSound(null, targetBlock, ModSounds.TELEPORT, CommonProxy.SoundCategory_WizardryGeneral, 1, RandUtil.nextFloat());
			if (NBTHelper.hasNBTEntry(hand, "selected")) {

				NBTTagCompound compound = NBTHelper.getCompound(hand, "selected");
				if (compound == null) return false;

				IBlockState state = NBTUtil.readBlockState(compound);
				IBlockState touchedBlock = world.getBlockState(targetBlock);

				boolean misMatch = false;
				for (IProperty property : touchedBlock.getPropertyKeys()) {
					if (state.getPropertyKeys().contains(property)) {
						if (state.getValue(property).equals(touchedBlock.getValue(property))) {

						} else {
							misMatch = true;
						}
					}
				}
				if (touchedBlock.getBlock() == state.getBlock() && !misMatch) return false;

				double area = spellRing.getAttributeValue(world, AttributeRegistry.AREA, spell);

				ItemStack stackBlock = null;
				for (ItemStack stack : ((EntityPlayer) caster).inventory.mainInventory) {
					if (stack.isEmpty()) continue;
					if (!(stack.getItem() instanceof ItemBlock)) continue;
					Block block = ((ItemBlock) stack.getItem()).getBlock();
					if (block != state.getBlock()) continue;

					stackBlock = stack;
					break;
				}

				if (stackBlock == null) return false;

				Set<BlockPos> blocks = BlockUtils.blocksInSquare(targetBlock, facing, Math.min(stackBlock.getCount(), (int) area), (int) ((Math.sqrt(area)+1)/2), pos -> {
					if (world.isAirBlock(pos)) return true;
					if (!world.isAirBlock(pos.offset(facing))) return true;

					IBlockState block = world.getBlockState(pos);
					return block.getBlock() != touchedBlock.getBlock();
				});

				if (blocks.isEmpty()) return true;

				for (BlockPos pos : blocks) {
					if (stackBlock.isEmpty()) return true;
					if (!spellRing.taxCaster(world, spell, 1 / area, false)) return false;
					if (world.isAirBlock(pos)) continue;
					if (world.getBlockState(pos).getBlock() == state.getBlock()) continue;

					stackBlock.shrink(1);

					IBlockState oldState = world.getBlockState(pos);
					BlockUtils.placeBlock(world, pos, state, (EntityPlayerMP) caster);
					((EntityPlayer) caster).inventory.addItemStackToInventory(new ItemStack(oldState.getBlock().getItemDropped(oldState, world.rand, 0)));
				}
			}
			return true;
		}

		return false;
	}

@NotNull
	@Override
	public SpellData renderVisualization(@Nonnull World world, ModuleInstanceEffect instance, @Nonnull SpellData data, @Nonnull SpellRing ring, float partialTicks) {
		if (ring.getParentRing() != null
				&& ring.getParentRing().getModule() != null
				&& ring.getParentRing().getModule() == ModuleRegistry.INSTANCE.getModule("event_collide_entity"))
			return data;

		Entity caster = data.getCaster(world);
		BlockPos targetBlock = data.getTargetPos();
		EnumFacing facing = data.getFaceHit();


		if (!(caster instanceof EntityLivingBase)) return data;
		ItemStack hand = ((EntityLivingBase) caster).getHeldItemMainhand();

		if (hand.isEmpty()) return data;

		if (targetBlock != null && caster instanceof EntityPlayer) {
			if (facing == null) return data;
			if (NBTHelper.hasNBTEntry(hand, "selected")) {
				NBTTagCompound compound = NBTHelper.getCompound(hand, "selected");
				if (compound == null) return data;

				IBlockState state = NBTUtil.readBlockState(compound);
				IBlockState targetState = instance.getCachableBlockstate(world, targetBlock, data);
				if (targetState.getBlock() == state.getBlock()) return data;

				double area = ring.getAttributeValue(world, AttributeRegistry.AREA, data);

				ItemStack stackBlock = null;
				for (ItemStack stack : ((EntityPlayer) caster).inventory.mainInventory) {
					if (stack.isEmpty()) continue;
					if (!(stack.getItem() instanceof ItemBlock)) continue;
					Block block = ((ItemBlock) stack.getItem()).getBlock();
					if (block != state.getBlock()) continue;
					stackBlock = stack;
					break;
				}

				if (stackBlock == null) return data;
				stackBlock = stackBlock.copy();

				Set<BlockPos> blocks = BlockUtils.blocksInSquare(targetBlock, facing, Math.min(stackBlock.getCount(), (int) area), (int) ((Math.sqrt(area)+1)/2), pos -> {
					BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos(pos);
					IBlockState adjacentState = world.getBlockState(mutable.offset(facing));
					if (adjacentState.getBlock() != Blocks.AIR) return true;

					IBlockState block = world.getBlockState(pos);
					return block.getBlock() != targetState.getBlock();
				});

				if (blocks.isEmpty()) return data;

				HashMap<BlockPos, IBlockState> blockStateCache = new HashMap<>();
				for (BlockPos pos : blocks) {
					blockStateCache.put(pos, world.getBlockState(pos));
				}

				HashMap<BlockPos, IBlockState> tmpCache = new HashMap<>(blockStateCache);


				for (Map.Entry<BlockPos, IBlockState> entry : tmpCache.entrySet()) {

					if (BlockUtils.isAnyAir(entry.getValue())) continue;

					BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos(entry.getKey());
					for (EnumFacing face : EnumFacing.VALUES) {

						mutable.move(face);

						IBlockState adjState;
						if (!blockStateCache.containsKey(mutable)) {
							adjState = world.getBlockState(mutable);
							blockStateCache.put(mutable.toImmutable(), adjState);
						} else adjState = blockStateCache.get(mutable);

						if (adjState.getBlock() != targetState.getBlock() || !blocks.contains(mutable)) {

							RenderUtils.drawFaceOutline(mutable, face.getOpposite());
						}
						mutable.move(face.getOpposite());
					}
				}
			}
		}

		return data;
	}

