@Override
        public PackResources openFull(PackLocationInfo location, Pack.Metadata metadata) {
            PackResources packresources = this.openPrimary(location);
            List<String> list = metadata.overlays();
            if (list.isEmpty()) {
                return packresources;
            } else {
                List<PackResources> list1 = new ArrayList<>(list.size());

                for (String s : list) {
                    Path path = this.sourcePack.resolve(s);
                    list1.add(new CombinedPackResources(location, this.packInfo, this.packs, path));
                }

                return new CompositePackResources(packresources, list1);
            }
        }

private static void updatePositions(BlockPos playerPos, ClientLevel level, ItemStack stack, int range, int type, boolean depopulate) {
        // Initial setup of the different IDs in the map.
        positionsForTypes.putIfAbsent(0, new ArrayList<>());
        positionsForTypes.putIfAbsent(1, new ArrayList<>());
        positionsForTypes.putIfAbsent(2, new ArrayList<>());
        positionsForTypes.putIfAbsent(3, new ArrayList<>());
        // Loop and select random positions to check and see whether an overlay should be rendered there.
        for (int c = 0; c < 667; ++c) {
            int x = playerPos.getX() + level.getRandom().nextInt(range) - level.getRandom().nextInt(range);
            int y = playerPos.getY() + level.getRandom().nextInt(range) - level.getRandom().nextInt(range);
            int z = playerPos.getZ() + level.getRandom().nextInt(range) - level.getRandom().nextInt(range);
            if (!depopulate) { // For checking to add overlays to the world.
                BlockPos pos = new BlockPos(x, y, z);
                if (stack.is(level.getBlockState(pos).getBlock().asItem())) { // Add an overlay if the corresponding dungeon block item is held.
                    if (!positionsForTypes.get(type).contains(pos)) {
                        positionsForTypes.get(type).add(pos);
                    }
                }
            } else { // For checking to remove overlays from the world.
                List<BlockPos> positions = positionsForTypes.get(type);
                if (!positions.isEmpty() && level.getRandom().nextInt(100) == 0) {
                    BlockPos pos = positions.get(level.getRandom().nextInt(positions.size()));
                    if (!stack.is(level.getBlockState(pos).getBlock().asItem())) { // Remove an overlay if the corresponding dungeon block item is not held.
                        positions.remove(pos);
                        positionsForTypes.put(type, positions);
                    }
                }
            }
        }
    }

private static void renderHammerCooldownOverlay(GuiGraphics guiGraphics, Minecraft minecraft, Window window, LocalPlayer player) {
        if (AetherConfig.CLIENT.enable_hammer_cooldown_overlay.get() && !minecraft.options.hideGui) {
            Inventory inventory = player.getInventory();
            if (inventory.contains((itemStack) -> itemStack.is(AetherItems.HAMMER_OF_KINGBDOGZ.get()))) {
                List<ItemStack> items = new ArrayList<>(inventory.items);
                items.addAll(inventory.offhand);
                for (ItemStack itemStack : items) {
                    Item item = itemStack.getItem();
                    if (item == AetherItems.HAMMER_OF_KINGBDOGZ.get()) {
                        float cooldownPercent = player.getCooldowns().getCooldownPercent(item, 0.0F);
                        if (cooldownPercent > 0.0F) {
                            if (player.getMainHandItem().getItem() == item) {
                                itemStack = player.getMainHandItem();
                            } else if (player.getOffhandItem().getItem() == item) {
                                itemStack = player.getOffhandItem();
                            }
                            String text = itemStack.getHoverName().getString().concat(" ").concat(Component.translatable("aether.hammer_of_kingbdogz_cooldown").getString());
                            guiGraphics.drawString(minecraft.font, text, (int) ((window.getGuiScaledWidth() / 2.0F) - (minecraft.font.width(text) / 2.0F)), 32, 16777215);
                            guiGraphics.blitSprite(TEXTURE_COOLDOWN_BAR_BACKGROUND, 128, 8, 0, 0, window.getGuiScaledWidth() / 2 - 64, 42, 128, 8);
                            guiGraphics.blitSprite(TEXTURE_COOLDOWN_BAR, 128, 8, 0, 0, window.getGuiScaledWidth() / 2 - 64, 42, (int) (cooldownPercent * 128), 8);
                            break;
                        }
                    }
                }
            }
        }
    }

