@Override
    public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
        ItemStack heldStack = player.getItemInHand(hand);
        HitResult hitResult = getPlayerPOVHitResult(level, player, ClipContext.Fluid.ANY);
        if (hitResult.getType() == HitResult.Type.MISS) {
            return InteractionResultHolder.pass(heldStack);
        } else {
            Vec3 viewVector = player.getViewVector(1.0F);
            List<Entity> list = level.getEntities(player, player.getBoundingBox().expandTowards(viewVector.scale(5.0)).inflate(1.0), ENTITY_PREDICATE);
            if (!list.isEmpty()) {
                Vec3 eyePosition = player.getEyePosition();
                for (Entity entity : list) {
                    AABB aabb = entity.getBoundingBox().inflate(entity.getPickRadius());
                    if (aabb.contains(eyePosition)) {
                        return InteractionResultHolder.pass(heldStack);
                    }
                }
            }
            if (hitResult.getType() == HitResult.Type.BLOCK) {
                Boat boat = this.getBoat(level, hitResult);
                boat.setYRot(player.getYRot());
                if (!level.noCollision(boat, boat.getBoundingBox())) {
                    return InteractionResultHolder.fail(heldStack);
                } else {
                    if (!level.isClientSide()) {
                        level.addFreshEntity(boat);
                        level.gameEvent(player, GameEvent.ENTITY_PLACE, BlockPos.containing(hitResult.getLocation()));
                        if (!player.getAbilities().instabuild) {
                            heldStack.shrink(1);
                        }
                    }
                    player.awardStat(Stats.ITEM_USED.get(this));
                    return InteractionResultHolder.sidedSuccess(heldStack, level.isClientSide());
                }
            } else {
                return InteractionResultHolder.pass(heldStack);
            }
        }
    }

public static ItemStack isCapeVisible(LivingEntity livingEntity) {
        AccessoriesCapability accessories = AccessoriesCapability.get(livingEntity);
        if (accessories != null) {
            AccessoriesContainer accessoriesContainer = accessories.getContainer(CapeItem.getStaticIdentifier());

            if (accessoriesContainer != null) {
                ExpandedSimpleContainer simpleAccessoriesContainer = accessoriesContainer.getAccessories();
                ExpandedSimpleContainer simpleCosmeticsContainer = accessoriesContainer.getCosmeticAccessories();

                Pair<Integer, ItemStack> stack = StreamSupport.stream(simpleAccessoriesContainer.spliterator(), true).findFirst().orElse(null);
                Pair<Integer, ItemStack> cosmeticStack = StreamSupport.stream(simpleCosmeticsContainer.spliterator(), true).findFirst().orElse(null);
                if (cosmeticStack != null && !cosmeticStack.getSecond().isEmpty() && Accessories.config().clientOptions.showCosmeticAccessories()) {
                    stack = cosmeticStack;
                }
                if (stack != null) {
                    if (accessoriesContainer.shouldRender(stack.getFirst())) {
                        return stack.getSecond();
                    }
                }
            }
        }
        return ItemStack.EMPTY;
    }

public static PerkSavedData load(CompoundTag tag, HolderLookup.Provider lookupProvider) {
        PerkSavedData data = PerkSavedData.create();
        for (String key : tag.getAllKeys()) {
            if (key.equals("StoredSkinData")) {
                CompoundTag storedSkinDataTag = tag.getCompound(key);
                for (String storedSkinDataKey : storedSkinDataTag.getAllKeys()) {
                    CompoundTag moaDataEntryTag = storedSkinDataTag.getCompound(storedSkinDataKey);
                    UUID playerUUID = UUID.fromString(storedSkinDataKey);
                    UUID moaUUID = null;
                    String moaSkinId = null;
                    if (moaDataEntryTag.contains("MoaUUID")) {
                        moaUUID = moaDataEntryTag.getUUID("MoaUUID");
                    }
                    if (moaDataEntryTag.contains("MoaSkin")) {
                        moaSkinId = moaDataEntryTag.getString("MoaSkin");
                    }
                    MoaSkins.MoaSkin moaSkin = MoaSkins.getMoaSkins().get(moaSkinId);
                    data.storedSkinData.put(playerUUID, new MoaData(moaUUID, moaSkin));
                }
            }
            if (key.equals("StoredHaloData")) {
                CompoundTag storedHaloDataTag = tag.getCompound(key);
                for (String storedHaloDataKey : storedHaloDataTag.getAllKeys()) {
                    CompoundTag haloEntryTag = storedHaloDataTag.getCompound(storedHaloDataKey);
                    UUID playerUUID = UUID.fromString(storedHaloDataKey);
                    String hexColor = null;
                    if (haloEntryTag.contains("HexColor")) {
                        hexColor = haloEntryTag.getString("HexColor");
                    }
                    data.storedHaloData.put(playerUUID, new Halo(hexColor));
                }
            }
            if (key.equals("StoredDeveloperGlowData")) {
                CompoundTag storedDeveloperGlowDataTag = tag.getCompound(key);
                for (String storedDeveloperGlowDataKey : storedDeveloperGlowDataTag.getAllKeys()) {
                    CompoundTag developerGlowEntryTag = storedDeveloperGlowDataTag.getCompound(storedDeveloperGlowDataKey);
                    UUID playerUUID = UUID.fromString(storedDeveloperGlowDataKey);
                    String hexColor = null;
                    if (developerGlowEntryTag.contains("HexColor")) {
                        hexColor = developerGlowEntryTag.getString("HexColor");
                    }
                    data.storedDeveloperGlowData.put(playerUUID, new DeveloperGlow(hexColor));
                }
            }
        }
        return data;
    }

@Override
        public MapCodec<IncubationRecipe> codec() {
            return RecordCodecBuilder.mapCodec((instance) -> instance.group(
                Codec.STRING.optionalFieldOf("group", "").forGetter(p_300832_ -> p_300832_.group),
                Ingredient.CODEC_NONEMPTY.fieldOf("ingredient").forGetter((recipe) -> recipe.ingredient),
                BuiltInRegistries.ENTITY_TYPE.byNameCodec().fieldOf("entity").forGetter((recipe) -> recipe.entity),
                CompoundTag.CODEC.optionalFieldOf("tag").forGetter((recipe) -> recipe.tag),
                Codec.INT.fieldOf("incubationtime").orElse(500).forGetter((recipe) -> recipe.incubationTime)
            ).apply(instance, IncubationRecipe::new));
        }

public AetherCookingSerializer(AetherCookingSerializer.CookieBaker<T> factory, int defaultCookingTime) {
        this.factory = factory;
        this.codec = RecordCodecBuilder.mapCodec((instance) -> instance.group(
                Codec.STRING.optionalFieldOf("group", "").forGetter(AbstractCookingRecipe::getGroup),
                AetherBookCategory.CODEC.fieldOf("category").forGetter(AbstractAetherCookingRecipe::aetherCategory),
                Ingredient.CODEC_NONEMPTY.fieldOf("ingredient").forGetter((recipe) -> recipe.getIngredients().getFirst()),
                ItemStack.CODEC.fieldOf("result").forGetter(AbstractAetherCookingRecipe::getResult),
                Codec.FLOAT.fieldOf("experience").orElse(0.0F).forGetter(AbstractCookingRecipe::getExperience),
                Codec.INT.fieldOf("cookingtime").orElse(defaultCookingTime).forGetter(AbstractCookingRecipe::getCookingTime)
        ).apply(instance, factory::create));
        this.streamCodec = StreamCodec.of(this::toNetwork, this::fromNetwork);
    }

