@Override
	public boolean matches(CraftingInput input, Level level) {
		if (this.ingredients.size() != input.ingredientCount())
			return false;

		for (ItemStack stack : input.items()) {
			if (stack.is(AoATags.Items.STAVES)) {
				if (AoAStaff.StoredCasts.getIfPresent(stack).map(storedCasts -> storedCasts.stored() >= 0).orElse(false))
					return false;
			}
		}

		return input.stackedContents().canCraft(this, null);
	}

@Override
	public boolean matches(CraftingInput input, Level level) {
		Reference2IntMap<Item> foundItems = new Reference2IntArrayMap<>();
		Reference2IntMap<Item> runeCosts = null;

		for (ItemStack stack : input.items()) {
			if (runeCosts == null && stack.has(AoADataComponents.STORED_SPELL_CASTS)) {
				AoAStaff.StoredCasts storedCasts = stack.get(AoADataComponents.STORED_SPELL_CASTS);

				if (storedCasts.stored() < 0 || storedCasts.stored() >= storedCasts.max().orElse(Integer.MAX_VALUE))
					return false;

				runeCosts = stack.has(AoADataComponents.STAFF_STATS) ? stack.get(AoADataComponents.STAFF_STATS).runeCosts() : null;
			}
			else if (!stack.isEmpty()) {
				foundItems.mergeInt(stack.getItem(), stack.getCount(), Integer::sum);
			}
		}

		if (foundItems.isEmpty() || runeCosts == null || foundItems.size() != runeCosts.size())
			return false;

		for (Reference2IntMap.Entry<Item> foundItem : foundItems.reference2IntEntrySet()) {
			if (!runeCosts.containsKey(foundItem.getKey()))
				return false;
		}

		for (Reference2IntMap.Entry<Item> runeCost : runeCosts.reference2IntEntrySet()) {
			if (!foundItems.containsKey(runeCost.getKey()) || foundItems.getInt(runeCost.getKey()) < runeCost.getIntValue())
				return false;
		}

		return true;
	}

public static void init() {
        NeoForge.EVENT_BUS.addListener(DynamicEventSubscriptions::addNewSubscribers);
    }

public static void addListeners(DynamicEventSubscriber<? extends Event>... subscribers) {
        addListeners(List.of(subscribers));
    }

public static void addListeners(Collection<? extends DynamicEventSubscriber<? extends Event>> subscribers) {
        synchronized (NEW_LISTENERS) {
            for (DynamicEventSubscriber<? extends Event> subscriber : subscribers) {
                assert subscriber.eventClass() != PlayerEvent.Clone.class && subscriber.eventClass() != PlayerEvent.PlayerRespawnEvent.class;

                NEW_LISTENERS.computeIfAbsent(subscriber.eventClass(), key -> new ObjectArrayList<>()).add(subscriber);
            }

            isDirty = true;
        }
    }

private static void addNewSubscribers(final ServerTickEvent.Post ev) {
        if (!isDirty)
            return;

        synchronized (NEW_LISTENERS) {
            for (Map.Entry<Class<? extends Event>, List<DynamicEventSubscriber<? extends Event>>> entry : NEW_LISTENERS.entrySet()) {
                Class<? extends Event> eventClass = entry.getKey();
                Set<DynamicEventSubscriber<? extends Event>> listeners;

                if (!LISTENERS.containsKey(eventClass)) {
                    listeners = LISTENERS.computeIfAbsent(eventClass, k -> new CopyOnWriteArraySet<>());

                    NeoForge.EVENT_BUS.addListener(eventClass, event -> {
                        List<DynamicEventSubscriber<? extends Event>> toRemove = new ObjectArrayList<>();

                        for (DynamicEventSubscriber subscriber : listeners) {
                            if (!subscriber.isStillValid()) {
                                toRemove.add(subscriber);

                                continue;
                            }

                            subscriber.accept(event);
                        }

                        if (!toRemove.isEmpty())
                            listeners.removeAll(toRemove);
                    });
                }
                else {
                    listeners = LISTENERS.get(eventClass);
                }

                listeners.addAll(entry.getValue());
                entry.getValue().clear();
            }
        }

        isDirty = false;
    }

