public static boolean findItemForConsumption(Player player, Predicate<ItemStack> predicate, int amount, boolean shouldConsume) {
        if (amount <= 0)
            return true;

        final List<ItemStack> foundStacks = new ObjectArrayList<>(amount / 64);
        final AtomicInteger count = new AtomicInteger(amount);

        return findItem(player, stack -> {
            if (predicate.test(stack)) {
                foundStacks.add(stack);

                return count.updateAndGet(value -> value - stack.getCount()) <= 0;
            }

            return false;
        }).map(ignored -> {
            if (shouldConsume && !player.level().isClientSide) {
                int remaining = amount;

                for (ItemStack stack : foundStacks) {
                    int reduction = Math.min(remaining, stack.getCount());

                    stack.shrink(reduction);

                    if ((remaining -= reduction) <= 0)
                        break;
                }

                player.inventoryMenu.broadcastChanges();
            }

            return true;
        }).orElse(false);
    }

public static boolean findAndConsumeRunes(Reference2IntMap<Item> runeMap, ServerPlayer player, boolean allowBuffs, @NotNull ItemStack heldItem) {
		if (player.hasInfiniteMaterials())
			return true;

		Reference2IntOpenHashMap<Item> requiredRunes = new Reference2IntOpenHashMap<>(runeMap);
		boolean nightmareArmour = allowBuffs && PlayerUtil.isWearingFullSet(player, AoAArmourMaterials.NIGHTMARE);

		for (Item item : requiredRunes.keySet()) {
			requiredRunes.computeIntIfPresent(item, (rune, cost) -> {
				if (allowBuffs) {
					cost = Mth.ceil(AoAEnchantments.modifyRuneCost(player.serverLevel(), heldItem, cost));

					if (nightmareArmour) {
						if (rune == AoAItems.DISTORTION_RUNE.get())
							return null;

						cost = Math.max(cost - 1, 1);
					}
				}

				return Mth.ceil(AoAEnchantments.modifyAmmoCost(player.serverLevel(), heldItem, cost));
			});
		}

		if (requiredRunes.isEmpty())
			return true;

		IntSet runeSlots = new IntOpenHashSet();
		Reference2IntOpenHashMap<Item> runeCounter = new Reference2IntOpenHashMap<>(requiredRunes);

		ItemStack mainHandStack = player.getItemInHand(InteractionHand.MAIN_HAND);
		ItemStack offHandStack = player.getItemInHand(InteractionHand.OFF_HAND);

		if (mainHandStack.is(AoATags.Items.ADVENT_RUNE)) {
			Item type = mainHandStack.getItem();

			if (runeCounter.containsKey(type)) {
				int amount = runeCounter.getInt(type);

				runeSlots.add(-1);
				amount -= mainHandStack.getCount();

				if (amount > 0) {
					runeCounter.put(type, amount);
				}
				else {
					runeCounter.removeInt(type);
				}
			}
		}

		if (!runeCounter.isEmpty() && offHandStack.is(AoATags.Items.ADVENT_RUNE)) {
			Item type = offHandStack.getItem();

			if (runeCounter.containsKey(type)) {
				int amount = runeCounter.getInt(type);

				runeSlots.add(-2);
				amount -= offHandStack.getCount();

				if (amount > 0) {
					runeCounter.put(type, amount);
				}
				else {
					runeCounter.removeInt(type);
				}
			}
		}

		if (!runeCounter.isEmpty()) {
			for (int i = 0; i < player.getInventory().getContainerSize(); i++) {
				ItemStack stack = player.getInventory().getItem(i);

				if (stack.is(AoATags.Items.ADVENT_RUNE)) {
					Item type = stack.getItem();

					if (runeCounter.containsKey(type)) {
						int amount = runeCounter.getInt(type);

						runeSlots.add(i);
						amount -= stack.getCount();

						if (amount > 0) {
							runeCounter.put(type, amount);
						}
						else {
							runeCounter.removeInt(type);
						}

						if (runeCounter.isEmpty())
							break;
					}
				}
			}
		}

		if (runeCounter.isEmpty()) {
			if (runeSlots.contains(-1)) {
				ItemStack rune = player.getItemInHand(InteractionHand.MAIN_HAND);
				Item type = rune.getItem();
				int amount = requiredRunes.getInt(type);
				int remaining = amount - rune.getCount();

				rune.shrink(amount);

				if (remaining <= 0) {
					requiredRunes.removeInt(type);
				}
				else {
					requiredRunes.put(type, remaining);
				}

				runeSlots.remove(-1);
			}

			if (runeSlots.contains(-2)) {
				ItemStack rune = player.getItemInHand(InteractionHand.OFF_HAND);
				Item type = rune.getItem();
				int amount = requiredRunes.getInt(type);
				int remaining = amount - rune.getCount();

				rune.shrink(amount);

				if (remaining <= 0) {
					requiredRunes.removeInt(type);
				}
				else {
					requiredRunes.put(type, remaining);
				}

				runeSlots.remove(-2);
			}

			for (int slotId : runeSlots) {
				ItemStack rune = player.getInventory().getItem(slotId);
				Item type = rune.getItem();
				int amount = requiredRunes.getInt(type);
				int remaining = amount - rune.getCount();

				rune.shrink(amount);

				if (remaining <= 0) {
					requiredRunes.removeInt(type);
				}
				else {
					requiredRunes.put(type, remaining);
				}

				if (requiredRunes.isEmpty())
					break;
			}

			return true;
		}

		return false;
	}

@Override
	public void initialize() {
		if(type != null) {
			throw new IllegalStateException("NeoForge player data storage was initialized more than once");
		}
		DeferredRegister<AttachmentType<?>> attachments = DeferredRegister.create(
				NeoForgeRegistries.Keys.ATTACHMENT_TYPES, PsiAPI.MOD_ID);
		type = attachments.register("player_data", () -> AttachmentType.builder(() -> new PlayerData())
				.serialize(PlayerData.CODEC)
				.copyOnDeath()
				.build());
		attachments.register(NeoForgePsiPlatform.modBus());
	}

@Override
	public PlayerData get(Player player) {
		if(!player.hasData(type)) {
			CompoundTag legacy = legacyData(player);
			if(legacy != null) {
				PlayerData imported = new PlayerData();
				imported.readFromNBT(legacy);
				player.setData(type, imported);
			}
		}
		PlayerData data = player.getData(type);
		data.bind(player);
		return data;
	}

@Override
	public void save(Player player, PlayerData data) {
		player.setData(type, data);
	}

private static CompoundTag legacyData(Player player) {
		CompoundTag forgeData = player.getPersistentData();
		if(!forgeData.contains(Player.PERSISTED_NBT_TAG, Tag.TAG_COMPOUND)) {
			return null;
		}
		CompoundTag persisted = forgeData.getCompound(Player.PERSISTED_NBT_TAG);
		return persisted.contains(LEGACY_DATA_TAG, Tag.TAG_COMPOUND)
				? persisted.getCompound(LEGACY_DATA_TAG)
				: null;
	}

