@Override
	public boolean hurtEnemy(ItemStack stack, LivingEntity target, LivingEntity attacker)
	{
		if (attacker instanceof FakePlayer)
			return false;

		if (target == null || attacker == null || attacker.getCommandSenderWorld().isClientSide || (attacker instanceof Player && !(attacker instanceof ServerPlayer)))
			return false;

		if (!target.canChangeDimensions())
			return false;

		if (target instanceof Player)
			return false;

		if (target.isBaby() && !(target instanceof Enemy))
			return false;

		if (!target.isAlive() || target.getHealth() < 0.5F)
			return false;

//		EntityEntry entityEntry = EntityRegistry.getEntry(target.getClass());
//		if (entityEntry == null)
//			return false;
		ResourceLocation id = ForgeRegistries.ENTITY_TYPES.getKey(target.getType());
		int lifeEssenceRatio = BloodMagicAPI.INSTANCE.getValueManager().getSacrificial().getOrDefault(id, ConfigManager.COMMON.entitySacrificeDefault.get());
//		int lifeEssenceRatio = 25;

		if (lifeEssenceRatio <= 0)
			return false;

		int lifeEssence = (int) (lifeEssenceRatio * target.getHealth());
//		if (target instanceof AnimalEntity)
//		{
//			lifeEssence = (int) (lifeEssence * (1 + PurificationHelper.getCurrentPurity((AnimalEntity) target)));
//		}

		if (target.isBaby())
		{
			lifeEssence *= 0.5F;
		}

		if (PlayerSacrificeHelper.findAndFillAltar(attacker.getCommandSenderWorld(), target, lifeEssence, true))
		{
			target.getCommandSenderWorld().playSound(null, target.getX(), target.getY(), target.getZ(), SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 0.5F, 2.6F + (target.getCommandSenderWorld().random.nextFloat() - target.getCommandSenderWorld().random.nextFloat()) * 0.8F);
			target.setHealth(0.00001f);
			target.invulnerableTime = 0;
			target.hurt(target.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 10);
//			target.onDeath(DamageSourceBloodMagic.INSTANCE);
		}

		return false;
	}

@Override
	public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand)
	{
		boolean oneLevel = !player.isShiftKeyDown();

		ItemStack held = player.getItemInHand(hand);

		LivingStats armorStats = LivingStats.fromPlayer(player, true);
		if (armorStats == null)
			return InteractionResultHolder.pass(held);

		LivingStats tomeStats = getLivingStats(held);
		if (tomeStats == null)
			return InteractionResultHolder.pass(held);

		Map<LivingUpgrade, Double> upgradeMap = tomeStats.getUpgrades();

		boolean[] flag = new boolean[] { false };
		double[] expUsedArray = new double[upgradeMap.size()];
		int[] i = new int[] { 0 };
		upgradeMap.forEach((k, v) -> {
//			if (armorStats.getLevel(k.getKey()) >= tomeStats.getLevel(k.getKey()))
//				return;
			if (oneLevel)
			{
				double curExp = armorStats.getUpgrades().getOrDefault(k, 0d);
				double expToNextLevel = k.getNextRequirement((int) curExp) - curExp;

				v = Math.min(expToNextLevel, v);
			}

			Pair<LivingStats, Double> upgraded = LivingUtil.applyExperienceToUpgradeCap(player, k, v);
			// applyExperienceToUpgradeCap
			flag[0] = flag[0] || upgraded.getRight() > 0;
			expUsedArray[i[0]] = upgraded.getRight();
			i[0] = i[0] + 1;
		});
//        LivingStats.toPlayer(player, armorStats);
		if (flag[0])
		{
			Object[] upgradeArray = upgradeMap.entrySet().toArray();
//			tomeStats.addExperience(key, experience)
			for (int j = 0; j < expUsedArray.length; j++)
			{
				double expUsed = expUsedArray[j];
				if (expUsed > 0)
				{
					ResourceLocation key = ((Entry<LivingUpgrade, Double>) upgradeArray[j]).getKey().getKey();
//					if (((Entry<LivingUpgrade, Double>) upgradeArray[j]).getValue() < expUsed)
//					{
//						tomeStats.resetExperience(registryName);
//					} else
					{
						tomeStats.addExperience(key, -expUsed);
					}

					updateLivingStats(held, tomeStats);
				}
			}

			if (!player.isCreative())
			{
				boolean doShrink = true;
				for (Entry<LivingUpgrade, Double> entry : tomeStats.getUpgrades().entrySet())
				{
					LivingUpgrade upgrade = entry.getKey();
					int level = upgrade.getLevel(entry.getValue().intValue());
					if (level > 0)
					{
						doShrink = false;
					}
				}

				// Shrink the stack if the tome is empty
				if (doShrink)
				{
					held.shrink(1);
				}
			}

//			held.shrink(1);
			return InteractionResultHolder.success(held);
		} else
			return InteractionResultHolder.pass(held);
	}

@Override
	@OnlyIn(Dist.CLIENT)
	public void appendHoverText(ItemStack stack, Level world, List<Component> tooltip, TooltipFlag flag)
	{
		if (!stack.hasTag())
			return;

		Ritual ritual = BloodMagic.RITUAL_MANAGER.getRitual(this.getCurrentRitual(stack));
		if (ritual != null)
		{
			tooltip.add(Component.translatable("tooltip.bloodmagic.diviner.currentRitual", Component.translatable(ritual.getTranslationKey())).withStyle(ChatFormatting.GRAY));

			boolean sneaking = Screen.hasShiftDown();
//			boolean extraInfo = sneaking && Keyboard.isKeyDown(Keyboard.KEY_M);
			boolean extraInfo = sneaking && Screen.hasAltDown();

			if (extraInfo)
			{
				tooltip.add(Component.literal(""));

				for (EnumDemonWillType type : EnumDemonWillType.values())
				{
					if (TextHelper.canTranslate(ritual.getTranslationKey() + "." + type.name().toLowerCase(Locale.ROOT) + ".info"))
					{
						tooltip.add(Component.translatable(ritual.getTranslationKey() + "." + type.name().toLowerCase(Locale.ROOT) + ".info"));
					}
				}
			} else if (sneaking)
			{
				tooltip.add(Component.translatable(tooltipBase + "currentDirection", Utils.toFancyCasing(getDirection(stack).name())).withStyle(ChatFormatting.GRAY));
				tooltip.add(Component.literal(""));

				Tuple<Integer, Map<EnumRuneType, Integer>> runeCount = RitualHelper.countRunes(ritual);
				int totalRunes = runeCount.getA();
				Map<EnumRuneType, Integer> runeMap = runeCount.getB();
				for (EnumRuneType type : EnumRuneType.values())
				{
					int count = runeMap.getOrDefault(type, 0);
					if (count > 0)
					{
						tooltip.add(Component.translatable(tooltipBase + type.translationKey, count).withStyle(type.colorCode));
					}
				}
				tooltip.add(Component.literal(""));
				tooltip.add(Component.translatable(tooltipBase + "totalRune", totalRunes).withStyle(ChatFormatting.GRAY));
			} else
			{
				tooltip.add(Component.literal(""));
				if (TextHelper.canTranslate(ritual.getTranslationKey() + ".info"))
				{
					tooltip.add(Component.translatable(ritual.getTranslationKey() + ".info").withStyle(ChatFormatting.GRAY));
					tooltip.add(Component.literal(""));
				}

				tooltip.add(Component.translatable(tooltipBase + "extraInfo").withStyle(ChatFormatting.BLUE));
				tooltip.add(Component.translatable(tooltipBase + "extraExtraInfo").withStyle(ChatFormatting.BLUE));
			}
		}
	}

