private static ItemStack smelt(ItemStack stack, LootContext context)
		{
			return context.getLevel().getRecipeManager().getRecipeFor(RecipeType.SMELTING, new SimpleContainer(stack), context.getLevel())
					.map((a) -> a.getResultItem(context.getLevel().registryAccess()))
					.filter(itemStack -> !itemStack.isEmpty())
					.map(itemStack -> ItemHandlerHelper.copyStackWithSize(itemStack, stack.getCount() * itemStack.getCount()))
					.orElse(stack);
		}

public String getNextBlockRange(String range)
	{
		List<String> rangeList = getListOfRanges();

		if (rangeList.isEmpty())
		{
			return "";
		}

		if (!rangeList.contains(range))
		{
			return rangeList.get(0);
		}

		boolean hasMatch = false;

		for (String rangeCheck : rangeList)
		{
			if (hasMatch)
			{
				return rangeCheck;
			} else if (rangeCheck.equals(range))
			{
				hasMatch = true;
			}
		}

		return rangeList.get(0);
	}

