@Override
	public void performRitual(IMasterRitualStone masterRitualStone)
	{

//		System.out.println(desc);
		Level level = masterRitualStone.getWorldObj();
		int currentEssence = masterRitualStone.getOwnerNetwork().getCurrentEssence();

		if (currentEssence < getRefreshCost())
		{
			masterRitualStone.getOwnerNetwork().causeNausea();
			return;
		}

		BlockPos pos = masterRitualStone.getMasterBlockPos();
		List<EnumDemonWillType> willConfig = masterRitualStone.getActiveWillConfig();

		int mode = CRAFTING_MODE;

		if (willConfig.contains(EnumDemonWillType.STEADFAST))
		{
			double steadfastWill = this.getWillRespectingConfig(level, pos, EnumDemonWillType.STEADFAST, willConfig);

			mode = HELLFORGE_MODE;
			if (steadfastWill < MAX_STEADFAST_DRAIN)
			{
				return;
			}
		} else if (willConfig.contains(EnumDemonWillType.CORROSIVE))
		{
			double corrosiveWill = this.getWillRespectingConfig(level, pos, EnumDemonWillType.CORROSIVE, willConfig);

			mode = ALCHEMY_TABLE_MODE;
			if (corrosiveWill < MAX_CORROSIVE_DRAIN)
			{
				return;
			}
		}

		if (mode == CRAFTING_MODE)
		{
			attemptVanillaCrafting(masterRitualStone, level, pos);
		}

		if (mode == HELLFORGE_MODE)
		{
			AreaDescriptor forgeDesc = masterRitualStone.getBlockRange(HELLFORGED_RANGE);
//			System.out.println("Desc: " + forgeDesc.getAABB(pos));
			List<BlockPos> forgePosList = forgeDesc.getContainedPositions(pos);
			if (!forgePosList.isEmpty())
			{
//				System.out.println("Pos: " + forgePosList.get(0));
				BlockEntity forgeTile = level.getBlockEntity(forgePosList.get(0));
				if (forgeTile instanceof TileSoulForge)
				{
//					System.out.println("Have a forge");
					int operations = attemptHellforgedCrafting(masterRitualStone, level, pos, (TileSoulForge) forgeTile);
					if (operations > 0)
					{
						double steadfastDrained = Math.min(operations * steadfastWillDrain, MAX_STEADFAST_DRAIN);
						WorldDemonWillHandler.drainWill(level, pos, EnumDemonWillType.STEADFAST, steadfastDrained, true);
					}
				}
			}
		}

		if (mode == ALCHEMY_TABLE_MODE)
		{
			AreaDescriptor forgeDesc = masterRitualStone.getBlockRange(HELLFORGED_RANGE);
//			System.out.println("Desc: " + forgeDesc.getAABB(pos));
			List<BlockPos> forgePosList = forgeDesc.getContainedPositions(pos);
			if (!forgePosList.isEmpty())
			{
//				System.out.println("Pos: " + forgePosList.get(0));
				BlockEntity alchemyTile = level.getBlockEntity(forgePosList.get(0));
				if (alchemyTile instanceof TileAlchemyTable)
				{
					if (((TileAlchemyTable) alchemyTile).isSlave())
					{
						BlockEntity tile = level.getBlockEntity(((TileAlchemyTable) alchemyTile).getConnectedPos());
						if (tile instanceof TileAlchemyTable && !((TileAlchemyTable) tile).isSlave)
						{
							alchemyTile = tile;
						} else
						{
							return;
						}
					}

//					System.out.println("Have a table!");
					int operations = attemptAlchemyTableCrafting(masterRitualStone, level, pos, (TileAlchemyTable) alchemyTile);
					if (operations > 0)
					{
						double corrosiveDrained = Math.min(operations * corrosiveWillDrain, MAX_CORROSIVE_DRAIN);
						WorldDemonWillHandler.drainWill(level, pos, EnumDemonWillType.CORROSIVE, corrosiveDrained, true);
					}
				}
			}
		}
	}

public void attemptVanillaCrafting(IMasterRitualStone masterRitualStone, Level level, BlockPos pos)
	{
		ItemStack filterStack = getRecipeFilterStack(masterRitualStone, level, pos);
		if (filterStack.isEmpty())
		{
			return;
		}

		IItemHandler inputInv = this.getInputInventory(masterRitualStone, level, pos);
		if (inputInv == null)
		{
			return;
		}

		InventoryFilter filterInv = ItemRouterFilter.getInv(filterStack);
		CraftingContainer craftingContainer = makeContainer();

		for (int i = 0; i < filterInv.getSlots(); i++)
		{
			craftingContainer.setItem(i, filterInv.getStackInSlot(i));
		}

		List<CraftingRecipe> craftingRecipes = level.getRecipeManager().getRecipesFor(RecipeType.CRAFTING, craftingContainer, level);

		if (craftingRecipes.isEmpty())
		{
//			System.out.println("Crafting recipe is not valid.");
			return;
		}

		CraftingRecipe recipe = craftingRecipes.get(0);

		ItemStack outputFilterStack = getOutputFilterStack(masterRitualStone, level, pos);

		boolean doLimit = false;
		int craftLimit = 0;

		if (!outputFilterStack.isEmpty())
		{
			IItemFilter outputFilter = ((IItemFilterProvider) outputFilterStack.getItem()).getUninitializedItemFilter(outputFilterStack);

			if (craftingRecipes.size() > 1)
			{
				boolean foundRecipe = false;
				for (CraftingRecipe testRecipe : craftingRecipes)
				{
					ItemStack resultStack = testRecipe.getResultItem(level.registryAccess());
					if (outputFilter.doesStackPassFilter(resultStack))
					{
						recipe = testRecipe;
						foundRecipe = true;
						break;
					}
				}

				if (!foundRecipe)
				{
					return;
				}
			}

			List<IFilterKey> keyList = outputFilter.getFilterList();
			for (IFilterKey outputKey : keyList)
			{
				int count = outputKey.getCount();
				if (count == 0)
				{
					doLimit = false;
					break;
				}

				doLimit = true;

				craftLimit += Math.abs(count);
			}

			if (doLimit)
			{
				craftLimit += (recipe.getResultItem(level.registryAccess()).getCount() - 1);
			}
		}

		IItemFilter itemRecipeFilter = ((IItemFilterProvider) filterStack.getItem()).getUninitializedItemFilter(filterStack);

		// Map that stores the slots that are going to be syphoned from.
		Map<Integer, Integer> selectedMap = new HashMap<>();
		List<IFilterKey> filterKeyList = itemRecipeFilter.getFilterList();
		int filterKeyIndex = 0;

		for (int filterSlot = 0; filterSlot < Math.min(filterInv.getSlots(), 9); filterSlot++)
		{
			ItemStack filterKeyStack = filterInv.getStackInSlot(filterSlot);
			if (filterKeyStack.isEmpty())
			{
				continue;
			}

			if (filterKeyIndex >= filterKeyList.size())
			{
				// Broken filter!
				return;
			}

			boolean hasSucceeded = false;
			IFilterKey filterKey = filterKeyList.get(filterKeyIndex);

			for (int invSlot = 0; invSlot < inputInv.getSlots(); invSlot++)
			{
				ItemStack invStack = inputInv.getStackInSlot(invSlot);
				int claimedAmount = selectedMap.getOrDefault(invSlot, 0);
				if (invStack.getCount() < (claimedAmount + 1))
				{
					continue;
				}

				if (filterKey.doesStackMatch(invStack))
				{
					ItemStack extractedStack = inputInv.extractItem(invSlot, 1, true);
					if (extractedStack.isEmpty())
					{
						continue;
					}

					selectedMap.put(invSlot, 1 + claimedAmount);
					craftingContainer.setItem(filterSlot, extractedStack);

					hasSucceeded = true;
					break;
				}
			}

			filterKeyIndex++;

			if (!hasSucceeded)
			{
				// Didn't manage to find an available input item!
//				System.out.println("Didn't find the item");
				return;
			}
		}

        if (!recipe.matches(craftingContainer, level)) {
            return;
        }

		AreaDescriptor outputDesc = masterRitualStone.getBlockRange(OUTPUT_CHEST_RANGE);
		List<BlockPos> outputPosList = outputDesc.getContainedPositions(pos);
		BlockEntity outputTile = null;
		IItemHandler outputInv = null;
		BlockPos outputPos = pos;

		if (!outputPosList.isEmpty())
		{
			outputPos = outputPosList.get(0);
			outputTile = level.getBlockEntity(outputPos);
		} else
		{
			outputPos = pos.above(2);
		}

		if (outputTile != null)
		{
			outputInv = Utils.getInventory(outputTile, null);
		}

		ItemStack resultStack = recipe.assemble(craftingContainer, level.registryAccess());

		boolean doCraft = true;
		if (outputInv != null)
		{
			doCraft = false;
			if (Utils.canInsertStackFullyIntoInventory(resultStack, outputInv, doLimit, craftLimit))
			{
				doCraft = true;
			}
		}

		if (doCraft)
		{
			List<ItemStack> insertionList = new ArrayList<>();
			insertionList.add(resultStack);

			for (Entry<Integer, Integer> syphonEntry : selectedMap.entrySet())
			{
				int slot = syphonEntry.getKey();
				int syphonAmount = syphonEntry.getValue();
				ItemStack syphonStack = inputInv.extractItem(slot, syphonAmount, false);
				if (syphonStack.hasCraftingRemainingItem())
				{
					ItemStack containedStack = syphonStack.getCraftingRemainingItem();
					if (inputInv.isItemValid(slot, containedStack))
					{
						ItemStack remainderStack = inputInv.insertItem(slot, containedStack, false);
						if (!remainderStack.isEmpty())
						{
							insertionList.add(remainderStack);
						}
					} else
					{
						insertionList.add(containedStack);
					}
				}
			}

			if (outputInv != null)
			{
				for (ItemStack insertedStack : insertionList)
				{
					ItemStack remainder = Utils.insertStackIntoTile(insertedStack, outputInv, true);
					if (!remainder.isEmpty())
					{
						Utils.spawnStackAtBlock(level, outputPos, Direction.UP, remainder);
					}
				}
			} else
			{
				for (ItemStack insertedStack : insertionList)
				{
					Utils.spawnStackAtBlock(level, outputPos, Direction.UP, insertedStack);
				}
			}

			masterRitualStone.getOwnerNetwork().syphon(masterRitualStone.ticket(getRefreshCost()));

//			return insertionList;
		}
	}

@Override
	public void performRitual(IMasterRitualStone masterRitualStone)
	{
		Level world = masterRitualStone.getWorldObj();
		int currentEssence = masterRitualStone.getOwnerNetwork().getCurrentEssence();

		BlockPos masterPos = masterRitualStone.getMasterBlockPos();
		AreaDescriptor chestRange = masterRitualStone.getBlockRange(CHEST_RANGE);
		BlockEntity tileInventory = world.getBlockEntity(chestRange.getContainedPositions(masterPos).get(0));

		if (world.isClientSide)
		{
			return;
		}

		if (tileInventory != null && Utils.getNumberOfFreeSlots(tileInventory, Direction.DOWN) < 1)
		{
			return;
		}

		if (currentEssence < getRefreshCost())
		{
			masterRitualStone.getOwnerNetwork().causeNausea();
			return;
		}

		if (!cached || treePartsCache.isEmpty())
		{
			for (BlockPos blockPos : masterRitualStone.getBlockRange(FELLING_RANGE).getContainedPositions(masterRitualStone.getMasterBlockPos()))
			{
				if (!treePartsCache.contains(blockPos))
					if (!world.isEmptyBlock(blockPos) && (world.getBlockState(blockPos).is(BlockTags.LOGS) || world.getBlockState(blockPos).is(BlockTags.LEAVES)))
					{
						treePartsCache.add(blockPos);
					}
			}

			cached = true;
			blockPosIterator = treePartsCache.iterator();
		}

		if (blockPosIterator.hasNext() && tileInventory != null)
		{
			currentPos = blockPosIterator.next();

			// Check protection before breaking
			if (!BlockProtectionHelper.canBreakBlock(world, currentPos, masterRitualStone.getOwner()))
			{
				blockPosIterator.remove();
				return;
			}

			masterRitualStone.getOwnerNetwork().syphon(masterRitualStone.ticket(getRefreshCost()));
			IItemHandler inventory = Utils.getInventory(tileInventory, Direction.DOWN);
			BlockState state = world.getBlockState(currentPos);
			placeInInventory(state, world, currentPos, inventory);

			BlockPlaceContext ctx = new BlockPlaceContext(world, null, InteractionHand.MAIN_HAND, ItemStack.EMPTY, BlockHitResult.miss(new Vec3(0, 0, 0), Direction.UP, currentPos));
			spawnParticlesAndSound((ServerLevel) world, currentPos, state, ctx);

			world.setBlockAndUpdate(currentPos, Blocks.AIR.defaultBlockState());
			blockPosIterator.remove();
		}
	}

@Override
	public void performRitual(IMasterRitualStone masterRitualStone)
	{
		Level world = masterRitualStone.getWorldObj();
		BlockPos masterPos = masterRitualStone.getMasterBlockPos();
		Direction direction = masterRitualStone.getDirection();

		Player selectedPlayer = null;
		AreaDescriptor downgradeRange = masterRitualStone.getBlockRange(DOWNGRADE_RANGE);

		for (Player player : world.getEntitiesOfClass(Player.class, downgradeRange.getAABB(masterRitualStone.getMasterBlockPos())))
		{
			if (!player.isCrouching() && LivingUtil.hasFullSet(player))
			{
				selectedPlayer = player;
				break;
			}
		}

		if (selectedPlayer == null)
		{
			return;
		}

		LivingStats playerStats = LivingStats.fromPlayer(selectedPlayer, true);

//		System.out.println("Found a downgrade!");

		BlockPos chestOffsetPos = new BlockPos(0, 1, 0);
		chestOffsetPos = chestOffsetPos.relative(direction, 2);

		BlockPos chestPos = masterPos.offset(chestOffsetPos);

		BlockEntity tile = world.getBlockEntity(chestPos);

		if (tile == null)
		{
			selectedPlayer.displayClientMessage(Component.translatable("chat.bloodmagic.ritualLivingDowngrade.missingInventory", chestPos.getX(), chestPos.getY(), chestPos.getZ()), true);
			return;
		}

		// Contains the desired levels for each upgrade.
		Map<LivingUpgrade, Integer> downgradeMap = new HashMap<>();

		int availablePoints = 0;
//		int wantedLevel = 0;
		Direction accessDir = Direction.DOWN;

		Map<Integer, List<Integer>> priorityMap = new HashMap<>();
		// Contains the ItemStack used for each downgrade.  Used for the insufficient level message.
		Map<LivingUpgrade, ItemStack> downgradeItemStacksMap= new HashMap<>();

		LazyOptional<IItemHandler> capability = tile.getCapability(ForgeCapabilities.ITEM_HANDLER, accessDir);
		if (capability.isPresent())
		{
			IItemHandler handler = capability.resolve().get();

			for (int i = 0; i < handler.getSlots(); i++)
			{
				ItemStack invStack = handler.getStackInSlot(i);
				availablePoints += getAvailablePointsFromStack(invStack);
				LivingUpgrade downgrade = getDowngradeFromStack(world, invStack);
				if (downgrade != null && downgrade != LivingUpgrade.DUMMY)
				{
					int wantedLevel = getLevelFromStack(invStack);
					downgradeMap.put(downgrade, downgradeMap.getOrDefault(downgrade, 0) + wantedLevel);
					downgradeItemStacksMap.put(downgrade, invStack);
				}

				int priority = getPriorityFromStack(invStack);
				if (priority >= 0)
				{
					if (priorityMap.containsKey(priority))
					{
						priorityMap.get(priority).add(i);
					} else
					{
						ArrayList<Integer> priorityList = new ArrayList<Integer>();
						priorityList.add(i);
						priorityMap.put(priority, priorityList);
					}
				}
			}
		} else if (tile instanceof Container)
		{
			for (int i = 0; i < ((Container) tile).getContainerSize(); i++)
			{
				ItemStack invStack = ((Container) tile).getItem(i);
				availablePoints += getAvailablePointsFromStack(invStack);
				LivingUpgrade downgrade = getDowngradeFromStack(world, invStack);
				if (downgrade != null && downgrade != LivingUpgrade.DUMMY)
				{
					int wantedLevel = getLevelFromStack(invStack);
					downgradeMap.put(downgrade, downgradeMap.getOrDefault(downgrade, 0) + wantedLevel);
					downgradeItemStacksMap.put(downgrade, invStack);
				}

				int priority = getPriorityFromStack(invStack);
				if (priority >= 0)
				{
					if (priorityMap.containsKey(priority))
					{
						priorityMap.get(priority).add(i);
					} else
					{
						ArrayList<Integer> priorityList = new ArrayList<Integer>();
						priorityList.add(i);
						priorityMap.put(priority, priorityList);
					}
				}
			}
		}

		if (downgradeMap.isEmpty())
		{
			return;
		}

		// TODO: Change when chest logic is implemented.

		// Stores the difference in points between the player's armour and the requested
		// downgrade. 0 means nothing is added.
		Map<LivingUpgrade, Integer> pointDifferentialMap = new HashMap<LivingUpgrade, Integer>();
		int totalDifferentialPoints = 0;
		LivingUpgrade lastSkippedDowngrade = null;
		for (Entry<LivingUpgrade, Integer> entry : downgradeMap.entrySet())
		{
			LivingUpgrade downgrade = entry.getKey();
			int playerDowngradeLevel = playerStats.getLevel(downgrade.getKey());
			int wantedLevel = Math.min(entry.getValue(), downgrade.getLevel(Integer.MAX_VALUE));
			if (playerDowngradeLevel >= wantedLevel)
			{
				lastSkippedDowngrade = downgrade;
				continue;
			}

			if (!LivingUtil.canTrain(selectedPlayer, downgrade, playerDowngradeLevel, wantedLevel))
			{
				selectedPlayer.displayClientMessage(Component.translatable("chat.bloodmagic.ritualLivingDowngrade.trainingBraceletBlock"), true);
				return;
			}

			int playerInitialPoints = 0;
			if (playerDowngradeLevel > 0)
			{
				playerInitialPoints = playerStats.getUpgrades().getOrDefault(downgrade, 0d).intValue();
			}

			int totalRequiredPoints = Math.abs(downgrade.getLevelCost(wantedLevel));
			int upgradeRequiredPoints = totalRequiredPoints - playerInitialPoints;
			if (upgradeRequiredPoints > 0)
			{
				pointDifferentialMap.put(downgrade, upgradeRequiredPoints);
				totalDifferentialPoints += upgradeRequiredPoints;
			}
		}

		if (availablePoints < totalDifferentialPoints)
		{
			selectedPlayer.displayClientMessage(Component.translatable("chat.bloodmagic.ritualLivingDowngrade.notEnoughPoints"), true);
			return;
		}
		if (priorityMap.isEmpty() || pointDifferentialMap.isEmpty())
		{
			if (lastSkippedDowngrade != null)
			{
				String itemName = downgradeItemStacksMap.get(lastSkippedDowngrade).getItem().getDefaultInstance().getDisplayName().getString();
				int lastCharIndex = itemName.length() - 1;
				if (itemName.charAt(0) == '[' && itemName.charAt(lastCharIndex) == ']')
				{
					itemName = itemName.substring(1, lastCharIndex); // remove the brackets around the item name.
				}
				selectedPlayer.displayClientMessage(Component.translatable("chat.bloodmagic.ritualLivingDowngrade.notEnoughKeyItems", itemName), true);
			}
			return;
		}

		List<Integer> slotOrderList = new ArrayList<>();

		List<Integer> priorityList = new ArrayList<>(priorityMap.keySet());

		Collections.sort(priorityList);
		for (int priority : priorityList)
		{
			slotOrderList.addAll(priorityMap.get(priority));
		}

		// Consumption logic
		int requiredPoints = totalDifferentialPoints;
		int initialRequiredPoints = requiredPoints;
//		System.out.println("Initial required points: " + requiredPoints);

		List<ItemStack> excessStackList = new ArrayList<>();

		if (capability.isPresent())
		{
			IItemHandler handler = capability.resolve().get();

			for (int i : slotOrderList)
			{
				ItemStack invStack = handler.getStackInSlot(i);
				if (!invStack.isEmpty() && invStack.getItem() instanceof ILivingUpgradePointsProvider)
				{
					ItemStack simStack = handler.extractItem(i, invStack.getCount(), true);

					int containedPoints = ((ILivingUpgradePointsProvider) simStack.getItem()).getAvailableUpgradePoints(simStack, requiredPoints);
					int drainPoints = Math.min(containedPoints, requiredPoints);
					int remainingPointsInItem = ((ILivingUpgradePointsProvider) simStack.getItem()).getExcessUpgradePoints(simStack, drainPoints);
					ItemStack newItemStack = ((ILivingUpgradePointsProvider) simStack.getItem()).getResultingStack(simStack, drainPoints);

					if (newItemStack.isEmpty() || handler.isItemValid(i, newItemStack))
					{
						// Actual number of points syphoned from the item.
						int totalPoints = ((ILivingUpgradePointsProvider) simStack.getItem()).getTotalUpgradePoints(simStack);
						int totalDrainedPoints = (totalPoints - remainingPointsInItem);
//						System.out.println("Contained points: " + containedPoints + ", remaining points: " + remainingPointsInItem);
						requiredPoints -= totalDrainedPoints;
						handler.extractItem(i, simStack.getCount(), false);
						ItemStack remainingStack = handler.insertItem(i, newItemStack, false);

						if (!remainingStack.isEmpty())
						{
							excessStackList.add(remainingStack);
						}

						if (requiredPoints <= 0)
						{
							break;
						}
					}
				}
			}
		} else if (tile instanceof Container)
		{
			for (int i : slotOrderList)
			{
				ItemStack invStack = ((Container) tile).getItem(i);
				if (!invStack.isEmpty() && invStack.getItem() instanceof ILivingUpgradePointsProvider)
				{
					int drainPoints = Math.min(((ILivingUpgradePointsProvider) invStack.getItem()).getAvailableUpgradePoints(invStack, requiredPoints), requiredPoints);
					int remainingPointsInItem = ((ILivingUpgradePointsProvider) invStack.getItem()).getExcessUpgradePoints(invStack, drainPoints);
					ItemStack newItemStack = ((ILivingUpgradePointsProvider) invStack.getItem()).getResultingStack(invStack, drainPoints);

					requiredPoints -= (drainPoints - remainingPointsInItem);
					((Container) tile).setItem(i, newItemStack);

					if (requiredPoints <= 0)
					{
						break;
					}
				}
			}
		}

		if (requiredPoints < 0)
		{
			ItemStack scrapStack = new ItemStack(BloodMagicItems.UPGRADE_SCRAPS.get());
			((ItemLivingTomeScrap) BloodMagicItems.UPGRADE_SCRAPS.get()).setTotalUpgradePoints(scrapStack, Math.abs(requiredPoints));
			excessStackList.add(scrapStack);
		}

		// TODO: Apply ALL upgrades.
		if (requiredPoints <= 0)
		{
			for (Entry<LivingUpgrade, Integer> entry : pointDifferentialMap.entrySet())
			{
				LivingUtil.applyExperienceToUpgradeCap(selectedPlayer, entry.getKey(), entry.getValue());
			}

			masterRitualStone.setActive(false);

			LightningBolt lightningboltentity = EntityType.LIGHTNING_BOLT.create(world);
			lightningboltentity.setPos(masterPos.getX() + 0.5, masterPos.getY(), masterPos.getZ() + 0.5);
			world.addFreshEntity(lightningboltentity);
		} else if (requiredPoints < initialRequiredPoints)
		{
			ItemStack scrapStack = new ItemStack(BloodMagicItems.UPGRADE_SCRAPS.get());
			((ItemLivingTomeScrap) BloodMagicItems.UPGRADE_SCRAPS.get()).setTotalUpgradePoints(scrapStack, Math.abs(initialRequiredPoints - requiredPoints));
			excessStackList.add(scrapStack);
		}

		for (ItemStack item : excessStackList)
		{
			ItemStack copyStack = item.copy();

			if (tile != null)
			{
				copyStack = Utils.insertStackIntoTile(copyStack, tile, Direction.DOWN);
			} else
			{
				Utils.spawnStackAtBlock(world, chestPos, Direction.UP, copyStack);
				continue;
			}
			if (!copyStack.isEmpty())
			{
				Utils.spawnStackAtBlock(world, chestPos, Direction.UP, copyStack);
			}
		}
	}

public LivingUpgrade getDowngradeFromStack(Level world, ItemStack focusStack)
	{
		if (focusStack.isEmpty())
		{
			return LivingUpgrade.DUMMY;
		}

		if (!(focusStack.getItem() instanceof ILivingUpgradePointsProvider))
		{
			RecipeLivingDowngrade downgradeRecipe = BloodMagicAPI.INSTANCE.getRecipeRegistrar().getLivingDowngrade(world, focusStack);
			if (downgradeRecipe != null)
			{
				return LivingArmorRegistrar.UPGRADE_MAP.getOrDefault(downgradeRecipe.getLivingArmourResource(), LivingUpgrade.DUMMY);
			}

//			LivingUpgrade downgrade = LivingArmorRegistrar.UPGRADE_MAP.get(downgradeRecipe.getLivingArmourResource());

		}

		return LivingUpgrade.DUMMY;
	}

