            float rampOut = 0F;
            if (in != null && out != null) {
                rampIn = ramps * 0.5F;
                rampOut = ramps * 0.5F;
            } else if (in != null) {
                rampIn = ramps;
            } else {
                rampOut = ramps;
            }
            if (rampIn > 0F && t < rampIn) {
                return apply(in, t / rampIn);
            }
            var outStart = 1F - rampOut;
            if (rampOut > 0F && t > outStart) {
                return 1F - apply(out, (t - outStart) / rampOut);
            }
            return 1F;
        }

private static float clamp01(float value) {
            return value < 0F ? 0F : (value > 1F ? 1F : value);
        }

public static Curve fadeIn(Easing in, float hold) {
            return new Curve().in(in).hold(hold);
        }

public static Curve fadeOut(Easing out, float hold) {
            return new Curve().out(out).hold(hold);
        }

public static Curve fadeInOut(Easing in, Easing out, float hold) {
            return new Curve().in(in).out(out).hold(hold);
        }

public Curve copy() {
            var copy = new Curve();
            copy.in = this.in;
            copy.out = this.out;
            copy.hold = this.hold;
            return copy;
        }

public ClientCastController(ClientPlayerEntity player) {
        this.player = player;
    }

@Nullable public SpellCast.Process predictedProcess() {
        return predictedProcess;
    }

public List<Entity> currentTargets() {
        var targets = spellTarget.entities();
        if (targets == null) {
            return List.of();
        }
        return targets;
    }

@Nullable public SpellCast.Progress progress() {
        if (predictedProcess != null) {
            return predictedProcess.progress(player.getWorld().getTime());
        }
        return null;
    }

private void setProcess(@Nullable SpellCast.Process newValue) {
        predictedProcess = newValue;
    }

public SpellCast.Attempt startSpellCast(ItemStack itemStack, RegistryEntry<Spell> spellEntry) {
        if (player.isSpectator()) {
            return SpellCast.Attempt.none();
        }
        if (spellEntry == null) {
            this.cancelSpellCast();
            return SpellCast.Attempt.none();
        }
        var spell = spellEntry.value();
        var spellId = spellEntry.getKey().get().getValue();
        if ((predictedProcess != null && predictedProcess.id().equals(spellId))
                || spell == null) {
            return SpellCast.Attempt.none();
        }
        if (EntityActionsAllowed.isImpaired(player, EntityActionsAllowed.Player.CAST_SPELL, true)) {
            return SpellCast.Attempt.none();
        }
        var attempt = SpellCasting.attempt(player, itemStack, spellId);
        if (attempt.isSuccess()) {
            if (predictedProcess != null) {
                // Cancel previous spell
                cancelSpellCast();
            }
            var instant = SpellParameters.isInstantCast(spellEntry, player);
            if (instant) {
                // One-shot targeting at the input frame, shipped with the request; no process
                var targetResult = SpellTarget.findTargets(player, spellEntry, SpellTarget.SearchResult.empty(), SpellEngineClient.config.filterInvalidTargets, targetingRange(spellEntry));
                Platform.util().networkC2S_Send(new Packets.CastRequest(spellId, snapshotFor(spellEntry, targetResult)));
                applyInstantGlobalCooldown();
            } else {
                // Predicted process only (display); the server starts its own on the request.
                // Current aim rides along so the server has targets from tick one.
                var details = SpellParameters.getCastTimeDetails(player, spell);
                setProcess(new SpellCast.Process(player, spellEntry, itemStack.getItem(), details.speed(), details.length(), player.getWorld().getTime()));
                predictionConfirmed = false;
                spellTarget = SpellTarget.findTargets(player, spellEntry, SpellTarget.SearchResult.empty(), SpellEngineClient.config.filterInvalidTargets, targetingRange(spellEntry));
                var snapshot = snapshotFor(spellEntry, spellTarget);
                lastSentSnapshot = snapshot; // the request seeds the server's slot; the stream dedups against it
                Platform.util().networkC2S_Send(new Packets.CastRequest(spellId, snapshot));
            }
        }
        return attempt;
    }

private void applyInstantGlobalCooldown() {
        var duration = SpellEngineMod.config.spell_instant_cast_global_cooldown;
        if (duration > 0) {
            for (var slot: SpellHotbar.INSTANCE.slots) {
                var spellEntry = slot.spell();
                if (spellEntry == null) {
                    // Some slots may not have spells (such as item usage bypass slot)
                    continue;
                }
                var spell = spellEntry.value();
                if (spell.active != null && spell.active.cast != null && spell.active.cast.duration <= 0) {
                    ((SpellCaster.Client) player).getCooldownManager().set(spellEntry, duration, false);
                }
            }
        }
    }

public void cancelSpellCast() {
        var process = this.predictedProcess;
        if (process != null) {
            // End-input: the server decides what ending means for this mechanic
            // (cancel / early channel completion / charge release).
            Platform.util().networkC2S_Send(new Packets.CastInput(process.id(), snapshotFor(process.spell(), spellTarget)));
        }
        endPrediction();
    }

public void releaseCharge() {
        var process = this.predictedProcess;
        if (process == null) {
            return;
        }
        Platform.util().networkC2S_Send(new Packets.CastInput(process.id(), snapshotFor(process.spell(), spellTarget)));
        endPrediction();
    }

public void tick() {
        var process = this.predictedProcess;
        if (process != null) {
            var caster = (SpellCaster.Client) player;
            if (!player.isAlive()
                    || player.getMainHandStack().getItem() != process.item()
                    || caster.getCooldownManager().isCoolingDown(process.spell())
                    || EntityActionsAllowed.isImpaired(player, EntityActionsAllowed.Player.CAST_SPELL, true)
            ) {
                cancelSpellCast();
                return;
            }
            var spell = process.spell().value();
            spellTarget = SpellTarget.findTargets(player, process.spell(), spellTarget, SpellEngineClient.config.filterInvalidTargets, targetingRange(process.spell()));
            streamTargets(process);

            // Prediction only — the server owns the timeline and fires on its own clock.
            var mode = SpellCast.Mode.from(spell);
            var castTicks = process.spellCastTicksSoFar(player.getWorld().getTime());
            var declared = caster.getInteractor().process();
            var declaredMatches = declared != null && declared.id().equals(process.id());
            if (declaredMatches) {
                predictionConfirmed = true;
            }
            if (predictionConfirmed) {
                // The prediction ends when the SERVER'S declared process ends (it fired,
                // completed or cancelled) — never at client-computed completion. The client
                // clock starts at the input frame, the server's ~latency later; ending here
                // at client completion let a held-key re-cast supersede a server process one
                // tick away from firing (release swallowed, cast "restarts"). (Bug#1)
                if (!declaredMatches) {
                    endPrediction();
                    return;
                }
            } else if (castTicks > RECONCILE_GRACE_TICKS) {
                endPrediction(); // the server never confirmed this cast — rejected
                return;
            }
            // Fallback: end an overrun prediction even if the declaration was lost
            if (mode != SpellCast.Mode.CHARGED
                    && castTicks >= process.length() + RECONCILE_GRACE_TICKS) {
                endPrediction();
            }
        } else {
            spellTarget = SpellTarget.SearchResult.empty();
        }
    }

public List<SpellCast.Option> displayOptions() {
        var declared = ((SpellCaster.Player) player).getInteractor().options();
        var containers = SpellContainerSource.getSpellsOf(player);
        if (containers != lastSeenContainers) {
            // The client's container state changed (e.g. a weapon swap applied locally) —
            // predict until the server's declaration reflects it
            lastSeenContainers = containers;
            predictedOptions = SpellCast.Option.allOf(player);
            if (predictedOptions.equals(declared)) {
                predictingOptions = false;
            } else {
                predictingOptions = true;
                declaredAtPredictionStart = declared;
                optionsPredictionStartedAt = player.age;
            }
        }
        if (predictingOptions) {
            var declarationArrived = !declared.equals(declaredAtPredictionStart);
            var timedOut = player.age - optionsPredictionStartedAt > OPTIONS_PREDICTION_TIMEOUT_TICKS;
            if (declarationArrived || timedOut) {
                predictingOptions = false;
            } else {
                return predictedOptions;
            }
        }
        return declared;
    }

private void endPrediction() {
        setProcess(null);
        spellTarget = SpellTarget.SearchResult.empty();
        predictionConfirmed = false;
    }

private float targetingRange(RegistryEntry<Spell> spellEntry) {
        var id = spellEntry.getKey().get().getValue();
        for (var option : ((SpellCaster.Player) player).getInteractor().options()) {
            if (option.id().equals(id)) {
                return option.range();
            }
        }
        return SpellParameters.getMaxRange(player, spellEntry);
    }

private static SpellCast.TargetSnapshot snapshotFor(RegistryEntry<Spell> spellEntry, SpellTarget.SearchResult targetResult) {
        return SpellCast.Option.Targeting.of(spellEntry.value()).clientResolved()
                ? SpellCast.TargetSnapshot.of(targetResult)
                : SpellCast.TargetSnapshot.EMPTY;
    }

private void streamTargets(SpellCast.Process process) {
        if (!SpellCast.Option.Targeting.of(process.spell().value()).clientResolved()) {
            return;
        }
        var snapshot = SpellCast.TargetSnapshot.of(spellTarget);
        if (snapshot.equals(lastSentSnapshot)) {
            return; // Unchanged aim — silence means "unchanged", the server's copy stays valid
        }
        lastSentSnapshot = snapshot;
        Platform.util().networkC2S_Send(new Packets.TargetStream(process.id(), snapshot));
    }

public Reaction keyHeld(SpellCast.Option option, boolean freshForStart, boolean freshForStop) {
        switch (option.mode()) {
            case INSTANT -> {
                var attempt = startSpellCast(player.getMainHandStack(), option.spell());
                return new Reaction(Reaction.Type.STARTED, attempt);
            }
            case CASTING, CHANNEL -> {
                if (isCastingSame(option)) {
                    if (!holdToCast(option) && freshForStop) {
                        cancelSpellCast();
                        return new Reaction(Reaction.Type.STOPPED, null);
                    }
                } else if (freshForStart) {
                    var attempt = startSpellCast(player.getMainHandStack(), option.spell());
                    return new Reaction(Reaction.Type.STARTED, attempt);
                }
            }
            case CHARGED -> {
                if (isCastingSame(option)) {
                    if (!SpellEngineClient.config.holdToCastCharged && freshForStop) {
                        releaseCharge();
                        return new Reaction(Reaction.Type.RELEASED, null);
                    }
                } else if (freshForStart) {
                    var attempt = startSpellCast(player.getMainHandStack(), option.spell());
                    return new Reaction(Reaction.Type.STARTED, attempt);
                }
            }
            case PASSIVE, ITEM_USE -> { }
        }
        return Reaction.NOTHING;
    }

public boolean keyUp(SpellCast.Option option) {
        if (!isCastingSame(option)) { return false; }
        switch (option.mode()) {
            case CASTING, CHANNEL -> {
                if (holdToCast(option)) {
                    cancelSpellCast();
                    return true;
                }
            }
            case CHARGED -> {
                if (SpellEngineClient.config.holdToCastCharged) {
                    releaseCharge();
                    return true;
                }
            }
            default -> { }
        }
        return false;
    }

private boolean isCastingSame(SpellCast.Option option) {
        return predictedProcess != null && predictedProcess.id().equals(option.id());
    }

private static boolean holdToCast(SpellCast.Option option) {
        return option.mode() == SpellCast.Mode.CHANNEL
                ? SpellEngineClient.config.holdToCastChannelled
                : SpellEngineClient.config.holdToCastCharged;
    }

public static void addSpellLines(ItemStack itemStack, TooltipType tooltipType, List<Text> lines) {
        var player = MinecraftClient.getInstance().player;
        if (player == null) {
            return;
        }
        int addSectionDivider = 0;
        var config = SpellEngineClient.config;
        var spellTextLines = new ArrayList<Text>();

        var choices = SpellChoices.from(itemStack);
        var container = SpellContainerHelper.containerFromItemStack(itemStack);
        if (container != null && container.isValid()) {
            if (container.isResolver() && config.showSpellBookSuppportTooltip) {
                switch (container.access()) {
                    case ANY -> {
                        spellTextLines.add(Text.translatable("spell.tooltip.container.access.any")
                                .formatted(Formatting.GRAY));
                    }
                    case MAGIC -> {
                        spellTextLines.add(Text.translatable("spell.tooltip.container.access.spell")
                                .formatted(Formatting.GRAY));
                    }
                    case ARCHERY -> {
                        spellTextLines.add(Text.translatable("spell.tooltip.container.access.archery")
                                .formatted(Formatting.GRAY));
                    }
                    case TAG -> {
                        if (!container.access_param().isBlank()) {
                            var id = Identifier.tryParse(container.access_param());
                            if (id != null) {
                                var key = "spell.tooltip.container.access.tag." + id.getNamespace() + "." + id.getPath();
                                if (Language.getInstance().hasTranslation(key)) {
                                    spellTextLines.add(Text.translatable(key)
                                            .formatted(Formatting.GRAY));
                                }
                            }
                        }
                    }
                }
                addSectionDivider += 1;
            }
        }
        if (choices != null) {
            var spellInfo = getSpellChoiceInfo(choices, player);
            spellTextLines.addAll(spellInfo.content());
            addSectionDivider += spellInfo.sectionDividersAdded();
        }
        if (container != null && container.isValid()) {
            var spellInfo = getSpellInfoExpandedWithKey(itemStack, container, player, false, true);
            spellTextLines.addAll(spellInfo.content());
            addSectionDivider += spellInfo.sectionDividersAdded();
        }

        if (spellTextLines.isEmpty()) {
            return;
        }
        var found = 0;
        if (tooltipType.isAdvanced()) {
            var searchedStyle = Text.literal("x")
                    .formatted(Formatting.DARK_GRAY)
                    .getStyle(); // From: ItemStack.java, advanced tooltip section
            var reverseIndex = lines.size();
            for (var line : lines.reversed()) {
                --reverseIndex;
                var style = line.getStyle();
                if (style != null) {
                    var newFind = searchedStyle.getColor().equals(style.getColor());
                    if (found != 0 && !newFind) {
                        break;
                    } else {
                        found = reverseIndex;
                    }
                }
            }
        }
        if (found <= 0) {
            if (addSectionDivider > 0) {
                spellTextLines.addFirst(Text.literal(""));
            }
            lines.addAll(spellTextLines);
        } else {
            if (addSectionDivider > 0) {
                boolean hasPreceedignEmptyLine = false;
                if (found > 0) {
                    var previousLine = lines.get(found - 1).getString();
                    hasPreceedignEmptyLine = previousLine.isBlank();
                }
                if (!hasPreceedignEmptyLine) {
                    spellTextLines.addFirst(Text.literal(""));
                }
            }
            lines.addAll(found, spellTextLines);
        }
    }

public static @NotNull SpellTooltip.SpellInfo getSpellInfoExpandedWithKey(
            ItemStack itemStack, SpellContainer container, PlayerEntity player,
            boolean forceHideHeader, boolean allowDetailsHint) {
        var config = SpellEngineClient.config;
        var keybinding = detailsKeybinding();
        var showDetails = config.alwaysShowFullTooltip
                || (!keybinding.isUnbound() && isKeyPressed(keybinding)
        );
        var spellInfo = getSpellInfo(itemStack, container, player, forceHideHeader, showDetails);
        if (!showDetails) {
            if (config.showSpellBindingTooltip
                    && SpellChoices.from(itemStack) == null
                    && container.pool() != null && !container.pool().isEmpty()
                    && container.spell_ids().isEmpty()) {
                spellInfo.content().add(Text.translatable("spell.tooltip.spell_binding_tip")
                        .formatted(Formatting.GRAY));
            }
        }
        if (allowDetailsHint && !showDetails) {
            if (!keybinding.isUnbound() && container.spell_ids().size() > 0) {
                spellInfo.content().add(Text.translatable("spell.tooltip.hold_for_details",
                                keybinding.getBoundKeyLocalizedText())
                        .formatted(Formatting.DARK_GRAY));
            }
        }
        return spellInfo;
    }

public static @NotNull SpellInfo getSpellChoiceInfo(SpellChoice container, PlayerEntity player) {
        // Get world reference
        final var world = player.getWorld();
        if (world == null) {
            return new SpellInfo(List.of(), 0);
        }

        // Validate pool
        var pool = container.pool();
        if (pool == null || pool.isEmpty()) {
            return new SpellInfo(List.of(), 0);
        }

        // Resolve all spells from the pool tag
        List<RegistryEntry<Spell>> spells = SpellRegistry.entries(world, pool);
        if (spells.isEmpty()) {
            return new SpellInfo(List.of(), 0);
        }
        var archetype = spells.getFirst().value().school.archetype;

        // Sort spells by tier then alphabetically
        HashMap<Identifier, Spell> spellMap = new HashMap<>();
        for (var entry : spells) {
            var id = entry.getKey().get().getValue();
            spellMap.put(id, entry.value());
        }

        List<Identifier> sortedSpellIds = spellMap.entrySet().stream()
            .sorted(SpellContainerHelper.containerSorter)
            .map(entry -> entry.getKey())
            .collect(Collectors.toList());

        // Build tooltip access
        var spellTextLines = new ArrayList<Text>();

        // Header: "Spell choice:" or "Skill choice:" based on access type
        var key = archetype == SpellSchool.Archetype.MAGIC
            ? "spell.tooltip.choice.list.spell"
            : "spell.tooltip.choice.list.skill";
        spellTextLines.add(Text.translatable(key).formatted(Formatting.GRAY));

        // Spell names: "  Arcane Blast | Pyroblast | Frostbolt"
        var spellNames = sortedSpellIds.stream()
            .map(SpellTooltip::spellTranslationKey)
            .map(I18n::translate)
            .collect(Collectors.toList());

        var joinedNames = String.join(" | ", spellNames);
        spellTextLines.add(indentation(1).append(Text.literal(joinedNames)).formatted(Formatting.GRAY));

        // Return with 1 section divider (for the header)
        return new SpellInfo(spellTextLines, 1);
    }

public static @NotNull SpellTooltip.SpellInfo getSpellInfo(ItemStack itemStack, SpellContainer container, PlayerEntity player,
                                                               boolean forceHideHeader, boolean showDetails) {
        var config = SpellEngineClient.config;
        List<RegistryEntry<Spell>> spells = List.of();
        final var world = MinecraftClient.getInstance().world;
        var spellTextLines = new ArrayList<Text>();
        int addSectionDivider = 0;
        if (world != null) {
            spells = container.spell_ids().stream()
                    .map(idString -> resolveSpell(world, idString))
                    .filter(Objects::nonNull)
                    .toList();
        }

        forceHideHeader = forceHideHeader || itemStack.isIn(SpellEngineItemTags.SPELL_BOOK_MERGEABLE);
        boolean showListHeader = false;
        if (!forceHideHeader) {
            for (var spellEntry : spells) {
                var spell = spellEntry.value();
                var tooltip = spell.tooltip();
                showListHeader = showListHeader || tooltip.show_header;
            }
        }
        int indentLevel = showListHeader ? 1 : 0;

        if (spells.isEmpty()) {
            return new SpellInfo(spellTextLines, addSectionDivider);
        }

        var activeSpells = spells.stream()
                .filter(entry -> entry.value().type == Spell.Type.ACTIVE)
                .toList();
        if (!activeSpells.isEmpty()) {
            String limit = "";
            if (container.max_spell_count() > 0) {
                limit = I18n.translate("spell.tooltip.container.limit")
                        .replace(placeholder("current"), "" + container.spell_ids().size())
                        .replace(placeholder("max"), "" + container.max_spell_count());
            }

            var key = "spell.tooltip.container.list.spell";
            switch (container.access()) {
                case MAGIC -> {
                    key = "spell.tooltip.container.list.spell";
                }
                case ARCHERY -> {
                    key = "spell.tooltip.container.list.archery";
                }
            }
            var header = Text.translatable(key)
                    .append(Text.literal(" " + limit))
                    .formatted(Formatting.GRAY);
            addSpellSection(spellTextLines, indentLevel, showListHeader ? header : null,
                    activeSpells, player, itemStack, showDetails);
            if (showListHeader) {
                addSectionDivider += 1;
            }
        }

        var passiveSpells = spells.stream()
                .filter(entry -> entry.value().type == Spell.Type.PASSIVE)
                .toList();
        if (!passiveSpells.isEmpty()) {
            var header = Text.translatable("spell.tooltip.container.list.passives").formatted(Formatting.GRAY);
            addSpellSection(spellTextLines, indentLevel, showListHeader ? header : null,
                    passiveSpells, player, itemStack, showDetails);
            if (showListHeader) {
                addSectionDivider += 1;
            }
        }

        var modifiers = spells.stream()
                .filter(entry -> entry.value().type == Spell.Type.MODIFIER)
                .toList();
        if (!modifiers.isEmpty()) {
            var header = Text.translatable("spell.tooltip.container.list.modifiers").formatted(Formatting.GRAY);
            addSpellSection(spellTextLines, indentLevel, showListHeader ? header : null,
                    modifiers, player, itemStack, showDetails);
            if (showListHeader) {
                addSectionDivider += 1;
            }
        }

        return new SpellInfo(spellTextLines, addSectionDivider);
    }

private static void addSpellSection(ArrayList<Text> lines, int indentLevel, @Nullable Text header, List<RegistryEntry<Spell>> content,
                                        PlayerEntity player, ItemStack itemStack, boolean showDetails) {
        if (header != null) {
            lines.add(header);
        }
        for (int i = 0; i < content.size(); i++) {
            var spellEntry = content.get(i);
            var info = spellEntry(spellEntry, player, itemStack, showDetails, indentLevel);
            if (!info.isEmpty()) {
                if (i > 0 && showDetails) {
                    lines.add(Text.literal(" ")); // Separator: empty line
                }
                lines.addAll(info);
            }
        }
    }

private static KeyBinding detailsKeybinding() {
        var dedicated = Keybindings.tooltip_details;
        return dedicated.isUnbound() ? Keybindings.bypass_spell_hotbar : dedicated;
    }

private static boolean isKeyPressed(KeyBinding keybinding) {
        var client = MinecraftClient.getInstance();
        // Checking execution on render thread
        // some loaders like to call these concurrently
        if (client.isOnThread()) {
            return InputUtil.isKeyPressed(client.getWindow().getHandle(),
                    ((KeybindingAccessor) keybinding).spellEngine_getBoundKey().getCode());
        }
        return false;
    }

public static List<Text> spellEntry(Identifier spellId, PlayerEntity player, ItemStack itemStack, boolean details, int indentLevel) {
        var world = player.getWorld();
        if (world == null) {
            return List.of();
        }
        var spellEntry = resolveSpell(world, spellId);
        if (spellEntry == null) {
            return List.of();
        }
        return spellEntry(spellEntry, player, itemStack, details, indentLevel);
