public static LootConfig constrainValues(LootConfig config, LootConfig defaults) {
        if (defaults.behavior == null) {
            config.behavior = null; // Not supported by this config (for example: scrolls)
        } else if (config.behavior == null) {
            config.behavior = new Behavior();
        }
        if (config.behavior != null) {
            if (config.behavior.class_affiliation_extra_weight < 0) {
                config.behavior.class_affiliation_extra_weight = 0;
            }
            if (config.behavior.class_affiliation_weight_operation == null) { // Missing or unknown value
                config.behavior.class_affiliation_weight_operation = Behavior.WeightOperation.MULTIPLY;
            }
        }
        if (config.injectors == null) { config.injectors = new LinkedHashMap<>(); }
        if (config.regex_injectors == null) { config.regex_injectors = new LinkedHashMap<>(); }
        if (config.fallback == null) {
            config.fallback = defaults.fallback != null ? defaults.fallback : new Fallback();
        }
        var fallback = config.fallback;
        if (fallback.rolls_multiplier < 0) { fallback.rolls_multiplier = 0; }
        if (fallback.max_rolls < 0) { fallback.max_rolls = 0; }
        if (fallback.tables == null || fallback.tables.isEmpty()) { fallback.tables = Fallback.DEFAULT_TABLES; }
        if (fallback.blacklist == null) { fallback.blacklist = new ArrayList<>(); }
        if (fallback.entries == null) { fallback.entries = new ArrayList<>(); }
        fallback.entries.removeIf(Objects::isNull);
        for (var entry: fallback.entries) {
            if (entry.reference == null) { entry.reference = ""; }
            if (entry.rolls < 0) { entry.rolls = 0; }
            if (entry.bonus_rolls < 0) { entry.bonus_rolls = 0; }
            if (entry.items == null) { entry.items = new ArrayList<>(); }
            constrainEntries(entry.items);
        }
        constrainPools(config.injectors.values());
        constrainPools(config.regex_injectors.values());
        return config;
    }

private static void constrainEntries(List<Pool.Entry> entries) {
        for (var lootEntry: entries) {
            if (lootEntry.weight < 1) {
                lootEntry.weight = 1;
            }
            // Default value is not serialized (older config files spelled it out)
            if (Boolean.TRUE.equals(lootEntry.filters_lenient)) {
                lootEntry.filters_lenient = null;
            }
        }
    }

private static void constrainPools(Iterable<? extends Pool> pools) {
        for (var pool: pools) {
            if (pool.entries == null) { pool.entries = new ArrayList<>(); }
            constrainEntries(pool.entries);
        }
    }

public static void updateTagCache(LootConfig lootConfig) {
        var updatedTags = new HashSet<String>();
        var tagsToCache = new ArrayList<String>();
        var entryLists = new ArrayList<List<LootConfig.Pool.Entry>>();
        lootConfig.injectors.values().forEach(pool -> entryLists.add(pool.entries));
        lootConfig.regex_injectors.values().forEach(pool -> entryLists.add(pool.entries));
        if (lootConfig.fallback != null) {
            for (var fallbackEntry: lootConfig.fallback.entries) {
                entryLists.add(fallbackEntry.items);
                tagsToCache.add(fallbackEntry.reference);
            }
        }
        for (var entries: entryLists) {
            for (var itemInjectorEntry: entries) {
                if (itemInjectorEntry.id != null) {
                    tagsToCache.add(itemInjectorEntry.id);
                }
                if (itemInjectorEntry.filters != null) {
                    tagsToCache.addAll(itemInjectorEntry.filters);
                }
            }
        }
        for (var id: tagsToCache) {
            var pattern = id.startsWith(PatternMatching.NEGATE_PREFIX) ? id.substring(1) : id;
            if (!pattern.startsWith(PatternMatching.TAG_PREFIX)) { continue; }
            var tagString = pattern.substring(1);
            if (updatedTags.contains(tagString)) {
                continue;
            }
            var tagId = Identifier.of(tagString);
            TagKey<Item> tag = TagKey.of(RegistryKeys.ITEM, tagId);
            var itemList = new ArrayList<String>();
            Registries.ITEM.iterateEntries(tag).forEach((itemEntry) -> {
                var itemId = itemEntry.getKey().get().getValue();
                itemList.add(itemId.toString());
            });
            LootHelper.TAG_CACHE.value.cache.put(tagString, itemList);
            updatedTags.add(tagString);
        }
        LootHelper.TAG_CACHE.save();
        rpgTierItems = null;
    }

private static Set<String> rpgTierItems() {
        if (rpgTierItems == null) {
            var items = new HashSet<String>();
            for (var entry: TAG_CACHE.value.cache.entrySet()) {
                if (entry.getKey().startsWith(LOOT_TIER_TAG_PREFIX)) {
                    items.addAll(entry.getValue());
                }
            }
            rpgTierItems = items;
        }
        return rpgTierItems;
    }

public static void saveFallbackReport() {
        FALLBACK_REPORT.value = pendingReport;
        FALLBACK_REPORT.save();
        pendingReport = new FallbackReport();
    }

public static void configure(RegistryWrapper.WrapperLookup registries, Identifier lootTableId,
                                 List<LootPool> existingPools, Consumer<LootPool> poolSink,
                                 LootConfig config, String configName) {
        boolean isEntityLootTable = lootTableId.getPath().startsWith("entities");
        var tableId = lootTableId.toString();

        // 1. Exact id
        var pool = config.injectors.get(tableId);
        // 2. Regex id
        if (pool == null) {
            for (var regex: config.regex_injectors.keySet()) {
                if (regexMatches(tableId, regex)) {
                    pool = config.regex_injectors.get(regex);
                    break;
                }
            }
        }
        if (pool != null) {
            boolean skipConditions = pool.skip_conditions != null && pool.skip_conditions;
            var lootPool = buildPool(registries, pool.entries, pool.rolls, pool.bonus_rolls,
                    isEntityLootTable && !skipConditions, null, config.behavior);
            if (lootPool != null) {
                poolSink.accept(lootPool.build());
            }
            return;
        }
        // 3. Fallback, based on what the table already drops
        configureFallback(registries, tableId, existingPools, poolSink, config, configName, isEntityLootTable);
    }

private static void configureFallback(RegistryWrapper.WrapperLookup registries, String tableId,
                                          List<LootPool> existingPools, Consumer<LootPool> poolSink,
                                          LootConfig config, String configName, boolean isEntityLootTable) {
        var fallback = config.fallback;
        if (fallback == null || fallback.entries.isEmpty() || fallback.rolls_multiplier <= 0) { return; }
        for (var blacklisted: fallback.blacklist) {
            if (matchesId(tableId, blacklisted)) { return; }
        }
        var applicable = new ArrayList<LootConfig.Fallback.Entry>();
        for (var entry: fallback.entries) {
            if (entry.reference.isEmpty()) { continue; }
            var tables = entry.tables != null ? entry.tables : fallback.tables;
            if (matchesId(tableId, tables)) {
                applicable.add(entry);
            }
        }
        if (applicable.isEmpty()) { return; }

        var contents = inspect(existingPools);
        if (contents.isEmpty()) { return; }

        if (fallback.skip_tables_with_rpg_loot) {
            var rpgItems = rpgTierItems();
            for (var pool: contents) {
                for (var itemId: pool.items.keySet()) {
                    if (rpgItems.contains(itemId)) {
                        pendingReport.skipped.put(tableId, "already drops RPG Series loot: " + itemId);
                        return;
                    }
                }
            }
        }

        // Every applicable entry becomes a part of a single injected pool, so the total injected
        // loot is bounded by `max_rolls`, no matter how many references the table matches
        var parts = new ArrayList<FallbackPart>();
        var reportLines = new LinkedHashMap<String, String>();
        for (var entry: applicable) {
            var reference = entry.reference;
            float share = 0;
            String matchedItem = null;
            int plainWeight = 0, enchantedWeight = 0;
            Float minLevel = null, maxLevel = null;
            for (var pool: contents) {
                int matchedWeight = 0;
                for (var item: pool.items.entrySet()) {
                    if (!matchesItem(item.getKey(), reference)) { continue; }
                    var occurrence = item.getValue();
                    matchedWeight += occurrence.weight();
                    plainWeight += occurrence.plainWeight;
                    enchantedWeight += occurrence.enchantedWeight;
                    if (occurrence.minLevel != null) {
                        minLevel = minLevel == null ? occurrence.minLevel : Math.min(minLevel, occurrence.minLevel);
                        maxLevel = maxLevel == null ? occurrence.maxLevel : Math.max(maxLevel, occurrence.maxLevel);
                    }
                    if (matchedItem == null) { matchedItem = item.getKey(); }
                }
                if (matchedWeight > 0 && pool.totalWeight > 0) {
                    share = Math.max(share, (float) matchedWeight / (float) pool.totalWeight);
                }
            }
            if (share <= 0) { continue; }

            var scale = share * fallback.rolls_multiplier;
            var rolls = entry.rolls * scale;
            var bonusRolls = entry.bonus_rolls * scale;
            if (rolls <= 0) { continue; }
            var mix = new EnchantMix(plainWeight, enchantedWeight, minLevel, maxLevel);
            // A single roll, the combined pool decides how many times a part is rolled
            var partPool = buildPool(registries, entry.items, 1F, 0F, false, mix, config.behavior);
            if (partPool == null) { continue; }
            parts.add(new FallbackPart(partPool, rolls, bonusRolls));

            var enchantInfo = enchantedWeight == 0 ? "plain" : plainWeight == 0 ? "enchanted" :
                    String.format(Locale.ROOT, "%.0f%% enchanted", 100F * enchantedWeight / (plainWeight + enchantedWeight));
            if (enchantedWeight > 0 && minLevel != null) {
                enchantInfo += String.format(Locale.ROOT, " (levels %.0f-%.0f)", minLevel, maxLevel);
            }
            // The same reference may drive multiple entries (for example: gear and accessories)
            reportLines.put(configName + "/" + reference + " -> " + describe(entry.items), String.format(Locale.ROOT,
                    "matched %s, share %.2f, rolls %.2f, %s", matchedItem, share, rolls, enchantInfo));
        }
        if (parts.isEmpty()) { return; }

        float totalRolls = 0, totalBonusRolls = 0;
        for (var part: parts) {
            totalRolls += part.rolls();
            totalBonusRolls += part.bonusRolls();
        }
        var rolls = fallback.max_rolls > 0 ? Math.min(totalRolls, fallback.max_rolls) : totalRolls;
        var bonusRolls = totalBonusRolls * (rolls / totalRolls);

        LootPool.Builder lootPoolBuilder = LootPool.builder();
        if (isEntityLootTable) {
            lootPoolBuilder.conditionally(KilledByPlayerLootCondition.builder());
        }
        applyRolls(lootPoolBuilder, rolls, bonusRolls);
        for (var part: parts) {
            // Parts are picked proportionally to their own rolls, each an inline table keeping its item weights intact
            var weight = Math.max(1, Math.round(FALLBACK_PART_WEIGHT_SCALE * part.rolls() / totalRolls));
            lootPoolBuilder.with(LootTableEntry.builder(LootTable.builder().pool(part.pool()).build()).weight(weight));
        }
        poolSink.accept(lootPoolBuilder.build());

        var tableReport = pendingReport.injected.computeIfAbsent(tableId, k -> new LinkedHashMap<>());
        tableReport.putAll(reportLines);
        tableReport.put(configName + " (total)", String.format(Locale.ROOT,
                "rolls %.2f, injected %.2f", totalRolls, rolls));
    }

private static String describe(List<LootConfig.Pool.Entry> entries) {
        var ids = new ArrayList<String>();
        for (var entry: entries) {
            if (entry.id != null) { ids.add(entry.id); }
        }
        return String.join(", ", ids);
    }

private static List<PoolContents> inspect(List<LootPool> pools) {
        var result = new ArrayList<PoolContents>(pools.size());
        for (var pool: pools) {
            var items = new LinkedHashMap<String, ItemOccurrence>();
            int[] total = { 0 };
            for (var entry: pool.entries) {
                collect(entry, items, total);
            }
            if (!items.isEmpty()) {
                result.add(new PoolContents(items, total[0]));
            }
        }
        return result;
    }

private static void collect(LootPoolEntry entry, LinkedHashMap<String, ItemOccurrence> items, int[] total) {
        if (entry instanceof CombinedEntry) {
            for (var child: ((CombinedEntryAccessor) entry).spellEngine_getChildren()) {
                collect(child, items, total);
            }
            return;
        }
        if (entry instanceof AffiliationGroupEntry group) {
            for (var child: group.children()) {
                collect(child, items, total);
            }
            return;
        }
        if (!(entry instanceof LeafEntry)) { return; }
        var leaf = (LeafEntryAccessor) entry;
        var weight = leaf.spellEngine_getWeight();
        total[0] += weight;
        if (entry instanceof ItemEntry) {
            var item = ((ItemEntryAccessor) entry).spellEngine_getItem().value();
            var itemId = Registries.ITEM.getId(item).toString();
            var occurrence = items.computeIfAbsent(itemId, k -> new ItemOccurrence());
            boolean enchanted = false;
            for (var function: leaf.spellEngine_getFunctions()) {
                if (function instanceof EnchantWithLevelsLootFunction) {
                    enchanted = true;
                    var levels = ((EnchantWithLevelsLootFunctionAccessor) function).spellEngine_getLevels();
                    Float min = null, max = null;
                    if (levels instanceof ConstantLootNumberProvider constant) {
                        min = constant.value(); max = constant.value();
                    } else if (levels instanceof UniformLootNumberProvider uniform
                            && uniform.min() instanceof ConstantLootNumberProvider lo
                            && uniform.max() instanceof ConstantLootNumberProvider hi) {
                        min = lo.value(); max = hi.value();
                    }
                    if (min != null) {
                        occurrence.minLevel = occurrence.minLevel == null ? min : Math.min(occurrence.minLevel, min);
                        occurrence.maxLevel = occurrence.maxLevel == null ? max : Math.max(occurrence.maxLevel, max);
                    }
                } else if (function instanceof EnchantRandomlyLootFunction) {
                    enchanted = true;
                }
            }
            if (enchanted) {
                occurrence.enchantedWeight += weight;
            } else {
                occurrence.plainWeight += weight;
            }
        }
        // Table references and tag entries are not resolved (referenced tables may not be parsed yet).
    }

LootConfig.Pool.Entry.Enchant levels(@Nullable LootConfig.Pool.Entry.Enchant configured) {
            if (configured != null && configured.isValid()) { return configured; }
            var mirrored = new LootConfig.Pool.Entry.Enchant();
            if (minLevel != null && maxLevel != null && maxLevel > minLevel && minLevel > 0) {
                mirrored.min_power = minLevel;
                mirrored.max_power = maxLevel;
            }
            return mirrored;
        }

@Nullable private static LootPool.Builder buildPool(RegistryWrapper.WrapperLookup registries, List<LootConfig.Pool.Entry> entries,
                                      float rolls, float bonusRolls, boolean killedByPlayerOnly, @Nullable EnchantMix mix,
                                      @Nullable LootConfig.Behavior behavior) {
        LootPool.Builder lootPoolBuilder = LootPool.builder();
        boolean classAffiliation = behavior != null && behavior.classAffiliationActive();
        int[] entryCount = { 0 };
        if (killedByPlayerOnly) {
            lootPoolBuilder.conditionally(KilledByPlayerLootCondition.builder());
        }

        applyRolls(lootPoolBuilder, rolls, bonusRolls);
        for (var entry: entries) {
            var entryId = entry.id;
            var weight = entry.weight;
            var enchant = entry.enchant;
            var spellBind = entry.spell_bind;
            if (entryId == null || entryId.isEmpty()) { continue; }

            // Tag cache is used, because this event handler is called before the game loads the item tags
            List<String> itemList = entryId.startsWith("#")
                            ? TAG_CACHE.value.cache.get(entryId.substring(1))
                            : List.of(entryId);
            List<String> filters = entry.filters != null ? entry.filters : List.of();

            if (itemList == null) {
                System.err.println("RPG Series loot config: failed to resolve itemList for: " + entryId
                + " (Probably just needs a game restart)");
                continue;
            }

            // With class affiliation, the items of a config entry are rolled as one group,
            // redistributing weight within towards the items relevant for the looting player
            var group = classAffiliation
                    ? AffiliationGroupEntry.builder(behavior.class_affiliation_extra_weight,
                            behavior.class_affiliation_weight_operation, behavior.class_affiliation_include_team)
                    : null;
            Consumer<LootPoolEntry.Builder<?>> entrySink = lootEntry -> {
                if (group != null) { group.with(lootEntry); } else { lootPoolBuilder.with(lootEntry); }
                entryCount[0] += 1;
            };

            for (var itemId: itemList) {
                var item = Registries.ITEM.get(Identifier.of(itemId));
                if (item == null || item == Items.AIR) { continue; } // Unknown id resolves to air
                var lootEntry = ItemEntry.builder(item)
                        .weight(weight);
                var lenient = entry.filtersLenient();
                var filtersMatch = lenient ? filters.isEmpty() : true;
                for (var filter: filters) {
                    if (!filter.startsWith("#")) { continue; }
                    var tag = TAG_CACHE.value.cache.get(filter.substring(1));
                    if (tag == null) { continue; }
                    var contains = tag.contains(itemId);
                    if (lenient) {
                        filtersMatch = filtersMatch || contains;
                    } else {
                        filtersMatch = filtersMatch && contains;
                    }
                }
                if (!filtersMatch) { continue; }

                if (mix != null && spellBind == null) {
                    // Mirror the source: a plain and an enchanted copy, weighted like the reference gear
                    if (mix.plainWeight() > 0) {
                        entrySink.accept(ItemEntry.builder(item).weight(weight * mix.plainWeight()));
                    }
                    if (mix.enchantedWeight() > 0) {
                        var levels = mix.levels(enchant);
                        entrySink.accept(ItemEntry.builder(item).weight(weight * mix.enchantedWeight())
                                .apply(EnchantWithLevelsLootFunction.builder(registries, numberProvider(levels.min_power, levels.max_power))));
                    }
                    continue;
                }

                if (enchant != null && enchant.isValid()) {
                    var enchantFunction = EnchantWithLevelsLootFunction.builder(registries, numberProvider(enchant.min_power, enchant.max_power));
                    lootEntry.apply(enchantFunction);
                }
                if (spellBind != null && spellBind.isValid()) {
                    var function = SpellBindRandomlyLootFunction.builder(
                            spellBind.pool,
                            numberProvider(tierBound(spellBind.tier_min), tierBound(spellBind.tier_max)),
                            numberProvider(spellBind.count_min, spellBind.count_max));
                    lootEntry.apply(function);
                }
                entrySink.accept(lootEntry);
            }
            if (group != null && !group.isEmpty()) {
                lootPoolBuilder.with(group);
            }
        }
        return entryCount[0] > 0 ? lootPoolBuilder : null;
    }

private static void applyRolls(LootPool.Builder lootPoolBuilder, float rolls, float bonusRolls) {
        rolls = rolls > 0 ? rolls : 1F;
        var attempts = Math.ceil(rolls);
        var chance = rolls / attempts;
        lootPoolBuilder.rolls(BinomialLootNumberProvider.create((int) attempts, (float) chance));
        lootPoolBuilder.bonusRolls(ConstantLootNumberProvider.create(bonusRolls));
    }

private static boolean regexMatches(String subject, String regex) {
        var pattern = REGEX_CACHE.computeIfAbsent(regex, r -> Pattern.compile(r, Pattern.CASE_INSENSITIVE));
        return pattern.matcher(subject).find();
    }

private static boolean matchesId(String id, @Nullable String pattern) {
        if (pattern == null || pattern.isEmpty() || pattern.equals(PatternMatching.ANY)) { return true; }
        if (pattern.startsWith(PatternMatching.NEGATE_PREFIX)) { return !matchesId(id, pattern.substring(1)); }
        if (pattern.startsWith(PatternMatching.REGEX_PREFIX)) { return regexMatches(id, pattern.substring(1)); }
        if (pattern.startsWith(PatternMatching.TAG_PREFIX)) { return false; } // tags are not applicable to table ids
        return id.equals(pattern);
    }

private static boolean matchesItem(String itemId, @Nullable String pattern) {
        if (pattern == null || pattern.isEmpty() || pattern.equals(PatternMatching.ANY)) { return true; }
        if (pattern.startsWith(PatternMatching.NEGATE_PREFIX)) { return !matchesItem(itemId, pattern.substring(1)); }
        if (pattern.startsWith(PatternMatching.TAG_PREFIX)) {
            var items = TAG_CACHE.value.cache.get(pattern.substring(1));
            return items != null && items.contains(itemId);
        }
        if (pattern.startsWith(PatternMatching.REGEX_PREFIX)) { return regexMatches(itemId, pattern.substring(1)); }
        return itemId.equals(pattern);
    }

private static float tierBound(Integer tier) {
        return (tier == null || tier < 0) ? -1 : tier;
    }

private static LootNumberProvider numberProvider(float min, float max) {
        if (max <= min) {
            return ConstantLootNumberProvider.create(min);
        } else {
            return UniformLootNumberProvider.create(min, max);
        }
    }

@Override
    public ItemStack process(ItemStack stack, LootContext context) {
        @Nullable final var spellTag = getSpellTag();
        final var selectedTier = this.tier != null ? this.tier.nextInt(context) : -1;
        @Nullable var existingContainer = SpellContainerHelper.containerFromItemStack(stack);
        final List<Identifier> alreadyPresentSpells = existingContainer != null
                ? existingContainer.spell_ids().stream().map(Identifier::of).toList()
                : List.of();
        var spells = SpellRegistry.stream(context.getWorld())
                .filter(entry -> {
                    var id = entry.getKey().get().getValue();
                    return (selectedTier < 0 || entry.value().tier == selectedTier)
                            // && (entry.value().active != null && entry.value().active.scroll != null)
                            && (spellTag == null || entry.isIn(spellTag))
                            && !alreadyPresentSpells.contains(id);
                })
                .toList();

        ArrayList<RegistryEntry<Spell>> selectedSpells = new ArrayList<>();
        if (!spells.isEmpty()) {
            var selectedCount = this.count != null ? this.count.nextInt(context) : 1;
            var retryAttempts = 3;
            for (int i = 0; i < selectedCount; i++) {
                var entry = spells.get(context.getRandom().nextInt(spells.size()));
                while (
                        (retryAttempts > 0) &&
                                // Reroll if
                                // already selected
                                (
                                        selectedSpells.contains(entry)
                                )
                ) {
                    entry = spells.get(context.getRandom().nextInt(spells.size()));
                    retryAttempts -= 1;
                }

                selectedSpells.add(entry);
            }
        }

        if (!selectedSpells.isEmpty()) {
            var newContainer = existingContainer != null ? existingContainer : SpellContainer.EMPTY;
            var newSpellIds = selectedSpells.stream().map(entry -> entry.getKey().get().getValue().toString()).toList();
            newContainer = newContainer
                    .withAdditionalSpell(newSpellIds);
            var sortedSpellIds = SpellContainerHelper.sortedSpells(context.getWorld(), newContainer.spell_ids());
            newContainer = newContainer.copyWith(sortedSpellIds);

            stack.set(SpellDataComponents.SPELL_CONTAINER, newContainer);

            if (stack.getItem() == SpellEngineItems.SCROLL.get()) {
                ScrollItem.onSpellAdded(stack, selectedSpells.getFirst(), ScrollItem.resolveSpellPool(context.getWorld(), selectedSpells.getFirst()));
            }
        } else {
            if (stack.getItem() == SpellEngineItems.SCROLL.get()) {
                return ItemStack.EMPTY;
            }
        }

        return stack;
    }

public static OfferResult offersFor(World world, boolean creative, ItemStack itemStack, ItemStack consumableStack, int libraryPower) {
        if (itemStack.getItem() == Items.BOOK) {
            var tags = availableSpellBookTags(world);
            var offers = new ArrayList<Offer>();
            if (SpellEngineMod.config.spell_book_creation_enabled) {
                for (int i = 0; i < tags.size(); ++i) {
                    offers.add(new Offer(
                            i + BOOK_OFFSET,
                            SpellEngineMod.config.spell_book_creation_cost,
                            SpellEngineMod.config.spell_book_creation_requirement,
                            0,
                            true));
                }
            }
            return new OfferResult(Mode.BOOK, offers);
        }

        var choices = SpellChoices.from(itemStack);
        if (choices != null) {
            return new OfferResult(Mode.SPELL, List.of());
        }
        var container = SpellContainerHelper.containerFromItemStack(itemStack);
        if (container == null) {
            return new OfferResult(Mode.SPELL, List.of());
        }
        var pool = SpellRegistry.entries(world, container.pool());
        if (pool == null || pool.isEmpty()) {
            return new OfferResult(Mode.SPELL, List.of());
        }

        List<RegistryEntry<Spell>> spells;
        var consumableContainer = SpellContainerHelper.containerFromItemStack(consumableStack);
        var scrollMode = false;
        if (consumableStack.isIn(SpellEngineItemTags.SPELL_BOOK_MERGEABLE) && consumableContainer != null) {
            scrollMode = true;
            var spellRegistry = SpellRegistry.from(world);
            var consumableSpells = consumableContainer.spell_ids().stream()
                    .map(Identifier::of)
                    .map(spellRegistry::getEntry)
                    .filter(Optional::isPresent)
                    .map(Optional::get)
                    .toList();
            var availableSpellIds = pool.stream()
                    .map(entry -> entry.getKey().get().getValue())
                    .collect(Collectors.toSet());
            spells = consumableSpells.stream()
                    .filter(entry -> {
                        var spellId = entry.getKey().get().getValue();
                        return availableSpellIds.contains(spellId) || creative;
                    })
                    .map(entry -> (RegistryEntry<Spell>) entry)
                    .toList();
        } else {
            spells = pool;
        }

        var spellMap = new HashMap<Identifier, Spell>(); // Refactor: remove this conversion
        spells.forEach(entry -> {
            var spell = entry.value();
            spellMap.put(entry.getKey().get().getValue(), spell);
        });
        final var finalScrollMode = scrollMode;
        return new OfferResult(Mode.SPELL,
                spellMap.entrySet().stream()
                .sorted(SpellContainerHelper.catalogSorter)
                .map(entry -> {
                    var spell = entry.getValue();
                    if (finalScrollMode) {
                        var cost = spell.tier * SpellEngineMod.config.spell_scroll_level_cost_per_tier
                                + SpellEngineMod.config.spell_scroll_apply_cost_base;
                        var levelRequirement = 1;
                        return new Offer(
                                rawSpellId(world, entry.getKey()),
                                cost,
                                levelRequirement,
                                0,
                                true);
                    } else {
                        if (spell.learn != null && spell.tier > 0) {
                            var cost = spell.tier * spell.learn.level_cost_per_tier;
                            var levelCost = Math.max(
                                    SpellEngineMod.config.spell_binding_level_cost_min,
                                    cost * SpellEngineMod.config.spell_binding_level_cost_multiplier + SpellEngineMod.config.spell_binding_level_cost_offset);

                            var levelRequirementDefault = spell.tier * spell.learn.level_requirement_per_tier;
                            var levelRequirement = Math.max(
                                    SpellEngineMod.config.spell_binding_level_requirement_min,
                                    levelRequirementDefault * SpellEngineMod.config.spell_binding_level_requirement_multiplier + SpellEngineMod.config.spell_binding_level_requirement_offset);
                            return new Offer(
                                    rawSpellId(world, entry.getKey()),
                                    levelCost,
                                    levelRequirement,
                                    cost * SpellEngineMod.config.spell_binding_lapis_cost_multiplier,
                                    (libraryPower >= LIBRARY_POWER_CAP)
                                            || ((LIBRARY_POWER_BASE + libraryPower * LIBRARY_POWER_MULTIPLIER) >= levelRequirement)
                            );
                        }
                    }
                    return null;
                })
                .filter(Objects::nonNull)
                .collect(Collectors.toList())
        );
    }

public static State of(World world, Identifier spellId, ItemStack itemStack, int levelCost, int requiredLevel, int lapisCost) {
            var container = SpellContainerHelper.containerFromItemStack(itemStack);
            var requirements = new Requirements(
                    lapisCost,
                    levelCost,
                    requiredLevel);
            if (container == null) {
                return new State(ApplyState.INVALID, requirements);
            }
            if (container.spell_ids().contains(spellId.toString())) {
                return new State(ApplyState.ALREADY_APPLIED, requirements);
            }
            if (container.max_spell_count() > 0 && container.spell_ids().size() >= container.max_spell_count()) {
                return new State(ApplyState.NO_MORE_SLOT, requirements);
            }

            // Check for tier conflicts
            var registry = SpellRegistry.from(world);
            var spellEntry = registry.getEntry(spellId);
            if (spellEntry.isPresent()) {
                var newSpellTier = spellEntry.get().value().tier;
                var otherSpellsInTier = 0;
                // Check existing spell with the same tier
                for (var existingSpellIdString : container.spell_ids()) {
                    var existingSpellId = Identifier.of(existingSpellIdString);
                    var existingSpellEntry = registry.getEntry(existingSpellId);
                    if (existingSpellEntry.isPresent() && existingSpellEntry.get().value().tier == newSpellTier) {
                        otherSpellsInTier += 1;
                    }
                }
                if (otherSpellsInTier >= container.binding_mutex_count()) {
                    return new State(ApplyState.TIER_CONFLICT, requirements);
                }
            }

            return new State(ApplyState.APPLICABLE, requirements);
        }

