private static int castSpell(CommandSourceStack source, Collection<? extends Entity> targets, String spellId, int spellLevel) {
        if (!spellId.contains(":")) {
            spellId = IronsSpellbooks.MODID + ":" + spellId;
        }

        var spell = SpellRegistry.getSpell(spellId);

        for (Entity target : targets) {
            if (target instanceof ServerPlayer serverPlayer) {
                spell.attemptInitiateCast(ItemStack.EMPTY, spellLevel, source.getLevel(), serverPlayer, CastSource.COMMAND, false, "command");
            } else if (target instanceof IMagicEntity castingMob) {
                castingMob.initiateCastSpell(spell, spellLevel);
            } else if (target instanceof LivingEntity livingEntity) {
                var magicData = MagicData.getPlayerMagicData(livingEntity);

                if (!spell.checkPreCastConditions(source.getLevel(), spellLevel, livingEntity, magicData)) {
                    return 0;
                }

                //if (spell.getCastType() == CastType.INSTANT) {
                spell.onCast(source.getLevel(), spellLevel, livingEntity, CastSource.COMMAND, magicData);
                spell.onServerCastComplete(source.getLevel(), spellLevel, livingEntity, magicData, false);
                //} else {
                //    int effectiveCastTime = spell.getEffectiveCastTime(spellLevel, livingEntity);
                //    magicData.initiateCast(spell, spellLevel, effectiveCastTime, CastSource.MOB, "command");
                //    spell.onServerPreCast(source.getLevel(), spellLevel, livingEntity, magicData);
                //}
            }
        }
        return 1;
    }

private static int createImbuedSword(CommandSourceStack source, ItemInput itemInput, String spell, int spellLevel) throws CommandSyntaxException {
        if (!spell.contains(":")) {
            spell = IronsSpellbooks.MODID + ":" + spell;
        }

        var abstractSpell = SpellRegistry.REGISTRY.get(ResourceLocation.parse(spell));

        if (spellLevel > abstractSpell.getMaxLevel()) {
            throw new SimpleCommandExceptionType(Component.translatable("commands.irons_spellbooks.create_spell.failed_max_level", abstractSpell.getSpellName(), abstractSpell.getMaxLevel())).create();
        }

        var serverPlayer = source.getPlayer();
        if (serverPlayer != null) {
            ItemStack itemstack = new ItemStack(itemInput.getItem());
            if (itemstack.getItem() instanceof SwordItem swordItem) {
                var spellContainer = ISpellContainer.create(1, true, false).mutableCopy();
                spellContainer.addSpell(abstractSpell, spellLevel, false);
                ISpellContainer.set(itemstack, spellContainer.toImmutable());
                if (serverPlayer.getInventory().add(itemstack)) {
                    return 1;
                }
            }
        }

        throw ERROR_FAILED.create();
    }

private static int createScroll(CommandSourceStack source, String spell, int spellLevel) throws CommandSyntaxException {
        if (!spell.contains(":")) {
            spell = IronsSpellbooks.MODID + ":" + spell;
        }

        var abstractSpell = SpellRegistry.REGISTRY.get(ResourceLocation.parse(spell));

        if (abstractSpell == null || abstractSpell == SpellRegistry.none()) {
            throw ERROR_FAILED.create();
        }

        if (spellLevel > abstractSpell.getMaxLevel()) {
            throw new SimpleCommandExceptionType(Component.translatable("commands.irons_spellbooks.create_spell.failed_max_level", abstractSpell.getSpellName(), abstractSpell.getMaxLevel())).create();
        }

        var serverPlayer = source.getPlayer();
        if (serverPlayer != null) {
            ItemStack itemStack = new ItemStack(ItemRegistry.SCROLL.get());
            ISpellContainer.createScrollContainer(abstractSpell, spellLevel, itemStack);
            if (serverPlayer.getInventory().add(itemStack)) {
                return 1;
            }
        }

        throw ERROR_FAILED.create();
    }

private static void generateRecipeData(CommandSourceStack source) {
        if (false) {
            var temp = new SpellBalanceDebugger();
            temp.run();
        }
        boolean showAdvancedTooltip = Minecraft.getInstance().options.advancedItemTooltips;
        try {
            var itemBuilder = new StringBuilder();
            var armorBuilder = new StringBuilder();
            var spellbookBuilder = new StringBuilder();
            var curioBuilder = new StringBuilder();
            var blockBuilder = new StringBuilder();
            Set<Item> itemsTracked = new HashSet<>();
            level = source.getLevel();

            // Reveal additional shift information from tooltips
            ClientInputEvents.setShowExpandedTooltip(true);
            // Hide advanced/debug info from tooltips
            Minecraft.getInstance().options.advancedItemTooltips = false;

            handleAffinityRingEntry(curioBuilder, itemsTracked, source);
            getVisibleItems()
                    .stream()
                    .sorted(Comparator.comparing(Item::getDescriptionId))
                    .forEach(item -> {
                        if (item instanceof FurledMapItem) {
                            return;
                        }
                        var itemResource = BuiltInRegistries.ITEM.getKey(item);
                        var tooltip = getTooltip(source.getPlayer(), new ItemStack(item));

                        if (itemResource.getNamespace().equals("irons_spellbooks") && !itemsTracked.contains(item)) {
                            var recipe = getRecipeFor(source, item);
                            var name = item.getName(item.getDefaultInstance()).getString();
                            if (item.getDescriptionId().contains("patchouli") || item.getDescriptionId().contains("spawn_egg") || item.getDescriptionId().equals("item.irons_spellbooks.scroll")) {
                                return;
                            } else if (item instanceof ArmorItem armorItem) {
                                Class<? extends ArmorItem> armortype = armorItem.getClass();
                                boolean hasGroup = ItemRegistry.getIronsItems().stream().filter(holder -> armortype.isAssignableFrom(holder.value().getClass())).toList().size() > 1;
                                int sort = 0;
                                String group = "All Armor";
                                if (hasGroup) {
                                    var words = name.split(" ");
                                    group = Arrays.stream(words).limit(words.length - 1).collect(Collectors.joining(" ")) + " Armor";
                                    sort = 3 - armorItem.getEquipmentSlot().getIndex();
                                }
                                if (recipe != null) {
                                    appendRecipeSorted(armorBuilder, recipe, getRecipeData(recipe), group, tooltip, sort);
                                } else {
                                    appendSimpleGroupedSorted(armorBuilder, name, itemResource, group, tooltip, sort);
                                }
                            } else if (item instanceof SpellBook || item instanceof ExtendedSwordItem || item instanceof CastingItem || item instanceof ProjectileWeaponItem || item instanceof UniqueItem) {
                                var group = item instanceof SpellBook ? "Spellbooks" : (item instanceof CastingItem ? "Staves" : "Weapons");
                                if (recipe != null) {
                                    appendRecipe(spellbookBuilder, recipe, getRecipeData(recipe), group, tooltip);
                                } else {
                                    appendSimpleGrouped(spellbookBuilder, name, itemResource, group, tooltip);
                                }
                            } else if (item instanceof CurioBaseItem) {
                                if (recipe != null) {
                                    appendRecipe(curioBuilder, recipe, getRecipeData(recipe), "", tooltip);
                                } else {
                                    appendSimple(curioBuilder, name, itemResource, tooltip);
                                }
                            } else if (item instanceof BlockItem) {
                                if (recipe != null) {
                                    appendRecipe(blockBuilder, recipe, getRecipeData(recipe), "", tooltip);
                                } else {
                                    appendSimple(blockBuilder, name, itemResource, tooltip);
                                }
                            } else {
                                if (recipe != null) {
                                    appendRecipe(itemBuilder, recipe, getRecipeData(recipe), handleGenericItemGrouping(item), tooltip);
                                } else {
                                    appendSimpleGrouped(itemBuilder, name, itemResource, handleGenericItemGrouping(item), tooltip);
                                }
                            }
                            itemsTracked.add(item);

                        }
                    });
            ClientInputEvents.setShowExpandedTooltip(false);

            var file = new BufferedWriter(new FileWriter("item_data.yml"));
            file.write(postProcess(itemBuilder));
            file.close();

            file = new BufferedWriter(new FileWriter("armor_data.yml"));
            file.write(postProcess(armorBuilder));
            file.close();

            file = new BufferedWriter(new FileWriter("curio_data.yml"));
            file.write(postProcess(curioBuilder));
            file.close();

            file = new BufferedWriter(new FileWriter("spellbook_data.yml"));
            file.write(postProcess(spellbookBuilder));
            file.close();

            file = new BufferedWriter(new FileWriter("block_data.yml"));
            file.write(postProcess(blockBuilder));
            file.close();
        } catch (Exception e) {
            IronsSpellbooks.LOGGER.debug(e.getMessage());
        } finally {
            Minecraft.getInstance().options.advancedItemTooltips = showAdvancedTooltip;
        }
    }

private static String handleGenericItemGrouping(Item item) {
        if (DUNGEON_ITEMS.contains(item.builtInRegistryHolder().getKey().location().getPath())) {
            // arbitrary group to try to whittle down the full list
            return "Dungeon Items";
        } else if (item instanceof InkItem) {
            return "Ink";
        } else if (item.components().has(DataComponents.JUKEBOX_PLAYABLE)) {
            return "Music Discs";
        } else if (item.getDescriptionId().contains("rune")) {
            return "Runes";
        } else if (item instanceof UpgradeOrbItem || item == ItemRegistry.UPGRADE_ORB.get()) {
            return "Upgrade Orbs";
        } else if (item instanceof DrinkableItem) {
            return "Elixirs";
        } else {
            return "All";
        }
    }

@NotNull
    private static ArrayList<RecipeIngredientData> getRecipeData(Recipe<?> recipe) {
        var resultItemResourceLocation = BuiltInRegistries.ITEM.getKey(recipe.getResultItem(level.registryAccess()).getItem());
        var recipeData = new ArrayList<RecipeIngredientData>(10);
        recipeData.add(new RecipeIngredientData(
                resultItemResourceLocation.toString(),
                recipe.getResultItem(level.registryAccess()).getItem().getName(recipe.getResultItem(level.registryAccess()).getItem().getDefaultInstance()).getString(),
                String.format("/img/items/%s.png", resultItemResourceLocation.getPath()),
                recipe.getResultItem(level.registryAccess()).getItem())
        );
        if (recipe instanceof ShapedRecipe || recipe instanceof ShapelessRecipe) {
            recipe.getIngredients().forEach(ingredient -> {
                handleIngredient(ingredient, recipeData, recipe);
            });
        } else if (recipe instanceof SmithingTransformRecipe smithingRecipe) {
            handleIngredient(Ingredient.of(BuiltInRegistries.ITEM.stream().map(Item::getDefaultInstance).filter(smithingRecipe::isTemplateIngredient).findFirst().orElse(ItemStack.EMPTY)), recipeData, recipe);
            handleIngredient(Ingredient.of(BuiltInRegistries.ITEM.stream().map(Item::getDefaultInstance).filter(smithingRecipe::isBaseIngredient).findFirst().orElse(ItemStack.EMPTY)), recipeData, recipe);
            handleIngredient(Ingredient.of(BuiltInRegistries.ITEM.stream().map(Item::getDefaultInstance).filter(smithingRecipe::isAdditionIngredient).findFirst().orElse(ItemStack.EMPTY)), recipeData, recipe);
        } else if (recipe instanceof NoAdditionSmithingTransformRecipe smithingRecipe) {
            handleIngredient(Ingredient.of(BuiltInRegistries.ITEM.stream().map(Item::getDefaultInstance).filter(smithingRecipe::isTemplateIngredient).findFirst().orElse(ItemStack.EMPTY)), recipeData, recipe);
            handleIngredient(Ingredient.of(BuiltInRegistries.ITEM.stream().map(Item::getDefaultInstance).filter(smithingRecipe::isBaseIngredient).findFirst().orElse(ItemStack.EMPTY)), recipeData, recipe);
        }
        return recipeData;
    }

private static @Nullable Recipe getRecipeFor(CommandSourceStack sourceStack, Item item) {
        return sourceStack.getRecipeManager().getRecipes().stream()
                .filter(recipe -> recipe.value().getResultItem(level.registryAccess()).is(item))
                // max prioritizes smithing recipes over crafting recipes (If both present) due to alphabetical sorting
                .max(Comparator.comparing(recipeHolder -> BuiltInRegistries.RECIPE_TYPE.getKey(recipeHolder.value().getType()).toString()))
