public static ItemStack from(FluidStack stack) {
        if (stack.getAmount() < 250 || !(stack.is(Tags.Fluids.WATER) || stack.has(DataComponents.POTION_CONTENTS))) {
            return ItemStack.EMPTY;
        }
        PotionFluid.BottleType type = stack.getOrDefault(ComponentRegistry.POTION_BOTTLE_TYPE, PotionFluid.BottleType.REGULAR);
        Item item = type == BottleType.LINGERING ? Items.LINGERING_POTION
                : type == BottleType.SPLASH ? Items.SPLASH_POTION
                : Items.POTION;
        var is = new ItemStack(item);
        is.set(DataComponents.POTION_CONTENTS, stack.getOrDefault(DataComponents.POTION_CONTENTS, new PotionContents(Potions.WATER)));
        return is;
    }

private void setupResultSlot(AbstractSpell spell) {
        ItemStack scrollStack = this.blankScrollSlot.getItem();
        ItemStack inkStack = this.inkSlot.getItem();
        ItemStack focusStack = this.focusSlot.getItem();
        ItemStack resultStack = ItemStack.EMPTY;
        if (!scrollStack.isEmpty() && !inkStack.isEmpty() && !focusStack.isEmpty() &&
                !spell.equals(SpellRegistry.none()) &&
                spell.allowCrafting() &&
                SchoolRegistry.getSchoolsFromFocus(focusStack).contains(spell.getSchoolType())) {
            if (scrollStack.getItem().equals(Items.PAPER) && inkStack.getItem() instanceof InkItem inkItem) {
                resultStack = new ItemStack(ItemRegistry.SCROLL.get());
                resultStack.setCount(1);
                ISpellContainer.createScrollContainer(spell, spell.getMinLevelForRarity(inkItem.getRarity()), resultStack);
            }
        }

        if (!ItemStack.matches(resultStack, this.resultSlot.getItem())) {
            if (resultStack.isEmpty()) {
                this.spellRecipeSelection = SpellRegistry.none();
            }
            this.resultSlot.set(resultStack);
        }
    }

