        if (event.getTarget() instanceof Creeper creeper) {
            var player = event.getEntity();
            var hand = event.getHand();
            var useItem = player.getItemInHand(hand);
            if (useItem.is(Items.GLASS_BOTTLE) && creeper.isPowered()) {
