                            GoldenSacrificialBowlBlockEntity.this.startRitual(GoldenSacrificialBowlBlockEntity.this.castingPlayer, activationItemStack, ritualRecipe);
                    }).updateSnapshots(tx);
                }

                return inserted;
            }

