public void clone(FamiliarSettingsData settings) {
        for (Entry<EntityType<?>, FamiliarEffectSettings> entry : settings.familiarEnabled.entrySet())
            this.familiarEnabled.put(entry.getKey(), entry.getValue());
    }

public void deserializeNBT(Provider provider, CompoundTag tag) {
        this.familiarEnabled.clear();

        for (String entityKey : tag.keySet()) {
            Identifier entityId = Identifier.parse(entityKey);

            EntityType<?> entityType = BuiltInRegistries.ENTITY_TYPE.getValue(entityId);

            CompoundTag familiarTag = tag.getCompoundOrEmpty(entityKey);

            boolean enabled = familiarTag.getBooleanOr("enabled", true);

            Map<Holder<MobEffect>, Byte> effects = new HashMap<>();

            CompoundTag effectsTag = familiarTag.getCompoundOrEmpty("effects");

            for (String effectKey : effectsTag.keySet()) {
                Identifier effectId = Identifier.parse(effectKey);

                Optional<Holder.Reference<MobEffect>> holder =
                        BuiltInRegistries.MOB_EFFECT.get(ResourceKey.create(Registries.MOB_EFFECT, effectId));

                holder.ifPresent(effect ->
                        effects.put(effect, effectsTag.getByteOr(effectKey, (byte) 0)));
            }

            this.familiarEnabled.put(entityType, new FamiliarEffectSettings(enabled, effects));
        }
    }

@Override
    public void deserialize(ValueInput input) {
        this.familiarEnabled.clear();

        for (EntityType<?> familiar : getFamiliars()) {
            Identifier entityId = BuiltInRegistries.ENTITY_TYPE.getKey(familiar);

            Optional<ValueInput> familiarInput = input.child(entityId.toString());

            if (familiarInput.isEmpty()) {
                continue;
            }

            ValueInput familiarTag = familiarInput.get();

            boolean enabled = familiarTag.getBooleanOr("enabled", true);

            Map<Holder<MobEffect>, Byte> effects = new HashMap<>();

            ValueInput effectsInput = familiarTag.childOrEmpty("effects");

            ImmutableList<FamiliarEffects.FamiliarEffectDefinition> definitions =
                    FamiliarEffects.effectMap().get(familiar);

            if (definitions != null) {
                for (var definition : definitions) {
                    Identifier effectId = definition.effect()
                            .unwrapKey()
                            .orElseThrow()
                            .identifier();

                    byte amplifier = effectsInput.getByteOr(
                            effectId.toString(),
                            definition.iesniumValue());

                    effects.put(definition.effect(), amplifier);
                }
            }

            this.familiarEnabled.put(
                    familiar,
                    new FamiliarEffectSettings(enabled, effects));
        }
    }

public boolean hasIngredient(Ingredient ingredient, Object2IntOpenHashMap<Object> reservedAmounts) {
        //First check the crafting grid if it has the required items
        for (int i = 1; i < 10; i++) {
            var slot = this.getSlot(i);
            var stackInSlot = slot.getItem();
            if (!stackInSlot.isEmpty() && ingredient.test(stackInSlot)) {
                var reservedAmount = reservedAmounts.getOrDefault(slot, 0);
                if (stackInSlot.getCount() > reservedAmount) {
                    reservedAmounts.merge(slot, 1, Integer::sum);
                    return true;
                }
            }
        }

        //then check the storage system local cache
        var clientCache = this.getClientStorageCache();
        if (clientCache == null) {
            return false;
        }

        for (var stack : clientCache.getByIngredient(ingredient)) {
            var reservedAmount = reservedAmounts.getOrDefault(stack, 0);
            if (stack.getCount() - reservedAmount >= 1) {
                reservedAmounts.merge(stack, 1, Integer::sum);
                return true;
            }
        }

        return false;
    }

protected List<ItemStack> getCraftingMatrixFromItemStack(ItemStack stack) {
        List<ItemStack> craftingMatrix = new ArrayList<>(Collections.nCopies(9, ItemStack.EMPTY));
        if (!stack.has(OccultismDataComponents.CRAFTING_MATRIX))
            return craftingMatrix;

        ListTag nbtTagList = stack.get(OccultismDataComponents.CRAFTING_MATRIX).copyTag().getListOrEmpty("craftingMatrix");

        for (int i = 0; i < nbtTagList.size(); i++) {
            craftingMatrix.set(i, ItemStack.OPTIONAL_CODEC.parse(this.player.registryAccess().createSerializationContext(NbtOps.INSTANCE), nbtTagList.getCompoundOrEmpty(i)).result().orElse(ItemStack.EMPTY));
        }

        return craftingMatrix;
    }

protected ItemStack getOrderStackFromItemStack(ItemStack stack) {
        if (!stack.has(OccultismDataComponents.ORDER_STACK))
            return ItemStack.EMPTY;

        return ItemStack.OPTIONAL_CODEC.parse(this.player.registryAccess().createSerializationContext(NbtOps.INSTANCE), stack.get(OccultismDataComponents.ORDER_STACK).copyTag()).result().orElse(ItemStack.EMPTY);
    }

