                //refresh item nbt
                ItemNBTUtil.updateItemNBTFromEntity(itemStack, entity);

                itemStack.remove(OccultismDataComponents.SPIRIT_ENTITY_DATA);
                itemStack.set(DataComponents.RARITY, Rarity.COMMON);
                if (player != null)
                    player.inventoryMenu.broadcastChanges();
            }
