						.openContextMenu(getGui());
			}
		} else if (button.isLeft()) {
			if (isCtrlKeyDown() && canEdit) {
				if (questScreen.isViewingQuest()) {
					questScreen.closeQuest();
				}
				questScreen.toggleSelected(moveAndDeleteFocus());
			} else if (isKeyDown(InputConstants.KEY_LALT) && canEdit) {
				theQuestObject().onEditButtonClicked(questScreen);
			} else if (isKeyDown(InputConstants.KEY_RALT) && canEdit) {
				quest.copyToClipboard();
				Minecraft.getInstance().getToasts().addToast(new CustomToast(Component.translatable("ftbquests.quest.copied"),
						Icons.INFO, Component.literal(moveAndDeleteFocus().getTitle().getString())));
			} else if (!quest.getGuidePage().isEmpty() && quest.getTasks().isEmpty() && quest.getRewards().isEmpty() && quest.getDescription().isEmpty()) {
				handleClick("guide", quest.getGuidePage());
			} else if (canEdit || !quest.hideDetailsUntilStartable() || questScreen.file.selfTeamData.canStartTasks(quest)) {
				questScreen.open(theQuestObject(), false);
			}
		} else if (canEdit && button.isMiddle()) {
			if (!questScreen.selectedObjects.contains(moveAndDeleteFocus())) {
				questScreen.toggleSelected(moveAndDeleteFocus());
			}

			questScreen.movingObjects = true;
		} else if (button.isRight()) {
			questScreen.movingObjects = false;

			if (questScreen.getViewedQuest() != quest) {
				questScreen.viewQuest(quest);
			} else {
				questScreen.closeQuest();
			}
		}
	}

private void bulkChangeSize() {
		Collection<Quest> quests = questScreen.getSelectedQuests();
		if (quests.isEmpty()) return;

		var c = new DoubleConfig(0.0625D, 8D);
		c.setValue(quests.stream().findFirst().map(Quest::getSize).orElse(1.0));

		EditStringConfigOverlay<Double> overlay = new EditStringConfigOverlay<>(getGui(), c, accepted -> {
			if (accepted) {
				quests.forEach(q -> {
					q.setSize(c.getValue());
					new EditObjectMessage(q).sendToServer();
				});
			}
			run();
		}, Component.translatable("ftbquests.quest.appearance.size")).atMousePosition();
		overlay.setExtraZlevel(600);
		getGui().pushModalPanel(overlay);
	}

@Override
	public void addMouseOverText(TooltipList list) {
		questScreen.addInfoTooltip(list, quest);

		Component title = getTitle();

		TeamData teamData = questScreen.file.selfTeamData;

		if (teamData != null) {
			if (teamData.isStarted(quest) && !teamData.isCompleted(quest)) {
				title = title.copy().append(Component.literal(" " + teamData.getRelativeProgress(quest) + "%").withStyle(ChatFormatting.DARK_GRAY));
			}
		}

		if (title.getString().contains("\n")) {
			// I'm not proud of this kludge but getting titles with embedded newlines and possible styling
			// to work well as tooltips is not fun
			title.visit((style, txt) -> {
				for (String s : txt.split("\n")) {
					if (!s.isEmpty()) list.add(Component.literal(s).withStyle(style));
				}
				return Optional.empty();
			}, title.getStyle());
		} else {
			list.add(title);
		}

		Component description = quest.getSubtitle();

		if (description.getContents() != ComponentContents.EMPTY) {
			list.add(Component.literal("").append(description).withStyle(ChatFormatting.GRAY));
		}

		if (quest.isOptional()) {
			list.add(Component.literal("[").withStyle(ChatFormatting.GRAY).append(Component.translatable("ftbquests.quest.misc.optional")).append("]"));
		}
		if (quest.canBeRepeated()) {
			list.add(Component.translatable("ftbquests.quest.misc.can_repeat").withStyle(ChatFormatting.GRAY));
			if (teamData != null) {
				int completionCount = teamData.getCompletionCount(quest);
				if (completionCount > 0) {
					String key = completionCount > 1 ? "ftbquests.quest.misc.completion_count.plural" : "ftbquests.quest.misc.completion_count";
					list.add(Component.translatable(key, completionCount).withStyle(ChatFormatting.GRAY));
				}
			}
		}
		if (teamData != null && !teamData.canStartTasks(quest)) {
			Component reason = teamData.getCannotStartReason(this.quest);
			list.add(Component.literal("[").withStyle(ChatFormatting.DARK_GRAY).append(reason).append("]"));
		}
		if (quest.isExclusiveQuest()) {
			list.add(Component.translatable("ftbquests.quest.misc.exclusive").withStyle(ChatFormatting.GOLD));
			list.add(Component.translatable("ftbquests.quest.misc.exclusive.desc").withStyle(Style.EMPTY.withColor(0xFFC08000)));
		}
	}

@Override
	public void draw(GuiGraphics graphics, Theme theme, int x, int y, int w, int h) {
		Color4I outlineColor = ThemeProperties.QUEST_NOT_STARTED_COLOR.get(quest);
		Icon questIcon = Color4I.empty() ;
		Icon hiddenIcon = Color4I.empty();
		Icon lockIcon = Color4I.empty();

		TeamData teamData = questScreen.file.selfTeamData;
		boolean isCompleted = teamData.isCompleted(quest);
		boolean isStarted = isCompleted || teamData.isStarted(quest);
		boolean canStart = teamData.canStartTasks(quest);
		Player player = Minecraft.getInstance().player;

		if (canStart) {
			if (isCompleted) {
				if (teamData.hasUnclaimedRewards(player.getUUID(), quest)) {
					questIcon = ThemeProperties.ALERT_ICON.get(quest);
				} else if (teamData.isQuestPinned(player, quest.id)) {
					questIcon = ThemeProperties.PIN_ICON_ON.get();
				} else {
					questIcon = ThemeProperties.CHECK_ICON.get(quest);
				}

				outlineColor = ThemeProperties.QUEST_COMPLETED_COLOR.get(quest);
			} else if (isStarted) {
				if (teamData.areDependenciesComplete(quest)) {
					outlineColor = ThemeProperties.QUEST_STARTED_COLOR.get(quest);
				}
				if (quest.getProgressionMode() == ProgressionMode.FLEXIBLE && quest.allTasksCompleted(teamData)) {
					questIcon = new ThemeProperties.CheckIcon(Color4I.rgb(0x606060), Color4I.rgb(0x808080));
				}
			}
		} else {
			outlineColor = ThemeProperties.QUEST_LOCKED_COLOR.get(quest);
		}

		if (questIcon == Color4I.empty() && teamData.isQuestPinned(player, quest.id)) {
			questIcon = ThemeProperties.PIN_ICON_ON.get();
		}
		if (questScreen.file.canEdit() && !quest.isVisible(teamData)) {
			hiddenIcon = ThemeProperties.HIDDEN_ICON.get();
		}

		QuestShape shape = QuestShape.get(getShape());

		if (shape.shouldDraw()) {
			shape.getShape().withColor(Color4I.DARK_GRAY).draw(graphics, x, y, w, h);
			shape.getBackground().withColor(Color4I.WHITE.withAlpha(150)).draw(graphics, x, y, w, h);
			shape.getOutline().withColor(outlineColor).draw(graphics, x, y, w, h);
		}

		PoseStack poseStack = graphics.pose();

		if (!icon.isEmpty()) {
			float s = w * (2F / 3F) * (float) quest.getIconScale();
			poseStack.pushPose();
			poseStack.translate(x + (w - s) / 2D, y + (h - s) / 2D, 0);
			poseStack.scale(s, s, 1F);
			icon.draw(graphics, 0, 0, 1, 1);
			poseStack.popPose();
		}

		GuiHelper.setupDrawing();
		// TODO: custom shader to implement alphaFunc?
		//RenderSystem.alphaFunc(GL11.GL_GREATER, 0.1F);

		if (questScreen.getViewedQuest() == quest || questScreen.selectedObjects.contains(moveAndDeleteFocus())) {
			poseStack.pushPose();
			poseStack.translate(0, 0, 1);
			Color4I col = Color4I.WHITE.withAlpha((int) (190D + Math.sin(System.currentTimeMillis() * 0.003D) * 50D));
			shape.getOutline().withColor(col).draw(graphics, x, y, w, h);
			shape.getBackground().withColor(col).draw(graphics, x, y, w, h);
			poseStack.popPose();
		}

		if (!canStart || !teamData.areDependenciesComplete(quest)) {
			if (shape.shouldDraw()) {
				shape.getShape().withColor(Color4I.BLACK.withAlpha(100)).draw(graphics, x, y, w, h);
			}
			if (quest.getQuestFile().showLockIcons() && FTBQuestsClientConfig.SHOW_LOCK_ICON.get()) {
				lockIcon = ThemeProperties.LOCK_ICON.get();
			}
		}

		if (isMouseOver()) {
			shape.getShape().withColor(Color4I.WHITE.withAlpha(100)).draw(graphics, x, y, w, h);
		}

		if (!questIcon.isEmpty()) {
			float s = w / 8F * 3F;
			poseStack.pushPose();
			poseStack.translate(x + w - s, y, 0);
			poseStack.scale(s, s, 1F);
			questIcon.draw(graphics, 0, 0, 1, 1);
			poseStack.popPose();
		}

		if (!hiddenIcon.isEmpty()) {
			float s = w / 8F * 3F;
			poseStack.pushPose();
			poseStack.translate(x, y, 0);
			poseStack.scale(s, s, 1F);
			hiddenIcon.draw(graphics, 0, 0, 1, 1);
			poseStack.popPose();
		}

		if (!lockIcon.isEmpty() && !quest.shouldHideLockIcon()) {
			int s = (int) (w / 8F * 3F);
			poseStack.pushPose();
			poseStack.translate(x + w - s, y + h - 1 - s, 0);
			lockIcon.draw(graphics, 0, 0, s, s);
			poseStack.popPose();
		}
	}

@Override
	public void drawOffsetBackground(GuiGraphics graphics, Theme theme, int x, int y, int w, int h) {
		if (questScreen.selectedChapter == null || questScreen.file.selfTeamData == null) {
			return;
		}

		Tesselator tesselator = Tesselator.getInstance();
		BufferBuilder buffer = tesselator.getBuilder();

		Icon icon = ThemeProperties.DEPENDENCY_LINE_TEXTURE.get(questScreen.selectedChapter);
		if (icon instanceof ImageIcon img) {
			img.bindTexture();
		} else {
			DEFAULT_DEPENDENCY_LINE_TEXTURE.bindTexture();
		}

		Quest selectedQuest = questScreen.getViewedQuest();
		if (selectedQuest == null) {
			Collection<Quest> sel = questScreen.getSelectedQuests();
			if (sel.size() == 1) {
				selectedQuest = questScreen.getSelectedQuests().stream().findFirst().orElse(null);
			}
		}

		double mt = -(System.currentTimeMillis() * 0.001D);
		float lineWidth = (float) (questScreen.getZoom() * ThemeProperties.DEPENDENCY_LINE_THICKNESS.get(questScreen.selectedChapter) / 4D * 3D);

		RenderSystem.setShader(GameRenderer::getPositionColorTexShader);
		RenderSystem.setShaderColor(1F, 1F, 1F, 1F);

		// pass 1: render connections for all visible quests
		float mu = (float) ((mt * ThemeProperties.DEPENDENCY_LINE_UNSELECTED_SPEED.get(questScreen.selectedChapter)) % 1D);
		for (Widget widget : widgets) {
			if (widget.shouldDraw() && widget instanceof QuestButton qb && (!qb.quest.shouldHideDependencyLines() || qb.isMouseOver())) {
				boolean unavailable = !questScreen.file.selfTeamData.canStartTasks(qb.quest);
				boolean complete = !unavailable && questScreen.file.selfTeamData.isCompleted(qb.quest);
				Color4I c = complete ?
						ThemeProperties.DEPENDENCY_LINE_COMPLETED_COLOR.get(questScreen.selectedChapter) :
						ThemeProperties.DEPENDENCY_LINE_UNCOMPLETED_COLOR.get(questScreen.selectedChapter);
				if (unavailable || qb.quest.getProgressionMode() == ProgressionMode.FLEXIBLE && !questScreen.file.selfTeamData.areDependenciesComplete(qb.quest)) {
					// dim connection lines for unavailable quests
					c = c.withAlpha(Math.max(30, c.alphai() / 2));
				}

				for (QuestButton button : qb.getDependencies()) {
					if (button.shouldDraw() && button.quest != selectedQuest && qb.quest != selectedQuest && !button.quest.shouldHideDependentLines()) {
						renderConnection(widget, button, graphics.pose(), buffer, lineWidth,
								c.redi(), c.greeni(), c.bluei(), c.alphai(), c.alphai(),
								mu, tesselator);
					}
				}
			}

		}

		// pass 2: render highlighted connections for hovered quest(s) dependencies/dependents
		float ms = (float) ((mt * ThemeProperties.DEPENDENCY_LINE_SELECTED_SPEED.get(questScreen.selectedChapter)) % 1D);
		List<QuestButton> toOutline = new ArrayList<>();
		for (Widget widget : widgets) {
			if (widget.shouldDraw() && widget instanceof QuestButton qb && !qb.quest.shouldHideDependencyLines()) {
				for (QuestButton button : qb.getDependencies()) {
					if (button.shouldDraw()) {
						if (button.quest == selectedQuest || button.isMouseOver()) {
							Color4I c = ThemeProperties.DEPENDENCY_LINE_REQUIRED_FOR_COLOR.get(questScreen.selectedChapter);
							int a, a2;
							if (qb.shouldDraw()) {
								a = a2 = c.alphai();
							} else {
								a = c.alphai() / 4 * 3;
								a2 = 30;
								toOutline.add(qb);
							}
							renderConnection(widget, button, graphics.pose(), buffer, lineWidth, c.redi(), c.greeni(), c.bluei(), a2, a, ms, tesselator);
						} else if (qb.quest == selectedQuest || qb.isMouseOver()) {
							Color4I c = ThemeProperties.DEPENDENCY_LINE_REQUIRES_COLOR.get(questScreen.selectedChapter);
							renderConnection(widget, button, graphics.pose(), buffer, lineWidth, c.redi(), c.greeni(), c.bluei(), c.alphai(), c.alphai(), ms, tesselator);
						}
					}
				}
			}

		}
		toOutline.forEach(qb -> {
			QuestShape.get(qb.quest.getShape()).getShape()
					.withColor(Color4I.BLACK.withAlpha(30))
					.draw(graphics, qb.getX(), qb.getY(), qb.width, qb.height);
			QuestShape.get(qb.quest.getShape()).getOutline()
					.withColor(Color4I.BLACK.withAlpha(90))
					.draw(graphics, qb.getX(), qb.getY(), qb.width, qb.height);
		});
	}

@Override
	public void draw(GuiGraphics graphics, Theme theme, int x, int y, int w, int h) {
		super.draw(graphics, theme, x, y, w, h);

		if (questScreen.selectedChapter != null && isMouseOver()) {
			double dx = (questMaxX - questMinX);
			double dy = (questMaxY - questMinY);

			double px = getX() - getScrollX();
			double py = getY() - getScrollY();

			double qx = (questScreen.getMouseX() - px) / questScreen.scrollWidth * dx + questMinX;
			double qy = (questScreen.getMouseY() - py) / questScreen.scrollHeight * dy + questMinY;
			centerQuestX = (questScreen.width / 2D - px) / questScreen.scrollWidth * dx + questMinX;
			centerQuestY = (questScreen.height / 2D - py) / questScreen.scrollHeight * dy + questMinY;

			if (isShiftKeyDown()) {
				questX = qx;
				questY = qy;
			} else {
				// grid-snapping size is based on the smallest selected item
				//   although images always act as if they were size 1
				double minSize = questScreen.selectedObjects.stream()
						.map(m -> m instanceof ChapterImage ? 1d : m.getWidth())
						.min(Double::compare)
						.orElse(1d);
				double snap = 1D / (questScreen.file.getGridScale() * minSize);
				questX = Mth.floor(qx * snap + 0.5D) / snap;
				questY = Mth.floor(qy * snap + 0.5D) / snap;
			}

			if (questScreen.file.canEdit()) {
				PoseStack poseStack = graphics.pose();

				drawStatusBar(graphics, theme, poseStack);

				double bs = questScreen.getQuestButtonSize();

				if (questScreen.movingObjects && !questScreen.selectedObjects.isEmpty()) {
					double ominX = Double.POSITIVE_INFINITY, ominY = Double.POSITIVE_INFINITY, omaxX = Double.NEGATIVE_INFINITY, omaxY = Double.NEGATIVE_INFINITY;

					for (Movable q : questScreen.selectedObjects) {
						ominX = Math.min(ominX, q.getX());
						ominY = Math.min(ominY, q.getY());
						omaxX = Math.max(omaxX, q.getX());
						omaxY = Math.max(omaxY, q.getY());
					}

					for (Movable m : questScreen.selectedObjects) {
						double ox = m.getX() - ominX;
						double oy = m.getY() - ominY;
						double sx = (questX + ox - questMinX) / dx * questScreen.scrollWidth + px;
						double sy = (questY + oy - questMinY) / dy * questScreen.scrollHeight + py;
						poseStack.pushPose();
						poseStack.translate(sx - bs * m.getWidth() / 2D, sy - bs * m.getHeight() / 2D, 0D);
						poseStack.scale((float) (bs * m.getWidth()), (float) (bs * m.getHeight()), 1F);
						GuiHelper.setupDrawing();
						RenderSystem.enableDepthTest();
						m.drawMoved(graphics);
						poseStack.popPose();
					}

					if (QuestScreen.grid && !questScreen.isViewingQuest()) {
						double boxX = ominX / dx * questScreen.scrollWidth + px;
						double boxY = ominY / dy * questScreen.scrollHeight + py;
						double boxW = omaxX / dx * questScreen.scrollWidth + px - boxX;
						double boxH = omaxY / dy * questScreen.scrollHeight + py - boxY;

						poseStack.pushPose();
						poseStack.translate(0, 0, 200);
						GuiHelper.drawHollowRect(graphics, (int) Math.round(boxX), (int) Math.round(boxY), (int) Math.round(boxW), (int) Math.round(boxH), Color4I.WHITE.withAlpha(30), false);
						poseStack.popPose();
					}
				} else if (!questScreen.isViewingQuest() || !questScreen.viewQuestPanel.isMouseOver()) {
					//int z = treeGui.getZoom();
					double sx = (questX - questMinX) / dx * questScreen.scrollWidth + px;
					double sy = (questY - questMinY) / dy * questScreen.scrollHeight + py;
					poseStack.pushPose();
					poseStack.translate(sx - bs / 2D, sy - bs / 2D, 0D);
					poseStack.scale((float) bs, (float) bs, 1F);
					GuiHelper.setupDrawing();
					RenderSystem.enableDepthTest();
					// TODO: custom shader to implement alphaFunc? for now however, rendering outline at alpha 30 works well
					//RenderSystem.alphaFunc(GL11.GL_GREATER, 0.01F);
					QuestShape.get(questScreen.selectedChapter.getDefaultQuestShape()).getOutline().withColor(Color4I.WHITE.withAlpha(30)).draw(graphics, 0, 0, 1, 1);
					//RenderSystem.defaultAlphaFunc();
					poseStack.popPose();

					if (QuestScreen.grid && !questScreen.isViewingQuest()) {
						poseStack.pushPose();
						poseStack.translate(0, 0, 1000);
						Color4I.WHITE.draw(graphics, (int) Math.round(sx), (int) Math.round(sy), 1, 1);
						Color4I.WHITE.withAlpha(30).draw(graphics, getX(), (int) sy, width, 1);
						Color4I.WHITE.withAlpha(30).draw(graphics, (int) Math.round(sx), getY(), 1, height);
						poseStack.popPose();
					}
				}
			}
		}
	}

public void toggleSelected(Movable movable) {
		viewQuest(null);

		if (selectedObjects.contains(movable)) {
			selectedObjects.remove(movable);
		} else {
			selectedObjects.add(movable);
		}
	}

private boolean copyObjectsToClipboard() {
		Movable toCopy = null;

		if (selectedObjects.size() > 1) {
			displayError(Component.translatable("ftbquests.quest.cannot_copy_many"));
		} else if (selectedObjects.isEmpty()) {
			// no objects selected: copy hovered object if there is one
			toCopy = questPanel.getWidgets().stream()
					.filter(w -> w instanceof QuestPositionableButton && w.isMouseOver())
					.map(w -> ((QuestPositionableButton) w).moveAndDeleteFocus())
					.findFirst()
					.orElse(null);
		} else {
			// one object selected
			toCopy = selectedObjects.get(0);
		}

		if (toCopy != null) {
			toCopy.copyToClipboard();
			Minecraft.getInstance().getToasts().addToast(new CustomToast(Component.translatable("ftbquests.quest.copied"),
					Icons.INFO, Component.literal(toCopy.getTitle().getString())));
			return true;
		}

		return false;
	}

private boolean pasteSelectedQuest(boolean withDeps) {
		if (ChapterImage.isImageInClipboard()) {
			return pasteSelectedImage();
		} else {
			return QuestObjectBase.parseHexId(getClipboardString()).map(id -> {
				Quest quest = file.getQuest(id);
				if (quest == null) return false;
				Pair<Double, Double> qxy = getSnappedXY();
				new CopyQuestMessage(quest, selectedChapter, qxy.getFirst(), qxy.getSecond(), withDeps).sendToServer();
				return true;
			}).orElse(false);
		}
	}

private boolean pasteSelectedImage() {
		return ChapterImageButton.getClipboardImage().map(clipImg -> {
			Pair<Double,Double> qxy = getSnappedXY();
			new CopyChapterImageMessage(clipImg, selectedChapter, qxy.getFirst(), qxy.getSecond()).sendToServer();
			return true;
		}).orElse(false);
	}

private boolean pasteSelectedQuestLinks() {
		String clip = getClipboardString();
		if (clip.isEmpty()) return false;

		return QuestObjectBase.parseHexId(clip).map(id -> {
			if (file.getQuest(id) == null) return false;
			Pair<Double,Double> qxy = getSnappedXY();
			QuestLink link = new QuestLink(0L, selectedChapter, id);
			link.setPosition(qxy.getFirst(), qxy.getSecond());
			new CreateObjectMessage(link, new CompoundTag(), false).sendToServer();
			return true;
		}).orElse(false);
	}

void selectAllQuestsInBox(int mouseX, int mouseY, double scrollX, double scrollY) {
		int x1 = Math.min(prevMouseX, mouseX);
		int x2 = Math.max(prevMouseX, mouseX);
		int y1 = Math.min(prevMouseY, mouseY);
		int y2 = Math.max(prevMouseY, mouseY);
		Rect2i rect = new Rect2i(x1, y1, x2 - x1, y2 - y1);

		if (!Screen.hasControlDown()) selectedObjects.clear();

		questPanel.getWidgets().forEach(w -> {
			if (w instanceof QuestPositionableButton qb && rect.contains((int) (w.getX() - scrollX), (int) (w.getY() - scrollY))) {
				toggleSelected(qb.moveAndDeleteFocus());
			}
		});
	}

