private void doLinkInsertion(String action, String replacementText) {
		String text = textBox.getSelectedText();
		if (!text.contains("\n")) {
			// a selection which doesn't extend over multiple physical lines; replace the selection in a smart way
			StringExtents lineExtents = getPhysicalLineExtents();
			StringExtents selectionExtents = textBox.getSelected();

			if (lineExtents.start() == lineExtents.end() || selectionExtents.start() == selectionExtents.end()) {
				return;
			}

			String thisLine = textBox.getText().substring(lineExtents.start(), lineExtents.end());
			if (thisLine.startsWith("[") && thisLine.endsWith("]")) {
				errorToPlayer("ftbquests.gui.error.already_component");
				return;
			}

			List<String> parts = List.of(
					textBox.getText().substring(lineExtents.start(), selectionExtents.start()),
					textBox.getText().substring(selectionExtents.start(), selectionExtents.end()),
					textBox.getText().substring(selectionExtents.end(), lineExtents.end())
			);

			StringBuilder builder = new StringBuilder("[ ");
			if (!parts.get(0).isEmpty()) builder.append("\"").append(parts.get(0)).append("\", ");
			builder.append(String.format(LINK_TEXT_TEMPLATE, parts.get(1).isEmpty() ? "EDIT HERE" : parts.get(1), action, replacementText));
			if (!parts.get(2).isEmpty()) builder.append(", ").append("\"").append(parts.get(2)).append("\"");
			builder.append(" ]");

			replaceText(lineExtents, builder.toString());
		} else {
			errorToPlayer("ftbquests.gui.error.selection_multiple_lines");
		}
	}

private boolean isOkForLinkInsertion() {
			return textBox.hasSelection() && !textBox.getSelectedText().contains("\n");
		}

public void draw(GuiGraphics graphics, QuestScreen questScreen) {
        boolean forceShow = FTBQuestsClientConfig.CHANGELOG_ALWAYS_SHOW.get();
        float alpha = forceShow ? 1f : getDisplayAlpha();
        if (alpha > 0f) {
            float fontScale = FTBQuestsClientConfig.CHANGELOG_FONT_SCALE.get().floatValue();
            long displayTime = (long) (FTBQuestsClientConfig.CHANGELOG_SHOW_TIME.get() * 1000L);

            var recent = getRecent(FTBQuestsClientConfig.CHANGELOG_MAX_LINES.get());
            if (recent.isEmpty()) {
                return;
            }

            List<Pair<ChangeRecord, Component>> lines = recent.stream().map(rec -> Pair.of(rec, rec.format())).toList();

            Theme theme = questScreen.getGui().getTheme();
            int lh = Math.round(theme.getFontHeight() * fontScale);
            int w = (int) (lines.stream()
                    .map(p -> theme.getStringWidth(p.getSecond()))
                    .max(Integer::compareTo)
                    .orElse(100) * fontScale
            );
            int x = questScreen.getChapterPanelRight();
            int y = questScreen.questPanel.height - 10 - lh;

            graphics.pose().translate(0, 0, QuestScreen.Z_LEVEL);
            Color4I.BLACK.withAlpha((int) (100 * alpha)).draw(graphics, x, y - lh * (recent.size() - 1) - 2, w + 4, lh * recent.size() + 4);

            boolean first = true;
            for (var entry : lines) {
                float lineAlpha = Util.getEpochMillis() - entry.getFirst().timestamp() < displayTime || first ? 1f : 0.5f;
                entry.getFirst().drawAt(graphics, entry.getSecond(), theme.getFont(), x + 2, y, fontScale, Math.max(0.1f, alpha * lineAlpha));
                y -= lh;
                first = false;
            }

            graphics.pose().translate(0, 0, QuestScreen.Z_LEVEL);
        }
    }

private boolean shouldShowButton(Reward reward) {
            return switch (selfData.getClaimType(Minecraft.getInstance().player.getUUID(), reward)) {
