                case CLAIMED -> selfData.getRewardClaimTime(Minecraft.getInstance().player.getUUID(), reward)
                        .map(date -> date.getTime() > rewardInfoGenerated).orElse(false);
                case CAN_CLAIM -> true;
            };
        }

