private void deleteRewardTable() {
			if (pendingDeleteIndexes.contains(idx)) {
				pendingDeleteIndexes.remove(idx);
			} else {
				pendingDeleteIndexes.add(idx);
			}
			changed = true;
			refreshWidgets();
