@Nullable
	public static LootCrate getCrate(ItemStack stack, boolean isClientSide) {
		return FTBQuests.getComponent(stack, ModDataComponents.LOOT_CRATE)
				.map(type -> LootCrate.getLootCrates(isClientSide).get(type))
				.orElse(null);
	}

@Override
	@Environment(EnvType.CLIENT)
	public void appendHoverText(ItemStack stack, TooltipContext context, List<Component> tooltip, TooltipFlag flag) {
		if (context.registries() == null || !ClientQuestFile.exists()) {
			return;
		}

		LootCrate crate = getCrate(stack, true);
		if (crate != null) {
			if (crate.getItemName().isEmpty()) {
				// if crate doesn't have an item name, show the reward table's name in the tooltip
				tooltip.add(Component.literal(crate.getStringID()).withStyle(ChatFormatting.YELLOW));
				tooltip.add(Component.empty());
			}
			tooltip.add(Component.translatable("item.ftbquests.lootcrate.tooltip_1").withStyle(ChatFormatting.GRAY));
			tooltip.add(Component.translatable("item.ftbquests.lootcrate.tooltip_2").withStyle(ChatFormatting.GRAY));
		} else {
			String name = stack.getOrDefault(ModDataComponents.LOOT_CRATE.get(), "");
			// stay quiet if there's no loot crate ID at all
			if (!name.isEmpty()) {
				tooltip.add(Component.translatable("item.ftbquests.lootcrate.missing", name).withStyle(ChatFormatting.RED));
			}
		}
	}

private boolean tryUseOn(ServerPlayer player, ItemStack stack) {
        return readBlockPos(stack).map(gPos -> {
            Level level = player.getServer().getLevel(gPos.dimension());
            if (level != player.level() || !player.level().isLoaded(gPos.pos())) {
                player.displayClientMessage(Component.translatable("ftbquests.message.task_screen_inaccessible").withStyle(ChatFormatting.RED), true);
                return false;
            }
            if (level.getBlockEntity(gPos.pos()) instanceof ITaskScreen taskScreen) {
                if (taskScreen.hasPermissionToEdit(player)) {
                    taskScreen.getCoreScreen().ifPresent(coreScreen ->
                            NetworkManager.sendToPlayer(player, new BlockConfigRequestMessage(coreScreen.getBlockPos(), BlockConfigRequestMessage.BlockType.TASK_SCREEN)));
                    return true;
                } else {
                    player.displayClientMessage(Component.translatable("block.ftbquests.screen.no_permission").withStyle(ChatFormatting.RED), true);
                }
            } else {
                player.displayClientMessage(Component.translatable("ftbquests.message.missing_task_screen").withStyle(ChatFormatting.RED), true);
            }
            return false;
        }).orElse(false);
    }

public static void handle(CreateObjectResponseMessage message, NetworkManager.PacketContext context) {
		context.queue(() -> FTBQuestsNetClient.createObjects(message.creationRecords, message.creator.orElse(Util.NIL_UUID)));
	}

public static void handle(CreateQuestAndTaskMessage message, NetworkManager.PacketContext context) {
		context.queue(() -> ServerQuestFile.getInstance().ifPresent(sqf -> {
			if (PermissionsHelper.canPlayerEdit(context) && context.getPlayer() instanceof ServerPlayer sp) {
				Chapter chapter = sqf.getChapter(message.chapterId);
				TaskType taskType = ServerQuestFile.INSTANCE.getTaskType(message.taskTypeId);

				if (chapter != null && taskType != null) {
					var allocator = new BaseQuestFile.UniqueIdAllocator(sqf);

					Quest quest = new Quest(allocator.newId(), chapter).setPosition(message.x, message.y);

					Task task = taskType.createTask(allocator.newId(), quest);
					task.readData(message.nbt, context.registryAccess());
					CompoundTag extra = message.extra.orElse(new CompoundTag());
					sqf.getTranslationManager().processInitialTranslation(extra, task);

					List<CreateOrDeleteRecord> recs = CreateOrDeleteRecord.ofQuestObjects(quest, task);
					sqf.getHistoryStack().addAndApply(sqf, new CreateQuestObjects(recs, sp.getUUID()));
				}
			}
		}));
	}

public static void handle(GetEmergencyItemsMessage message, NetworkManager.PacketContext context) {
		context.queue(() -> {
			ServerPlayer player = (ServerPlayer) context.getPlayer();
			long now = Util.getEpochMillis();
			long delta = now - lastItemsGot.getOrDefault(player.getUUID(), 0L);

			if (delta >= ServerQuestFile.INSTANCE.getEmergencyItemsCooldown() * 1000L) {
				ServerQuestFile.INSTANCE.getEmergencyItems()
						.forEach(stack -> ItemStackHooks.giveItem(player, stack.copy()));
				lastItemsGot.put(player.getUUID(), now);
			}
		});
	}

