public String replaceVariables(SelectorProperties selectorProperties, String value) {
		int iter = 0;
		while (iter++ < 30 && value.contains("{{") && value.contains("}}")) {
			for (String k : knownReplacements) {
				String replaced = Objects.requireNonNullElseGet(selectorProperties.properties.get(k), () -> defaults.properties.get(k));
				value = value.replace("{{" + k + "}}", replaced);
			}
		}

		return value;
	}

@Nullable
	public static ThemeSelector parseSelector(String sel) {
		if (sel.isEmpty()) {
			return null;
		} else if (sel.equals("*")) {
			return AllSelector.INSTANCE;
		} else if (sel.startsWith("!")) {
			ThemeSelector s = parseSelector(sel.substring(1));
			return s == null ? null : new NotSelector(s);
		} else if (QuestObjectType.NAME_MAP.map.containsKey(sel)) {
			return new TypeSelector(QuestObjectType.NAME_MAP.get(sel));
		} else if (sel.startsWith("#")) {
			String s = sel.substring(1);
			return s.isEmpty() ? null : new TagSelector(s);
		} else {
			return QuestObjectBase.parseHexId(sel).map(IDSelector::new).orElse(null);
		}
	}

public void loadFromNBT(BaseQuestFile file, Path langFolder) {
        map.clear();

        if (!Files.exists(langFolder)) {
            // the first run, hopefully...
            try {
                Files.createDirectory(langFolder);
            } catch (IOException e) {
                FTBQuests.LOGGER.error("can't create lang folder {}: {}", langFolder, e.getMessage());
                return;
            }
        }

        try (Stream<Path> s = Files.list(langFolder)) {
            s.filter(TranslationManager::isValidLangFile).forEach(path -> {
                CompoundTag langNBT = SNBT.read(path);
                if (langNBT != null) {
                    String locale = (path.getFileName().toString().split("\\.", 2))[0].toLowerCase(Locale.ROOT);
                    map.put(locale, TranslationTable.fromNBT(langNBT));
                } else {
                    FTBQuests.LOGGER.error("can't read lang file {}", path);
                }
            });
            if (!map.containsKey(file.getFallbackLocale())) {
                map.put(file.getFallbackLocale(), new TranslationTable());
            }
            FTBQuests.LOGGER.info("loaded translation tables for {} language(s)", map.size());
        } catch (IOException e) {
            FTBQuests.LOGGER.error("can't scan lang folder {}: {}", langFolder, e.getMessage());
        }
    }

