public int[] readIndex(File dir, String name)
	{
		NBTTagCompound nbt = SNBT.readOrTransform(dir, name);

		if (nbt == null)
		{
			return new int[0];
		}

		int[] ai = nbt.getIntArray("index");

		if (ai.length > 0)
		{
			if (this instanceof ServerQuestFile)
			{
				((ServerQuestFile) this).save();
			}

			return ai;
		}

		NBTTagList list = nbt.getTagList("index", Constants.NBT.TAG_STRING);

		ai = new int[list.tagCount()];

		for (int i = 0; i < ai.length; i++)
		{
			ai[i] = getID(list.getStringTagAt(i));
		}

		return ai;
	}

public final void readDataFull(File folder)
	{
		NBTTagCompound nbt = SNBT.readOrTransform(folder, "file");

		if (nbt != null)
		{
			fileVersion = nbt.getInteger("version");
			readData(nbt);
		}

		chapters.clear();
		rewardTables.clear();

		Int2ObjectOpenHashMap<NBTTagCompound> questFileCache = new Int2ObjectOpenHashMap<>();

		for (int i : readIndex(folder, "chapters/index"))
		{
			Chapter chapter = new Chapter(this);
			chapter.id = i;
			chapters.add(chapter);

			File[] files = new File(folder, "chapters/" + getCodeString(chapter)).listFiles();

			if (files != null && files.length > 0)
			{
				for (File f : files)
				{
					if (!f.getName().equals("chapter.snbt") && !f.getName().equals("chapter.nbt"))
					{
						try
						{
							Quest quest = new Quest(chapter);
							quest.id = Long.decode("#" + f.getName().replace(".nbt", "").replace(".snbt", "")).intValue();

							nbt = SNBT.readOrTransform(chapter.file.getFolder(), "chapters/" + getCodeString(chapter) + "/" + getCodeString(quest));

							if (nbt != null)
							{
								questFileCache.put(quest.id, nbt);
								NBTTagList t = nbt.getTagList("tasks", Constants.NBT.TAG_COMPOUND);

								for (int k = 0; k < t.tagCount(); k++)
								{
									NBTTagCompound tt = t.getCompoundTagAt(k);
									Task task = TaskType.createTask(quest, tt.getString("type"));

									if (task == null)
									{
										task = new CustomTask(quest);
										task.title = "Unknown type: " + tt.getString("type");
									}

									task.id = tt.getInteger("uid");

									if (task.id == 0)
									{
										task.id = getID(tt.getString("uid"));
									}

									quest.tasks.add(task);
								}

								NBTTagList r = nbt.getTagList("rewards", Constants.NBT.TAG_COMPOUND);

								for (int k = 0; k < r.tagCount(); k++)
								{
									NBTTagCompound rt = r.getCompoundTagAt(k);
									Reward reward = RewardType.createReward(quest, rt.getString("type"));

									if (reward == null)
									{
										reward = new CustomReward(quest);
										reward.title = "Unknown type: " + rt.getString("type");
									}

									reward.id = rt.getInteger("uid");

									if (reward.id == 0)
									{
										reward.id = getID(rt.getString("uid"));
									}

									quest.rewards.add(reward);
								}

								chapter.quests.add(quest);
							}
						}
						catch (Exception ex)
						{
							FTBQuests.LOGGER.warn("Failed to read quest ID " + f.getName());
						}
					}
				}
			}
		}

		for (int i : readIndex(folder, "reward_tables/index"))
		{
			RewardTable table = new RewardTable(this);
			table.id = i;
			rewardTables.add(table);
		}

		refreshIDMap();

		for (Chapter chapter : chapters)
		{
			nbt = SNBT.readOrTransform(folder, "chapters/" + getCodeString(chapter) + "/chapter");

			if (nbt != null)
			{
				chapter.readData(nbt);
			}

			for (Quest quest : chapter.quests)
			{
				nbt = questFileCache.get(quest.id);

				if (nbt == null)
				{
					continue;
				}

				quest.readData(nbt);

				NBTTagList t = nbt.getTagList("tasks", Constants.NBT.TAG_COMPOUND);

				for (int k = 0; k < t.tagCount(); k++)
				{
					quest.tasks.get(k).readData(t.getCompoundTagAt(k));
				}

				NBTTagList r = nbt.getTagList("rewards", Constants.NBT.TAG_COMPOUND);

				for (int k = 0; k < r.tagCount(); k++)
				{
					quest.rewards.get(k).readData(r.getCompoundTagAt(k));
				}
			}
		}

		for (RewardTable table : rewardTables)
		{
			nbt = SNBT.readOrTransform(folder, "reward_tables/" + getCodeString(table));

			if (nbt != null)
			{
				table.readData(nbt);
			}
		}

		for (Chapter chapter : chapters)
		{
			for (Quest quest : chapter.quests)
			{
				quest.verifyDependencies(true);
			}
		}

		for (QuestObjectBase object : getAllObjects())
		{
			if (object instanceof CustomTask)
			{
				new CustomTaskEvent((CustomTask) object).post();
			}
		}
	}

