                    // New_Village to Village first. It doesn't make sense to me to relocate it just to remove it, so it
                    // must be a typo.
                    if (newVillage == null) {
                        references.remove("Village");
                    } else {
                        references.remove("New_Village");
                        references.setMap("Village", newVillage);
                    }
                }

                return null;
            }

