        if (type == net.minecraft.util.datafix.fixes.References.PLAYER) {
            return ca.spottedleaf.dataconverter.minecraft.datatypes.MCTypeRegistry.PLAYER;
        }
        if (type == net.minecraft.util.datafix.fixes.References.CHUNK) {
