private void renderErrorOverlay(GuiGraphics guiGraphics) {
		menu.getErrorUpgradeSlotChangeResult().ifPresent(upgradeSlotChangeResult -> upgradeSlotChangeResult.getErrorMessage().ifPresent(overlayErrorMessage -> {
			guiGraphics.flush();
			RenderSystem.disableDepthTest();
			PoseStack poseStack = guiGraphics.pose();
			poseStack.pushPose();
			poseStack.translate(getGuiLeft(), getGuiTop(), 300.0F);
			upgradeSlotChangeResult.errorUpgradeSlots().forEach(slotIndex -> {
				Slot upgradeSlot = menu.getSlot(menu.getFirstUpgradeSlot() + slotIndex);
				renderSlotHighlight(guiGraphics, upgradeSlot.x, upgradeSlot.y, 0, ERROR_SLOT_COLOR);
			});
			Set<Integer> inventorySlotsHandledByControls = new HashSet<>();
			getAllInventoryControls().forEach(control -> {
				Set<Integer> controlErrorSlots = new HashSet<>();
				upgradeSlotChangeResult.errorInventorySlots().forEach(slotIndex -> {
					if (control.replacesSlotRender(slotIndex)) {
						controlErrorSlots.add(slotIndex);
					}
				});
				if (!controlErrorSlots.isEmpty()) {
					control.renderErrorOverlay(guiGraphics, controlErrorSlots);
					inventorySlotsHandledByControls.addAll(controlErrorSlots);
				}
			});
			upgradeSlotChangeResult.errorInventorySlots().stream().filter(slotIndex -> !inventorySlotsHandledByControls.contains(slotIndex))
					.forEach(slotIndex -> {
						Slot slot = menu.getSlot(slotIndex);
						// noinspection ConstantConditions
						if (slot != null) {
							renderSlotHighlight(guiGraphics, slot.x, slot.y, 0, ERROR_SLOT_COLOR);
						}
					});
			upgradeSlotChangeResult.errorInventoryParts().forEach(partIndex -> {
				UpgradeInventoryControlBase inventoryControl = inventoryControls.get(partIndex);
				if (inventoryControl != null) {
					inventoryControl.renderErrorOverlay(guiGraphics);
				}
			});
			poseStack.popPose();

			renderErrorMessage(guiGraphics, poseStack, overlayErrorMessage);
		}));
	}

private void updateFilter(String searchPhrase) {
		filteredResults.clear();
		String normalizedSearchPhrase = searchPhrase.trim().toLowerCase(Locale.ROOT);
		for (ResultEntry result : allResults) {
			if (normalizedSearchPhrase.isEmpty() || result.stack().getHoverName().getString().toLowerCase(Locale.ROOT).contains(normalizedSearchPhrase)) {
				filteredResults.add(result);
			}
		}
		scrollSelectedResultIntoView();
	}

public static List<ClientTooltipComponent> gatherTooltipComponents(List<? extends FormattedText> textElements, int mouseX, int screenWidth,
			int screenHeight, Font fallbackFont) {
		Font font = ClientHooks.getTooltipFont(ItemStack.EMPTY, fallbackFont);
		List<Either<FormattedText, TooltipComponent>> elements = textElements.stream()
				.map((Function<FormattedText, Either<FormattedText, TooltipComponent>>) Either::left).collect(Collectors.toCollection(ArrayList::new));

		var event = new RenderTooltipEvent.GatherComponents(ItemStack.EMPTY, screenWidth, screenHeight, elements, -1);
		NeoForge.EVENT_BUS.post(event);
		if (event.isCanceled()) {
			return List.of();
		}

		// text wrapping
		int tooltipTextWidth = event.getTooltipElements().stream().mapToInt(either -> either.map(font::width, component -> 0)).max().orElse(0);

		int tooltipX = mouseX + 12;
		if (tooltipX + tooltipTextWidth + 4 > screenWidth) {
			tooltipX = mouseX - 16 - tooltipTextWidth;
			if (tooltipX < 4) // if the tooltip doesn't fit on the screen
			{
				if (mouseX > screenWidth / 2) {
					tooltipTextWidth = mouseX - 12 - 8;
				} else {
					tooltipTextWidth = screenWidth - 16 - mouseX;
				}
			}
		}

		if (event.getMaxWidth() > 0 && tooltipTextWidth > event.getMaxWidth()) {
			tooltipTextWidth = event.getMaxWidth();
		}

		int tooltipTextWidthF = tooltipTextWidth;
		return event.getTooltipElements().stream()
				.flatMap(either -> either.map(text -> font.split(text, tooltipTextWidthF).stream().map(ClientTooltipComponent::create),
						component -> Stream.of(ClientTooltipComponent.create(component))))
				.toList();
	}

