@Override
	public void clicked(int slotId, int dragType, ClickType clickType, Player player) {
		inventorySlotsBeforeClickHandled = getInventorySlotsSize();
		if (isUpgradeSettingsSlot(slotId) && getSlot(slotId) instanceof IFilterSlot && getSlot(slotId).mayPlace(getCarried())) {
			Slot slot = getSlot(slotId);
			ItemStack cursorStack = getCarried().copy();
			if (cursorStack.getCount() > 1) {
				cursorStack.setCount(1);
			}

			slot.set(cursorStack);
			((IFilterSlot) slot).onItemSet(dragType);
			return;
		} else if (isUpgradeSlot(slotId) && getSlot(slotId) instanceof StorageContainerMenuBase<?>.StorageUpgradeSlot slot) {
			ItemStack slotStack = slot.getItem();
			if (clickType == ClickType.PICKUP && dragType == 1 && getCarried().getItem() instanceof StackUpgradeConversionItem conversionItem) {
				ItemStack targetUpgradeStack = conversionItem.getTargetUpgradeStack();
				if (conversionItem.canConvert(slotStack) && slot.mayPlace(targetUpgradeStack)) {
					slot.set(targetUpgradeStack);
					if (!player.getAbilities().instabuild) {
						getCarried().shrink(1);
						if (getCarried().isEmpty()) {
							setCarried(ItemStack.EMPTY);
						}
					}
					slot.setChanged();
					if (!player.level().isClientSide()) {
						player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.SMITHING_TABLE_USE, SoundSource.PLAYERS, 0.8F,
								1.0F);
					}
				}
				return;
			}
			if (slot.mayPlace(getCarried())) {
				ItemStack carriedStack = getCarried();
				IUpgradeItem<?> upgradeItem = (IUpgradeItem<?>) carriedStack.getItem();
				int newColumnsTaken = upgradeItem.getInventoryColumnsTaken();
				int currentColumnsTaken = 0;
				if (!slotStack.isEmpty()) {
					currentColumnsTaken = ((IUpgradeItem<?>) slotStack.getItem()).getInventoryColumnsTaken();
				}
				if (needsSlotsThatAreOccupied(carriedStack, currentColumnsTaken, newColumnsTaken)) {
					return;
				}

				int columnsToRemove = newColumnsTaken - currentColumnsTaken;
				if (slotStack.isEmpty()) {
					slot.set(carriedStack.split(1));
					if (carriedStack.isEmpty()) {
						setCarried(ItemStack.EMPTY);
					}
				} else if (carriedStack.getCount() == 1) {
					slot.set(carriedStack);
					setCarried(upgradeItem.getCleanedUpgradeStack(slotStack.copy()));
				}

				updateColumnsTaken(columnsToRemove);
				slot.setChanged();
				if (columnsToRemove != 0 && player.level().isClientSide()) {
					onUpgradesChanged(); // need to trigger onUpgradesChanged again so that screen can react to this with updating slot positions after slots
											// were refreshed as part of columns update
				}
			} else if (getCarried().isEmpty() && !slotStack.isEmpty() && slot.mayPickup(player)) {
				int k2 = dragType == 0
						? Math.min(slotStack.getCount(), slotStack.getMaxStackSize())
						: Math.min(slotStack.getMaxStackSize() + 1, slotStack.getCount() + 1) / 2;
				IUpgradeItem<?> upgradeItem = (IUpgradeItem<?>) slotStack.getItem();
				int columnsTaken = upgradeItem.getInventoryColumnsTaken();
				if (clickType == ClickType.QUICK_MOVE) {
					quickMoveStack(player, slotId);
				} else {
					setCarried(upgradeItem.getCleanedUpgradeStack(slot.remove(k2)));
				}
				slot.wasEmpty = false; // slot was not empty when this was reached and need to force onTake below to trigger slot position recalculation if
										// slots are refreshed when columns taken changes
				updateColumnsTaken(-columnsTaken);
				slot.onTake(player, getCarried());
			}
			return;
		} else if (isOverflowLogicSlotAndAction(slotId, clickType) && handleOverflow(slotId, clickType, dragType, player)) {
			return;
		}

		super.clicked(slotId, dragType, clickType, player);
	}

@Override
	public boolean isValidSlotIndex(int slotIndex) {
		return slotIndex == -1 || slotIndex == -999 || slotIndex < getTotalSlotsNumber();
	}

private boolean handleOverflow(int slotId, ClickType clickType, int dragType, Player player) {
		ItemStack cursorStack = clickType == ClickType.SWAP ? player.getInventory().getItem(dragType) : getCarried();
		Consumer<ItemStack> updateCursorStack = clickType == ClickType.SWAP ? s -> player.getInventory().setItem(dragType, s) : this::setCarried;
		Slot slot = getSlot(slotId);
		if ((clickType != ClickType.SWAP && cursorStack.isEmpty()) || !slot.mayPlace(cursorStack)) {
			return false;
		}
		ItemStack slotStack = slot.getItem();
		if (slotStack.isEmpty() || (slot.mayPickup(player) && slotStack.getItem() != cursorStack.getItem()
				&& cursorStack.getCount() <= slot.getMaxStackSize(cursorStack) && slotStack.getCount() <= slotStack.getMaxStackSize())) {
			return processOverflowIfSlotWithSameItemFound(cursorStack, updateCursorStack);
		} else if (slotStack.getItem() == cursorStack.getItem()) {
			return processOverflowForAnythingOverSlotMaxSize(cursorStack, updateCursorStack, slot, slotStack);
		}
		return false;
	}

private boolean processOverflowForAnythingOverSlotMaxSize(ItemStack cursorStack, Consumer<ItemStack> updateCursorStack, Slot slot, ItemStack slotStack) {
		int remainingSpaceInSlot = slot.getMaxStackSize(cursorStack) - slotStack.getCount();
		if (remainingSpaceInSlot < cursorStack.getCount()) {
			ItemStack overflow = cursorStack.copy();
			int overflowCount = cursorStack.getCount() - remainingSpaceInSlot;
			overflow.setCount(overflowCount);
			ItemStack result = processOverflowLogic(overflow);
			if (result.getCount() < overflowCount) {
				cursorStack.shrink(overflowCount - result.getCount());
				if (cursorStack.isEmpty()) {
					updateCursorStack.accept(ItemStack.EMPTY);
					return true;
				} else {
					updateCursorStack.accept(cursorStack);
				}
			}
		}
		return false;
	}

private boolean processOverflowIfSlotWithSameItemFound(ItemStack cursorStack, Consumer<ItemStack> updateCursorStack) {
		for (IOverflowResponseUpgrade overflowUpgrade : storageWrapper.getUpgradeHandler()
				.getWrappersThatImplementFromMainStorage(IOverflowResponseUpgrade.class)) {
			if (overflowUpgrade.stackMatchesFilter(cursorStack) && overflowUpgrade.worksInGui()
					&& findSlotWithMatchingStack(cursorStack, updateCursorStack, overflowUpgrade)) {
				return true;
			}
		}
		return false;
	}

private boolean findSlotWithMatchingStack(ItemStack cursorStack, Consumer<ItemStack> updateCursorStack, IOverflowResponseUpgrade overflowUpgrade) {
		if (overflowUpgrade.hasSlotOverflowMatch(storageWrapper.getInventoryHandler(), cursorStack)) {
			ItemStack result = cursorStack;
			result = overflowUpgrade.onSlotOverflow(result);
			updateCursorStack.accept(result);
			if (result.isEmpty()) {
				return true;
			}
		}
		return false;
	}

private boolean isOverflowLogicSlotAndAction(int slotId, ClickType clickType) {
		return isStorageInventorySlot(slotId) && (clickType == ClickType.SWAP || clickType == ClickType.PICKUP);
	}

protected void updateColumnsTaken(int columnsChange) {
		if (player.level().isClientSide()) {
			this.columnsChange = columnsChange;
		} else {
			actuallyUpdateColumnsTaken(columnsChange);
		}
	}

private void actuallyUpdateColumnsTaken(int columnsChange) {
		if (columnsChange != 0) {
			// when these get changed recalculate columns taken to fix columnsTaken out of sync issues
			AtomicInteger columnsTaken = new AtomicInteger(0);
			InventoryHelper.iterate(storageWrapper.getUpgradeHandler(), (slot, upgradeStack) -> {
				if (upgradeStack.getItem() instanceof UpgradeItemBase<?> upgradeItem) {
					columnsTaken.addAndGet(upgradeItem.getInventoryColumnsTaken());
				}
			});
			int targetColumnsTaken = columnsTaken.get();
			InventoryLayoutFitResult fitResult = getInventoryLayoutFitResult(targetColumnsTaken);
			if (fitResult.fits() && targetColumnsTaken > storageWrapper.getColumnsTaken()) {
				storageWrapper.applyInventoryLayout(fitResult, getColumnsForColumnsTaken(targetColumnsTaken));
			}
			storageWrapper.setColumnsTaken(targetColumnsTaken, true);
			storageWrapper.onContentsNbtUpdated();
			if (fitResult.fits()) {
				storageWrapper.applyInventoryLayout(fitResult, getColumnsForColumnsTaken(targetColumnsTaken));
			}
			storageWrapper.onContentsNbtUpdated();
			refreshAllSlots();
			onUpgradeChanged();
			sendAllDataToRemote();
			sendStorageSettingsToClient();
		}
	}

protected boolean needsSlotsThatAreOccupied(ItemStack cursorStack, int currentColumnsTaken, int newColumnsTaken) {
		if (currentColumnsTaken >= newColumnsTaken) {
			return false;
		}

		int slotsToCheck = (newColumnsTaken - currentColumnsTaken) * getNumberOfRows();
		InventoryLayoutFitResult fitResult = getInventoryLayoutFitResult(getCurrentColumnsTakenAfterChange(currentColumnsTaken, newColumnsTaken));
		Set<Integer> errorSlots = fitResult.errorSlots();

		if (!errorSlots.isEmpty()) {
			updateSlotChangeError(UpgradeSlotChangeResult.fail(
					TranslationHelper.INSTANCE.translError("add.needs_occupied_inventory_slots", slotsToCheck, cursorStack.getHoverName()),
					Collections.emptySet(), errorSlots, Collections.emptySet()));
			return true;
		}
		return false;
	}

private int getCurrentColumnsTakenAfterChange(int currentColumnsTaken, int newColumnsTaken) {
		return storageWrapper.getColumnsTaken() - currentColumnsTaken + newColumnsTaken;
	}

private InventoryLayoutFitResult getInventoryLayoutFitResult(int targetColumnsTaken) {
		int currentColumns = getCurrentColumns();
		int targetColumns = getColumnsForColumnsTaken(targetColumnsTaken);
		return InventoryLayoutFitter.fit(storageWrapper.getInventoryLayoutParts(currentColumns, targetColumns), getTargetSlots(targetColumnsTaken),
				targetColumns, targetColumnsTaken < storageWrapper.getColumnsTaken());
	}

private int getTargetSlots(int targetColumnsTaken) {
		return getBaseStorageSlots() - targetColumnsTaken * getNumberOfRows();
	}

private int getCurrentColumns() {
		return getColumnsForColumnsTaken(storageWrapper.getColumnsTaken());
	}

private int getColumnsForColumnsTaken(int columnsTaken) {
		return getBaseColumns() - columnsTaken;
	}

private int getBaseColumns() {
		return getBaseStorageSlots() <= 81 ? 9 : 12;
	}

