			ItemStack previous = remoteSlots.get(slotIndex);
			remoteSlots.set(slotIndex, stack);

			if (isStorageInventorySlot(slotIndex) && (previous.isEmpty() || stack.isEmpty())) {
				inventorySlotStackChanged = true;
