				k1 = dragType == 0 ? 0 : upgradeSlots.size() - 1;

				for (int j = 0; j < 2; ++j) {
					for (int upgradeSlotId = k1; upgradeSlotId >= 0 && upgradeSlotId < upgradeSlots.size()
							&& carriedStack.getCount() < carriedStack.getMaxStackSize(); upgradeSlotId += j2) {
