public static void issueCraftClaim(Player player, ItemStack result) {
		EnderLinkPendingCraftData pendingCraft = result.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		if (pendingCraft == null) {
			return;
		}
		EnderLinkPendingCraftPlan plan = pendingCraft.plan();

		UUID playerId = player.getUUID();
		InFlightClaim inFlightClaim = pendingCraft.claimId() == null ? null : IN_FLIGHT_CLAIMS.get(pendingCraft.claimId());
		if (inFlightClaim != null && inFlightClaim.playerId().equals(playerId) && inFlightClaim.plan() == plan) {
			return;
		}
		UUID latestClaimId = LATEST_IN_FLIGHT_CLAIMS.getOrDefault(playerId, Map.of()).get(plan);
		InFlightClaim latestClaim = latestClaimId == null ? null : IN_FLIGHT_CLAIMS.get(latestClaimId);
		if (latestClaim != null && latestClaim.playerId().equals(playerId) && latestClaim.plan() == plan) {
			result.set(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT, new EnderLinkPendingCraftData(pendingCraft.plan(), latestClaimId));
			return;
		}
		UUID claimId = UUID.randomUUID();
		result.set(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT, new EnderLinkPendingCraftData(pendingCraft.plan(), claimId));
		IN_FLIGHT_CLAIMS.put(claimId, new InFlightClaim(claimId, playerId, plan));
		LATEST_IN_FLIGHT_CLAIMS.computeIfAbsent(playerId, ignored -> new HashMap<>()).put(plan, claimId);
	}

public static boolean completeCraft(ServerLevel level, Player player, Container inventory, ItemStack result) {
		Optional<Inputs> liveInputs = getInputs(inventory.getContainerSize(), inventory::getItem);
		EnderLinkPendingCraftData pendingCraft = result.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		EnderLinkPendingCraftPlan plan = pendingCraft == null ? liveInputs.map(Inputs::plan).orElse(null) : pendingCraft.plan();
		if (plan == null) {
			return false;
		}
		InFlightClaim claim = findInFlightClaim(player, pendingCraft, plan);
		if (claim == null) {
			return false;
		}
		if (liveInputs.isEmpty() || liveInputs.get().plan() != plan) {
			return false;
		}
		Inputs inputs = liveInputs.get();
		LinkedStorageEndpointData endpointData;
		if (plan == EnderLinkPendingCraftPlan.CREATE_PRIMARY) {
			if (!LinkedStorageService.link(level, player.getUUID(), inputs.linker().copyWithCount(1), inputs.endpoint())) {
				return false;
			}
			endpointData = inputs.endpoint().get(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT);
		} else if (plan == EnderLinkPendingCraftPlan.BIND_EXISTING_ENDPOINT) {
			endpointData = inputs.endpoint().get(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT);
		} else {
			if (LinkedStorageStackLifecycle.classifyLinker(inputs.linker()) == EnderLinkerStackState.PENDING_CRAFT
					&& !finalizePendingCraftLinker(level, inputs.linker())) {
				return false;
			}
			ItemStack endpoint = inputs.endpoint().copyWithCount(1);
			if (!LinkedStorageService.link(level, inputs.linker().copyWithCount(1), endpoint)) {
				return false;
			}
			endpointData = endpoint.get(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT);
		}
		LinkedStorageGroupsSavedData.get(level).manager()
				.activatePendingCraftClaim(new ActivePendingCraftClaim(claim.claimId(), endpointData.groupId(), endpointData.endpointId(), inputs.plan()));
		IN_FLIGHT_CLAIMS.remove(claim.claimId());
		Map<EnderLinkPendingCraftPlan, UUID> latestClaims = LATEST_IN_FLIGHT_CLAIMS.get(player.getUUID());
		if (latestClaims != null) {
			latestClaims.remove(plan, claim.claimId());
			if (latestClaims.isEmpty()) {
				LATEST_IN_FLIGHT_CLAIMS.remove(player.getUUID());
			}
		}
		return true;
	}

private static EnderLinkerTargetData createTarget(LinkedStorageGroupManager manager, UUID groupId) {
		Component groupName = manager.resolveVirtualHost(groupId).orElseThrow().getLinkedStorageDisplayName().orElse(Component.empty());
		return new EnderLinkerTargetData(groupId, groupName);
	}

@Nullable
	private static InFlightClaim findInFlightClaim(Player player, @Nullable EnderLinkPendingCraftData pendingCraft, EnderLinkPendingCraftPlan plan) {
		UUID playerId = player.getUUID();
		UUID claimId = pendingCraft == null ? null : pendingCraft.claimId();
		if (claimId == null) {
			claimId = LATEST_IN_FLIGHT_CLAIMS.getOrDefault(playerId, Map.of()).get(plan);
		}
		InFlightClaim claim = claimId == null ? null : IN_FLIGHT_CLAIMS.get(claimId);
		if (claim == null || !claim.playerId().equals(playerId) || claim.plan() != plan) {
			return null;
		}
		if (pendingCraft != null && pendingCraft.claimId() != null && !pendingCraft.claimId().equals(claim.claimId())) {
			return null;
		}
		return claim;
	}

@Override
	public ItemStack insertItem(int slot, ItemStack stack, boolean simulate) {
		if (simulate) {
			return wrappedHandlerGetter.get().insertItem(slot, stack, true);
		}

		if (currentCacheTime != timeSupplier.getAsLong()) {
			failedInsertStacks.clear();
			currentCacheTime = timeSupplier.getAsLong();
		}

		if (failedInsertStacks.contains(stack)) {
			return stack;
		}

		ItemStack result = wrappedHandlerGetter.get().insertItem(slot, stack, false);

		if (result == stack) {
			failedInsertStacks.add(stack); // only working with stack references because this logic is meant to handle the case where something tries to insert
											// the same stack number of slots times
		}

		return result;
	}

private Tag getSlotsStackNbt(int slot, ItemStack slotStack) {
		CompoundTag itemTag = new CompoundTag();
		itemTag.putInt("Slot", slot);
		return RegistryHelper.getRegistryAccess().map(registryAccess -> CodecHelper.OVERSIZED_ITEM_STACK_CODEC
				.encode(slotStack, registryAccess.createSerializationContext(NbtOps.INSTANCE), itemTag).getOrThrow()).orElse(itemTag);
	}

private Optional<ItemStack> getStackFromNbt(int slot, Tag itemTag, RegistryAccess registryAccess) {
		try {
			return CodecHelper.OVERSIZED_ITEM_STACK_CODEC.parse(registryAccess.createSerializationContext(NbtOps.INSTANCE), itemTag).resultOrPartial(
					errorMessage -> SophisticatedCore.LOGGER.error("Failed to deserialize stored item in storage '{}' slot {} - {}. Raw item data: {}",
							getStorageLogName(), slot, errorMessage, itemTag));
		} catch (Exception e) {
			SophisticatedCore.LOGGER.error("Error deserializing stored item in storage '{}' slot {}. Raw item data: {}", getStorageLogName(), slot, itemTag, e);
			return Optional.empty();
		}
	}

private String getStorageLogName() {
		String displayName = Optional.ofNullable(storageWrapper.getDisplayName()).map(Component::getString).orElse("");
		if (!displayName.isEmpty()) {
			return storageWrapper.getStorageType() + " (" + displayName + ")";
		}
		return storageWrapper.getStorageType();
	}

@Override
	public void deserializeNBT(HolderLookup.Provider registries, CompoundTag nbt) {
		slotTracker.clear();
		setSize(nbt.contains("Size", Tag.TAG_INT) ? nbt.getInt("Size") : stacks.size());
		ListTag tagList = nbt.getList("Items", Tag.TAG_COMPOUND);
		RegistryHelper.getRegistryAccess().ifPresent(registryAccess -> {
			for (int i = 0; i < tagList.size(); i++) {
				CompoundTag itemTag = tagList.getCompound(i);
				int slot = itemTag.getInt("Slot");
				if (slot >= 0 && slot < stacks.size()) {
					getStackFromNbt(slot, itemTag, registryAccess).ifPresent(stack -> stacks.set(slot, stack));
				}
			}
		});
		slotTracker.refreshSlotIndexesFrom(this);
		onLoad();
	}

@Override
	public void removeAndSetSlotIndexes(InventoryHandler inventoryHandler, int slot, ItemStack stack) {
		if (stack.isEmpty()) {
			removePartiallyFilled(slot);
			removeFull(slot);
			if (inventoryHandler.isSlotAccessible(slot)) {
				addEmptySlot(slot);
			}
			return;
		}

		if (emptySlots.contains(slot)) {
			removeEmpty(slot);
		}

		if (isPartiallyFilled(inventoryHandler, slot, stack)) {
			setPartiallyFilled(slot, stack);
		} else {
			setFull(slot, stack);
		}
	}

@Override
	public ItemStack insertItemIntoHandler(InventoryHandler itemHandler, BiFunction<ItemStack, Boolean, ItemStack> beforeInsertHandler,
			IItemHandlerInserter inserter, UnaryOperator<ItemStack> slotOverflowHandler, UnaryOperator<ItemStack> storageOverflowHandler, int slot,
			ItemStack stack, boolean simulate) {
		if (simulate) {
			ItemStack remainingStack = beforeInsertHandler.apply(stack, simulate);
			if (remainingStack.isEmpty()) {
				return remainingStack;
			}

			if (fullSlotStacks.containsKey(slot)) {
				return handleOverflow(slotOverflowHandler, storageOverflowHandler, ItemStackKey.of(stack), remainingStack);
			} else if (emptySlots.contains(slot)) {
				if (memorySettings.isSlotSelected(slot) && memorySettings.matchesFilter(slot, stack)) {
					return inserter.insertItem(slot, remainingStack, true);
				} else if (filterItemSlots.getSlots(stack.getItem()).contains(slot)) {
					return inserter.insertItem(slot, remainingStack, true);
				} else if (shouldInsertIntoEmpty.getAsBoolean()) {
					if ((memorySettings.isSlotSelected(slot) && !memorySettings.matchesFilter(slot, stack))
							|| filterItemSlots.containsSlotAndDoesNotMatch(slot, stack.getItem())) {
						ItemStackKey stackKey = ItemStackKey.of(stack);
						return handleOverflow(slotOverflowHandler, storageOverflowHandler, stackKey, remainingStack, hasOneFullStackOfItem(stackKey));
					}
					return inserter.insertItem(slot, remainingStack, true);
				}
			} else if (partiallyFilledSlotStacks.containsKey(slot)) {
				if (partiallyFilledSlotStacks.get(slot).hashCode() == ItemStackKey.of(stack).hashCode()) {
					remainingStack = inserter.insertItem(slot, remainingStack, true);
				}
				if (remainingStack.isEmpty()) {
					return remainingStack;
				}
				boolean insertedSomething = remainingStack.getCount() != stack.getCount();
				ItemStackKey stackKey = ItemStackKey.of(remainingStack);
				return handleOverflow(slotOverflowHandler, storageOverflowHandler, stackKey, remainingStack,
						insertedSomething || hasOneFullStackOfItem(stackKey));
			}
			return remainingStack;
		}

		return insertItemIntoHandler(itemHandler, beforeInsertHandler, inserter, slotOverflowHandler, storageOverflowHandler, stack, simulate);
	}

private ItemStack insertIntoEmptyFilterSlots(IItemHandlerInserter inserter, boolean simulate, ItemStack remainingStack) {
		Item item = remainingStack.getItem();
		if (filterItemSlots.containsValue(item)) {
			for (int filterSlot : filterItemSlots.getSlots(item)) {
				if (emptySlots.contains(filterSlot)) {
					remainingStack = inserter.insertItem(filterSlot, remainingStack, simulate);
					if (remainingStack.isEmpty()) {
						break;
					}
				}
			}
		}
		return remainingStack;
	}

private ItemStack insertIntoEmptyMemorySlots(IItemHandlerInserter inserter, boolean simulate, ItemStack stack) {
		ItemStack remainingStack = stack;
		Map<Item, Set<Integer>> memoryFilterItemSlots = memorySettings.getFilterItemSlots();
		Item item = remainingStack.getItem();
		if (memoryFilterItemSlots.containsKey(item)) {
			for (int memorySlot : memoryFilterItemSlots.get(item)) {
				if (emptySlots.contains(memorySlot)) {
					remainingStack = inserter.insertItem(memorySlot, remainingStack, simulate);
					if (remainingStack.isEmpty()) {
						break;
					}
				}
			}
		}

		Map<Integer, Set<Integer>> memoryFilterStackSlots = memorySettings.getFilterStackSlots();
		if (!memoryFilterStackSlots.isEmpty()) {
			int stackHash = ItemStack.hashItemAndComponents(remainingStack);
			if (memoryFilterStackSlots.containsKey(stackHash)) {
				for (int memorySlot : memoryFilterStackSlots.get(stackHash)) {
					if (emptySlots.contains(memorySlot)) {
						remainingStack = inserter.insertItem(memorySlot, remainingStack, simulate);
						if (remainingStack.isEmpty()) {
							break;
						}
					}
				}
			}
		}
		return remainingStack;
	}

private void deserializeNBT(CompoundTag tag, Supplier<MemorySettingsCategory> getMemorySettings) {
		if (!tag.contains(BASE_INDEXES_TAG)) {
			this.inventoryPartHandlers = new IInventoryPartHandler[]{new IInventoryPartHandler.Default(parent, parent.getSlots())};
			this.baseIndexes = new int[]{0};
			return;
		}

		baseIndexes = tag.getIntArray(BASE_INDEXES_TAG);
		inventoryPartHandlers = new IInventoryPartHandler[baseIndexes.length];
		ListTag partNamesTag = tag.getList("inventoryPartNames", Tag.TAG_STRING);
		int i = 0;
		for (Tag t : partNamesTag) {
			SlotRange slotRange = new SlotRange(baseIndexes[i], (i + 1 < baseIndexes.length ? baseIndexes[i + 1] : parent.getSlots()) - baseIndexes[i]);
			inventoryPartHandlers[i] = InventoryPartRegistry.instantiatePart(t.getAsString(), parent, slotRange, getMemorySettings);
			i++;
		}
	}

