		batteryRenderInfo = null;
		getRenderInfoTag().ifPresent(renderInfoTag -> {
			renderInfoTag.remove(TANKS_TAG);
			renderInfoTag.remove(BATTERY_TAG);
			serializeRenderInfo(renderInfoTag);
		});
