@Override
	public Optional<Integer> getSlotOverlayColor(int slotNumber, boolean templateLoadHovered) {
		if (!getSettingsContainer().canDeselectSlots()) {
			return Optional.empty();
		}

		if (templateLoadHovered) {
			return getSettingsContainer().getSettingsContainer().getSelectedTemplatesCategory(ItemDisplaySettingsCategory.class)
					.filter(c -> c.getSlots().contains(slotNumber)).map(category -> category.getColor().getTextureDiffuseColor() & 0x00_FFFFFF | (80 << 24));
		}

		return getSettingsContainer().isSlotSelected(slotNumber)
				? Optional.of(getSettingsContainer().getColor().getTextureDiffuseColor() | (80 << 24))
				: Optional.empty();
	}

@Override
	public int getItemRotation(int slotIndex, boolean templateLoadHovered) {
		if (templateLoadHovered) {
			return getSettingsContainer().getSettingsContainer().getSelectedTemplatesCategory(ItemDisplaySettingsCategory.class)
					.filter(c -> c.getSlots().contains(slotIndex)).map(category -> category.getRotation(slotIndex)).orElse(0);
		}

		return getSettingsContainer().getRotation(slotIndex);
	}

private void deserialize() {
		NBTHelper.getMap(categoryNbt, SLOT_FILTER_ITEMS_TAG, Integer::valueOf,
				(k, v) -> BuiltInRegistries.ITEM.getOptional(ResourceLocation.parse(v.getAsString()))).ifPresent(map -> map.forEach(this::addSlotItem));

		NBTHelper.getMap(categoryNbt, SLOT_FILTER_STACKS_TAG, Integer::valueOf,
				(k, v) -> v instanceof CompoundTag tag
						? RegistryHelper.getRegistryAccess().flatMap(registryAccess -> ItemStack.parse(registryAccess, tag))
						: Optional.empty())
				.ifPresent(map -> map.forEach(this::addSlotStack));
		ignoreNbt = NBTHelper.getBoolean(categoryNbt, IGNORE_NBT_TAG).orElse(true);
	}

private void serializeFilterItems() {
		NBTHelper.putMap(categoryNbt, SLOT_FILTER_ITEMS_TAG, slotFilterItems, String::valueOf,
				i -> StringTag.valueOf(BuiltInRegistries.ITEM.getKey(i).toString()));
		NBTHelper.putMap(categoryNbt, SLOT_FILTER_STACKS_TAG, slotFilterStacks, String::valueOf,
				isk -> RegistryHelper.getRegistryAccess().map(registryAccess -> isk.stack().saveOptional(registryAccess)).orElse(new CompoundTag()));
		saveNbt.accept(categoryNbt);
	}

@Override
	public void handlePacket(CompoundTag data) {
		if (data.contains(ACTION_TAG)) {
			switch (data.getString(ACTION_TAG)) {
				case SELECT_ALL_ACTION -> selectAllSlots();
				case UNSELECT_ALL_ACTION -> unselectAllSlots();
				default -> {
					// noop
				}
			}
		} else if (data.contains(SELECT_SLOT_TAG)) {
			selectSlot(data.getInt(SELECT_SLOT_TAG));
		} else if (data.contains(UNSELECT_SLOT_TAG)) {
			unselectSlot(data.getInt(UNSELECT_SLOT_TAG));
		} else if (data.contains(IGNORE_NBT_TAG)) {
			setIgnoreNbt(data.getBoolean(IGNORE_NBT_TAG));
		}
