static Map<ItemStackKey, Integer> getCompactedStacks(IItemHandler handler, Set<Integer> ignoreSlots, boolean getVirtualCounts) {
		Map<ItemStackKey, Integer> ret = new HashMap<>();
		iterate(handler, (slot, stack) -> {
			if (stack.isEmpty() || ignoreSlots.contains(slot)) {
				return;
			}
			ItemStackKey itemStackKey = ItemStackKey.of(stack);
			ret.put(itemStackKey, ret.computeIfAbsent(itemStackKey, fs -> 0) + stack.getCount());
		}, () -> false, getVirtualCounts);
		return ret;
	}

private static void sortIntoOtherSlots(IItemHandlerModifiable handler, Set<Integer> noSortSlots, List<Map.Entry<ItemStackKey, Integer>> sortedList,
			int slots) {
		Iterator<Map.Entry<ItemStackKey, Integer>> ite = sortedList.iterator();
		ItemStackKey current = null;
		int count = 0;

		for (int slot = 0; slot < slots; slot++) {
			if (noSortSlots.contains(slot)) {
				continue;
			}
			if ((current == null || count <= 0) && ite.hasNext()) {
				Map.Entry<ItemStackKey, Integer> entry = ite.next();
				current = entry.getKey();
				count = entry.getValue();
			}
			if (current != null && count > 0) {
				count -= placeStack(handler, current, count, slot, false);
			} else {
				emptySlot(handler, slot);
			}
		}
	}

public static void normalizeInventory(CompoundTag inventoryNbt) {
		ListTag items = inventoryNbt.getList("Items", Tag.TAG_COMPOUND);
		for (int i = 0; i < items.size(); i++) {
			items.set(i, normalizeItemStack(items.getCompound(i)));
		}
	}

public static CompoundTag normalizeItemStack(CompoundTag itemTag) {
		CompoundTag normalized = itemTag;
		if (itemTag.contains("Count", Tag.TAG_ANY_NUMERIC) && !itemTag.contains("components") && itemTag.contains("id", Tag.TAG_STRING)) {
			normalized = (CompoundTag) DataFixers.getDataFixer().update(References.ITEM_STACK, new Dynamic<>(NbtOps.INSTANCE, itemTag), LEGACY_DATA_VERSION,
					SharedConstants.getCurrentVersion().getDataVersion().getVersion()).getValue();
		}
		if (itemTag.contains("realCount", Tag.TAG_ANY_NUMERIC) && (normalized != itemTag || !normalized.contains("count", Tag.TAG_ANY_NUMERIC))) {
			normalized.putInt("count", itemTag.getInt("realCount"));
		} else if (!normalized.contains("count", Tag.TAG_ANY_NUMERIC) && itemTag.contains("Count", Tag.TAG_ANY_NUMERIC)) {
			normalized.putInt("count", itemTag.getInt("Count"));
		}
		return normalized;
	}

private static Set<CompactingShape> getCompactingShapes(ItemStack stack) {
		return getLevel().map(w -> {
			Set<CompactingShape> compactingShapes = new HashSet<>();
			getCompactingShape(stack, w, 2, 2, TWO_BY_TWO_UNCRAFTABLE, TWO_BY_TWO).ifPresent(compactingShapes::add);
			getCompactingShape(stack, w, 3, 3, THREE_BY_THREE_UNCRAFTABLE, THREE_BY_THREE).ifPresent(compactingShapes::add);
			if (compactingShapes.isEmpty()) {
				compactingShapes.add(NONE);
			}
			return compactingShapes;
		}).orElse(Collections.emptySet());
	}

private static boolean isPartOfCompactingLoop(ItemStack firstCompacted, ItemStack firstCompactResult, Level w) {
		ItemStack compactingResultStack;
		int iterations = 0;
		Set<Integer> compactedItemHashes = new HashSet<>();
		Queue<ItemStack> itemsToCompact = new LinkedList<>();
		itemsToCompact.add(firstCompactResult);
		while (!itemsToCompact.isEmpty()) {
			ItemStack itemToCompact = itemsToCompact.poll();
			compactingResultStack = getCompactingResult(itemToCompact, w, 2, 2).getResult();
			if (!compactingResultStack.isEmpty()) {
				if (ItemStack.isSameItemSameComponents(compactingResultStack, firstCompacted)) {
					return true;
				} else if (compactedItemHashes.contains(ItemStack.hashItemAndComponents(compactingResultStack))) {
					return false; // loop exists but the first compacted item isn't part of it so we will let it be compacted, but no follow up compacting will
									// happen
				}
				itemsToCompact.add(compactingResultStack);
			}

			compactingResultStack = getCompactingResult(itemToCompact, w, 3, 3).getResult();
			if (!compactingResultStack.isEmpty()) {
				if (ItemStack.isSameItemSameComponents(compactingResultStack, firstCompacted)) {
					return true;
				} else if (compactedItemHashes.contains(ItemStack.hashItemAndComponents(compactingResultStack))) {
					return false; // loop exists but the first compacted item isn't part of it so we will let it be compacted, but no follow up compacting will
									// happen
				}
				itemsToCompact.add(compactingResultStack);
			}
			compactedItemHashes.add(ItemStack.hashItemAndComponents(itemToCompact));
			iterations++;
			if (iterations > MAX_FOLLOW_UP_COMPACTING_RECIPES) {
				return true; // we were unable to figure out if the loop exists because of way too many follow up compacting recipe thus not allowing to compact
								// anyway
			}
		}
		return false;
	}

public static UncompactingResult getUncompactingResult(ItemStack uncompactedItem) {
		return getFromCache(cache -> cache.getUncompactingResults().computeIfAbsent(ItemStack.hashItemAndComponents(uncompactedItem), k -> getLevel().map(w -> {
			for (ItemStack uncompactResultItem : getUncompactResultItems(w, uncompactedItem)) {
				if (uncompactResultItem.getCount() == 9) {
					if (ItemStack.isSameItemSameComponents(getCompactingResult(uncompactResultItem, 3, 3).getResult(), uncompactedItem)) {
						return new UncompactingResult(uncompactResultItem, THREE_BY_THREE_UNCRAFTABLE);
					}
				} else if (uncompactResultItem.getCount() == 4
						&& ItemStack.isSameItemSameComponents(getCompactingResult(uncompactResultItem, 2, 2).getResult(), uncompactedItem)) {
					return new UncompactingResult(uncompactResultItem, TWO_BY_TWO_UNCRAFTABLE);
				}
			}
			return UncompactingResult.EMPTY;
		}).orElse(UncompactingResult.EMPTY)), UncompactingResult.EMPTY);
	}

public static List<ItemStack> getUncompactResultItems(ItemStack itemToUncompact) {
		return getLevel().map(w -> getUncompactResultItems(w, itemToUncompact)).orElse(Collections.emptyList());
	}

