private static int createTemplate(CommandSourceStack source, ResourceLocation templateName, boolean override) {
		if (!source.isPlayer()) {
			return 1;
		}

		ServerPlayer player = source.getPlayer();
		ItemStack backpack = player.getMainHandItem();
		if (!(backpack.getItem() instanceof BackpackItem)) {
			source.sendFailure(Component.translatable("commands.sophisticatedbackpacks.template.create.nobackpack"));
			return 2;
		}

		IBackpackWrapper backpackWrapper = BackpackWrapper.fromStack(backpack);
		if (!backpackWrapper.supportsBackpackContents()) {
			source.sendFailure(Component.translatable("commands.sophisticatedbackpacks.template.unsupported_host"));
			return 5;
		}
		Optional<UUID> backpackUuid = backpackWrapper.getContentsUuid();
		if (backpackUuid.isEmpty()
				|| (InventoryHelper.isEmpty(backpackWrapper.getInventoryHandler()) && InventoryHelper.isEmpty(backpackWrapper.getUpgradeHandler()))) {
			source.sendFailure(Component.translatable("commands.sophisticatedbackpacks.template.backpackempty"));
			return 3;
		}

		if (BackpackTemplates.getTemplateNames().contains(templateName) && !override) {
			source.sendFailure(Component.translatable("commands.sophisticatedbackpacks.template.create.alreadyexists", templateName.toString()));
			return 4;
		}

		BackpackTemplates.setBackpackTemplate(templateName, backpackWrapper);
		source.sendSuccess(() -> Component.translatable("commands.sophisticatedbackpacks.template.create.success", templateName.toString()), true);
		return 0;
	}

private void onWorldTick(LevelTickEvent.Post event) {
		if (event.getLevel().isClientSide()) {
			return;
		}

		ResourceLocation dimensionKey = event.getLevel().dimension().location();
		boolean runSlownessLogic = Boolean.TRUE.equals(Config.SERVER.nerfsConfig.tooManyBackpacksSlowness.get());
		boolean runDedupeLogic = Boolean.FALSE.equals(Config.SERVER.tickDedupeLogicDisabled.get());
		if ((!runSlownessLogic && !runDedupeLogic) || nextBackpackCheckTime.getOrDefault(dimensionKey, 0L) > event.getLevel().getGameTime()) {
			return;
		}
		nextBackpackCheckTime.put(dimensionKey, event.getLevel().getGameTime() + BACKPACK_CHECK_COOLDOWN);

		Map<UUID, IBackpackWrapper> backpackIds = new HashMap<>();

		event.getLevel().players().forEach(player -> {
			Set<ItemStack> allBackpacks = new HashSet<>();
			PlayerInventoryProvider.get().runOnBackpacks(player, (backpack, handlerName, identifier, slot) -> {
				if (runSlownessLogic) {
					allBackpacks.add(backpack);
				}
				if (runDedupeLogic && LinkedStorageStackLifecycle.classifyEndpoint(backpack) != LinkedStorageEndpointStackState.ENDPOINT) {
					addBackpackIdIfUniqueOrDedupe(backpackIds, BackpackWrapper.fromStack(backpack));
				}
				return false;
			});
			if (runSlownessLogic) {
				int maxNumberOfBackpacks = Config.SERVER.nerfsConfig.maxNumberOfBackpacks.get();
				if (allBackpacks.size() > maxNumberOfBackpacks) {
					int numberOfSlownessLevels = Math.min(10, (int) Math
							.ceil((allBackpacks.size() - maxNumberOfBackpacks) * Config.SERVER.nerfsConfig.slownessLevelsPerAdditionalBackpack.get()));
					Holder<MobEffect> effect = Config.SERVER.nerfsConfig.getEffect();
					player.addEffect(new MobEffectInstance(effect, BACKPACK_CHECK_COOLDOWN * 2, numberOfSlownessLevels - 1, false, false));
				}
			}
		});
	}

private void handleBreakBackpackWithInfinityUpgrade(BlockEvent.BreakEvent event) {
		Player player = event.getPlayer();

		if (!(event.getState().getBlock() instanceof BackpackBlock)) {
			return;
		}

		if (WorldHelper
				.getBlockEntity(event.getLevel(), event.getPos(), BackpackBlockEntity.class).map(backpackBlockEntity -> backpackBlockEntity.getStorageWrapper()
						.getUpgradeHandler().getTypeWrappers(InfinityUpgradeItem.TYPE).stream().anyMatch(w -> !player.hasPermissions(w.getPermissionLevel())))
				.orElse(false)) {
			event.setCanceled(true);
			player.displayClientMessage(SBPTranslationHelper.INSTANCE.translStatusMessage("infinity_upgrade_only_admin_break").withStyle(ChatFormatting.RED),
					true);
		}
	}

private static boolean shouldDropBackpack(LivingDropsEvent event, Config.Server.EntityBackpackAdditionsConfig additionsConfig, LivingEntity mob,
			ItemStack backpack) {
		if (!(event.getSource().getEntity() instanceof Player player)) {
			return false;
		}
		if (!additionsConfig.dropToFakePlayers.get() && event.getSource().getEntity() instanceof FakePlayer) {
			return false;
		}
		float lootingChanceMultiplier = dropChanceMultiplier.getOrDefault(backpack.getItem(), 1F);
		int lootingLevel = player.level().registryAccess().registry(Registries.ENCHANTMENT)
				.map(registry -> player.getMainHandItem().getEnchantmentLevel(registry.getHolderOrThrow(Enchantments.LOOTING))).orElse(0);
		return mob.level().random.nextFloat() < (additionsConfig.backpackDropChance.get() + lootingLevel * additionsConfig.lootingChanceIncreasePerLevel.get())
				* lootingChanceMultiplier;
	}

private static CompoundTag getOrCreateBackpackEntityData(LivingEntity entity) {
