public static void handlePayload(RequestBackpackInventoryContentsPayload payload, IPayloadContext context) {
		CompoundTag backpackContents = BackpackStorage.get().getOrCreateBackpackContents(payload.backpackUuid);

		CompoundTag inventoryContents = new CompoundTag();
		Tag inventoryNbt = backpackContents.get(InventoryHandler.INVENTORY_TAG);
		if (inventoryNbt != null) {
			inventoryContents.put(InventoryHandler.INVENTORY_TAG, inventoryNbt);
		}
		Tag upgradeNbt = backpackContents.get(UpgradeHandler.UPGRADE_INVENTORY_TAG);
		if (upgradeNbt != null) {
			inventoryContents.put(UpgradeHandler.UPGRADE_INVENTORY_TAG, upgradeNbt);
		}
		if (context.player() instanceof ServerPlayer serverPlayer) {
			PacketDistributor.sendToPlayer(serverPlayer, new BackpackContentsPayload(payload.backpackUuid, inventoryContents));
		}
	}

public static void handlePayload(SyncClientInfoPayload payload, IPayloadContext context) {
		Player player = context.player();
		if (payload.renderInfoNbt == null || !(player.containerMenu instanceof BackpackContainer backpackContainer)) {
			return;
		}
		if (!backpackContainer.canApplyClientInfo(payload.slotIndex)) {
			return;
		}
		if (payload.slotIndex >= 0) {
			if (payload.slotIndex >= player.getInventory().items.size()) {
				return;
			}
			ItemStack backpack = player.getInventory().items.get(payload.slotIndex);
			// Keep the canonical columns unchanged until the menu detects the layout change below.
			IBackpackWrapper backpackWrapper = new BackpackWrapper(backpack);
			backpackWrapper.getRenderInfo().deserializeFrom(payload.renderInfoNbt);
			backpackWrapper.setColumnsTaken(payload.columnsTaken, false);
		}
		backpackContainer.syncClientInfo(payload.renderInfoNbt, payload.columnsTaken);
	}

public static boolean isSword(ItemStack stack) {
		if (SWORD_ITEMS.contains(stack.getItem())) {
			return true;
		}

		if (stack.getItem() instanceof SwordItem) {
			SWORD_ITEMS.add(stack.getItem());
			return true;
		}

		ResourceLocation registryName = BuiltInRegistries.ITEM.getKey(stack.getItem());
		if (registryName == BuiltInRegistries.ITEM.getDefaultKey()) {
			return false;
		}

		for (Predicate<ItemStack> swordMatcher : SWORD_MATCHERS) {
			if (swordMatcher.test(stack)) {
				return true;
			}
		}

		String modId = registryName.getNamespace();
		if (!MOD_SWORD_MATCHERS.containsKey(modId)) {
			return false;
		}

		Set<Predicate<ItemStack>> matchers = MOD_SWORD_MATCHERS.get(modId);
		for (Predicate<ItemStack> matcher : matchers) {
			if (matcher.test(stack)) {
				return true;
			}
		}

		return false;
	}

private void parseFromArrays(JsonArray blocksArray, JsonArray toolsArray) {
			Tuple<Set<Item>, Set<Predicate<ItemStack>>> tools = getItemsAndItemPredicates(toolsArray);
			if (tools.getA().isEmpty() && tools.getB().isEmpty()) {
				return;
			}
			for (JsonElement jsonElement : blocksArray) {
				if (jsonElement.isJsonPrimitive() && jsonElement.getAsString().contains(":")) {
					parseObjectEntry(tools, jsonElement.getAsString());
				} else {
					parseObjectPredicateEntry(tools, jsonElement);
				}
			}
		}

private void parseFromProperty(JsonObject entry) {
			for (Map.Entry<String, JsonElement> property : entry.entrySet()) {
				if (property.getKey().contains(":")) {
					parseObjectTools(property);
				} else {
					parseModTools(property);
				}
			}
		}

public boolean isToolFor(ItemStack stack, V object, Supplier<C> getContext) {
			Item item = stack.getItem();
			if (objectTools.containsKey(object) && objectTools.get(object).contains(item)) {
				return true;
			}
			if (notToolCache.containsKey(object) && notToolCache.get(object).contains(item)) {
				return false;
			}

			if (tryToMatchAgainstObjectToolPredicates(stack, object)) {
				return true;
			}

			C context = getContext.get();
			if (tryToMatchAgainstObjectPredicateTools(item, context)) {
				return true;
			}

			if (tryToMatchAgainstObjectPredicateToolPredicates(stack, context)) {
				return true;
			}

			if (tryToMatchNoMappingMod(stack, object)) {
				return true;
			}

			notToolCache.computeIfAbsent(object, b -> new HashSet<>()).add(item);

			return false;
		}

private boolean isNoMappingModAndNonStackableItemFromSameMod(ItemStack stack, V object) {
			return RegistryHelper.getRegistryName(registry, object)
					.map(rn -> !rn.getNamespace().equals("minecraft") && !modsWithMapping.contains(rn.getNamespace())
							&& RegistryHelper.getRegistryName(BuiltInRegistries.ITEM, stack.getItem())
									.map(itemRegistryName -> itemRegistryName.getNamespace().equals(rn.getNamespace())).orElse(false))
					.orElse(false) && stack.getMaxStackSize() == 1;
		}

private boolean tryToMatchAgainstObjectPredicateTools(Item item, C context) {
			for (Map.Entry<Predicate<C>, Set<Item>> entry : objectPredicateTools.entrySet()) {
				if (entry.getKey().test(context) && entry.getValue().contains(item)) {
					addObjectToolMapping(getObjectFromContext.apply(context), item);
					return true;
				}
			}
			return false;
		}

