	public UpgradeSlotChangeResult canRemoveUpgradeFrom(IStorageWrapper storageWrapper, boolean isClientSide) {
		Optional<IBackpackWrapper> canonicalBackpack = findCanonicalBackpack(storageWrapper);
		if (canonicalBackpack.isEmpty()) {
			return UpgradeSlotChangeResult.success();
		}
		IBackpackWrapper backpackWrapper = canonicalBackpack.get();
		List<CapturedMob> capturedMobs = MobCatcherStorage.getCapturedMobs(backpackWrapper);
		return capturedMobs.isEmpty()
				? UpgradeSlotChangeResult.success()
				: UpgradeSlotChangeResult.fail(Component.translatable("gui.sophisticatedbackpacks.status.mob_catcher_contains_mobs"),
						getMobCatcherUpgradeSlots(backpackWrapper), getOccupiedCapturedMobSlots(backpackWrapper, capturedMobs), Set.of());
	}

@Override
	public UpgradeSlotChangeResult canSwapUpgradeFor(ItemStack upgradeStackToPut, int upgradeSlot, IStorageWrapper storageWrapper, boolean isClientSide) {
		Optional<IBackpackWrapper> canonicalBackpack = findCanonicalBackpack(storageWrapper);
		if (canonicalBackpack.isEmpty()) {
			return UpgradeSlotChangeResult.success();
		}
		if (upgradeStackToPut.getItem() instanceof MobCatcherUpgradeItem mobCatcherUpgradeItem && mobCatcherUpgradeItem.isAdvanced()) {
			return UpgradeSlotChangeResult.success();
		}
		IBackpackWrapper backpackWrapper = canonicalBackpack.get();
		List<CapturedMob> capturedMobs = MobCatcherStorage.getCapturedMobs(backpackWrapper);
		return MobCatcherStorage.canFitBasicTier(backpackWrapper, Config.SERVER.mobCatcherUpgrade.basicMaxSlotCost.get())
				? UpgradeSlotChangeResult.success()
				: UpgradeSlotChangeResult.fail(Component.translatable("gui.sophisticatedbackpacks.status.mob_catcher_mobs_need_advanced"), Set.of(upgradeSlot),
						getOccupiedCapturedMobSlots(backpackWrapper, capturedMobs), Set.of());
	}

private Optional<IBackpackWrapper> findCanonicalBackpack(IStorageWrapper storageWrapper) {
		if (storageWrapper instanceof IBackpackWrapper backpackWrapper) {
			return Optional.of(backpackWrapper);
		}
		return storageWrapper.getUpgradeHandler().getTypeWrappers(TYPE).stream().map(MobCatcherUpgradeWrapper::getBackpackWrapper).flatMap(Optional::stream)
				.findFirst();
	}

private Set<Integer> getMobCatcherUpgradeSlots(IBackpackWrapper backpackWrapper) {
		Set<Integer> slots = new HashSet<>();
		backpackWrapper.getUpgradeHandler().getSlotWrappers().forEach((slot, wrapper) -> {
			if (wrapper instanceof MobCatcherUpgradeWrapper) {
				slots.add(slot);
			}
		});
		return slots;
	}

private Set<Integer> getOccupiedCapturedMobSlots(IBackpackWrapper backpackWrapper, List<CapturedMob> capturedMobs) {
		Set<Integer> slots = new HashSet<>();
		int columns = MobCatcherStorage.getColumns(backpackWrapper);
		for (CapturedMob capturedMob : capturedMobs) {
			for (int yOffset = 0; yOffset < capturedMob.height(); yOffset++) {
				for (int xOffset = 0; xOffset < capturedMob.width(); xOffset++) {
					slots.add(capturedMob.slot() + yOffset * columns + xOffset);
				}
			}
		}
		return slots;
	}

@Override
	public void addClientStorageContents(CompoundTag contents) {
		if (!(storageWrapper instanceof IBackpackWrapper backpackWrapper)) {
			return;
		}

		CompoundTag capturedMobsTag = MobCatcherStorage.getCapturedMobsTag(backpackWrapper);
		if (capturedMobsTag.contains(MobCatcherStorage.CAPTURED_MOBS_TAG)) {
			contents.put(MobCatcherStorage.CAPTURED_MOBS_TAG, capturedMobsTag.get(MobCatcherStorage.CAPTURED_MOBS_TAG));
		}
	}

public RefillUpgradeWrapper(IStorageWrapper backpackWrapper, ItemStack upgrade, Consumer<ItemStack> upgradeSaveHandler) {
		super(backpackWrapper, upgrade, upgradeSaveHandler);
		filterLogic = new FilterLogic(upgrade, upgradeSaveHandler, upgradeItem.getFilterSlotCount(), ModCoreDataComponents.FILTER_ATTRIBUTES);
		targetSlots = new HashMap<>(upgrade.getOrDefault(ModDataComponents.TARGET_SLOTS, new HashMap<>()));
		if (upgradeItem.allowsTargetSlotSelection()) {
			FilterLogic.ObservableFilterItemStackHandler filterHandler = filterLogic.getFilterHandler();
			filterHandler.setOnSlotChange(s -> onFilterChange(filterHandler, s));
		}
		filterLogic.setAllowByDefault(true);
	}

private void refillItemFor(Entity entity) {
		CapabilityHelper.runOnItemHandler(entity, playerInvHandler -> InventoryHelper.iterate(filterLogic.getFilterHandler(), (slot, filter) -> {
			if (filter.isEmpty()) {
				return;
			}
			tryRefillFilter(entity, playerInvHandler, filter, getTargetSlots().getOrDefault(slot, TargetSlot.ANY));
		}));
	}

