		}

@Override
		public TintDecorationResult decorateWithTints(ItemStack input, int mainColorToSet, int accentColorToSet) {
			if (colorsTransparentOrSameAs(input, mainColorToSet, accentColorToSet)) {
				return TintDecorationResult.EMPTY;
			}

			ItemStack result = input.copyWithCount(1);

			if (result.getItem() instanceof BlockItem blockItem && blockItem instanceof ITintableBlockItem tintableBlockItem) {
				if (mainColorToSet != -1) {
					tintableBlockItem.setMainColor(result, mainColorToSet);
				}
				if (accentColorToSet != -1) {
					tintableBlockItem.setAccentColor(result, accentColorToSet);
				}
			}

			return new TintDecorationResult(result, calculateRequiredDyes(mainColorToSet, accentColorToSet,
					StorageBlockItem.getMainColorFromComponentHolder(input).orElse(-1), StorageBlockItem.getAccentColorFromComponentHolder(input).orElse(-1)));

		}

@Override
			public TintDecorationResult decorateWithTints(ItemStack input, int mainColorToSet, int accentColorToSet) {
				int currentColor = DyedItemColor.getOrDefault(input, -1);
				if (mainColorToSet == -1 || (currentColor == mainColorToSet)) {
					return TintDecorationResult.EMPTY;
				}

				ItemStack result = input.copyWithCount(1);
				result.set(DataComponents.DYED_COLOR, new DyedItemColor(FastColor.ARGB32.color(0, FastColor.ARGB32.red(mainColorToSet),
						FastColor.ARGB32.green(mainColorToSet), FastColor.ARGB32.blue(mainColorToSet)), true));

				return new TintDecorationResult(result, DecorationHelper.getDyePartsNeeded(mainColorToSet, -1, currentColor, -1, 24, 0));
			}

public boolean tryToDyeAll(BlockState state, Level level, BlockPos pos, BlockHitResult hitVec, ItemStack itemStack) {
		if (hitVec.getDirection() != getFacing(state) || !(itemStack.getItem() instanceof DyeItem)) {
			return false;
		}
		return WorldHelper.getBlockEntity(level, pos, LimitedBarrelBlockEntity.class)
				.map(barrel -> barrel.applyDye(0, itemStack, ((DyeItem) itemStack.getItem()).getDyeColor(), true)).orElse(false);
	}

public boolean tryToTakeItem(BlockState state, Level level, BlockPos pos, Player player) {
		return WorldHelper.getBlockEntity(level, pos, LimitedBarrelBlockEntity.class).map(be -> tryToTakeItem(state, level, pos, player, be)).orElse(false);
	}

private boolean tryToTakeItem(BlockState state, Level level, BlockPos pos, Player player, LimitedBarrelBlockEntity be) {
		return getHitResult(player).map(blockHitResult -> {
			if (!blockHitResult.getBlockPos().equals(pos) || level.getBlockState(pos) != state || blockHitResult.getDirection() != getFacing(state)) {
				return false;
			}

			return !be.isPacked() && be.tryToTakeItem(player, getInteractionSlot(pos, state, blockHitResult));
		}).orElse(false);
	}

public boolean isLookingAtFront(Player player, BlockPos pos, BlockState state) {
