public void copyLinkedStorageEndpointTo(ItemStack stack) {
		if (linkedStorageEndpoint == null) {
			return;
		}
		stack.set(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT, linkedStorageEndpoint);
		if (storageWrapper.getLinkedStorageEndpointRole().orElse(null) == LinkedStorageEndpointRole.PRIMARY) {
			stack.set(ModCoreDataComponents.LINKED_STORAGE_PRIMARY_ENDPOINT, true);
		} else {
			stack.remove(ModCoreDataComponents.LINKED_STORAGE_PRIMARY_ENDPOINT);
		}
		stack.remove(ModCoreDataComponents.STORAGE_UUID);
	}

public void writeLinkedStorageMenuData(FriendlyByteBuf buffer) {
		if (!(level instanceof ServerLevel serverLevel) || linkedStorageEndpoint == null || !isLinkedStorageEndpointMember(serverLevel, linkedStorageEndpoint)
				|| linkedStorageHost == null) {
			buffer.writeBoolean(false);
			return;
		}

		LinkedStorageGroupManager manager = LinkedStorageGroupsSavedData.get(serverLevel).manager();
		Optional<ILinkedStorageContents> contents = manager.resolveContents(linkedStorageEndpoint.groupId());
		Optional<CompoundTag> virtualCarrier = ((ILinkedStorageVirtualHost) linkedStorageHost).getVirtualCarrierSnapshot();
		if (contents.isEmpty() || virtualCarrier.isEmpty()) {
			buffer.writeBoolean(false);
			return;
		}

		buffer.writeBoolean(true);
		buffer.writeUUID(linkedStorageEndpoint.groupId());
		buffer.writeUUID(linkedStorageEndpoint.endpointId());
		buffer.writeBoolean(manager.isPrimaryEndpoint(linkedStorageEndpoint.groupId(), linkedStorageEndpoint.endpointId()));
		buffer.writeVarLong(manager.getRevision(linkedStorageEndpoint.groupId()));
		ComponentSerialization.TRUSTED_CONTEXT_FREE_STREAM_CODEC.encode(buffer,
				((ILinkedStorageVirtualHost) linkedStorageHost).getLinkedStorageDisplayName().orElse(getDisplayName()));
		FriendlyByteBuf.writeNbt(buffer, contents.get().getContents());
		buffer.writeVarInt(linkedStorageHost.getInventoryHandler().getSlots());
		buffer.writeVarInt(linkedStorageHost.getUpgradeHandler().getSlots());
		buffer.writeVarInt(linkedStorageHost.getColumnsTaken());
		buffer.writeResourceLocation(manager.getHostDescriptor(linkedStorageEndpoint.groupId()).orElseThrow().factoryId());
		FriendlyByteBuf.writeNbt(buffer, virtualCarrier.get());
	}

void loadEndpointData(CompoundTag tag) {
		renderInfoNbt = tag.getCompound(RENDER_INFO_TAG);
		renderInfo.deserializeFrom(renderInfoNbt);
		renderInfoValidationPending = true;
		openTabId = NBTHelper.getInt(tag, OPEN_TAB_ID_TAG).orElse(-1);
		mainColor = NBTHelper.getInt(tag, MAIN_COLOR_TAG).orElse(-1);
		accentColor = NBTHelper.getInt(tag, ACCENT_COLOR_TAG).orElse(-1);
	}

void loadCanonicalData(CompoundTag tag) {
		contentsNbt = tag.contains(CONTENTS_TAG) ? tag.getCompound(CONTENTS_TAG) : new CompoundTag();
		settingsNbt = tag.getCompound(SETTINGS_TAG);
		if (!tag.contains(SETTINGS_TAG)) {
			tag.put(SETTINGS_TAG, settingsNbt);
		}
		settingsHandler.reloadFrom(settingsNbt);
		numberOfInventorySlots = tag.getInt(NUMBER_OF_INVENTORY_SLOTS_TAG);
		numberOfUpgradeSlots = tag.getInt(NUMBER_OF_UPGRADE_SLOTS_TAG);
		sortBy = NBTHelper.getString(tag, SORT_BY_TAG).map(SortBy::fromName).orElse(SortBy.NAME);
		inventoryHandler = null;
		upgradeHandler = null;
		inventoryIOHandler = null;
	}

private void loadData(CompoundTag tag) {
		settingsNbt = tag.getCompound(SETTINGS_TAG);
		settingsHandler.reloadFrom(settingsNbt);
		renderInfoNbt = tag.getCompound(RENDER_INFO_TAG);
		renderInfo.deserializeFrom(renderInfoNbt);
		renderInfoValidationPending = true;
		contentsUuid = NBTHelper.getTagValue(tag, UUID_TAG, CompoundTag::get).map(NbtUtils::loadUUID).orElse(null);
		openTabId = NBTHelper.getInt(tag, OPEN_TAB_ID_TAG).orElse(-1);
		sortBy = NBTHelper.getString(tag, SORT_BY_TAG).map(SortBy::fromName).orElse(SortBy.NAME);
		columnsTaken = NBTHelper.getInt(tag, "columnsTaken").orElse(0);
		loadSlotNumbers(tag);
		mainColor = NBTHelper.getInt(tag, MAIN_COLOR_TAG).orElse(-1);
		accentColor = NBTHelper.getInt(tag, ACCENT_COLOR_TAG).orElse(-1);
	}

protected void loadSlotNumbers(CompoundTag tag) {
		numberOfInventorySlots = NBTHelper.getInt(tag, NUMBER_OF_INVENTORY_SLOTS_TAG).orElse(0);
		numberOfUpgradeSlots = NBTHelper.getInt(tag, NUMBER_OF_UPGRADE_SLOTS_TAG).orElse(-1);
		if (promoteSlotNumbersToDefaults()) {
			save();
		}
	}

private void loadContents(CompoundTag tag) {
		if (tag.contains(CONTENTS_TAG)) {
			contentsNbt = tag.getCompound(CONTENTS_TAG);
			onContentsNbtUpdated();
		}
	}

private boolean updateLinkedHandlers() {
		Object inventory = linkedStorage == null ? null : linkedStorage.getInventoryHandler();
		Object upgrades = linkedStorage == null ? null : linkedStorage.getUpgradeHandler();
		IStorageFluidHandler fluid = linkedStorage == null ? null : linkedStorage.getFluidHandler().orElse(null);
		IEnergyStorage energy = linkedStorage == null ? null : linkedStorage.getEnergyStorage().orElse(null);
		boolean changed = linkedInventory != inventory || linkedUpgrades != upgrades || linkedFluidHandler != fluid || linkedEnergyStorage != energy;
		linkedInventory = inventory;
		linkedUpgrades = upgrades;
		linkedFluidHandler = fluid;
		linkedEnergyStorage = energy;
		return changed;
	}

public void addDropData(ItemStack stack, StorageBlockEntity be) {
		if (be instanceof WoodStorageBlockEntity wbe) {
			addNameWoodAndTintData(stack, wbe);
			if (wbe.isLinkedStorage()) {
				wbe.copyLinkedStorageEndpointTo(stack);
				return;
			}
			boolean packed = wbe.isPacked() || shouldNonEmptyDropPacked(wbe);
			if (packed) {
				StorageWrapper storageWrapper = be.getStorageWrapper();
				UUID storageUuid = storageWrapper.getContentsUuid().orElse(UUID.randomUUID());
				CompoundTag storageContents = wbe.getStorageContentsTag();
				if (!storageContents.isEmpty()) {
					ItemContentsStorage.get().setStorageContents(storageUuid, storageContents);
					stack.set(ModCoreDataComponents.STORAGE_UUID, storageUuid);
				}
				WoodStorageBlockItem.setPacked(stack, true);
				StorageBlockItem.setShowsTier(stack, be.shouldShowTier());
				StorageBlockItem.setNumberOfInventorySlots(stack, storageWrapper.getInventoryHandler().getSlots());
				StorageBlockItem.setNumberOfUpgradeSlots(stack, storageWrapper.getUpgradeHandler().getSlots());
			}
		}
	}

@Override
	public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack stack) {
		if (level.isClientSide()) {
			WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).ifPresent(be -> setRenderBlockRenderProperties(stack, be));
			return;
		}
		ServerLevel serverLevel = (ServerLevel) level;

		WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).ifPresent(be -> {
			LegacyStorageBlockDataMigration.normalizeLegacyData(stack);
			UUID storageUuid = stack.get(ModCoreDataComponents.STORAGE_UUID);
			if (storageUuid != null && !StorageBlockEntity.hasLinkedStorageEndpoint(stack)) {
				ItemContentsStorage itemContentsStorage = ItemContentsStorage.get();
				if (itemContentsStorage.has(storageUuid)) {
					be.setBeingUpgraded(true);
					be.loadAdditional(itemContentsStorage.getOrCreateStorageContents(storageUuid), level.registryAccess());
					itemContentsStorage.removeStorageContents(storageUuid);
					setNewSize(stack, be);
					setTicking(level, pos, state, !be.getStorageWrapper().getUpgradeHandler().getWrappersThatImplement(ITickableUpgrade.class).isEmpty());
				} else {
					SophisticatedStorage.LOGGER
							.error("No storage contents found for uuid: " + storageUuid + " when placing " + stack.getHoverName().getString());
				}
			}

			if (stack.has(DataComponents.CUSTOM_NAME) && (!StorageBlockEntity.hasLinkedStorageEndpoint(stack)
					|| StorageBlockEntity.getLinkedStorageEndpointRole(stack).orElse(null) == LinkedStorageEndpointRole.PRIMARY)) {
				be.setCustomName(stack.getHoverName());
			}
			if (stack.has(DataComponents.CUSTOM_NAME)
					&& StorageBlockEntity.getLinkedStorageEndpointRole(stack).orElse(null) == LinkedStorageEndpointRole.PRIMARY) {
				StorageLinkedStorageEndpointAdapter.synchronizePrimaryCarrier(serverLevel, stack);
			}
			setRenderBlockRenderProperties(stack, be);
			boolean restoredLinkedStorage = !StorageBlockEntity.hasLinkedStorageEndpoint(stack);
			if (shouldRestoreLinkedStorageEndpoint(stack) && !restoredLinkedStorage) {
				if (placer instanceof Player player && player.getAbilities().instabuild && StorageBlockEntity.hasLinkedStorageEndpoint(stack)) {
					restoredLinkedStorage = be.restoreCreativeLinkedStorageEndpoint(serverLevel, stack);
				} else {
					restoredLinkedStorage = be.restoreLinkedStorageEndpoint(serverLevel, stack);
				}
			}

			be.getStorageWrapper().onInit(level);
			if (restoredLinkedStorage) {
				be.tryToAddToController();
			}

			if (placer != null && placer.getOffhandItem().getItem() == ModItems.STORAGE_TOOL.get()) {
				StorageToolItem.useOffHandOnPlaced(placer.getOffhandItem(), be);
			}
			be.setBeingUpgraded(false);
		});
	}

