private static int getBarrelTintColor(BlockState state, @Nullable BlockAndTintGetter blockDisplayReader, @Nullable BlockPos pos, int tintIndex) {
		if (tintIndex < 0 || pos == null) {
			return -1;
		}
		return WorldHelper.getBlockEntity(blockDisplayReader, pos, StorageBlockEntity.class).map(be -> {
			if (tintIndex == 1000) {
				int mainColor = be.getStorageWrapper().getMainColor();
				return mainColor != -1 ? mainColor : getGenericWoodColor(be, true);
			} else if (tintIndex == 1001) {
				int accentColor = be.getStorageWrapper().getAccentColor();
				return accentColor != -1 ? accentColor : getGenericWoodColor(be, false);
			} else {
				RenderInfo.ItemDisplayRenderInfo itemDisplayRenderInfo = be.getStorageWrapper().getRenderInfo().getItemDisplayRenderInfo();
				int displayItemIndex = (tintIndex > 1000 ? tintIndex - 1000 : tintIndex) / 10 - 1;
				List<RenderInfo.DisplayItem> displayItems = itemDisplayRenderInfo.getDisplayItems();
				if (displayItemIndex >= 0) {
					int tintOffset = (displayItemIndex + 1) * 10;
					ItemStack stack = getDisplayItemWithIndex(displayItemIndex, displayItems, state.getBlock() instanceof LimitedBarrelBlock);
					if (stack.isEmpty()) {
						return -1;
					}
					return Minecraft.getInstance().getItemColors().getColor(stack, tintIndex - tintOffset);
				}
			}
			return -1;
		}).orElse(-1);
	}

private static int getGenericWoodColor(StorageBlockEntity be, boolean mainColor) {
		if (be instanceof WoodStorageBlockEntity woodStorageBlockEntity) {
			return woodStorageBlockEntity.getWoodType().filter(GenericWoodStorageHelper::isGenericWood)
					.map(woodType -> mainColor ? GenericWoodStorageTintCache.getMainColor(woodType) : GenericWoodStorageTintCache.getAccentColor(woodType))
					.orElse(-1);
		}
		return -1;
	}

private static int getChestShulkerBoxColor(BlockState state, @Nullable BlockAndTintGetter blockDisplayReader, @Nullable BlockPos pos, int tintIndex) {
		if (tintIndex < 0 || pos == null) {
			return -1;
		}
		return WorldHelper.getBlockEntity(blockDisplayReader, pos, StorageBlockEntity.class).map(be -> {
			if (tintIndex == 0) { // this is only needed for particle texture handling so no need to handle anything other than just the main color
				int mainColor = be.getStorageWrapper().getMainColor();
				return mainColor != -1 ? mainColor : getGenericWoodColor(be, true);
			}
			return -1;
		}).orElse(-1);
	}

@Override
	public List<BakedQuad> getQuads(@Nullable BlockState state, @Nullable Direction side, RandomSource rand, ModelData extraData,
			@Nullable RenderType renderType) {
		String woodName = null;
		boolean hasMainColor;
		boolean hasAccentColor;
		boolean isPacked;
		boolean showsTier;
		Map<BarrelMaterial, ResourceLocation> materials;
		Map<ResourceLocation, Integer> materialTintColors;
		if (state != null) {
			hasMainColor = Boolean.TRUE.equals(extraData.get(HAS_MAIN_COLOR));
			hasAccentColor = Boolean.TRUE.equals(extraData.get(HAS_ACCENT_COLOR));
			if (extraData.has(WOOD_NAME)) {
				woodName = extraData.get(WOOD_NAME);
			}
			isPacked = isPacked(extraData);
			materials = getMaterials(extraData);
			materialTintColors = getMaterialTintColors(extraData);
			showsTier = showsTier(extraData);
		} else {
			woodName = barrelWoodName;
			hasMainColor = barrelHasMainColor;
			hasAccentColor = barrelHasAccentColor;
			isPacked = barrelIsPacked;
			materials = barrelMaterials;
			materialTintColors = getMaterialTintColors(materials, null, null);
			showsTier = barrelShowsTier;
		}
		boolean showsLocked = showsLocked(extraData);
		List<RenderInfo.DisplayItem> displayItems = extraData.has(DISPLAY_ITEMS) ? extraData.get(DISPLAY_ITEMS) : null;
		List<Integer> inaccessibleSlots = extraData.has(INACCESSIBLE_SLOTS) ? extraData.get(INACCESSIBLE_SLOTS) : null;
		BarrelBakedModelCacheKey cacheKey = new BarrelBakedModelCacheKey(this, state, side, renderType, state == null ? barrelItem : null, woodName,
				hasMainColor, hasAccentColor, isPacked, showsLocked, showsTier, state == null && flatTop, materials, materialTintColors, displayItems,
				inaccessibleSlots);
		List<BakedQuad> quads = BAKED_QUADS_CACHE.getIfPresent(cacheKey);
		if (quads != null) {
			return quads;
		}
		cacheKey = cacheKey.immutableCopy();

		List<BakedQuad> ret = new ArrayList<>();

		boolean isBakedDynamically = !materials.isEmpty();
		Set<BarrelMaterial.MaterialModelPart> materialModelParts = materials.keySet().stream().map(BarrelMaterial::getMaterialModelPart)
				.collect(Collectors.toSet());
		boolean rendersUsingSplitModel = materialModelParts.contains(BarrelMaterial.MaterialModelPart.CORE)
				|| materialModelParts.contains(BarrelMaterial.MaterialModelPart.TRIM);

		Map<BarrelModelPart, BakedModel> modelParts = getWoodModelParts(woodName, isBakedDynamically && rendersUsingSplitModel);
		if (modelParts.isEmpty()) {
			return Collections.emptyList();
		}

		if ((!hasMainColor || !hasAccentColor) && !isBakedDynamically) {
			addPartQuads(state, side, rand, ret, modelParts, getBasePart(state), renderType);
		}

		addTintableModelQuads(state, side, rand, ret, hasMainColor, hasAccentColor, modelParts, renderType);

		if (isBakedDynamically && shouldRenderDynamicMaterials(state, renderType)) {
			Direction spriteSide = getSpriteSide(state, side);
			Map<ResourceLocation, RenderHelper.SpriteData> materialSpriteData = state != null
					? getMaterialSpriteData(spriteSide, rand, materials)
					: Collections.emptyMap();
			bakeAndAddDynamicQuads(spriteSide, rand, woodName, materials, rendersUsingSplitModel,
					!hasMainColor || materialModelParts.contains(BarrelMaterial.MaterialModelPart.CORE),
					!hasAccentColor || materialModelParts.contains(BarrelMaterial.MaterialModelPart.TRIM))
					.forEach(bakedModel -> addDynamicQuads(state, side, rand, ret, renderType, materialSpriteData, materialTintColors, bakedModel));
		}

		if (showsTier) {
			addPartQuads(state, side, rand, ret, modelParts, BarrelModelPart.TIER, renderType);
		}

		if (isPacked) {
			addPartQuads(state, side, rand, ret, modelParts, BarrelModelPart.PACKED, renderType);
		} else {
			if (showsLocked) {
				addPartQuads(state, side, rand, ret, modelParts, BarrelModelPart.LOCKED, renderType);
			}
			addDisplayItemQuads(state, side, rand, ret, extraData, renderType);
		}

		BAKED_QUADS_CACHE.put(cacheKey, ret);

		return ret;
	}

private static boolean shouldRenderDynamicQuad(ResourceLocation spriteName, Map<ResourceLocation, RenderHelper.SpriteData> materialSpriteData,
			@Nullable RenderType renderType) {
		if (renderType == null) {
			return true;
		}

		boolean translucent = Optional.ofNullable(materialSpriteData.get(spriteName)).map(RenderHelper.SpriteData::translucent).orElse(false);
		return (renderType == RenderType.translucent()) == translucent;
	}

private BakedModel compileAndBakeModel(Map<String, Either<Material, String>> materials, DynamicBarrelBakingData bakingData) {
		bakingData.modelPartDefinition().textures().forEach((textureName, texture) -> {
			if (!materials.containsKey(textureName)) {
				materials.put(textureName, Either.left(texture));
			}
		});

		BarrelDynamicModelBase.BarrelModelPartDefinition baseModelPartDefinition = bakingData.modelPartDefinition();
		return baseModelPartDefinition.modelLocation().map(modelLocation -> {
			BlockModel baseModel = new CompositeElementsModel(modelLocation, materials);
			ModelBakery bakery = Minecraft.getInstance().getModelManager().getModelBakery();
			baseModel.resolveParents(bakery::getModel); // need to call resolveParents here to get parent models loaded
			return baseModel.bake(baker, baseModel, baker.getModelTextureGetter(), bakingData.modelState(), false);
		}).orElse(Minecraft.getInstance().getModelManager().getMissingModel());
	}

private static boolean shouldRenderForRenderType(ItemStack item, @Nullable RenderType renderType, BakedModel model, RandomSource rand) {
		ClientLevel clientLevel = Minecraft.getInstance().level;
		if (renderType == null || clientLevel == null) {
			return true;
		}

		if (item.getItem() instanceof BlockItem blockItem) {
			ChunkRenderTypeSet renderTypes = model.getRenderTypes(blockItem.getBlock().defaultBlockState(), rand, ModelData.EMPTY);
			if (renderTypes.contains(RenderType.translucent())) {
				return renderType == RenderType.translucent() || renderTypes.asList().size() > 1;
			}
		}

		return renderType != RenderType.translucent();
	}

private void addPartQuads(@Nullable BlockState state, @Nullable Direction side, RandomSource rand, List<BakedQuad> ret,
			Map<BarrelModelPart, BakedModel> modelParts, BarrelModelPart part, @Nullable RenderType renderType) {
		if (renderType != null && renderType != RenderType.cutout()) {
			return;
		}

		if (modelParts.containsKey(part)) {
			ret.addAll(modelParts.getOrDefault(part, Minecraft.getInstance().getModelManager().getMissingModel()).getQuads(state, side, rand, ModelData.EMPTY,
					renderType));
		}
	}

