private static ModelData getModelDataFromBlockEntity(BarrelBlockEntity be, @Nullable BlockAndTintGetter world, @Nullable BlockPos pos) {
		ModelData.Builder builder = ModelData.builder();
		Optional<WoodType> woodType = be.getWoodType();
		boolean isGenericWood = woodType.map(GenericWoodStorageHelper::isGenericWood).orElse(false);
		boolean hasMainColor = be.getStorageWrapper().hasMainColor();
		boolean hasAccentColor = be.getStorageWrapper().hasAccentColor();
		builder.with(HAS_MAIN_COLOR, hasMainColor || isGenericWood);
		builder.with(HAS_ACCENT_COLOR, hasAccentColor || isGenericWood);
		if (!be.hasFullyDynamicRenderer()) {
			builder.with(DISPLAY_ITEMS, be.getStorageWrapper().getRenderInfo().getItemDisplayRenderInfo().getDisplayItems());
			builder.with(INACCESSIBLE_SLOTS, be.getStorageWrapper().getRenderInfo().getItemDisplayRenderInfo().getInaccessibleSlots());
		}
		builder.with(IS_PACKED, be.isPacked());
		builder.with(SHOWS_LOCK, be.isLocked() && be.shouldShowLock());
		builder.with(SHOWS_TIER, be.shouldShowTier());
		if (!isGenericWood && (woodType.isPresent() || !(hasMainColor && hasAccentColor))) {
			builder.with(WOOD_NAME, woodType.orElse(WoodType.ACACIA).name());
		}

		Map<BarrelMaterial, ResourceLocation> materials = be.getMaterials();
		if (!materials.isEmpty()) {
			builder.with(MATERIALS, materials);
			Map<ResourceLocation, Integer> materialTintColors = getMaterialTintColors(materials, world, pos);
			if (!materialTintColors.isEmpty()) {
				builder.with(MATERIAL_TINT_COLORS, materialTintColors);
			}
		}
		return builder.build();
	}

@Nullable
		@Override
		public BakedModel resolve(BakedModel model, ItemStack stack, @Nullable ClientLevel level, @Nullable LivingEntity entity, int seed) {
			boolean flatTop = BarrelBlockItem.isFlatTop(stack);
			if (flatTopModel != null && flatTop) {
				return flatTopModel.getOverrides().resolve(flatTopModel, stack, level, entity, seed);
			}

			Optional<WoodType> woodType = WoodStorageBlockItem.getWoodType(stack);
			boolean isGenericWood = woodType.map(GenericWoodStorageHelper::isGenericWood).orElse(false);
			boolean hasMainColor = StorageBlockItem.getMainColorFromComponentHolder(stack).isPresent() || isGenericWood;
			boolean hasAccentColor = StorageBlockItem.getAccentColorFromComponentHolder(stack).isPresent() || isGenericWood;
			Map<BarrelMaterial, ResourceLocation> materials = BarrelBlockItem.getMaterials(stack);
			String woodName = isGenericWood
					? null
					: woodType.map(WoodType::name).orElse(hasAccentColor && hasMainColor && materials.isEmpty() ? null : WoodType.ACACIA.name());
			boolean packed = WoodStorageBlockItem.isPacked(stack);
			boolean barrelShowsTier = StorageBlockItem.showsTier(stack);
			Item item = stack.getItem();

			int hash = Objects.hash(item, woodName, hasMainColor, hasAccentColor, packed, barrelShowsTier, flatTop, materials);

			BakedModel resolvedModel = resolvedModels.getIfPresent(hash);
			if (resolvedModel == null) {
				resolvedModel = new ResolvedModel(hasMainColor, hasAccentColor, woodName, packed, barrelShowsTier, materials, flatTop, item);
				resolvedModels.put(hash, resolvedModel);
			}

			return resolvedModel;
		}

private void renderBlockEntity(ItemStack stack, PoseStack poseStack, MultiBufferSource buffer, int packedLight, int packedOverlay,
			ChestBlockEntity chestBlockEntity) {
		if (stack.getItem() instanceof ITintableBlockItem tintableBlockItem) {
			chestBlockEntity.getStorageWrapper().setColors(tintableBlockItem.getMainColor(stack).orElse(-1),
					tintableBlockItem.getAccentColor(stack).orElse(-1));
		}
		Optional<WoodType> woodType = WoodStorageBlockItem.getWoodType(stack);
		if (woodType.isPresent() || !(chestBlockEntity.getStorageWrapper().hasAccentColor() && chestBlockEntity.getStorageWrapper().hasMainColor())) {
			chestBlockEntity.setWoodType(woodType.orElse(WoodType.ACACIA));
		}
		chestBlockEntity.setPacked(WoodStorageBlockItem.isPacked(stack));
		if (StorageBlockItem.showsTier(stack) != chestBlockEntity.shouldShowTier()) {
			chestBlockEntity.toggleTierVisiblity();
		}
		var blockentityrenderer = blockEntityRenderDispatcher.getRenderer(chestBlockEntity);
		if (blockentityrenderer != null) {
			blockentityrenderer.render(chestBlockEntity, 0.0F, poseStack, buffer, packedLight, packedOverlay);
		}
	}

