private static <T extends PropertyBasedSubtypeInterpreter> void addMultipleColorsRecipe(List<RecipeHolder<CraftingRecipe>> recipes,
			Map<Item, ItemStack[]> items, Function<ItemStack, Optional<T>> getSubtypeInterpreter) {
		items.forEach((block, stacks) -> {
			NonNullList<Ingredient> ingredients = NonNullList.create();
			ingredients.add(Ingredient.of(DyeColor.YELLOW.getTag()));
			ingredients.add(Ingredient.of(stacks));
			ingredients.add(Ingredient.of(DyeColor.LIME.getTag()));

			ItemStack result = new ItemStack(block);
			if (result.getItem() instanceof ITintableBlockItem tintableBlockItem) {
				tintableBlockItem.setMainColor(result, DyeColor.YELLOW.getTextureDiffuseColor());
				tintableBlockItem.setAccentColor(result, DyeColor.LIME.getTextureDiffuseColor());
			}
			ResourceLocation id = ResourceLocation.fromNamespaceAndPath(SophisticatedStorage.MOD_ID,
					getSubtypeInterpreter.apply(result).map(i -> i.getRegistrySanitizedItemString(result)).orElse("multiple_color"));
			ShapedRecipePattern pattern = new ShapedRecipePattern(3, 1, ingredients, Optional.empty());
			recipes.add(new RecipeHolder<>(id, new ShapedRecipe("", CraftingBookCategory.MISC, pattern, result)));
		});
	}

private static <T extends PropertyBasedSubtypeInterpreter> List<SingleColorDyeRecipeSpec> getSingleColorRecipeSpecs(Map<Item, ItemStack[]> items,
			Function<ItemStack, Optional<T>> getSubtypeInterpreter) {
		List<SingleColorDyeRecipeSpec> recipes = new ArrayList<>();
		items.forEach((block, stacks) -> {
			List<DyeVariantPair> variants = new ArrayList<>();
			for (DyeColor color : DyeColor.values()) {
				ItemStack result = new ItemStack(block);
				if (result.getItem() instanceof ITintableBlockItem tintableBlockItem) {
					tintableBlockItem.setMainColor(result, color.getTextureDiffuseColor());
					tintableBlockItem.setAccentColor(result, color.getTextureDiffuseColor());
				}
				variants.add(new DyeVariantPair(new ItemStack(DyeItem.byColor(color)), result));
			}
			ItemStack idStack = variants.getFirst().result();
			ResourceLocation id = ResourceLocation.fromNamespaceAndPath(SophisticatedStorage.MOD_ID, getSubtypeInterpreter.apply(idStack)
					.map(i -> i.getRegistrySanitizedItemString(idStack)).orElse("single_color_" + BuiltInRegistries.ITEM.getKey(block).getPath()));
			recipes.add(new SingleColorDyeRecipeSpec(id.withSuffix("_grouped"), List.of(stacks), variants));
		});
		return recipes;
	}

public static void registerDyeRecipes(IRecipeViewerDisplayCatalog catalog, IRecipeViewerDisplayContext context) {
		DyeRecipesMaker.getSingleColorRecipeSpecs(context::getSubtypeInterpreter).stream()
				.map(spec -> new SingleColorDyeRecipeSpec(spec.id(), spec.sourceStacks(), spec.variantPairs(),
						(recipeResult, focusedOutput) -> context.getSubtypeInterpreter(focusedOutput)
								.map(interpreter -> recipeResult.is(focusedOutput.getItem())
										&& interpreter.getComparableData(recipeResult).equals(interpreter.getComparableData(focusedOutput)))
								.orElse(ItemStack.isSameItemSameComponents(recipeResult, focusedOutput))))
				.forEach(catalog::addGroupedCraftingSpec);
		DyeRecipesMaker.getMultipleColorsRecipes(context::getSubtypeInterpreter).forEach(catalog::addCraftingRecipe);
	}

private static ItemStack getSource(CraftingDisplayVariant variant) {
		return variant.inputs().stream().filter(stack -> !stack.isEmpty()).findFirst().orElse(ItemStack.EMPTY);
	}

private static <U extends PropertyBasedSubtypeInterpreter> String getPairKey(TierUpgradeVariantPair pair,
			Function<ItemStack, Optional<U>> getSubtypeInterpreter) {
		return getSubtypeInterpreter.apply(pair.source()).map(interpreter -> interpreter.getRegistrySanitizedItemString(pair.source()))
				.orElse(pair.source().toString()) + "->"
				+ getSubtypeInterpreter.apply(pair.result()).map(interpreter -> interpreter.getRegistrySanitizedItemString(pair.result()))
						.orElse(pair.result().toString());
	}

private void registerRecipes(EmiRegistry registry) {
		Map<BlockItem, PropertyBasedSubtypeInterpreter> subtypeInterpreters = getSubtypeInterpreters();
		IRecipeViewerDisplayCatalog catalog = createCatalog(subtypeInterpreters);
		Set<ResourceLocation> craftingRecipeIds = catalog.getCraftingRecipes().stream().map(RecipeHolder::id).collect(Collectors.toSet());
		registry.removeRecipes(recipe -> recipe.getBackingRecipe() != null
				&& (catalog.replacesCraftingRecipe(recipe.getBackingRecipe()) || craftingRecipeIds.contains(recipe.getBackingRecipe().id())));

		catalog.getGroupedCraftingSpecs().stream().flatMap(spec -> spec.getAllDisplays().stream())
				.flatMap(recipeHolder -> GroupedCraftingEmiRecipe.ofGroupedUsageAndFocusedRecipes(recipeHolder).stream()).forEach(registry::addRecipe);
		catalog.getCraftingRecipes().stream().filter(recipeHolder -> !catalog.replacesCraftingRecipe(recipeHolder))
				.flatMap(recipeHolder -> wrapSyntheticCraftingRecipe(recipeHolder).stream()).forEach(registry::addRecipe);

		catalog.getCraftingSpecs().stream().flatMap(spec -> CraftingSpecEmiRecipe.ofGroupedUsageAndFocusedRecipes(spec).stream()).forEach(registry::addRecipe);

	}

@Override
	public boolean matches(CraftingInput input, Level level) {
		int barrelRow = -1;
		int barrelCol = -1;
		int minRowWithBlock = Integer.MAX_VALUE;
		int minColWithBlock = Integer.MAX_VALUE;
		int maxRowWithBlock = Integer.MIN_VALUE;
		int maxColWithBlock = Integer.MIN_VALUE;

		Map<Integer, Integer> rowCounts = new HashMap<>();

		for (int row = 0; row < input.height(); row++) {
			for (int col = 0; col < input.width(); col++) {
				ItemStack item = input.getItem(col + row * input.width());
				if (item.isEmpty()) {
					continue;
				}

				if (item.getItem() instanceof BlockItem blockItem && blockItem.getBlock() instanceof BarrelBlock) {
					if (barrelRow < 0) {
						barrelRow = row;
						barrelCol = col;
					} else {
						return false;
					}
				} else if (item.getItem() instanceof BlockItem blockItem
						&& Block.isShapeFullBlock(blockItem.getBlock().defaultBlockState().getShape(EmptyBlockGetter.INSTANCE, BlockPos.ZERO))) {
					boolean isBottomMiddleAndBottomLeftHasBlock = barrelCol == col && barrelRow < row && rowCounts.getOrDefault(row, 0) > 0;
					if (isBottomMiddleAndBottomLeftHasBlock) {
						return false;
					}

					rowCounts.compute(row, (k, v) -> v == null ? 1 : v + 1);
					if (row < minRowWithBlock) {
						minRowWithBlock = row;
					}
					if (col < minColWithBlock) {
						minColWithBlock = col;
					}
					if (row > maxRowWithBlock) {
						maxRowWithBlock = row;
					}
					if (col > maxColWithBlock) {
						maxColWithBlock = col;
					}
				} else {
					return false;
				}
			}
		}

		if (barrelRow < 0 || rowCounts.isEmpty() || minRowWithBlock < barrelRow - 1 || maxRowWithBlock > barrelRow + 1 || minColWithBlock < barrelCol - 1
				|| maxColWithBlock > barrelCol + 1) {
			return false;
		}

		return rowCounts.getOrDefault(barrelRow - 1, 0) <= 3 && rowCounts.getOrDefault(barrelRow, 0) <= 2 && rowCounts.getOrDefault(barrelRow + 1, 0) <= 2;
	}

@Override
