		if (!storageStack.has(ModDataComponents.WOOD_TYPE)) {
			getWoodType(storageStack).ifPresent(woodType -> storageStack.set(ModDataComponents.WOOD_TYPE, woodType));
		}
		if (!storageStack.has(ModDataComponents.LOCKED)) {
