			Iterator<Map.Entry<ResourceKey<Item>, Item>> delegate = entries.iterator();
			return new Iterator<>() {
				@Override
				public boolean hasNext() {
					return delegate.hasNext();
				}

				@Override
				public Map.Entry<ResourceKey<Item>, Item> next() {
					visits++;
					return delegate.next();
				}
			};
		}

@Override
				public boolean hasNext() {
					return delegate.hasNext();
				}

@Override
				public Map.Entry<ResourceKey<Item>, Item> next() {
					visits++;
