        if (currentRecipe == null || !currentRecipe.matches(matrix, level)) {
            currentRecipe = level.getRecipeManager().getRecipeFor(RecipeType.CRAFTING, matrix, level)
                .map(RecipeHolder::value)
                .orElse(null);
        }

        if (currentRecipe == null) {
            result.setItem(0, ItemStack.EMPTY);
        } else {
            result.setItem(0, currentRecipe.assemble(matrix, level.registryAccess()));
        }

        craftingListeners.forEach(ICraftingGridListener::onCraftingMatrixChanged);

        if (!readingInventory) {
            markDirty();
        }
    }

