            ListTag disksTag = tag.getList(NBT_DISKS, Tag.TAG_COMPOUND);

            for (int i = 0; i < disksTag.size(); ++i) {
                CompoundTag diskTag = disksTag.getCompound(i);

                UUID id = diskTag.getUUID(NBT_DISK_ID);
                CompoundTag data = diskTag.getCompound(NBT_DISK_DATA);
                String type = diskTag.getString(NBT_DISK_TYPE);

                IStorageDiskFactory factory = API.instance().getStorageDiskRegistry().get(new ResourceLocation(type));
                if (factory != null) {
                    disks.put(id, factory.createFromNbt(level, data));
                }
            }
        }
    }

@Override
    public IStorageDisk<FluidStack> createFromNbt(ServerLevel level, CompoundTag tag) {
        FluidStorageDisk disk = new FluidStorageDisk(
            level,
            tag.getInt(FluidStorageDisk.NBT_CAPACITY),
            tag.contains(FluidStorageDisk.NBT_OWNER) ? tag.getUUID(FluidStorageDisk.NBT_OWNER) : null
        );

        ListTag list = tag.getList(FluidStorageDisk.NBT_FLUIDS, Tag.TAG_COMPOUND);

        for (int i = 0; i < list.size(); ++i) {
            FluidStack stack = FluidStack.loadFluidStackFromNBT(list.getCompound(i));

            if (!stack.isEmpty()) {
                disk.getRawStacks().put(stack.getRawFluid(), stack);
            }
        }

        return disk;
    }

@Override
    public IStorageDisk<ItemStack> createFromNbt(ServerLevel level, CompoundTag tag) {
        ItemStorageDisk disk = new ItemStorageDisk(
            level,
            tag.getInt(ItemStorageDisk.NBT_CAPACITY),
            tag.contains(ItemStorageDisk.NBT_OWNER) ? tag.getUUID(ItemStorageDisk.NBT_OWNER) : null
        );

        ListTag list = tag.getList(ItemStorageDisk.NBT_ITEMS, Tag.TAG_COMPOUND);

        for (int i = 0; i < list.size(); ++i) {
            ItemStack stack = StackUtils.deserializeStackFromNbt(list.getCompound(i));

            if (!stack.isEmpty()) {
                disk.getRawStacks().put(stack.getItem(), stack);
            }
        }

        disk.updateItemCount();

        return disk;
    }

