public static void findAndOpen(Item... items) {
        Set<Item> validItems = new HashSet<>(Arrays.asList(items));
        Container inv = Minecraft.getInstance().player.getInventory();
        int slotFound = -1;

        for (int i = 0; i < inv.getContainerSize(); ++i) {
            ItemStack slot = inv.getItem(i);

            if (validItems.contains(slot.getItem())) {
                if (slotFound != -1) {
                    sendError(Component.translatable("misc.refinedstorage.network_item.shortcut_duplicate", Component.translatable(items[0].getDescriptionId())));
                    return;
                }

                slotFound = i;
            }
        }

        if (CuriosIntegration.isLoaded() && slotFound == -1) {
            Optional<ImmutableTriple<String, Integer, ItemStack>> curio = CuriosApi.getCuriosHelper().findEquippedCurio(stack -> validItems.contains(stack.getItem()), Minecraft.getInstance().player);

            if (curio.isPresent()) {
                RS.NETWORK_HANDLER.sendToServer(new OpenNetworkItemMessage(new PlayerSlot(curio.get().getMiddle(), curio.get().getLeft())));
                return;
            }
        }

        if (slotFound == -1) {
            sendError(Component.translatable("misc.refinedstorage.network_item.shortcut_not_found", Component.translatable(items[0].getDescriptionId())));
        } else {
            RS.NETWORK_HANDLER.sendToServer(new OpenNetworkItemMessage(new PlayerSlot(slotFound)));
        }
    }

@Override
    public void onPostInit(int x, int y) {
        lines.clear();

        if (item != null) {
            lines.add(new ItemLine(item));

            Collection<TagKey<Item>> tagsOfItem = BuiltInRegistries.ITEM.getResourceKey(item.getItem())
                .flatMap(k -> BuiltInRegistries.ITEM.getHolder(k)
                    .map(holder -> holder.tags().collect(Collectors.toSet())))
                .orElse(Collections.emptySet());

            for (TagKey<Item> owningTag : tagsOfItem) {
                lines.add(new TagLine(owningTag.location(), GridBlockEntity.ALLOWED_ITEM_TAGS.getValue().get(slot).contains(owningTag.location())));

                int itemCount = 0;

                ItemListLine line = new ItemListLine();

                for (Holder<Item> itemInTag : BuiltInRegistries.ITEM.getTagOrEmpty(owningTag)) {
                    if (itemCount > 0 && itemCount % 8 == 0) {
                        lines.add(line);
                        line = new ItemListLine();
                    }

                    itemCount++;

                    line.addItem(new ItemStack(itemInTag));
                }

                lines.add(line);
            }
        } else if (fluid != null) {
            lines.add(new FluidLine(fluid));

            Collection<TagKey<Fluid>> tagsOfFluid = BuiltInRegistries.FLUID.getResourceKey(fluid.getFluid())
                .flatMap(k -> BuiltInRegistries.FLUID.getHolder(k)
                    .map(holder -> holder.tags().collect(Collectors.toSet())))
                .orElse(Collections.emptySet());

            for (TagKey<Fluid> owningTag : tagsOfFluid) {
                lines.add(new TagLine(owningTag.location(), GridBlockEntity.ALLOWED_FLUID_TAGS.getValue().get(slot).contains(owningTag.location())));

                int fluidCount = 0;

                FluidListLine line = new FluidListLine();

                for (Holder<Fluid> fluidInTag : BuiltInRegistries.FLUID.getTagOrEmpty(owningTag)) {
                    if (fluidCount > 0 && fluidCount % 8 == 0) {
                        lines.add(line);
                        line = new FluidListLine();
                    }

                    fluidCount++;

                    line.addFluid(new FluidStack(fluidInTag, FluidType.BUCKET_VOLUME));
                }

                lines.add(line);
            }
        }

        // Do an initial layout
        int xx = 8;
        int yy = 20;

        for (int i = 0; i < lines.size(); ++i) {
            boolean visible = i >= scrollbar.getOffset() && i < scrollbar.getOffset() + VISIBLE_ROWS;

            if (visible) {
                lines.get(i).layoutDependantControls(true, leftPos + xx + 3, topPos + yy + 3);

                yy += 18;
            }
        }

        Button apply = addButton(x + 7, y + 114, 50, 20, Component.translatable("gui.refinedstorage.alternatives.apply"), lines.size() > 1, true, btn -> apply());
        addButton(x + apply.getWidth() + 7 + 4, y + 114, 50, 20, Component.translatable("gui.cancel"), true, true, btn -> close());
    }

